INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-001-0', 'p0001', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '臣賢案：呼沱河舊在饒陽南，至魏太祖曹操因饒河故瀆決，令北注新溝水，所以今在饒陽縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-008-full-1', 'p0001', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-008-2', 'p0001', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-3', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '東郡太守曹操大破黃巾於壽張，降之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-4', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '辛亥，鎮東將軍曹操自領司隷校尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-5', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操殺侍中臺崇、尚書馮碩等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-6', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十一月丙戌，曹操自為司空，行車騎將軍事，百官緫己以聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-7', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月癸酉，曹操擊呂布於徐州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-8', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五年春正月，車騎將軍董承、偏將軍王服、越騎校尉种輯受密詔誅曹操，事洩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-9', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '壬午，曹操殺董承等，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-10', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操與袁紹戰於官度，裴松之北征記曰：「中牟臺下臨汴水，是為官度，袁紹、曹操壘尚存焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-11', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九年秋八月戊寅，曹操大破袁尚，平兾州，自領兾州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-12', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十年春正月，曹操破袁譚於青州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-13', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，曹操破高幹於并州，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-14', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二年秋八月，曹操大破烏桓於柳城，斬其蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-15', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操南征劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-16', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」壬子，曹操殺太中大夫孔融，夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-17', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操以舟師伐孫權，權將周瑜敗之於烏林、赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-18', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十六年秋九月庚戌，曹操與韓遂、馬超戰於渭南，遂等大敗，關西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-19', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '夏五月丙申，曹操自立為魏公，加九錫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-20', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月，曹操遣將夏侯淵討宋建于枹罕，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-21', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」十一月丁卯，曹操殺皇后伏氏，滅其族及二皇子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-22', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操破漢中，張魯降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-23', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二十一年夏四月甲午，曹操自進號魏王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-24', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，曹操殺琅邪王熙，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-25', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二十三年春正月甲子，少府耿紀、丞相司直韋晃起兵誅曹操，不克，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-009-26', 'p0001', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二十五年春正月庚子，魏王曹操薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-full-27', 'p0001', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '完以政在曹操，自嫌尊戚，乃上印綬，拜中散大夫，尋遷屯騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-full-28', 'p0001', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '議郎趙彥甞為帝陳言時策，曹操惡而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-full-29', 'p0001', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '后自是懷懼，乃與父完書，言曹操殘逼之狀，令密圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-30', 'p0001', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '完以政在曹操，自嫌尊戚，乃上印綬，拜中散大夫，尋遷屯騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-31', 'p0001', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '議郎趙彥甞爲帝陳言時策，曹操惡而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-010b-32', 'p0001', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '后自是懷懼，乃與父完書，言曹操殘逼之狀，令密圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-019-33', 'p0001', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '後曹操誅耿氏，唯援孫弘存焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-019-34', 'p0001', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '曾孫紀，少有美名，辟公府，曹操甚敬異之，稍遷少府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-026-35', 'p0001', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '曹操殺后，誅伏氏，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-027-36', 'p0001', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '建安十三年，以辟司空曹操子丕為掾，操怒，奏溫辟臣子弟，選舉不實，免官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-035-37', 'p0001', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '時袁紹與曹操相拒於官度，官度，津名也，在今鄭州中牟縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-042-38', 'p0001', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '初，邈至長安，盛稱東郡太守曹操忠誠於帝，操以此德於邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-048-39', 'p0001', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '應順，將作大匠；子疊，江夏太守；疊生郴，武陵太守；郴生奉，從事中郎；奉生劭，車騎將軍掾；劭弟珣，司空掾；珣子㻛，曹操辟為丞相掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-048-40', 'p0001', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '後拜太常，使持節拜曹操為丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-051-41', 'p0001', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '初，曹操微時，人莫知者，甞往候玄，玄見而異焉，謂曰：「今天下將亂，安生民者其在君乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-054-42', 'p0001', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '時天子新遷，大會公卿，兖州刺史曹操上殿，見彪色不恱，恐於此圖之，未得讌設，託疾如厠，因出還營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-054-43', 'p0001', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '後子脩為曹操所殺，操見彪問曰：「公何瘦之甚？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-054-44', 'p0001', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '脩字德祖，好學，有俊才，為丞相曹操主簿，典略曰：「脩，建安中舉孝廉，除郎中，丞相請署倉曹屬主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-057-45', 'p0001', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '吏人詣闕陳訴，耽與議郎曹操上言：「公卿所舉，率黨其私，所謂放鴟梟而囚鸞鳳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-058-46', 'p0001', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時曹操圍張超於雍丘，甚危急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-062-47', 'p0001', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '初辟鎮東將軍曹操府，遷黃門侍郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-064-48', 'p0001', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '建安中，曹操北討柳城，過涿郡，魏志曰，建安十二年，操北征烏桓，涉鮮卑，討柳城，登白狼山也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-064-49', 'p0001', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '是時袁紹、曹操與公孫瓚爭兾州，紹及操聞歧至，皆自將兵數百里奉迎，歧深陳天子恩德，宜罷兵安人之道，又移書公孫瓚，為言利害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-064-50', 'p0001', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '曹操時為司空，舉以自代。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-066-51', 'p0001', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '及曹操平荊州，乃辟之，執戩手曰：「恨相見晚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-067-52', 'p0001', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '初，曹操微時，瓚異其才，將沒，謂子宣等曰：「時將亂矣，天下英雄無過曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-067-53', 'p0001', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '初，顒見曹操，歎曰：「漢家將亡，安天下者必此人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-068-54', 'p0001', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '讓以輕侮曹操，操殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-068-55', 'p0001', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '曹操微時，常卑辭厚禮，求為己目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-069-56', 'p0001', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '會表卒，曹操定荊州，輔與宗人徙居於鄴，辟丞相府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-069-57', 'p0001', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '是時置西園八校尉，以小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎都尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍校尉，淳于瓊為佐軍校尉，又有左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-58', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，曹操攻屠鄴城，袁氏婦子多見侵略，而操子丕私納袁熙妻甄氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-59', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '曹操旣積嫌忌，而郗慮復搆成其罪，遂令丞相軍謀祭酒路粹典略曰：「粹字文蔚，陳留人，少學於蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-60', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '或言於曹操，遂盡殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-61', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '魏略曰：「曹操為司空，威德日盛，融故以舊意書疏倨傲，習常責融令改節，融不從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-62', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '人存謂曹操身在不得篡位也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-63', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '時曹操在東郡，彧聞操有雄略，而度紹終不能定大業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-070-64', 'p0001', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '將軍本以兖州首事，故能平定山東，曹操初從東郡守鮑信等迎領兖州牧，遂進兵破黃巾等，故能平定山東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-071-65', 'p0001', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '會帝遣騎都尉曹操將兵適至，嵩、操與朱儁合兵更戰，大破之，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-072-66', 'p0001', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '干亂政事，董承患之，潛召兖州牧曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-072-67', 'p0001', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」曹操以洛陽殘荒，遂移帝幸許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-072-68', 'p0001', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊奉、韓暹欲要遮車駕，不及，曹操擊之，獻帝春秋曰：「車駕出洛陽，自轘轅而東，楊奉、韓暹引軍追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-072-69', 'p0001', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '十六年，超與韓遂舉關中背曹操，操擊破之，遂、超敗走，騰坐夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-072-70', 'p0001', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '曹操因遣夏侯淵擊建，斬之，涼州悉平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-71', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '鮮于輔將其衆歸曹操，操以輔為度遼將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-72', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '閻柔將部曲從曹操擊烏桓，拜護烏桓校尉，封關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-73', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '曹操將定兾州，乃率衆詣鄴降，拜平北將軍，封安國亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-74', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，曹操父嵩避難琅邪，時謙別將守陰平，縣名，屬東海國，故城在今沂州承縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-75', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初平四年，曹操擊謙，破彭城傅陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-76', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '興平元年，曹操復擊謙，略定琅邪、東海諸縣，謙懼不免，欲走歸丹陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-073-77', 'p0001', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」及曹操擊謙，徐方不安，融乃將男女萬口、馬三千匹走廣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-78', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-79', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '建安元年，曹操迎天子都許，乃下詔書於紹，責以地廣兵多而專自樹黨，不聞勤王之師而但擅相討伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-80', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '臣時輒承制，竊比竇融，以議郎曹操權領兖州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-81', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」時曹操自為大將軍，紹恥為之下，大尉位在大將軍上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-82', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '若不得通，乃表曹操隔我王路，然後進屯黎陽，漸營河南，益作舟舩，繕修器械，分遣精騎，抄其邊鄙，令彼不得安，我取其逸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-83', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '今以明公之神武，連河朔之強衆，以伐曹操，其埶譬若覆手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-84', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」 曹操奉迎天子，建宮許都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-85', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」曹操法令旣行，士卒精練，非公孫瓚坐受圍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-86', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」圖等曰：「武王伐紂，不為不義；況兵加曹操，而云無名！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-87', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '五年，左將軍劉備殺徐州刺史車胄，據沛以背曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-88', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐說紹曰：「與公爭天下者，曹操也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-89', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹操畏紹過河，乃急擊備，遂破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-90', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐以旣失前幾，不宜便行，諫紹曰：「曹操旣破劉備，則許下非復空虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-91', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '司空曹操祖父騰，故中常侍，與左悺、徐璜並作妖孽，饕餮放橫，傷化虐人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-92', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '乃先遣顏良攻曹操別將劉延於白馬，白馬，縣，屬東郡，今滑州縣也，故城在今縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-93', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」其弟宗曰：「曹操士馬不敵，君何懼焉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-94', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹操遂救劉延，擊顏良斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-95', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹使劉備、文醜挑戰，曹操又擊破之，斬文醜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-96', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」獻帝春秋曰：「紹令軍中各持三尺繩，曹操誠禽，但當縛之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-97', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '許攸進曰：「曹操兵少而悉師拒我，許下餘守埶必空弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-98', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會攸家犯法，審配收繫之，攸不得志，遂奔曹操，而說使襲取淳于瓊等，瓊等時宿在烏巢，烏巢，地名，在滑州酸棗城東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-99', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '所歷道問者，語之曰：『袁公恐曹操鈔掠後軍，還兵以益備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-100', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '餘衆偽降，曹操盡阬之，前後所殺八萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-074-101', 'p0001', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '官度之敗，審配二子為曹操所禽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-102', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十三年，曹操自將征荊州，璋乃遣使致敬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-103', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十六年，璋聞曹操當遣兵向漢中討張魯，內懷恐懼，松復說璋迎劉備以拒操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-104', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '明年，曹操破張魯，定漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-105', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魯自在漢川垂三十年，聞曹操征之，至陽平，周地圖記曰：「襃谷西北有古陽平關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-106', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '公孫瓚使劉備與術合謀共逼紹，紹與曹操會擊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-107', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '黑山餘賊及匈奴於扶羅等佐術，與曹操戰於匡亭，大敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-108', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操毒被於東徐，劉表僭亂於南荊，公孫叛逆於朔北，正禮阻兵，劉繇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-109', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術又率兵擊陳國，誘殺其王寵及相駱俊，曹操乃自征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-110', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操雖欲扶衰獎微，安能續絕運，起已滅乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-111', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術因欲北至青州從袁譚，曹操使劉備徼之，不得過，復走還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-112', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '董卓之亂，與曹操共舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-113', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '紹旣怨邈，且聞與布厚，乃令曹操殺邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-114', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，曹操東擊陶謙，令其將武陽人陳宮屯東郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-115', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操聞而引軍擊布，累戰，相持百餘日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-116', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '昔金元休南至封丘，為曹操所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-117', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」布亦素怨術，而女已在塗，乃追還絕婚，執胤送許，曹操殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-118', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '陳珪欲使子登詣曹操，布固不許，會使至，拜布為左將軍，布大喜，即聽登行，并令奉章謝恩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-119', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '登見曹操，因陳布勇而無謀，輕於去就，宜早圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-120', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '登還，布怒，拔戟斫机曰：「卿父勸吾協同曹操，絕婚公路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-075-121', 'p0001', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操壍圍之，壅沂、泗以灌其城，三月，上下離心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-080b-122', 'p0001', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '恃才氣，不屈曹操，多輕侮之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-080b-123', 'p0001', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '融旣愛衡才，數稱述於曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-081-124', 'p0001', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '曹操聞烈高名，遣徵不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-084-125', 'p0001', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '曹操素與邕善，痛其無嗣，乃遣使者以金璧贖之，而重嫁於祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-084-126', 'p0001', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '祀為屯田都尉，犯法當死，文姬詣曹操請之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-089-127', 'p0001', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '二十一年，單于來朝，曹操因留於鄴，留呼厨泉於鄴，而遣去卑歸平陽，監其五部國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-090-128', 'p0001', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '會曹操平河北，閻柔率鮮卑、烏桓歸附，操即以柔為校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-090-129', 'p0001', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安十二年，曹操自征烏桓，大破蹋頓於柳城，斬之，首虜二十餘萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-105-130', 'p0001', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '袁山松書曰：「曹操專政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-105-131', 'p0001', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '』時天下尚亂，豪桀並爭：曹操事二袁於河北；孫吳創基於江外；劉表阻亂衆於襄陽，南招零、桂，北割漢川，又以黃祖為爪牙，而祖與孫氏為深讎，兵革歲交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-105-132', 'p0001', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十年，曹操破袁譚於南皮；十一年，走袁尚於遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-105-133', 'p0001', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '曹操略荊州，逐劉備於當陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-105-134', 'p0001', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十四年，吳破曹操於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a03-118-135', 'p0001', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '犬牙相經，共為嚴國，雖王莽善盜，將何因而敢竊，曹操雄勇，亦安能以得士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-001-136', 'p0001', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布騎得太祖而不知是，問曰：「曹操何在？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-001-137', 'p0001', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布疑有伏，乃相謂曰：「曹操多譎，勿入伏中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-001-138', 'p0001', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」公大喜，乃選精銳步騎，皆用袁軍旗幟，銜枚縛馬口，夜從間道出，人抱束薪，所歷道有問者，語之曰：「袁公恐曹操鈔略後軍，遣兵以益備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-001-139', 'p0001', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '便欲送璽，會曹操斷道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-006-140', 'p0001', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '天子以紹為太尉，轉為大將軍，封鄴侯，獻帝春秋曰：紹恥班在太祖下，怒曰；「曹操當死數矣，我輒救存之，今乃背恩，挾天子以令我乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-006-141', 'p0001', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司空曹操，祖父騰，故中常侍，與左悺、徐璜並作妖孽，饕餮放橫，傷化虐民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-006-142', 'p0001', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '仁君度數弘廣，綽然有餘，當以大包小，以優容劣，先除曹操以卒先公之恨，事定之後，乃議曲直之計，不亦善乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-006-143', 'p0001', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '曹操欲扶衰拯弱，安能續絕命救已滅乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-006-144', 'p0001', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋曰：王威說劉琮曰：「曹操得將軍旣降，劉備已走，必懈弛無備，輕行單進；若給威奇兵數千，徼之於險，操可獲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-007-145', 'p0001', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '昔將金元休向兖州，甫詣封部，為曹操逆所拒破，流離迸走，幾至滅亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-007-146', 'p0001', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布大喜，復遣使上書於天子曰：「臣本當迎大駕，知曹操忠孝，奉迎都許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-007-147', 'p0001', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」陳宮曰：「逆賊曹操，何等明公！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-008-148', 'p0001', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝紀曰：以虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融、馮芳為助軍校尉，夏牟、淳于瓊為左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-013-149', 'p0001', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '傕、汜等以為「關東欲自立天子，今曹操雖有使命，非其至實」，議留太祖使，拒絕其意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-026-150', 'p0001', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」忠曰：「我遼東在滄海之東，擁兵百萬，又有扶餘、濊貊之用；當今之勢，彊者為右，曹操獨何得為是也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-031-151', 'p0001', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '習鑿齒曰：昔齊桓一矜其功而叛者九國，曹操暫自驕伐而天下三分，皆勤之於數十年之內而棄之於俯仰之頃，豈不惜乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-031-152', 'p0001', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '君子是以知曹操之不能遂兼天下者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-032-153', 'p0001', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：孫權欲與備共取蜀，遣使報備曰：「米賊張魯居王巴、漢，為曹操耳目，規圖益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-032-154', 'p0001', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹操雖有無君之心，而有奉主之名，議者見操失利於赤壁，謂其力屈，無復遠志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-032-155', 'p0001', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '董卓首難，蕩覆京畿，曹操階禍，竊執天衡；皇后太子鴆殺見害，剥亂天下，殘毀民物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-032-156', 'p0001', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '惟獨曹操乆未梟除，侵擅國權，恣心極亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-032-157', 'p0001', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '今曹操阻兵安忍，戮殺主后，滔天泯夏，罔顧天顯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-033-158', 'p0001', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '曹操階禍，竊執天衡，殘剥海內，懷無君之心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-159', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操比於袁紹，則名微而衆寡，然操遂能克紹，以弱為彊者，非惟天時，抑亦人謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-160', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」時權擁軍在柴桑，觀望成敗，亮說權曰：「海內大亂，將軍起兵據有江東，劉豫州亦收衆漢南，與曹操並爭天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-161', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '非劉豫州莫可以當曹操者，然豫州新敗之後，安能抗此難乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-162', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操之衆遠來疲弊，聞追豫州，輕騎一日一夜行三百餘里，此所謂『彊弩之末，勢不能穿魯縞』者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-163', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操智計殊絕於人，其用兵也，髣髴孫、吳，然困於南陽，險於烏巢，危於祁連，偪於黎陽，幾敗伯山，殆死潼關，然後偽定一時耳，況臣才弱，而欲以不危而定之，此臣之未解三也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-164', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操五攻昌霸不下，四越巢湖不成，任用李服而李服圖之，委夏侯而夏侯敗亡，先帝每稱操為能，猶有此失，況臣駑下，何能必勝？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-035-165', 'p0001', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '昔先帝敗軍於楚，當此時，曹操拊手，謂天下以定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-036-166', 'p0001', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹操父子，世載其罪，朕用慘怛，疢如疾首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-036-167', 'p0001', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '雲諫曰：「國賊是曹操，非孫權也，且先滅魏，則吳自服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-037-168', 'p0001', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」備曰：「今指與吾為水火者，曹操也，操以急，吾以寬；操以暴，吾以仁；操以譎，吾以忠；每與操反，事乃可成耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-037-169', 'p0001', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-040-170', 'p0001', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕於獄中與諸葛亮書曰：「僕昔有事於諸侯，以為曹操暴虐，孫權無道，振威闇弱，其惟主公有霸王之器，可與興業致治，故乃翻然有輕舉之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-040-171', 'p0001', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '至於內外之言，欲使孟起立功北州，勠力主公，共討曹操耳，寧敢有他志邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-040-172', 'p0001', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」延對曰：「若曹操舉天下而來，請為大王拒之；偏將十萬之衆至，請為大王吞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-041-173', 'p0001', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '後羣臣議欲推漢中王稱尊號，詩上疏曰：「殿下以曹操父子偪主篡位，故乃羇旅萬里，糾合士衆，將以討賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-046-174', 'p0001', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-047-175', 'p0001', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」泉曰：「曹操父子陵轢漢室，終奪其位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-047-176', 'p0001', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '其司州之土，以函谷關為界，造為盟曰：「天降喪亂，皇綱失叙，逆臣承釁，劫奪國柄，始於董卓，終於曹操，窮凶極惡，以覆四海，至令九州幅裂，普天無統，民神痛怨，靡所戾止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-048-177', 'p0001', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '曹操雖功蓋中夏，威震四海，崇詐杖術，征伐無已，民畏其威，而不懷其德也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-178', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉璋為益州牧，外有張魯寇侵，瑜乃詣京見權曰：「今曹操新折衂，方憂在腹心，未能與將軍道兵相事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-179', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣竊以瑜昔見寵任，入作心膂，出為爪牙，銜命出征，身當矢石，盡節用命，視死如歸，故能摧曹操於烏林，走曹仁於郢都，揚國威德，華夏是震，蠢爾蠻荊，莫不賔服，雖周之方叔，漢之信、布，誠無以尚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-180', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權曰：「昔走曹操，拓有荊州，皆是公瑾，常不忘之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-181', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今之曹操，猶昔項羽，將軍何由得為桓文乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-182', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '肅竊料之，漢室不可復興，曹操不可卒除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-183', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '肅請得奉命弔表二子，并慰勞其軍中用事者，及說備使撫表衆，同心一意，共治曹操，備必喜而從命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-054-184', 'p0001', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今旣與曹操為敵，劉備近在公安，邊境密邇，百姓未附，宜得良將以鎮撫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-055-185', 'p0001', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧陳計曰：「今漢祚日微，曹操彌憍，終為篡盜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-058-186', 'p0001', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜案劒曰：「劉備天下知名，曹操所憚，今在境界，此彊對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-064-187', 'p0001', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '今敵政在私門，外內猜隔，兵挫於外，而民怨於內，自曹操以來，彼之亡形未有如今者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a04-064-188', 'p0001', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '近者劉景升在荊州，有衆十萬，財穀如山，不及曹操尚微，與之力競，坐觀其彊大，吞滅諸袁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0001-a05-014-189', 'p0001', 'jinshu', 'a05-014', '《晉書·卷十四》', '獻帝建安元年拜曹操為鎮東將軍，封費亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-032-0', 'p0002', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '太傅許靖、安漢將軍糜笁、軍師將軍諸葛亮、太常賴恭、光祿勳黃柱、少府王謀等上言：「曹丕篡弒，湮滅漢室，竊據神器，劫迫忠良，酷烈無道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-035-1', 'p0002', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '章武三年春，先主於永安病篤，召亮於成都，屬以後事，謂亮曰：「君才十倍曹丕，必能安國，終定大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-035-2', 'p0002', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '然後吳更違盟，關羽毀敗，秭歸蹉跌，曹丕稱帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-042-3', 'p0002', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '」微自乞老病求歸，亮又與書荅曰：「曹丕篡弒，自立為帝，是猶土龍芻狗之有名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-047-4', 'p0002', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權令趙達筭之，曰：「曹丕走矣，雖然，吳衰庚子歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-047-5', 'p0002', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權謂芝曰：「山民作亂，江邊守兵多徹，慮曹丕乘空弄態，而反求和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-047-6', 'p0002', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '孽臣曹丕遂奪神器，丕子叡繼世作慝，淫名亂制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-052-7', 'p0002', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '又別咨瑾曰：「近得伯言表，以為曹丕已死，毒亂之民，當望旌瓦解，而更靜然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-053-8', 'p0002', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」初，魏文帝即位，權嘗從容問羣臣曰：「曹丕以盛年即位，恐孤不能及之，諸卿以為何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-056-9', 'p0002', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '雖曹丕自來，尚不足憂，況仁等邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-057-10', 'p0002', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '後聞曹丕自出淮、泗，故豫勑溫有急便出，而溫悉內諸將，布於深山，被命不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0002-a04-058-11', 'p0002', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權以問遜，遜與朱然、駱統以為曹丕大合士衆，外託助國討備，內實有姦心，謹決計輒還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0003-a03-018-0', 'p0003', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '」曹植結交篇曰：「利劔鳴手中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0003-a03-054-1', 'p0003', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '續漢書曰：「人有白脩與臨淄侯曹植飲醉共載，從司馬門出，謗訕鄢陵侯章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0003-a03-111-2', 'p0003', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」曹植禹廟讚曰：「有禹祠，植移于其城，城本名杞城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0003-a03-115-3', 'p0003', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '董卓為東中郎將，盧植為北中郎將，獻帝以曹植為南中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-0', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，進軍臨河，使史渙、曹仁渡河擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-1', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹使劉備助辟，公使曹仁擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-2', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-3', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，王引軍還，留夏侯惇、曹仁、張遼等屯居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-4', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，曹仁討關羽，屯樊城，是月使仁圍宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-001-5', 'p0005', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '子卿因夜踰城亡出，遂與太守收餘民圍音，會曹仁軍至，共滅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-002-6', 'p0005', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '夏四月，以車騎將軍曹仁為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-002-7', 'p0005', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '五月，鄭甘復叛，遣曹仁討斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-002-8', 'p0005', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」己卯，以大將軍曹仁為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-002-9', 'p0005', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」丁未，大司馬曹仁薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-003-10', 'p0005', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏五月壬申，詔祀故大將軍夏侯惇、大司馬曹仁、車騎將軍程昱於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-004-11', 'p0005', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '征南將軍曹仁討平音，表余行狀，并脩祭醊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-009-12', 'p0005', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹仁字子孝，太祖從弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-010-13', 'p0005', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '故曹仁守江陵，敗不旋踵，何撫安之得行，稽服之可期？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-014-14', 'p0005', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及關羽圍曹仁於樊，孫權遣使辭以「遣兵西上，欲掩取羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-014-15', 'p0005', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '黃初三年，與大司馬曹仁征吳，濟別襲羨溪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-017-16', 'p0005', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '關羽圍曹仁於樊，會權稱藩，召遼及諸軍悉還救仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-017-17', 'p0005', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-017-18', 'p0005', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安二十四年，太祖在長安，使曹仁討關羽於樊，又遣禁助仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-017-19', 'p0005', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-017-20', 'p0005', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復遣晃助曹仁討關羽，屯宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-018-21', 'p0005', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-018-22', 'p0005', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '曹仁自荊州來朝謁，太祖未出，入與褚相見於殿外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-018-23', 'p0005', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '侯音、衞開等以宛叛，悳將所領與曹仁共攻拔宛，斬音、開，遂南屯樊，討關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-019-24', 'p0005', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '二十四年，曹仁為關羽所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-022-25', 'p0005', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹仁為關羽所圍，太祖遣徐晃救之，不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-023-26', 'p0005', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '關羽圍征南將軍曹仁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-026-27', 'p0005', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '關羽圍襄陽，寵助征南將軍曹仁屯樊城拒之，而左將軍于禁等軍以霖雨水長為羽所沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-032-28', 'p0005', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公遣曹仁將兵擊先主，先主還紹軍，陰欲離紹，乃說紹南連荊州牧劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-032-29', 'p0005', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '時關羽攻曹公將曹仁，禽于禁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-035-30', 'p0005', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-036-31', 'p0005', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '是歲，羽率衆攻曹仁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-036-32', 'p0005', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '而曹公遣徐晃救曹仁，蜀記曰：羽與晃宿相愛，遙共語，但說平生，不及軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-047-33', 'p0005', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備、瑜等復追至南郡，曹公遂北還，留曹仁、徐晃於江陵，使樂進守襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-047-34', 'p0005', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二十四年，關羽圍曹仁於襄陽，曹公遣左將軍于禁救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-047-35', 'p0005', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '曹公且欲使羽與權相持以鬬之，驛傳權書，使曹仁以弩射示羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-047-36', 'p0005', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-047-37', 'p0005', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '三月，曹仁遣將軍常彫等，以兵五千，乘油舩，晨渡濡須中州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-054-38', 'p0005', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '曹公留曹仁等守江陵城，徑自北歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-054-39', 'p0005', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣竊以瑜昔見寵任，入作心膂，出為爪牙，銜命出征，身當矢石，盡節用命，視死如歸，故能摧曹操於烏林，走曹仁於郢都，揚國威德，華夏是震，蠢爾蠻荊，莫不賔服，雖周之方叔，漢之信、布，誠無以尚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-054-40', 'p0005', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是歲，又與周瑜、程普等西破曹公於烏林，圍曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-054-41', 'p0005', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜使甘寧前據夷陵，曹仁分衆攻寧，寧困急，使使請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-054-42', 'p0005', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '於是將士形勢自倍，乃渡江立屯，與相攻擊，曹仁退走，遂據南郡，撫定荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-43', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '樂安平定，代太史慈備海昏，與周瑜為左右督，破曹公於烏林，又進攻南郡，走曹仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-44', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後與周瑜、程普拒曹公於赤壁，攻曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-45', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹仁出濡須，戰有功，又從攻破曹休，進位裨將軍，黃龍二年卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-46', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '攻曹仁於南郡，未拔，寧建計先徑進取夷陵，往即得其城，因入守之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-47', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹仁乃令五六千人圍寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-055-48', 'p0005', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權以統為承烈都尉，與周瑜等拒破曹公於烏林，遂攻曹仁，遷為校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-056-49', 'p0005', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武元年，魏使大司馬曹仁步騎數萬向濡須，仁欲以兵襲取州上，偽先揚聲，欲東攻羨溪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-056-50', 'p0005', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '諸君聞曹仁用兵行師，孰與桓邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a04-057-51', 'p0005', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃武初，曹仁攻濡須，使別將常雕等襲中洲，統與嚴圭共拒破之，封新陽亭侯，後為濡須督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a05-001-52', 'p0005', 'jinshu', 'a05-001', '《晉書·卷一》', '及蜀將關羽圍曹仁於樊，于禁等七軍皆沒，脩、方果降羽，而仁圍甚急焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0005-a05-001-53', 'p0005', 'jinshu', 'a05-001', '《晉書·卷一》', '時曹仁鎮襄陽，請召仁還宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-002-0', 'p0006', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書曰：十一月辛未，鎮西將軍曹真命衆將及州郡兵討破叛胡治元多、蘆水、封賞等，斬首五萬餘級，獲生口十萬，羊一百一十一萬口，牛八萬，河西遂平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-002-1', 'p0006', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '夏五月丙辰，帝疾篤，召中軍大將軍曹真、鎮軍大將軍陳羣、征東大將軍曹休、撫軍大將軍司馬宣王，並受遺詔輔嗣主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-002-2', 'p0006', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏氏春秋曰：明帝將送葬，曹真、陳羣、王朗等以暑熱固諫，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-003-3', 'p0006', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-003-4', 'p0006', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '遣大將軍曹真都督關右，並進兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-003-5', 'p0006', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，諸葛亮圍陳倉，曹真遣將軍費曜等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-003-6', 'p0006', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '癸巳，以大將軍曹真為大司馬，驃騎將軍司馬宣王為大將軍，遼東太守公孫淵為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-003-7', 'p0006', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '詔大司馬曹真、大將軍司馬宣王伐蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-004-8', 'p0006', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-009-9', 'p0006', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏略曰：文帝收洪，時曹真在左右，請之曰：「今誅洪，洪必以真為譖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-009-10', 'p0006', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹真字子丹，太祖族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-009-11', 'p0006', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '範於沛郡，仕次在曹真後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-009-12', 'p0006', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '干寶晉紀曰：蔣濟以曹真之勳力，不宜絕祀，故以熈為後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-009-13', 'p0006', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '黃初三年，車駕幸宛，使尚率諸軍與曹真共圍江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-013-14', 'p0006', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太和中，遣曹真從子午道伐蜀，車駕東幸許昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-013-15', 'p0006', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '四年，大司馬曹真征蜀，肅上疏曰：「前志有之，『千里饋糧，士有饑色，樵蘇後爨，師不宿飽』，此謂平塗之行軍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-013-16', 'p0006', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '聞曹真發已踰月而行裁半谷，治道功夫，戰士悉作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-014-17', 'p0006', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '文皇帝始召曹真還時，親詔臣以重慮，及至晏駕，陛下即阼，猶有曹休外內之望，賴遭日月，御勒不傾，使各守分職，纖介不間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-017-18', 'p0006', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '詔郃與曹真討安定盧水胡及東羌，召郃與真並朝許宮，遣南與夏侯尚擊江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-021-19', 'p0006', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」初，曹真、曹休亦與質等俱在渤海游處，時休、真亦以宗親並受爵封，出為列將，而質故為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-021-20', 'p0006', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時上將軍曹真性肥，中領軍朱鑠性瘦，質召優，使說肥瘦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-022-21', 'p0006', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '帝寢疾，羣與曹真、司馬宣王等並受遺詔輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-022-22', 'p0006', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '明帝即位，進封潁陰侯，增邑五百，并前千三百戶，與征東大將軍曹休、中軍大將軍曹真、撫軍大將軍司馬宣王並開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-022-23', 'p0006', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」太和中，曹真表欲數道伐蜀，從斜谷入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-023-24', 'p0006', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '諸葛亮出秦川，大將軍曹真督諸軍拒亮，徙襲為大將軍軍師，分邑百戶賜兄基爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-025-25', 'p0006', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '上軍大將軍曹真征朱然于江陵，毗行軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-025-26', 'p0006', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '是時大司馬曹真伐蜀，遇雨不進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-033-27', 'p0006', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '八年秋，魏使司馬懿由西城，張郃由子午，曹真由斜谷，斜，余奢反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-035-28', 'p0006', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮初屯陽平，宣帝尚為荊州都督，鎮宛城，至曹真死後，始與亮於關中相抗禦耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-035-29', 'p0006', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年春，揚聲由斜谷道取郿，使趙雲、鄧芝為疑軍，據箕谷，魏大將軍曹真舉衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-035-30', 'p0006', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '冬，亮復出散關，圍陳倉，曹真拒之，亮糧盡而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-035-31', 'p0006', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '於是魏大司馬曹真有疾，司馬宣王自荊州入朝，魏明帝曰：「西方事重，非君莫可付者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-036-32', 'p0006', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '明年，亮出軍，揚聲由斜谷道，曹真遣大衆當之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-040-33', 'p0006', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '以曹真欲三道向漢川，亮命嚴將二萬人赴漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-047-34', 'p0006', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-047-35', 'p0006', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二年春正月，曹真分軍據江陵中州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-052-36', 'p0006', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：曹真、夏侯尚等圍朱然於江陵，又分據中州，瑾以大兵為之救援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-055-37', 'p0006', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹真攻南郡，當保東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a04-056-38', 'p0006', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏遣曹真、夏侯尚、張郃等攻江陵，魏文帝自住宛，為其勢援，連屯圍城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a05-001-39', 'p0006', 'jinshu', 'a05-001', '《晉書·卷一》', '及天子疾篤，帝與曹真、陳羣等見於崇華殿之南堂，並受顧命輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a05-001-40', 'p0006', 'jinshu', 'a05-001', '《晉書·卷一》', '四年，遷大將軍，加大都督、假黃鉞，與曹真伐蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0006-a05-001-41', 'p0006', 'jinshu', 'a05-001', '《晉書·卷一》', '蔣濟曰：「曹真之勳，不可以不祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-003-0', 'p0007', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '以燕王宇為大將軍，甲申免，以武衞將軍曹爽代之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-003-1', 'p0007', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '漢晉春秋曰：帝以燕王宇為大將軍，使與領軍將軍夏侯獻、武衞將軍曹爽、屯騎校尉曹肈、驍騎將軍秦朗等對輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-003-2', 'p0007', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '甲申，帝氣微，宇下殿呼曹肈有所議，未還，而帝少間，惟曹爽獨在。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-3', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '大將軍曹爽、太尉司馬宣王輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-4', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五年春二月，詔大將軍曹爽率衆征蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-5', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '丙午，大將軍曹爽引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-6', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '司馬宣王謂曹爽曰：「若便令還，必復致寇，宜權留之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-7', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '太傅司馬宣王奏免大將軍曹爽、爽弟中領軍羲、武衞將軍訓、散騎常侍彥官，以侯就第。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-004-8', 'p0007', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '明帝旣不能然，情繫私愛，撫養嬰孩，傳以大器，託付不專，必參枝族，終於曹爽誅夷，齊王替位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-9', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '霸，正始中為討蜀護軍右將軍，進封愽昌亭侯，素為曹爽所厚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-10', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時征西將軍夏侯玄，於霸為從子，而玄於曹爽為外弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-11', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '及司馬宣王誅曹爽，遂召玄，玄來東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-12', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '霸聞曹爽被誅而玄又徵，以為禍必轉相及，心旣內恐；又霸先與雍州刺史郭淮不和，而淮代玄為征西，霸尤不安，故遂奔蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-13', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹爽宿與相親，時爽為武衞將軍，數為帝稱其可大用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-14', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '素與曹爽善，每言於爽，多見從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-15', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '勝少游京師，雅有才智，與曹爽善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-16', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝崩，曹爽輔政，勝為洛陽令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-17', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '于時曹爽輔政，以範鄉里老宿，於九卿中特敬之，然不甚親也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-18', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」　漢晉春秋曰：安定皇甫謐以九年冬夢至洛陽，自廟出，見車騎甚衆，以物呈廟云：「誅大將軍曹爽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-19', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '至正始初，曲合於曹爽，亦以才能，故爽用為散騎侍郎，遷侍中尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-20', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '與曹爽共興駱谷之役，時人譏之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-21', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '密謂韜曰：「玄旣為海內重人，加以當大任，年時方壯而永見廢，又親曹爽外弟，於大將軍有嫌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-22', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹爽專政，豐依違二公間，無有適莫，故于時有謗書曰：「曹爽之勢熱如湯，太傅父子冷如漿，李豐兄弟如游光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-23', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '臣松之案：曹爽以正始五年伐蜀，時玄已為關中都督，至十年，爽誅滅後，方還洛耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-24', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '大將軍曹爽附絹二十匹令交市於吳，經不發書，棄官歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-009-25', 'p0007', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '玄以規格局度，世稱其名，然與曹爽中外繾綣；榮位如斯，曾未聞匡弼其非，援致良才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-013-26', 'p0007', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '大將軍曹爽盛夏興軍伐蜀，蜀拒守，軍不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-013-27', 'p0007', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時大將軍曹爽專權，任用何晏、鄧颺等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-28', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曹爽時為選部郎，鄧颺之徒稱之以為伊呂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-29', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '是時，曹爽專政，丁謐、鄧颺等輕改法度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-30', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '以隨太傅司馬宣王屯洛水浮橋，誅曹爽等，進封都鄉侯，邑七百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-31', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '世語曰：初，濟隨司馬宣王屯洛水浮橋，濟書與曹爽，言宣王旨「惟免官而已」，爽遂誅滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-32', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '其年，帝寢疾，欲以燕王宇為大將軍，及領軍將軍夏侯獻、武衞將軍曹爽、屯騎校尉曹肇、驍騎將軍秦朗共輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-33', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」帝曰：「曹爽可代宇不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-34', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '案本傳及諸書並云放、資稱贊曹爽，勸召宣王，魏室之亡，禍基於此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-014-35', 'p0007', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」曹爽誅後，復以資為侍中，領中書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-020-36', 'p0007', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '是時天子幼稚，冏兾以此論感悟曹爽，爽不能納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-021-37', 'p0007', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '曹爽秉政，多違法度，璩為詩以諷焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-021-38', 'p0007', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太尉蔣濟聞而辟之，後為尚書郎、曹爽參軍，以疾歸田里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-021-39', 'p0007', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時曹爽秉政，何晏為吏部尚書，嘏謂爽弟羲曰：「何平叔外靜而內銛巧，好利，不念務本。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-021-40', 'p0007', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '曹爽誅，為河南尹，傅子曰：河南尹內掌帝都，外統京畿，兼古六鄉六遂之士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-022-41', 'p0007', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹爽輔政，使夏侯玄宣指，欲引臻入守尚書令，及為弟求婚，皆不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-022-42', 'p0007', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時曹爽秉權，將樹其黨，徙毓僕射，以侍中何晏代毓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-024-43', 'p0007', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太傅司馬宣王奏免曹爽，皇太后詔召柔假節行大將軍事，據爽營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-024-44', 'p0007', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '明帝臨崩之時，以曹爽為大將軍，宜得良佐，於牀下受遺詔，拜禮大將軍長史，加散騎常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-024-45', 'p0007', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '而曹爽信清河言，下書云：「圖不可用，當參異同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-024-46', 'p0007', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '大將軍曹爽使材官張達斫家屋材，及諸私用之物，觀聞知，皆錄奪以沒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-025-47', 'p0007', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』弟敞為大將軍曹爽參軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-025-48', 'p0007', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '且曹爽與太傅俱受寄託之任，而獨專權勢，行以驕奢，於王室不忠，於人道不直，此舉不過以誅曹爽耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-027-49', 'p0007', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '嘉平初，太傅司馬宣王旣誅曹爽，乃奏愽問大臣得失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-027-50', 'p0007', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '大將軍曹爽請為從事中郎，出為安豐太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-027-51', 'p0007', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '時曹爽專柄，風化陵遲，基著時要論以切世事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-52', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '司馬宣王旣誅曹爽，進淩為太尉，假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-53', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '今曹爽以驕奢失民，何平叔虛而不治，丁、畢、桓、鄧雖並有宿望，皆專競於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-54', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '正始中，為曹爽長史，後出為兖州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-55', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '揚州刺史前將軍文欽，曹爽之邑人也，驍果麄猛，數有戰功，好增虜獲，以徼寵賞，多不見許，怨恨日甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-56', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '曹爽以欽鄉里，厚養待之，不治欽事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-57', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '曹爽誅後，進欽為前將軍以安其心，後代諸葛誕為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-58', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '自曹爽之誅，欽常內懼，與諸葛誕相惡，無所與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-59', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '』是時大將軍曹爽專朝政，日縱酒沈醉，會兄侍中毓宴還，言其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-60', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '時丁謐與晏爭衡，致高邑王黎於曹爽，爽用黎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-028-61', 'p0007', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '正始十年，曹爽廢，以公事免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-029-62', 'p0007', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」毓未解輅言，無幾，曹爽等誅，乃覺寤云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-033-63', 'p0007', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-033-64', 'p0007', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十二年春正月，魏誅大將軍曹爽等，右將軍夏侯霸來降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-043-65', 'p0007', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '七年春，魏大將軍曹爽率步騎十餘萬向漢川，前鋒已在駱谷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-044-66', 'p0007', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏遣大將軍曹爽襲蜀時，議者或謂但可守城，不出拒敵，必自引退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-044-67', 'p0007', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '殷基通語曰：司馬懿誅曹爽，禕設甲乙論平其是非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-044-68', 'p0007', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '甲以為曹爽兄弟凡品庸人，苟以宗子枝屬，得蒙顧命之任，而驕奢僭逸，交非其人，私樹朋黨，謀以亂國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a04-044-69', 'p0007', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及興勢之役，王平捍拒曹爽，皆承此制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-70', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '」命與大將軍曹爽並受遺詔輔少主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-71', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '尚書鄧颺、李勝等欲令曹爽建立功名，勸使伐蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-72', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '六年秋八月，曹爽毀中壘中堅營，以兵屬其弟中領軍羲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-73', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '曹爽曰：「今不能脩守沔南而留百姓，非長策也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-74', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '曹爽用何晏、鄧颺、丁謐之謀，遷太后於永寧宮，專擅朝政，兄弟並典禁兵，多樹親黨，屢改制度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-75', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '九年春三月，黃門張當私出掖庭才人石英等十一人，與曹爽為伎人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-001-76', 'p0007', 'jinshu', 'a05-001', '《晉書·卷一》', '誅曹爽之際，支黨皆夷及三族，男女無少長，姑姊妹女子之適人者皆殺之，既而竟遷魏鼎云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-002-77', 'p0007', 'jinshu', 'a05-002', '《晉書·卷二》', '宣帝之將誅曹爽，深謀祕策，獨與帝潛畫，文帝弗之知也，將發夕乃告之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-002-78', 'p0007', 'jinshu', 'a05-002', '《晉書·卷二》', '大將軍曹爽之伐蜀也，以帝為征蜀將軍，副夏侯玄出駱谷，次于興勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-002-79', 'p0007', 'jinshu', 'a05-002', '《晉書·卷二》', '及誅曹爽，帥衆衞二宮，以功增邑千戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-005-80', 'p0007', 'jinshu', 'a05-005', '《晉書·卷五》', '故能西禽孟達，東舉公孫，內夷曹爽，外襲王淩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-012-81', 'p0007', 'jinshu', 'a05-012', '《晉書·卷十二》', '是時曹爽專政，丁謐、鄧颺等轉改法度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-012-82', 'p0007', 'jinshu', 'a05-012', '《晉書·卷十二》', '宣帝奏永寧太后廢曹爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-013-83', 'p0007', 'jinshu', 'a05-013', '《晉書·卷十三》', '」嘉平元年，天子謁陵，宣帝奏誅曹爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-013-84', 'p0007', 'jinshu', 'a05-013', '《晉書·卷十三》', '」嘉平元年，宣帝誅曹爽兄弟及其黨與，皆夷三族，京師嚴兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-037-85', 'p0007', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '及大將軍曹爽擅權，李勝、何晏、鄧颺等亂政，孚不視庶事，但正身遠害而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-039-86', 'p0007', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '大將軍曹爽辟爲掾，累遷中書門下侍郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-039-87', 'p0007', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時曹爽專權，何晏等欲害太常傅嘏，顗營救得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-039-88', 'p0007', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '仕魏，辟大將軍曹爽掾，遷中書通事郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-040-89', 'p0007', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '時駿居曹爽故府，在武庫南，聞內有變，召眾官議之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-042-90', 'p0007', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '襲父爵京陵侯，辟大將軍曹爽掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0007-a05-042-91', 'p0007', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '楚王瑋將害汝南王亮等也，公孫宏說瑋曰：「昔宣帝廢曹爽，引太尉蔣濟參乘，以增威重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-002-0', 'p0008', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '夏五月丙辰，帝疾篤，召中軍大將軍曹真、鎮軍大將軍陳羣、征東大將軍曹休、撫軍大將軍司馬宣王，並受遺詔輔嗣主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-003-1', 'p0008', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '吳將諸葛瑾、張霸等寇襄陽，撫軍大將軍司馬宣王討破之，斬霸，征東大將軍曹休又破其別將於尋陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-003-2', 'p0008', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-003-3', 'p0008', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」秋九月，曹休率諸軍至皖，與吳將陸議戰於石亭，敗績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-004-4', 'p0008', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-009-5', 'p0008', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹休字文烈，太祖族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-013-6', 'p0008', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其後征東將軍曹休來朝，時帝方與夏有所咨論，而外啟休到，帝引入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-014-7', 'p0008', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '三年，征東大將軍曹休臨江在洞浦口，自表：「願將銳卒虎步江南，因敵取資，事必克捷；若其無臣，不須為念。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-014-8', 'p0008', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大司馬曹休帥軍向皖，濟表以為「深入虜地，與權精兵對，而朱然等在上流，乘休後，臣未見其利也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-014-9', 'p0008', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '文皇帝始召曹真還時，親詔臣以重慮，及至晏駕，陛下即阼，猶有曹休外內之望，賴遭日月，御勒不傾，使各守分職，纖介不間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-015-10', 'p0008', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和二年，帝使逵督前將軍滿寵、東莞太守胡質等四軍，從西陽直向東關，曹休從皖，司馬宣王從江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-015-11', 'p0008', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '今忍其私忿而急彼之憂，冒難犯危而免之於害，使功顯於明君，惠施於百姓，身登於君子之塗，義愧於敵人之心，雖豺虎猶將不覺所復，而況於曹休乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-017-12', 'p0008', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '孫權復叛，帝遣遼乘舟，與曹休至海陵，臨江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-018-13', 'p0008', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與曹休討吳賊，破呂範於洞浦，徵為執金吾，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-018-14', 'p0008', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '文帝即位，以曹休都督青、徐，霸謂休曰：「國家未肯聽霸耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-021-15', 'p0008', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」初，曹真、曹休亦與質等俱在渤海游處，時休、真亦以宗親並受爵封，出為列將，而質故為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-021-16', 'p0008', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '質別傳曰：帝嘗召質及曹休歡會，命郭后出見質等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-022-17', 'p0008', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '明帝即位，進封潁陰侯，增邑五百，并前千三百戶，與征東大將軍曹休、中軍大將軍曹真、撫軍大將軍司馬宣王並開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-022-18', 'p0008', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '征軍大將軍曹休表得降賊辭，「孫權已在濡須口」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-023-19', 'p0008', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '孫權寇邊，征東大將軍曹休統五州軍禦之，徵儼為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-024-20', 'p0008', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '從大司馬曹休征吳於夾石，禮諫以為不可深入，不從而敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-025-21', 'p0008', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '乆之，太祖遣都護曹洪平下辯，使毗與曹休參之，令曰：「昔高祖貪財好色，而良、平匡其過失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-026-22', 'p0008', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '秋，使曹休從廬江南入合肥，令寵向夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-026-23', 'p0008', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '寵上疏曰：「曹休雖明果而希用兵，今所從道，背湖旁江，易進難退，此兵之窪地也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-028-24', 'p0008', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '後從曹休征吳，與賊遇於夾石，休軍失利，淩力戰決圍，休得免難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-035-25', 'p0008', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮聞孫權破曹休，魏兵東下，關中虛弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-047-26', 'p0008', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-047-27', 'p0008', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '曹休使臧霸以輕船五百、敢死萬人襲攻徐陵，燒攻城車，殺略數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-047-28', 'p0008', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏五月，鄱陽太守周魴偽叛，誘魏將曹休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-051-29', 'p0008', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '江表傳曰：曹休出洞口，呂範率軍禦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-055-30', 'p0008', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹仁出濡須，戰有功，又從攻破曹休，進位裨將軍，黃龍二年卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-055-31', 'p0008', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹休出洞口，盛與呂範、全琮渡江拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-056-32', 'p0008', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-056-33', 'p0008', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武七年，鄱陽太守周魴譎誘魏大司馬曹休，休將步騎十萬至皖城以迎魴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-057-34', 'p0008', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃武元年，與呂範、賀齊等俱以舟師拒魏將曹休於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-058-35', 'p0008', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '七年，權使鄱陽太守周魴譎魏大司馬曹休，休果舉衆入皖，乃召遜假黃鉞，為大都督，逆休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-058-36', 'p0008', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '陸機為遜銘曰：魏大司馬曹休侵我北鄙，乃假公黃鉞，統御六師及中軍禁衞而攝行王事，主上執鞭，百司屈膝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-060-37', 'p0008', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃武初，魏使曹休來伐，齊以道遠後至，因住新市為拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-060-38', 'p0008', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '七年，權到皖，使琮與輔國將軍陸遜擊曹休，破之於石亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-060-39', 'p0008', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '被命密求山中舊族名帥為北敵所聞知者，令譎挑魏大司馬揚州牧曹休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0008-a04-062-40', 'p0008', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '黃武中，遣儀之皖就將軍劉邵，欲誘致曹休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a03-074-0', 'p0009', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹洪以馬與操，得夜遁，又為呂布所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-1', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-2', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公之自舞陰還也，南陽、章陵諸縣復叛為繡，公遣曹洪擊之，不利，還屯葉，數為繡、表所侵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-3', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公乃留曹洪守，自將步騎五千人夜往，會明至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-4', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」乃使張郃、高覽攻曹洪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-5', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，留曹洪攻鄴，公自將擊楷，破之而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-6', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-7', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-001-8', 'p0009', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '曹洪破吳蘭，斬其將任夔等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-004-9', 'p0009', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-006-10', 'p0009', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖乃留曹洪守，自將步騎五千候夜潛往攻瓊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-009-11', 'p0009', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '曹洪字子廉，太祖從弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-009-12', 'p0009', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '卞太后謂郭后曰：「令曹洪今日死，吾明日勑帝廢后矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-009-13', 'p0009', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '劉備遣將吳蘭屯下辯，太祖遣曹洪征之，以休為騎都尉，參洪軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-009-14', 'p0009', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖自至漢中，拔出諸軍，使真至武都迎曹洪等還屯陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-010-15', 'p0009', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '驃騎將軍曹洪女有美色，粲於是娉焉，容服帷帳甚麗，專房歡宴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-012-16', 'p0009', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '頃之，特進曹洪乳母當，與臨汾公主侍者共事無澗神繫獄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-015-17', 'p0009', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '其後與曹洪破吳蘭於下辯，又與夏侯淵討宋建，別攻臨洮、狄道，平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-015-18', 'p0009', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '時曹洪賔客在縣界，徵調不肯如法，沛先撾折其脚，遂殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-015-19', 'p0009', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '沛辭去，未到鄴，而軍中豪右曹洪、劉勳等畏沛，各遣家馳騎告子弟，使各自檢勑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-017-20', 'p0009', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與曹洪擊彊賊祝臂，破之，又與史渙擊袁紹運車於故市，功最多，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-021-21', 'p0009', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '建安中都護曹洪欲使掌書記，瑀終不為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-021-22', 'p0009', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '臣松之案魚氏典略、摯虞文章志並云瑀建安初辭疾避役，不為曹洪屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-021-23', 'p0009', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」驃騎將軍曹洪、輕車將軍王忠言：「將軍必欲使上將軍服肥，即自宜為瘦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-025-24', 'p0009', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '乆之，太祖遣都護曹洪平下辯，使毗與曹休參之，令曰：「昔高祖貪財好色，而良、平匡其過失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-025-25', 'p0009', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '太祖遣都護曹洪禦超等，超等退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a04-026-26', 'p0009', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '時曹洪宗室親貴，有賔客在界，數犯法，寵收治之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0009-a05-013-27', 'p0009', 'jinshu', 'a05-013', '《晉書·卷十三》', '七年正月，驃騎將軍曹洪免為庶人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0010-a04-018-0', 'p0010', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '授聘兵，使與曹純追討劉備於長阪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0011-a04-044-0', 'p0011', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '琬出類拔萃，處羣僚之右，旣無戚容，又無喜色，神守舉止，有如平日，由是衆望漸服，延熈元年，詔琬曰：「寇難未弭，曹叡驕凶，遼東三郡苦其暴虐，遂相糾結，與之離隔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0012-a04-064-0', 'p0012', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '夫以曹芳闇劣，而政在私門，彼之臣民，固有離心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0013-a04-048-0', 'p0013', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '故淮南三叛而腹心不擾，曹髦之死，四方不動，摧堅敵如折枯，蕩異同如反掌，任賢使能，各盡其心，非智勇兼人，孰能如之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a03-070-0', 'p0015', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧將往，東郡太守夏侯惇等止之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a03-073-1', 'p0015', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '疇上疏自陳，太祖令夏侯惇喻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a03-075-2', 'p0015', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魏志曰：「夏侯惇字元讓，沛國譙人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-3', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '吳人作曹瞞傳及郭頒世語並云：嵩，夏侯氏之子，夏侯惇之叔父。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-4', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖兵少，乃與夏侯惇等詣揚州募兵，刺史陳溫、丹楊太守周昕與兵四千餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-5', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-6', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-7', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，王引軍還，留夏侯惇、曹仁、張遼等屯居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-8', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」　魏氏春秋曰：夏侯惇謂王曰：「天下咸知漢祚已盡，異代方起。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-9', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」　曹瞞傳及世語並云桓階勸王正位，夏侯惇以為宜先滅蜀，蜀亡則吳服，二方旣定，然後遵舜、禹之軌，王從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-001-10', 'p0015', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫盛評曰：夏侯惇恥為漢官，求受魏印，桓階方惇，有義直之節；考其傳記，世語為妄矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-002-11', 'p0015', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '已卯，以前將軍夏侯惇為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-002-12', 'p0015', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '庚午，大將軍夏侯惇薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-003-13', 'p0015', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏五月壬申，詔祀故大將軍夏侯惇、大司馬曹仁、車騎將軍程昱於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-007-14', 'p0015', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖遣夏侯惇救備，為順所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-008-15', 'p0015', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '武皇帝意沮，便欲拔軍截山而還，遣故大將軍夏侯惇、將軍許褚呼山上兵還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-009-16', 'p0015', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯惇字元讓，沛國譙人，夏侯嬰之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-009-17', 'p0015', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯惇聞其名，請與相見，大奇之，使領兵從征伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-009-18', 'p0015', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯惇薨，以休為鎮南將軍，假節都督諸軍事，車駕臨送，上乃下輿執手而別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-010-19', 'p0015', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧知邈為亂，即勒兵設備，馳召東郡太守夏侯惇，而兖州諸城皆應布矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-011-20', 'p0015', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '疇素與夏侯惇善，太祖語惇曰：「且往以情喻之，自從君所言，無告吾意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-015-21', 'p0015', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安二十二年，與夏侯惇、臧霸等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-016-22', 'p0015', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖遣夏侯惇討之，未至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-018-23', 'p0015', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉表使劉備北侵，至葉，太祖遣典從夏侯惇拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-018-24', 'p0015', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '後權乞降，太祖還，留霸與夏侯惇等屯居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-018-25', 'p0015', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '後屬夏侯惇，數斬首有功，拜司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-022-26', 'p0015', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '夏侯惇為陳留太守，舉臻計吏，命婦出宴，臻以為「末世之俗，非禮之正」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-032-27', 'p0015', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布遣高順攻之，曹公遣夏侯惇往，不能救，為順所敗，復虜先主妻子送布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-032-28', 'p0015', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '使拒夏侯惇、于禁等於博望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0015-a04-036-29', 'p0015', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先是，與夏侯惇戰於博望，生獲夏侯蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a03-009-0', 'p0016', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月，曹操遣將夏侯淵討宋建于枹罕，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a03-072-1', 'p0016', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '曹操因遣夏侯淵擊建，斬之，涼州悉平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-2', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太原商曜等以大陵叛，遣夏侯淵、徐晃圍破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-3', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，自安定還，留夏侯淵屯長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-4', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超餘衆梁興等屯藍田，使夏侯淵擊平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-5', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂徙金城，入氐王千萬部，率羌、胡萬餘騎與夏侯淵戰，擊，大破之，遂走西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-6', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，公自南鄭還，留夏侯淵屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-001-7', 'p0016', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏侯淵與劉備戰於陽平，為備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-004-8', 'p0016', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-008-9', 'p0016', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖遣夏侯淵討破之，雄鳴南奔漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-10', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏略曰：時夏侯淵與惇俱為將軍，軍中號惇為盲夏侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-11', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '文帝少與楙親，及即位，以為安西將軍、持節，承夏侯淵處都督關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-12', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯淵字妙才，惇族弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-13', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏書曰：淵為將，赴急疾，常出敵之不意，故軍中為之語曰：「典軍校尉夏侯淵，三日五百，六日一千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-009-14', 'p0016', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '是時，夏侯淵沒於陽平，太祖憂之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-014-15', 'p0016', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '又自往拔出夏侯淵軍，數言『南鄭直為天獄，中斜谷道為五百里石穴耳』，言其深險，喜出淵軍之辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-015-16', 'p0016', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '其後與曹洪破吳蘭於下辯，又與夏侯淵討宋建，別攻臨洮、狄道，平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-015-17', 'p0016', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '及夏侯淵還，使閻行留後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-016-18', 'p0016', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖使夏侯淵就助郡擊之，渾率吏民前登，斬興及其支黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-19', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯淵圍昌豨於東海，數月糧盡，議引軍還，遼謂淵曰：「數日已來，每行諸圍，豨輒屬目視遼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-20', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯淵討鄜賊梁興及武都氐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-21', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至陽平，魯降，太祖還，留郃與夏侯淵等守漢中，拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-22', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遂破超等，使晃與夏侯淵平隃麋、汧諸氐，與太祖會安定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-23', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，使晃與夏侯淵平鄜、夏陽餘賊，斬梁興，降三千餘戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-017-24', 'p0016', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，留晃與夏侯淵拒劉備於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-25', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '又與于禁討昌豨，與夏侯淵討黃巾餘賊徐和等，有功，遷徐州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-26', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '虔引兵與夏侯淵會擊之，前後數十戰，斬首獲生數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-018-27', 'p0016', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '超復圍州所治兾城甚急，州乃遣溫密出，告急於夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-023-28', 'p0016', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '夏侯淵為劉備所沒，軍喪元帥，將士失色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-026-29', 'p0016', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖還，留征西將軍夏侯淵拒劉備，以淮為淵司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-030-30', 'p0016', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '超破之後，阿貴為夏侯淵所攻滅，千萬西南入蜀，其部落不能去，皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-032-31', 'p0016', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公使夏侯淵、張郃屯漢中，數數犯暴巴界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-035-32', 'p0016', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '今蜀、魏為敵戰之國，勢不俱王，自操、備時，彊弱縣殊，而備猶出兵陽平，禽夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-33', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-34', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安二十四年，於漢中定軍山擊夏侯淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-036-35', 'p0016', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '夏侯淵敗，曹公爭漢中地，運米北山下，數千萬囊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-037-36', 'p0016', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-040-37', 'p0016', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '旣亡漢中，使夏侯淵、張郃深入于巴，幾喪一州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-043-38', 'p0016', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魯已還南鄭，北降曹公，然卒破杜濩、朴胡，殺夏侯淵，據漢中，皆權本謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0016-a04-054-39', 'p0016', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '左將軍在漢中，為夏侯淵所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-003-0', 'p0017', 'houhanshu', 'a03-003', '《後漢書·卷三》', '孝宣皇帝以為去聖乆遠，學不厭博，故遂立大、小夏侯尚書，後又立京氏易。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-026-1', 'p0017', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '少博學，以大夏侯尚書敎授，大夏侯名勝，宣帝時人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-027-2', 'p0017', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '少好學，習小夏侯尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-027-3', 'p0017', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '又治尚書，學通師法，東觀記曰：「良習大夏侯尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-036-4', 'p0017', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '逵悉傳父業，弱冠能誦左氏傳及五經本文，以大夏侯尚書敎授，雖為古學，兼通五家穀梁之說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-036-5', 'p0017', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '逵數為帝言古文尚書與經傳爾雅詁訓相應，詔令撰歐陽、大小夏侯尚書古文同異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-041-6', 'p0017', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '父京，以大夏侯尚書敎授，夏侯勝也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a03-079-7', 'p0017', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '中興，北海牟融習大夏侯尚書，東海王良習小夏侯尚書，沛國桓榮習歐陽尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-003-8', 'p0017', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」達旣為文帝所寵，又與桓階、夏侯尚親善，及文帝崩，時桓、尚皆卒，達自以羈旅久在疆場，心不自安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-004-9', 'p0017', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-009-10', 'p0017', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '與夏侯尚等征孫權，擊牛渚屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-009-11', 'p0017', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯尚字伯仁，淵從子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-010-12', 'p0017', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '及彧卒，惲又與植善，而與夏侯尚不穆，文帝深恨惲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-014-13', 'p0017', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大駕幸宛，征南大將軍夏侯尚等攻江陵，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-014-14', 'p0017', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時有詔，詔征南將軍夏侯尚曰：「卿腹心重將，時當任使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-015-15', 'p0017', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：儒字俊林，夏侯尚從弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-015-16', 'p0017', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖善之，拜諫議大夫，與夏侯尚並掌軍計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-017-17', 'p0017', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '詔郃與曹真討安定盧水胡及東羌，召郃與真並朝許宮，遣南與夏侯尚擊江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-017-18', 'p0017', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯尚討劉備於上庸，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-018-19', 'p0017', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與夏侯尚圍江陵，使聘別屯沔口，止石梵，自當一隊，禦賊有功，遷後將軍，封新野侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-019-20', 'p0017', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '乃對中領軍夏侯尚叩頭求哀，尚為涕泣而不能救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-023-21', 'p0017', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時夏侯尚暱於太子，情好至密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-040-22', 'p0017', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '遣征南將軍夏侯尚、右將軍徐晃與達共襲封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-047-23', 'p0017', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-052-24', 'p0017', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：曹真、夏侯尚等圍朱然於江陵，又分據中州，瑾以大兵為之救援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-055-25', 'p0017', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將夏侯尚等圍南郡，分前部三萬人作浮橋，渡百里洲上，諸葛瑾、楊粲並會兵赴救，未知所出，而魏兵日渡不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a04-056-26', 'p0017', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏遣曹真、夏侯尚、張郃等攻江陵，魏文帝自住宛，為其勢援，連屯圍城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0017-a05-013-27', 'p0017', 'jinshu', 'a05-013', '《晉書·卷十三》', '四月，征南大將軍夏侯尚薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-009-0', 'p0018', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏氏春秋曰：初，夏侯霸將奔蜀，呼玄欲與之俱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-022-1', 'p0018', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後年，雍州刺史王經白泰，云姜維、夏侯霸欲三道向祁山、石營、金城，求進兵為翅，使涼州軍至枹，討蜀護軍向祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-026-2', 'p0018', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '討蜀護軍夏侯霸督諸軍屯為翅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-026-3', 'p0018', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」乃別遣夏侯霸等追維於沓中，淮自率諸軍就攻化等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-028-4', 'p0018', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：夏侯霸奔蜀，蜀朝問「司馬公如何德」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-028-5', 'p0018', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-033-6', 'p0018', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十二年春正月，魏誅大將軍曹爽等，右將軍夏侯霸來降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-036-7', 'p0018', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-043-8', 'p0018', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '嶷至，拜盪寇將軍，慷慨壯烈，士人咸多貴之，然放蕩少禮，人亦以此譏焉，益部耆舊傳曰：時車騎將軍夏侯霸謂嶷曰：「雖與足下踈闊，然託心如舊，宜明此意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-044-9', 'p0018', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '又出隴西、南安、金城界，與魏大將軍郭淮、夏侯霸等戰於洮西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a04-044-10', 'p0018', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '維乘勝多所降下，拔河間、狄道、臨洮三縣民還，後十八年，復與車騎將軍夏侯霸等俱出狄道，大破魏雍州刺史王經於洮西，經衆死者數萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0018-a05-034-11', 'p0018', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '夏侯霸之降蜀也，姻親多告絕，祜獨安其室，恩禮有加焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-004-0', 'p0019', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚戌，中書令李豐與皇后父光祿大夫張緝等謀廢易大臣，以太常夏侯玄為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-004-1', 'p0019', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之案夏侯玄傳及魏略，許允此年春與李豐事相連。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-2', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時征西將軍夏侯玄，於霸為從子，而玄於曹爽為外弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-3', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '漢晉春秋曰：司馬宣王謂夏侯玄曰：「春秋責大德重，昔武皇帝再入漢中，幾至大敗，君所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-4', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '夏侯玄為征西將軍，以勝為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-009-5', 'p0019', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '魏氏春秋曰：初，夏侯玄、何晏等名盛於時，司馬景王亦預焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-6', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正始中，夏侯玄盛有名勢，貞嘗在玄坐作五言詩，玄嘉玩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-7', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏弱冠知名，傅子曰：是時何晏以材辯顯於貴戚之間，鄧颺好變通，合徒黨，鬻聲名於閭閻，而夏侯玄以貴臣子少有重名，為之宗主，求交於嘏而不納也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-8', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '愚以為夏侯玄以名重致患，釁由外至；鍾會以利動取敗，禍自己出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-021-9', 'p0019', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」豐後為中書令，與夏侯玄俱禍，卒如嘏言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-022-10', 'p0019', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹爽輔政，使夏侯玄宣指，欲引臻入守尚書令，及為弟求婚，皆不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-023-11', 'p0019', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '常慕其舅夏侯玄之為人，厚自封植，嶷然不羣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-023-12', 'p0019', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '義子豐，字宣國，見夏侯玄傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-026-13', 'p0019', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '五年，夏侯玄伐蜀，淮督諸軍為前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-14', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，儉與夏侯玄、李豊等厚善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-15', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '累遷御史中丞尚書，與夏侯玄、鄧颺等相善，收名朝廷，京都翕然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-028-16', 'p0019', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-033-17', 'p0019', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a04-039-18', 'p0019', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '夏侯玄、陳表並有騂角之美，而亦如泰者，魏書總名此卷云諸夏侯曹傳，故不復稍加品藻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-19', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '少流美譽，與夏侯玄、何晏齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-20', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-21', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '正元元年春正月，天子與中書令李豐、后父光祿大夫張緝、黃門監蘇鑠、永寧署令樂敦、冗從僕射劉寶賢等謀以太常夏侯玄代帝輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0019-a05-002-22', 'p0019', 'jinshu', 'a05-002', '《晉書·卷二》', '大將軍曹爽之伐蜀也，以帝為征蜀將軍，副夏侯玄出駱谷，次于興勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-049-0', 'p0020', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '尚書令荀彧聞統名，竒之，舉為尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-067-1', 'p0020', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '甞稱「潁川荀彧，王佐之器」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-070-2', 'p0020', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '荀彧薦襲，太祖以為丞相軍謀祭酒，魏國建，為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-070-3', 'p0020', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '尚書令荀彧深建宜住之便，遠恢進討之略，恢，大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-074-4', 'p0020', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹乃使外甥陳留高幹及潁川荀諶等說馥曰：魏志云諶，荀彧之弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a03-099-5', 'p0020', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '後荀彧問仲長統以社所祭者何神也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-6', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-7', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧、程昱保鄄城，范、東阿二縣固守，太祖乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-8', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-9', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公與荀彧書曰：「賊來追吾，雖日行數里，吾策之，到安衆，破繡必矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-10', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧問公：「前以策賊必破，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-001-11', 'p0020', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公糧少，與荀彧書，議欲還許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-002-12', 'p0020', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '後軍南征次內蠡，尚書令荀彧奉使犒軍，見余談論之末，彧言：「聞君善左右射，此實難能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-004-13', 'p0020', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之以為故魏氏配饗不及荀彧，蓋以其末年異議，又位非魏臣故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-006-14', 'p0020', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '荊州平，太祖與荀彧書曰：「不喜得荊州，喜得蒯異度耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-15', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀彧字文若，潁川潁陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-16', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鍾繇以為顏子旣沒，能備九德，不貳其過，唯荀彧然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-17', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒旣奇太祖而知荀彧，袁紹慕之，與為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-18', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後荀彧為尚書令，遣人迎叔父司空爽喪，使并置顒尸，而葬之於爽冢傍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-19', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖素聞攸名，與語大恱，謂荀彧，鍾繇曰：「公達，非常人也，吾得與之計事，天下當何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-010-20', 'p0020', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '評曰：荀彧清秀通雅，有王佐之風，然機鑒先識，未能充其志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-011-21', 'p0020', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '尚書令荀彧、司隷校尉鍾繇亦以為可聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-011-22', 'p0020', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」　魏書載荀彧議，以為「君子之道，或出或處，期於為善而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-23', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-24', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖旣數聽荀彧之稱繇，又聞其說傕、汜，益虛心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-013-25', 'p0020', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '歆至，拜議郎，參司空軍事，入為尚書，轉侍中，代荀彧為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-26', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征徐州，使昱與荀彧留守鄄城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-27', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖與荀彧書曰：「自志才亡後，莫可與計事者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-28', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖與荀彧書，追傷嘉曰：「郭奉孝年不滿四十，相與周旋十一年，阻險艱難，皆共罹之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-29', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」獻帝春秋曰：昭與列侯諸將議，以丞相宜進爵國公，九錫備物，以彰殊勳；書與荀彧曰：「昔周旦、呂望，當姬氏之盛，因二聖之業，輔翼成王之幼，功勳若彼，猶受上爵，錫土開宇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-014-30', 'p0020', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '尚書令荀彧見資，歎曰：「北州承喪亂已乆，謂其賢智零落，今日乃復見孫計君乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-31', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '荀彧進之太祖，傅子曰：畿自荊州還，後至許，見侍中耿紀，語終夜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-32', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '尚書令荀彧與紀比屋，夜聞畿言，異之，旦遣人謂紀曰：「有國士而不進，何以居位？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-016-33', 'p0020', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖謂荀彧曰：「關西諸將，恃險與馬，征必為亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-34', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時四方大有還民，關中諸將多引為部曲，覬書與荀彧曰：「關中膏腴之地，頃遭荒亂，人民流入荊州者十萬餘家，聞本土安寧，皆企望思歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-35', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖使荀彧問覬，覬以為「西方諸將，皆豎夫屈起，無雄天下意，苟安樂目前而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-36', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」劭時在尚書令荀彧所，坐者數十人，或云當廢朝，或云宜却會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-021-37', 'p0020', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '漢帝在許，尚書令荀彧領典樞機，好士愛奇，聞統名，啟召以為尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-023-38', 'p0020', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '荀彧又薦襲，太祖以為丞相軍祭酒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-023-39', 'p0020', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」乃書與荀彧曰：「今陽安郡當送緜絹，道路艱阻，必致寇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-026-40', 'p0020', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-029-41', 'p0020', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '荀彧請曰：「佗術實工，人命所縣，宜含宥之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-037-42', 'p0020', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '儗之魏臣，統其荀彧之仲叔，正其程、郭之儔儷邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-038-43', 'p0020', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '陳國袁徽以寄寓交州，徽與尚書令荀彧書曰：「許文休英才偉士，智略足以計事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a04-049-44', 'p0020', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '陳國袁徽與尚書令荀彧書曰：「交阯士府君旣學問優博，又達於從政，處大亂之中，保全一郡，二十餘年疆埸無事，民不失業，羈旅之徒，皆蒙其慶，雖竇融保河西，曷以加之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a05-019-45', 'p0020', 'jinshu', 'a05-019', '《晉書·卷十九》', '朝士疑會否，共諮尚書令荀彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0020-a05-019-46', 'p0020', 'jinshu', 'a05-019', '《晉書·卷十九》', '於時有謂邵為不得禮意，荀彧從之，是勝人之一失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-069-0', 'p0021', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '因復博徵智謀之士龐紀、何顒、荀攸等，與同腹心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-1', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '謂潁川人荀攸曰：「何公未易輔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-2', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '乃與何顒、荀攸共謀殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-3', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧又進操計謀之士從子攸，魏志，荀攸字公達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a03-070-4', 'p0021', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧使荀攸深自陳讓，至于十數，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-5', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公連戰，士卒罷，欲還，用荀攸、郭嘉計，遂決泗、沂水以灌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-6', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀攸說公曰：「今兵少不敵，分其勢乃可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-7', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀攸曰：「此所以餌敵，如何去之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-8', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-9', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '左右疑之，荀攸、賈詡勸公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-10', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-11', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-001-12', 'p0021', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-004-13', 'p0021', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月癸卯，詔祀故尚書令荀攸於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-004-14', 'p0021', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-15', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧言「荀攸、鍾繇」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-16', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」太祖欲表彧為三公，彧使荀攸深讓，至于十數，太祖乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-17', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-18', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸後為魏尚書令，亦推賢進士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-19', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸字公達，彧從子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-20', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '兾州平，太祖表封攸曰：「軍師荀攸，自初佐臣，無征不從，前後克敵，皆攸之謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-010-21', 'p0021', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸、賈詡，庶乎筭無遺策，經達權變，其良、平之亞與！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-013-22', 'p0021', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-013-23', 'p0021', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '靈帝崩，何進輔政，徵河南鄭泰、潁川荀攸及歆等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-014-24', 'p0021', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及薨，臨其喪，哀甚，謂荀攸等曰：「諸君年皆孤輩也，唯奉孝最少。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-014-25', 'p0021', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-016-26', 'p0021', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾兄泰，與荀攸等謀誅董卓，為揚州刺史，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-016-27', 'p0021', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '謂潁川人荀攸曰：「何公未易輔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a04-029-28', 'p0021', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '初，潁川荀攸、鍾繇相與親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0021-a05-039-29', 'p0021', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '昔魏武帝使中軍司荀攸典刑獄，明帝時猶以付內常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-009-0', 'p0022', 'houhanshu', 'a03-009', '《後漢書·卷九》', '賈詡奏曰：『立司候不明，疑誤上下，請付理官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-010b-full-1', 'p0022', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」尚書賈詡知之，魏志曰：「詡字文和，武威姑臧人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-071-2', 'p0022', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」會李傕用太尉周忠、尚書賈詡策，徵儁入朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-3', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '武威人賈詡時在傕軍，說之曰：魏志曰：「卓之入洛陽，詡以太尉掾為平津尉，遷討虜校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-4', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以賈詡為左馮翊，欲侯之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-072-5', 'p0022', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '前涼州刺史种劭、中郎將杜稟合兵攻傕，獻帝紀曰：「稟與賈詡有隙，脅扶風吏人為騰守槐里，欲共攻傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a03-108-6', 'p0022', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '尚書賈詡奏曰：『立伺候不明，疑誤上下；太尉周忠，職所典掌，請皆治罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-7', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '左右疑之，荀攸、賈詡勸公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-8', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '超等數挑戰，又不許；固請割地，求送任子，公用賈詡計，偽許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-001-9', 'p0022', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-002-10', 'p0022', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-002-11', 'p0022', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-12', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '用賈詡策，遂將其衆而西，所在收兵，比至長安，衆十餘萬，九州春秋曰：傕等在陝，皆恐怖，急擁兵自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-13', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '賈詡曰「此上意，不可拒」，傕不從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-006-14', 'p0022', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」於是天子一乘，貴人伏氏一乘，賈詡、左靈一乘，其餘皆步從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-008-15', 'p0022', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：繡降，用賈詡計，乞徙軍就高道，道由太祖屯中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-008-16', 'p0022', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖拒袁紹於官渡，繡從賈詡計，復以衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-17', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '賈詡字文和，武威姑臧人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-18', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '當是時，元惡旣梟，天地始開，致使厲階重結，大梗殷流，邦國遘殄悴之哀，黎民嬰周餘之酷，豈不由賈詡片言乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-19', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔魏文帝用賈詡為三公，孫權笑之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-010-20', 'p0022', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荀攸、賈詡，庶乎筭無遺策，經達權變，其良、平之亞與！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-014-21', 'p0022', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖謂賈詡曰：「程昱之膽，過於賁、育。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0022-a04-036-22', 'p0022', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公用賈詡謀，離間超、遂，更相猜疑，軍以大敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a03-070-0', 'p0023', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」及鍾繇、郭嘉、魏志，嘉字奉孝，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-1', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時公連戰，士卒罷，欲還，用荀攸、郭嘉計，遂決泗、沂水以灌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-2', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-3', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」郭嘉亦勸公，遂東擊備，破之，生禽其將夏侯博。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-001-4', 'p0023', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」惟郭嘉策表必不能任備，勸公行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-004-5', 'p0023', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-004-6', 'p0023', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲，詔祀故軍祭酒郭嘉於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-010-7', 'p0023', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '取士不以一揆，戲志才、郭嘉等有負俗之譏，杜畿簡傲少文，皆以智策舉之，終各顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-010-8', 'p0023', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與郭嘉說曰：「呂布勇而無謀，今三戰皆北，其銳氣衰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-9', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後又遣備至徐州要擊袁術，昱與郭嘉說太祖曰：「公前日不圖備，昱等誠不及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-10', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '郭嘉字奉孝，潁川陽翟人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-11', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」乃表曰：「軍祭酒郭嘉，自從征伐，十有一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-12', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '故軍祭酒郭嘉，忠良淵淑，體通性達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-014-13', 'p0023', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-025-14', 'p0023', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '他日置酒，毗望太祖色，知有變，以語郭嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0023-a04-032-15', 'p0023', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏武帝遣先主統諸將要擊袁術，郭嘉等並諫，魏武不從，其事顯然，非因種菜遁逃而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a03-070-0', 'p0024', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧乃使程昱說范、東阿，魏志：「昱字仲德，東郡東阿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-1', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-2', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荀彧、程昱保鄄城，范、東阿二縣固守，太祖乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-3', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱止太祖，太祖從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-4', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-5', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱說公曰：「觀劉備有雄才而甚得衆心，終不為人下，不如早圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-6', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-001-7', 'p0024', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-003-8', 'p0024', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏五月壬申，詔祀故大將軍夏侯惇、大司馬曹仁、車騎將軍程昱於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-004-9', 'p0024', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-010-10', 'p0024', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '又與程昱計，使說范、東阿，卒全三城，以待太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-11', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '程昱字仲德，東郡東阿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-12', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」岱議連日不決，別駕王彧白岱：「程昱有謀，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-13', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖謂賈詡曰：「程昱之膽，過於賁、育。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-14', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖使備要擊袁術，嘉與程昱俱駕而諫太祖曰：「放備，變作矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-014-15', 'p0024', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-018-16', 'p0024', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖擊譚、尚於黎陽，使典與程昱等以船運軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0024-a04-036-17', 'p0024', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，飛雄壯威猛，亞於關羽，魏謀臣程昱等咸稱羽、飛萬人之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-031-0', 'p0025', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '其諸臧過者，望風解印綬去，唯癭陶長濟陰董昭、觀津長梁國黃就當官待琮，於是州界翕然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-1', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '十七年，董昭等昭字公仁，濟陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-2', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '至董昭建魏公議，彧意不同，欲言之於太祖，乃齎璽書犒軍，飲饗禮畢，彧請間，太祖知彧欲言，揖而遣之，遂不得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a03-070-3', 'p0025', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及阻董昭之議，以致非命，豈數也夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-001-4', 'p0025', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '洛陽殘破，董昭等勸太祖都許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-001-5', 'p0025', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-003-6', 'p0025', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '秋七月，以衞尉董昭為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-003-7', 'p0025', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '五月乙卯，司徒董昭薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-008-8', 'p0025', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載董昭表曰：「武皇帝承涼州從事及武都降人之辭，說張魯易攻，陽平城下南北山相遠，不可守也，信以為然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-010-9', 'p0025', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '十七年，董昭等謂太祖宜進爵國公，九錫備物，以彰殊勳，密以諮彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-010-10', 'p0025', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '至董昭建立魏公之議，彧意不同，欲言之於太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-012-11', 'p0025', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會內官欲以事託芝，不敢發言，因芝妻伯父董昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-014-12', 'p0025', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '董昭字公仁，濟陰定陶人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-014-13', 'p0025', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-016-14', 'p0025', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '徵拜侍中，與董昭同寮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a04-021-15', 'p0025', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '質自以不為本郡所饒，謂司徒董昭曰：「我欲溺鄉里耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0025-a05-013-16', 'p0025', 'jinshu', 'a05-013', '《晉書·卷十三》', '四年五月，司徒董昭薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-002-0', 'p0026', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」　魏王侍中劉廙、辛毗、劉曄、尚書令桓階、尚書陳矯、陳羣、給事黃門侍郎王毖、董遇等言：「臣伏讀左中郎將李伏上事，考圖緯之言，以效神明之應，稽之古代，未有不然者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-002-1', 'p0026', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」於是侍中辛毗、劉曄、散騎常侍傅巽、衞臻、尚書令桓階、尚書陳矯、陳羣、給事中博士騎都尉蘇林、董巴等奏曰：「伏見太史丞許芝上魏國受命之符；令書懇切，允執謙讓，雖舜、禹、湯、文，義無以過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-003-2', 'p0026', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '居數日，獨見侍中劉曄，語盡日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-008-3', 'p0026', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '侍中辛毗、劉曄等在兵後，語惇、褚，言『官兵已據得賊要屯，賊已散走』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-010-4', 'p0026', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-012-5', 'p0026', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」侍中劉曄對曰：「獵勝於樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-012-6', 'p0026', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」因奏：「劉曄佞諛不忠，阿順陛下過戲之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-7', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉曄字子揚，淮南成悳人，悳音德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-8', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣言誠不足采，侍中劉曄先帝謀臣，常曰蜀不可伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-014-9', 'p0026', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-017-10', 'p0026', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '帝遣侍中劉曄將太醫視疾，虎賁問消息，道路相屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-022-11', 'p0026', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '世語曰：劉曄以先進見幸，因譖矯專權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-022-12', 'p0026', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」旣入，盡日，帝曰：「劉曄構君，朕有以迹君；朕心故已了。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-025-13', 'p0026', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '文帝問侍中劉曄等：「武都太守何如人也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-026-14', 'p0026', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '臣松之案：曁字休先，熒陽人，事見劉曄傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-037-15', 'p0026', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '劉曄曰：「子昭拔自賈豎，年至耳順，退能守靜，進能不苟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0026-a04-047-16', 'p0026', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '珩還言曰：「臣密參侍中劉曄，數為賊設姦計，終不乆愨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-004-0', 'p0027', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙酉，以領軍將軍蔣濟為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-1', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '干寶晉書曰：桓範出赴爽，宣王謂蔣濟曰：「智囊往矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-2', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」　世語曰：宣王使許允、陳泰解語爽，蔣濟亦與書達宣王之旨，又使爽所信殿中校尉尹大目謂爽，唯免官而已，以洛水為誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-3', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '中護軍蔣濟表曰：「畢軌前失，旣往不咎，但恐是後難可以再。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-4', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '蔣濟為太尉，嘗與範會社下，羣卿列坐有數人，範懷其所撰，欲以示濟，謂濟當虛心觀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-5', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '干寶晉紀曰：蔣濟以曹真之勳力，不宜絕祀，故以熈為後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-009-6', 'p0027', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '故蔣濟為護軍時，有謠言「欲求牙門，當得千匹；百人督，五百匹」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-013-7', 'p0027', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '肅與太尉蔣濟、司農桓範論及時政，肅正色曰：「此輩即弘恭、石顯之屬，復稱說邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-8', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖徵曄及蔣濟、胡質等五人，皆揚州名士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-9', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '蔣濟字子通，楚國平阿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-10', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」民有誣告濟為謀叛主率者，太祖聞之，指前令與左將軍于禁、沛相封仁等曰：「蔣濟寧有此事！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-11', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '蔣濟諫曰：「凡非相吞之國，不侵叛之臣，不宜輕伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-12', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣松之案蔣濟立郊議稱曹騰碑文云「曹氏族出自邾」，魏書述曹氏胤緒亦如之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-13', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫盛曰：蔣濟之辭邑，可謂不負心矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-14', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '語曰「不為利回，不為義疚」，蔣濟其有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-014-15', 'p0027', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '評曰：程昱、郭嘉、董昭、劉曄、蔣濟才策謀略，世之奇士，雖清治德業殊於荀攸，而籌畫所料是其倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-015-16', 'p0027', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '』得無當得蔣濟為治中邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-021-17', 'p0027', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太尉蔣濟聞而辟之，後為尚書郎、曹爽參軍，以疾歸田里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-022-18', 'p0027', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '中護軍蔣濟遺臻書曰：「漢祖遇亡虜為上將，周武拔漁父為太師；布衣厮養，可登王公，何必守文，試而後用？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-19', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '揚州治在其縣，時蔣濟為治中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-20', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '苗恚恨還，刻木為人，署曰「酒徒蔣濟」，置之牆下，旦夕射之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-023-21', 'p0027', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '如所忿蔣濟者，仕進至太尉，濟不以苗前毀己為嫌，苗亦不以濟貴更屈意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-025-22', 'p0027', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '初，太和中，中護軍蔣濟上疏曰「宜遵古封禪」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-026-23', 'p0027', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」護軍將軍蔣濟議，以為：「旣示天下以弱，且望賊煙火而壞城，此為未攻而自拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-027-24', 'p0027', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '少與蔣濟、朱績俱知名於江、淮間，仕州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-027-25', 'p0027', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '蔣濟為別駕，使見太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-028-26', 'p0027', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '太傅嘗從容問蔣濟，濟曰：「淩文武俱贍，當今無雙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-028-27', 'p0027', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '中護軍蔣濟著論，謂「觀其眸子，足以知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-036-28', 'p0027', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-037-29', 'p0027', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '蔣濟萬機論云許子將襃貶不平，以拔樊子昭而抑許文休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-037-30', 'p0027', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '至於友于不穆，失由子將，尋蔣濟之論，知非文休之尤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a04-038-31', 'p0027', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '評曰：許靖夙有名譽，旣以篤厚為稱，又以人物為意，雖行事舉動，未悉允當，蔣濟以為「大較廊廟器」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-32', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '大司農桓範出赴爽，蔣濟言於帝曰：「智囊往矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-33', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '帝親帥太尉蔣濟等勒兵出迎天子，屯于洛水浮橋，上奏曰：「先帝詔陛下、秦王及臣升於御牀，握臣臂曰『深以後事為念』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-001-34', 'p0027', 'jinshu', 'a05-001', '《晉書·卷一》', '蔣濟曰：「曹真之勳，不可以不祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-012-35', 'p0027', 'jinshu', 'a05-012', '《晉書·卷十二》', '蔣濟上疏曰：「昔大舜佐治，戒在比周。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0027-a05-042-36', 'p0027', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '楚王瑋將害汝南王亮等也，公孫宏說瑋曰：「昔宣帝廢曹爽，引太尉蔣濟參乘，以增威重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-054-0', 'p0028', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕脅帝歸其營，竒與黃門侍郎鍾繇誘傕部曲將宋曅、楊昂令反傕，傕由此孤弱，帝乃得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-066-1', 'p0028', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '鍾繇字元常，魏太祖時為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-070-2', 'p0028', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」及鍾繇、郭嘉、魏志，嘉字奉孝，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a03-072-3', 'p0028', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-4', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '按鍾繇傳云：「公與紹相持，繇為司隷，送馬二千餘匹以給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-5', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯據漢中，三月，遣鍾繇討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-6', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-7', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，以大理鍾繇為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-8', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '九月，相國鍾繇坐西曹掾魏諷反免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-001-9', 'p0028', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '世語曰：諷字子京，沛人，有惑衆才，傾動鄴都，鍾繇由是辟焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-002-10', 'p0028', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月丁卯，以廷尉鍾繇為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-003-11', 'p0028', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-004-12', 'p0028', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-004-13', 'p0028', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '至於升程昱而遺郭嘉，先鍾繇而後荀攸，則未詳厥趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-14', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧言「荀攸、鍾繇」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-15', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '鍾繇以問彧，彧曰：「公之聦明，必不追咎往事，殆有他慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-16', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-17', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '時有甲乙疑論，閎與鍾繇、王朗、袁渙議各不同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-18', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-19', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鍾繇以為顏子旣沒，能備九德，不貳其過，唯荀彧然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-20', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖素聞攸名，與語大恱，謂荀彧，鍾繇曰：「公達，非常人也，吾得與之計事，天下當何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-21', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與鍾繇善，繇言：「我每有所行，反覆思惟，自謂無以易；以咨公達，輒復過人意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-010-22', 'p0028', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '臣松之案：攸亡後十六年，鍾繇乃卒，撰攸奇策，亦有何難？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-23', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '尚書令荀彧、司隷校尉鍾繇亦以為可聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-24', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '鍾繇以為「原思辭粟，仲尼不與，子路拒牛，謂之止善，雖可以激清勵濁，猶不足多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-25', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」相國鍾繇謂脩：「舊，京城有變，九卿各居其府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-011-26', 'p0028', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，昭善史書，與鍾繇、邯鄲淳、衞覬、韋誕並有名，尺牘之迹，動見模楷焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-012-27', 'p0028', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '大理鍾繇詰玠曰：「自古聖帝明王，罪及妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-012-28', 'p0028', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-29', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '鍾繇字元常，頴川長社人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-30', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-31', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '謹桉侍中守司隷校尉東武亭侯鍾繇，幸得蒙恩，以斗筲之才，仍見拔擢，顯從近密，銜命督使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-32', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '鍾繇明察當法，俱以治獄見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-33', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '至黃初初，朗又與太尉鍾繇連名表聞，兼稱登在職勤勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-34', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '司隷鍾繇在東，識其文，曰：「此賈洪作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-013-35', 'p0028', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-015-36', 'p0028', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '鍾繇、王粲著論云：「非聖人不能致太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-015-37', 'p0028', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司隷校尉鍾繇遣旣說將軍馬騰等，旣為言利害，騰等從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-018-38', 'p0028', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-021-39', 'p0028', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾繇、王朗等雖各為魏卿相，至於朝廷奏議，皆閣筆不能措手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-021-40', 'p0028', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾繇求以三千兵入關，外託討張魯，內以脅取質任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-022-41', 'p0028', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」時鍾繇與羣議同，王朗及議者多以為未可行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-42', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '是時科禁長吏擅去官，而黃聞司徒趙溫薨，自以為故吏，違科奔喪，為司隷鍾繇所收，遂伏法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-43', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '司隷鍾繇表拜議郎參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-023-44', 'p0028', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '司隷鍾繇不好公羊而好左氏，謂左氏為太官，而謂公羊為賣餅家，故數與幹共辯析長短。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-024-45', 'p0028', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-028-46', 'p0028', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '宣王為泰會，使尚書鍾繇調泰：「君釋褐登宰府，三十六日擁麾蓋，守兵馬郡；乞兒乘小車，一何駛乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-028-47', 'p0028', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　臣松之案：鍾繇于時老矣，而方納正室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-029-48', 'p0028', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '初，潁川荀攸、鍾繇相與親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-032-49', 'p0028', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-032-50', 'p0028', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後為五官將司馬，相國鍾繇長史，年六十餘卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-036-51', 'p0028', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '司隷校尉鍾繇鎮關中，移書遂、騰，為陳禍福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a04-036-52', 'p0028', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安之初，國家綱紀始弛，乃使司隷校尉鍾繇、涼州牧韋端和解之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a05-019-53', 'p0028', 'jinshu', 'a05-019', '《晉書·卷十九》', '及文帝崩，太尉鍾繇告謚南郊，皆是有事於郊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0028-a05-039-54', 'p0028', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '從外祖魏太傅鍾繇曰：「此兒當及其曾祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-009-0', 'p0029', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二十二年夏六月，丞相軍師華歆為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-010b-full-1', 'p0029', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」又以尚書令華歆為郗慮副，魏志曰：「華歆字子魚，平原高唐人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-010b-2', 'p0029', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」又以尚書令華歆爲郗慮副，〈《魏志》曰：「華歆字子魚，平原高唐人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-053-3', 'p0029', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '太守華歆禮請相見，固病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a03-110-4', 'p0029', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '庚午，登壇，魏相國華歆跪受璽綬，以進於王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-001-5', 'p0029', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '曹瞞傳曰：公遣華歆勒兵入宮收后，后閉戶匿壁中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-001-6', 'p0029', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '六月，以軍師華歆為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-7', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '今使使持節御史大夫華歆奉策詔授丕丞相印綬、魏王璽紱，領兾州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-8', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-002-9', 'p0029', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-003-10', 'p0029', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-004-11', 'p0029', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-004-12', 'p0029', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　魏名臣奏載太尉華歆表曰：「臣聞勵俗宣化，莫先於表善，班祿敘爵，莫美於顯能，是以楚人思子文之治，復命其胤，漢室嘉江公之德，用顯其世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-010-13', 'p0029', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-14', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '與平原華歆、同縣邴原相友，俱游學於異國，並敬善陳仲弓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-15', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '黃初四年，詔公卿舉獨行君子，司徒華歆薦寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-16', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '明帝即位，太尉華歆遜位讓寧，傅子曰：司空陳羣又薦寧曰：「臣聞王者顯善以消惡，故湯舉伊尹，不仁者遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-011-17', 'p0029', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '黃初四年，高祖文皇帝疇咨羣公，思求儁乂，故司徒華歆舉寧應選，公車特徵，振翼遐裔，翻然來翔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-012-18', 'p0029', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-19', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時司徒華歆、司空王朗，並先世名臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-20', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時華歆亦以高年疾病，朝見皆使載輿車，虎賁舁上殿就坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-21', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '華歆字子魚，平原高唐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-013-22', 'p0029', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-016-23', 'p0029', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '時華歆為豫章太守，素與泰善，渾乃渡江投歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-035-24', 'p0029', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮集曰：是歲，魏司徒華歆、司空王朗、尚書令陳羣、太史令許芝、謁者僕射諸葛璋各有書與亮，陳天命人事，欲使舉國稱藩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-038-25', 'p0029', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '始靖兄事潁川陳紀，與陳郡袁渙、平原華歆、東海王朗等親善，歆、朗及紀并子羣，魏初為公輔大臣，咸與靖書，申陳舊好，情義欵至，文多故不載。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-046-26', 'p0029', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '勳糧食少，無以相振，乃遣從弟偕告糴於豫章太守華歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-047-27', 'p0029', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '年十一，華歆行風俗，見而異之，因呼曰：「沈郎，可登車語乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-057-28', 'p0029', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」翻別傳曰：朗使翻見豫章太守華歆，圖起義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0029-a04-057-29', 'p0029', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '統母改適，為華歆小妻，統時八歲，遂與親客歸會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-037-0', 'p0030', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '後東適會稽，住止山陰縣故魯相鍾離意舍，太守王朗餉給糧食、布帛、牛羊，一無所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-045-1', 'p0030', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '一見太守王朗徒從整飾，心嫌之，遂稱病自絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-045-2', 'p0030', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '王朗字景興，肅之父也，魏志有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-049-3', 'p0030', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '其後王朗為會稽太守，又得其書，及還許下，時人稱其才進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a03-080b-4', 'p0030', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '府掾孔融、王朗並修刺候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-001-5', 'p0030', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-6', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '壬戌，以大中大夫賈詡為太尉，御史大夫華歆為相國，大理王朗為御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-7', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」相國華歆、太尉賈詡、御史大夫王朗及九卿上言曰：「臣等被召到，伏見太史丞許芝、左中郎將李伏所上圖讖、符命，侍中劉廙等宣叙衆心，人靈同謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-8', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏氏春秋曰：明帝將送葬，曹真、陳羣、王朗等以暑熱固諫，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-002-9', 'p0030', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書曰：帝初在東宮，疫癘大起，時人彫傷，帝深感歎，與素所敬者大理王朗書曰：「生有七尺之形，死為一棺之土，唯立德揚名，可以不朽，其次莫如著篇籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-003-10', 'p0030', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，以太尉鍾繇為太傅，征東大將軍曹休為大司馬，中軍大將軍曹真為大將軍，司徒華歆為太尉，司空王朗為司徒，鎮軍大將軍陳羣為司空，撫軍大將軍司馬宣王為驃騎大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-004-11', 'p0030', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-004-12', 'p0030', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月辛亥，詔故司徒王朗所作易傳，令學者得以課試。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-005-13', 'p0030', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明帝即位，有司奏請追謚，使司空王朗持節奉策以太牢告祠于陵，又別立寢廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-007-14', 'p0030', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-010-15', 'p0030', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '時有甲乙疑論，閎與鍾繇、王朗、袁渙議各不同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-010-16', 'p0030', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-17', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時司徒華歆、司空王朗，並先世名臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-18', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」司徒王朗議，以為「繇欲輕減大辟之條，以增益刖刑之數，此即起偃為豎，化屍為人矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-19', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '王朗字景興，東海郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-20', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '策令使者詰朗曰：「問逆賊故會稽太守王朗：朗受國恩當官，云何不惟報德，而阻兵安忍？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-21', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」王朗集載朗為大理時上主簿趙郡張登：「昔為本縣主簿，值黑山賊圍郡，登與縣長王儁帥吏兵七十二人直往赴救，與賊交戰，吏兵散走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-013-22', 'p0030', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '評曰：鍾繇開達理幹，華歆清純德素，王朗文博富贍，誠皆一時之俊偉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-017-23', 'p0030', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及太祖領兖州，禁與其黨俱詣為都伯，屬將軍王朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-021-24', 'p0030', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾繇、王朗等雖各為魏卿相，至於朝廷奏議，皆閣筆不能措手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-022-25', 'p0030', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」時鍾繇與羣議同，王朗及議者多以為未可行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-027-26', 'p0030', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '頃之，司徒王朗辟基，淩不遣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-035-27', 'p0030', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮集曰：是歲，魏司徒華歆、司空王朗、尚書令陳羣、太史令許芝、謁者僕射諸葛璋各有書與亮，陳天命人事，欲使舉國稱藩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-035-28', 'p0030', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-29', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '禕死，吳郡都尉許貢、會稽太守王朗素與靖有舊，故往保焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-30', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '始靖兄事潁川陳紀，與陳郡袁渙、平原華歆、東海王朗等親善，歆、朗及紀并子羣，魏初為公輔大臣，咸與靖書，申陳舊好，情義欵至，文多故不載。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-038-31', 'p0030', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '魏略：王朗與文休書曰：「文休足下：消息平安，甚善甚善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-042-32', 'p0030', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '魏太子荅王朗書曰：「昔石厚與州吁游，父碏知其與亂；韓子昵田蘇，穆子知其好仁：故君子游必有方，居必就士，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-046-33', 'p0030', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」術知其恨，而以劉繇據曲阿，王朗在會稽，謂策未必能定，故許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-049-34', 'p0030', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '王朗遺策書曰：「劉正禮昔初臨州，未能自達，實賴尊門為之先後，用能濟江成治，有所處定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-051-35', 'p0030', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '是時太守王朗拒策於固陵，策數渡水戰，不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-052-36', 'p0030', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少好學，善隷書，從白侯子安受左氏春秋，博覽衆書，與琅邪趙昱、東海王朗俱發名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a04-060-37', 'p0030', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '時王朗奔東冶，候官長商升為朗起兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0030-a05-019-38', 'p0030', 'jinshu', 'a05-019', '《晉書·卷十九》', '明帝即位，有司奏請追謚曰文昭皇后，使司空王朗持節奉策告祠于陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a03-072-0', 'p0032', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '萌字文始，有才學，與王粲善，粲作詩贈萌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-1', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-2', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-001-3', 'p0032', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是行也，侍中王粲作五言詩以美其事，曰：「從軍有苦樂，但問所從誰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-006-4', 'p0032', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '萌字文始，亦有才學，與王粲善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-013-5', 'p0032', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其邯鄲淳事在王粲傳，蘇林事在劉邵、高堂隆傳，樂詳事在杜畿傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-015-6', 'p0032', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '鍾繇、王粲著論云：「非聖人不能致太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-7', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '王粲字仲宣，山陽高平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-8', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏侍中王粲識舊珮，始復作之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-9', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-021-10', 'p0032', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏國旣建，拜侍中，與王粲並典制度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-11', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-12', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏國旣建，為侍中，與王粲、和洽並用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-023-13', 'p0032', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '潛私謂所親王粲、司馬芝曰：「劉牧非霸王之才，乃欲西伯自處，其敗無日矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-028-14', 'p0032', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '博物記曰：初，王粲與族兄凱俱避地荊州，劉表欲以女妻粲，而嫌其形陋而用率，以凱有風貌，乃以妻凱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a04-061-15', 'p0032', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '吳書曰：濬為人聦察，對問有機理，山陽王粲見而貴異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0032-a05-019-16', 'p0032', 'jinshu', 'a05-019', '《晉書·卷十九》', '魏氏承漢末大亂，舊章殄滅，命侍中王粲、尚書衞覬草創朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-058-0', 'p0033', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '紹興兵圍之，歷年不下，使洪邑人陳琳以書譬洪，示其禍福，責以恩義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-069-1', 'p0033', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '主簿陳琳入諫曰：「易稱『即鹿無虞』，易屯卦六三爻辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-070-2', 'p0033', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安初，以高第擢拜尚書郎，後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-070-3', 'p0033', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '陳琳為紹作檄書曰：「操祖父騰饕餮放橫，父嵩乞匄攜養，操贅閹遺醜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-073-4', 'p0033', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」紹候得其書，獻帝春秋「候者得書，紹使陳琳易其詞」，即此書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-074-5', 'p0033', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '據陳琳集，此檄陳琳之詞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-074-6', 'p0033', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」流俗本此下有「陳琳之辭」者，非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a03-080b-7', 'p0033', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-001-8', 'p0033', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '故豫州刺史陰夔及陳琳乞降，公不許，為圍益急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-006-9', 'p0033', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '未合，尚懼，遣陰夔、陳琳乞降，不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-007-10', 'p0033', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '紹令洪邑人陳琳書與洪，喻以禍福，責以恩義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-008-11', 'p0033', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹候者得之，使陳琳更其書曰：「蓋聞在昔衰周之世，僵戶流血，以為不然，豈意今日身當其衝！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-012-12', 'p0033', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '琰稱疾固辭，由是獲罪，幽於囹圄，賴陰夔、陳琳營救得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-13', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-14', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-021-15', 'p0033', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粹後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-023-16', 'p0033', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-052-17', 'p0033', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '弱冠察孝廉，不就，與朗共論舊君諱事，州里才士陳琳等皆稱善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-053-18', 'p0033', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '陳琳在北見之，以示人曰：「此吾鄉里張子綱所作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0033-a04-053-19', 'p0033', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」後紘見陳琳作武庫賦、應機論，與琳書深歎美之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-012-0', 'p0034', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '庶子劉楨書諫植曰：「家丞邢顒，北土之彥，少秉高節，玄靜澹泊，言少理多，真雅士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-1', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '東平劉楨字公幹並見友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-2', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-3', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '應瑒和而不壯；劉楨壯而不密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-021-4', 'p0034', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '及河北平定，五官將為世子，質與劉楨等並在坐席。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0034-a04-029-5', 'p0034', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '後東平劉楨夢蛇生四足，穴居門中，使宣占之，宣曰：「此為國夢，非君家之事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-0', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '平陵人徐幹素與超同志，上疏願奮身佐超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-1', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '會徐幹適至，超遂與幹擊番辰，大破之，斬首千餘級，多獲生口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-2', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '以徐幹為軍司馬，別遣衞候李邑護送烏孫使者，賜大小昆彌以下錦帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-3', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '徐幹謂超曰：「邑前親毀君，欲敗西域，今何不緣詔書留之，更遣它吏送侍子乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-4', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '明年，龜茲、姑墨、溫宿皆降，乃以超為都護，徐幹為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-047-5', 'p0035', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '超居龜茲它乾城，徐幹屯疏勒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a03-080b-6', 'p0035', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-7', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-8', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0035-a04-021-9', 'p0035', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '而粲特處常伯之官，興一代之制，然其沖虛德宇，未若徐幹之粹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a03-080b-0', 'p0036', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-1', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-2', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0036-a04-021-3', 'p0036', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '應瑒和而不壯；劉楨壯而不密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a03-070-0', 'p0037', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安初，以高第擢拜尚書郎，後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a03-080b-1', 'p0037', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '魏志楨字公幹，為司空軍謀祭酒，五官郎將文學，與徐幹、陳琳、阮瑀、應瑒俱以章知名，轉為平原侯庶子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-2', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粲與北海徐幹字偉長、廣陵陳琳字孔璋、陳留阮瑀字元瑜、汝南應瑒字德璉、瑒，音徒哽反，一音暢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-3', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-021-4', 'p0037', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '粹後為軍謀祭酒，與陳琳、阮瑀等典記室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0037-a04-023-5', 'p0037', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及王粲、陳琳、阮瑀、路粹等亡後，新出之中，惟象才最高。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-0', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '丁儀等見寵於時，並害之，而弈終不為動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-1', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '丁儀方貴重，宜思所以下之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-2', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰、徐弈，一時清賢，皆以忠信顯於魏朝；丁儀間之，徐弈失位而崔琰被誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-3', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏書曰：時丁儀兄弟方進寵，儀與夔不合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-012-4', 'p0039', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '初，太子未定，而臨菑侯植有寵，丁儀等並贊翼其美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-5', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」植旣以才見異，而丁儀、丁廙、楊脩等為之羽翼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-6', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '世語曰：脩年二十五，以名公子有才能，為太祖所器，與丁儀兄弟，皆欲以植為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-7', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '文帝即王位，誅丁儀、丁廙并其男口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-8', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '魏略曰：丁儀字正禮，沛郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-019-9', 'p0039', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '乃令楊脩以倚注遇害，丁儀以希意族滅，哀夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-021-10', 'p0039', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」沛國丁儀、丁廙、弘農楊脩、河內苟緯等，亦有文采，而不在此七人之例。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-021-11', 'p0039', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '廙著書數十篇，及與丁儀共論刑禮，皆傳於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-022-12', 'p0039', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '又毛玠、徐弈以剛蹇少黨，而為西曹掾丁儀所不善，儀屢言其短，賴階左右以自全保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0039-a04-022-13', 'p0039', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '丁儀等為之羽翼，勸臻自結，臻以大義拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a03-035-0', 'p0040', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '其門人山陽郗慮至御史大夫，東萊王基、清河崔琰著名於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-001-1', 'p0040', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-006-2', 'p0040', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '孫盛評曰：案魏武謂崔琰曰「昨案貴州戶籍，可得三十萬衆」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-011-3', 'p0040', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '崔琰為東曹掾，記讓曰：「徵事邴原、議郎張範，皆秉德純懿，志行忠方，清靜足以厲俗，貞固足以幹事，所謂龍翰鳳翼，國之重寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-4', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰字季珪，清河東武城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-5', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '公忿然曰：「崔琰必欲使孤行刀鋸乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-6', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖為司空丞相，玠甞為東曹掾，與崔琰並典選舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-7', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰、徐弈，一時清賢，皆以忠信顯於魏朝；丁儀間之，徐弈失位而崔琰被誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-012-8', 'p0040', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '崔琰高格最優，鮑勛秉正無虧，而皆不免其身，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a04-023-9', 'p0040', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時毛玠、崔琰並以忠清幹事，其選用先尚儉節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0040-a05-001-10', 'p0040', 'jinshu', 'a05-001', '《晉書·卷一》', '尚書清河崔琰與帝兄朗善，亦謂朗曰：「君弟聰亮明允，剛斷英特，非子所及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-001-0', 'p0041', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-001-1', 'p0041', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏氏春秋曰：以荀攸為尚書令，涼茂為僕射，毛玠、崔琰、常林、徐奕、何夔為尚書，王粲、杜襲、衞覬、和洽為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-002-2', 'p0041', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '丁亥令曰：「故尚書僕射毛玠、奉常王脩、涼茂、郎中令袁渙、少府謝奐、萬潛、中尉徐奕、國淵等，皆忠直在朝，履蹈仁義，並早即世，而子孫陵遲，惻然愍之，其皆拜子男為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-3', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '毛玠字孝先，陳留平丘人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-4', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '尚書傅巽謂夔曰：「人不相好已甚，子友毛玠，玠等儀已害之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-012-5', 'p0041', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '毛玠清公素履，司馬芝忠亮不傾，庶乎不吐剛茹柔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-022-6', 'p0041', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '又毛玠、徐弈以剛蹇少黨，而為西曹掾丁儀所不善，儀屢言其短，賴階左右以自全保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-023-7', 'p0041', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時毛玠、崔琰並以忠清幹事，其選用先尚儉節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0041-a04-023-8', 'p0041', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏國旣建，為侍中，後有白毛玠謗毀太祖，太祖見近臣，怒甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-070-0', 'p0042', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '將軍本以兖州首事，故能平定山東，曹操初從東郡守鮑信等迎領兖州牧，遂進兵破黃巾等，故能平定山東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-074-1', 'p0042', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '及卓將兵至，騎都尉太山鮑信說紹曰：魏書曰：「信，太山陽平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a03-074-2', 'p0042', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '濟北相鮑信等同時俱起，衆各數萬，以討卓為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-001-3', 'p0042', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟北相鮑信信事見子勛傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-001-4', 'p0042', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱欲擊之，鮑信諫曰：「今賊衆百萬，百姓皆震恐，士卒無鬬志，不可敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-006-5', 'p0042', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，進遣騎都尉太山鮑信所在募兵，適至，信謂紹曰：「卓擁彊兵，有異志，今不早圖，將為所制；及其初至疲勞，襲之可禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0042-a04-017-6', 'p0042', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '黃巾起，鮑信招合徒衆，禁附從焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a03-074-0', 'p0044', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '蜀志曰：「曹公使張遼及關羽為先鋒，羽望見良麾蓋，策馬刺良萬衆之中，斬其首還，諸將莫能當，遂解白馬圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-1', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張遼、關羽前登，擊破，斬良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-2', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公登高，望虜陳不整，乃縱兵擊之，使張遼為先鋒，虜衆大崩，斬蹋頓及名王已下，胡、漢降者二十餘萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-3', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-4', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，王引軍還，留夏侯惇、曹仁、張遼等屯居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-001-5', 'p0044', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-004-6', 'p0044', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-009-7', 'p0044', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-012-8', 'p0044', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '牟平賊從錢，衆亦數千，夔率郡兵與張遼共討定之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-015-9', 'p0044', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '又語張遼、樂進等曰：「揚州刺史曉達軍事，動靜與共咨議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-015-10', 'p0044', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '一二日必有密書促卿進道，張遼等又將被召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-11', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張遼字文遠，鴈門馬邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-12', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '權甚憚焉，勑諸將：「張遼雖病，不可當也，慎之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-13', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安十一年，太祖表漢帝，稱進及于禁、張遼曰：「武力旣弘，計略周備，質忠信一，守執節義，每臨戰攻，常為督率，奮彊突固，無堅不陷，自援枹鼓，手不知倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-14', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還，留進與張遼、李典屯合肥，增邑五百，并前凡千二百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-15', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-16', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-17', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討柳城，與張遼俱為軍鋒，以功遷平狄將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-18', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '別征東萊，討管承，又與張遼討陳蘭、梅成等，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-017-19', 'p0044', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '或注記有遺漏，未如張遼、徐晃之備詳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-20', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-21', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '張遼之討陳蘭，霸別遣至皖，討吳將韓當，使權不得救蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-018-22', 'p0044', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '霸從討孫權於濡須口，與張遼為前鋒，行遇霖雨，大軍先及，水遂長，賊舩稍進，將士皆不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-023-23', 'p0044', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-023-24', 'p0044', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-025-25', 'p0044', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '毗欲弘廣主意，當舉若張遼之疇，安有於一將之死而可以祖宗為譬哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-027-26', 'p0044', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '將軍張遼與其護軍武周有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-028-27', 'p0044', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文帝踐阼，拜散騎常侍，出為兖州刺史，與張遼等至廣陵討孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-032-28', 'p0044', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布由是遣中郎將高順、北地太守張遼等攻備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-036-29', 'p0044', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '紹遣大將軍顏良攻東郡太守劉延於白馬，曹公使張遼及羽為先鋒擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-036-30', 'p0044', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，曹公壯羽為人，而察其心神無乆留之意，謂張遼曰：「卿試以情問之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-31', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '兵皆就路，權與凌統、甘寧等在津北為魏將張遼所襲，統等以死扞權，權乘駿馬越津橋得去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-32', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '獻帝春秋曰：張遼問吳降人：「向有紫髯將軍，長上短下，便馬善射，是誰？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-047-33', 'p0044', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-054-34', 'p0044', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '旣而張遼至夾石，聞城已拔，乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-054-35', 'p0044', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '師還，遂征合肥，旣徹兵，為張遼等所襲，蒙與淩統以死扞衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-36', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征合肥，魏將張遼襲權於津北，欽力戰有功，遷盪寇將軍，領濡須督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-37', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權曰：「孟德有張遼，孤有興霸，足相敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-38', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '張遼覘望知之，即將步騎奄至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-39', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時權徹軍，前部已發，魏將張遼等奄至津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-055-40', 'p0044', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-056-41', 'p0044', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0044-a04-060-42', 'p0044', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '江表傳曰：權征合肥還，為張遼所掩襲於津北，幾至危殆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-0', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣樂進、李典擊之，幹還守壺關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-1', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋八月，公東征海賊管承，至淳于，遣樂進、李典擊破之，承走入海島。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-001-2', 'p0045', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-004-3', 'p0045', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-006-4', 'p0045', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遣樂進、李典擊之，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-015-5', 'p0045', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '又語張遼、樂進等曰：「揚州刺史曉達軍事，動靜與共咨議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-6', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還許，使遼與樂進拔陰安，徙其民河南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-7', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-8', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '樂進字文謙，陽平衞國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-9', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復與樂進等將步騎五千，擊紹別營，從延津西南緣河至汲、獲嘉二縣，焚燒保聚三十餘屯，斬首獲生各數千，降紹將何茂、王摩等二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-10', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-017-11', 'p0045', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃以巧變為稱，樂進以驍果顯名，而鑒其行事，未副所聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-12', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從圍鄴，鄴定，與樂進圍高幹於壺關，擊管承於長廣，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-13', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-018-14', 'p0045', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與樂進討關羽於尋口，有功，進封延壽亭侯，加討逆將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-023-15', 'p0045', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-032-16', 'p0045', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫氏與孤本為脣齒，又樂進在青泥與關羽相拒，今不往救羽，進必大克，轉侵州界，其憂有甚於魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-035-17', 'p0045', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-047-18', 'p0045', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備、瑜等復追至南郡，曹公遂北還，留曹仁、徐晃於江陵，使樂進守襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0045-a04-047-19', 'p0045', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」遼及樂進相遇，言不早知之，急追自得，舉軍歎恨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a03-076-0', 'p0046', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '數引公卿郎將，列于禁坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a03-095-1', 'p0046', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '中黃門行之，宂從僕射將之，以逐惡鬼于禁中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-001-2', 'p0046', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋八月，公進軍黎陽，使臧霸等入青州破齊、北海、東安，留于禁屯河上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-001-3', 'p0046', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-002-4', 'p0046', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月，孫權遣使奉章，并遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-004-5', 'p0046', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '衮後為于禁司馬，見魏略游說傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-009-6', 'p0046', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '昌狶反，遣于禁擊之，未拔，復遣淵與禁并力，遂擊狶，降其十餘屯，狶詣禁降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-009-7', 'p0046', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '關羽攻樊，時漢水暴溢，于禁等七軍皆沒，禁降羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-013-8', 'p0046', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」肅曰：「昔關羽率荊州之衆，降于禁於漢濵，遂有北向爭天下之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-014-9', 'p0046', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」民有誣告濟為謀叛主率者，太祖聞之，指前令與左將軍于禁、沛相封仁等曰：「蔣濟寧有此事！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-014-10', 'p0046', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '司馬宣王及濟說太祖曰：「于禁等為水所沒，非戰攻之失，於國家大計未足有損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-11', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-12', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安十一年，太祖表漢帝，稱進及于禁、張遼曰：「武力旣弘，計略周備，質忠信一，守執節義，每臨戰攻，常為督率，奮彊突固，無堅不陷，自援枹鼓，手不知倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-13', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '于禁字文則，泰山鉅平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-14', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '會漢水暴隘，于禁等沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-017-15', 'p0046', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '于禁最號毅重，然弗克其終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-018-16', 'p0046', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '」惇不聽，與于禁追之，典留守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-018-17', 'p0046', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '又與于禁討昌豨，與夏侯淵討黃巾餘賊徐和等，有功，遷徐州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-022-18', 'p0046', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時大將軍入于禁中，泰見之悲慟，大將軍亦對之泣，謂曰：「玄伯，其如我何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-023-19', 'p0046', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時于禁屯潁陰，樂進屯陽翟，張遼屯長社，諸將任氣，多共不協；使儼并參三軍，每事訓喻，遂相親睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-023-20', 'p0046', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-026-21', 'p0046', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '關羽圍襄陽，寵助征南將軍曹仁屯樊城拒之，而左將軍于禁等軍以霖雨水長為羽所沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-032-22', 'p0046', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '使拒夏侯惇、于禁等於博望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-032-23', 'p0046', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '時關羽攻曹公將曹仁，禽于禁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-035-24', 'p0046', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-036-25', 'p0046', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽忿其淹遲，又自已得于禁等，乃罵曰：「狢子敢爾，如使樊城拔，吾不能滅汝邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-26', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二十四年，關羽圍曹仁於襄陽，曹公遣左將軍于禁救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-27', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙據江陵，撫其老弱，釋于禁之囚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-28', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」自魏文帝踐阼，權使命稱藩，及遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-29', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-30', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '先帝知權姦以求用，時以于禁敗於水災，等當討羽，因以委權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-31', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後領護于禁軍，軍沒，為關羽所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-047-32', 'p0046', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」初東里衮為于禁軍司馬，前與周俱沒，又俱還到，有詔皆見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-054-33', 'p0046', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魏使于禁救樊，羽盡禽禁等，人馬數萬，託以糧乏，擅取湘關米。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-057-34', 'p0046', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '魏將于禁為羽所獲，繫在城中，權至釋之，請與相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a04-058-35', 'p0046', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '」又曰：「于禁等見獲，遐邇欣歎，以為將軍之勳足以長世，雖昔晉文城濮之師，淮陰拔趙之略，蔑以尚茲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-001-36', 'p0046', 'jinshu', 'a05-001', '《晉書·卷一》', '及蜀將關羽圍曹仁於樊，于禁等七軍皆沒，脩、方果降羽，而仁圍甚急焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-037-37', 'p0046', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時孫權稱藩，請送任子，當遣前將軍于禁還，久而不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0046-a05-037-38', 'p0046', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '權雖未送任子，于禁不至，猶宜以寬待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a03-074-0', 'p0047', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」乃使高覽、張郃等攻操營，不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a03-074-1', 'p0047', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏志曰：「張郃字儁文，河閒鄚人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-2', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」乃使張郃、高覽攻曹洪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-3', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張郃等見事急，共引公入船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-4', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，公西征張魯，至陳倉，將自武都入氐；氐人塞道，先遣張郃、朱靈等攻破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-001-5', 'p0047', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-002-6', 'p0047', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '中軍、征南攻圍江陵，左將軍張郃等舳艫直渡，擊其南渚，賊赴水溺死者數千人，又為地道攻城，城中外雀鼠不得出入，此几上肉耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-003-7', 'p0047', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '右將軍張郃擊亮於街亭，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-004-8', 'p0047', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-006-9', 'p0047', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖還，未至營，紹將高覽、張郃等率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-10', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」遂行，使張郃督步騎五千在前，從陳倉狹道入，淵自督糧在後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-11', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '淵別遣張郃等平河關，渡河入小湟中，河西諸羌盡降，隴右平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-12', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '會魯降，漢中平，以淵行都護將軍，督張郃、徐晃等平巴郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-13', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '淵使張郃護東圍，自將輕兵護南圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-009-14', 'p0047', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝遣真督諸軍軍郿，遣張郃擊亮將馬謖，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-010-15', 'p0047', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '紹將張郃、高覽燒攻櫓降，紹遂棄軍走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-16', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-17', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-18', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-19', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃字儁乂，河閒鄚人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-20', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-017-21', 'p0047', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '張郃以巧變為稱，樂進以驍果顯名，而鑒其行事，未副所聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-023-22', 'p0047', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲與張郃、郭淮糾攝諸軍事，權宜以郃為督，以一衆心，三軍遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-023-23', 'p0047', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-025-24', 'p0047', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '張郃追之，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-025-25', 'p0047', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '今國內所少，豈張郃乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-26', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '淵遇害，軍中擾擾，淮收散卒，推盪寇將軍張郃為軍主，諸營乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-27', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '又行征羌護軍，護左將軍張郃、冠軍將軍楊秋討山賊鄭甘、盧水叛胡，皆破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-026-28', 'p0047', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '張郃擊謖，淮攻詳營，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-032-29', 'p0047', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公使夏侯淵、張郃屯漢中，數數犯暴巴界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-033-30', 'p0047', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '八年秋，魏使司馬懿由西城，張郃由子午，曹真由斜谷，斜，余奢反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-033-31', 'p0047', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏司馬懿、張郃救祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-32', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '及至孟德，以其譎勝之力，舉數十萬之師，救張郃於陽平，勢窮慮悔，僅能自脫，辱其鋒銳之衆，遂喪漢中之地，深知神器不可妄獲，旋還未至，感毒而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-33', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏明帝西鎮長安，命張郃拒亮，亮使馬謖督諸軍在前，與郃戰于街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-34', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃使西屯長安，督張郃、費曜、戴陵、郭淮等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-35', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '張郃曰：「彼遠來逆我，請戰不得，謂我利在不戰，欲以長計制之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-36', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '五月辛巳，乃使張郃攻无當監何平於南圍，自案中道向亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-37', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '糧盡退軍，與魏將張郃交戰，射殺郃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-38', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭沖五事曰：魏明帝自征蜀，幸長安，遣宣王督張郃諸軍，雍、涼勁卒三十餘萬，潛軍密進，規向劒閣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-035-39', 'p0047', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」臨戰之日，莫不拔刃爭先，以一當十，殺張郃，却宣王，一戰大剋，此信之由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-036-40', 'p0047', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-037-41', 'p0047', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-039-42', 'p0047', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建興六年，亮出軍向祁山，時有宿將魏延、吳壹等，論者皆言以為宜令為先鋒，而亮違衆拔謖，統大衆在前，與魏將張郃戰于街亭，為郃所破，士卒離散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-040-43', 'p0047', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '旣亡漢中，使夏侯淵、張郃深入于巴，幾喪一州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-043-44', 'p0047', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '衆盡星散，惟平所領千人，鳴鼓自持，魏將張郃疑其伏兵，不往偪也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-043-45', 'p0047', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魏大將軍司馬宣王攻亮，張郃攻平，平堅守不動，郃不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-044-46', 'p0047', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '未及遣迎兾中人，會亮前鋒為張郃、費繇等所破，遂將維等却縮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-047-47', 'p0047', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a04-056-48', 'p0047', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏遣曹真、夏侯尚、張郃等攻江陵，魏文帝自住宛，為其勢援，連屯圍城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-001-49', 'p0047', 'jinshu', 'a05-001', '《晉書·卷一》', '」乃使帝西屯長安，都督雍、梁二州諸軍事，統車騎將軍張郃、後將軍費曜、征蜀護軍戴淩、雍州刺史郭淮等討亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-001-50', 'p0047', 'jinshu', 'a05-001', '《晉書·卷一》', '張郃勸帝分軍住雍、郿為後鎮，帝曰：「料前軍獨能當之者，將軍言是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0047-a05-013-51', 'p0047', 'jinshu', 'a05-013', '《晉書·卷十三》', '」其七月，車騎將軍張郃追諸葛亮，為亮所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-0', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹若有十倍之衆，理應當悉力圍守，使出入斷絕，而公使徐晃等擊其運車，公又自出擊淳于瓊等，揚旌往還，曾無抵閡，明紹力不能制，是不得甚少，二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-1', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-2', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太原商曜等以大陵叛，遣夏侯淵、徐晃圍破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-3', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公急持之，而潛遣徐晃、朱靈等夜渡蒲阪津，據河西為營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-001-4', 'p0048', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '知人善察，難眩以偽，拔于禁、樂進於行陣之間，取張遼、徐晃於亡虜之內，皆佐命立功，列為名將；其餘拔出細微，登為牧守者，不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-004-5', 'p0048', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-6', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征孫權還，使淵督諸將擊廬江叛者雷緒，緒破，又行征西護軍，督徐晃擊太原賊，攻下二十餘屯，斬賊帥商曜，屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-7', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '會魯降，漢中平，以淵行都護將軍，督張郃、徐晃等平巴郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-8', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '徐晃救至，水亦稍減，晃從外擊羽，仁得潰圍出，羽退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-9', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '仁與徐晃攻破邵，遂入襄陽，使將軍高遷等徙漢南附化民於漢北，文帝遣使即拜仁大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-009-10', 'p0048', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以真為征蜀護軍，督徐晃等破劉備別將高詳於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-014-11', 'p0048', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」即勑救將徐晃以權書射著圍裏及羽屯中，圍裏聞之，志氣百倍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-12', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遼未至，徐晃已破關羽，仁圍解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-13', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '是時，禁與張遼、樂進、張郃、徐晃俱為名將，太祖每征伐，咸遞行為軍鋒，還為後拒；而禁持軍嚴整，得賊財物，無所私入，由是賞賜特重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-14', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '徐晃字公明，河東楊人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-017-15', 'p0048', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '或注記有遺漏，未如張遼、徐晃之備詳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-022-16', 'p0048', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹仁為關羽所圍，太祖遣徐晃救之，不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-023-17', 'p0048', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '儼以議郎參仁軍事南行，與平寇將軍徐晃俱前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-026-18', 'p0048', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '會徐晃等救至，寵力戰有功，羽遂退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-035-19', 'p0048', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '羽圍襄陽，將降曹仁，生獲于禁，當時北邊大小憂懼，孟德身出南陽，樂進、徐晃等為救，圍不即解，故蔣子通言彼時有徙許渡河之計，會國家襲取南郡，羽乃解軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-036-20', 'p0048', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '而曹公遣徐晃救曹仁，蜀記曰：羽與晃宿相愛，遙共語，但說平生，不及軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-040-21', 'p0048', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '遣征南將軍夏侯尚、右將軍徐晃與達共襲封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-047-22', 'p0048', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備、瑜等復追至南郡，曹公遂北還，留曹仁、徐晃於江陵，使樂進守襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-047-23', 'p0048', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0048-a04-058-24', 'p0048', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '聞徐晃等步騎駐旌，闚望麾葆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-0', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣樂進、李典擊之，幹還守壺關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-1', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋八月，公東征海賊管承，至淳于，遣樂進、李典擊破之，承走入海島。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-001-2', 'p0049', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-004-3', 'p0049', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-006-4', 'p0049', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遣樂進、李典擊之，未拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-5', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-6', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征管承，軍淳于，遣進與李典擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-017-7', 'p0049', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還，留進與張遼、李典屯合肥，增邑五百，并前凡千二百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-018-8', 'p0049', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李典字曼成，山陽鉅野人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-018-9', 'p0049', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '評曰：李典貴尚儒雅，義忘私隙，美矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0049-a04-023-10', 'p0049', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖征荊州，以儼領章陵太守，徙都督護軍，護于禁、張遼、張郃、朱靈、李典、路招、馮楷七軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-001-0', 'p0050', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '宛人李通等以圖讖說光武云：「劉氏復起，李氏為輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-001-1', 'p0050', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '十月，與李通從弟軼等起於宛，時年二十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-011-2', 'p0050', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始乃先封宗室太常將軍劉祉為定陶王，劉賜為宛王，劉慶為燕王，劉歙為元氏王，大將軍劉嘉為漢中王，劉信為汝陰王；後遂立王匡為比陽王，王鳳為宜城王，朱鮪為膠東王，衞尉大將軍張卬為淮陽王，廷尉大將軍王常為鄧王，執金吾大將軍廖湛為穰王，申屠建為平氏王，尚書胡殷為隨王，柱天大將軍李通為西平王，西平，縣，屬汝南郡，故城在今豫州郾城縣南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-011-3', 'p0050', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '乃徙鮪為左大司馬，劉賜為前大司馬，使與李軼、李通、王常等鎮撫關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-014-4', 'p0050', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '於是分遣親客，使鄧晨起新野，光武與李通、李軼起於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-5', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通　王常　鄧晨　來歙　歷伯珍');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-6', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通字次元，南陽宛人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-7', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '續漢書曰：「先是李通同母弟申徒臣能為醫，難使，伯升殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-8', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '李通豈知夫所欲而未識以道者乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-9', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '伯升聞下江軍在宜秋，即與光武及李通俱造常壁，曰：「願見下江一賢將，議大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-015-10', 'p0050', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '鄧晨代以吏二千石為豪，李通家富為贍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-017-11', 'p0050', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '是時列侯唯高密、固始、膠東三侯與公卿參議國家大事，高密侯鄧禹，固始侯李通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-021-12', 'p0050', 'houhanshu', 'a03-021', '《後漢書·卷二十一》', '八年，東郡、濟陰盜賊羣起，遣大司空李通、橫野大將軍王常擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-13', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '明年，大司空李通罷，以成行大司空事，居府如真，數月復拜揚武將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-14', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '永平中，顯宗追感前世功臣，乃圖畫二十八將於南宮雲臺，其外又有王常、李通、竇融、卓茂，合三十二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-022-15', 'p0050', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '太傅高密侯鄧禹　                   中山太守全椒侯馬成                   大司馬廣平侯吳漢                   河南尹阜成侯王梁                   左將軍膠東侯賈復                   琅邪太守祝阿侯陳俊                   建威大將軍好畤侯耿弇                   驃騎大將軍參蘧侯杜茂                   執金吾雍奴侯寇恂                   積弩將軍昆陽侯傅俊                   征南大將軍舞陽侯岑彭                   左曹合肥侯堅鐔                   征西大將軍陽夏侯馮異                   上谷太守淮陽侯王霸                   建義大將軍鬲侯朱祐                   信都太守阿陵侯任光                   征虜將軍潁陽侯祭遵                   豫章太守中水侯李忠                   驃騎大將軍櫟陽侯景丹                   右將軍槐里侯萬脩                   虎牙大將軍安平侯蓋延                   太常靈壽侯邳彤                   衞尉安成侯銚期                   驍騎將軍昌成侯劉植                   東郡太守東光侯耿純                   橫野大將軍山桑侯王常                   城門校尉朗陵侯臧宮                   大司空固始侯李通                   捕虜將軍楊虛侯馬武                   大司空安豐侯竇融                   驃騎將軍慎侯劉隆                   太傅宣德侯卓茂');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-036-16', 'p0050', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '元以才高著名，辟司空李通府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-036-17', 'p0050', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '李通罷，元後復辟司徒歐陽歙府，數陳當世便事、郊廟之禮，帝不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a03-070-18', 'p0050', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '若要離焚妻子以徇吳，李通誅宗族以從漢之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-19', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通字文達，江夏平春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-20', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '昔樂羊食子，李通覆家，經國之臣，寧懷妻孥邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-018-21', 'p0050', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-023-22', 'p0050', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '惟陽安郡不動，而都尉李通急錄戶調。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-023-23', 'p0050', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '儼與領陽安太守李通同治，通亦欲遣使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0050-a04-042-24', 'p0050', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '益部耆舊傳曰：益州刺史董榮圖畫周像於州學，命從事李通頌之曰：「抑抑譙侯，好古述儒，寶道懷真，鑒世盈虛，雅名美迹，終始是書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a03-075-0', 'p0051', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時太山臧霸等攻破莒城，許布財幣以相結，而未及送，布乃自往求之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-001-1', 'p0051', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太山臧霸、孫觀、吳敦、尹禮、昌狶各聚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-001-2', 'p0051', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋八月，公進軍黎陽，使臧霸等入青州破齊、北海、東安，留于禁屯河上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-003-3', 'p0051', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏書曰：行過繁昌，使執金吾臧霸行太尉事，以特牛祠受禪壇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-004-4', 'p0051', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-007-5', 'p0051', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建尋為臧霸所襲破，得建資實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-010-6', 'p0051', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」比行，布以敗劉備，而臧霸等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-014-7', 'p0051', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臧霸等旣富且貴，無復他望，但欲終其天年，保守祿祚而已，何肯乘危自投死地，以求徼倖？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-015-8', 'p0051', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安二十二年，與夏侯惇、臧霸等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-017-9', 'p0051', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '陳蘭、梅成以氐六縣叛，太祖遣于禁、臧霸等討成，遼督張郃、牛蓋等討蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-017-10', 'p0051', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後與臧霸等攻梅成，張遼、張郃等討陳蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-11', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸字宣高，泰山華人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-12', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與臧霸俱起，討黃巾，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-13', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸少有孝烈之稱，文聘著垂泣之誠，是以魏武一面，委之以二方之任，豈直壯武見知於倉卒之間哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-018-14', 'p0051', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-047-15', 'p0051', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏乃命曹休、張遼、臧霸出洞口，曹仁出濡須，曹真、夏侯尚、張郃、徐晃圍南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-047-16', 'p0051', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '曹休使臧霸以輕船五百、敢死萬人襲攻徐陵，燒攻城車，殺略數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a04-056-17', 'p0051', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0051-a05-019-18', 'p0051', 'jinshu', 'a05-019', '《晉書·卷十九》', '四年八月，天子東巡，過繁昌，使執金吾臧霸行太尉事，以特牛祠受禪壇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-001-0', 'p0052', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-003-1', 'p0052', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '八月，孫權攻江夏郡，太守文聘堅守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-004-2', 'p0052', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-011-3', 'p0052', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '魏略純固傳以脂習、王脩、龐淯、文聘、成公英、郭憲、單固七人為一傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-4', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '文聘字仲業，南陽宛人也，為劉表大將，使禦北方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-5', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '臧霸少有孝烈之稱，文聘著垂泣之誠，是以魏武一面，委之以二方之任，豈直壯武見知於倉卒之間哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-018-6', 'p0052', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '李通、臧霸、文聘、呂虔鎮衞州郡，並著威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0052-a04-058-7', 'p0052', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '兼領兵馬，頗作邊害，而與北舊將文聘子休宿不協。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-004-0', 'p0053', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '徐佗謀逆而許褚心動，忠誠之至遠同於日磾，且潼關之危，非褚不濟，褚之功烈有過典韋，今祀韋而不及褚，文所未達也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-008-1', 'p0053', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '武皇帝意沮，便欲拔軍截山而還，遣故大將軍夏侯惇、將軍許褚呼山上兵還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-018-2', 'p0053', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚字仲康，譙國譙人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-018-3', 'p0053', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚、典韋折衝左右，抑亦漢之樊噲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-028-4', 'p0053', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '儀者，許褚之子，有功王室，猶不原貸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0053-a04-036-5', 'p0053', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公與遂、超單馬會語，超負其多力，陰欲突前捉曹公，曹公左右將許褚瞋目眄之，超乃不敢動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-004-0', 'p0054', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-004-1', 'p0054', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '徐佗謀逆而許褚心動，忠誠之至遠同於日磾，且潼關之危，非褚不濟，褚之功烈有過典韋，今祀韋而不及褚，文所未達也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0054-a04-018-2', 'p0054', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '許褚、典韋折衝左右，抑亦漢之樊噲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-004-0', 'p0055', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，詔祀故大司馬曹真、曹休、征南大將軍夏侯尚、太常桓階、司空陳羣、太傅鍾繇、車騎將軍張郃、左將軍徐晃、前將軍張遼、右將軍樂進、太尉華歆、司徒王朗、驃騎將軍曹洪、征西將軍夏侯淵、後將軍朱靈、文聘、執金吾臧霸、破虜將軍李典、立義將軍龐德、武猛校尉典韋於太祖廟庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-1', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '禁降羽，羽又斬將軍龐德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-2', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：龐德子會，隨鍾、鄧伐蜀，蜀破，盡滅關氏家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-036-3', 'p0055', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '騰遣超隨繇討郭援、高幹於平陽，超將龐德親斬援首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0055-a04-037-4', 'p0055', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '襄陽記曰：諸葛孔明為卧龍，龐士元為鳳雛，司馬德操為水鏡，皆龐德公語也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-003-0', 'p0056', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '六月，征東將軍滿寵進軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-004-1', 'p0056', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」三月，以征東將軍滿寵為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-014-2', 'p0056', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '邊候得權書，放乃改易其辭，往往換其本文而傅合之，與征東將軍滿寵，若欲歸化，封以示亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-014-3', 'p0056', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '如征東將軍滿寵、涼州刺史徐邈，並有譖毀之者，資皆盛陳其素行，使卒無纖介。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-015-4', 'p0056', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和二年，帝使逵督前將軍滿寵、東莞太守胡質等四軍，從西陽直向東關，曹休從皖，司馬宣王從江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-017-5', 'p0056', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-021-6', 'p0056', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '青龍中，吳圍合肥，時東方吏士皆分休，征東將軍滿寵表請中軍兵，并召休將士，須集擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-7', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '滿寵字伯寧，山陽昌邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-8', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後孫權號十萬衆攻新城，征東將軍滿寵欲率諸軍救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a04-026-9', 'p0056', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '評曰：滿寵立志剛毅，勇而有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0056-a05-013-10', 'p0056', 'jinshu', 'a05-013', '《晉書·卷十三》', '」三年三月，太尉滿寵薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-003-0', 'p0057', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '冬十月，殄夷將軍田豫帥衆討吴將周賀於成山，殺賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-1', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '司馬彪戰略曰：太和六年，明帝遣平州刺史田豫乘海渡，幽州刺史王雄陸道，并攻遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-2', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏氏春秋曰：烏丸校尉田豫帥西部鮮卑泄歸尼等出塞，討軻比能、智鬱築鞬，破之，還至馬邑故城，比能帥三萬騎圍豫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-3', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '鄉人司空掾田豫、梁相宗豔皆妬害之，而楊豐黨附豫等，專為資構造謗端，怨隙甚重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-014-4', 'p0057', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及當顯位，而田豫老疾在家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-019-5', 'p0057', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '用田豫計，固守要隙，虜乃退散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-6', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '田豫字國讓，漁陽雍奴人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-7', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，護烏丸校尉田豫出塞，為軻比能所圍於故馬邑城，移招求救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-8', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '其治邊之稱，次於田豫，百姓追思之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-026-9', 'p0057', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '田豫居身清白，規畧明練。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-027-10', 'p0057', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-028-11', 'p0057', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '烏丸校尉田豫討胡有功，小違節度，愚以法繩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-12', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '田豫有馬城之圍，畢軌有陘北之敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-13', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '文帝踐阼，田豫為烏丸校尉，持節并護鮮卑，屯昌平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-030-14', 'p0057', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '田豫和合，使不得相侵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0057-a04-047-15', 'p0057', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，魏將田豫要擊，斬賀于成山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-003-0', 'p0058', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '雍州刺史郭淮遣廣魏太守王贇、南安太守游弈將兵討惇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-1', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年夏五月，以征西將軍郭淮為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-2', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃使郭淮、陳泰悉關中之衆，解狄道之圍；勑毌丘儉等案兵自守，以新城委吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-004-3', 'p0058', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，車騎將軍郭淮薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-009-4', 'p0058', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '霸聞曹爽被誅而玄又徵，以為禍必轉相及，心旣內恐；又霸先與雍州刺史郭淮不和，而淮代玄為征西，霸尤不安，故遂奔蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-011-5', 'p0058', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '車騎將軍郭淮以意氣呼之，問其所欲，亦不肯言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-017-6', 'p0058', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '淵司馬郭淮乃令衆曰：「張將軍，國家名將，劉備所憚；今日事急，非張將軍不能安也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-022-7', 'p0058', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '嘉平初，代郭淮為雍州刺史，加奮威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-022-8', 'p0058', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '征西將軍郭淮與泰謀所以禦之，泰曰：「麴城雖固，去蜀險遠，當須運糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-023-9', 'p0058', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲與張郃、郭淮糾攝諸軍事，權宜以郃為督，以一衆心，三軍遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-026-10', 'p0058', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '郭淮字伯濟，太原陽曲人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-026-11', 'p0058', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '郭淮方策精詳，垂問秦、雍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-12', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽與郭淮書曰：「大將軍昭伯與太傅俱受顧命，登牀把臂，託付天下，此遠近所知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-13', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」時郭淮已卒，欽未知，故有此書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-14', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '前與毌丘儉、郭淮等俱舉義兵，當共討師，埽除凶孽，誠臣慺慺愚管所執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-028-15', 'p0058', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '嘉平元年，與征西將軍郭淮拒蜀偏將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-033-16', 'p0058', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，魏延破魏雍州刺史郭淮于陽谿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-17', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏雍州刺史郭淮率衆欲擊戒，亮自出至建威，淮退還，遂平二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-18', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '前年耀師，馘斬王雙；今歲爰征，郭淮遁走；降集氐、羌，興復二郡，威鎮凶暴，功勳顯然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-19', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃使西屯長安，督張郃、費曜、戴陵、郭淮等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-035-20', 'p0058', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭淮、費曜等徼亮，亮破之，因大芟刈其麥，與宣王遇于上邽之東，斂兵依險，軍不得交，亮引而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-040-21', 'p0058', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '五年，諸葛亮駐漢中，更以延為督前部，領丞相司馬、涼州刺史，八年，使延西入羌中，魏後將軍費瑤、雍州刺史郭淮與延戰于陽谿，延大破淮等，遷為前軍師征西大將軍，假節，進封南鄭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-22', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-23', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏略曰：天水太守馬遵將維及諸官屬隨雍州刺史郭淮偶自西至洛門案行，會聞亮已到祁山，淮顧遵曰：「是欲不善！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a04-044-24', 'p0058', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '又出隴西、南安、金城界，與魏大將軍郭淮、夏侯霸等戰於洮西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-001-25', 'p0058', 'jinshu', 'a05-001', '《晉書·卷一》', '」乃使帝西屯長安，都督雍、梁二州諸軍事，統車騎將軍張郃、後將軍費曜、征蜀護軍戴淩、雍州刺史郭淮等討亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-001-26', 'p0058', 'jinshu', 'a05-001', '《晉書·卷一》', '」遣將軍胡遵、雍州刺史郭淮共備陽遂，與亮會于積石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-002-27', 'p0058', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維之寇隴右也，征西將軍郭淮自長安距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0058-a05-013-28', 'p0058', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀將姜維攻隴西，車騎將軍郭淮討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-0', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '文帝初，北狄彊盛，侵擾邊塞，乃使豫持節護烏丸校尉，牽招、解儁并護鮮卑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-1', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '牽招字子經，安平觀津人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0059-a04-026-2', 'p0059', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '牽招秉義壯烈，威績顯著。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-001-0', 'p0060', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '尚攻之急，譚遣辛毗乞降請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-002-1', 'p0060', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」　魏王侍中劉廙、辛毗、劉曄、尚書令桓階、尚書陳矯、陳羣、給事黃門侍郎王毖、董遇等言：「臣伏讀左中郎將李伏上事，考圖緯之言，以效神明之應，稽之古代，未有不然者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-002-2', 'p0060', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」於是侍中辛毗、劉曄、散騎常侍傅巽、衞臻、尚書令桓階、尚書陳矯、陳羣、給事中博士騎都尉蘇林、董巴等奏曰：「伏見太史丞許芝上魏國受命之符；令書懇切，允執謙讓，雖舜、禹、湯、文，義無以過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-003-3', 'p0060', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '宣王將出戰，辛毗杖節奉詔，勒宣王及軍吏已下，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-4', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚攻之急，譚遣辛毗詣太祖請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-5', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-6', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是時，辛毗在軍，聞門開，馳走詣獄，欲解其兄家，兄家已死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-7', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是日生縛配，將詣帳下，辛毗等逆以馬鞭擊其頭，罵之曰：「奴，汝今日真死矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-006-8', 'p0060', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '配旣無撓辭，而辛毗等號哭不已，乃殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-008-9', 'p0060', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '侍中辛毗、劉曄等在兵後，語惇、褚，言『官兵已據得賊要屯，賊已散走』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-010-10', 'p0060', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前後所舉者，命世大才，邦邑則荀攸、鍾繇、陳羣，海內則司馬宣王，及引致當世知名郗慮、華歆、王朗、荀恱、杜襲、辛毗、趙儼之儔，終為卿相，以十數人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-010-11', 'p0060', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '譚遣辛毗乞降請救，太祖將許之，以問羣下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-012-12', 'p0060', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-014-13', 'p0060', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '譚為尚軍所敗，走保平原，遣辛毗乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-014-14', 'p0060', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '放、資旣善承順主上，又未嘗顯言得失，抑辛毗而助王思，以是獲譏於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-016-15', 'p0060', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '每政有得失，常引綱維以正言，於是侍中辛毗等器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-023-16', 'p0060', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '初，儼與同郡辛毗、陳羣、杜襲並知名，號曰辛、陳、杜、趙云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-024-17', 'p0060', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '魏名臣奏載侍中辛毗奏曰：「昔桓階為尚書令，以崔林非尚書才，遷以為河間太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-18', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '辛毗字佐治，潁川陽翟人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-19', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」宂從僕射畢軌表言：「尚書僕射王思精勤舊吏，忠亮計略不如辛毗，毗宜代思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-20', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」陳羣曰：「亦誠如辛毗言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-025-21', 'p0060', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '評曰：辛毗、楊阜，剛亮公直，正諫匪躬，亞乎汲黯之高風焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-035-22', 'p0060', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '使衞尉辛毗持節以制之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a04-047-23', 'p0060', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '魏乃遣侍中辛毗、尚書桓階往與盟誓，并徵任子，權辭讓不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a05-001-24', 'p0060', 'jinshu', 'a05-001', '《晉書·卷一》', '帝怒，表請決戰，天子不許，乃遣骨鯁臣衞尉辛毗杖節為軍師以制之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0060-a05-001-25', 'p0060', 'jinshu', 'a05-001', '《晉書·卷一》', '初，蜀將姜維聞毗來，謂亮曰：「辛毗杖節而至，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a03-072-0', 'p0061', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '十九年，天水人楊阜破超，魏志曰：「阜字義山，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-003-1', 'p0061', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '百姓失農時，直臣楊阜、高堂隆等各數切諫，雖不能聽，常優容之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-005-2', 'p0061', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '陳羣雖抗言，楊阜引事比並，然皆不能極陳先王之禮，明封建繼嗣之義，忠至之辭，猶有闕乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-015-3', 'p0061', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '旣臨二州十餘年，政惠著聞，其所禮辟扶風龐延、天水楊阜、安定胡遵、酒泉龐淯、燉煌張恭、周生烈等，終皆有名位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-022-4', 'p0061', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '袁子曰：或云「故少府楊阜豈非忠臣哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-5', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '楊阜字義山，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-6', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '叙姑子楊阜，故為康從事，同等十餘人，皆略屬超，陰相結為康報仇，未有閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-7', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及昂與楊阜等結謀討超，告異曰：「吾謀如是，事必萬全，當柰月何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-025-8', 'p0061', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '評曰：辛毗、楊阜，剛亮公直，正諫匪躬，亞乎汲黯之高風焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-036-9', 'p0061', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '楊阜說曹公曰：「超有信、布之勇，甚得羌、胡心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0061-a04-036-10', 'p0061', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '康故吏民楊阜、姜叙、梁寬、趙衢等合謀擊超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-0', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '八月丁卯，以太常高柔為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-1', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月，以司空高柔為司徒；光祿大夫徐邈為司空，固辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-2', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '使兼太尉高柔奉策，用一元大武告于宗廟，遣芳歸藩于齊，以避皇位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-004-3', 'p0062', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九月，以司徒高柔為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-011-4', 'p0062', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，脩識高柔於弱冠，異王基於幼童，終皆遠至，世稱其知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-012-5', 'p0062', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」太尉鍾繇、司徒華歆、鎮軍大將軍陳羣、侍中辛毗、尚書衞臻、守廷尉高柔等並表「勛父信有功於太祖」，求請勛罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-024-6', 'p0062', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '高柔字文惠，陳留圉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a04-024-7', 'p0062', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-001-8', 'p0062', 'jinshu', 'a05-001', '《晉書·卷一》', '」於是假司徒高柔節，行大將軍事，領爽營，謂柔曰：「君為周勃矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-002-9', 'p0062', 'jinshu', 'a05-002', '《晉書·卷二》', '二年秋八月甲寅，天子使太尉高柔授帝相國印綬，司空鄭沖致晉公茅土九錫，固辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0062-a05-039-10', 'p0062', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '前渤海太守劉亮、從子北海太守搏、司空掾高柔並切諫，浚怒，誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-004-0', 'p0063', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚子，以司隷校尉孫禮為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-010-1', 'p0063', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」詡遂往，繡執子孫禮，煨果善視其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-012-2', 'p0063', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」涿郡孫禮、盧毓始入軍府，琰又名之曰：「孫疏亮亢烈，剛簡能斷，盧清警明理，百鍊不消，皆公才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-012-3', 'p0063', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '高密鄭玄，稱之鄭公，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-016-4', 'p0063', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '畿為尚書僕射，二人各脩子孫禮見畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-022-5', 'p0063', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '寔之亡也，司空荀爽、太僕令韓融並制緦麻，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-024-6', 'p0063', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '孫禮字德達，涿郡容城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-024-7', 'p0063', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0063-a04-027-8', 'p0063', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '邈同郡韓觀曼遊，有鑒識器幹，與邈齊名，而在孫禮、盧毓先，為豫州刺史，甚有治功，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0064-a04-001-0', 'p0064', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0064-a04-027-1', 'p0064', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '是時青土初定，刺史王凌特表請基為別駕，後召為秘書郎，凌復請還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a03-085-0', 'p0065', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '魏志曰，毌丘儉遣王頎追句驪王宮，窮沃沮東界，問其耆老所傳云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-003-1', 'p0065', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '遣幽州刺史毌丘儉率諸軍及鮮卑、烏丸屯遼東南界，璽書徵公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-003-2', 'p0065', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」毌丘儉志記云，時以儉為宣王副也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-3', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '七年春二月，幽州刺史毌丘儉討高句驪，夏五月，討濊貊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-4', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月，詔征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-5', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：毌丘儉、王昶聞東軍敗，各燒屯走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-6', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃使郭淮、陳泰悉關中之衆，解狄道之圍；勑毌丘儉等案兵自守，以新城委吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-7', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '會毌丘儉代誕，遂使特屯守合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-8', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '六年春二月己丑，鎮東將軍毌丘儉上言：「昔諸葛恪圍合肥新城，城中遣士劉整出圍傳消息，為賊所得，考問所傳，語整曰：『諸葛公欲活汝，汝可具服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-004-9', 'p0065', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年春正月乙丑，鎮東將軍毌丘儉、楊州刺史文欽反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-005-10', 'p0065', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '毌丘儉、鍾會等作亂，咸假其命而以為辭焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-008-11', 'p0065', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '景初元年，乃遣幽州刺史毌丘儉等齎璽書徵淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-012-12', 'p0065', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時毌丘儉孫女適劉氏，以孕繫廷尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-013-13', 'p0065', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '正元中，毌丘儉、文欽反，毓持節至揚、豫州班行赦令，告諭士民，還為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-013-14', 'p0065', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」明年春，鎮東將軍毌丘儉、揚州刺史文欽反，景王謂肅曰：「霍光感夏侯勝之言，始重儒學之士，良有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-014-15', 'p0065', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '干寶晉紀曰：毌丘儉之起也，大將軍以問陶，陶荅依違。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-16', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '世語曰：毌丘儉反，康有力，且欲起兵應之，以問山濤，濤曰：「不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-17', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '蓋緣世語云康欲舉兵應毌丘儉，故謂破儉便應殺康也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-18', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '尋文王以景元四年鍾、鄧平蜀後，始授相國位；若巽為相國掾時陷安，焉得以破毌丘儉年殺嵇、呂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-19', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '摯與毌丘儉鄉里相親，故為詩與儉，求仙人藥一丸，欲以感切儉求助也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-20', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等表請征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-021-21', 'p0065', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正元二年春，毌丘儉、文欽作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-022-22', 'p0065', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '幽州刺史毌丘儉上疏曰：「陛下即位已來，未有可書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-022-23', 'p0065', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '毌丘儉作亂，大將軍司馬景王出征，毓綱紀後事，加侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-027-24', 'p0065', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，引兵拒儉、欽有功，封二子亭侯、關內侯，進位驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-027-25', 'p0065', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，以基為行監軍、假節，統許昌軍，適與景王會於許昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-26', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉字仲恭，河東聞喜人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-27', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：毌丘儉之誅，黨與七百餘人，傳侍御史杜友治獄，惟舉首事十人，餘皆奏散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-28', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '習鑿齒曰：毌丘儉感明帝之顧命，故為此役。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-29', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '君子謂毌丘儉事雖不成，可謂忠臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-30', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」若毌丘儉可謂能不愧也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-31', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '前與毌丘儉、郭淮等俱舉義兵，當共討師，埽除凶孽，誠臣慺慺愚管所執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-32', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會誕去兵，毌丘儉往，乃陰共結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-33', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '後毌丘儉、文欽反，遣使詣誕，招呼豫州士民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-34', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '誕旣與玄、颺等至親，又王淩、毌丘儉累見夷滅，懼不自安，傾帑藏振施以結衆心，厚養親附及揚州輕俠者數千人為死士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-35', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉作亂，遣健步齎書，欲疑惑大衆，艾斬之，兼道進軍，先趣樂嘉城，作浮橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-36', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '毌丘儉作亂，大將軍司馬景王東征，會從，典知密事，衞將軍司馬文王為大軍後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-028-37', 'p0065', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-029-38', 'p0065', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅隨軍西行，過毌丘儉墓下，倚樹哀吟，精神不樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-39', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '魏畧曰：景初元年秋，遣幽州刺史毌丘儉率衆軍討遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-40', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '正始中，幽州刺史毌丘儉討句麗，遣玄菟太守王頎詣夫餘，位居遣大加郊迎，供軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-41', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '正始三年，宮寇西安平，其五年，為幽州刺吏毌丘儉所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-030-42', 'p0065', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '毌丘儉討句麗，句麗王宮奔沃沮，遂進師擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-048-43', 'p0065', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-048-44', 'p0065', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春正月，魏鎮東將軍毌丘儉、前將軍文欽以淮南之衆西入，戰于樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a04-064-45', 'p0065', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-46', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-47', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '帝於是使鎮東將軍毌丘儉、揚州刺史文欽等距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-48', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '毌丘儉、文欽之亂，大軍東征，帝兼中領軍，留鎮洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-002-49', 'p0065', 'jinshu', 'a05-002', '《晉書·卷二》', '議者請速伐之，帝曰：「誕以毌丘儉輕疾傾覆，今必外連吳寇，此為變大而遲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-013-50', 'p0065', 'jinshu', 'a05-013', '《晉書·卷十三》', '鎮東大將軍毌丘儉等據淮南叛，景帝討平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-013-51', 'p0065', 'jinshu', 'a05-013', '《晉書·卷十三》', '是以毌丘儉以孛為己應，遂起兵而敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-037-52', 'p0065', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孚次壽春，遣毌丘儉、文欽等進討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-039-53', 'p0065', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」毌丘儉、文欽果不服，舉兵反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-040-54', 'p0065', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '參大將軍軍事，從景帝討毌丘儉、文欽於樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0065-a05-040-55', 'p0065', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '時沛國劉含母，及帝舅羽林監王虔前妻，皆毌丘儉孫女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-004-0', 'p0066', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '二年春正月乙丑，鎮東將軍毌丘儉、楊州刺史文欽反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-009-1', 'p0066', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '奏使郭太后出居別宮，及遣樂安王使北詣鄴，又遣文欽令還淮南，皆謐之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-013-2', 'p0066', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '正元中，毌丘儉、文欽反，毓持節至揚、豫州班行赦令，告諭士民，還為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-013-3', 'p0066', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」明年春，鎮東將軍毌丘儉、揚州刺史文欽反，景王謂肅曰：「霍光感夏侯勝之言，始重儒學之士，良有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-021-4', 'p0066', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '正元二年春，毌丘儉、文欽作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-5', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，引兵拒儉、欽有功，封二子亭侯、關內侯，進位驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-6', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '毌丘儉、文欽作亂，以基為行監軍、假節，統許昌軍，適與景王會於許昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-7', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '時兖州刺史鄧艾屯樂嘉，儉使文欽將兵襲艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-027-8', 'p0066', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '文欽、唐咨，舉吳重兵，昧利壽春，身歿不反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-9', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-10', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '揚州刺史前將軍文欽，曹爽之邑人也，驍果麄猛，數有戰功，好增虜獲，以徼寵賞，多不見許，怨恨日甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-11', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大目知大將軍一目已突出，啟云：「文欽本是明公腹心，但為人所誤耳，又天子鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-12', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大目昔為文欽所信，乞得追解語之，令還與公復好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-13', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」大將軍聽遣大目單身往，乘大馬，被鎧冑，追文欽，遙相與語。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-14', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '後毌丘儉、文欽反，遣使詣誕，招呼豫州士民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-15', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-16', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴人大喜，遣將全懌、全端、唐咨、王祚等，率三萬衆，密與文欽俱來應誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-17', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」文欽曰：「江東乘戰勝之威乆矣，未有難北方者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-18', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：文欽曰：「蔣班、焦彝謂我不能出而走，全端、全懌又率衆逆降，此敵無備之時也，可以戰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-19', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」乃赦鴦、虎，使將兵數百騎馳巡城，呼語城內云：「文欽之子猶不見殺，其餘何懼？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-20', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽日祠祭事天，斬於人手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-21', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽以後大軍破敗於城下，艾追之至丘頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-028-22', 'p0066', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文欽、唐咨為國大害，叛主讎賊，還為戎首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-047-23', 'p0066', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-24', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春正月，魏鎮東將軍毌丘儉、前將軍文欽以淮南之衆西入，戰于樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-25', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '峻用征北大將軍文欽計，將征魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-26', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '六月，使文欽、唐咨、全端等步騎三萬救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-048-27', 'p0066', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三年春正月，諸葛誕殺文欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-055-28', 'p0066', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將文欽來降，以奉為虎威將軍，從孫峻至壽春迎之，與敵追軍戰於高亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-29', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '綝聞之，使中書奉詔，詔文欽、劉纂、唐咨等使取據，又遣從兄憲以都下兵逆據於江都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-30', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏廬江太守文欽營住六安，多設屯砦，置諸道要，以招誘亡叛，為邊寇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-056-31', 'p0066', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」十三年，文欽詐降，密書與異，欲令自迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-32', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-33', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-34', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝聞之，遣從兄慮將兵逆據於江都，使中使勑文欽、劉纂、唐咨等合衆擊據，遣侍中左將軍華融、中書丞丁晏告胤取據，并喻胤宜速去意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-35', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '吳遣文欽、唐咨、全端、全懌等帥三萬人救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a04-064-36', 'p0066', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱異帥三萬人屯安豐城，為文欽勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-37', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '帝於是使鎮東將軍毌丘儉、揚州刺史文欽等距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-38', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '鎮東大將軍毋丘儉、揚州刺史文欽舉兵作亂，矯太后令移檄郡國，為壇盟於西門之外，各遣子四人質于吳以請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-39', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '毌丘儉、文欽之亂，大軍東征，帝兼中領軍，留鎮洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-40', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '吳使文欽、唐咨、全端、全懌等三萬餘人來救誕，諸將逆擊，不能禦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-013-41', 'p0066', 'jinshu', 'a05-013', '《晉書·卷十三》', '」正元元年正月，鎮東將軍毋丘儉、揚州刺史文欽反，兵俱敗，誅死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-037-42', 'p0066', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孚次壽春，遣毌丘儉、文欽等進討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-039-43', 'p0066', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」毌丘儉、文欽果不服，舉兵反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-040-44', 'p0066', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '參大將軍軍事，從景帝討毌丘儉、文欽於樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-0', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '諸葛誕言於司馬景王曰：「致人而不至於人者，此之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-1', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '先時領牙門，給事鎮東諸葛誕，誕不以為能也，欲遣還護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-2', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之檢諸書都無此事，至諸葛誕反，司馬文王始挾太后及帝與俱行耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-3', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '以鎮南將軍諸葛誕為鎮東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-4', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，吳大將孫峻等衆號十萬至壽春，諸葛誕拒擊破之，斬吳左將軍留贊，獻捷于京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-5', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，以征東大將軍胡遵為衞將軍，鎮東大將軍諸葛誕為征東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-6', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，以征東大將軍諸葛誕為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-7', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙亥，諸葛誕不就徵，發兵反，殺揚州刺史樂綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-8', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '丁丑，詔曰：「諸葛誕造為凶亂，盪覆揚州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-9', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」己卯，詔曰：「諸葛誕造構逆亂，迫脅忠義，平寇將軍臨渭亭侯龐會、騎督偏將軍路蕃，各將左右，斬門突出，忠壯勇烈，所宜嘉異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-10', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '諸葛誕創造凶亂，主簿宣隆、部曲督秦絜秉節守義，臨事固爭，為誕所殺，所謂無比干之親而受其戮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-11', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三年春二月，大將軍司馬文王陷壽春城，斬諸葛誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-013-12', 'p0067', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '諸葛誕反，大將軍司馬文王議自詣壽春討誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-013-13', 'p0067', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '臣松之以為諸葛誕舉淮南以與吳，孫壹率三百人以歸魏，謂吳有釁，本非有理之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-014-14', 'p0067', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」帝於是發切詔，斥免諸葛誕、鄧颺等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-017-15', 'p0067', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛誕反，掩襲殺綝，詔悼惜之，追贈衞尉，謚曰愍侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-022-16', 'p0067', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '諸葛誕作亂壽春，司馬文王率六軍軍丘頭，泰總署行臺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-022-17', 'p0067', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '前此諸葛誕、鄧颺等馳名譽，有四䆫八達之誚，帝疾之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-023-18', 'p0067', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '案晉書，諸葛誕反，大將軍東征，峕坐稱疾，為司馬文王所法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-19', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，昶據夾石以逼江陵，持施績、全熈使不得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-20', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '吳嘗大發衆集建業，揚聲欲入攻揚州，刺史諸葛誕使基策之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-21', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，基以本官行鎮東將軍，都督揚、豫諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-22', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕戰於東關，不利，乃令誕、儉對換。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-23', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍統中外軍討之，別使諸葛誕督豫州諸軍從安風津擬壽春，征東將軍胡遵督青、徐諸軍出於譙、宋之間，絕其歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-24', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '曹爽誅後，進欽為前將軍以安其心，後代諸葛誕為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-25', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '自曹爽之誅，欽常內懼，與諸葛誕相惡，無所與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-26', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕字公休，琅邪陽都人，諸葛豐後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-27', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-28', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-29', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕夫婦聚會神巫，淫祀求福，伏尸淮南，舉族誅夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-30', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '東安公繇，諸葛誕外孫，欲殺俶，因誅楊駿，誣俶謀逆，遂夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-31', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳大將軍孫峻等號十萬衆，將渡江，鎮東將軍諸葛誕遣艾據肥陽，艾以與賊勢相遠，非要害之地，輒移屯附亭，遣泰山太守諸葛緒等於黎漿拒戰，遂走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-32', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '甘露二年，徵諸葛誕為司空，時會喪寧在家，策誕必不從命，馳白文王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-33', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '以討諸葛誕功，進爵陳侯，屢讓不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-34', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-033-35', 'p0067', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二十年，聞魏大將軍諸葛誕據壽春以叛，姜維復率衆出駱谷，至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-044-36', 'p0067', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '二十年，魏征東大將軍諸葛誕反於淮南，分關中兵東下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-047-37', 'p0067', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '江表傳曰：是歲權遣諸葛壹偽叛以誘諸葛誕，誕以步騎二萬迎壹於高山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-38', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-39', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏諸葛誕入壽春，峻引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-40', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '五月，魏征東大將軍諸葛誕以淮南之衆保壽春城，遣將軍朱成稱臣上疏，又遣子靚、長史吳綱諸牙門子弟為質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-41', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三年春正月，諸葛誕殺文欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-050-42', 'p0067', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及魏大將諸葛誕以壽春來附，而全懌、全端、全煒、全儀等並因此際降魏，全熈謀泄見殺，由是諸全衰弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-055-43', 'p0067', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏遣諸葛誕、胡遵等攻東興，諸葛恪率軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-055-44', 'p0067', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '太平二年，魏大將軍諸葛誕據壽春來降，魏人圍之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-056-45', 'p0067', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是歲魏遣胡遵、諸葛誕等出東興，異督水軍攻浮梁，壞之，魏軍大破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-058-46', 'p0067', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '太平二年，魏將諸葛誕舉壽春降，拜抗為柴桑督，赴壽春，破魏牙門將偏將軍，遷征北將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-059-47', 'p0067', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '後諸葛壹偽叛以誘魏將諸葛誕，權潛軍待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-060-48', 'p0067', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '後襲業領兵，救諸葛誕於壽春，出城先降，魏以為平東將軍，封臨湘侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-064-49', 'p0067', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏以吳軍入其疆土，恥於受侮，命大將胡遵、諸葛誕等率衆七萬，欲攻圍兩塢，圖壞隄遏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-064-50', 'p0067', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏大將軍諸葛誕舉壽春叛，保城請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-51', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-52', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '」乃遣諸葛誕督豫州諸軍自安風向壽春，征東將軍胡遵督青、徐諸軍出譙宋之間，絕其歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-53', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '尋進號都督，統征東將軍胡遵、鎮東將軍諸葛誕伐吳，戰于東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-54', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '二年夏五月辛未，鎮東大將軍諸葛誕殺揚州刺史樂綝，以淮南作亂，遣子靚為質於吳以請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-55', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '暨諸葛誕滔天作逆，稱兵揚楚，欽、咨逋罪，同惡相濟，帥其蝥賊，以入壽春，憑阻淮山，敢距王命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-56', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '四年三月，吳將為寇，鎮東將軍諸葛誕破走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-57', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年五月，有成濟之變及諸葛誕誅，皆其應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-58', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '後三年，即魏甘露二年，諸葛誕又反淮南，吳遣將救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-039-59', 'p0067', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '帝征諸葛誕，留顗鎮守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-040-60', 'p0067', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '帝新執朝權，恐方鎮有異議，使充詣諸葛誕，圖欲伐吳，陰察其變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-0', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '辛未，以長水校尉鄧艾行安西將軍，與征西將軍陳泰并力拒維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-1', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，安西將軍鄧艾大破蜀大將姜維於上邽，詔曰：「兵未極武，醜虜摧破，斬首獲生，動以萬計，自頃戰克，無如此者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-2', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，蜀大將姜維寇洮陽，鎮西將軍鄧艾拒之，破維於侯和，維遁走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-3', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '今使征西將軍鄧艾督帥諸軍，趣甘松、沓中以羅取維，雍州刺史諸葛緒督諸軍趣武都、高樓，首尾踧討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-4', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '自鄧艾、鍾會率衆伐蜀，所至輙克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-5', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五年乙卯，以征西將軍鄧艾為太尉，鎮西將軍鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-6', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '咸熈元年春正月壬戌，檻車徵鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-7', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，鍾會反於蜀，為衆所討；鄧艾亦見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-022-8', 'p0068', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」淮從泰計，使泰率討蜀護軍徐質、南安太守鄧艾等進兵圍之，斷其運道及城外流水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-022-9', 'p0068', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '鄧艾、胡奮、王秘亦到，即與艾、祕等分為三軍，進到隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-026-10', 'p0068', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '次子弘，亦猛毅有招風，以隴西太守隨鄧艾伐蜀有功，咸熈中為振威護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-027-11', 'p0068', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '時兖州刺史鄧艾屯樂嘉，儉使文欽將兵襲艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-12', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍遣兖州刺史鄧艾督泰山諸軍萬餘人至樂嘉，示弱以誘之，大將軍尋自洙至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-13', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾字士載，義陽棘陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-14', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '宣王奇之，辟之為掾，世語曰：鄧艾少為襄城典農部民，與石苞皆年十二三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-15', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-16', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '征西將軍鄧艾，矜功失節，實應大辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-17', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：咸寧中，積射將軍樊震為西戎牙門，得見辭，武帝問震所由進，震自陳曾為鄧艾伐蜀時帳下將，帝遂尋問艾，震具申艾之忠，言之流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-18', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '四年秋，乃下詔使鄧艾、諸葛緒各統諸軍三萬餘人，艾趣甘松、沓中連綴維，緒趣武街、橋頭絕維歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-19', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾追姜維到陰平，簡選精銳，欲從漢德陽入江由、左儋道詣緜竹，趣成都，與諸葛緒共行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-20', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會內有異志，因鄧艾承制專事，密白艾有反狀，世語曰：會善效人書，於劒閣要艾章表白事，皆易其言，令辭指悖傲，多自矜伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-21', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會得文王書云：「恐鄧艾或不就徵，今遣中護軍賈充將步騎萬人徑入斜谷，屯樂城，吾自將十萬屯長安，相見在近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-22', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」會得書，驚呼所親語之曰：「但取鄧艾，相國知我能獨辦之；今來大重，必覺我異矣，便當速發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-23', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」及會白鄧艾不軌，文王將西，悌復曰：「鍾會所統，五六倍於鄧艾，但可勑會取艾，不足自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-24', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾矯然彊壯，立功立事，然闇於防患，咎敗旋至，豈遠知乎諸葛恪而不能近自見，此蓋古人所謂目論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-25', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋八月，維為魏大將軍鄧艾所破于上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-26', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，姜維復率衆出侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-27', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年夏，魏大興徒衆，命征西將軍鄧艾、鎮西將軍鍾會、雍州刺史諸葛緒數道並攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-28', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬，鄧艾破衞將軍諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-035-29', 'p0068', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年冬，魏征西將軍鄧艾伐蜀，自陰平由景谷道旁入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-035-30', 'p0068', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」建稽首曰：「臣竊聞天下之論，皆謂鄧艾見枉，陛下知而不理，此豈馮唐之所謂『雖得頗、牧而不能用』者乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-036-31', 'p0068', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '苞子遵為尚書，隨諸葛瞻於緜竹，與鄧艾戰，死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-039-32', 'p0068', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '及鄧艾至蜀，聞皓姦險，收閉，將殺之，而皓厚賂艾左右，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-042-33', 'p0068', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年冬，魏大將軍鄧艾克江由，長驅而前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-042-34', 'p0068', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年，後主從譙周之計，遣使請降於鄧艾，其書，正所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-043-35', 'p0068', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '權留蜀子崇，為尚書郎，隨衞將軍諸葛瞻拒鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-043-36', 'p0068', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '恢弟子球，羽林右部督，隨諸葛瞻拒鄧艾，臨陣授命，死于緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-37', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '後主旣降鄧艾，斌詣會於涪，待以交友之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-38', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '更整勒戎馬，與鎮西大將軍胡濟期會上邽，濟失誓不至，故維為魏大將鄧艾所破於段谷，星散流離，死者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-39', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏大將軍司馬望拒之，鄧艾亦自隴右，皆軍于長城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-40', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '五年，維率衆出漢、侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-41', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-42', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '月餘，維為鄧艾所摧，還住陰平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-43', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '而鄧艾自陰平由景谷道傍入，遂破諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-44', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會旣構鄧艾，艾檻車徵，因將維等詣成都，自稱益州牧以叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-45', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鄧艾之入江由，士衆鮮少，維進不能奮節緜竹之下，退不能總帥五將，擁衞蜀主，思後圖之計，而乃反覆於逆順之間，希違情於難兾之會，以衰弱之國，而屢觀兵於三秦，已滅之邦，兾理外之奇舉，不亦闇哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-46', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '但鄧艾詭道傍入，出於其後，諸葛瞻旣敗，成都自潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-045-47', 'p0068', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '蜀平後，征西將軍鄧艾聞其名，請為主簿，及書招，欲與相見，皆不往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-48', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-49', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '帝屯汝陽，遣兗州刺史鄧艾督太山諸軍進屯樂嘉，示弱以誘之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-50', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '」征西將軍鄧艾以為未有釁，屢陳異議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-51', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-52', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '十一月，鄧艾帥萬餘人自陰平踰絕險至江由，破蜀將諸葛瞻於緜竹，斬瞻，傳首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-53', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '表鄧艾為太尉，鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-003-54', 'p0068', 'jinshu', 'a05-003', '《晉書·卷三》', '鄧艾雖矜功失節，然束手受罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-005-55', 'p0068', 'jinshu', 'a05-005', '《晉書·卷五》', '爾乃取鄧艾於農瑣，引州泰於行役，委以文武，各善其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-56', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是後鍾會、鄧艾破蜀，會譖艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-57', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，鄧艾、鍾會皆夷滅，赦蜀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-58', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」四年，鍾會、鄧艾伐蜀，剋之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-59', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-60', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾本營將士復追破檻車出艾，還向成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-61', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-62', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-63', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾本營將士復追破檻車出艾，還向成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-64', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-037-65', 'p0068', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '征西將軍陳泰與安西將軍鄧艾進擊維，維退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-66', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '」濬曰：「吾始懼鄧艾之事，畏禍及，不得無言，亦不能遣諸胸中，是吾褊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-67', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '初，鄧艾之誅也，文帝以艾久在隴右，素得士心，一旦夷滅，恐邊情搔動，使彬密察之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-68', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '彬還，白帝曰：「鄧艾忌克詭狹，矜能負才，順從者謂爲見事，直言者謂之觸迕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-0', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」鍾會對曰：「才同陳思，武類太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-1', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」於是侍郎鍾會退論次焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-2', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　傅暢晉諸公贊曰：帝常與中護軍司馬望、侍中王沈、散騎常侍裴秀、黃門侍郎鍾會等講宴於東堂，并屬文論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-3', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃令散騎常侍裴秀、給事黃門侍郎鍾會咸與大將軍俱行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-4', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」又命鎮西將軍鍾會由駱谷伐蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-5', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '自鄧艾、鍾會率衆伐蜀，所至輙克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-6', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五年乙卯，以征西將軍鄧艾為太尉，鎮西將軍鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-7', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，鍾會反於蜀，為衆所討；鄧艾亦見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-8', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，詔曰：「前逆臣鍾會構造反亂，聚集征行將士，劫以兵威，始吐姦謀，發言桀逆，逼脅衆人，皆使下議，倉卒之際，莫不驚懾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-9', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚戌，以虎賁張脩昔於成都馳馬至諸營言鍾會反逆，以至沒身，賜脩弟倚爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-005-10', 'p0069', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '毌丘儉、鍾會等作亂，咸假其命而以為辭焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-009-11', 'p0069', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」後移居墓所，景王遣鍾會看之，若才藝德能及父，當收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-010-12', 'p0069', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '紹子融，字伯雅，與王弼、鍾會俱知名，為洛陽令，參大將軍軍事，與弼、會論易、老義，傳於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-010-13', 'p0069', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '嘗難鍾會「易無互體」，見稱於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-018-14', 'p0069', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '王隱蜀記曰：鍾會平蜀，前後鼓吹，迎悳屍喪還葬鄴，冢中身首如生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-15', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾會為大將軍所昵，聞康名而造之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-16', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾會勸大將軍因此除之，遂殺安及康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-17', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又鍾會傳亦云會作司隷校尉時誅康；會作司隷，景元中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-18', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '干寶云呂安兄巽善於鍾會，巽為相國掾，俱有寵於司馬文王，故遂抵安罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-19', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏常論才性同異，鍾會集而論之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-20', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾會年甚少，嘏以明智交會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-21', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '臣松之案：傅子前云嘏了夏侯之必敗，不與之交，而此云與鍾會善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-22', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '愚以為夏侯玄以名重致患，釁由外至；鍾會以利動取敗，禍自己出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-23', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏若了夏侯之必危，而不見鍾會之將敗，則為識有所蔽，難以言通；若皆知其不終，而情有彼此，是為厚薄由于愛憎，奚豫於成敗哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-023-24', 'p0069', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '晉諸公贊曰：康有弘量，綽以明達為稱，楷少與琅邪王戎俱為掾發名，鍾會致之大將軍司馬文王曰：「裴楷清通，王戎簡要。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-024-25', 'p0069', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '若趙括之母，以先請獲免，鍾會之兄，以密言全子，古今此比，蓋為不少。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-025-26', 'p0069', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』逮鍾會為鎮西將軍，憲英謂從子羊祜曰：『鍾士季何故西出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-025-27', 'p0069', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』其後會請子琇為參軍，憲英憂曰：『他日見鍾會之出，吾為國憂之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-28', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '維聞鍾會諸軍已入漢中，引退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-29', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-30', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」鍾會、胡烈、師纂等皆白艾所作悖逆，變釁以結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-31', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾父子旣囚，鍾會至成都，先送艾，然後作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-32', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鍾會忌艾威名，搆成其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-33', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鍾會字士季，潁川長社人，太傅繇小子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-34', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '臣松之以為鍾會名公之子，聲譽夙著，弱冠登朝，已歷顯仕，景王為相，何容不悉，而方於定虞松表然後乃蒙接引乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-35', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，文王欲遣會伐蜀，西曹屬邵悌求見曰：「今遣鍾會率十餘萬衆伐蜀，愚謂會單身無重任，不若使餘人行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-36', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '惟鍾會與人意同，今遣會伐蜀，必可滅蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-37', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」及會白鄧艾不軌，文王將西，悌復曰：「鍾會所統，五六倍於鄧艾，但可勑會取艾，不足自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-38', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '近日賈護軍問我，言：『頗疑鍾會不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-39', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：文王聞鍾會功曹向雄之收葬會也，召而責之曰：「往者王經之死，卿哭於東市而我不問，今鍾會躬為叛逆而又輒收葬，若復相容，其如王法何！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-40', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '習鑿齒曰：向伯茂可謂勇於蹈義也，哭王經而哀感市人，葬鍾會而義動明主，彼皆忠烈奮勁，知死而往，非存生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-41', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '弼與鍾會善，會論議以校練為家，然每服弼之高致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-42', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '何晏以為聖人無喜怒哀樂，其論甚精，鍾會等述之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-43', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-033-44', 'p0069', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年夏，魏大興徒衆，命征西將軍鄧艾、鎮西將軍鍾會、雍州刺史諸葛緒數道並攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-034-45', 'p0069', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '咸熈元年正月，鍾會作亂於成都，璿為亂兵所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-035-46', 'p0069', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '秋，魏鎮西將軍鍾會征蜀，至漢川，祭亮之廟，令軍士不得於亮墓所左右芻牧樵採。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-042-47', 'p0069', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '明年正月，鍾會作亂成都，後主東遷洛陽，時擾攘倉卒，蜀之大臣無翼從者，惟正及殿中督汝南張通，捨妻子單身隨侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-48', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏大將軍鍾會至漢城，與斌書曰：「巴蜀賢智文武之士多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-49', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-50', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-51', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-52', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-53', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '于時鍾會大衆旣造劒閣，維與諸將列營守險，會不得進，已議還計，全蜀之功，幾乎立矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-54', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '干寶曰：姜維為蜀相，國亡主辱弗之死，而死於鍾會之亂，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-045-55', 'p0069', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '六年，與維咸在劒閣，共詣降鍾會于涪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-56', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-57', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '帝會公卿謀征討計，朝議多謂可遣諸將擊之，王肅及尚書傅嘏、中書侍郎鍾會勸帝自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-58', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '帝用嘏及鍾會策，自帥軍而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-59', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '儀兄靜時在壽春，用鍾會計，作禕、儀書以譎靜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-60', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-61', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會分為二隊，入自斜谷，使李輔圍王含於樂城，又使部將易愷攻蔣斌於漢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-62', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-63', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '表鄧艾為太尉，鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-64', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會遂反於蜀，監軍衞瓘、右將軍胡烈攻會，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-65', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '初，會之伐蜀也，西曹屬邵悌言於帝曰：「鍾會難信，不可令行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-66', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是後鍾會、鄧艾破蜀，會譖艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-67', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，鄧艾、鍾會皆夷滅，赦蜀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-68', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」四年，鍾會、鄧艾伐蜀，剋之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-69', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '鍾會既叛，三軍憤怒，隆隆有聲，兵將怒之徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-034-70', 'p0069', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '鍾會有寵而忌，祜亦憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-034-71', 'p0069', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '鍾會伐蜀，以預爲鎮西長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-72', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-73', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '紞嘗侍帝，從容論魏晉事，因曰：「臣竊謂鍾會之釁，頗由太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-74', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鍾會才見有限，而太祖誇奬太過，嘉其謀猷，盛其名器，居以重勢，委以大兵，故使會自謂算無遺策，功在不賞，輈張跋扈，遂搆凶逆耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-75', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-76', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '紞嘗侍帝，從容論魏晉事，因曰：「臣竊謂鍾會之釁，頗由太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-77', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鍾會才見有限，而太祖誇奬太過，嘉其謀猷，盛其名器，居以重勢，委以大兵，故使會自謂算無遺策，功在不賞，輈張跋扈，遂搆凶逆耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-037-78', 'p0069', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時魏高貴鄉公好才愛士，望與裴秀、王沈、鍾會並見親待，數侍宴筵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-039-79', 'p0069', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '難鍾會易無互體，又與扶風王駿論仁孝孰先，見稱於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-039-80', 'p0069', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及鍾會謀反，審問未至，而外人先告之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-040-81', 'p0069', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '鍾會謀反於蜀，帝假充節，以本官都督關中、隴右諸軍事，西據漢中，未至而會死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a03-070-0', 'p0070', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '司馬懿、懿字仲達，即晉宣帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-002-1', 'p0070', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '督軍御史中丞司馬懿、侍御史鄭渾、羊祕、鮑勛、武周等言：「令如左。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-002-2', 'p0070', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '其以尚書令潁鄉侯陳羣為鎮軍大將軍，尚書僕射西鄉侯司馬懿為撫軍大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-003-3', 'p0070', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '帝曰：「司馬懿臨危制變，擒淵可計日待也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-008-4', 'p0070', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」又曰：「司馬懿所向無前，深為弟憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-021-5', 'p0070', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時司空陳羣錄尚書事，帝初親萬機，質以輔弼大臣，安危之本，對帝盛稱「驃騎將軍司馬懿，忠智至公，社稷之臣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-028-6', 'p0070', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-033-7', 'p0070', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '八年秋，魏使司馬懿由西城，張郃由子午，曹真由斜谷，斜，余奢反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-033-8', 'p0070', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏司馬懿、張郃救祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-035-9', 'p0070', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '明日食時，亮謂參佐拊手大笑曰：「司馬懿必謂吾怯，將有彊伏，循山走矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-035-10', 'p0070', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏司馬懿才用兵衆，未易可輕，量敵而進，兵家所慎；若丞相必有以筭之，則未見坦然之勳，若無筭以裁之，則非明哲之謂，海內歸向之意也，余竊疑焉，請聞其說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-040-11', 'p0070', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '去年臣欲西征，欲令平主督漢中，平說司馬懿等開府辟召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-044-12', 'p0070', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '殷基通語曰：司馬懿誅曹爽，禕設甲乙論平其是非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-047-13', 'p0070', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又蔣琬守漢中，聞司馬懿南向，不出兵乘虛以掎角之，反委漢中，還近成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-047-14', 'p0070', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又司馬懿前來入舒，旬日便退，蜀在萬里，何知緩急而便出兵乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-048-15', 'p0070', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '司馬懿父子，自握其柄，累有大功，除其煩苛而布其平惠，為之謀主而救其疾，民心歸之，亦已乆矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-064-16', 'p0070', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '加司馬懿先誅王淩，續自隕斃，其子幼弱，而專彼大任，雖有智計之士，未得施用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a05-001-17', 'p0070', 'jinshu', 'a05-001', '《晉書·卷一》', '因謂太子丕曰：「司馬懿非人臣也，必預汝家事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a05-037-18', 'p0070', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '」天子曰：「吾得司馬懿二人，復何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-0', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽殊不悟，乃更厲聲罵大目：「汝先帝家人，不念報恩，而反與司馬師作逆；不顧上天，天不祐汝！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-1', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '司馬師滔天作逆，廢害二主，辛、癸、高、莽，惡不足喻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-2', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾遣子惠唐亭侯忠等出其右，司馬師纂等出其左。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0072-a04-004-0', 'p0072', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乃召侍中王沈、尚書王經、散騎常侍王業，謂曰：「司馬昭之心，路人所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-0', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三月，以尚書令司馬孚為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-1', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '辛未，以司空司馬孚為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-2', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五月，吳太傅諸葛恪圍合肥新城，詔太尉司馬孚拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-3', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝受命，遂載王車，與太后別，垂涕，始從太極殿南出，羣臣送者數十人，太尉司馬孚悲不自勝，餘多流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-4', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '戊辰，復遣太尉司馬孚為後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-5', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸酉，以太尉司馬孚為太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-022-6', 'p0073', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '魏氏春秋曰：帝之崩也，太傅司馬孚、尚書右僕射陳泰枕帝尸於股，號哭盡哀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-028-7', 'p0073', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a05-037-8', 'p0073', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '臨終，遺令曰：「有魏貞士河內溫縣司馬孚，字叔達，不伊不周，不夷不惠，立身行道，終始若一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a03-080b-0', 'p0074', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '司馬朗字伯達，河內溫人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-012-1', 'p0074', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '始琰與司馬朗善，晉宣王方壯，琰謂朗曰：「子之弟，聦哲明允，剛斷英跱，殆非子之所及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-015-2', 'p0074', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司馬朗字伯達，河內溫人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-023-3', 'p0074', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」又司馬朗早有聲名，其族兄芝，衆未之知，惟俊言曰：「芝雖風望不及朗，實理但有優耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-028-4', 'p0074', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，淩與司馬朗、賈逵友善，及臨兖、豫，繼其名跡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-002-0', 'p0075', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋七月，兾州大蝗，民饑，使尚書杜畿持節開倉廩以振之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-010-1', 'p0075', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '取士不以一揆，戲志才、郭嘉等有負俗之譏，杜畿簡傲少文，皆以智策舉之，終各顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-2', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '而詔已拜杜畿為太守，畿已入界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-3', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '又臣上言吏民大小，各懷顧望，謂邑當還，拒太守杜畿，今皆反悔，共迎畿之官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-4', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其邯鄲淳事在王粲傳，蘇林事在劉邵、高堂隆傳，樂詳事在杜畿傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-5', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜畿字伯侯，京兆杜陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-6', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」彧曰：「杜畿其人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-7', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖下令曰：「河東太守杜畿，孔子所謂『禹，吾無閒然矣』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-8', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後勳伏法，太祖得其書，歎曰：「杜畿可謂『不媚於竈』者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-9', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」故尚書僕射杜畿於孟津試船，遂至覆沒，忠之至也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-10', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '所問旣了而歸鄉里，時杜畿為太守，亦甚好學，署詳文學祭酒，使教後進，於是河東學業大興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-11', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜畿寬猛克濟，惠以康民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-028-12', 'p0075', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初以尚書郎為滎陽令，魏氏春秋曰：誕為郎，與僕射杜畿試船陶河，遭風覆沒，誕亦俱溺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-014-0', 'p0076', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '與班固、賈逵共述漢史，傅毅等皆宗事之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-017-1', 'p0076', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '賈逵注國語曰：「折其鋒曰挫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-025-2', 'p0076', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '」時侍中賈逵薦丕道蓺深明，宜見任用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-025-3', 'p0076', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '和帝因朝會召見諸儒，丕與侍中賈逵、尚書令黃香等相難數事，帝善丕說，罷朝，特賜冠幘履韤衣一襲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-035-4', 'p0076', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '」初，中興之後，范升、陳元、李育、賈逵之徒爭論古今學，後馬融荅北地太守劉瓌及玄荅何休，義據通深，由是古學遂明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-5', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '鄭興子衆　范升　陳元　賈逵　張霸子揩　揩子陵　陵弟玄');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-6', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '世言左氏者多祖於興，而賈逵自傳其父業，故有鄭、賈之學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-7', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵字景伯，扶風平陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-8', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵以為紀季不能兄弟同心以存國，乃背兄歸讎，書以譏之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-9', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '謂防曰：「賈逵母病，此子無人事於外，無人事謂不廣交通也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-10', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '桓譚以不善讖流亡，鄭興以遜辭僅免，賈逵能附會文致，最差貴顯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-11', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵附會文致，謂引左氏明漢為堯後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-037-12', 'p0076', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '肅宗詔鴻與廣平王羨及諸儒樓望、成封、桓郁、賈逵等，論定五經同異於北宮白虎觀，廣平王羨，明帝子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-037-13', 'p0076', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '東觀記曰「與太常樓望、少府成封、屯騎校尉桓郁、衞士令賈逵等集議」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-039-14', 'p0076', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '積十餘歲，至永元十年，有司復奏之，侍中賈逵因上書曰：「孔子稱『能以禮讓為國，於從政乎何有』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-042-15', 'p0076', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '帝甚善之，以其文典雅，特令校書郎賈逵為之訓詁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-048-16', 'p0076', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '會終坐事繫獄，愽士趙愽、校書郎班固、賈逵等，以終深曉春秋，學多異聞，表請之，終又上書自訟，即日貰出，乃得與於白虎觀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-048-17', 'p0076', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '袁山松書曰「侍中賈逵薦終博達忠直，徵拜郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-052-18', 'p0076', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '年十八，至京師，從侍中賈逵質正大義，逵善待之，瑗因留游學，遂明天官、歷數、京房易傳、六日七分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-052-19', 'p0076', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '賈逵注國語曰：「從後牽曰掎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-059-20', 'p0076', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '賈逵注國語曰：「淈，亂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-059-21', 'p0076', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '往者侍中賈逵摘讖互異三十餘事，諸言讖者皆不能說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-060a-22', 'p0076', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」賈逵注云：「繯，還也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-060a-23', 'p0076', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '甞欲訓左氏春秋，及見賈逵、鄭衆注，乃曰：「賈君精而不博，鄭君博而不精。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-064-24', 'p0076', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '中興以來，通儒達士班固、賈逵、鄭興父子，並敦恱之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-074-25', 'p0076', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '賈逵注國語曰：「從後牽曰掎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-079-26', 'p0076', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '扶風杜林傳古文尚書，林同郡賈逵為之作訓，馬融作傳，鄭玄注解，由是古文尚書遂顯于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-080-27', 'p0076', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '建初中，肅宗博召文學之士，以毅為蘭臺令史，拜郎中，與班固、賈逵共典校書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-080-28', 'p0076', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '和帝時，侍中賈逵薦尤有相如、楊雄之風，召詣東觀，受詔作賦，拜蘭臺令史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-082-29', 'p0076', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '鄭興、賈逵以附同稱顯，桓譚、尹敏以乖忤淪敗，各見本傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-082-30', 'p0076', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '謂桓譚、賈逵、張衡之流也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-092-31', 'p0076', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '賈逵論曆　永元論曆　延光論曆　漢安論曆　熹平論曆　論月食');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-092-32', 'p0076', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '行之未期，章帝復發聖思，考之經讖，使左中郎將賈逵問治曆者衞承、李崇、太尉屬梁鮪、司徒掾嚴勗、太子舍人徐震、鉅鹿公乘蘇統及訢、梵等十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-098-33', 'p0076', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」賈逵曰：「六宗謂日宗、月宗、星宗、岱宗、海宗、河宗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-104-34', 'p0076', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '案宣帝、明帝時，五色鳥羣翔殿屋，賈逵以為胡降徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-113-35', 'p0076', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」賈逵曰：「陶唐之胤劉累也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-014-36', 'p0076', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '友人河東賈逵謂資曰：「足下抱逸群之才，值舊邦傾覆，主將殷勤，千里延頸，宜崇古賢桑梓之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-37', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '賈逵字梁道，河東襄陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-38', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '召見計事，大恱之，謂左右曰：「使天下二千石悉如賈逵，吾何憂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-39', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '青龍中，帝東征，乘輦入逵祠，詔曰：「昨過項，見賈逵碑像，念之愴然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-018-40', 'p0076', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '其祝公道一人，已見賈逵傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-019-41', 'p0076', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '脩與賈逵、王淩並為主簿，而為植所友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-028-42', 'p0076', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，淩與司馬朗、賈逵友善，及臨兖、豫，繼其名跡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-028-43', 'p0076', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '干寶晉紀曰：淩到項，見賈逵祠在水側，淩呼曰：「賈梁道，王淩固忠於魏之社稷者，唯尔有神，知之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-042-44', 'p0076', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '皆通諸經史，又專精於左氏春秋，自劉歆條例，鄭衆、賈逵父子、陳元方、服虔注說，咸略誦述，不復桉本。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-001-45', 'p0076', 'jinshu', 'a05-001', '《晉書·卷一》', '道經賈逵廟，淩呼曰：「賈梁道！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-001-46', 'p0076', 'jinshu', 'a05-001', '《晉書·卷一》', '六月，帝寢疾，夢賈逵、王淩為祟，甚惡之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-011-47', 'p0076', 'jinshu', 'a05-011', '《晉書·卷十一》', '後至和帝時，賈逵繫作，又加黃道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-039-48', 'p0076', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈探尋善政，案賈逵以來法制禁令，諸所施行，擇善者而從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0077-a04-015-0', 'p0077', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '劉馥字元穎，沛國相人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0077-a04-051-1', 'p0077', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」遂殺河，使人北迎揚州刺史劉馥，令住歷陽，以丹楊應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-0', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丙戌，太中大夫楊彪為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-1', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-2', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，太尉黃琬、司徒楊彪免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-3', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '甲申，司空淳于嘉為司徒，光祿大夫楊彪為司空，並錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-4', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」司空楊彪免，太常趙溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-5', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '戊午，太常楊彪為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-6', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，太尉楊彪、司空張喜罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-027-7', 'p0079', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '獻帝西遷都，為侍中，同輿輦至長安，封江南亭侯，代楊彪為司空，免，頃之，復為司徒，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-054-8', 'p0079', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '太尉楊彪，乃祖以來世著名績，其賜公延年杖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-061-9', 'p0079', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '卓議遷都長安，琬與司徒楊彪同諫不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-061-10', 'p0079', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後與楊彪同拜光祿大夫，及徙西都，轉司隷校尉，與司徒王允同謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-064-11', 'p0079', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-066-12', 'p0079', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '初平元年，代楊彪為司徒，守尚書令如故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-066-13', 'p0079', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '每三公缺，楊彪、皇甫嵩皆讓位於瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-068-14', 'p0079', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '司空楊彪辟，舉方正、敦樸，徵，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-070-15', 'p0079', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-071-16', 'p0079', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-17', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-18', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '會公卿議，太尉黃琬、司徒楊彪廷爭不能得，而伍瓊、周珌又固諫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-19', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '太尉楊彪謂暹曰：「古今帝王，無在人臣家者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-20', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '帝使楊彪與司空張喜等十餘人和傕、汜，汜不從，遂質留公卿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-21', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』太尉楊彪等曰：『煨不反，臣等敢以死保，車駕可幸其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-22', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪曰：『臣弘農人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-23', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-074-24', 'p0079', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '故太尉楊彪，歷典二司，元綱極位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-001-25', 'p0079', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-001-26', 'p0079', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '臣松之以為楊彪亦曾為魏武所困，幾至於死，孔融竟不免於誅滅，豈所謂先行其言而後從之哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-002-27', 'p0079', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '冬十月，授楊彪光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-002-28', 'p0079', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書曰：己亥，公卿朝朔旦，并引故漢太尉楊彪，待以客禮，詔曰：「夫先王制几杖之賜，所以賔禮黃耇襃崇元老也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-29', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司徒楊彪曰：「昔盤庚五遷，殷民胥怨，故作三篇以曉天下之民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-30', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-31', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊彪曰：「自古帝王無在人臣家者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-32', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊彪曰：「羣臣共鬬，一人劫天子，一人質公卿，此可行乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-33', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉周忠、皇甫嵩，司徒淳于嘉、趙溫，司空楊彪、張喜等為公，皆辭拜讓瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-34', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：初，議者欲令天子浮河東下，太尉楊彪曰：「臣弘農人，從此已東有三十六灘，非萬乘所當從也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-35', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉楊彪、太僕韓融近臣從者十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-36', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉楊彪，歷典三司，享國極位，操因睚眥，被以非罪，榜楚并兼，五毒俱至，觸情放慝，不顧憲章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-37', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-012-38', 'p0079', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '續漢書曰：太尉楊彪與袁術婚姻，術僭號，太祖與彪有隙，因是執彪，將殺焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-013-39', 'p0079', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '朗薦光祿大夫楊彪，且稱疾，讓位於彪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-022-40', 'p0079', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '為車騎將軍何苗所辟，司徒楊彪再加旌命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-026-41', 'p0079', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-026-42', 'p0079', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '數日，求見太祖，言之曰：「楊彪考訊無他辭語。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-001-0', 'p0080', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '蔡邕獨斷曰：「天子以四海為家，故謂所居為行在所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-001-1', 'p0080', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '奉高皇帝璽綬，蔡邕獨斷曰：「皇帝六璽，皆玉螭虎紐，文曰『皇帝行璽』、『皇帝之璽』、『皇帝信璽』、『天子行璽』、『天子之璽』、『天子信璽』，皆以武都紫泥封之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-008-full-2', 'p0080', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '蔡邕曰：「平城門，正陽之門，與宮連，郊祀法駕所從出，門之最尊者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-008-3', 'p0080', 'houhanshu', 'a03-008', '《後漢書·卷八》', '蔡邕曰：「平城門，正陽之門，與宮連，郊祀法駕所從出，門之最尊者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-4', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '皇太后臨朝，蔡邕獨斷曰：「少帝即位，太后即代攝政，臨前殿，朝羣臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-5', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '今使御史大夫郗慮持節策詔，其上皇后璽綬，蔡邕獨斷曰：「皇后赤綬玉璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-6', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '初平中，蔡邕始追正和熹之謚，蔡邕集謚議曰：「漢世母氏無謚，至于明帝始建光烈之稱，是後轉因帝號加之以德，上下優劣，混而為一，違禮『大行受大名，小行受小名』之制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-7', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '蔡邕曰：「帝女曰公主，姊妹曰長公主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-8', 'p0080', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '今使御史大夫郗慮持節策詔，其上皇后璽綬，〈蔡邕《獨斷》曰：「皇后赤綬玉璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-037-9', 'p0080', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '所著七說及書凡三篇，蔡邕等共論序其志，僉以為彬有過人者四：夙智早成，岐嶷也；夙，早也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-040-10', 'p0080', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '蔡邕獨斷曰：「天子至尊，不敢渫瀆言之，故託於乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-11', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '袁山松書曰：「穆著論甚美，蔡邕甞至其家自寫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-12', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」及穆卒，蔡邕復與門人共述其體行，謚為文忠先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-13', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '袁山松書曰：「蔡邕議曰：『魯季文子，君子以為忠，而謚曰文子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-14', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '蔡邕以為穆貞而孤，又作正交而廣其致焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-044-15', 'p0080', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '熹平六年，靈帝思感舊德，乃圖畫廣及太尉黃瓊於省內，詔議郎蔡邕為其頌云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-047-16', 'p0080', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '」蔡邕月令章句曰：「羽，鳥翼也，以為旌幢麾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-049-17', 'p0080', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '箸論衡八十五篇，二十餘萬言，袁山松書曰：「充所作論衡，中土未有傳者，蔡邕入吳始得之，恒秘玩以為談助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-049-18', 'p0080', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」抱朴子曰：「時人嫌蔡邕得異書，或搜求其帳中隱處，果得論衡，抱數卷持去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-052-19', 'p0080', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」蔡邕銘論曰「呂尚作周太師，其功銘於昆吾之鼎」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-053-20', 'p0080', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '同郡蔡邕深重蟠，及被州辟，乃辭讓之曰：「申屠蟠稟氣玄妙，性敏心通，喪親盡禮，幾於毀滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-21', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」帝惡之，引賜及議郎蔡邕等入金商門崇德署，戴延之西征記曰：「太極殿西有金商門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-22', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '蔡邕坐直對抵罪，徙朔方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-23', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-059-24', 'p0080', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '漢名臣奏曰，蔡邕曰：「言天體者有三家：一曰周髀，二曰宣夜，三曰渾天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-060a-25', 'p0080', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '蔡邕獨斷曰：「金𡕰者，馬冠也，高廣各四寸，在馬鬉前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-064-26', 'p0080', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-064-27', 'p0080', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '植素善蔡邕，邕前徙朔方，植獨上書請之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-068-28', 'p0080', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」同志者乃共刻石立碑，蔡邕為其文，旣而謂涿郡盧植曰：「吾為碑銘多矣，皆有慙德，唯郭有道無愧色耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-29', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-30', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」與蔡邕素善，邕卒後，有虎賁士貌類於邕，漢官典職儀曰：「虎賁中郎將，主武賁千五百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-31', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '曹操旣積嫌忌，而郗慮復搆成其罪，遂令丞相軍謀祭酒路粹典略曰：「粹字文蔚，陳留人，少學於蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-072-32', 'p0080', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-33', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '又聞前召議郎蔡邕對問於金商門，而令中常侍曹節、王甫等以詔書喻旨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-34', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '今羣臣皆以邕為戒，上畏不測之難，下懼劔客之害，謂蔡邕徙朔方時，陽球使刺客追刺邕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-35', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '巡以為諸博士試甲乙科，爭弟高下，更相告言，至有行賂定蘭臺漆書經字，以合其私文者，乃白帝，與諸儒共刻五經文於石，於是詔蔡邕等正其文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-36', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '詐利旣滋，朋徒日廣，直臣抗議，必漏先言之閒，謂蔡邕對詔，王甫、曹節竊觀之，乃宣布於外，而邕下獄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-079-37', 'p0080', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '與蔡邕共奏定六經文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080-38', 'p0080', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '後蔡邕亦造此賦，未成，及見延壽所為，甚竒之，遂輟翰而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-39', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕深敬之，以為讓宜處高任，乃薦於何進曰：「伏惟幕府初開，博選清英，華髮舊德，並為元龜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-40', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕等皆賦詩，彪乃獨作箴曰：「文武將墜，乃俾俊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-41', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '甞與衡俱遊，共讀蔡邕所作碑文，射愛其辭，還恨不繕寫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-082-42', 'p0080', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '謂襄楷、蔡邕、楊厚等也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-084-43', 'p0080', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '其後蔡邕又題八字曰：『黃絹幼婦，外孫虀臼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-084-44', 'p0080', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '陳留董祀妻者，同郡蔡邕之女也，名琰，字文姬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-45', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕議云：「梵，清河人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-46', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕集載：「三月九日，百官會府公殿下，東面，校尉南面，侍中、郎將、大夫、千石、六百石重行北面，議郎、博士西面。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-47', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕前坐侍中西北，近公卿，與光、晃相難問是非焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-48', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕月令論曰：「顓頊曆術曰：『天元正月己巳朔旦立春，俱以日月起於天廟營室五度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-49', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '觀蔡邕之議，可以言天機矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-50', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '勑曰：「前郎中馮光、司徒掾陳晃各訟曆，故議郎蔡邕共補續其志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-51', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '及在東觀，與蔡邕共述律曆記，考驗天官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-52', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '」　蔡邕分星次度數與皇甫謐不同，兼明氣節所在，故載焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-53', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '光和元年中，議郎蔡邕、郎中劉洪補續律曆志，邕能著文，清濁鍾律，洪能為筭，述敘三光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-54', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '蔡邕戍邊上章曰：「朔方髡鉗徒臣邕稽首再拜上書皇帝陛下：臣邕被受陛下尤異大恩，初由宰府備數典城，以叔父故衞尉質時為尚書，召拜郎中，受詔詣東觀著作，遂與羣儒並拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-55', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝沈書曰：「太傅胡廣博綜舊儀，立漢制度，蔡邕依以為志，譙周後改定以為禮儀志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-56', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」蔡邕曰：「即此詔之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-57', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '東都之儀，百官、四姓親家婦女、公主、諸王大夫、蔡邕獨斷曰：「凡與先后有瓜葛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-58', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝承書曰：「建寧五年正月，車駕上原陵，蔡邕為司徒掾，從公行，到陵，見其儀，愾然謂同坐者曰：『聞古不墓祭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-59', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '蔡邕曰：「五更，長老之稱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-60', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」蔡邕曰：「論語『暮春者，春服旣成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-61', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕獨斷曰：「冬至陽氣始動，夏至陰氣始起，麋鹿角解，故寢兵鼓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-62', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」蔡邕曰：「見客平樂、饗衞士，瓌偉壯觀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-63', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕獨斷曰：「三公奉璧上殿，向御坐，北面，太常贊曰：『皇帝為君興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-64', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕曰：「羣臣朝見之儀，視不晚朝十月朔之故，以問胡廣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-65', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '』」蔡邕禮樂志曰：「漢樂四品：一曰大予樂，典郊廟、上陵、殿諸食舉之樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-097-66', 'p0080', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '謝沈書曰蔡邕引中興以來所修者為祭祀志，即邕之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-098-67', 'p0080', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」蔡邕明堂論曰：「明堂者，天子太廟，所以崇禮其祖，以配上帝者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-68', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '蔡邕表志曰：「孝明立世祖廟，以明再受命祖有功之義，後嗣遵儉，不復改立，皆藏主其中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-69', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '初平中，相國董卓、左中郎將蔡邕等以和帝以下，功德無殊，而有過差，不應為宗，及餘非宗者追尊三后，皆奏毀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-70', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '蔡邕表志曰：「宗廟迭毀議奏，國家大體，班固錄漢書，乃置韋賢傳末。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-100-71', 'p0080', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '謝沈書曰：「蔡邕撰建武已後，星驗著明，以續前志，譙周接繼其下者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-100-72', 'p0080', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '」蔡邕表志曰：「言天體者有三家：一曰周髀，二曰宣夜，三曰渾天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-73', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕對曰：「平城門，正陽之門，與宮連，郊祀法駕所由從出，門之最尊者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-74', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕作伯夷叔齊碑曰「熹平五年，天下大旱，禱請名山，求獲荅應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-75', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕封事曰：『政有苛暴，則虎狼食人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-105-76', 'p0080', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」蔡邕對曰：「臣聞易傳曰：『大作不時，天降災，厥咎蝗蟲來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-105-77', 'p0080', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '蔡邕對曰：「蝗蟲出，息不急之作，省賦斂之費，進清仁，黜貪虐，分損承安，屈省別藏，以贍國用，則其救也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-107-78', 'p0080', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '時蔡邕以成帝時男子王襃絳衣入宮，上前殿非常室，曰「天帝令我居此」，後王莽篡位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-107-79', 'p0080', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '上問蔡邕，對曰：「所謂天投蜺者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-108-80', 'p0080', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '蔡邕上書曰：「四年正月朔，日體微傷，羣臣服赤幘，赴宮門之中，無救，乃各罷歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-108-81', 'p0080', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '蔡邕對問曰：「詔問踐阼以來，災眚屢見，頻歲日蝕、地動，風雨不時，疫癘流行，勁風折樹，河、雒盛溢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-109-82', 'p0080', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '蔡邕作樊陵頌云：「前漢戶五萬，口有十七萬，王莽後十不存一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-83', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '乘輿、金根、安車、立車，蔡邕曰：「五安五立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-84', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」貳轂兩轄，蔡邕曰：「轂外復有一轂抱轄，其外乃復設轄，抱銅置其中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-85', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕曰：「在最後左騑馬頭上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-86', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕表志曰：「以文義不著之故，俗人多失其名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-87', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕表志曰：「國家舊章，而幽僻藏蔽，莫之得見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-120-88', 'p0080', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '蔡邕曰：「鄙人不識，謂之平天冠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-120-89', 'p0080', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '蔡邕表志曰：「永平初，詔書下車服制度，中宮皇太子親服重繒厚練，浣已復御，率下以儉化起機。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-001-90', 'p0080', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '謝承後漢書曰：匡少與蔡邕善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-001-91', 'p0080', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '桓譚、蔡邕善音樂，馮翊山子道、王九真、郭凱等善圍棊，太祖皆與埒能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-004-92', 'p0080', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '蔡邕明堂論云：「更」應作「叟」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-93', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」卓怒，罷坐，欲誅植，侍中蔡邕勸之，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-94', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：卓旣為太師，復欲稱尚父，以問蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-95', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：蔡邕在王允坐，聞卓死，有歎惜之音。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-96', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '臣松之以為蔡邕雖為卓所親任，情必不黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-97', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張璠漢紀曰：初，蔡邕以言事見徙，名聞天下，義動志士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-98', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-012-99', 'p0080', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」虎賁士有貌似蔡邕者，融每酒酣，輙引與同坐，曰：「雖無老成人，尚有典刑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-100', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '獻帝西遷，粲徙長安，左中郎將蔡邕見而奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-101', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '陳留路粹、典略曰：粹字文蔚，少學於蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-102', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '漢末又有蔡邕采斯、喜之法，為古今雜形，然精密簡理不如淳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-028-103', 'p0080', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蔡邕有書近萬卷，末年載數車與粲，粲亡後，相國掾魏諷謀反，粲子與焉，旣被誅，邕所與書悉入業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-104', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '及班固敘漢史，馬遷續述天文，而蔡邕、譙周各有撰錄，司馬彪採之，以繼前志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-105', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '漢靈帝時，蔡邕於朔方上書，言「宣夜之學，絕無師法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-106', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '蔡邕所謂周髀者，即蓋天之說也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-107', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '又有費直說周易、蔡邕月令章句，所言頗有先後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-108', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '蔡邕月令章句，壽星起軫六度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-016-109', 'p0080', 'jinshu', 'a05-016', '《晉書·卷十六》', '蔡邕又記建武已後言律呂者，至司馬紹統採而續之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-016-110', 'p0080', 'jinshu', 'a05-016', '《晉書·卷十六》', '至章帝時，其法已絕，蔡邕雖追紀其言，亦曰今無能為者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-017-111', 'p0080', 'jinshu', 'a05-017', '《晉書·卷十七》', '及光和中，乃命劉洪、蔡邕共脩律歷，其後司馬彪因之，以繼班史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-034-112', 'p0080', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜，蔡邕外孫，景獻皇后同產弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-036-full-113', 'p0080', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '漢末又有蔡邕，采斯喜之法，爲古今雜形，然精密閑理不如淳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-070-0', 'p0081', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '又前與白衣禰衡跌蕩於言，跌蕩，無儀檢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-1', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '張升　趙壹　劉梁　邊讓　酈炎　侯瑾　高彪　張超　禰衡');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-2', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '禰衡字正平，平原般人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-3', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」竊見處士平原禰衡，年二十四，字正平，淑質貞亮，英才卓礫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-4', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '操怒，謂融曰：「禰衡豎子，孤殺之猶雀鼠耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-5', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '臨發，衆人為之祖道，先供設於城南，乃更相戒曰：「禰衡勃虐無禮，今因其後到，咸當以不起折之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-081-6', 'p0081', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '」脩因拜曰：「昔任座面折文侯，解見文苑禰衡傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-010-7', 'p0081', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '又平原禰衡傳曰：衡字正平，建安初，自荊州北游許都，恃才傲逸，臧否過差，見不如己者不與語，人皆以是憎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-010-8', 'p0081', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖勑外廄急具精馬三匹，并騎二人，謂融曰：「禰衡豎子，乃敢爾！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-012-9', 'p0081', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '此州人說平原禰衡受傳融論，以為父母與人無親，譬若缻器，寄盛其中，又言若遭饑饉，而父不肖，寧贍活餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-021-10', 'p0081', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又與白衣禰衡言論放蕩，衡與融更相贊揚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-062-11', 'p0081', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '綜時侍坐，權問何如，綜對曰：「蕃上書，大語有似東方朔，巧捷詭辯有似禰衡，而才皆不及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-0', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '華佗字元化，沛國譙人也，一名旉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-1', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」及後愛子倉舒病困，太祖歎曰：「吾悔殺華佗，令此兒彊死也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-2', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '先持貸我，我差，為卿從華佗更索。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-3', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '佗別傳曰：人有在青龍中見山陽太守廣陵劉景宗，景宗說中平曰「數見華佗，其治病手脉之候，其驗若神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-4', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '評曰：華佗之醫診，杜夔之聲樂，朱建平之相術，周宣之相夢，管輅之術筮，誠皆玄妙之殊巧，非常之絕技矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-023-0', 'p0083', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '事見荀粲、傅嘏、王弼、管輅諸傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-1', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '管輅字公明，平原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-2', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」孔曜言：「平原管輅字公明，年三十六，雅性寬大，與世無忌，可謂士雄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-3', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '評曰：華佗之醫診，杜夔之聲樂，朱建平之相術，周宣之相夢，管輅之術筮，誠皆玄妙之殊巧，非常之絕技矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-004-0', 'p0084', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '己未，故漢獻帝夫人節薨，帝臨于華林園，使使持節追謚夫人為獻穆皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-014-1', 'p0084', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭欲詣漢獻帝，至河內，為張楊所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-031-2', 'p0084', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '漢獻帝春秋曰：漢朝聞益州亂，遣五官中郎將牛亶為益州刺史；徵璋為卿，不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-046-3', 'p0084', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：案漢獻帝起居注云「天子從河上還，得六璽於閣上」，又太康之初孫皓送金璽六枚，無有玉，明其偽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-014-4', 'p0084', 'jinshu', 'a05-014', '《晉書·卷十四》', '西海郡故屬張掖，漢獻帝興平二年，武威太守張雅請置。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-015-5', 'p0084', 'jinshu', 'a05-015', '《晉書·卷十五》', '後漢獻帝建安十三年，魏武盡得荊州之地，分南郡以北立襄陽郡，又分南陽西界立南鄉郡，分枝江以西立臨江郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-019-6', 'p0084', 'jinshu', 'a05-019', '《晉書·卷十九》', '司徒荀組據漢獻帝都許即便立郊，自宜於此脩奉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-019-7', 'p0084', 'jinshu', 'a05-019', '《晉書·卷十九》', '漢獻帝建安十八年五月，以河北十郡封魏武帝為魏公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-0', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '三月戊申，以河南尹何進為大將軍，將兵屯都亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-1', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '後將軍袁隗為太傅，與大將軍何進參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-2', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-3', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '何進部曲將吳匡與車騎將軍何苗戰於朱雀闕下，苗敗斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-4', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '三月戊申，以河南尹何進為大將軍，將兵屯都亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-5', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '後將軍袁隗為太傅，與大將軍何進參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-6', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-7', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '何進部曲將吳匡與車騎將軍何苗戰於朱雀闕下，苗敗斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-010b-full-8', 'p0085', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '何進遂舉兵圍驃騎府，收重，重免官自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-031-9', 'p0085', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '靈帝崩，大將軍何進表琮為度遼將軍，卒於官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-035-10', 'p0085', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '靈帝末，黨禁解，大將軍何進聞而辟之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-037-11', 'p0085', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝崩，大將軍何進秉政，典與同謀議，三遷羽林中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-037-12', 'p0085', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '獻帝即位，三公奏典前與何進謀誅閹官，功雖不遂，忠義炳著。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-053-13', 'p0085', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '大將軍何進連徵不詣，進必欲致之，使蟠同郡黃忠書勸曰：「前莫府初開，至如先生，特加殊禮，優而不名，申以手筆，設几杖之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-056-14', 'p0085', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '子謙，為大將軍何進長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-056-15', 'p0085', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '大將軍何進將誅宦官，召并州牧董卓，至澠池，而進意更狐疑，遣劭宣詔止之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-058-16', 'p0085', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '何進令於本州募兵，得千餘人，因留上黨擊山賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-17', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '後公車徵為大將軍何進從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-18', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '及黨禁始解，大將軍何進、司徒袁隗遣人敦寔，敦，勸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-19', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '何進遣使弔祭，海內赴者三萬餘人，制衰麻者以百數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-20', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '先賢行狀曰：「將軍何進遣官屬弔祠為謚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-21', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '帝崩，大將軍何進謀誅中官，乃召并州牧董卓，以懼太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-22', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '當植抽白刃嚴閤之下，追帝河津之閒，排戈刃，赴戕折，事見何進傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-23', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '大將軍何進舉為敦煌太守，行至襄武，縣名，屬隴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-066-24', 'p0085', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '大將軍何進、太尉袁隗、司徒楊賜共上疏請之曰：「夫內視反聽，則忠臣竭誠；寬賢矜能，則義士厲節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-066-25', 'p0085', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '時大將軍何進欲誅宦官，召允與謀事，請為從事中郎，轉河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-26', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '何進字遂高，南陽宛人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-27', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」中黃門以進頭擲與尚書，曰：「何進謀反，已伏誅矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-28', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '論曰：竇武、何進藉元舅之資，據輔政之權，內倚太后臨朝之威，外迎羣英乘風之埶，卒而事敗閹豎，身死功穨，為世所悲，豈智不足而權有餘乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-070-29', 'p0085', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及大將軍何進輔政，徵用名士，以公業為尚書侍郎，續漢志曰：「尚書凡六曹，侍郎三十六人，四百石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-070-30', 'p0085', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '河南尹何進當遷為大將軍，楊賜遣融奉謁賀進，不時通，融即奪謁還府，投劾而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-31', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及帝崩，大將軍何進、司隷校尉袁紹謀誅閹宦，而太后不許，乃私呼卓將兵入朝，以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-32', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」卓未至而何進敗，虎賁中郎將袁術乃燒南宮，欲討宦官，而中常侍段珪等山陽公載記「段」字作「殷」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-33', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '尋而何進及弟苗先所領部曲皆歸於卓，卓又使呂布殺執金吾丁原而并其衆，英雄記曰：「原字建陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-073-34', 'p0085', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹不能舉直措枉，而專為邪媚，招來不軌，疑誤社稷，至令丁原焚燒孟津，續漢書曰：「何進欲誅中常侍趙忠等，進乃詐令武猛都尉丁原放兵數千人，為賊於河內，稱『黑山伯』，上事以誅忠等為辭，燒平陰、河津莫府人舍，以怖動太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-35', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後辟大將軍何進掾，為侍御史、虎賁中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-36', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '靈帝崩，紹勸何進徵董卓等衆軍，脅太后誅諸宦官，轉紹司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-37', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '故大將軍何進忠國疾亂，義心赫怒，以臣頗有一介之節，可責以鷹犬之功，故授臣以督司，諮臣以方略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-38', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '忠策未盡而元帥受敗，元帥謂何進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-075-39', 'p0085', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '靈帝崩，原受何進召，將兵詣洛陽，為執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-078-40', 'p0085', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '竇武、何進，位崇戚近，乘九服之嚻怨，協羣英之埶力，九服已見上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-078-41', 'p0085', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中軍校尉袁紹說大將軍何進，令誅中官以恱天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-080b-42', 'p0085', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '大將軍何進聞讓才名，欲辟命之，恐不至，詭以軍事徵召，旣到，署令史，續漢志曰：「大將軍下有令史及御史屬三十一人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-080b-43', 'p0085', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕深敬之，以為讓宜處高任，乃薦於何進曰：「伏惟幕府初開，博選清英，華髮舊德，並為元龜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-081-44', 'p0085', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '大將軍何進移書陳留太守，累行論謚，僉曰宜為貞節先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-45', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-46', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」中平六年，大將軍何進謀盡誅中官，中官覺，於省中殺進：俱兩破滅，天下由此遂大壞亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-47', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其日未冥四刻，大將軍何進於省中為諸黃門所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-103-48', 'p0085', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時靈帝新棄羣臣，大行尚在梓宮，大將軍何進與佐軍校尉袁紹等共謀欲誅廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-103-49', 'p0085', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '皇后同父兄何進為大將軍，同母弟苗為車騎將軍，兄弟並貴盛，皆統兵在京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-104-50', 'p0085', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '皇后兄何進，異父兄朱苗，皆為將軍，領兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-104-51', 'p0085', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '到六年，靈帝崩，大將軍何進以內寵外嬖，積惡日乆，欲悉糾黜，以隆更始冗政，而太后持疑，事乆不決。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-52', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '大將軍何進與袁紹謀誅宦官，太后不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-53', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '辟大將軍何進府進符使，匡於徐州發彊弩五百西詣京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-54', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遂奉計詣京師，何進宿聞其名，特與相見，遂說進使誅諸閹人，進不從，乃求歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-55', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」卓再違詔勑，會為何進所召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-56', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進與司隷校尉袁紹謀誅諸閹官，太后不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-57', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後大將軍何進辟為東曹屬，稍遷侍中、河南尹、越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-58', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '靈帝崩，太后兄大將軍何進與紹謀誅諸閹官，續漢書曰：紹使客張津說進曰：「黃門、常侍秉權日乆，又永樂太后與諸常侍專通財利，將軍宜整頓天下，為海內除患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-59', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進聞其名，辟為東曹掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-007-60', 'p0085', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '與何進謀誅諸黃門，拜執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-008-61', 'p0085', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝崩，碩為何進所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-010-62', 'p0085', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '何進秉政，徵海內名士攸等二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-012-63', 'p0085', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '勛父信，靈帝時為騎都尉，大將軍何進遣東募兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-012-64', 'p0085', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '大將軍何進辟拜騎都尉，遣歸募兵，得千餘人，還到成皐而進已遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-013-65', 'p0085', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '靈帝崩，何進輔政，徵河南鄭泰、潁川荀攸及歆等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-016-66', 'p0085', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '何進輔政，徵用名士，以泰為尚書侍郎，加奉車都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-017-67', 'p0085', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '何進遣詣河北募兵，得千餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-021-68', 'p0085', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '父謙，為大將軍何進長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-022-69', 'p0085', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '靈帝崩，何進輔政，引用天下名士，徵寔，欲以為參軍，以老病，遂不屈節，諶為司空掾，早卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-022-70', 'p0085', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '先賢行狀曰：大將軍何進遣屬弔祠，謚曰文範先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-031-71', 'p0085', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '大將軍何進表薦扶曰：「資游、夏之德，述孔氏之風，內懷焦、董消復之術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-032-72', 'p0085', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '頃之，大將軍何進遣都尉毌丘毅詣丹楊募兵，先主與俱行，至下邳遇賊，力戰有功，除為下密丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-045-73', 'p0085', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '壹族弟班，字元雄，大將軍何進官屬吳匡之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-053-74', 'p0085', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-0', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '獻帝起居注曰：「自誅黃門後，侍中、侍郎出入禁中，機事頗露，由是王允乃奏侍中、黃門不得出入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-1', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '司徒王允錄尚書事，揔朝政，遣使者張种撫慰山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-2', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-025-3', 'p0086', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '謙子旭，官至太僕，從獻帝西入關，與司徒王允同謀共誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-027-4', 'p0086', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕殺司徒王允，復代允為司徒，數月病免，拜尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-058-5', 'p0086', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '卓問司徒王允曰：「欲得快司隷校尉，誰可作者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-061-6', 'p0086', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後與楊彪同拜光祿大夫，及徙西都，轉司隷校尉，與司徒王允同謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-062-7', 'p0086', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-066-8', 'p0086', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '王允字子師，太原祁人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-066-9', 'p0086', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '若王允之推董卓而引其權，伺其閒而敝其罪，當此之時，天子懸解矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-067-10', 'p0086', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-069-11', 'p0086', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」進於是以紹為司隷校尉，假節，專命擊斷；從事中郎王允為河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-069-12', 'p0086', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '公卿並出平樂觀，無得從者，唯尚書盧植夜馳河上，王允遣河南中部掾閔貢隨植後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-13', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」少有名譽，累登公卿，亦陰與司徒王允共謀誅卓，事未及發而見害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-14', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時王允與呂布及僕射士孫瑞謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-15', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允乃與士孫瑞密表其事，使瑞自書詔以授布，令騎都尉李肅獻帝紀曰：「肅，呂布同郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-16', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-17', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允以為一歲不可再赦，不許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-18', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-19', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「胡文才、楊整脩皆涼州人，王允素所不善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-20', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允奉天子保宣平城門樓上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-21', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遂圍門樓，共表請司徒王允出，問「太師何罪」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-075-22', 'p0086', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '因往見司徒王允，自陳卓幾見殺之狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-079-23', 'p0086', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '」及王允所收而西者，裁七十餘乘，道路艱遠，復弃其半矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-102-24', 'p0086', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-103-25', 'p0086', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-116-26', 'p0086', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '誅黃門後，侍中、侍郎出入禁闈，機事頗露，由是王允乃奏比尚書，不得出入，不通賔客，自此始也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-001-27', 'p0086', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，司徒王允與呂布共殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-28', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三年四月，司徒王允、尚書僕射士孫瑞、卓將呂布共謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-29', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：蔡邕在王允坐，聞卓死，有歎惜之音。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-30', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '縱復令然，不應反言於王允之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-31', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '史遷紀傳，博有奇功於世，而云王允謂孝武應早殺遷，此非識者之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-32', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '王允之忠正，可謂內省不疚者矣，旣無懼於謗，且欲殺邕，當論邕應死與不，豈可慮其謗己而枉戮善人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-33', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '胡文才、楊整脩皆涼州大人，而司徒王允素所不善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-34', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '誅殺卓者，尸王允於市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-35', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司徒王允扶天子上宣平城門避兵，傕等於城門下拜，伏地叩頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-36', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '華嶠曰：夫士以正立，以謀濟，以義成，若王允之推董卓而分其權，伺其間而弊其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-007-37', 'p0086', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '先是，司徒王允以布州里壯健，厚接納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-014-38', 'p0086', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '講業太學，博覽傳記，同郡王允一見而奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-016-39', 'p0086', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後又與王允謀共誅卓，泰脫身自武關走，東歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-032-40', 'p0086', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '故將王允被害，莫敢近者，戩棄官收歛之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-003-41', 'p0086', 'jinshu', 'a05-003', '《晉書·卷三》', '改封南陽王柬為秦王，始平王瑋為楚王，濮陽王允為淮南王，並假節之國，各統方州軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-003-42', 'p0086', 'jinshu', 'a05-003', '《晉書·卷三》', '說者紛然，久而不定，竟用王佑之謀，遣太子母弟秦王柬都督關中，楚王瑋、淮南王允並鎮守要害，以彊帝室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-43', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '癸酉，鎮南將軍楚王瑋、鎮東將軍淮南王允來朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-44', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '丁酉，以梁王肜為太宰，左光祿大夫何劭為司徒，右光祿大夫劉寔為司空，淮南王允為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-45', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '秋八月，淮南王允舉兵討趙王倫，不剋，允及其二子秦王郁、漢王迪皆遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-46', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '乙未，將軍王允之及逸戰於溧陽，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-47', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '癸丑，帝觀兵于廣莫門，分命諸將，遣將軍劉仕救歷陽，平西將軍趙胤屯慈湖，龍驤將軍路永戍牛渚，建武將軍王允之戍蕪湖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-48', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '庾懌嘗送酒於江州刺史王允之，允之與犬，犬斃，懼而表之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-49', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '以江州刺史王允之為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-50', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '冬十月甲午，衞將軍王允之卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-037-51', 'p0086', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '出爲安東將軍、都督揚州諸軍事，代淮南王允鎮壽春，未發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-0', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-1', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '又遣中郎將董卓討先零羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-2', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '并州牧董卓殺執金吾丁原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-3', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空劉弘免，董卓自為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-4', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月甲戌，董卓廢帝為弘農王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-5', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-6', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '又遣中郎將董卓討先零羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-7', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '并州牧董卓殺執金吾丁原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-8', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空劉弘免，董卓自為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-9', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月甲戌，董卓廢帝為弘農王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-10', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丙子，董卓殺皇太后何氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-11', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓自為太尉，加鈇鉞、虎賁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-12', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」董卓遣其將牛輔擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-13', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月癸酉，董卓為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-14', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '初平元年春正月，山東州郡起兵以討董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-15', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '庚辰，董卓殺城門校尉伍瓊、督軍校尉周珌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-16', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓驅徙京師百姓悉西入關，自留屯畢圭苑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-17', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」己酉，董卓焚洛陽宮廟及人家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-18', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '戊午，董卓殺太傅袁隗、太僕袁基，夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-19', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓壞五銖錢，更鑄小錢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-20', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月丁丑，董卓自為太師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-21', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-22', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓遂發掘洛陽諸帝陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-23', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月壬戌，董卓殺衞尉張溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-24', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '夏四月辛巳，誅董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-25', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-26', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '并州牧董卓被徵，將兵入洛陽，陵虐朝庭，遂廢少帝為弘農王而立協，是為獻帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-27', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董卓又議太后踧迫永樂宮，至令憂死，逆婦姑之禮，乃遷於永安宮，因進酖，弒而崩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-28', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董卓令帝出奉常亭舉哀，華延儁洛陽記曰：「城內有奉常亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-29', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '明年，山東義兵大起，討董卓之亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-025-30', 'p0087', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '謙子旭，官至太僕，從獻帝西入關，與司徒王允同謀共誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-027-31', 'p0087', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '車師王侍子為董卓所愛，數犯法，謙收殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-035-32', 'p0087', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '董卓遷都長安，公卿舉玄為趙相，道斷不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-036-33', 'p0087', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '及董卓秉政，聞之，辟以為掾，舉侍御史，不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-045-34', 'p0087', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '董卓忿紹、術背己，遂誅隗及術兄基男女二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-045-35', 'p0087', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '及帝崩，暉聞京師不安，來候忠，董卓聞而惡之，使兵劫殺其兄弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-048-36', 'p0087', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '逆臣董卓，蕩覆王室，典憲焚燎，靡有孑遺，開辟以來，莫或茲酷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-048-37', 'p0087', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '孫堅從桂陽入雒討董卓，軍於城南，見井中有五色光，軍人莫敢汲，堅乃浚得璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-049-38', 'p0087', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '孝靈遭黃巾之寇，獻帝嬰董卓之禍，英雄棋峙，白骨膏野，兵亂相尋三十餘年，三方旣寧，萬不存一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-052-39', 'p0087', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '獻帝初，鈞與袁紹俱起兵山東，董卓以是收烈付郿獄，錮之，鋃鐺鐵鎖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-053-40', 'p0087', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '明年，董卓廢立，蟠及爽、融、紀等復俱公車徵，續漢志曰，徵爽為司空，融為尚書，紀為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-054-41', 'p0087', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '中平六年，代董卓為司空，其冬，代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-054-42', 'p0087', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '明年，關東兵起，董卓懼，欲遷都以違其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-056-43', 'p0087', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '大將軍何進將誅宦官，召并州牧董卓，至澠池，而進意更狐疑，遣劭宣詔止之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-44', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '及帝崩，董卓廢少帝，殺何太后，勳與書曰：「昔伊尹、霍光權以立功，猶可寒心，足下小醜，何以終此？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-45', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時董卓殺帝，圖危社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-46', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '洪乃攝衣升壇，操血而盟曰：「漢室不幸，皇綱失統，賊臣董卓，乘釁縱害，禍加至尊，毒流百姓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-061-47', 'p0087', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及董卓秉政，以琬名臣，徵為司徒，遷太尉，更封陽泉鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-48', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '獻帝即立，董卓輔政，復徵之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-49', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-50', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '及董卓當朝，復備禮召之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-51', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '董卓入洛陽，乃使就家拜五官中郎將，不得已，到京師，遷侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-064-52', 'p0087', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '帝崩，大將軍何進謀誅中官，乃召并州牧董卓，以懼太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-065-53', 'p0087', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐遣司馬尹端、董卓並擊，大破之，斬其酋豪，首虜萬餘人，三州清定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-065-54', 'p0087', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '董卓慕之，使其兄遺縑百匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-55', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '及董卓遷都關中，允悉收斂蘭臺、石室圖書秘緯要者以從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-56', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '時董卓尚留洛陽，朝政大小悉委之於允。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-57', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '初懼董卓豺狼，故折節圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-58', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '董卓將校及在位者多涼州人，允議罷其軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-59', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」宏曰：「義兵鼎沸，在於董卓，況其黨與乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-60', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '瑞以允自專討董卓之勞，故歸功不侯，所以獲免於難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-61', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '董卓數欲有所私授，戩輒堅拒不聽，言色強厲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-62', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '若王允之推董卓而引其權，伺其閒而敝其罪，當此之時，天子懸解矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-067-63', 'p0087', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-64', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '太史奏言有大臣誅死，董卓取溫笞殺於市以厭之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-65', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-66', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '紹使洛陽方略武吏司察宦者，而促董卓等使馳驛上，欲進兵平樂觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-67', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '今董卓垂至，諸君何不早各就國？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-68', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」匡遂引兵與董卓弟奉車都尉旻攻殺苗，弃其屍於苑中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-69', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '董卓遂廢帝，又迫殺太后，殺舞陽君，何氏遂亡，而漢室亦自此敗亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-70', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '進將誅閹官，欲召并州牧董卓為助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-71', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業謂進曰：「董卓彊忍寡義，志欲無猒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-72', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會董卓廢立，融每因對荅，輒有匡正之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-73', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '董卓之亂，弃官歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-74', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-75', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，紹去董卓，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-76', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-77', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '五年，涼州賊王國圍陳倉，復拜嵩為左將軍，督前將軍董卓，各率二萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-78', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時在軍中，說嵩曰：「本朝失政，天下倒懸，能安危定傾者，唯大人與董卓耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-79', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '嵩將行，長史梁衍說曰：「漢室微弱，閹豎亂朝，董卓雖誅之，而不能盡忠於國，遂復寇掠京邑，廢立從意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-80', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時董卓擅政，以儁宿將，外甚親納而心實忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-81', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」儁曰：「相國董卓具為臣說，所以知耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-82', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-83', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '及董卓被誅，傕、汜作亂，儁時猶在中牟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-84', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-85', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董卓字仲穎，卓別傳曰：「卓父君雅為潁川輪氏尉，生卓及弟旻，故卓字仲穎，旻字叔穎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-86', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-87', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕等葬董卓於郿，并收董氏所焚尸之灰，合斂一棺而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-88', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又於朝廷省門外為董卓作神坐，數以牛羊祠之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-89', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '論曰：董卓初以虓闞為情，詩大雅曰：「闞如虓虎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-90', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」董卓滔天，滔，漫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-91', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '及董卓秉政，遣使者授虞大司馬，進封襄賁侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-92', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '逼於董卓，遠隔關塞，不知存否，以虞宗室長者，欲立為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-93', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹為勃海，當攻董卓，而默選戎馬，不告父兄，至使太傅一門纍然同斃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-94', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '董卓恨紹起兵山東，乃誅紹叔父太傅隗，及宗族在京師者，盡誅滅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-95', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '又長沙太守孫堅，前領豫州刺史，遂能驅走董卓，埽除陵廟，忠勤王室，其功莫大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-96', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹遣小將盜居其位，斷絕堅糧，不得深入，使董卓乆不服誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-97', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-98', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '靈帝崩，紹勸何進徵董卓等衆軍，脅太后誅諸宦官，轉紹司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-99', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」「董卓擁制強兵，將有異志，今不早圖，必為所制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-100', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '董卓聞紹起山東，乃誅紹叔父隗，及宗族在京師者，盡滅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-101', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁乃詐作三公移書，傳驛州郡，說董卓罪惡，天子危逼，企望義兵，以釋國難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-102', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初，紹去董卓，與許攸及紀俱詣兾州，以紀聦達有計策，甚親信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-103', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '瓚遂引兵而至，外託討董卓，而陰謀襲馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-104', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '值廢立之際，忠義奮發，單騎出奔，董卓懷懼，濟河而北，勃海稽服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-105', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會董卓乘虛，所圖不軌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-106', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '山陽公載記曰：「董卓以紹為前將軍，封邟鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-107', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '獻帝春秋曰：「紹合兾州十郡守相，衆數十萬，登壇歃血，盟曰：『賊臣董卓，承漢室之微，負兵甲之衆，陵越帝城，跨蹈王朝，幽鴆太后，戮殺弘農，提挈幼主，越遷秦地，殘害朝臣，斬刈忠良，焚燒宮室，蒸亂宮人，發掘陵墓，虐及鬼神，過惡烝皇天，濁穢薰后土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-108', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續遇董卓侵官暴國，左傳：「侵官冒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-109', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續漢書曰：「彪代董卓為司空，又代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-110', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時董卓將欲廢立，以術為後將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-111', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉表上術為南陽太守，術又表堅領豫州刺史，使率荊、豫之卒，擊破董卓於陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-112', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫堅北討董卓，頓軍城南，甄官署有井，每旦有五色氣從井中出，使人浚井，得漢傳國玉璽，其文曰『受命于天，旣壽永昌』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-113', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '策聞術將欲僭號，與書諫曰：「董卓無道，陵虐王室，禍加太后，暴及弘農，天子播越，左傳曰，王子朝云「茲不穀震蕩播越」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-114', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '會進敗，董卓誘布殺原而并其兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-115', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '董卓之亂，與曹操共舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-116', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術欲引布擊備，乃與布書曰：「術舉兵詣闕，未能屠裂董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-117', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '董卓殺隗及術兄基等男女二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-118', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」布用珪策，與暹、奉書曰：「二將軍親拔大駕，而布手殺董卓，俱立功名，當垂竹帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-076-119', 'p0087', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '董卓入洛陽，岱從侍中出為兖州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-079-120', 'p0087', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '及董卓移都之際，吏民擾亂，自辟雍、東觀、蘭臺、石室、宣明、鴻都諸藏典策文章，競共剖散，其縑帛圖書，大則連為帷蓋，小乃制為縢囊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-081-121', 'p0087', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '遭黃巾、董卓之亂，乃避地遼東，夷人尊奉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-084-122', 'p0087', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '後董卓為相國，承其名，娉以軿輜百乘，馬二十匹，奴婢錢帛充路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-084-123', 'p0087', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '漢季失權柄，董卓亂天常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-096-124', 'p0087', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」臣昭案：董卓傳：「卓使呂布發諸帝陵及公卿以下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-099-125', 'p0087', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '初平中，相國董卓、左中郎將蔡邕等以和帝以下，功德無殊，而有過差，不應為宗，及餘非宗者追尊三后，皆奏毀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-102-126', 'p0087', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-127', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '其後董卓多擁胡兵，填塞街衢，虜掠宮掖，發掘園陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-128', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '其後董卓陵虐王室，多援邊人以充本朝，胡夷異種，跨蹈中國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-129', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-130', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」案逆臣董卓滔天虐民，窮凶極惡，關東舉兵欲共誅之，轉相顧望，莫肯先進，處處停兵數十萬，若烏臘蟲，相隨橫取之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-131', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」案「董」謂董卓也，言雖跋扈，縱其殘暴，終歸逃竄，至於滅族也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-104-132', 'p0087', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '其後三年，靈帝暴崩，續以董卓之亂，火三日不絕，京都為丘墟矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-104-133', 'p0087', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '董卓之亂，實擁胡兵，傕、汜之時，充斥尤甚，遂窺閒宮嬪，剽虐百姓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-134', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '到光熹元年，董卓自外入，因閒乘釁，廢帝殺后，百官總己，號令自由，殺戮決前，威重於主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-135', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '後董卓戮太后，被以不孝之名，放廢天子，後復害之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-136', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '陰呼并州牧董卓欲共誅中官，中官逆殺大將軍進，兵相攻討，京都戰者塞道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-109-137', 'p0087', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-114-138', 'p0087', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '董卓在長安，又自尊為太師，位在太傅上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-114-139', 'p0087', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」案獻帝方，董卓自太尉進為相國，而司徒不省。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-115-140', 'p0087', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '董卓為東中郎將，盧植為北中郎將，獻帝以曹植為南中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-120-141', 'p0087', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '孫堅北討董卓，頓軍城南，官署有井，每旦有五色氣從井出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-142', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '進乃召董卓，欲以脅太后，魏書曰：太祖聞而笑之曰：「閹豎之官，古今宜有，但世主不當假之權寵，使至於此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-143', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」馥得移，請諸從事問曰：「今當助袁氏邪，助董卓邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-144', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '向使董卓聞山東兵起，倚王室之重，據二周之險，東向以臨天下；雖以無道行之，猶足為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-145', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書載太祖荅紹曰：「董卓之罪，暴於四海，吾等合大衆興義兵，遠近莫不響應，此以義動故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-146', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '興平元年春，太祖自徐州還，初，太祖父嵩去官後還譙，董卓之亂，避難琅邪，為陶謙所害，故太祖志在復讎東伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-147', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '而遭值董卓之難，興舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-148', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '昔者董卓初興國難，羣后釋位以謀王室，左氏傳曰：「諸侯釋位以間王政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-149', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會董卓作亂，義當死難，故敢奮身出命，摧鋒率衆，遂值千載之運，奉役目下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-002-150', 'p0087', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '董卓乘釁，惡甚澆、𤡬，劫遷省御太僕宮廟，遂使九州幅裂，彊敵虎爭，華夏鼎沸，蝮蛇塞路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-002-151', 'p0087', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '評曰：文帝天資文藻，下筆成章，博聞彊識，才藝兼該；典論帝自敘曰：初平之元，董卓殺主鴆后，盪覆王室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-003-152', 'p0087', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」於是贈冊曰：「嗚呼，昔皇天降戾于漢，俾逆臣董卓，播厥凶虐，焚滅京都，劫遷大駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-005-153', 'p0087', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '及董卓為亂，太祖微服東出避難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-154', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓字仲穎，隴西臨洮人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-155', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」又趨陳留王，曰：「我董卓也，從我抱來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-156', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」傕等曰：「董卓忠於陛下，而無故為呂布所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-157', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '華嶠曰：夫士以正立，以謀濟，以義成，若王允之推董卓而分其權，伺其間而弊其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-158', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又於朝廷省門外，為董卓作神坐，數以牛羊祠之，訖，過省閤問起居，求入見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-159', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃召董卓，欲以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-160', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓呼紹，議欲廢帝，立陳留王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-161', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '說紹曰：「將軍弱冠登朝，則播名海內；值廢立之際，則忠義奮發；單騎出奔，則董卓懷怖；濟河而北，則勃海稽首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-162', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：班，王匡之妹夫，董卓使班奉詔到河內，解釋義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-163', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '僕與董卓有何親戚，義豈同惡？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-164', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　英雄記載太祖作董卓歌，辭云：「德行不虧缺，變故自難常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-165', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續遇董卓侵官暴國，於是提劒揮鼓，發命東夏，方收羅英雄，棄瑕錄用，故遂與操參咨策略，謂其鷹犬之才，爪牙可任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-166', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹去董卓出奔，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚親信之，與共舉事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-167', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓之將廢帝，以術為後將軍；術亦畏卓之禍，出奔南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-168', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '評曰：董卓狼戾賊忍，暴虐不仁，自書契已來，殆未之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-169', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓自竊權柄，至于隕斃，計其日月，未盈三周，而禍崇山岳，毒流四海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-170', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '進敗，董卓入京都，將為亂，欲殺原，并其兵衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-171', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '董卓之亂，太祖與邈首舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-172', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布見關東起兵，欲誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-173', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術報書曰：「昔董卓作亂，破壞王室，禍害術門戶，術舉兵關東，未能屠裂卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-174', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布有殺董卓之功，與二將軍俱為功臣，可因今共擊破術，建功於天下，此時不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-175', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布與建書曰：「天下舉兵，本以誅董卓爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-176', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '高順諫曰：「將軍躬殺董卓，威震夷狄，端坐顧盼，遠近自然畏服，不宜輕自出軍；如或不捷，損名非小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-177', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '董卓殺帝，圖危社稷，洪說超曰：「明府歷世受恩，兄弟並據大郡，今王室將危，賊臣未梟，此誠天下義烈報恩効命之秋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-178', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '洪乃升壇操槃歃血而盟曰：「漢室不幸，皇綱失統，賊臣董卓乘釁縱害，禍加至尊，虐流百姓，大懼淪喪社稷，剪覆四海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-179', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會董卓至洛陽，遷虞大司馬，瓚奮武將軍，封薊侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-180', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '昔為司隷校尉，會值國家喪禍之際，太后承攝，何氏輔政，紹專為邪媚，不能舉直，至令丁原焚燒孟津，招來董卓，造為亂根，紹罪一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-181', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹為勃海太守，默選戎馬，當攻董卓，不告父兄，至使太傅門戶、太僕母子一旦而斃，不仁不孝，紹罪三也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-182', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '又長沙太守孫堅，前領豫州刺史，驅走董卓，掃除陵廟，其功莫大；紹令周昂盜居其位，斷絕堅糧，令不得入，使卓不被誅，紹罪十也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-183', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓之亂，州郡起兵，天子都長安，四方斷絕，謙遣使間行致貢獻，遷安東將軍、徐州牧，封溧陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-184', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '同郡徐榮為董卓中郎將，薦度為遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-185', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '是後，董卓遷天子於長安，天下兵數起，燕遂以其衆與豪傑相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-186', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-009-187', 'p0087', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太守王匡以為從事，將兵拒董卓於盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-009-188', 'p0087', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖起義兵討董卓，至熒陽，為卓將徐榮所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-189', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓秉政，復徵爽，爽欲遁去，吏持之急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-190', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是時，董卓威陵天下，太祖以問彧，彧曰：「卓暴虐已甚，必以亂終，無能為也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-191', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前討徐州，威罰實行，曹瞞傳云：自京師遭董卓之亂，人民流移東出，多依彭城間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-192', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓之亂，關東兵起，卓徙都長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-193', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與議郎鄭泰、何顒、侍中种輯、越騎校尉伍瓊等謀曰：「董卓無道，甚於桀紂，天下皆怨之，雖資彊兵，實一匹夫耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-194', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '遷北軍中候，董卓以為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-195', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓之入洛陽，詡以太尉掾為平津都尉，遷討虜校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-196', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '董卓作亂，承欲合徒衆與天下共誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-197', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初平元年，義兵起，董卓遷帝于長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-198', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '會董卓作亂，避地遼東，躬秉農器，編於四民，布衣蔬食，不改其樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-012-199', 'p0087', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '信至京師，董卓亦始到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-013-200', 'p0087', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '董卓遷天子長安，歆求出為下邽令，病不行，遂從藍田至南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-014-201', 'p0087', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-014-202', 'p0087', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖克兾州，放說松曰：「往者董卓作逆，英雄並起，阻兵擅命，人自封殖，惟曹公能拔拯危亂，翼戴天子，奉辭伐罪，所向必克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-015-203', 'p0087', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '是時董卓遷天子都長安，卓因留洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-015-204', 'p0087', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '到謂父老曰；「董卓悖逆，為天下所讎，此忠臣義士奮發之時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-205', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '峻說原曰：「董卓首亂，天下莫不側目，然而未有先發者，非無其心也，勢未敢耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-206', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾兄泰，與荀攸等謀誅董卓，為揚州刺史，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-207', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '進將誅黃門，欲召董卓為助，泰謂進曰：「董卓彊忍寡義，志欲無饜，若借之朝政，授之大事，將肆其心以危朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-017-208', 'p0087', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '還，進敗，以兵屬董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-209', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '從討董卓，戰于熒陽而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-210', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '董卓作亂，漢室傾蕩，太祖到陳留，始與茲相見，遂同盟，計興武事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-211', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '董卓議欲廢帝，衆莫敢對，植獨正言，語在卓傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-023-212', 'p0087', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太守王匡起兵討董卓，遣諸生於屬縣微伺吏民罪負，便收之，考責錢穀贖罪，稽遲則夷滅宗族，以崇威嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-028-213', 'p0087', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '叔父允，為漢司徒，誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-028-214', 'p0087', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '郡有董卓塢，為之宮舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-215', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：劉焉起兵，不與天下討董卓，保州自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-216', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '董卓使司徒趙謙將兵向州，說校尉賈龍，使引兵還擊焉，焉出青羌與戰，故能破殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-217', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '時焉子範為左中郎將，誕治書御史，璋為奉車都尉，皆從獻帝在長安，英雄記曰：範父焉為益州牧，董卓所徵發，皆不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-218', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '會靈帝崩，天下大亂，備亦起軍從討董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-219', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '董卓欲以所私並充臺閣，戩拒不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-220', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '董卓首難，蕩覆京畿，曹操階禍，竊執天衡；皇后太子鴆殺見害，剥亂天下，殘毀民物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-221', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曩者董卓造為亂階，自是之後，羣兇縱橫，殘剥海內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-033-222', 'p0087', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '曩者漢祚中微，網漏凶慝，董卓造難，震蕩京畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-035-223', 'p0087', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」亮荅曰：「自董卓已來，豪傑並起，跨州連郡者不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-037-224', 'p0087', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '盛又譏其受任非所，將謂仕於董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-038-225', 'p0087', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '靈帝崩，董卓秉政，以漢陽周毖為吏部尚書，與靖共謀議，進退天下之士，沙汰穢濁，顯拔幽滯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-039-226', 'p0087', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時孫堅舉兵討董卓，以南陽太守張咨不給軍糧，殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-227', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '董卓見儁，外甚親納，而心忌之，儁亦陰備焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-228', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」儁曰：「相國董卓為臣說之，臣聞之於相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-229', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '英雄記曰：初堅討董卓，到梁縣之陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-230', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先君與袁氏共破董卓，功業未遂，卒為黃祖所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-231', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　江表傳曰：策徑到壽春見袁術，涕泣而言曰：「亡父昔從長沙入討董卓，與明使君會於南陽，同盟結好；不幸遇難，勳業不終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-232', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '曩日之舉義兵也，天下之士所以響應者，董卓擅廢置，害太后、弘農王，略烝宮人，發掘園陵，暴逆至此，故諸州郡雄豪聞聲慕義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-233', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：建安二年夏，漢朝遣議郎王誧奉戊辰詔書曰：「董卓逆亂，凶國害民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-047-234', 'p0087', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '其司州之土，以函谷關為界，造為盟曰：「天降喪亂，皇綱失叙，逆臣承釁，劫奪國柄，始於董卓，終於曹操，窮凶極惡，以覆四海，至令九州幅裂，普天無統，民神痛怨，靡所戾止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-049-235', 'p0087', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '董卓作亂，壹亡歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-053-236', 'p0087', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '紘以破虜有破走董卓，扶持漢室之勳；討逆平定江外，建立大業，宜有紀頌以昭公美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-054-237', 'p0087', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，孫堅興義兵討董卓，徙家於舒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-055-238', 'p0087', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從孫堅征伐，討黃巾於宛、鄧，破董卓於陽人，攻城野戰，身被創夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-055-239', 'p0087', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '堅南破山賊，北走董卓，拜蓋別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-056-240', 'p0087', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '從破董卓於陽人，入洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-056-241', 'p0087', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '治聞之，求往見賁，為陳安危，江表傳載治說賁曰：「破虜將軍昔率義兵入討董卓，聲冠中夏，義士壯之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-057-242', 'p0087', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陳國陳融、陳留濮陽逸、沛郡蔣纂、廣陵袁迪等，皆單貧有志，就瑁游處，迪孫曄，字思光，作獻帝春秋，云迪與張紘等俱過江，迪父綏為太傅掾，張超之討董卓，以綏領廣陵事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-060-243', 'p0087', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '父柔，漢靈帝時舉孝廉，補尚書郎右丞，董卓之亂，棄官歸，州辟別駕從事，詔書就拜會稽東部都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-009-0', 'p0088', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月癸酉，曹操擊呂布於徐州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-058-1', 'p0088', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '魏志呂布傳曰：「布破張燕軍而求益兵，衆將士鈔掠，紹患忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-058-2', 'p0088', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '先是洪遣司馬二人出，求救於呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-3', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」允然其言，乃潛結卓將呂布，使為內應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-4', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '會卓入賀，呂布因刺殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-5', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '允初議赦卓部曲，呂布亦數勸之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-6', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」呂布又欲以卓財物班賜公卿、將校，允又不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-7', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」曰：「何知貢不與呂布同謀，而輕欲見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-8', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '二年，陶謙死，操欲遂取徐州，還定呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-9', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '宜急分討陳宮，使虜不得西顧，乘其閒而收熟麥，約食稸穀，以資一舉，則呂布不足破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-10', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧量紹雖強，終為操所制，乃說先取呂布，然後圖紹，操從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-11', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '三年，遂擒呂布，定徐州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-12', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '尋而何進及弟苗先所領部曲皆歸於卓，卓又使呂布殺執金吾丁原而并其衆，英雄記曰：「原字建陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-13', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又使呂布發諸帝陵，及公卿已下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-14', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將胡軫、呂布攻之，布與軫不相能，軍中自驚恐，士卒散亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-15', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「卓以東郡太守胡軫為大督，呂布為騎督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-16', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時王允與呂布及僕射士孫瑞謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-17', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '英雄記曰：「有道士書布為『呂』字，將以示卓，卓不知其為呂布也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-18', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃陳兵夾道，自壘及宮，左步右騎，屯衞周帀，令呂布等扞衞前後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-19', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允乃與士孫瑞密表其事，使瑞自書詔以授布，令騎都尉李肅獻帝紀曰：「肅，呂布同郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-20', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '肅以戟刺之，卓衷甲不入，傷臂墯車，顧大呼曰：「呂布何在？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-21', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '呂布乃使李肅以詔命至陝討輔等，輔等逆與肅戰，肅敗走弘農，布誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-22', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-23', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '城峻不可攻，守之八日，呂布軍有叟兵內反，叟兵即蜀兵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-24', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '魏志曰：「楊素與呂布善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-073-25', 'p0088', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '會張邈迎呂布據兖州，操還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-26', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹洪以馬與操，得夜遁，又為呂布所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-27', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '自是士林憤痛，人怨天怒，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，魏志曰：「陶謙為徐州牧，操初征之，下十餘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-28', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-29', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃遣使以竊號告呂布，并為子娉布女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-30', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '呂布字奉先，五原九原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-31', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布常御良馬，號曰赤菟，能馳城飛塹，曹瞞傳曰：「時人語曰：『人中有呂布，馬中有赤菟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-32', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今州軍東征，其處空虛，呂布壯士，善戰無前，迎之共據兖州，觀天下形埶，俟時事變通，此亦從橫一時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-33', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '後從征呂布，為流矢傷左目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-34', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '宋武北征記曰：「下邳城有三重，大城周四里，呂布所守也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-35', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '明公不見呂布事丁建陽、董太師乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-096-36', 'p0088', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」臣昭案：董卓傳：「卓使呂布發諸帝陵及公卿以下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-102-37', 'p0088', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-103-38', 'p0088', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-39', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，司徒王允與呂布共殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-40', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-41', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術欲稱帝於淮南，使人告呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-42', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-43', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-44', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-003-45', 'p0088', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '獻帝傳曰：朗父名宜祿，為呂布使詣袁術，術妻以漢宗室女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-46', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓又使呂布殺執金吾丁原，并其衆，故京都兵權唯在卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-47', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三年四月，司徒王允、尚書僕射士孫瑞、卓將呂布共謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-48', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又有道士書布為「呂」字以示卓，卓不知其為呂布也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-49', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓死，呂布使李肅至陝，欲以詔命誅輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-50', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」傕等曰：「董卓忠於陛下，而無故為呂布所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-51', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '詣傕，傕不肯，曰：「我有討呂布之功，輔政四年，三輔清靜，天下所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-52', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '近董公之彊，明將軍目所見，內有王公以為內主，外有董旻、承、璜以為鯁毒，呂布受恩而反圖之，斯須之間，頭縣竿端，此有勇而無謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-53', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '自是士林憤痛，民怨彌重，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，仿偟東裔，蹈據無所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-54', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '術前為呂布所破，後為太祖所敗，奔其部曲雷薄、陳蘭於灊山，復為所拒，憂懼不知所出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-55', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布字奉先，五原郡九原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-56', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '曹瞞傳曰：時人語曰：「人中有呂布，馬中有赤兎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-57', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-58', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今州軍東征，其處空虛，呂布壯士，善戰無前，若權迎之，共牧兖州，觀天下形勢，俟時事之變通，此亦縱橫之一時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-59', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '及天下亂，始隨太祖，後自疑，乃從呂布，為布畫策，布每不從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-60', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '又掎角呂布有功，加伏波將軍，年三十九卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-61', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '奉使到許，太祖以登為廣陵太守，令陰合衆以圖呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-62', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁、曹方睦，夾輔王室，呂布反覆無義，志在逆亂，而邈、超擅立布為州牧，其於王法，乃一罪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-63', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」先是，洪遣司馬二人出，求救於呂布；比還，城已陷，皆赴敵死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-64', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '評曰：呂布有虓虎之勇，而無英奇之略，輕狡反覆，唯利是視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-008-65', 'p0088', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會張邈叛迎呂布，太祖還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-008-66', 'p0088', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-67', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張邈叛迎呂布，太祖家在鄄城，惇輕軍往赴，適與布會，交戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-68', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖自徐州還，惇從征呂布，為流矢所中，傷左目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-69', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征呂布，仁別攻勾陽，拔之，生獲布將劉何。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-70', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征徐州，張邈舉兖州叛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-71', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-72', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '豫州刺史郭貢帥衆數萬來至城下，或言與呂布同謀，衆甚懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-73', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖方東憂呂布，南拒張繡，而繡敗太祖軍於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-74', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧曰：「不先取呂布，河北亦未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-75', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-76', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是歲，太祖自宛征呂布，魏書曰：議者云表、繡在後而還襲呂布，其危必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-77', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與郭嘉說曰：「呂布勇而無謀，今三戰皆北，其銳氣衰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-011-78', 'p0088', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '頃之，呂布擊術於阜陵，渙往從之，遂復為布所拘留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-011-79', 'p0088', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」又帝聞渙昔拒呂布之事，問渙從弟敏：「渙勇怯何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-80', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張邈等叛迎呂布，郡縣響應，唯鄄城、范、東阿不動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-81', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱乃歸，過范，說其令靳允曰：「聞呂布執君母弟妻子，孝子誠不可為心！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-82', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '陳宮叛迎呂布而百城皆應，似能有為，然以君觀之，布何如人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-83', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖與呂布戰於濮陽，數不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-84', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」嘉又曰：「紹方北擊公孫瓚，可因其遠征，東取呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-85', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '征呂布，三戰破之，布退固守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-86', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-015-87', 'p0088', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '乆之，關東兵散，太祖與呂布相持於濮陽，朗乃將家還溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-016-88', 'p0088', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '呂布之亂，兖州皆叛，惟范、東阿完在，由祗以兵據城之力也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-89', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '卓敗，以兵屬呂布，遷騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-90', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖破呂布於下邳，遼將其衆降，拜中郎將，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-91', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從擊呂布於濮陽，張超於雍丘，橋蕤於苦，皆先登有功，封廣昌亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-92', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-93', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討呂布於濮陽，別破布二營於城南，又別將破高雅於須昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-94', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-95', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征呂布，別降布將趙庶、李鄒等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-96', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '呂布之亂，太祖遣乾還乘氏，慰勞諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-97', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖之討呂布也，霸等將兵助布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-98', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖破呂布，使霸招觀兄弟，皆厚遇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-022-99', 'p0088', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '呂布若襲將軍之後，將軍雖得徐州，事必無成。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-022-100', 'p0088', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '屬呂布破，太祖辟羣為司空西曹掾屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-101', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主與術相持經月，呂布乘虛襲下邳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-102', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '豹衆堅營自守，使人招呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-103', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主求和於呂布，布還其妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-104', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '呂布惡之，自出兵攻先主，先主敗走歸曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-036-105', 'p0088', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-036-106', 'p0088', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主從曹公破呂布，隨還許，曹公拜飛為中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-038-107', 'p0088', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '建安元年，呂布乘先主之出拒袁術，襲下邳，虜先主妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-046-108', 'p0088', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓亦遣兵步騎五千迎之，陳郡太守胡軫為大督護，呂布為騎督，其餘步騎將校都督者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-053-109', 'p0088', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '表為正議校尉，吳書曰：紘與張昭並與參謀，常令一人居守，一人從征討，後呂布襲取徐州，因為之牧，不欲令紘與策從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-054-110', 'p0088', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權曰：「老賊欲廢漢自立乆矣，徒忌二袁、呂布、劉表與孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-070-0', 'p0089', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會張邈、陳宮以兖州反操，典略「宮字公臺，東郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-070-1', 'p0089', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '宜急分討陳宮，使虜不得西顧，乘其閒而收熟麥，約食稸穀，以資一舉，則呂布不足破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-074-2', 'p0089', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-074-3', 'p0089', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布復與陳宮將萬餘人來戰，操時兵少，設伏縱竒兵擊，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-4', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，曹操東擊陶謙，令其將武陽人陳宮屯東郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-5', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '典略曰：「陳宮字公臺，東郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-6', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布欲降，而陳宮等自以負罪於操，深沮其計，而謂布曰：「曹公遠來，埶不能乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-7', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」成忿懼，乃與諸將共執陳宮、高順，率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-8', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」酈元水經注曰：「南門謂之白門，魏武禽陳宮於此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-9', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」操謂陳宮曰：「公臺平生自謂智有餘，今意何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-10', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '世語曰：岱旣死，陳宮謂太祖曰：「州今無主，而王命斷絕，宮請說州中，明府尋往牧之，資之以收天下，此霸王之業也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-11', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-12', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布復從東緍與陳宮將萬餘人來戰，時太祖兵少，設伏，縱奇兵擊，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-13', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '陳宮等沮其計，求救於術，勸布出戰，戰又敗，乃還固守，攻之不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-14', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-15', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '興平元年，太祖復征謙，邈弟超，與太祖將陳宮、從事中郎許汜、王楷共謀叛太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-16', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲降，陳宮等自以負罪深，沮其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-17', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '陳宮謂布：「宜逆擊之，以逸擊勞，無不克也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-18', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」陳宮曰：「逆賊曹操，何等明公！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-19', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲令陳宮、高順守城，自將騎斷太祖糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-20', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魏氏春秋曰：陳宮謂布曰：「曹公遠來，勢不能乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-21', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-22', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魚氏典略曰：陳宮字公臺，東郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-23', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-24', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-25', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '夫陳宮有智而遲，今及布氣之未復，宮謀之未定，進急攻之，布可拔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-26', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '布軍降者，言陳宮欲自將兵取東阿，又使汎嶷取范，吏民皆恐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-27', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '陳宮叛迎呂布而百城皆應，似能有為，然以君觀之，布何如人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-28', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昱又遣別騎絕倉亭津，陳宮至，不得渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-057-29', 'p0089', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '及陳宮、費齊皆上契天心，功德治狀，記在漢籍，有道山陰趙曄，徵士上虞王充，各洪才淵懿，學究道源，著書垂藻，駱驛百篇，釋經傳之宿疑，解當世之槃結，或上窮陰陽之奧祕，下攄人情之歸極。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a03-075-0', 'p0090', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '其督將高順諫止曰：英雄記曰「順為人不飲酒，不受饋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a03-075-1', 'p0090', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」成忿懼，乃與諸將共執陳宮、高順，率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-001-2', 'p0090', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-3', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布不知反者為誰，直牽婦，科頭袒衣，相將從溷上排壁出，詣都督高順營，直排順門入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-4', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '高順諫曰：「將軍躬殺董卓，威震夷狄，端坐顧盼，遠近自然畏服，不宜輕自出軍；如或不捷，損名非小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-5', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安三年，布復叛為術，遣高順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-6', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲令陳宮、高順守城，自將騎斷太祖糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-032-7', 'p0090', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布遣高順攻之，曹公遣夏侯惇往，不能救，為順所敗，復虜先主妻子送布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-032-8', 'p0090', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布由是遣中郎將高順、北地太守張遼等攻備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-067-0', 'p0091', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '度尚、張邈、王考、劉儒、胡母班、秦周、蕃嚮、王章為「八厨」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-070-1', 'p0091', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會張邈、陳宮以兖州反操，典略「宮字公臺，東郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-073-2', 'p0091', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '會張邈迎呂布據兖州，操還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-074-3', 'p0091', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-074-4', 'p0091', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-075-5', 'p0091', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '道經陳留，太守張邈遣使迎之，相待甚厚，臨別把臂言誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-6', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '其年為卓軍所敗，走還泰山，收集勁勇得數千人，欲與張邈合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-7', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-8', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-9', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布東奔劉備，張邈從布，使其弟超將家屬保雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-10', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張邈之叛也，邈劫諶母弟妻子；公謝遣之，曰：「卿老母在彼，可去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-11', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-12', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢末名士錄曰：班字季皮，太山人，少與山陽度尚、東平張邈等八人並輕財赴義，振濟人士，世謂之八厨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-13', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '馥懷懼，從紹索去，往依張邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-007-14', 'p0091', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '張邈字孟卓，東平壽張人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-007-15', 'p0091', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '昔漢光武謬於龐萌，近魏太祖亦蔽於張邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-008-16', 'p0091', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會張邈叛迎呂布，太祖還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-009-17', 'p0091', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張邈叛迎呂布，太祖家在鄄城，惇輕軍往赴，適與布會，交戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-009-18', 'p0091', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征徐州，張邈舉兖州叛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-010-19', 'p0091', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-014-20', 'p0091', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張邈等叛迎呂布，郡縣響應，唯鄄城、范、東阿不動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-018-21', 'p0091', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，張邈舉義兵，韋為士，屬司馬趙寵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-024-22', 'p0091', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '」衆人皆以張邈與太祖善，柔又年少，不然其言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-038-23', 'p0091', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-0', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '虞詡　傅爕　蓋勳　臧洪');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-1', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '臧洪字子源，廣陵射陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-2', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '邈先謂超曰：「聞弟為郡，委政臧洪，洪者何如人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-3', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」超曰：「臧洪海內竒士，才略智數不比於超矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-4', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '超謂軍吏曰：「今日之事，唯有臧洪必來救我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-5', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '足下徼利於境外，臧洪投命於君親；吾子託身於盟主，盟主謂袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-6', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '謂曰：「臧洪何相負若是！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-7', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '臧洪發舉為郡將，柰何殺之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-8', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」紹慙，使人牽出，謂曰：「汝非臧洪疇，空復爾為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-9', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '今日寧與臧洪同日死，不與將軍同日生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-10', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '論曰：雍丘之圍，臧洪之感憤壯矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-11', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '言臧洪徒守節致死，不能如包胥之存楚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-12', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臧洪字子源，廣陵射陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-13', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '邈亦素有心，會于酸棗，邈謂超曰：「聞弟為郡守，政教威恩不由己出，動任臧洪，洪者何人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-14', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖圍張超於雍丘，超言：「唯恃臧洪，當來救吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-15', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '足下徼利於境外，臧洪授命於君親；吾子託身於盟主，臧洪策名於長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-16', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '紹素親洪，盛施帷幔，大會諸將見洪，謂曰：「臧洪，何相負若此！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-17', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臧洪發舉為郡將，柰何殺之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-18', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」紹慙，左右使人牽出，謂曰：「汝非臧洪儔，空復爾為！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-19', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今日寧與臧洪同日而死，不與將軍同日而生！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-20', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '陳登、臧洪並有雄氣壯節，登降年夙隕，功業未遂，洪以兵弱敵彊，烈志不立，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a05-037-21', 'p0092', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '假令天長喪亂，九流渾濁，當與臧洪游於地下耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a03-070-0', 'p0093', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '而操敗於張繡，魏志，張繡在南陽降，旣而悔之，而復反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-1', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張繡降，旣而悔之，復反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-2', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公謂諸將曰：「吾降張繡等，失不便取其質，以至于此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-3', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，公將討張繡，入覲天子，時始復此制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-4', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '冬十一月，張繡率衆降，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-5', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-002-6', 'p0093', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '建安初，上南征荊州，至宛，張繡降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-008-7', 'p0093', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張繡，武威祖厲人，驃騎將軍濟族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-009-8', 'p0093', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征張繡，仁別徇旁縣，虜其男女三千餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-9', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖方東憂呂布，南拒張繡，而繡敗太祖軍於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-10', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖大怒，出入動靜變於常，衆皆謂以失利於張繡故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-11', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-12', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張繡謂詡曰：「此中不可乆處，君胡不去？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-13', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張繡在南陽，詡陰結繡，繡遣人迎詡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-017-14', 'p0093', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-017-15', 'p0093', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-16', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖討張繡，劉表遣兵以助繡，太祖軍不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-17', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從征張繡，先登，斬首萬計，遷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-18', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖征荊州，至宛，張繡迎降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-020-19', 'p0093', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '隨太祖南征，為張繡所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-009-0', 'p0094', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-009-1', 'p0094', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十一月，盜殺大司馬張楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-017-2', 'p0094', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '彭乃潛兵度沔水，擊其將張楊於阿頭山，沔水源出武都東狼谷中，即漢水之上源也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-3', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '百官飢餓，河內太守張楊魏志曰：「楊字稚叔，雲中人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-4', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '拜胡才征東將軍，張楊為安國將軍，皆假節、開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-5', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-6', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張楊以為己功，故因以「楊」名殿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-7', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-8', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '操乃詣闕貢獻，稟公卿以下，因奏韓暹、張楊之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-9', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '四年，張楊為其將楊醜所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-073-10', 'p0094', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹與故虎牙都尉劉勳，首共造兵，勳降服張楊，累有功効，而以小忿枉加酷害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-074-11', 'p0094', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '又黃巾十萬焚燒青、兖、黑山、張楊蹈藉兾城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-074-12', 'p0094', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '金鼓未震，狡敵知亡，故韓馥懷懼，謝咎歸土，張楊、黑山同時乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-075-13', 'p0094', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布不安，復去從張楊於河內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-075-14', 'p0094', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '紹聞，懼為患，募遣追之，皆莫敢逼，遂歸張楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-15', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張楊繕治宮室，名殿曰揚安殿，八月，帝乃遷居。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-16', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-17', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-006-18', 'p0094', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '出箕關，下軹道，張楊以食迎道路，拜大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-006-19', 'p0094', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '浮等到，謂馥曰：「袁本初軍無斗糧，各己離散，雖有張楊、於扶羅新附，未肯為用，不足敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-007-20', 'p0094', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-007-21', 'p0094', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '但懼秋風揚塵，伯珪馬首南向，張楊、飛燕膂力作難，北鄙將告倒縣之急，股肱奏乞歸之誠耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-22', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹與故虎牙都尉劉勳首共造兵，勳仍有効，又降伏張楊，而以小忿枉害於勳，信用讒慝，殺害有功，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-23', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張楊字稚叔，雲中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-24', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '陶謙昬亂而憂死，張楊授首於臣下，皆擁據州郡，曾匹夫之不若，固無可論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-010-25', 'p0094', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-014-26', 'p0094', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭欲詣漢獻帝，至河內，為張楊所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-014-27', 'p0094', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時張楊為其將楊醜所殺，楊長史薛洪、河內太守繆尚城守待紹救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-019-28', 'p0094', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」是時張楊適還河內，太祖得其書，乃引軍迎天子東詣許，以沖為司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-023-29', 'p0094', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '張楊利其婦女，貪其資貨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-009-0', 'p0095', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」夏四月，黑山賊張燕率衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-058-1', 'p0095', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '魏志呂布傳曰：「布破張燕軍而求益兵，衆將士鈔掠，紹患忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-058-2', 'p0095', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '張燕，常山人，本姓褚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-071-3', 'p0095', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '賊帥常山人張燕，輕勇趫捷，故軍中號曰飛燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-4', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '四年春，黑山賊帥張燕與續率兵十萬，三道來救瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-5', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '汝當碎首於張燕，馳驟以告急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-6', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '張燕旣為紹所敗，人衆稍散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-074-7', 'p0095', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '若舉軍東向，則黃巾可埽；還討黑山，則張燕可滅；黑山在今衞州衞縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-074-8', 'p0095', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '遂與黑山賊張燕及四營屠各、鴈門烏桓戰於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-075-9', 'p0095', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '有頃，布得走投袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-001-10', 'p0095', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，黑山賊張燕率其衆十餘萬降，封為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-006-11', 'p0095', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '雖黃巾猾亂，黑山跋扈，舉軍東向，則青州可定；還討黑山，則張燕可滅；回衆北首，則公孫必喪；震脅戎狄，則匈奴必從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-007-12', 'p0095', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '北詣袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-008-13', 'p0095', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '汝當碎首於張燕，速致輕騎，到者當起烽火於北，吾當從內出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-008-14', 'p0095', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張燕，常山真定人也，本姓褚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-0', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時討虜校尉公孫瓚與大司馬劉虞有隙，超乃遣洪詣虞，共謀其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-1', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」但懼秋風揚塵，伯珪馬首南向，伯珪，公孫瓚字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-2', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後助公孫瓚與紹爭兾州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-064-3', 'p0096', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '是時袁紹、曹操與公孫瓚爭兾州，紹及操聞歧至，皆自將兵數百里奉迎，歧深陳天子恩德，宜罷兵安人之道，又移書公孫瓚，為言利害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-4', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，詔令公孫瓚討烏桓，受虞節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-5', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，公孫瓚知術詐，固止虞遣兵，虞不從，瓚乃陰勸術執和，使奪其兵，自是與瓚仇怨益深。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-6', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '將行，從事代郡程緒免冑而前曰：「公孫瓚雖有過惡，而罪名未正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-7', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '公孫瓚字伯珪，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-8', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '今兾部強實，而韓馥庸才，可密要公孫瓚將兵南下，馥聞必駭懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-9', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '「公孫瓚乘勝來南，而諸郡應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-10', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '當今之計，莫若舉兾州以讓袁氏，必厚德將軍，公孫瓚不能復與之爭矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-11', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，公孫瓚大破黃巾，還屯槃河，爾雅有九河，鉤槃是其一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-12', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會公孫瓚師旅南馳，陸掠北境，臣即星駕席卷，與瓚交鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-13', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '四年春，擊公孫瓚，遂定幽土，事在瓚傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-14', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」曹操法令旣行，士卒精練，非公孫瓚坐受圍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-15', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時兾州方有北鄙之警，匪遑離局，北鄙之儆謂公孫瓚攻紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-16', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '往歲伐鼓北征，討公孫瓚，強禦桀逆，拒圍一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-17', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃各外交黨援，以相圖謀，術結公孫瓚，而紹連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-18', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」又與公孫瓚書，云紹非袁氏子，紹聞大怒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-19', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '公孫瓚使劉備與術合謀共逼紹，紹與曹操會擊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-090-20', 'p0096', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-103-21', 'p0096', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」公孫瓚以為易地當之，遂徙鎮焉，乃修城積穀，以待天下之變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-001-22', 'p0096', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-001-23', 'p0096', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時袁紹旣并公孫瓚，兼四州之地，衆十餘萬，將進軍攻許，諸將以為不可敵，公曰：「吾知紹之為人，志大而智小，色厲而膽薄，忌克而少威，兵多而分畫不明，將驕而政令不一，土地雖廣，糧食雖豐，適足以為吾奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-24', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後馥軍安平，為公孫瓚所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-25', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紀曰：「可與公孫瓚相聞，導使來南，擊取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-26', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會卓西入關，紹還軍延津，因馥惶遽，使陳留高幹、頴川荀諶等說馥曰：「公孫瓚乘勝來向南，而諸郡應之，袁車騎引軍東向，此其意不可知，竊為將軍危之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-27', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '英雄記曰：公孫瓚擊青州黃巾賊，大破之，還屯廣宗，改易守令，兾州長吏無不望風響應，開門受之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-28', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '曹氏法令旣行，士卒精練，非公孫瓚坐受圍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-29', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '往歲伐鼓北征，討公孫瓚，彊禦桀逆，拒圍一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-30', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹後用豐謀，以平公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-31', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣與紹有隙，又與劉表不平而北連公孫瓚；紹與瓚不和而南連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-32', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-33', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '超遣洪詣大司馬劉虞謀，值公孫瓚之難，至河間，遇幽、兾二州交兵，使命不達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-34', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：公孫瓚表列紹罪過云：「紹與故虎牙將軍劉勳首共造兵，勳仍有效，而以小忿枉害於勳，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-35', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '公孫瓚字伯珪，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-36', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹破走，太祖喜，顧謂輔曰：「如前歲本初送公孫瓚頭來，孤自視忽然耳，而今克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-37', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹與公孫瓚爭兾州，燕遣將杜長等助瓚，與紹戰，為紹所敗，人衆稍散，太祖將定兾州，燕遣使求佐王師，拜平北將軍；率衆詣鄴，封安國亭侯，邑五百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-38', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '評曰：公孫瓚保京，坐待夷滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-011-39', 'p0096', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '且公孫瓚阻兵安忍，不早圖之，必有後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-011-40', 'p0096', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '得報，馳還，未至，虞已為公孫瓚所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-41', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '是時岱與袁紹、公孫瓚和親，紹令妻子居岱所，瓚亦遣從事范方將騎助岱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-42', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫公孫瓚，非袁紹之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-43', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」嘉又曰：「紹方北擊公孫瓚，可因其遠征，東取呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-44', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '紹逆公孫瓚於界橋，鉅鹿太守李邵及郡冠蓋，以瓚兵彊，皆欲屬瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-017-45', 'p0096', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '紹以郃為校尉，使拒公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-017-46', 'p0096', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '九州春秋曰：初，清河季雍以鄃叛袁紹而降公孫瓚，瓚遣兵衞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-022-47', 'p0096', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '當袁紹、公孫瓚交兵，幽兾饑荒，養寡嫂孤兄子，以學行見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-026-48', 'p0096', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '劉備之奔公孫瓚也，豫時年少，自託於備，備甚奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-026-49', 'p0096', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '公孫瓚使豫守東州令，瓚將王門叛瓚，為袁紹將萬餘人來攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-030-50', 'p0096', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-030-51', 'p0096', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '自我王室多故，公孫瓚作難，殘夷厥土之君，以侮天慢主，是以四海之內，並執干戈以衞社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-52', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」年十五，母使行學，與同宗劉德然、遼西公孫瓚俱事故九江太守同郡盧植。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-53', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-54', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-036-55', 'p0096', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-036-56', 'p0096', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '雲別傳曰：雲身長八尺，姿顏雄偉，為本郡所舉，將義從吏兵詣公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-046-57', 'p0096', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a03-057-0', 'p0097', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '建寧二年，詔舉有道之士，弼與東海陳敦、玄菟公孫度俱對策，皆除郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a03-081-1', 'p0097', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '太守公孫度接以昆弟之禮，魏志曰：「公孫度字升濟，本遼東襄平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-008-2', 'p0097', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '公孫度字升濟，本遼東襄平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-3', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '公孫度在遼東，擅留茂，不遣之官，然茂終不為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-4', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」臣松之案此傳云公孫度聞曹公遠征，鄴無守備，則太祖定鄴後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-5', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '遼東太守公孫度畏惡欲殺之，盡收捕其家，政得脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-6', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '天下大亂，聞公孫度令行於海外，遂與原及平原王烈等至于遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-7', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '辭公孫度長史，商賈自穢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-030-8', 'p0097', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '漢末，公孫度雄張海東，威服外夷，夫餘王尉仇台更屬遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-030-9', 'p0097', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '公孫度之雄海東也，伯固遣大加優居、主簿然人等助度擊富山賊，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a05-014-10', 'p0097', 'jinshu', 'a05-014', '《晉書·卷十四》', '後漢末，公孫度自號平州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-0', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '癸巳，以大將軍曹真為大司馬，驃騎將軍司馬宣王為大將軍，遼東太守公孫淵為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-1', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，公孫淵斬送孫權所遣使張彌、許晏首，以淵為大司馬樂浪公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-2', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '遣幽州刺史毌丘儉率諸軍及鮮卑、烏丸屯遼東南界，璽書徵公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-3', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '丙寅，司馬宣王圍公孫淵於襄平，大破之，傳淵首于京都，海東諸郡平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-004-4', 'p0098', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '丁丑詔曰：「太尉體道正直，盡忠三世，南擒孟達，西破蜀虜，東滅公孫淵，功蓋海內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-5', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載中領軍夏侯獻表曰：「公孫淵昔年敢違王命，廢絕計貢者，實挾兩端。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-6', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '昕等伏自惟省，螻蟻小醜，器非時用，遭值千載，被受公孫淵祖考以來光明之德，惠澤沾渥，滋潤榮華，無尺寸之功，有負乘之累；遂蒙襃獎，登名天府，並以駑蹇附龍託驥，紆青拖紫，飛騰雲梯，感恩惟報，死不擇地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-7', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：公孫淵自立，稱紹漢元年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-8', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '遼東太守公孫淵奪叔父位，擅自立，遣使表狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-9', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」漢晉春秋曰：公孫淵聞魏將來討，復稱臣於孫權，乞兵自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-10', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太和末，吳遣將周賀浮海詣遼東，招誘公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-021-11', 'p0098', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-024-12', 'p0098', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '初，公孫淵兄晃，為叔父恭任內侍，先淵未反，數陳其變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-026-13', 'p0098', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和末，公孫淵以遼東叛，帝欲征之而難其人，中領軍楊曁舉豫應選。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-028-14', 'p0098', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '公孫淵逆與儉戰，不利，引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-15', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '而公孫淵仍父祖三世有遼東，天子為其絕域，委以海外之事，遂隔斷東夷，不得通於諸夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-16', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '公孫淵伏誅，玄菟庫猶有玉匣一具。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-17', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '景初二年，太尉司馬宣王率衆討公孫淵，宮遣主簿大加將數千人助軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-047-18', 'p0098', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏遼東太守公孫淵遣校尉宿舒、閬中令孫綜稱藩於權，并獻貂馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-047-19', 'p0098', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後拜宣信校尉，往救公孫淵，已為魏所破，還遷執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-052-20', 'p0098', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權以公孫淵稱藩，遣張彌、許晏至遼東拜淵為燕王，昭諫曰：「淵背魏懼討，遠來求援，非本志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-053-21', 'p0098', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '時公孫淵降而復叛，權盛怒，欲自親征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-057-22', 'p0098', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權忿公孫淵之巧詐反覆，欲親征之，瑁上疏諫曰：「臣聞聖王之御遠夷，羈縻而已，不常保有，故古者制地，謂之荒服，言慌惚無常，不可保也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-058-23', 'p0098', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '及公孫淵背盟，權欲往征，遜上疏曰：「淵憑險恃固，拘留大使，名馬不獻，實可讎忿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-035-0', 'p0099', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '會黃巾寇青部，乃避地徐州，徐州牧陶謙接以師友之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-048-1', 'p0099', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '興平元年，前太尉曹嵩及子德從琅邪入太山，劭遣兵迎之，未到，而徐州牧陶謙素怨嵩子操數擊之，乃使輕騎追嵩、德，並殺之於郡界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-068-2', 'p0099', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '徐州刺史陶謙禮之甚厚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-3', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '興平元年，操東擊陶謙，使彧守甄城，縣名，屬濟陰郡，今濮州縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-4', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '「呂將軍來助曹使君擊陶謙，宜亟供軍實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-5', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '二年，陶謙死，操欲遂取徐州，還定呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-6', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '徐州刺史陶謙遣精兵三千，餘州郡稍有所給，謙乃上儁行車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-7', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '陶謙以儁名臣，數有戰功，可委以大事，乃與諸豪桀共推儁為太師，因移檄牧伯，同討李傕等，奉迎天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-8', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '乃奏記於儁曰：「徐州刺史陶謙、前楊州刺史周乾、琅邪相陰德、東海相劉馗、馗音巨眉反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-9', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '軍吏皆憚入關，欲應陶謙等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-10', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '陶謙字恭祖，丹陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-11', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '吳書曰：「陶謙父，故餘姚長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-12', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」少為諸生，仕州郡，吳書曰：「陶謙察孝廉，拜尚書郎，除舒令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-074-13', 'p0099', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '自是士林憤痛，人怨天怒，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，魏志曰：「陶謙為徐州牧，操初征之，下十餘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-075-14', 'p0099', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，曹操東擊陶謙，令其將武陽人陳宮屯東郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-078-15', 'p0099', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '及子操起兵，不肯相隨，乃與少子疾避亂琅邪，為徐州刺史陶謙所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-16', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-17', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '下邳闕宣聚衆數千人，自稱天子；徐州牧陶謙與共舉兵，取泰山華、費，略任城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-18', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋，太祖征陶謙，下十餘城，謙守城不敢出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-19', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '興平元年春，太祖自徐州還，初，太祖父嵩去官後還譙，董卓之亂，避難琅邪，為陶謙所害，故太祖志在復讎東伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-20', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖令泰山太守應劭送家詣兖州，劭兵未至，陶謙密遣數千騎掩捕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-21', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '陶謙遣都尉張闓將騎二百衞送，闓於泰山華、費間殺嵩，取財物，因奔淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-22', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖歸咎於陶謙，故伐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-23', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-007-24', 'p0099', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖之征陶謙，勑家曰；「我若不還，往依孟卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-007-25', 'p0099', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '是時世荒民饑，州牧陶謙表登為典農校尉，乃巡土田之宜，盡鑿溉之利，秔稻豐積。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-008-26', 'p0099', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '徐州牧陶謙初辟別駕從事，辭疾遜遁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-008-27', 'p0099', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '陶謙昬亂而憂死，張楊授首於臣下，皆擁據州郡，曾匹夫之不若，固無可論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-009-28', 'p0099', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征陶謙，留惇守濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-009-29', 'p0099', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '別攻陶謙將呂由，破之，還與大軍合彭城，大破謙軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-30', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '興平元年，太祖征陶謙，任彧留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-31', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '布旣至，邈乃使劉翊告彧曰：「呂將軍來助曹使君擊陶謙，宜亟供其軍食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-32', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陶謙死，太祖欲遂取徐州，還乃定布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-33', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '且陶謙雖死，徐州未易亡也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-34', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陶謙帥其衆軍武原，太祖不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-013-35', 'p0099', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '徐州刺史陶謙察朗茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-017-36', 'p0099', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖之征陶謙，紹使靈督三營助太祖，戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-018-37', 'p0099', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '黃巾起，霸從陶謙擊破之，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-022-38', 'p0099', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時陶謙病死，徐州迎備，備欲往，羣說備曰：「袁術尚彊，今東，必與之爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-032-39', 'p0099', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公征徐州，徐州牧陶謙遣使告急於田楷，楷與先主俱救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-032-40', 'p0099', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '陶謙故將曹豹在下邳，張飛欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-038-41', 'p0099', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後徐州牧陶謙辟為別駕從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-046-42', 'p0099', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢來領郡，岱將憲避難於許昭家，求救於陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-43', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融者，丹楊人，初聚衆數百，往依徐州牧陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-44', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '曹公攻陶謙，徐土搔動，融將男女萬口，馬三千匹，走廣陵，廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-45', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '先是，彭城相薛禮為陶謙所偪，屯秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-052-46', 'p0099', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」刺史陶謙舉茂才，不應，謙以為輕己，遂見拘執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-056-47', 'p0099', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '表治行督軍校尉，特將步騎，東助徐州牧陶謙討黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-056-48', 'p0099', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '徐州牧陶謙謂範為袁氏覘候，諷縣掠考範，範親客健兒篡取以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-009-0', 'p0100', 'houhanshu', 'a03-009', '《後漢書·卷九》', '青州黃巾擊殺兖州刺史劉岱於東平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-031-1', 'p0100', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '侍御史劉岱典考其事，岱為表陳解釋，免歸田里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-058-2', 'p0100', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '乃使詣兖州刺史劉岱、岱字公山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-072-3', 'p0100', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '侍中劉岱為兖州刺史，吳志曰：「劉岱字公山，東萊牟平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-4', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-5', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏氏春秋云劉岱惡而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-6', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '兖州刺史劉岱與其書，道『卓無道，天下所共攻，死在旦暮，不足為憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-7', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」兖州刺史劉岱、岱，劉繇之兄，事見吳志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-8', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱與橋瑁相惡，岱殺瑁，以王肱領東郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-9', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱欲擊之，鮑信諫曰：「今賊衆百萬，百姓皆震恐，士卒無鬬志，不可敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-10', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-006-11', 'p0100', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-006-12', 'p0100', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-007-13', 'p0100', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：于時此盟止有劉岱等五人而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-012-14', 'p0100', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會黃巾大衆入州界，劉岱欲與戰，信止之，岱不從，遂敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-014-15', 'p0100', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初平中，兖州刺史劉岱辟昱，昱不應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-032-16', 'p0100', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-038-17', 'p0100', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-full-0', 'p0101', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '三月，幽州牧劉虞購斬漁陽賊張純。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-full-1', 'p0101', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-2', 'p0101', 'houhanshu', 'a03-008', '《後漢書·卷八》', '三月，幽州牧劉虞購斬漁陽賊張純。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-3', 'p0101', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-009-4', 'p0101', 'houhanshu', 'a03-009', '《後漢書·卷九》', '乙酉，以太尉劉虞為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-058-5', 'p0101', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '勳時與宗正劉虞、佐軍校尉袁紹同典禁兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-058-6', 'p0101', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時討虜校尉公孫瓚與大司馬劉虞有隙，超乃遣洪詣虞，共謀其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-7', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞字伯安，東海郯人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-8', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚志埽滅烏桓，而劉虞欲以恩信招降，由是與虞相忤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-9', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚旣諫劉虞遣兵就袁術，而懼術知怨之，乃使從弟越將千餘騎詣術自結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-10', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '是歲，瓚破禽劉虞，盡有幽州之地，猛志益盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-11', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞從事漁陽鮮于輔等，合率州兵，欲共報瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-12', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞守道慕名，以忠厚自牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-075-13', 'p0101', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '太僕黃琬為豫州牧，宗正劉虞為幽州牧，皆以本秩居職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-075-14', 'p0101', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '紹議欲立劉虞為帝，術好放縱，憚立長君，託以公義不肯同，積此釁隙遂成。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-089-15', 'p0101', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '靈帝詔發南匈奴兵，配幽州牧劉虞討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-090-16', 'p0101', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '五年，以劉虞為幽州牧，虞購募斬純首，北州乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-103-17', 'p0101', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '初，瓚破黃巾，殺劉虞，乘勝南下，侵據齊地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-114-18', 'p0101', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」臣昭案：劉虞為大司馬，而與太尉並置焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-001-19', 'p0101', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-001-20', 'p0101', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-006-21', 'p0101', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹自號車騎將軍，主盟，與兾州牧韓馥立幽州牧劉虞為帝，遣使奉章詣虞，虞不敢受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-006-22', 'p0101', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '幽州牧劉虞宿有德望，紹等欲立之以安當時，使人報術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-007-23', 'p0101', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '超遣洪詣大司馬劉虞謀，值公孫瓚之難，至河間，遇幽、兾二州交兵，使命不達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-008-24', 'p0101', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '朝議以宗正東海劉伯安旣有德義，昔為幽州刺史，恩信流著，戎狄附之，若使鎮撫，可不勞衆而定，乃以劉虞為幽州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-008-25', 'p0101', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏氏春秋曰：初，劉虞和輯戎狄，瓚以胡夷難禦，當因不賔而討之，今加財賞，必益輕漢，效一時之名，非乆長深慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-011-26', 'p0101', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '幽州牧劉虞歎曰：「賊臣作亂，朝廷播蕩，四海俄然，莫有固志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-011-27', 'p0101', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '瓚聞之大怒，購求獲疇，謂曰：「汝何自哭劉虞墓，而不送章報於我也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-030-28', 'p0101', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '靈帝末，以劉虞為幽州牧，募胡斬純首，北州乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-031-29', 'p0101', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-0', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-1', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操南征劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-2', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是月，劉表卒，少子琮立，琮以荊州降操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-056-3', 'p0102', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '同郡劉表時年十七，從暢受學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-056-4', 'p0102', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '後許汜與劉備並在荊州牧劉表坐，備共論天下人，汜曰：「陳元龍淮海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-064-5', 'p0102', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歧雖迫大命，猶志報國家，欲自乘牛車，南說劉表，可使其身自將兵來衞朝廷，與將軍并心同力，共獎王室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-064-6', 'p0102', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歧至，劉表即遣兵詣洛陽助修宮室，軍資委輸，前後不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-066-7', 'p0102', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '長安之亂，容於荊州，劉表厚禮焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-8', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '張儉、岑晊、劉表、陳翔、孔昱、苑康、檀𢾭、翟超為「八及」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-9', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以儉及檀彬、褚鳳、張肅、薛蘭、馮禧、魏玄、徐乾為「八俊」，田林、張隱、劉表、薛郁、王訪、劉祇、宣靖、公緒恭為「八顧」，公緒，姓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-10', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-069-11', 'p0102', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '至建安中，荊州牧劉表聞而辟焉，以為從事，使還竇姓，以事列上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-12', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '是時荊州牧劉表不供職貢，多行僭偽，遂乃郊祀天地，擬斥乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-13', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融上疏曰：「竊聞領荊州牧劉表桀逆放恣，所為不軌，至乃郊祭天地，擬儀社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-14', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」前以露袁術之罪，今復下劉表之事，是使跛牂欲闚高岸，天險可得而登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-15', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '六年，操以紹新破，未能為患，但欲留兵衞之，自欲南征劉表，以計問彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-16', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '復若南征劉表，委弃兖、豫，飢軍深入，踰越江、沔，沔即漢水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-17', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '操將伐劉表，問彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-18', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '先是荊州牧劉表表焉僭擬乘輿器服，韙以此遂屯兵朐䏰備表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-19', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉表上術為南陽太守，術又表堅領豫州刺史，使率荊、豫之卒，擊破董卓於陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-20', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃各外交黨援，以相圖謀，術結公孫瓚，而紹連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-21', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '初平三年，術遣孫堅擊劉表於襄陽，堅戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-22', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操毒被於東徐，劉表僭亂於南荊，公孫叛逆於朔北，正禮阻兵，劉繇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-080b-23', 'p0102', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '顧此人素有虛名，遠近將謂孤不能容之，今送與劉表，視當何如。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-080b-24', 'p0102', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '劉表及荊州士大夫先服其才名，甚賔禮之，文章言議，非衡不定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-083-25', 'p0102', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '荊州刺史劉表數延請，不能屈，乃就候之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-102-26', 'p0102', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '荊州分也，時荊州牧劉表據荊州，益州從事周羣以為荊州牧將死而失土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-103-27', 'p0102', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」言自中興以來，荊州無破亂，及劉表為牧，民又豐樂，至此逮八九年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-103-28', 'p0102', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '當始衰者，謂劉表妻當死，諸將並零落也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-105-29', 'p0102', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '』時天下尚亂，豪桀並爭：曹操事二袁於河北；孫吳創基於江外；劉表阻亂衆於襄陽，南招零、桂，北割漢川，又以黃祖為爪牙，而祖與孫氏為深讎，兵革歲交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-118-30', 'p0102', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '故焉牧益土，造帝服於岷、峨；袁紹取兾，下制書於燕、朔；劉表荊南，郊天祀地；魏祖據兖，遂構皇業：漢之殄滅，禍源乎此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-31', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荊州牧劉表斷術糧道，術引軍入陳留，屯封丘，黑山餘賊及於夫羅等佐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-32', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏五月，劉表遣兵救繡，以絕軍後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-33', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備聞公自行，走奔劉表，都等皆散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-34', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」八月，公征劉表，軍西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-35', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '今深入征之，劉備必說劉表以襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-36', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-37', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉表見紹彊，陰與紹通，儁謂表曰：「曹公，天下之雄也，必能興霸道，繼桓、文之功者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-38', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '又劉表自以為宗室，包藏姧心，乍前乍却，以觀世事，據有當州，孤復定之，遂平天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-39', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉表背誕，不供貢職，王師首路，威風先逝，百城八郡，交臂屈膝，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-40', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '魏氏春秋載劉表遺譚書曰：「天篤降害，禍難殷流，尊公殂殞，四海悼心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-41', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣與紹有隙，又與劉表不平而北連公孫瓚；紹與瓚不和而南連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-42', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '劉表字景升，山陽高平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-43', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司馬彪戰略曰：劉表之初為荊州也，江南宗賊盛，袁術屯魯陽，盡有南陽之衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-44', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」言自中平以來，荊州獨全，及劉表為牧，民又豐樂，至建安八年九年當始衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-45', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '始衰者，謂劉表妻死，諸將並零落也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-46', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」華谷去州數百里，即遣馬吏驗視，而劉表果死，縣乃出之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-47', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '越知進必敗，求出為汝陽令，佐劉表平定境內，表得以彊大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-48', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '黃巾起，嵩避難南方，劉表逼以為別駕，轉從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-49', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '為劉表別駕，奉章詣許，見太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-50', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹、劉表咸有威容、器觀，知名當世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-007-51', 'p0102', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '後許汜與劉備並在荊州牧劉表坐，表與備共論天下人，汜曰：「陳元龍湖海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-007-52', 'p0102', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魏氏春秋橫內劉表等數人，皆非事實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-008-53', 'p0102', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '繡領其衆，屯宛，與劉表合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-009-54', 'p0102', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '別征劉表，破表別將於舞陽、陰葉、堵陽、博望，有功，遷厲鋒將軍，封國明亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-55', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」衡南見劉表，表甚禮之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-56', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今送與劉表，視卒當何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-57', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '傅子曰：衡辯於言而剋于論，見荊州牧劉表日，所以自結於表者甚至，表恱之以為上賔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-58', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '衡以交絕於劉表，智窮於黃祖，身死名滅，為天下笑者，譖之者有形也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-59', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '六年，太祖就穀東平之安民，糧少，不足與河北相支，欲因紹新破，以其間擊討劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-60', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-61', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '及紹破敗，臣糧亦盡，以為河北未易圖也，欲南討劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-62', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖將伐劉表，問彧策安出，彧曰：「今華夏已平，南土知困矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-63', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸言於太祖曰：「繡與劉表相恃為彊，然繡以遊軍仰食於表，表不能供也，勢必離。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-64', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '明年，太祖方征劉表，譚、尚爭兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-65', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸曰：「天下方有事，而劉表坐保江、漢之閒，其無四方志可知矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-66', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '傅子曰：詡南見劉表，表以客禮待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-67', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '將此旣新平江、漢，威懾揚、越，資劉表水戰之具，藉荊楚檝櫂之手，實震蕩之良會，廓定之大機。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-68', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會天下義兵起，子伯亦合衆與劉表相依。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-69', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '將避亂荊州，未至，聞劉表政令不明，遂往魯陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-70', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '今袁紹、劉表，雖士民衆彊，皆無經遠之慮，未有樹基建本者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-71', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '不如南向荊州若征劉表者，以待其一變成而後擊之，可一舉定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-72', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-73', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-016-74', 'p0102', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '張晟寇殽、澠閒，南通劉表，固等因之，吾恐其為害深。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-017-75', 'p0102', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '今天子在許，公遠北征，若劉表遣劉備襲許，據之以號令四方，公之勢去矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-76', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉表使劉備北侵，至葉，太祖遣典從夏侯惇拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-77', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖討張繡，劉表遣兵以助繡，太祖軍不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-78', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '紹遣使拜通征南將軍，劉表亦陰招之，通皆拒焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-79', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '文聘字仲業，南陽宛人也，為劉表大將，使禦北方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-80', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '岐為劉表陳其本末，由是益禮賔碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-019-81', 'p0102', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '摯虞文章志曰：劉季緒名脩，劉表子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-82', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '劉表雍容荊楚，坐觀時變，自以為西伯可規。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-83', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖征袁紹，而劉表為紹援，關中諸將又中立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-84', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」廙兄望之，有名於世，荊州牧劉表辟為從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-85', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '廙懼，奔揚州，廙別傳載廙道路為牋謝劉表曰：「考匊過蒙分遇榮授之顯，未有管、狐、桓、文之烈，孤德隕命，精誠不遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-022-86', 'p0102', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '會堅擊劉表戰死，階冒難詣表乞堅喪，表義而與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-022-87', 'p0102', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '乆之，劉表辟為從事祭酒，欲妻以妻妹蔡氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-88', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '荊州劉表無他遠志，愛人樂士，土地險阻，山夷民弱，易依倚也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-89', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲避亂荊州，劉表待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-90', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '九州春秋曰：建安六年，劉表攻西鄂，西鄂長杜子緒帥縣男女嬰城而守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-91', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '避亂荊州，劉表待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-024-92', 'p0102', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '荊州牧劉表禮辟，遂遁逃，南居孱陵界，所在見敬愛，而表深恨之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-028-93', 'p0102', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '博物記曰：初，王粲與族兄凱俱避地荊州，劉表欲以女妻粲，而嫌其形陋而用率，以凱有風貌，乃以妻凱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-028-94', 'p0102', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '凱生業，業即劉表外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-029-95', 'p0102', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '荊州牧劉表令與孟曜為漢主合雅樂，樂備，表欲庭觀之，夔諫曰：「今將軍號為天子合樂，而庭作之，無乃不可乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-96', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-97', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '臣松之案：靈帝崩後，義軍起，孫堅殺荊州刺史王叡，然後劉表為荊州，不與焉同時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-98', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '荊州牧劉表表上焉有似子夏在西河疑聖人之論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-99', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '州大吏趙韙等貪璋溫仁，共上璋為益州刺史，詔書因以為監軍使者，領益州牧，以韙為征東中郎將，率衆擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-100', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-101', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公遣曹仁將兵擊先主，先主還紹軍，陰欲離紹，乃說紹南連荊州牧劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-102', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣麋笁、孫乾與劉表相聞，表自郊迎，以上賔禮待之，益其兵，使屯新野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-103', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」　世語曰：備屯樊城，劉表禮焉，憚其為人，不甚信用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-104', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-105', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉表吏士見從北軍，多叛來投備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-106', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '三輔亂，戩客荊州，劉表以為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-107', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '玄素與荊州牧劉表有舊，往依之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-108', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '獻帝春秋曰：初，豫章太守周術病卒，劉表上諸葛玄為豫章太守，治南昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-109', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '是時曹公方定河北，亮知荊州次當受敵，而劉表性緩，不曉軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-110', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉表長子琦，亦深器亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-036-111', 'p0102', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主背曹公依袁紹、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-036-112', 'p0102', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '荊州牧劉表以為中郎將，與表從子磐共守長沙攸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-113', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '荊州牧劉表及儒者宋忠咸聞其名，遺書與商切致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-114', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主將適荊州，遣笁先與劉表相聞，以笁為左將軍從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-115', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主之背曹公，遣乾自結袁紹，將適荊州，乾又與麋笁俱使劉表，皆如意指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-116', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '少依邑人鎮南將軍劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-039-117', 'p0102', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '劉表亦素不善祥，拘巴，欲殺之，數遣祥故所親信人密詐謂巴曰：「劉牧欲相危害，可相隨逃之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-039-118', 'p0102', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」荊州牧劉表連辟，及舉茂才，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-040-119', 'p0102', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '荊州牧劉表使歷諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-041-120', 'p0102', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '篤卒，荊州牧劉表令峻攝其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-041-121', 'p0102', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '荊州牧劉表以為臨沮長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-042-122', 'p0102', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '明年秋，劉表卒，曹公平荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-123', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」卓曰：「然，但殺二袁、劉表、孫堅，天下自服從孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-124', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初平三年，術使堅征荊州，擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-125', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又云：劉表將呂公將兵緣山向堅，堅輕騎尋山討公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-126', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-127', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-128', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '至沂，築壘自守，告急於劉表，求救於黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-129', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時劉表遣從子虎、南陽韓晞將長矛五千，來為黃祖前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-130', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉表遣將助祖，並來趣臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-131', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '黃祖始被策破，魂氣未反，且劉表君臣本無兼并之志，雖在上流，何辦規擬吳會？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-047-132', 'p0102', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '荊州牧劉表死，魯肅乞奉命弔表二子，且以觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-133', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '殺太守朱皓，獻帝春秋曰：是歲，繇屯彭澤，又使融助皓討劉表所用太守諸葛玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-134', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '劉表從子磐，驍勇，數為寇於艾、西安諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-135', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '朱符死後，漢遣張津為交州刺史，津後又為其將區景所殺，而荊州牧劉表遣零陵賴恭代津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-136', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '漢聞張津死，賜燮璽書曰：「交州絕域，南帶江海，上恩不宣，下義壅隔，知逆賊劉表又遣賴恭闚看南土，今以燮為綏南中郎將，董督七郡，領交阯太守如故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-052-137', 'p0102', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉表所置蒼梧太守吳巨陰懷異心，外附內違。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-053-138', 'p0102', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '次得南陽張津，與荊州牧劉表為隙，兵弱敵彊，歲歲興軍，諸將厭患，去留自在。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-139', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今操得荊州，掩有其地，劉表治水軍，蒙衝鬬艦，乃以千數，操悉浮以沿江，兼有步兵，水陸俱下，此為長江之險，已與我共之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-140', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權曰：「老賊欲廢漢自立乆矣，徒忌二袁、呂布、劉表與孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-141', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '因其多務，勦除黃祖，進伐劉表，竟長江所極，據而有之，然後建號帝王以圖天下，此高帝之業也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-142', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-143', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '止不攻劫，頗讀諸子，乃往依劉表，因居南陽，不見進用，後轉託黃祖，祖又以凡人畜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-144', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '吳書曰：寧將僮客八百人就劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-145', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧已觀劉表，慮旣不遠，兒子又劣，非能承業傳基者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-146', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉表在荊州，民數被寇，自璋在事，寇不入境。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-059-147', 'p0102', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-059-148', 'p0102', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '近袁紹、劉表各有國土，土地非狹，人衆非弱，以適庶不分，遂滅其宗祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-061-149', 'p0102', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '年未三十，荊州牧劉表辟為部江夏從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-063-150', 'p0102', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '明年戊子，荊州劉表亦身死國亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a05-012-151', 'p0102', 'jinshu', 'a05-012', '《晉書·卷十二》', '圖緯舊說，及漢末劉表為荊州牧，命武陵太守劉叡集天文衆占，名荊州占。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a05-036-full-152', 'p0102', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '梁鵠奔劉表，魏武帝破荊州，募求鵠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-080b-0', 'p0103', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '後復侮慢於表，表恥不能容，以江夏太守黃祖性急，故送衡與之，祖亦善待焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-080b-1', 'p0103', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '後黃祖在蒙衝舩上，釋名曰：「外狹而長曰蒙衝，以衝突敵船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-105-2', 'p0103', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '』時天下尚亂，豪桀並爭：曹操事二袁於河北；孫吳創基於江外；劉表阻亂衆於襄陽，南招零、桂，北割漢川，又以黃祖為爪牙，而祖與孫氏為深讎，兵革歲交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-010-3', 'p0103', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '將軍黃祖屯夏口，祖子射與衡善，隨到夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-010-4', 'p0103', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '衡以交絕於劉表，智窮於黃祖，身死名滅，為天下笑者，譖之者有形也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-035-5', 'p0103', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '會黃祖死，得出，遂為江夏太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-6', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '表遣黃祖逆於樊、鄧之間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-7', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '典略曰；堅悉其衆攻表，表閉門，夜遣將黃祖潛出發兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-8', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先君與袁氏共破董卓，功業未遂，卒為黃祖所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-9', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時策西討黃祖，行及石城，聞勳輕身詣海昏，便分遣從兄賁、輔率八千人於彭澤待勳，自與周瑜率二萬人步襲皖城，即克之，得術百工及鼓吹部曲三萬餘人，并術、勳妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-10', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '至沂，築壘自守，告急於劉表，求救於黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-11', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策收得勳兵二千餘人，船千艘，遂前進夏口攻黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-12', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時劉表遣從子虎、南陽韓晞將長矛五千，來為黃祖前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-13', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳錄載策表曰：「臣討黃祖，以十二月八日到祖所屯沙羨縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-14', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫策雖威行江外，略有六郡，然黃祖乘其上流，陳登間其心腹，且深險彊宗未盡歸復，曹、袁虎爭，勢傾山海，策豈暇遠師汝、潁，而遷帝於吳、越哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-15', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '黃祖始被策破，魂氣未反，且劉表君臣本無兼并之志，雖在上流，何辦規擬吳會？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-16', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '勳破，進討黃祖於沙羡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-17', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '八年，權西伐黃祖，破其舟軍，惟城未克，而山寇復動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-18', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二年，西征黃祖，虜其人民而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-19', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-049-20', 'p0103', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '江表傳曰：策初遣慈，議者紛紜，謂慈未可信，或云與華子魚州里，恐留彼為籌策，或疑慈西託黃祖，假路還北，多言遣之非計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-050-21', 'p0103', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '後從討黃祖，中流矢卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-051-22', 'p0103', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時策已平吳、會二郡，賁與策征廬江太守劉勳、江夏太守黃祖，軍旋，聞繇病死，過定豫章，上賁領太守，江表傳曰：時丹楊僮芝自署廬陵太守，策留賁弟輔領兵住南昌，策謂賁曰：「兄今據豫章，是扼僮芝咽喉而守其門戶矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-23', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江夏太守黃祖遣將鄧龍將兵數千人入柴桑，瑜追討擊，生虜龍送吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-24', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '因其多務，勦除黃祖，進伐劉表，竟長江所極，據而有之，然後建號帝王以圖天下，此高帝之業也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-054-25', 'p0103', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '從征黃祖，祖令都督陳就逆以水軍出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-26', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後拜盪寇中郎將，領零陵太守，從討劉勳於尋陽，進攻黃祖於沙羨，還鎮石城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-27', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征劉勳，破黃祖，還討鄱陽，領樂安長，山越畏服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-28', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從策攻皖，又討劉勳於尋陽，伐黃祖於江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-29', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安十三年，權討黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-30', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '止不攻劫，頗讀諸子，乃往依劉表，因居南陽，不見進用，後轉託黃祖，祖又以凡人畜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-31', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '黃祖在夏口，軍不得過，乃留依祖，三年不禮之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-32', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '圖之之計，宜先取黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-33', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '行入右江，斬黃祖將張碩，盡獲船人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-055-34', 'p0103', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權統事，以為別部司馬，授兵五百人，守柴桑長，拒黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-057-35', 'p0103', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '江表傳曰：策討黃祖，旋軍欲過取豫章，特請翻語曰：「華子魚自有名字，然非吾敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-062-36', 'p0103', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '策薨，權為討虜將軍，以綜為金曹從事，從討黃祖，拜鄂長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-063-37', 'p0103', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '初，權在吳，欲討黃祖，範曰：「今茲少利，不如明年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-058-0', 'p0104', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '英雄記云，袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州與紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-070-1', 'p0104', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-072-2', 'p0104', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以尚書韓馥為兾州刺史，英雄記馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-073-3', 'p0104', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '二年，兾州刺史韓馥、勃海太守袁紹及山東諸將議，以朝廷幼沖，時獻帝年十歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-073-4', 'p0104', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '逼迫韓馥，竊奪其州，矯刻金玉，以為印璽，每有所下，輒皁囊施檢，文稱詔書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-5', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初平元年，紹遂以勃海起兵，與從弟後將軍術、兾州牧韓馥、馥字文節，潁川人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-6', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '韓馥見人情歸紹，忌其得衆，恐將圖己，常遣從事守紹門，不聽發兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-7', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '今兾部強實，而韓馥庸才，可密要公孫瓚將兵南下，馥聞必駭懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-8', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '』」並以正直不得志於韓馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-9', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會故兾州牧韓馥懷挾逆謀，欲專權埶，絕臣軍糧，不得踵係，至使猾虜肆毒，害及一門，尊卑大小，同日并戮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-074-10', 'p0104', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '金鼓未震，狡敵知亡，故韓馥懷懼，謝咎歸土，張楊、黑山同時乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a03-108-11', 'p0104', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」吳書載韓馥與袁術書曰：「凶出於代郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-12', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初平元年春正月，後將軍袁術、兾州牧韓馥、英雄記曰：馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-13', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-14', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，袁紹脅韓馥，取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-001-15', 'p0104', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-16', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-17', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹自號車騎將軍，主盟，與兾州牧韓馥立幽州牧劉虞為帝，遣使奉章詣虞，虞不敢受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-006-18', 'p0104', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '仕州別駕，舉茂才，歷二縣令，又為韓馥別駕，表拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-007-19', 'p0104', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案英雄記云：「袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-008-20', 'p0104', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹、韓馥議，以為少帝制於姦臣，天下無所歸心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-008-21', 'p0104', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓馥之迫，竊其虛位，矯命詔恩，刻金印玉璽，每下文書，皁囊施檢，文曰『詔書一封，邟口浪反鄉侯印』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-010-22', 'p0104', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」鄉人多懷土猶豫，會兾州牧同郡韓馥遣騎迎之，莫有隨者，彧獨將宗族至兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-012-23', 'p0104', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '紹劫奪韓馥位，遂據兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-017-24', 'p0104', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '漢末應募討黃巾，為軍司馬，屬韓馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0104-a04-038-25', 'p0104', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-full-0', 'p0105', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-full-1', 'p0105', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '辛未，司隷校尉袁紹勒兵收偽司隷校尉樊陵、河南尹許相及諸閹人，無少長皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-2', 'p0105', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-008-3', 'p0105', 'houhanshu', 'a03-008', '《後漢書·卷八》', '辛未，司隷校尉袁紹勒兵收偽司隷校尉樊陵、河南尹許相及諸閹人，無少長皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-4', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '輕財好施，以任俠聞，為袁紹河內太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-5', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁紹及公孫瓉戰于界橋，今貝州宗城縣東有古界城，近枯漳水，則界橋在此也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-6', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，袁紹遣將麴義與公孫瓉戰於鮑丘，鮑丘，水名，出北塞中，南流經九莊嶺東，俗謂之大榆河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-7', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，袁紹自為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-8', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '四年春三月，袁紹攻公孫瓉于易京，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-9', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操與袁紹戰於官度，裴松之北征記曰：「中牟臺下臨汴水，是為官度，袁紹、曹操壘尚存焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-009-10', 'p0105', 'houhanshu', 'a03-009', '《後漢書·卷九》', '七年夏五月庚戌，袁紹薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-035-11', 'p0105', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '時大將軍袁紹緫兵兾州，遣使要玄，大會賔客，玄最後至，乃延升上坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-035-12', 'p0105', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '時袁紹與曹操相拒於官度，官度，津名也，在今鄭州中牟縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-048-13', 'p0105', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '劭畏操誅，弃郡奔兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-048-14', 'p0105', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '二年，詔拜劭為袁紹軍謀校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-049-15', 'p0105', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '并州刺史高幹，袁紹甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-052-16', 'p0105', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '獻帝初，鈞與袁紹俱起兵山東，董卓以是收烈付郿獄，錮之，鋃鐺鐵鎖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-17', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '勳時與宗正劉虞、佐軍校尉袁紹同典禁兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-18', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '行至河閒而值幽兾交兵，行塗阻絕，因寓於袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-19', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '在事二年，袁紹憚其能，徙為東郡太守，都東武陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-20', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '英雄記云，袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州與紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-21', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '進敗，揚遂以所將兵攻上黨，仍略諸縣，衆至數千，又與袁紹合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-22', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '足下徼利於境外，臧洪投命於君親；吾子託身於盟主，盟主謂袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-058-23', 'p0105', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '城中粮盡，外無援救，洪自度不免，呼吏士謂曰：「袁紹無道，所圖不軌，且不救洪郡將，洪於大義，不得不死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-062-24', 'p0105', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '建安初，袁紹為太尉，讓於紀；紀不受，拜大鴻臚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-064-25', 'p0105', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '是時袁紹、曹操與公孫瓚爭兾州，紹及操聞歧至，皆自將兵數百里奉迎，歧深陳天子恩德，宜罷兵安人之道，又移書公孫瓚，為言利害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-067-26', 'p0105', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '袁紹慕之，私與往來，結為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-068-27', 'p0105', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '同郡袁紹，公族豪俠，去濮陽令歸，車徒甚盛，將入郡界，乃謝遣賔客，曰：「吾輿服豈可使許子將見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-28', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '是時置西園八校尉，以小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎都尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍校尉，淳于瓊為佐軍校尉，又有左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-29', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '進陰知其謀，乃上遣袁紹東擊徐兖二州兵，須紹還，即戎事，以稽行期。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-30', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹亦素有謀，因進親客張津勸之曰：「黃門常侍權重日乆，又與長樂太后專通姦利，靈帝母董太后居長樂宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-31', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹復說進曰：「前竇武欲誅內寵而反為所害者，以其言語漏泄，而五營百官服畏中人故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-32', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」袁紹勸進便於此決之，至于再三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-069-33', 'p0105', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹與叔父隗矯詔召樊陵、許相，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-34', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業等與侍中伍瓊、卓長史何顒共說卓，以袁紹為勃海太守，以發山東之謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-35', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '袁紹傳，熙，紹之中子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-36', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧比至兾州，而袁紹已奪馥位，紹待彧以上賔之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-37', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '袁紹旣兼河朔之地，有驕氣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-38', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '五年，袁紹率大衆以攻許，操與相距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-39', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-40', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」後皆如彧之籌，事在袁紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-070-41', 'p0105', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '十二年，操上書表彧曰：「昔袁紹作逆，連兵官度，時衆寡糧單，圖欲還許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-071-42', 'p0105', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '其後諸賊多為袁紹所定，事在紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-072-43', 'p0105', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及帝崩，大將軍何進、司隷校尉袁紹謀誅閹宦，而太后不許，乃私呼卓將兵入朝，以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-072-44', 'p0105', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初平元年，馥等到官，與袁紹之徒十餘人，各興義兵，同盟討卓，而伍瓊、周珌陰為內主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-45', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '二年，兾州刺史韓馥、勃海太守袁紹及山東諸將議，以朝廷幼沖，時獻帝年十歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-46', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '和尋得逃術還北，復為袁紹所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-47', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚乃誣虞前與袁紹等欲稱尊號，脅訓斬虞於薊市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-48', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '術遣越隨其將孫堅，擊袁紹將周昕，越為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-49', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '今車騎將軍袁紹，託承先軌，爵任崇厚，而性本淫亂，情行浮薄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-50', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '烏桓峭王感虞恩德，率種人及鮮卑七千餘騎，共輔南迎虞子和，與袁紹將麴義合兵十萬，共攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-073-51', 'p0105', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '建安三年，袁紹復大攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-52', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹字本初，汝南汝陽人，司徒湯之孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-53', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-54', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '山陽公載記曰：「卓以袁紹棄節，改第一葆為赤旄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-55', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹不達大體，恐懼出奔，非有它志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-56', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後袁紹至，馥從事十人棄馥去，唯恐在後，獨武、純杖刀拒，兵不能禁，紹後令田豐殺此二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-57', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁紹孤客窮軍，仰我鼻息，譬如嬰兒在股掌之上，絕其哺乳，立可餓殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-58', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏志曰：「琳字孔璋，廣陵人，避難兾州，袁紹使典文章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-074-59', 'p0105', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」典論曰：「袁紹妻劉氏性酷妒，紹死，僵尸未殯，寵妾五人盡殺之，為死者有知，當復見紹於地下，乃髡頭墨面，以毀其形。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-60', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '然而河北異謀於黑山，謂袁紹為兾州牧，與黑山賊相連。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-61', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '有頃，布得走投袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-075-62', 'p0105', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '及袁紹為盟主，有驕色，邈正義責之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-078-63', 'p0105', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '雖袁紹龔行，芟夷無餘，然以暴易亂，亦何云及！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-078-64', 'p0105', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中軍校尉袁紹說大將軍何進，令誅中官以恱天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-090-65', 'p0105', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-090-66', 'p0105', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁紹因寵慰柔，以安北邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-102-67', 'p0105', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-102-68', 'p0105', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」至六年，司隷校尉袁紹誅滅中官，大將軍部曲將吳匡攻殺車騎將軍何苗，死者數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-103-69', 'p0105', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時靈帝新棄羣臣，大行尚在梓宮，大將軍何進與佐軍校尉袁紹等共謀欲誅廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-103-70', 'p0105', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '建安三年，袁紹攻瓚，瓚大敗，縊其姊妹妻子，引火自焚，紹兵趣登臺斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-111-71', 'p0105', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '東有地烏巢，曹公破袁紹處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a03-118-72', 'p0105', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '故焉牧益土，造帝服於岷、峨；袁紹取兾，下制書於燕、朔；劉表荊南，郊天祀地；魏祖據兖，遂構皇業：漢之殄滅，禍源乎此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-73', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '大將軍何進與袁紹謀誅宦官，太后不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-74', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹之在勃海，馥恐其興兵，遣數部從事守之，不得動搖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-75', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-76', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-77', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，袁紹脅韓馥，取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-78', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹因表太祖為東郡太守，治東武陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-79', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是以袁紹為太尉，紹恥班在公下，不肯受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-80', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹之在河北，軍人仰食桑椹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-81', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝春秋曰：袁紹叛卒詣公云：「田豐使紹早襲許，若挾天子以令諸侯，四海可指麾而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-82', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-83', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-84', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時袁紹旣并公孫瓚，兼四州之地，衆十餘萬，將進軍攻許，諸將以為不可敵，公曰：「吾知紹之為人，志大而智小，色厲而膽薄，忌克而少威，兵多而分畫不明，將驕而政令不一，土地雖廣，糧食雖豐，適足以為吾奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-85', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公將自東征備，諸將皆曰：「與公爭天下者，袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-86', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹雖有大志，而見事遟，必不動也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-87', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹運穀車數千乘至，公用荀攸計，遣徐晃、史渙邀擊，大破之，盡燒其車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-88', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-89', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-90', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁紹以甥高幹領并州牧，公之拔鄴，幹降，遂以為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-91', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹皆立其酋豪為單于，以家人子為己女，妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-92', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '及袁紹與弟術喪母，歸葬汝南，儁與公會之，會者三萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-93', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '及至袁紹據河北，兵勢彊盛，孤自度勢，實不敵之，但計投死為國，以義滅身，足垂於後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-94', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹逆亂天常，謀危社稷，憑恃其衆，稱兵內侮，當此之時，王師寡弱，天下寒心，莫有固志，君執大節，精貫白日，奮其武怒，運其神策，致屆官渡，大殲醜類，詩曰：「致天之屆，于牧之野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-95', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '傅子曰：漢末王公，多委王服，以幅巾為雅，是以袁紹、崔豹之徒，雖為將帥，皆著縑巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-001-96', 'p0105', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '評曰：漢末，天下大亂，雄豪並起，而袁紹虎眎四州，彊盛莫敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-005-97', 'p0105', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '建安中，袁紹為中子熈納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-98', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進與司隷校尉袁紹謀誅諸閹官，太后不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-99', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獲袁紹豫州從事李延，煑殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-100', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹字本初，汝南汝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-101', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹孤客窮軍，仰我鼻息，譬如嬰兒在股掌之上，絕其哺乳，立可餓殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-102', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '匡受袁紹旨，收班繫獄，欲殺之以徇軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-103', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹起義，卑辭厚幣以招致豐，豐以王室多難，志存匡救，乃應紹命，以為別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-104', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹領兾州，委以腹心之任，以為治中別駕，并總幕府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-105', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹遣袁遺領州，敗散，奔沛國，為兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-106', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '天子都許，表雖遣使貢獻，然北與袁紹相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-107', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖與袁紹方相持於官渡，紹遣人求助，表許之而不至，亦不佐太祖，欲保江漢間，觀天下變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-108', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '夫以曹公之明哲，天下賢俊皆歸之，其勢必舉袁紹，然後稱兵以向江漢，恐將軍不能禦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-006-109', 'p0105', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹、劉表咸有威容、器觀，知名當世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-110', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '北詣袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-111', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁紹旣為盟主，有驕矜色，邈正議責紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-112', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-113', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '而袁紹見洪，又奇重之，與結分合好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-007-114', 'p0105', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案英雄記云：「袁紹使張景明、郭公則、高元才等說韓馥，使讓兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-115', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹、韓馥議，以為少帝制於姦臣，天下無所歸心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-116', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '今行車騎將軍袁紹，託其先軌，寇竊人爵，旣性暴亂，厥行淫穢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-117', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹又遣麴義及虞子和，將兵與輔合擊瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-118', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」是以袁紹始北擊之時，瓚南界上別營自度守則不能自固，又知必不見救，是以或自殺其將帥，或為紹兵所破，遂令紹軍徑至其門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-119', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：袁紹與瓚書曰：「孤與足下，旣有前盟舊要，申以討亂之誓，愛過夷、叔，分著丹青，謂為流力同仇，足踵齊、晉，故解印釋紱，以北帶南，分割膏腴，以奉執事，此非孤赤情之明驗邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-120', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '將軍堅守曠日，袁紹要當自退；自退之後，四方之衆必復可合也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-121', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：袁紹分部攻者掘地為道，穿穴其樓下，稍稍施木柱之，度足達半，便燒所施之柱，樓輒傾倒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-122', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖與袁紹相拒於官渡，閻柔遣使詣太祖受事，遷護烏丸校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-123', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹破走，太祖喜，顧謂輔曰：「如前歲本初送公孫瓚頭來，孤自視忽然耳，而今克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-124', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖及袁紹等皆為校尉，屬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-125', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝紀曰：以虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融、馮芳為助軍校尉，夏牟、淳于瓊為左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-126', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹至河內，楊與紹合，復與匈奴單于於夫羅屯漳水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-127', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其將楊醜殺楊以應太祖，楊將眭固殺醜，將其衆，欲北合袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-128', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹與公孫瓚爭兾州，燕遣將杜長等助瓚，與紹戰，為紹所敗，人衆稍散，太祖將定兾州，燕遣使求佐王師，拜平北將軍；率衆詣鄴，封安國亭侯，邑五百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-008-129', 'p0105', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '太祖拒袁紹於官渡，繡從賈詡計，復以衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-009-130', 'p0105', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '及與袁紹戰於官渡，行督軍校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-009-131', 'p0105', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖與袁紹乆相持於官渡，紹遣劉備徇㶏彊諸縣，多舉衆應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-132', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '而袁紹已奪馥位，待彧以上賔之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-133', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '自太祖之迎天子也，袁紹內懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-134', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今與公爭天下者，唯袁紹爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-135', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-136', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧第四兄諶，字友若，事見袁紹傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-137', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧別傳曰：太祖又表曰：「昔袁紹侵入郊甸，戰於官渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-138', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔公在官渡與袁紹相持，恐增內顧之念，故不言爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-139', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒旣奇太祖而知荀彧，袁紹慕之，與為奔走之友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-140', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '袁紹渡河追，卒與太祖遇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-141', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是後，太祖拒袁紹於官渡，紹遣人招繡，并與詡書結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-010-142', 'p0105', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '袁紹圍太祖於官渡，太祖糧方盡，問詡計焉出，詡曰：「公明勝紹，勇勝紹，用人勝紹，決機勝紹，有此四勝而半年不定者，但顧萬全故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-143', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹數遣使招命，又即授將軍印，因安輯所統，疇皆拒不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-144', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '及袁紹父子威力加於朔野，遠結烏丸，與為首尾，前後召疇，終不陷撓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-145', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '臣松之以為田疇不應袁紹父子之命，以其非正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-146', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹又辟脩除即墨令，後復為譚別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-147', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁紹前後辟命，不應，移居上黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-011-148', 'p0105', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '胡昭始避地兾州，亦辭袁紹之命，遁還鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-149', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏氏春秋曰：袁紹之敗也，融與太祖書曰：「武王伐紂，以妲己賜周公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-150', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '南陽許攸、魏略曰：攸字子遠，少與袁紹及太祖善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-151', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '今袁紹、劉表，雖士民衆彊，皆無經遠之慮，未有樹基建本者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-152', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時太子未定，而臨菑侯植有寵，玠密諫曰：「近者袁紹以嫡庶不分，覆宗滅國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-153', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '信知卓必為亂，勸袁紹襲卓，紹畏卓不敢發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-012-154', 'p0105', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖與袁紹表信行破虜將軍，韜裨將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-013-155', 'p0105', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖在官渡，與袁紹相持，繇送馬二千餘匹給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-156', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '是時岱與袁紹、公孫瓚和親，紹令妻子居岱所，瓚亦遣從事范方將騎助岱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-157', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫公孫瓚，非袁紹之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-158', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '於是袁紹使人說太祖連和，欲使太祖遷家居鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-159', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時昱使適還，引見，因言曰：「竊聞將軍欲遣家，與袁紹連和，誠有之乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-160', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫袁紹據燕、趙之地，有并天下之心，而智不能濟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-161', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '今聞將軍欲遣家往鄴，將北面而事袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-162', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫以將軍之聦明神武，而反不羞為袁紹之下，竊為將軍恥之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-163', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昱不肯，曰：「袁紹擁十萬衆，自以所向無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-164', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-165', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策轉鬬千里，盡有江東，聞太祖與袁紹相持於官渡，將渡江北襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-166', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖欲速征劉備，議者懼軍出，袁紹擊其後，進不得戰而退失所據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-167', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '從破袁紹，紹死，又從討譚、尚於黎陽，連戰數克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-168', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '諸將欲乘勝遂攻之，嘉曰：「袁紹愛此二子，莫適立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-169', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '且袁紹有恩於民夷，而尚兄弟生存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-170', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '舉孝廉，除廮陶長、栢人令，袁紹以為參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-171', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹遣將顏良攻東郡，又徙昭為魏郡太守，從討良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-172', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹同族春卿為魏郡太守，在城中，其父元長在楊州，太祖遣人迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-173', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-014-174', 'p0105', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自破袁紹，北拔柳城，南向江、漢，荊州交臂，威震天下，民無他志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-015-175', 'p0105', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖方有袁紹之難，謂馥可任以東南之事，遂表為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-016-176', 'p0105', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後袁紹在兾州，亦貪祗，欲得之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-177', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '袁紹破，別遣遼定魯國諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-178', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '渡河攻獲嘉，還，從擊袁紹於官渡，力戰，斬紹將淳于瓊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-179', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖初征袁紹，紹兵盛，禁願為先登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-180', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖與袁紹相拒於官渡，漢晉春秋曰：郃說紹曰：「公雖連勝，然勿與曹公戰也，密遣輕騎鈔絕其南，則兵自敗矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-181', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-182', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與曹洪擊彊賊祝臂，破之，又與史渙擊袁紹運車於故市，功最多，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-183', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '初，清河朱靈為袁紹將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-017-184', 'p0105', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '九州春秋曰：初，清河季雍以鄃叛袁紹而降公孫瓚，瓚遣兵衞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-185', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '時太祖與袁紹相拒官渡，典率宗族及部曲輸穀帛供軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-186', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖與袁紹相拒於官渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-187', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '詔曰：「昔袁紹之難，自許、蔡以南，人懷異心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-188', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '時太祖方與袁紹相拒，而霸數以精兵入青州，故太祖得專事紹，不以東方為念。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-018-189', 'p0105', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '袁紹所置中郎將郭祖、公孫犢等數十輩，保山為寇，百姓苦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-190', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖置酒漢濵，粲奉觴賀曰：「方今袁紹起河北，杖大衆，志兼天下，然好賢而不能用，故奇士去之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-191', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '琳避難兾州，袁紹使典文章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-192', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖征袁紹，而劉表為紹援，關中諸將又中立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-021-193', 'p0105', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '夫夷狄之臣，不當兾州之卒，權、備之籍，不比袁紹之業，然本初以亡，而二寇未捷，非闇弱於今而智武於昔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-022-194', 'p0105', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後太祖與袁紹相拒於官渡，表舉州以應紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-022-195', 'p0105', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '當袁紹、公孫瓚交兵，幽兾饑荒，養寡嫂孤兄子，以學行見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-196', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '袁紹在兾州，遣使迎汝南士大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-197', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '袁紹公族好名，為濮陽長，棄官來還，有副車從騎，將入郡界，紹乃歎曰：「吾之輿服，豈可使許子將見之乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-198', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '少孤苦，袁紹父子時，始為名吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-199', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時袁紹舉兵南侵，遣使招誘豫州諸郡，諸郡多受其命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-023-200', 'p0105', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏略曰：太祖北拒袁紹，時遠近無不私遺牋記，通意於紹者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-024-201', 'p0105', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '柔從兄幹，袁紹甥也，謝承後漢書曰：幹字元才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-202', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '時袁紹盛於河朔，而汝南紹之本郡，門生賔客布在諸縣，擁兵拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-203', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '公孫瓚使豫守東州令，瓚將王門叛瓚，為袁紹將萬餘人來攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-026-204', 'p0105', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '兾州牧袁紹辟為督軍從事，兼領烏丸突騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-027-205', 'p0105', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '武皇帝克袁紹於官渡，自以所獲已多，不復追奔，懼挫威也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-206', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '會袁紹兼河北，乃撫有三郡烏丸，寵其名王而收其精騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-207', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-030-208', 'p0105', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '部落近塞，自袁紹據河北，中國人多亡叛歸之，教作兵器鎧楯，頗學文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-209', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-210', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-211', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：陳登等遣使詣袁紹曰：「天降灾沴，禍臻鄙州，州將殂殞，生民無主，恐懼姦雄一旦承隙，以貽盟主日昃之憂，輒共奉故平原相劉備府君以為宗主，永使百姓知有依歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-212', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁術欲經徐州北就袁紹，曹公遣先主督朱靈、路招要擊術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-213', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-032-214', 'p0105', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公與袁紹相拒於官渡，汝南黃巾劉辟等叛曹公應紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-035-215', 'p0105', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曹操比於袁紹，則名微而衆寡，然操遂能克紹，以弱為彊者，非惟天時，抑亦人謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-216', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '建安五年，曹公東征，先主奔袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-217', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主背曹公依袁紹、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-218', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-219', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '時袁紹稱兾州牧，瓚深憂州人之從紹也，善雲來附，嘲雲曰：「聞貴州人皆願袁氏，君何獨迴心，迷而能反乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-036-220', 'p0105', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」先主就袁紹，雲見於鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-038-221', 'p0105', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主之背曹公，遣乾自結袁紹，將適荊州，乾又與麋笁俱使劉表，皆如意指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-222', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '袁紹遣會稽周㬂為豫州刺史，來襲取州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-223', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '山陽公載記曰：瑀單騎走兾州，自歸袁紹，紹以為故安都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-224', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '建安五年，曹公與袁紹相拒於官渡，策陰欲襲許，迎漢帝，吳錄曰：時有高岱者，隱於餘姚，策命出使會稽丞陸昭逆之，策虛己候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-225', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '案夏侯元讓與石威則書「袁紹破後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-226', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又案袁紹以建安五年至黎陽，而策以四月遇害，而志云策聞曹公與紹相拒於官渡，謬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-046-227', 'p0105', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '案魏武紀，武帝以建安四年已出屯官渡，乃策未死之前，乆與袁紹交兵，則國志所云不為謬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-054-228', 'p0105', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江表傳曰：曹公新破袁紹，兵威日盛，建安七年，下書責權質任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-054-229', 'p0105', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-059-230', 'p0105', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0105-a04-059-231', 'p0105', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '近袁紹、劉表各有國土，土地非狹，人衆非弱，以適庶不分，遂滅其宗祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-009-0', 'p0106', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十年春正月，曹操破袁譚於青州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-070-1', 'p0106', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '建安元年，為袁譚所攻，自春至夏，戰士所餘裁數百人，流矢雨集，戈矛內接。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-075-2', 'p0106', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術因欲北至青州從袁譚，曹操使劉備徼之，不得過，復走還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a03-105-3', 'p0106', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十年，曹操破袁譚於南皮；十一年，走袁尚於遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-001-4', 'p0106', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術自敗於陳，稍困，袁譚自青州遣迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-001-5', 'p0106', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟師洪河，拓定四州，袁譚、高幹，咸梟其首，海盜奔迸，黑山順軌，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-006-6', 'p0106', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '將歸帝號於紹，欲至青州從袁譚，發病道死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-008-7', 'p0106', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '從破袁譚於南皮，復增邑凡二千戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-8', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-9', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '七年，從討袁譚、尚於黎陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-010-10', 'p0106', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸曰：「佐治為袁譚乞降，王師自往平之，吾何知焉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-11', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '疇此舉止，良為進退無當，與王脩哭袁譚，貌同而心異也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-12', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁譚在青州，辟脩為治中從事，別駕劉獻數毀短脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-011-13', 'p0106', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '傅子曰：太祖旣誅袁譚，梟其首，令曰：「敢哭之者戮及妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-012-14', 'p0106', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '遂為袁譚所攻，自春至夏，城小寇衆，流矢雨集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-012-15', 'p0106', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '郡濵山海，黃巾未平，豪傑多背叛，袁譚就加以官位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-16', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱收山澤亡命，得精兵數千人，乃引軍與太祖會黎陽，討袁譚、袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-17', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-014-18', 'p0106', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖討袁譚於南皮，以書招松，松舉雍奴、泉州、安次以附之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-015-19', 'p0106', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會尚不能救鄴，破走至中山，而袁譚又追擊尚，尚走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-20', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討袁譚、袁尚於黎陽，有功，行中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-21', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從攻袁譚，譚破，別將徇海濵，破遼東賊柳毅等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-22', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從圍鄴，鄴定，從擊袁譚於南皮，先登，入譚東門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-23', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又從擊袁譚於渤海，別將軍圍雍奴，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-017-24', 'p0106', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破袁譚於南皮，討平原叛賊，克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-018-25', 'p0106', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖破袁譚於南皮，霸等會賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-018-26', 'p0106', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-026-27', 'p0106', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖將討袁譚，而柳城烏丸欲出騎助譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-032-28', 'p0106', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '青州刺史袁譚，先主故茂才也，將步騎迎先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0106-a04-052-29', 'p0106', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '然徽潛采聽，方與袁譚交爭，未有他意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-009-0', 'p0107', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九年秋八月戊寅，曹操大破袁尚，平兾州，自領兾州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-009-1', 'p0107', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-090-2', 'p0107', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁尚與樓班、烏延等皆走遼東，遼東太守公孫康並斬送之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a03-105-3', 'p0107', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十年，曹操破袁譚於南皮；十一年，走袁尚於遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-001-4', 'p0107', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」將北征三郡烏丸，諸將皆曰：「袁尚，亡虜耳，夷狄貪而無親，豈能為尚用？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-001-5', 'p0107', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '烏丸三種，崇亂二世，袁尚因之，逼據塞北，束馬縣車，一征而滅，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-005-6', 'p0107', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '世語曰：太祖下鄴，文帝先入袁尚府，有婦人被髮垢靣，垂涕立紹妻劉後，文帝問之，劉荅「是熈妻」，顧擥髮髻，以巾拭面，姿貌絕倫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-008-7', 'p0107', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁尚等奔遼東，康斬送尚首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-8', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前日公破袁尚，禽審配，海內震駭，必人人自恐不得保其土地，守其兵衆也；今使分屬兾州，將皆動心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-9', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-010-10', 'p0107', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖之征袁尚也，高幹密遣兵謀襲鄴，衍逆覺，盡誅之，以功封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-11', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '遼東斬送袁尚首，令「三軍敢有哭之者斬」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-12', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '致使袁尚奔迸，授首遼東，皆疇之由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-011-13', 'p0107', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '臣松之案田疇傳，疇為袁尚所辟，不被譚命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-013-14', 'p0107', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」其後匈奴單于作亂平陽，繇帥諸軍圍之，未拔；而袁尚所置河東太守郭援到河東，衆甚盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-013-15', 'p0107', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-16', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱收山澤亡命，得精兵數千人，乃引軍與太祖會黎陽，討袁譚、袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-17', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-18', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-014-19', 'p0107', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後袁尚依烏丸蹋頓，太祖將征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-015-20', 'p0107', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '袁尚拒太祖於黎陽，遣所置河東太守郭援、并州刺史高幹及匈奴單于取平陽，發使西與關中諸將合從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-015-21', 'p0107', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安中，袁尚領冀州，以孚為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-017-22', 'p0107', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討袁譚、袁尚於黎陽，有功，行中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-017-23', 'p0107', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征袁尚於柳城，卒與虜遇，遼勸太祖戰，氣甚奮，太祖壯之，自以所持麾授遼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-021-24', 'p0107', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-025-25', 'p0107', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及袁尚攻兄譚於平原，譚使毗詣太祖求和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-025-26', 'p0107', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '天以袁尚與明公，明公不取而伐荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-026-27', 'p0107', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '還鄴，遼東送袁尚首，縣在馬市，招覩之悲感，設祭頭下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-028-28', 'p0107', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '右北平烏丸單于寇婁敦、遼西烏丸都督率衆王護留等，昔隨袁尚奔遼東者，率衆五千餘人降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-030-29', 'p0107', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後袁尚敗奔蹋頓，憑其勢，復圖兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-030-30', 'p0107', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '右北平烏丸單于寇婁敦、遼西烏丸都督率衆王護留葉，昔隨袁尚奔遼西，聞儉軍至，率衆五千餘人降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0107-a04-038-31', 'p0107', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後表與袁尚書，說其兄弟分爭之變，曰：「每與劉左將軍、孫公祐共論此事，未甞不痛心入骨，相為悲傷也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a03-009-0', 'p0108', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a03-070-1', 'p0108', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，曹操攻屠鄴城，袁氏婦子多見侵略，而操子丕私納袁熙妻甄氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0108-a04-001-2', 'p0108', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是月，袁熙大將焦觸、張南等叛攻熙、尚，熙、尚奔三郡烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-008-full-0', 'p0109', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-008-1', 'p0109', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-2', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」將作大匠吳脩、越騎校尉王瓌安集關東，後將軍袁術、河內太守王匡各執而殺之，英雄記曰：「匡字公節，太山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-3', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-4', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-5', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，袁術殺楊州刺史陳溫，據淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-6', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-009-7', 'p0109', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二年春，袁術自稱天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-031-8', 'p0109', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '時袁術屯兵壽春，部曲飢餓，遣使求委輸兵甲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-031-9', 'p0109', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '幼年曾謁袁術，懷橘墯地者也，有名稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-048-10', 'p0109', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '獻帝遷許，以廷尉徵，當詣京師，道為袁術所劫，授璆以上公之位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-048-11', 'p0109', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '袁術有僭盜意，乃拘堅妻求之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-full-12', 'p0109', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '後袁術求糧於陳而俊拒絕之，術忿恚，遣客詐殺俊及寵，陳由是破敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-full-13', 'p0109', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '袁術使部曲將張闓陽私行到陳，之俊所，俊往從飲酒，因詐殺俊，一郡吏人哀號如喪父母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-14', 'p0109', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '後袁術求糧於陳而俊拒絕之，術忿恚，遣客詐殺俊及寵，陳由是破敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-050-15', 'p0109', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '袁術使部曲將張闓陽私行到陳，之俊所，俊往從飲酒，因詐殺俊，一郡吏人哀號如喪父母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-054-16', 'p0109', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '時袁術僭亂，操託彪與術婚姻，誣以欲圖廢置，奏收下獄，劾以大逆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-054-17', 'p0109', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '且以袁術之甥，慮為後患，遂因事殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-066-18', 'p0109', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '乃上護羌校尉楊瓚行左將軍事，執金吾士孫瑞為南陽太守，並將兵出武關道，以討袁術為名，實欲分路征卓，而後拔天子還洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-069-19', 'p0109', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁術與匡共斫攻之，中黃門持兵守閤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-20', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '事洩，顒等被執，公業脫身自武關走，東歸袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-21', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，太傅馬日磾奉使山東，及至淮南，數有意於袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-22', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '又袁術僭逆，非一朝一夕，日磾隨從，周旋歷歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-070-23', 'p0109', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」前以露袁術之罪，今復下劉表之事，是使跛牂欲闚高岸，天險可得而登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-24', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」卓未至而何進敗，虎賁中郎將袁術乃燒南宮，欲討宦官，而中常侍段珪等山陽公載記「段」字作「殷」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-25', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃使人誣衞尉張溫與袁術交通，遂笞溫於市，殺之，以塞天變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-072-26', 'p0109', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」奉、暹奔袁術，遂縱暴楊、徐閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-073-27', 'p0109', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '道由南陽，後將軍袁術聞其狀，遂質和，使報虞遣兵俱西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-073-28', 'p0109', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚旣諫劉虞遣兵就袁術，而懼術知怨之，乃使從弟越將千餘騎詣術自結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-074-29', 'p0109', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」袁術亦執殺陰循，惟韓融以名德免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-074-30', 'p0109', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時袁術僭亂，操託彪與術婚姻，誣以欲圖廢置，奏收下獄，劾以大逆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-31', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術字公路，汝南汝陽人，司空逢之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-32', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術登城，見而恱之，遂納焉，甚愛幸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-33', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '邈詣袁術求救，留超將家屬屯雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-34', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時劉備領徐州，居下邳，與袁術相拒於淮上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-35', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '尚依袁術，術僭號，欲以尚為太尉，不敢顯言，私使諷之，術亦不敢強也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-36', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今與袁術結姻，必受不義之名，將有累卵之危矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-37', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-38', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今袁術造逆，宜共誅討，柰何與賊還來伐布？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-39', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '建安二年，布遂復從袁術，遣順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-075-40', 'p0109', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '而潛遣人求救於袁術，自將千餘騎出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-076-41', 'p0109', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '時袁術據淮南，繇乃移居曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-076-42', 'p0109', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '袁術遣孫策攻破繇，因奔豫章，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-108-43', 'p0109', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」吳書載韓馥與袁術書曰：「凶出於代郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-110-44', 'p0109', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '地道記曰有公路城，袁術所築。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a03-111-45', 'p0109', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '匡人之亭，曹公破袁術處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-46', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初平元年春正月，後將軍袁術、兾州牧韓馥、英雄記曰：馥字文節，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-47', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '英雄記曰：紹後用遺為揚州刺史，為袁術所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-48', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-49', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是歲，孫策受袁術使渡江，數年閒遂有江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-50', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '邈詣袁術請救，為其衆所殺，兖州平，遂東略陳地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-51', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '建安元年春正月，太祖軍臨武平，袁術所置陳相袁嗣降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-52', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-53', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-54', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '冬十月，公征奉，奉南奔袁術，遂攻其梁屯，拔之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-55', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術在江、淮，取給蒲蠃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-56', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術欲稱帝於淮南，使人告呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-57', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-58', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術自敗於陳，稍困，袁譚自青州遣迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-59', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '被徵當還，為袁術所劫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-60', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '又袁術僭號於九江，下皆稱臣，名門曰建號門，衣被皆為天子之制，兩婦預爭為皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-001-61', 'p0109', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術僭逆，肆於淮南，懾憚君靈，用丕顯謀，蘄陽之役，橋蕤授首，稜威南邁，術以隕潰，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-003-62', 'p0109', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '獻帝傳曰：朗父名宜祿，為呂布使詣袁術，術妻以漢宗室女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-005-63', 'p0109', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '袁術傳太祖凶問，時太祖左右至洛者皆欲歸，后止之曰：「曹君吉凶未可知，今日還家，明日若在，何靣目復相見也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-64', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉張溫時為衞尉，素不善卓，卓心怨之，因天有變，欲以塞咎，使人言溫與袁術交關，遂笞殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-65', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，太祖遣劉備詣徐州拒袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-66', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術字公路，司空逢子，紹之從弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-67', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '坐櫺牀上，歎息良乆，乃大咤曰：「袁術至於此乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-68', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司馬彪戰略曰：劉表之初為荊州也，江南宗賊盛，袁術屯魯陽，盡有南陽之衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-69', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表曰：「宗賊甚盛，而衆不附，袁術因之，禍今至矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-70', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術勇而無斷，蘇代、具羽皆武人，不足慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-71', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術之在南陽也，與孫堅合從，欲襲奪表州，使堅攻表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-72', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術奢淫放肆，榮不終己，自取之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-006-73', 'p0109', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術無豪芒之功，纖介之善，而猖狂于時，妄自尊立，固義夫之所扼腕，人鬼之所同疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-74', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '將數百騎出武關，欲詣袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-75', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '邈詣袁術請救未至，自為其兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-76', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '獻帝春秋曰：袁術議稱尊號，邈謂術曰：「漢據火德，絕而復揚，德澤豐流，誕生明公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-77', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '英雄記曰：布初入徐州，書與袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-78', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布問性，言「萌受袁術謀，謀者悉誰？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-79', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-80', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '重見購捕袁術等詔書，布當以命為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-81', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁術稱天子，將軍止之，而使不通章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-007-82', 'p0109', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今袁術造逆，當共誅討，奈何與賊臣還共伐布？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-83', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」　吳書曰：馥以書與袁術，云帝非孝靈子，欲依絳、灌誅廢少主，迎立代王故事；稱虞功德治行，華夏少二，當今公室枝屬皆莫能及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-84', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '和道經袁術，為說天子意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-008-85', 'p0109', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '臣又每得後將軍袁術書，云紹非術類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-86', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '袁術聞而壯之，以為騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-87', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖之破袁術，仁所斬獲頗多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-009-88', 'p0109', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '興平末，袁術部黨與太祖攻劫，太祖出，為寇所追，走入秦氏，伯南開門受之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-89', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '破布，然後南結揚州，共討袁術，以臨淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-90', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '以督軍御史中丞詣揚州討袁術，會術病卒，因以為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-91', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '而袁術亦豪俠，與紹爭名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-010-92', 'p0109', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '布驍猛，又恃袁術，若從橫淮、泗間，豪傑必應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-011-93', 'p0109', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '後避地江、淮間，為袁術所命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-011-94', 'p0109', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '袁術備禮招請，範稱疾不往，術不彊屈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-95', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '續漢書曰：太尉楊彪與袁術婚姻，術僭號，太祖與彪有隙，因是執彪，將殺焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-96', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '後袁術至壽春，辟之，夔不應，然遂為術所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-012-97', 'p0109', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '時有傳袁術軍亂者，太祖問夔曰；「君以為信不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-98', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後又遣備至徐州要擊袁術，昱與郭嘉說太祖曰：「公前日不圖備，昱等誠不及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-99', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會太祖使備要擊袁術，嘉與程昱俱駕而諫太祖曰：「放備，變作矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-100', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '奉、暹失衆，東降袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-014-101', 'p0109', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-015-102', 'p0109', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '避亂揚州，建安初，說袁術將戚寄、秦翊，使率衆與俱詣太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-016-103', 'p0109', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後將軍袁術以為揚州刺史，未至官，道卒，時年四十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-016-104', 'p0109', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾將泰小子袤避難淮南，袁術賔禮甚厚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-018-105', 'p0109', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，以衆隨太祖，破黃巾於壽張，又從擊袁術，征徐州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-022-106', 'p0109', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時陶謙病死，徐州迎備，備欲往，羣說備曰：「袁術尚彊，今東，必與之爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-022-107', 'p0109', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東及東城，辭孫策、袁術之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-024-108', 'p0109', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '避袁術命召，徙居山都之山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-109', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」袁術來攻先主，先主拒之於盱眙、淮陰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-110', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '英雄記曰：備留張飛守下邳，引兵與袁術戰於淮陰石亭，更有勝負。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-111', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '收散卒，東取廣陵，與袁術戰，又敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-112', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁術欲經徐州北就袁紹，曹公遣先主督朱靈、路招要擊術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-032-113', 'p0109', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏武帝遣先主統諸將要擊袁術，郭嘉等並諫，魏武不從，其事顯然，非因種菜遁逃而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-035-114', 'p0109', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮早孤，從父玄為袁術所署豫章太守，玄將亮及亮弟均之官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-038-115', 'p0109', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '迫於袁術放命圮族，扇動羣逆，津塗四塞，雖縣心北風，欲行靡由。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-038-116', 'p0109', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '建安元年，呂布乘先主之出拒袁術，襲下邳，虜先主妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-117', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '獻帝春秋曰：袁術表堅假中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-118', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '前到魯陽，與袁術相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-119', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '山陽公載記曰：袁術將僭號，聞堅得傳國璽，乃拘堅夫人而奪之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-120', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '會次兄九江太守昂為袁術所攻，㬂往助之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-121', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　江表傳曰：策徑到壽春見袁術，涕泣而言曰：「亡父昔從長沙入討董卓，與明使君會於南陽，同盟結好；不幸遇難，勳業不終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-122', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時袁術僭號，策以書責而絕之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-123', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」又詔勑曰：「故左將軍袁術不顧朝恩，坐創凶逆，造合虛偽，欲因兵亂，詭詐百姓，始聞其言以為不然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-124', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '興平二年十二月二十日，於吳郡曲阿得袁術所呈表，以臣行殄寇將軍；至被詔書，乃知詐擅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-046-125', 'p0109', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-049-126', 'p0109', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '時袁術在淮南，繇畏憚，不敢之州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-127', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '袁術上景領丹楊太守，討故太守周昕，遂據其郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-128', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '策表琨領丹楊太守，會吳景委廣陵來東，復為丹楊守，江表傳曰：初，袁術遣從弟胤為丹楊，策令琨討而代之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-050-129', 'p0109', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳錄曰：袁夫人者，袁術女也，有節行而無子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-130', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術之在淮南也，昕惡其淫虐，絕不與通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-131', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '獻帝春秋曰：袁術遣吳景攻昕，未拔，景乃募百姓敢從周昕者死不赦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-132', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後袁術徙壽春，賁又依之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-133', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '江表傳曰：袁術以吳景守廣陵，策族兄香亦為術所用，作汝南太守，而令賁為將軍，領兵在壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-134', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後為袁術驅馳，加征南將軍，死於壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-135', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策討丹楊七縣，使輔西屯歷陽以拒袁術，并招誘餘民，鳩合遺散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-051-136', 'p0109', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術深怨策，乃陰遣間使齎印綬與丹楊宗帥陵陽祖郎等，使激動山越，大合衆，圖共攻策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-054-137', 'p0109', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '頃之，袁術遣從弟胤代尚為太守，而瑜與尚俱還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-054-138', 'p0109', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '袁術聞其名，就署東城長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-055-139', 'p0109', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策之襲袁術，欽隨從給事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-140', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '會堅薨，治扶翼策，依就袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-141', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '九州春秋曰：初平三年，揚州刺史陳禕死，袁術使瑀領揚州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-056-142', 'p0109', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '呂子衡忠篤亮直，性雖好奢，然以憂公為先，不足為損，避袁術自歸於兄，兄作大將，別領部曲，故憂兄事，乞為都督，辦護脩整，加之恪勤，與吳漢相類，故方之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-143', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '績年六歲，於九江見袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-144', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '父俊，官至陳相，為袁術所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-057-145', 'p0109', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '值袁術僭號，兄弟忿爭，天下鼎沸，羣賊並起，陳與比界，姧慝四布，俊厲威武，保疆境，賊不敢犯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a04-058-146', 'p0109', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '袁術與康有隙，將攻康，康遣遜及親戚還吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0109-a05-036-full-147', 'p0109', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '宜官後爲袁術將，今鉅鹿宋子有耿球碑，是術所立，其書甚工，云是宜官也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-070-0', 'p0110', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '審配、逢紀盡忠之臣任其事，配字正南，魏郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-070-1', 'p0110', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-2', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏郡審配，鉅鹿田豐，先賢行狀曰：「配字正南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-3', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-4', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」郭圖、審配曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-5', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會攸家犯法，審配收繫之，攸不得志，遂奔曹操，而說使襲取淳于瓊等，瓊等時宿在烏巢，烏巢，地名，在滑州酸棗城東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-6', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '官度之敗，審配二子為曹操所禽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-7', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a03-074-8', 'p0110', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-9', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，尚復攻譚，留蘇由、審配守鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-10', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，審配兄子榮夜開所守城東門內兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-11', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁氏之治也，使豪彊擅恣，親戚兼并；下民貧弱，代出租賦，衒鬻家財，不足應命；審配宗族，至乃藏匿罪人，為逋逃主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-12', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-13', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」審配、郭圖曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-14', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-15', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後審配任用，與紀不睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-16', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚欲分兵益譚，恐譚遂奪其衆，乃使審配守鄴，尚自將兵助譚，與太祖相拒於黎陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-17', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋載審配獻書於譚曰：「春秋之義，國君死社稷，忠臣死王命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-18', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚使審配、蘇由守鄴，復攻譚平原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-19', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」配厲聲曰：「汝為降虜，審配為忠臣，雖死，豈若汝生邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-20', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　樂資山陽公載記及袁暐獻帝春秋並云太祖兵入城，審配戰於門中，旣敗，逃于井中，於井獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-21', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-22', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配專而無謀，逢紀果而自用，此二人留知後事，若攸家犯其法，必不能縱也，不縱，攸必為變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-23', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-24', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前日公破袁尚，禽審配，海內震駭，必人人自恐不得保其土地，守其兵衆也；今使分屬兾州，將皆動心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-011-25', 'p0110', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '太祖破鄴，籍沒審配等家財物貲以萬數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-015-26', 'p0110', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後尚與其兄譚爭鬬，尚出軍詣平原，留別駕審配守鄴城，孚隨尚行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-070-0', 'p0111', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-070-1', 'p0111', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-2', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後袁紹至，馥從事十人棄馥去，唯恐在後，獨武、純杖刀拒，兵不能禁，紹後令田豐殺此二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-3', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏郡審配，鉅鹿田豐，先賢行狀曰：「配字正南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-4', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹軍之敗也，土崩奔走，徒衆略盡，軍將皆撫膝啼泣曰：『向使田豐在此，不至於是。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-5', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐扶紹，使却入空垣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-6', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐說紹曰：「徙都之計，旣不克從，宜早圖許，奉迎天子，動託詔令，響號海內，此筭之上者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-7', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-8', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐說紹曰：「與公爭天下者，曹操也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-9', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐以旣失前幾，不宜便行，諫紹曰：「曹操旣破劉備，則許下非復空虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-10', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '及軍還，或謂田豐曰：「君必見重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-11', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹還，曰：「吾不用田豐言，果為所笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-001-12', 'p0111', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝春秋曰：袁紹叛卒詣公云：「田豐使紹早襲許，若挾天子以令諸侯，四海可指麾而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-13', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '別駕從事田豐扶紹欲郤入空垣，紹以兜鍪撲地曰：「大丈夫當前鬬死，而入牆間，豈可得活乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-14', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-15', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將南師，沮授、田豐諫曰：「師出歷年，百姓疲弊，倉庾無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-16', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '田豐說紹襲太祖後，紹辭以子疾，不許，豐舉杖擊地曰：「夫遭難遇之機，而以嬰兒之病失其會，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-17', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹之南也，田豐說紹曰：「曹公善用兵，變化無方，衆雖少，未可輕也，不如以乆持之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-18', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹還，謂左右曰：「吾不用田豐言，果為所笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-19', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹軍之敗也，土崩奔北，師徒略盡，軍皆拊膺而泣曰：「向令田豐在此，不至於是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-20', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　孫盛曰：觀田豐、沮授之謀，雖良、平何以過之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-21', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '昔項羽背范增之謀，以喪其王業；紹之殺田豐，乃甚於羽遠矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-22', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-23', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '田豐剛而犯上，許攸貪而不治。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-24', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-0', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '馥長史耿武、別駕閔純、騎都尉沮授聞而諫曰：獻帝傳曰：「沮授，廣平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-1', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '引沮授為別駕，因謂授曰：「今賊臣作亂，朝廷遷移。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-2', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，車駕為李傕等所追於曹陽，沮授說紹曰：「將軍累葉台輔，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-3', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授諫曰：「世稱萬人逐兔，一人獲之，貪者悉止，分定故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-4', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授進說曰：「近討公孫，師出歷年，百姓疲敝，倉庫無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-5', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '圖等因是譖沮授曰：「授監統內外，威震三軍，若其浸盛，何以制之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-6', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授臨行，會其宗族，散資財以與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-7', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」沮授臨舩歎曰：「上盈其志，下務其功，悠悠黃河，吾其濟乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-8', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授又說紹曰：「北兵雖衆，而勁果不及南軍；南軍穀少，而資儲不如北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-9', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授說紹可遣蔣竒別為支軍於表，以支軍為瓊等表援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-10', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授為操軍所執，乃大呼曰：「授不降也，為所執耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-11', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：沮授，廣平人，少有大志，多權略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-12', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳云：沮授說紹曰：「將軍累葉輔弼，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-13', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '出長子譚為青州，沮授諫紹：「必為禍始。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-14', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將南師，沮授、田豐諫曰：「師出歷年，百姓疲弊，倉庾無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-15', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授又諫紹：「良性促狹，雖驍勇不可獨任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-16', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹臨發，沮授會其宗族，散資財以與之曰：「夫勢在則威無不加，勢亡則不保一身，哀哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-17', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將濟河，沮授諫曰：「勝負變化，不可不詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-18', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授又曰：「北兵數衆而果勁不及南，南穀虛少而貨財不及北；南利在於急戰，北利在於緩搏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-19', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會紹遣淳于瓊等將兵萬餘人北迎運車，沮授說紹：「可遣將蔣奇別為支軍於表，以斷曹公之鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-20', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授不及紹渡，為人所執，詣太祖，獻帝傳云：授大呼曰：「授不降也，為軍所執耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-21', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　孫盛曰：觀田豐、沮授之謀，雖良、平何以過之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-0', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-1', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，紹去董卓，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-2', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-3', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初，紹去董卓，與許攸及紀俱詣兾州，以紀聦達有計策，甚親信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-4', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-5', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '許攸進曰：「曹操兵少而悉師拒我，許下餘守埶必空弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-6', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹瞞傳曰：「公聞許攸來，跣出迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-7', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '頃之，兾州刺史王芬、南陽許攸、沛國周旌等連結豪傑，謀廢靈帝，立合肥侯，以告太祖，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-8', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '羽鑿齒漢晉春秋曰：許攸說紹曰：「公無與操相攻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-9', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹謀臣許攸貪財，紹不能足，來奔，因說公擊瓊等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-10', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '許攸曰：「明且鑒於鏡，此益不忘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-006-11', 'p0113', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-006-12', 'p0113', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹去董卓出奔，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚親信之，與共舉事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-13', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-14', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '田豐剛而犯上，許攸貪而不治。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-15', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-16', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會許攸來降，言紹遣淳于瓊等將萬餘兵迎運糧，將驕卒惰，可要擊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-012-17', 'p0113', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '南陽許攸、魏略曰：攸字子遠，少與袁紹及太祖善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-18', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時將軍許攸擁部曲，不附太祖而有慢言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-19', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」太祖曰：「許攸慢吾，如何可置乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-20', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」襲曰：「殿下謂許攸何如人邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-21', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '臣聞千鈞之弩不為鼷鼠發機，萬石之鍾不以莛撞起音，今區區之許攸，何足以勞神武哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-008-full-0', 'p0114', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '扶風人馬騰、漢陽人王國並叛，寇三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-008-1', 'p0114', 'houhanshu', 'a03-008', '《後漢書·卷八》', '扶風人馬騰、漢陽人王國並叛，寇三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-2', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-3', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-4', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十七年夏五月癸未，誅衞尉馬騰，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-056-5', 'p0114', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-6', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而鄙司馬扶風馬騰，典略曰：「騰字壽成，扶風茂陵人，馬援後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-7', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓之入關，要韓遂、馬騰共謀山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-8', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '興平元年，馬騰從隴右來朝，進屯霸橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-9', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂與馬騰自還涼州，更相戰爭，乃下隴據關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-10', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '復徵馬騰為衞尉，封槐里侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-075-11', 'p0114', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，征西將軍馬騰與範謀誅李傕，焉遣叟兵五千助之，漢世謂蜀為叟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-001-12', 'p0114', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '騎士皆下馬，付麥以相付，於是太祖馬騰入麥中，勑主簿議罪；主簿對以春秋之義，罰不加於尊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-006-13', 'p0114', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是歲，韓遂、馬騰等降，率衆詣長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-006-14', 'p0114', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-010-15', 'p0114', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-16', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時關中諸將馬騰、韓遂等，各擁彊兵相與爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-17', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」張旣說馬騰會擊援，騰遣子超將精兵逆之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-18', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-19', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司隷校尉鍾繇遣旣說將軍馬騰等，旣為言利害，騰等從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-20', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖以旣為議郎，參繇軍事，使西徵諸將馬騰等，皆引兵會擊晟等，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-21', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安初，約與馬騰相攻擊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-018-22', 'p0114', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，從馬騰擊反羌叛氐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-031-23', 'p0114', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '時征西將軍馬騰屯郿而反，焉及範與騰通謀，引兵襲長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-031-24', 'p0114', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：範從長安亡之馬騰營，從焉求兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-038-25', 'p0114', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '初，韓遂與馬騰作亂關中，數與璋父焉交通信，至騰子超復與璋相聞，有連蜀之意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-full-0', 'p0115', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '湟中義從胡北宮伯玉與先零羌叛，以金城人邊章、韓遂為軍帥，攻殺護羌校尉伶徵、金城太守陳懿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-full-1', 'p0115', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-2', 'p0115', 'houhanshu', 'a03-008', '《後漢書·卷八》', '湟中義從胡北宮伯玉與先零羌叛，以金城人邊章、韓遂為軍帥，攻殺護羌校尉伶徵、金城太守陳懿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-3', 'p0115', 'houhanshu', 'a03-008', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-009-4', 'p0115', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-009-5', 'p0115', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十六年秋九月庚戌，曹操與韓遂、馬超戰於渭南，遂等大敗，關西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-048-6', 'p0115', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平二年，漢陽賊邊章、韓遂與羌胡為寇，東侵三輔，時遣車騎將軍皇甫嵩西討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-056-7', 'p0115', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-058-8', 'p0115', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '會西羌反，邊章、韓遂作亂隴右，徵發天下，役賦無已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-058-9', 'p0115', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '中平四年，鄙率六郡兵討金城賊王國、韓遂等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-069-10', 'p0115', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '碩雖擅兵於中，而猶畏忌於進，乃與諸常侍共說帝遣進西擊邊章、韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-071-11', 'p0115', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '會邊章、韓遂作亂隴右，明年春，詔嵩迴鎮長安，以衞園陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-071-12', 'p0115', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝春秋曰：「初卓為前將軍，嵩為左將軍，俱征邊章、韓遂，爭雄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-13', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '伯玉等乃劫致金城人邊章、韓遂，獻帝春秋曰：「涼州義從宋建、王國等反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-14', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '嵩以無功免歸，而邊章、韓遂等大盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-15', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '其冬，徵溫還京師，韓遂乃殺邊章及伯玉、文侯，擁兵十餘萬，進圍隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-16', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」亦擁兵反叛，又漢陽王國，自號「合衆將軍」，皆與韓遂合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-17', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂等復共廢王國，而劫故信都令漢陽閻忠，英雄記曰：「王國等起兵，劫忠為主，統三十六部，號『車騎將軍』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-18', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓之入關，要韓遂、馬騰共謀山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-19', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂聞之，乃率衆來欲和騰、傕，旣而復與騰合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-20', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂使人語稠曰：「天下反覆未可知，相與州里，今雖小違，要當大同，欲共一言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-21', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂與馬騰自還涼州，更相戰爭，乃下隴據關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-22', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '十六年，超與韓遂舉關中背曹操，操擊破之，遂、超敗走，騰坐夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-23', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」韓遂走金城羌中，為其帳下所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-075-24', 'p0115', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '韓遂、馬超之亂，關西民奔魯者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-102-25', 'p0115', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-102-26', 'p0115', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '十九年，獲宗建；韓遂逃于羌中，病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-27', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」金城邊章、韓遂殺刺史郡守以叛，衆十餘萬，天下騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-28', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時關中諸將疑繇欲自襲，馬超遂與韓遂、楊秋、李堪、成宜等叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-29', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂請與公相見，公與遂父同歲孝廉，又與遂同時儕輩，於是交馬語移時，不及軍事，但說京都舊故，拊手歡笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-30', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂徙金城，入氐王千萬部，率羌、胡萬餘騎與夏侯淵戰，擊，大破之，遂走西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-31', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '西平、金城諸將麴演、蔣石等共斬送韓遂首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-32', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂、宋建，南結巴、蜀，羣逆合從，圖危社稷，君復命將，龍驤虎奮，梟其元首，屠其窟栖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-33', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '韓遂等起涼州，復為中郎將，西拒遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-34', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '山陽公載記曰：初卓為前將軍，皇甫嵩為左將軍，俱征韓遂，各不相下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-35', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是歲，韓遂、馬騰等降，率衆詣長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-36', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-37', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕以是疑稠與韓遂私和而有異意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-38', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '遷幽州刺史，徵拜議郎，參車騎將軍張溫軍事，西討韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-39', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '後邊章、韓遂為亂，司空張溫銜命征討；又請謙為參軍事，接遇甚厚，而謙輕其行事，心懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-40', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '邊章、韓遂為亂涼州，金城麴勝襲殺祖厲長劉儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-41', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓遂、馬超之亂，關西民從子午谷奔之者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-009-42', 'p0115', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從征韓遂等，戰於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-009-43', 'p0115', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '韓遂在顯親，淵欲襲取之，遂走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-010-44', 'p0115', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧曰：「關中將帥以十數，莫能相一，唯韓遂、馬超最彊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-010-45', 'p0115', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖後與韓遂、馬超戰於渭南，超等索割地以和，并求任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-013-46', 'p0115', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時關中諸將馬騰、韓遂等，各擁彊兵相與爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-013-47', 'p0115', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-015-48', 'p0115', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '典略曰：韓遂在湟中，其壻閻行欲殺遂以降，夜攻遂，不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-016-49', 'p0115', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」旣荅曰：「金城郡，昔為韓遂所見屠剥，死喪流亡，或竄戎狄，或陷寇亂，戶不滿五百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-016-50', 'p0115', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韓遂、馬超之叛也，弘農、馮翊多舉縣邑以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-017-51', 'p0115', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破馬超、韓遂於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-017-52', 'p0115', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '韓遂、馬超等反關右，遣晃屯汾陰以撫河東，賜牛酒，令上先人墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-018-53', 'p0115', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討韓遂、馬超於潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-018-54', 'p0115', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '至十五年，將軍韓遂自上討猛，猛發兵遣軍東拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-021-55', 'p0115', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-021-56', 'p0115', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖嘗使瑀作書與韓遂，時太祖適近出，瑀隨從，因於馬上具草，書成呈之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-023-57', 'p0115', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖徙出故韓遂、馬超等兵五千餘人，使平難將軍殷署等督領，以儼為關中護軍，盡統諸軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-024-58', 'p0115', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-030-59', 'p0115', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康分屯有縣以南荒地為帶方郡，遣公孫模、張敞等收集遺民，興兵伐韓濊，舊民稍出，是後倭韓遂屬帶方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-60', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '父騰，靈帝末與邊章、韓遂等俱起事於西州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-61', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '後騰與韓遂不和，求還京畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-62', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '會三輔亂，不復來東，而與鎮西將軍韓遂結為異姓兄弟，始甚相親，後轉以部曲相侵入，更為讎敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-63', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '超旣統衆，遂與韓遂合從，及楊秋、李堪、成宜等相結，進軍至潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-64', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '山陽公載記曰：初，曹公軍在蒲阪，欲西渡，超謂韓遂曰：「宜於渭北拒之，不過二十日，河東穀盡，彼必走矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-65', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '典略曰：建安十六年，超與關中諸將侯選、程銀、李堪、張橫、梁興、成宜、馬玩、楊秋、韓遂等，凡十部，俱反，其衆十萬，同據河、潼，建列營陣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-038-66', 'p0115', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '初，韓遂與馬騰作亂關中，數與璋父焉交通信，至騰子超復與璋相聞，有連蜀之意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-042-67', 'p0115', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-042-68', 'p0115', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '十九年，獲宋建，韓遂逃于羌中，被殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-054-69', 'p0115', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今北土旣未平安，加馬超、韓遂尚在關西，為操後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-009-0', 'p0116', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-031-1', 'p0116', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '曾孫商，益州牧劉焉以為蜀郡太守，有治聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-075-2', 'p0116', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉焉字君郎，江夏竟陵人也，竟陵今復州縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-075-3', 'p0116', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '論曰：劉焉覩時方艱，先求後亡之所，左傳曰，鄭公孫黑肱有疾，歸邑于公，曰：「吾聞之，生於亂代，貴而能貧，人無求焉，可以後亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-079-4', 'p0116', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '州牧劉焉表薦之，時王塗隔塞，詔命竟不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-104-5', 'p0116', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '臣昭案：劉焉傳，興平元年，天火燒其城府輜重，延及民家，館邑無餘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-118-6', 'p0116', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '至孝靈在位，橫流旣及，劉焉徼偽，自為身謀，非有憂國之心，專懷狼據之策，抗論昏世，薦議愚主，盛稱宜重牧伯，謂足鎮壓萬里，挾姦樹筭，苟罔一時，豈可永為國本，長期勝術哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-008-7', 'p0116', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：虞讓太尉，因薦衞尉趙謨、益州牧劉焉、豫州牧黃琬、南陽太守羊續，並任為公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-008-8', 'p0116', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '益州牧劉焉以魯為督義司馬，與別部司馬張脩將兵擊漢中太守蘇固，魯遂襲脩殺之，奪其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-9', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '劉焉字君郎，江夏竟陵人也，漢魯恭王之後裔，章帝元和中徙封竟陵，支庶家焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-10', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-11', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：劉焉起兵，不與天下討董卓，保州自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-12', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '而劉焉聞董扶之辭則心存益土，聽相者之言則求婚吳氏，遽造輿服，圖竊神器，其惑甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-034-13', 'p0116', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '兄吳壹，少孤，壹父素與劉焉有舊，是以舉家隨焉入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-038-14', 'p0116', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '奏記州牧劉焉，薦儒士任定祖曰：「昔百里、蹇叔以耆艾而定策，甘羅、子奇以童冠而立功，故書美黃髮，而易稱顏淵，固知選士用能，不拘長幼，明矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-038-15', 'p0116', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '州牧劉焉表薦安味精道度，厲節高邈，揆其器量，國之元寶，宜處弼疑之輔，以消非常之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-039-16', 'p0116', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之案：劉焉在漢靈帝時已經宗正太常，出為益州牧，祥始以孫堅作長沙時為江夏太守，不得舉焉為孝廉，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-039-17', 'p0116', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '父常，送故將軍劉焉入蜀，值王路隔塞，遂不得還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-042-18', 'p0116', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '獻帝遷都長安，遂逃入蜀，劉焉父子待以客禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-072-0', 'p0117', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '旣奔漢中，聞備圍劉璋於成都，密書請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-075-1', 'p0117', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉璋遣詣曹公，公不甚禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-102-2', 'p0117', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-113-3', 'p0117', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '建安六年，劉璋分巴，以永寧為巴東郡，以墊江為巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-001-4', 'p0117', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '益州牧劉璋始受徵役，遣兵給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-001-5', 'p0117', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-021-6', 'p0117', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '益州牧劉璋與表有隙，覬以治書侍御史使益州，令璋下兵以綴表軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-031-7', 'p0117', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張璠曰：劉璋愚弱而守善言，斯亦宋襄公、徐偃王之徒，未為無道之主也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-8', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備欲自圖蜀，拒荅不聽，曰：「益州民富彊，土地險阻，劉璋雖弱，足以自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-9', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-10', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉璋遣詣曹公，曹公不甚禮松；主簿楊脩深器之，白公辟松，公不納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-11', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十九年夏，雒城破，益部耆舊雜記曰：劉璋遣張任與劉璝率精兵拒捍先主於涪，為先主所破，退與璋子循守雒城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-12', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝之初，三輔飢亂，堅去官，與弟援南入蜀依劉璋，璋以堅為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-13', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，張魯在北，民殷國富而不知存卹，智能之士思得明君。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-14', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-15', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，自焉已來有累世之恩，文法羈縻，互相承奉，德政不舉，威刑不肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-16', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主入益州，還攻劉璋，飛與諸葛亮等泝流而上，分定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-17', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '魯不足與計事，內懷於邑，聞先主圍劉璋於成都，密書請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-18', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '自葭萌受任，還攻劉璋，忠常先登陷陣，勇毅冠三軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-19', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主自葭萌還攻劉璋，召諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-20', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '益州牧劉璋與先主會涪，統進策曰：「今因此會，便可執之，則將軍無用兵之勞，而坐定一州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-21', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '臣松之以為謀襲劉璋，計雖出於統，然違義成功，本由詭道，心旣內疚，則歡情自戢，故聞備稱樂之言，不覺率爾而對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-22', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '建安初，天下饑荒，正與同郡孟達俱入蜀依劉璋，乆之為新都令，後召署軍議校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-23', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後劉璋遂使使招靖，靖來入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-24', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主入益州，劉璋見雍，甚愛之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-25', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '劉璋時，宓同郡王商為治中從事，與宓書曰：「貧賤困苦，亦何時可以終身！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-26', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '漢末，和率宗族西遷，益州牧劉璋以為牛鞞、音髀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-27', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」主簿請自送至州，見益州牧劉璋，璋父焉昔為巴父祥所舉孝廉，見巴驚喜，每大事輒以咨訪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-28', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」初攻劉璋，備與士衆約：「若事定，府庫百物，孤無預焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-29', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-30', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，劉璋遣扶風孟達副法正，各將兵二千人，使迎先主，先主因令達并領其衆，留屯江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-31', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕仕州，不過書佐，後又為衆人所謗毀於州牧劉璋，璋髠鉗羕為徒隷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-32', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '曹公入荊州時，嚴宰秭歸，遂西詣蜀，劉璋以為成都令，復有能名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-33', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主自葭萌南還襲劉璋，留峻守葭萌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-34', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時入蜀，為梓潼令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-35', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時，舉孝廉，為魚復長，還州署從事，領帳下司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-36', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時為緜竹令，先主攻緜竹時，詩先舉城降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-37', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '劉璋辟為從事，以疾去官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-38', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '州牧劉璋，辟以為師友從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-39', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-40', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '初，先主與劉璋會涪時，裕為璋從事，侍坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-41', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '漢末大亂，敏隨姊奔荊州，姊夫黃琬是劉璋祖母之姪，故璋遣迎琬妻，敏遂俱與姊入蜀，常為璋賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-42', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '少為郡吏，州牧劉璋召為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-43', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '及先主襲取益州，將帥分下郡縣，郡縣望風景附，權閉城堅守，須劉璋稽服，乃詣降先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-44', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '後貢恢於州，涉道未至，聞先主自葭萌還攻劉璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-044-45', 'p0117', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '伯仁姑，益州牧劉璋之母也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-46', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋母，觀之族姑，璋又以女妻觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-47', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋時，為巴郡太守，還為州治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-48', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋時，為中郎將，將兵拒先主於涪，詣降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-49', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '華陽國志曰：邵兄邈，字漢南，劉璋時為牛鞞長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-50', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '勳，劉璋時為州書佐，先主定蜀，辟為左將軍屬，後轉州別駕從事，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-046-51', 'p0117', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-054-52', 'p0117', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉璋為益州牧，外有張魯寇侵，瑜乃詣京見權曰：「今曹操新折衂，方憂在腹心，未能與將軍道兵相事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-054-53', 'p0117', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-001-54', 'p0117', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-014-55', 'p0117', 'jinshu', 'a05-014', '《晉書·卷十四》', '建安六年，劉璋改永寧為巴東郡，分巴郡墊江置巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-014-56', 'p0117', 'jinshu', 'a05-014', '《晉書·卷十四》', '獻帝初平元年，劉璋分巴郡立永寧郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-009-0', 'p0118', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操破漢中，張魯降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-072-1', 'p0118', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '阜與戰，身被五創，宗族昆季死者七人，超遂南奔張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-2', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '沛人張魯，母有恣色，兼挾鬼道，往來焉家，遂任魯以為督義司馬，遂與別部司馬張脩將兵掩殺漢中太守蘇固，斷絕斜谷，殺使者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-3', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '張魯以璋闇懦，不復承順。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-4', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十六年，璋聞曹操當遣兵向漢中討張魯，內懷恐懼，松復說璋迎劉備以拒操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-5', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '明年，曹操破張魯，定漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-102-6', 'p0118', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-7', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯據漢中，三月，遣鍾繇討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-8', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，公西征張魯，至陳倉，將自武都入氐；氐人塞道，先遣張郃、朱靈等攻破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-9', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯使弟衞與將楊昂等據陽平關，橫山築城十餘里，攻之不能拔，乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-002-10', 'p0118', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '』臣以合辭語鎮南將軍張魯，魯亦問合知書所出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-006-11', 'p0118', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '趙衢等舉義兵討超，超走漢中從張魯，後奔劉備，死於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-12', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張魯字公祺，沛國豐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-13', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載董昭表曰：「武皇帝承涼州從事及武都降人之辭，說張魯易攻，陽平城下南北山相遠，不可守也，信以為然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-14', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」又楊曁表曰：「武皇帝始征張魯，以十萬之衆，身親臨履，指授方略，因就民麥以為軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-15', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '臣松之以為張魯雖有善心，要為敗而後降，今乃寵以萬戶，五子皆封侯，過矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-16', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖西征張魯，淵等將涼州諸將侯王已下，與太祖會休亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-17', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張魯前為鎮北將軍，休為司馬，家南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-18', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時漢中有甘露降，子朗見張魯精兵數萬人，有四塞之固，遂建言赤氣乆衰，黃家當興，欲魯舉號，魯不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-010-19', 'p0118', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-014-20', 'p0118', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征張魯，轉曄為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-014-21', 'p0118', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資曰：「昔武皇帝征南鄭，取張魯，陽平之役，危而後濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-015-22', 'p0118', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '」從征張魯，別從散關入討叛氐，收其麥以給軍食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-016-23', 'p0118', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖征張魯，過其郡，見則恱之，使為軍導。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-017-24', 'p0118', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征張魯，教與護軍薛悌，署函邊曰「賊至乃發」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-017-25', 'p0118', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征張魯，先遣郃督諸軍討興和氐王竇茂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-018-26', 'p0118', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '後復隨超奔漢中，從張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-021-27', 'p0118', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾繇求以三千兵入關，外託討張魯，內以脅取質任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-021-28', 'p0118', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '若以兵入關中，當討張魯，魯在深山，道徑不通，彼必疑之；一相驚動，地險衆彊，殆難為慮！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-022-29', 'p0118', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '羣以為「太祖昔到陽平攻張魯，多收豆麥以益軍糧，魯未下而食猶乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-023-30', 'p0118', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖克張魯，洽陳便宜以時拔軍徙民，可省置守之費。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-023-31', 'p0118', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」後襲領丞相長史，隨太祖到漢中討張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-024-32', 'p0118', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-025-33', 'p0118', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '超盡兼隴右之衆，而張魯又遣大將楊昂以助之，凡萬餘人，攻城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-025-34', 'p0118', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」遂共閉門逐超，超奔漢中，從張魯得兵還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-35', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張魯母始以鬼道，又有少容，常往來焉家，故焉遣魯為督義司馬，住漢中，斷絕谷閣，殺害漢使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-36', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋，字季玉，旣襲焉位，而張魯稍驕恣，不承順璋，璋殺魯母及弟，遂為讎敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-37', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋資給先主，使討張魯，然後分別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-38', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：孫權欲與備共取蜀，遣使報備曰：「米賊張魯居王巴、漢，為曹操耳目，規圖益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-39', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '今欲先攻取璋，進討張魯，首尾相連，一統吳、楚，雖有十操，無所憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-40', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張魯虛偽，未必盡忠於操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-41', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-42', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '別駕從事蜀郡張松說璋曰：「曹公兵彊無敵於天下，若因張魯之資以取蜀土，誰能禦之者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-43', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋增先主兵，使擊張魯，又令督白水軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-44', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是歲，曹公定漢中，張魯遁走巴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-45', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣黃權將兵迎張魯，張魯已降曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-033-46', 'p0118', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '簡喜，以語張魯，魯為洗沐送詣益州，備乃立以為太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-035-47', 'p0118', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，張魯在北，民殷國富而不知存卹，智能之士思得明君。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-035-48', 'p0118', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-49', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-50', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '進退狼狽，乃奔漢中依張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-51', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '後奔漢中，張魯以為都講祭酒，欲妻之以女，或諫魯曰：「有人若此不愛其親，焉能愛人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-52', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '典略曰：初超之入蜀，其庶妻董及子秋，留依張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-037-53', 'p0118', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '後因璋聞曹公欲遣將征張魯之有懼心也，松遂說璋宜迎先主，使之討魯，復令正銜命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-037-54', 'p0118', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-039-55', 'p0118', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」旣入，巴復諫曰：「若使備討張魯，是放虎於山林也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-040-56', 'p0118', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初在西平、上庸間聚衆數千家，後與張魯通，又遣使詣曹公，曹公加其號為將軍，因使領上庸都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-041-57', 'p0118', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張魯遣將楊帛誘峻，求共守城，峻曰：「小人頭可得，城不可得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-042-58', 'p0118', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-042-59', 'p0118', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '二十年秋，曹公攻漢中，張魯降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-043-60', 'p0118', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '時別駕張松建議，宜迎先主，使伐張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-043-61', 'p0118', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '及曹公破張魯，魯走入巴中，權進曰：「若失漢中，則三巴不振，此為割蜀之股臂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-052-62', 'p0118', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昔竇融歸漢，與國升降；張魯降魏，賞延于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-054-63', 'p0118', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉璋為益州牧，外有張魯寇侵，瑜乃詣京見權曰：「今曹操新折衂，方憂在腹心，未能與將軍道兵相事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-054-64', 'p0118', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乞與奮威俱進取蜀，得蜀而并張魯，因留奮威固守其地，好與馬超結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-060-65', 'p0118', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '吳書曰：建安十六年，岱督郎將尹異等，以兵二千人西誘漢中賊帥張魯到漢興寋城，魯嫌疑斷道，事計不立，權遂召岱還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a05-001-66', 'p0118', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-0', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '中平元年春二月，鉅鹿人張角自稱「黃天」，其部師有三十六萬，皆著黃巾，同日反叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-1', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-2', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-3', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '植連破張角，垂當拔之，小黃門左豐言於帝曰：「盧中郎固壘息軍，以待天誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-4', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-5', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-6', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-7', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-8', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '中平元年春二月，鉅鹿人張角自稱「黃天」，其部師有三十六萬，皆著黃巾，同日反叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-9', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-10', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-11', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '植連破張角，垂當拔之，小黃門左豐言於帝曰：「盧中郎固壘息軍，以待天誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-12', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-13', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-14', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-15', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-16', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '先是黃巾帥張角等執左道，稱大賢，以誑燿百姓，天下繈負歸之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-17', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '賜時在司徒，召掾劉陶告曰：「張角等遭赦不悔，而稍益滋蔓，今若下州郡捕討，恐更騷擾，速成其患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-18', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '後帝徙南宮，閱錄故事，得賜所上張角奏及前侍講注籍，所注之籍錄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-19', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '時鉅鹿張角偽託大道，妖惑小民，陶與奉車都尉樂松、議郎袁貢連名上疏言之，曰：「聖王以天下耳目為視聽，故能無不聞見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-20', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '明年，張角反亂，海內鼎沸，帝思陶言，封中陵鄉侯，三遷尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-21', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '竊見天下前遇張角之亂，後遭邊章之寇，每聞羽書告急之聲，心灼內熱，四體驚竦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-22', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '宦官事急，共讒陶曰：「前張角事發，詔書示以威恩，自此以來，各各改悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-23', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後為護軍司馬，與左中郎將皇甫嵩俱討賊張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-24', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '今張角起於趙、魏，黃巾亂於六州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-25', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '誠使張角梟夷，黃巾變服，臣之所憂，甫益深耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-26', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '及破張角，爕功多當封，續漢書曰：「爕軍斬賊三帥卜巳、張伯、梁仲寧等，功高為封首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-063-27', 'p0119', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '先是安平王續為張角賊所略，國家贖王得還，朝廷議復其國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-064-28', 'p0119', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '連戰破賊帥張角，斬獲萬餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-067-29', 'p0119', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '若乆不赦宥，輕與張角合謀，為變滋大，悔之無救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-069-30', 'p0119', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '中平元年，黃巾賊張角等起，以進為大將軍，率左右羽林五營士屯都亭，修理器械，以鎮京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-069-31', 'p0119', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '張角別黨馬元義謀起洛陽，進發其姦，以功封慎侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-32', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '初，鉅鹿張角自稱「大賢良師」，「良」或作「郎」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-33', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未及作亂，而張角弟子濟南唐周上書告之，於是車裂元義於洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-34', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-35', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '初，嵩討張角，路由鄴，見中常侍趙忠舍宅踰制，乃奏沒入之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-36', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-072-37', 'p0119', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中平元年，拜東中郎將，持節，代盧植擊張角於下曲陽，軍敗抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-075-38', 'p0119', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '光和中，東方有張角，漢中有張脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-39', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '黃巾旣作，盜賊糜沸，郎中中山張鈞上書曰：「竊惟張角所以能興兵作亂，萬人所以樂附之者，其源皆由十常侍多放父兄、子弟、婚親、賔客典據州郡，辜榷財利，侵掠百姓，百姓之冤無所告訴，故謀議不軌，聚為盜賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-40', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '詔使廷尉、侍御史考為張角道者，御史承讓等旨，遂誣奏鈞學黃巾道，收掠死獄中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-41', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '而讓等實多與張角交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-42', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '今黨人更為國用，汝曹反與張角通，為可斬未？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-081-43', 'p0119', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '會張角作亂，栩上便宜，頗譏刺左右，不欲國家興兵，但遣將於河上北向讀孝經，賊自當消滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-102-44', 'p0119', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」其後黃巾賊張角燒州郡，朝廷遣將討平，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-103-45', 'p0119', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」是後張角作亂稱黃巾，遂破壞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-46', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」到中平元年二月，張角兄弟起兵兾州，自號黃天，三十六方，四面出和，將帥星布，吏士外屬，因其疲餧，牽而勝之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-47', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '其後張角稱黃天作亂，竟破壞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-48', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」袁山松曰：「案張角一時狡亂，不足致此大妖，斯乃曹氏滅漢之徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-49', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '中平元年，黃巾賊張角等立三十六方，起兵燒郡國，山東七州處處應角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-112-50', 'p0119', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '光和末，張角亂，此鄉守險助國，漢嘉之，故立縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-118-51', 'p0119', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '張角懷挾妖偽，遐邇搖蕩，八州并發，煙炎絳天，牧守梟裂，流血成川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-008-52', 'p0119', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-008-53', 'p0119', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '光和中，東方有張角，漢中有張脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-022-54', 'p0119', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '張角起，以植為北中郎將征角，失利抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-046-55', 'p0119', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '中平元年，黃巾賊帥張角起於魏郡，託有神靈，遣八使以善道教化天下，而潛相連結，自稱黃天泰平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-0', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '輕財能施，善於交結，與諸葛瑾至厚，委廬江劉靖以得失，江夏李允以衆事，廣陵吳碩、河南張梁以軍旅，而傾心親待，莫不自盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-1', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '在事一年，遵皎舊迹，禮劉靖、李允、吳碩、張梁及江夏閭舉等，並納其善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-2', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '黃武五年，權攻石陽，奐以地主，使所部將軍鮮于丹帥五千人先斷淮道，自帥吳碩、張梁五千人為軍前鋒，降高城，得三將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-3', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '吳碩、張梁皆裨將軍，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-058-4', 'p0121', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '軍到白圍，託言住獵，潛遣將軍周峻、張梁等擊江夏新市、安陸、石陽，石陽市盛，峻等奄至，人皆捐物入城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0122-a04-035-0', 'p0122', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '聞孟獲者，為夷、漢所服，募生致之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0122-a04-039-1', 'p0122', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」亮納其策，赦孟獲以服南方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-048-0', 'p0123', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '故魯肅一面而自託，士燮蒙險而效命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-049-1', 'p0123', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '士燮字威彥，蒼梧廣信人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-049-2', 'p0123', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '士燮作守南越，優游終世，至子不慎，自貽凶咎，蓋庸才玩富貴而恃阻險，使之然也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-052-3', 'p0123', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '士燮兄弟，相率供命，南土之賔，自此始也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-053-4', 'p0123', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '士燮旣附孫權，召綜為五官中郎，除合浦、交阯太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-053-5', 'p0123', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '交阯太守士燮遣兵致討，卒不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-060-6', 'p0123', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '交阯太守士燮卒，權以燮子徽為安遠將軍，領九真太守，以校尉陳時代燮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a05-015-7', 'p0123', 'jinshu', 'a05-015', '《晉書·卷十五》', '建安八年，張津為刺史，士燮為交阯太守，共表立為州，乃拜津為交州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-0', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-1', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-2', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月，韓暹攻衞將軍董承。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-3', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '封衞將軍董承為輔國將軍伏完等十三人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-4', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」衞將軍董承為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-5', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五年春正月，車騎將軍董承、偏將軍王服、越騎校尉种輯受密詔誅曹操，事洩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-6', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '壬午，曹操殺董承等，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-full-7', 'p0125', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」后手持縑數匹，董承使符節令孫徽以刃脅奪之，殺傍侍者，血濺后衣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-full-8', 'p0125', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董承女為貴人，操誅承而求貴人殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-9', 'p0125', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」〉后手持縑數匹，董承使符節令孫徽以刃脅奪之，殺傍侍者，血濺后衣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-10', 'p0125', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '董承女爲貴人，操誅承而求貴人殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-064-11', 'p0125', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '興平元年，詔書徵歧，會帝當還洛陽，先遣衞將軍董承修理宮室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-070-12', 'p0125', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '獻帝春秋，董承之誅，伏后與父完書，言司空殺董承，帝方為報怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-13', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又以故牛輔部曲董承為安集將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-14', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-15', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-16', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-17', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '爭赴舡者，不可禁制，董承以戈擊披之，斷手指於舟中者可掬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-18', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-19', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-20', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '干亂政事，董承患之，潛召兖州牧曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-21', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '於是封衞將軍董承、輔國將軍伏完等十餘人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-22', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-23', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」以董承為車騎將軍，開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-24', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '帝忌操專偪，乃密詔董承，使結天下義士共誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-25', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-26', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備之未東也，陰與董承等謀反，至下邳，遂殺徐州刺史車胄，舉兵屯沛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-27', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '五年春正月，董承等謀泄，皆伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-28', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十一月，漢皇后伏氏坐昔與父故屯騎校尉完書，云帝以董承被誅怨恨公，辭甚醜惡，發聞，后廢黜死，兄弟皆伏法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-006-29', 'p0125', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '汜走南山，奉及將軍董承以天子還洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-006-30', 'p0125', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '天子步行趨河岸，岸高不得下，董承等謀欲以馬羈相續以繫帝腰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-008-31', 'p0125', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-010-32', 'p0125', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」　獻帝春秋曰：董承之誅，伏后與父完書，言司空殺董承，帝方為報怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-014-33', 'p0125', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-017-34', 'p0125', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及到洛陽，韓暹、董承日爭鬬，晃說奉令歸太祖；奉欲從之，後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-35', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主未出時，獻帝舅車騎將軍董承臣松之按：董承，漢靈帝母董太后之姪，於獻帝為丈人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-36', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '覩其機兆，赫然憤發，與車騎將軍董承同謀誅操，將安國家，克寧舊都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-37', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣昔與車騎將軍董承圖謀討操，機事不密，承見陷害，臣播越失據，忠義不果。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-036-38', 'p0125', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」　臣松之以為備後與董承等結謀，但事泄不克諧耳，若為國家惜曹公，其如此言何！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-046-39', 'p0125', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-0', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '安思閻皇后　順烈梁皇后　孝崇匽皇后　桓帝懿獻梁皇后　孝桓鄧皇后　桓思竇皇后　孝仁董皇后　孝靈宋皇后　靈思何皇后　獻帝伏皇后　獻穆曹皇后');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-1', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '獻帝伏皇后諱壽，琅邪東武人，東武，今密州諸城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-2', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '及伏皇后被弒，明年，立節為皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-3', 'p0126', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '獻帝伏皇后諱壽，琅邪東武人，〈東武，今密州諸城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-0', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '山陽公載記曰：「劉備在蜀聞之，遂發喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-1', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三輔決錄曰：「時有京兆全禕，字德偉，自以代為漢臣，乃發憤，與耿紀、韋晃欲挾天子以攻魏，南援劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-2', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月庚子，劉備自稱漢中王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-3', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '明年，劉備稱帝于蜀，孫權亦自王於吳，於是天下遂三分矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-054-4', 'p0127', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及操自平漢中，欲因討劉備而不得進，欲守之又難為功，護軍不知進止何依。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-056-5', 'p0127', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '後許汜與劉備並在荊州牧劉表坐，備共論天下人，汜曰：「陳元龍淮海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-6', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融逼急，乃遣東萊太史慈求救於平原相劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-7', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」慈單步見融，旣而求救於劉備，得兵以解圍焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-8', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '備驚曰：「孔北海乃復知天下有劉備邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-9', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '在郡六年，劉備表領青州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-072-10', 'p0127', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年，左將軍劉備誘奉斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-072-11', 'p0127', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承遂與劉備同謀，未發，會備出征，承更與偏將軍王服、長水校尉种輯、議郎吳碩結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-12', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '五年，左將軍劉備殺徐州刺史車胄，據沛以背曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-13', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '操今東擊劉備，兵連未可卒解，今舉軍而襲其後，可一往而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-14', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐以旣失前幾，不宜便行，諫紹曰：「曹操旣破劉備，則許下非復空虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-15', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹使劉備、文醜挑戰，曹操又擊破之，斬文醜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-16', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '松懷恨而還，勸璋絕曹氏，而結好劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-17', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十六年，璋聞曹操當遣兵向漢中討張魯，內懷恐懼，松復說璋迎劉備以拒操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-18', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '』」「劉備有梟名，梟即驍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-19', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '公孫瓚使劉備與術合謀共逼紹，紹與曹操會擊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-20', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術因欲北至青州從袁譚，曹操使劉備徼之，不得過，復走還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-21', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '二年閒，操復盡收諸城，破布於鉅野，布東奔劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-22', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時劉備領徐州，居下邳，與袁術相拒於淮上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-23', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術生年以來，不聞天下有劉備，備乃舉兵與術對戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-24', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '諸將謂布曰：「將軍常欲殺劉備，今可假手於術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-25', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '建安二年，布遂復從袁術，遣順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-26', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」顧謂劉備曰：「玄德，卿為坐上客，我為降虜，繩縛我急，獨不可一言邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-105-27', 'p0127', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '曹操略荊州，逐劉備於當陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-105-28', 'p0127', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十六年，劉備入蜀，與吳再爭荊州，於時戰爭四分五裂之地，荊州為劇，故山鳴之異作其域也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-112-29', 'p0127', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '孱陵魏氏春秋曰：「劉備在荊州所都，改曰公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-113-30', 'p0127', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '建安二十二年，劉備以為郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-31', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-32', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '還過郯，謙將曹豹與劉備屯郯東，要太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-33', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布東奔劉備，張邈從布，使其弟超將家屬保雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-34', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱說公曰：「觀劉備有雄才而甚得衆心，終不為人下，不如早圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-35', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-36', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布之破劉備也，霸等悉從布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-37', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '術欲從下邳北過，公遣劉備、朱靈要之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-38', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-39', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」公曰：「夫劉備，人傑也，今不擊，必為後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-40', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫盛魏氏春秋云：荅諸將曰：「劉備，人傑也，將生憂寡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-41', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」紹騎將文醜與劉備將五六千騎前後至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-42', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹使劉備助辟，公使曹仁擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-43', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹之未破也，使劉備略汝南，汝南賊共都等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-44', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '今深入征之，劉備必說劉表以襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-45', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，表卒，其子琮代，屯襄陽，劉備屯樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-46', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '軍旣得出，公大喜，諸將問之，公曰：「劉備，吾儔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-47', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫盛異同評曰：案吳志，劉備先破公軍，然後權攻合肥，而此記云權先攻合肥，後有赤壁之事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-48', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-49', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-50', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '邈字文然，穆字思然，以禕慷慨有日磾之風，又與王必善，因以閒之，若殺必，欲挾天子以攻魏，南援劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-51', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋七月，治兵，遂西征劉備，九月，至長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-52', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏侯淵與劉備戰於陽平，為備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-53', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '後密與臣議策質，國人不協，或欲西通，魯即怒曰：『寧為魏公奴，不為劉備上客也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-54', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」魏書曰：癸亥，孫權上書，說：「劉備支黨四萬人，馬二三千匹，出秭歸，請往埽撲，以克捷為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-55', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '閏月，孫權破劉備於夷陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-56', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '又王近出，乘小輦，執達手，撫其背戲之曰：「卿得無為劉備刺客邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-57', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略載帝露布天下并班告益州曰：「劉備背恩，自竄巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-58', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及劉備走小沛，張飛隨之，過謂宜祿曰：「人取汝妻，而為之長，何蚩蚩若是邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-004-59', 'p0127', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往者季漢分崩，九土顛覆，劉備、孫權乘間作禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-60', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '暹、奉不能奉王法，各出奔，寇徐、揚閒，為劉備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-61', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '趙衢等舉義兵討超，超走漢中從張魯，後奔劉備，死於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-62', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，太祖遣劉備詣徐州拒袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-63', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹渡河，壁延津南，使劉備、文醜挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-64', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '劉備奔表，表厚待之，然不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-65', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋曰：太祖之始征柳城，劉備說表使襲許，表不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-66', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以人臣而拒人主，逆也；以新造之楚而禦國家，其勢弗當也；以劉備而敵曹公，又弗當也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-67', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」巽曰：「誠以劉備不足禦曹公乎，則雖保楚之地，不足以自存也；誠以劉備足禦曹公乎，則備不為將軍下也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-68', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-69', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋曰：王威說劉琮曰：「曹操得將軍旣降，劉備已走，必懈弛無備，輕行單進；若給威奇兵數千，徼之於險，操可獲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-70', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術生年已來，不聞天下有劉備，備乃舉兵與術對戰；術憑將軍威靈，得以破備，其功三也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-71', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安三年，布復叛為術，遣高順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-72', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '九州春秋曰：初，布騎將侯成遣客牧馬十五匹，客悉驅馬去，向沛城，欲歸劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-73', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '劉備進曰：「明公不見布之事丁建陽及董太師乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-74', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」布縛急，謂劉備曰：「玄德，卿為坐客，我為執虜，不能一言以相寬乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-75', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '後許汜與劉備並在荊州牧劉表坐，表與備共論天下人，汜曰：「陳元龍湖海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-76', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '二十三年，劉備軍陽平關，淵率諸將拒之，相守連年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-77', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖與袁紹乆相持於官渡，紹遣劉備徇㶏彊諸縣，多舉衆應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-78', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '仁曰：「南方以大軍方有目前急，其勢不能相救，劉備以彊兵臨之，其背叛固宜也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-79', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從征荊州，追劉備於長坂，獲其二女輜重，收其散卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-80', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '劉備遣將吳蘭屯下辯，太祖遣曹洪征之，以休為騎都尉，參洪軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-81', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以偏將軍將兵擊劉備別將於下辯，破之，拜中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-82', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以真為征蜀護軍，督徐晃等破劉備別將高詳於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-83', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '尚奏：「劉備別軍在上庸，山道險難，彼不我虞，若以奇兵潛行，出其不意，則獨克之勢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-84', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '權以露布於蜀，劉備聞之，曰：「老賊不死，禍亂未已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-85', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」比行，布以敗劉備，而臧霸等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-86', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-87', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-88', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '劉備之為豫州，舉渙茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-89', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '布初與劉備和親，後離隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-90', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時有傳劉備死者，羣臣皆賀；渙以甞為備舉吏，獨不賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-012-91', 'p0127', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '在郡六年，劉備表融領青州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-012-92', 'p0127', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏書曰：自劉備叛後，東南多變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-013-93', 'p0127', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '初，建安末，孫權始遣使稱藩，而與劉備交兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-94', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '徐庶母為曹公所得，劉備乃遣庶歸，欲為天下者恕人子之情也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-95', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備失徐州，來歸太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-96', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征荊州，劉備奔吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-97', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-98', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」　魏書曰：劉備來奔，以為豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-99', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」　傅子曰：初，劉備來降，太祖以客禮待之，使為豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-100', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖欲速征劉備，議者懼軍出，袁紹擊其後，進不得戰而退失所據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-101', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-102', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-103', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備，人傑也，有度而遲，得蜀日淺，蜀人未恃也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-104', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '其後孟達去劉備歸文帝，論者多稱有樂毅之量。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-105', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '詔問羣臣令料劉備當為關羽出報吳不。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-106', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '權將陸議大敗劉備，殺其兵八萬餘人，備僅以身免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-107', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-015-108', 'p0127', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖將拔漢中守，恐劉備北取武都氐以逼關中，問旣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-015-109', 'p0127', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖征劉備，先遣逵至斜谷觀形勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-110', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '今天子在許，公遠北征，若劉表遣劉備襲許，據之以號令四方，公之勢去矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-111', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-112', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又討劉備臨沮長杜普、旌陽長梁大，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-113', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備以徐州叛，太祖東征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-114', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至陽平，魯降，太祖還，留郃與夏侯淵等守漢中，拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-115', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備屯陽平，郃屯廣石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-116', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '魏略曰：淵雖為都督，劉備憚郃而易淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-117', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '淵司馬郭淮乃令衆曰：「張將軍，國家名將，劉備所憚；今日事急，非張將軍不能安也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-118', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖遂自至漢中，劉備保高山不敢戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-119', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破劉備，又從破顏良，拔白馬，進至延津，破文醜，拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-120', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，留晃與夏侯淵拒劉備於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-121', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備欲斷絕外內，以取漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-122', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯尚討劉備於上庸，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-123', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉表使劉備北侵，至葉，太祖遣典從夏侯惇拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-124', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-125', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖語劉備，令語霸送二人首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-126', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '授聘兵，使與曹純追討劉備於長阪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-127', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '汝劉備庸才耳，豈能敵邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-128', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '」斆曰：「蜀漢絕遠，劉備嘗用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-019-129', 'p0127', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」魏略曰：太祖在漢中，而劉備栖於山頭，使劉封下挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-130', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '雄略冠時，智謀出世，摧袁氏於官渡，驅孫權於江外，逐劉備於隴右，破烏丸於白登，其餘梟夷蕩定者，往往如神，不可勝計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-131', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏武以十三年征荊州，劉備却後數年方入蜀，備身未嘗涉於關、隴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-132', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-133', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今以海內之兵，百勝之威，而孫權負險於吳，劉備不賔於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-022-134', 'p0127', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '劉備臨豫州，辟羣為別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-022-135', 'p0127', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '昔劉備自成都至白水，多作傳舍，興費人役，太祖知其疲民也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-023-136', 'p0127', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '夏侯淵為劉備所沒，軍喪元帥，將士失色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-023-137', 'p0127', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖問潛曰：「卿前與劉備俱在荊州，卿以備才略何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-025-138', 'p0127', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-025-139', 'p0127', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及劉備取漢中以逼下辯，太祖以武都孤遠，欲移之，恐吏民戀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-026-140', 'p0127', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '劉備之奔公孫瓚也，豫時年少，自託於備，備甚奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-026-141', 'p0127', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖還，留征西將軍夏侯淵拒劉備，以淮為淵司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-028-142', 'p0127', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '事成，可得天下；不成，退保蜀漢，不失作劉備也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-031-143', 'p0127', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '吳書曰：璋以米二十萬斛，騎千匹，車千乘，繒絮錦帛，以資送劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-144', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '謙病篤，謂別駕麋笁曰：「非劉備不能安此州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-145', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：陳登等遣使詣袁紹曰：「天降灾沴，禍臻鄙州，州將殂殞，生民無主，恐懼姦雄一旦承隙，以貽盟主日昃之憂，輒共奉故平原相劉備府君以為宗主，永使百姓知有依歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-146', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫盛曰：劉備雄才，處必亡之地，告急於吳，而獲奔助，無緣復顧望江渚而懷後計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-147', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-148', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備未破魏軍之前，尚未與孫權相見，不得有此說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-149', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '傅子曰：初，劉備襲蜀，丞相掾趙戩曰：「劉備其不濟乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-150', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」徵士傅幹曰：「劉備寬仁有度，能得人死力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-151', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備代璋，以堅為廣漢、蜀郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-152', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」襄陽記曰：劉備訪世事於司馬德操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-153', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏略曰：劉備屯於樊城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-154', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '及荊州內附，孔明與劉備相隨去，福與韜俱來北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-155', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '其二事曰：曹公遣刺客見劉備，方得交接，開論伐魏形勢，甚合備計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-156', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣松之案：劉備以建安十三年敗，遣亮使吳，亮以建興五年抗表北伐，自傾覆至此整二十年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-157', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏略曰：始，國家以蜀中惟有劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-158', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '時左將軍劉備以亮有殊量，乃三顧亮於草廬之中；亮深謂備雄姿傑出，遂解帶寫誠，厚相結納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-159', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-160', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晚得諸葛亮，因以為佐相，而羣臣恱服，劉備足信、亮足重故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-036-161', 'p0127', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-036-162', 'p0127', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：初，劉備在許，與曹公共獵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-037-163', 'p0127', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '今劉備襲奪璋土，權以濟業，負信違情，德義俱愆，雖功由是隆，宜大傷其敗，譬斷手全軀，何樂之有？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-039-164', 'p0127', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '巴謂曹公曰：「劉備據荊州，不可也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-039-165', 'p0127', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：璋遣法正迎劉備，巴諫曰：「備，雄人也，入必為害，不可內也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-045-166', 'p0127', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '僉父肜，復為劉備戰亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-046-167', 'p0127', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-168', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '劉備欲南濟江，肅與相見，因傳權旨，為陳成敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-169', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '劉備表權行車騎將軍，領徐州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-170', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二年四月，劉備稱帝於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-171', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '魏略曰：權聞魏文帝受禪而劉備稱帝，乃呼問知星者，己分野中星氣何如，遂有僭意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-172', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」是歲，劉備帥軍來伐，至巫山、秭歸，使使誘導武陵蠻夷，假與印傳，許之封賞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-173', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，權使太中大夫鄭泉聘劉備于白帝，始復通也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-174', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」使蜀，劉備問曰：「吳王何以不荅吾書，得無以吾正名不宜乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-049-175', 'p0127', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '融欲告急平原相劉備，城中人無由得出，慈自請求行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-049-176', 'p0127', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '」備斂容荅曰：「孔北海知世間有劉備邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-050-177', 'p0127', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '術方與劉備爭徐州，以景為廣陵太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-051-178', 'p0127', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '年二十五，拜安東中郎將，與陸遜共拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-179', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後劉備表權行車騎將軍，昭為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-180', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '建安二十年，權遣瑾使蜀通好劉備，與其弟亮俱公會相見，退無私面。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-181', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉備東伐吳，吳王求和，瑾與備牋曰：「奄聞旗鼓來至白帝，或恐議臣以吳王侵取此州，危害關羽，怨深禍大，不宜荅和，此用心於小，未留意於大者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-182', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '會劉備東下，武陵蠻夷蠢動，權遂命隲上益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-183', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '後劉備之東，宿於秣陵，周觀地形，亦勸權都之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-184', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '獻帝春秋云：劉備至京，謂孫權曰：「吳去此數百里，即有驚急，赴救為難，將軍無意屯京乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-185', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '諸書皆云劉備勸都秣陵，而此獨云權自欲都之，又為虛錯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-186', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-187', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備以左將軍領荊州牧，治公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-188', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-189', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-190', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑜威聲遠著，故曹公、劉備咸欲疑譖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-191', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '加劉備天下梟雄，與操有隙，寄寓於表，表惡其能而不能用也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-192', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣松之案：劉備與權併力，共拒中國，皆肅之本謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-193', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權大怒，欲斬肅，肅因曰：「今事已急，即有他圖，何不遣兵助劉備，而欲斬我乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-194', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今旣與曹操為敵，劉備近在公安，邊境密邇，百姓未附，宜得良將以鎮撫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-195', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '方今曹公在北，疆埸未靜，劉備寄寓，有似養虎，天下之事，未知終始，此朝士旰食之秋，至尊垂慮之日也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-196', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備負國，是非未決，羽亦何敢重欲干命！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-197', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉備令關羽鎮守，專有荊土，權命蒙西取長沙、零、桂三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-198', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備請盟，權乃歸普等，割湘水，以零陵還之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-199', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權分荊州與劉備，普復還領江夏，遷盪寇將軍，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-200', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '子壹封宣城侯，領兵拒劉備有功，還赴南郡，與魏交戰，臨陣卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-201', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備次西陵，盛攻取諸屯，所向有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-202', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-056-203', 'p0127', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武元年，劉備舉兵攻宜都，然督五千人與陸遜并力拒備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-056-204', 'p0127', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '劉備詣京見權，範密請留備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-205', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-206', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜案劒曰：「劉備天下知名，曹操所憚，今在境界，此彊對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-207', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '吳錄曰：劉備聞魏軍大出，書與遜云：「賊今已在江陵，吾將復東，將軍謂其能然不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-208', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '評曰：劉備天下稱雄，一世所憚，陸遜春秋方壯，威名未著，摧而克之，罔不如志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-060-209', 'p0127', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-061-210', 'p0127', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '劉備領荊州，以濬為治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-061-211', 'p0127', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '武陵郡從事樊伷誘導諸夷，圖以武陵屬劉備，外白差督督萬人往討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-062-212', 'p0127', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '劉備下白帝，權以見兵少，使綜料諸縣，得六千人，立解煩兩部，詳領左部、綜領右部督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-063-213', 'p0127', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '及壬辰歲，範又白言：「歲在甲午，劉備當得益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-063-214', 'p0127', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」劉備盛兵西陵，範曰：「後當和親。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-215', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-216', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '孫權、劉備，外親內踈，羽之得意，權所不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-217', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '帝恐達速發，以書喻之曰：「將軍昔棄劉備，託身國家，國家委將軍以疆埸之任，任將軍以圖蜀之事，可謂心貫白日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-218', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉備章武元年，亦以郡國封建諸王，或遙採嘉名，不由檢土地所出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-219', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉備據蜀，又分廣漢之葭萌、涪城、梓潼、白水四縣，改葭萌曰漢壽，又立漢德縣，以為梓潼郡；割巴郡之宕渠、宣漢、漢昌三縣置宕渠郡，尋省，以縣並屬巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-220', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '二十一年，劉備分巴郡立固陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-015-221', 'p0127', 'jinshu', 'a05-015', '《晉書·卷十五》', '蜀分南郡，立宜都郡，劉備沒後，宜都、武陵、零陵、南郡四郡之地悉復屬吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-0', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '劉禪以為左將軍，脩欲刺禪而不得親近，每因慶賀，且拜且前，為禪左右所遏，事輙不克，故殺禕焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-1', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏之與蜀，雖為敵國，非有趙襄滅智之仇，燕丹危亡之急；且劉禪凡下之主，費禕中才之相，二人存亡，固無關於興喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-2', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，蜀主劉禪詣艾降，巴蜀皆平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-3', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」丁亥，封劉禪為安樂公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-009-4', 'p0128', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '飛知其良家女，遂以為妻，產息女，為劉禪皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-5', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '劉禪遣使奉皇帝璽綬，為箋詣艾請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-6', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-7', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '今宜厚劉禪以致孫休，安士民以來遠人，若便送禪於京都，吴以為流徙，則於向化之心不勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-8', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾受命忘身，束馬縣車，自投死地，勇氣陵雲，士衆乘勢，使劉禪君臣靣縛，叉手屈膝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-9', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾進軍向成都，劉禪詣艾降，遣使勑維等令降於會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-033-10', 'p0128', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '晉諸公贊曰：劉禪乘騾車詣艾，不具亡國之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-033-11', 'p0128', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '皇帝臨軒，使太常嘉命劉禪為安樂縣公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-035-12', 'p0128', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '幸值劉禪闇弱，無猜險之性，諸葛威略，足以檢衞異端，故使異同之心無由自起耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-042-13', 'p0128', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '張璠以為譙周所陳降魏之策，蓋素料劉禪懦弱，心無害戾，故得行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-044-14', 'p0128', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-048-15', 'p0128', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '蜀主劉禪降魏問至，然後罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-002-16', 'p0128', 'jinshu', 'a05-002', '《晉書·卷二》', '以劉禪之闇，而邊城外破，士女內震，其亡可知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-003-17', 'p0128', 'jinshu', 'a05-003', '《晉書·卷三》', '賜山陽公劉康、安樂公劉禪子弟一人為駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-005-18', 'p0128', 'jinshu', 'a05-005', '《晉書·卷五》', '然後推轂鍾鄧，長驅庸蜀，三關電埽，劉禪入臣，天符人事，於是信矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-014-19', 'p0128', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉禪建興二年，改益州郡為建寧郡，廣漢屬國為陰平郡，分建寧永昌立雲南郡，分建寧䍧牱立興古郡，分廣漢立東廣漢郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-034-20', 'p0128', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '至劉禪降服，諸營堡者索然俱散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-034-21', 'p0128', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '今江淮之難，不過劍閣；山川之險，不過岷漢；孫皓之暴，侈於劉禪；吳人之困，甚於巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-086-0', 'p0129', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '故諸葛亮表云「五月度瀘」，言其艱苦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-113-1', 'p0129', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '諸葛亮表有耽文山、澤山、司彌瘞山、婁山、辟龍山，此等並皆未詳所在縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-113-2', 'p0129', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」諸葛亮書云：「漢嘉金，朱提銀，採之不足以自食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-3', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮聞之，陰欲誘達，數書招之，達與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-4', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '蜀大將諸葛亮寇邊，天水、南安、安定三郡吏民叛應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-5', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮棄父母之國，阿殘賊之黨，神人被毒，惡積身滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-6', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，諸葛亮圍陳倉，曹真遣將軍費曜等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-7', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮寇天水，詔大將軍司馬宣王拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-8', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '是月，諸葛亮出斜谷，屯渭南，司馬宣王率諸軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-9', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '羣臣以為大將軍方與諸葛亮相持未解，車駕可西幸長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-006-10', 'p0129', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-009-11', 'p0129', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '諸葛亮圍祁山，南安、天水、安定三郡反應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-010-12', 'p0129', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-013-13', 'p0129', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太和初，蜀相諸葛亮圍祁山，明帝欲西征，毓上疏曰：「夫策貴廟勝，功尚帷幄，不下殿堂之上，而決勝千里之外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-14', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-15', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：諸葛亮出在南鄭，時議者以為可因大發兵，就討之，帝意亦然，以問資。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-16', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '青龍初，孫權與諸葛亮連和，欲俱出為寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-17', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：是時，孫權、諸葛亮號稱劇賊，無歲不有軍征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-18', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和中，諸葛亮出隴右，吏民騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-19', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後十餘日，諸軍上隴，諸葛亮破走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-20', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會諸葛亮出，緝上便宜，詔以問中書令孫資，資以為有籌略，遂召拜騎都尉，遣參征蜀軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-21', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：建字公威，少與諸葛亮俱遊學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-22', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛亮復出，急攻陳倉，帝驛馬召郃到京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-23', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '郃識變數，善處營陣，料戰勢地形，無不如計，自諸葛亮皆憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-24', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛亮復出祁山，詔郃督諸將西至略陽，亮還保祁山，郃追至木門，與亮軍交戰，飛矢中郃右膝，薨，魏略曰：亮軍退，司馬宣王使郃追之，郃曰：「軍法，圍城必開出路，歸軍勿追。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-022-25', 'p0129', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '大將軍司馬文王曰：「昔諸葛亮常有此志，卒亦不能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-022-26', 'p0129', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」諸葛亮寇天水，臻奏：「宜遣奇兵入散關，絕其糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-023-27', 'p0129', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '諸葛亮出秦川，大將軍曹真督諸軍拒亮，徙襲為大將軍軍師，分邑百戶賜兄基爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-023-28', 'p0129', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏略列傳以徐福、嚴幹、李義、張旣、游楚、梁習、趙儼、裴潛、韓宣、黃朗十人共卷，其旣、習、儼、潛四人自有傳，徐福事在諸葛亮傳，游楚事在張旣傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-29', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝方脩殿舍，百姓勞役，毗上疏曰：「竊聞諸葛亮講武治兵，而孫權巿馬遼東，量其意指，似欲相左右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-30', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '魏略曰：諸葛亮圍祁山，不克，引退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-31', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '青龍二年，諸葛亮率衆出渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-32', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '招以蜀虜諸葛亮數出，而比能狡猾，能相交通，表為防備，議者以為縣遠，未之信也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-33', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，蜀相諸葛亮出祁山，遣將軍馬謖至街亭，高詳屯列柳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-34', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '青龍二年，諸葛亮出斜谷，並田于蘭坑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-027-35', 'p0129', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '至，值諸葛亮出祁山，隴右三郡反，邈輙遣參軍及金城太守等擊南安賊，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-028-36', 'p0129', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」袁子曰：諸葛亮，重人也，而驟用蜀兵，此知小國弱民難以乆存也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-028-37', 'p0129', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會徑過，西出陽安口，遣人祭諸葛亮之墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-029-38', 'p0129', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '先生見諸葛亮連弩，曰：『巧則巧矣，未盡善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-031-39', 'p0129', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後丞相諸葛亮問秦宓以扶所長，宓曰：「董扶襃秋毫之善，貶纖芥之惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-031-40', 'p0129', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '丞相諸葛亮平南土，闡還吳，為御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-41', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '過襄陽，諸葛亮說先主攻琮，荊州可有。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-42', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-43', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-44', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備大喜，進住鄂縣，即遣諸葛亮隨肅詣孫權，結同盟誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-45', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮詣吳未還，備聞曹公軍下，恐懼，日遣邏吏於水次候望權軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-46', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-47', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-48', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主留諸葛亮、關羽等據荊州，將步卒數萬人入益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-49', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-50', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-51', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-52', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '援亦少有名行，太尉皇甫嵩賢其才而以女妻之，丞相諸葛亮以援為祭酒，遷從事中郎，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-53', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-54', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '太傅許靖、安漢將軍糜笁、軍師將軍諸葛亮、太常賴恭、光祿勳黃柱、少府王謀等上言：「曹丕篡弒，湮滅漢室，竊據神器，劫迫忠良，酷烈無道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-55', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '以諸葛亮為丞相，許靖為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-56', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮集載先主遺詔勑後主曰：「朕初疾但下痢耳，後轉雜他病，殆不自濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-57', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及其舉國託孤於諸葛亮，而心神無貳，誠君臣之至公，古今之盛軌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-58', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '初備以諸葛亮為太子太傅，及禪立，以亮為丞相，委以諸事，謂亮曰：「政由葛氏，祭則寡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-59', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又諸葛亮以禪立之明年領益州牧，其年與主簿杜微書曰「朝廷今年十八」，與禪傳相應，理當非虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-60', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又案諸書記及諸葛亮集，亮亦不為太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-61', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮誅房諸子，徙其四弟於越嶲，欲以安之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-62', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮集載禪三月下詔曰：「朕聞天地之道，福仁而禍淫；善積者昌，惡積者喪，古今常數也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-63', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '雖使諸葛亮在，不能輔之乆全，而況姜維邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-64', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮雖達於為政，凡此之類，猶有未周焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-034-65', 'p0129', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '夫人欲將太子歸吳，諸葛亮使趙雲勒兵斷江留太子，乃得止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-66', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛亮字孔明，琅邪陽都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-67', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」　臣松之以為魏略此言，謂諸葛亮為公威計者可也，若謂兼為己言，可謂未達其心矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-68', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '初平中，中州兵起，乃與韜南客荊州，到，又與諸葛亮特相善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-69', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '逮大和中，諸葛亮出隴右，聞元直、廣元仕財如此，嘆曰：「魏殊多士邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-70', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '蜀記曰：晉初，扶風王駿鎮關中，司馬高平劉寶、長史熒陽桓隰諸官屬士大夫共論諸葛亮，于時譚者多譏亮託身非所，勞困蜀民，力小謀大，不能度德量力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-71', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣壽等言：臣前在著作郎，侍中領中書監濟北侯臣荀勗、中書令關內侯臣和嶠奏，使臣定故蜀丞相諸葛亮故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-72', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晉泰始起居注載詔曰：「諸葛亮在蜀，盡其心力，其子瞻臨難而死義，天下之善一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-73', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '漢晉春秋曰：樊建為給事中，晉武帝問諸葛亮之治國，建對曰：「聞惡必改，而不矜過，賞罰之信，足感神明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-74', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '評曰：諸葛亮之為相國也，撫百姓，示儀軌，約官職，從權制，開誠心，布公道；盡忠益時者雖讎必賞，犯法怠慢者雖親必罰，服罪輸情者雖重必釋，游辭巧飾者雖輕必戮；善無微而不賞，惡無纖而不貶；庶事精練，物理其本，循名責實，虛偽不齒；終於邦域之內，咸畏而愛之，刑政雖峻而無怨者，以其用心平而勸戒明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-75', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-76', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晚得諸葛亮，因以為佐相，而羣臣恱服，劉備足信、亮足重故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-77', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮死至今數十年，國人歌思，如周人之思召公也，孔子曰「雍也可使南靣」，諸葛亮有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-78', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '又問諸葛亮始出隴右，南安、天水、安定三郡人反應之，若亮速進，則三郡非中國之有也，而亮徐行不進；旣而官兵上隴，三郡復，亮無尺寸之功，失此機，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-79', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曰：子之論諸葛亮，則有證也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-80', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽聞馬超來降，舊非故人，羽書與諸葛亮，問超人才可誰比類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-81', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '興字安國，少有令問，丞相諸葛亮深器異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-82', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主入益州，還攻劉璋，飛與諸葛亮等泝流而上，分定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-83', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-84', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '故羽聞馬超歸降，以書問諸葛亮「超人才可誰比類」，不得如書所云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-85', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '是歲，先主為漢中王，欲用忠為後將軍，諸葛亮說先主曰：「忠之名望，素非關、馬之倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-86', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主自葭萌還攻劉璋，召諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-87', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '五年，隨諸葛亮駐漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-88', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-89', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」諸葛亮亦言之於先主，先主見與善譚，大器之，以為治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-90', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」親待亞於諸葛亮，遂與亮並為軍師中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-91', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '拜統父議郎，遷諫議大夫，諸葛亮親為之拜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-92', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '或謂諸葛亮曰：「法正於蜀郡太縱橫，將軍宜啟主公，抑其威福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-93', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '諸葛亮與正，雖好尚不同，以公義相取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-038-94', 'p0129', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '優游風儀，性簡傲跌宕，在先主坐席，猶箕踞傾倚，威儀不肅，自縱適；諸葛亮已下則獨擅一榻，項枕卧語，無所為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-038-95', 'p0129', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-96', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '先主定蜀，徵和為掌軍中郎將，與軍師將軍諸葛亮並署左將軍大司馬府事，獻可替否，共為歡交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-97', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時諸葛亮在臨烝，巴與亮書曰：「乘危歷險，到值思義之民，自與之衆，承天之心，順物之性，非余身謀所能勸動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-98', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮謂巴曰：「張飛雖實武人，敬慕足下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-99', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '卒後，魏尚書僕射陳羣與丞相諸葛亮書，問巴消息，稱曰劉君子初，甚敬重焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-100', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '及先主入蜀，諸葛亮亦從往，良留荊州，與亮書曰：「聞雒城已拔，此天祚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-101', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '才器過人，好論軍計，丞相諸葛亮深加器異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-102', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」　習鑿齒曰：諸葛亮之不能兼上國也，豈不宜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-103', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，孫權稱尊號，以震為衞尉，賀權踐阼，諸葛亮與兄瑾書曰：「孝起忠純之性，老而益篤，及其贊述東西，歡樂和合，有可貴者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-104', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-105', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '雖甞有鳴吠之益於時務，然旣已任之，勢不得輕，若一朝無諸葛亮，必為禍亂矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-106', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮聞之，以為知言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-107', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-108', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '丞相諸葛亮連年出軍，調發諸郡，多不相救，乂募取兵五千人詣亮，慰喻檢制，無逃竄者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-109', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-110', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮慮封剛猛，易世之後終難制御，勸先主因此除之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-111', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮雖外接待羕，而內不能善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-112', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕於獄中與諸葛亮書曰：「僕昔有事於諸侯，以為曹操暴虐，孫權無道，振威闇弱，其惟主公有霸王之器，可與興業致治，故乃翻然有輕舉之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-113', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-114', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立本意，自謂才名宜為諸葛亮之貳，而更游散在李嚴等下，常懷怏怏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-115', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」邵、琬具白其言於諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-116', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立躬率妻子耕殖自守，聞諸葛亮卒，垂泣歎曰：「吾終為左袵矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-117', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '三年，先主疾病，嚴與諸葛亮並受遺詔輔少主；以嚴為中都護，統內外軍事，留鎮永安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-118', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '以諸葛亮欲出軍漢中，嚴當知後事，移屯江州，留護軍陳到駐永安，皆統屬嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-119', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮集有嚴與亮書，勸亮宜受九錫，進爵稱王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-120', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮又與平子豐教曰：「吾與君父子戮力以獎漢室，此神明所聞，非但人知之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-121', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮之使廖立垂泣，李平致死，豈徒無怨言而已哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-122', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮於是可謂能用刑矣，自秦、漢已來未之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-123', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '五年，諸葛亮駐漢中，更以延為督前部，領丞相司馬、涼州刺史，八年，使延西入羌中，魏後將軍費瑤、雍州刺史郭淮與延戰于陽谿，延大破淮等，遷為前軍師征西大將軍，假節，進封南鄭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-124', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '魏略曰：諸葛亮病，謂延等云：「我之死後，但謹自守，慎勿復來也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-125', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主甚悼惜，乃詔諸葛亮曰：「峻旣佳士，加有功於國，欲行酹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-126', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '丞相諸葛亮北駐漢中，請為記室，使與子喬共周旋游處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-127', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '時南方諸郡不賔，諸葛亮將自征之，連諫以為「此不毛之地，疫癘之鄉，不宜以一國之望，冒險而行」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-128', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '諸葛亮當北行，表與後主曰：「將軍向寵，性行淑均，曉暢軍事，試用於昔，先帝稱之曰能，是以衆論舉寵為督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-129', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '會先主薨，諸葛亮遣鄧芝使吳，亮令芝言次可從權請裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-130', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主爭漢中，急書發兵，軍師將軍諸葛亮以問洪，洪曰：「漢中則益州咽喉，存亡之機會，若無漢中則無蜀矣，此家門之禍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-131', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '漢嘉太守黃元素為諸葛亮所不善，聞先主疾病，懼有後患，舉郡反，燒臨邛城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-132', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '是以西土咸服諸葛亮能盡時人之器用也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-133', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '時諸葛亮用法峻密，陰聞祗游戲放縱，不勤所職，常奄往錄獄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-134', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '建興三年，隨諸葛亮南行，歸至漢陽縣，降人李鴻來詣亮，亮見鴻，時蔣琬與詩在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-135', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '達曰：『諸葛亮見顧有本末，終不爾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-042-136', 'p0129', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '諸葛亮表請其罪，先主荅曰：「芳蘭生門，不得不鉏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-042-137', 'p0129', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-043-138', 'p0129', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '」宣王與諸葛亮書曰：「黃公衡，快士也，每坐起歎述足下，不去口實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-139', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '軍師將軍諸葛亮請曰：「蔣琬，社稷之器，非百里之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-140', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '琬以為昔諸葛亮數闚秦川，道險運艱，竟不能克，不若乘水東下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-141', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及至喪所，諸葛亮及諸貴人悉集，車乘甚鮮，允猶神色未泰，而禕晏然自若。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-142', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '建興六年，丞相諸葛亮軍向祁山，時天水太守適出案行，維及功曹梁緒、主簿尹賞、主記梁虔等從行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-143', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '丞相諸葛亮深慮權聞先主殂隕，恐有異計，未知所如。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-144', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」芝對曰：「吳、蜀二國四州之地，大王命世之英，諸葛亮亦一時之傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-145', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-146', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '入蜀，為巴郡太守，丞相諸葛亮主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-147', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」有司將殺之，諸葛亮為請，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-148', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '益部耆舊雜記曰：諸葛亮於武功病篤，後主遣福省侍，遂因諮以國家大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-047-149', 'p0129', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-047-150', 'p0129', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是時蜀相諸葛亮出武功，權謂魏明帝不能遠出，而帝遣兵助司馬宣王拒亮，自率水軍東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-051-151', 'p0129', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '蜀丞相諸葛亮與兄瑾書曰：「旣受東朝厚遇，依依於子弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-052-152', 'p0129', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後與張溫俱使蜀，諸葛亮甚稱歎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-053-153', 'p0129', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，及稱尊號，畯嘗為衞尉，使至蜀，蜀相諸葛亮深善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-154', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-155', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時諸葛亮與備相隨，肅謂亮曰「我子瑜友也」，即共定交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-156', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '又語諸葛亮曰「我子瑜友也」，則亮已亟聞肅言矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-057-157', 'p0129', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '然諸葛亮達見計數，必知神慮屈申之宜，加受朝廷天覆之惠，推亮之心，必無疑貳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-057-158', 'p0129', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」諸葛亮聞俊憂溫，意未之信，及溫放黜，亮乃歎俊之有先見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-058-159', 'p0129', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備尋病亡，子禪襲位，諸葛亮秉政，與權連和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-060-160', 'p0129', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東主中營自掩石陽，別遣從弟孫奐治安陸城，脩立邸閣，輦貲運糧，以為軍儲，又命諸葛亮進指關西，江邊諸將無復在者，才留三千所兵守武昌耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-062-161', 'p0129', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '蜀相諸葛亮卒，權垂心西州，遣儀使蜀申固盟好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-064-162', 'p0129', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛亮聞恪代詳，書與陸遜曰：「家兄年老，而恪性踈，今使典主糧穀，糧穀軍之要最，僕雖在遠，竊用不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-163', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '蜀相諸葛亮惡其反覆，又慮其為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-164', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '諸葛亮欲相破，惟苦無路耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-165', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '明年，諸葛亮寇天水，圍將軍賈嗣、魏平於祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-003-166', 'p0129', 'jinshu', 'a05-003', '《晉書·卷三》', '」己未，詔蜀相諸葛亮孫京隨才署吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-009-167', 'p0129', 'jinshu', 'a05-009', '《晉書·卷九》', '遺詔以桓溫輔政，依諸葛亮、王導故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-011-168', 'p0129', 'jinshu', 'a05-011', '《晉書·卷十一》', '陳卓、范蠡、鬼谷先生、張良、諸葛亮、譙周、京房、張衡並云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-012-169', 'p0129', 'jinshu', 'a05-012', '《晉書·卷十二》', '」五年三月，諸葛亮以大衆寇天水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-012-170', 'p0129', 'jinshu', 'a05-012', '《晉書·卷十二》', '」是年四月，諸葛亮據渭南，吳亦起兵應之，魏東西奔命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-171', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '」其七月，車騎將軍張郃追諸葛亮，為亮所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-172', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '是時，諸葛亮據渭南，宣帝與相持；孫權寇合肥，又遣陸議、孫昭等入淮沔，天子親東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-173', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '又明年，諸葛亮入秦川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-174', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀後主建興十三年，諸葛亮帥大衆伐魏，屯於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-037-175', 'p0129', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '每諸葛亮入寇關中，邊兵不能制敵，中軍奔赴，輒不及事機，宜預選步騎二萬，以爲二部，爲討賊之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-028-0', 'p0130', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蜀衞將軍諸葛瞻自涪還綿竹，列陳待艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-028-1', 'p0130', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾遂至緜竹，大戰，斬諸葛瞻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-033-2', 'p0130', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬，鄧艾破衞將軍諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-036-3', 'p0130', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '苞子遵為尚書，隨諸葛瞻於緜竹，與鄧艾戰，死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-4', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '權留蜀子崇，為尚書郎，隨衞將軍諸葛瞻拒鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-5', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '恢弟子球，羽林右部督，隨諸葛瞻拒鄧艾，臨陣授命，死于緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-6', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '侍中諸葛瞻，丞相亮之子，恪從弟也，嶷與書曰：「東主初崩，帝實幼弱，太傅受寄託之重，寄託之重，亦何容易！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-044-7', 'p0130', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '而鄧艾自陰平由景谷道傍入，遂破諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-044-8', 'p0130', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '但鄧艾詭道傍入，出於其後，諸葛瞻旣敗，成都自潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-045-9', 'p0130', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時都護諸葛瞻初統朝事，廖化過預，欲與預共詣瞻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a05-002-10', 'p0130', 'jinshu', 'a05-002', '《晉書·卷二》', '十一月，鄧艾帥萬餘人自陰平踰絕險至江由，破蜀將諸葛瞻於緜竹，斬瞻，傳首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a03-074-0', 'p0131', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '蜀志曰：「曹公使張遼及關羽為先鋒，羽望見良麾蓋，策馬刺良萬衆之中，斬其首還，諸將莫能當，遂解白馬圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a03-075-1', 'p0131', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫權破關羽，取荊州，以璋為益州牧，留住秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-2', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備將關羽屯下邳，復進攻之，羽降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-3', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張遼、關羽前登，擊破，斬良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-4', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時關羽彊盛，而王在鄴，留必典兵督許中事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-5', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，曹仁討關羽，屯樊城，是月使仁圍宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-6', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '曹瞞傳曰：是時南陽間苦繇役，音於是執太守東里襃，與吏民共反，與關羽連和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-7', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '吾與子共戮力，比曹公軍來，關羽兵亦至矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-8', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫權遣使上書，以討關羽自效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-003-9', 'p0131', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '布之被圍，關羽屢請於太祖，求以杜氏為妻，太祖疑其有色，及城陷，太祖見之，乃自納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-009-10', 'p0131', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '關羽攻樊，時漢水暴溢，于禁等七軍皆沒，禁降羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-11', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：孫權稱臣，斬送關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-12', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」肅曰：「昔關羽率荊州之衆，降于禁於漢濵，遂有北向爭天下之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-13', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '今淮南將士父母妻子皆在內州，但急往禦衞，使不得前，必有關羽土崩之勢矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-14', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-15', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張飛、關羽者，皆萬人之敵也，為之死用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-16', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-17', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及關羽圍曹仁於樊，孫權遣使辭以「遣兵西上，欲掩取羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-18', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-19', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '詔問羣臣令料劉備當為關羽出報吳不。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-20', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '且關羽與備，義為君臣，恩猶父子；羽死不能為興軍報敵，於終始之分不足。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-21', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '權前襲殺關羽，取荊州四郡，備怒，必大興師伐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-22', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-015-23', 'p0131', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '關羽驍銳，乘利而進，必將為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-24', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '關羽圍曹仁於樊，會權稱藩，召遼及諸軍悉還救仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-25', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遼未至，徐晃已破關羽，仁圍解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-26', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後從平荊州，留屯襄陽，擊關羽、蘇非等，皆走之，南郡諸縣山谷蠻夷詣進降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-27', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安二十四年，太祖在長安，使曹仁討關羽於樊，又遣禁助仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-28', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '帝使豫於陵屋畫關羽戰克、龐悳憤怒、禁降服之狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-29', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-30', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復遣晃助曹仁討關羽，屯宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-31', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-32', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與樂進討關羽於尋口，有功，進封延壽亭侯，加討逆將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-33', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '侯音、衞開等以宛叛，悳將所領與曹仁共攻拔宛，斬音、開，遂南屯樊，討關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-019-34', 'p0131', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '二十四年，曹仁為關羽所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-021-35', 'p0131', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破關羽并荊州之後，志盈欲滿，凶宄以極，是以宣文侯深建宏圖大舉之策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-022-36', 'p0131', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹仁為關羽所圍，太祖遣徐晃救之，不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-023-37', 'p0131', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '關羽圍征南將軍曹仁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-026-38', 'p0131', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '關羽圍襄陽，寵助征南將軍曹仁屯樊城拒之，而左將軍于禁等軍以霖雨水長為羽所沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-031-39', 'p0131', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '孫權殺關羽，取荊州，以璋為益州牧，駐秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-40', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '靈等還，先主乃殺徐州刺史車胄，留關羽守下邳，而身還小沛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-41', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '旣去，備謂張飛、關羽曰：「吾豈種菜者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-42', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公盡收其衆，虜先主妻子，并禽關羽以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-43', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '比到當陽，衆十餘萬，輜重數千兩，日行十餘里，別遣關羽乘船數百艘，使會江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-44', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備謂關羽、張飛曰：「彼欲致我，我今自結託於東而不往，非同盟之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-45', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-46', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主留諸葛亮、關羽等據荊州，將步卒數萬人入益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-47', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫氏與孤本為脣齒，又樂進在青泥與關羽相拒，今不往救羽，進必大克，轉侵州界，其憂有甚於魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-48', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-49', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-50', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-51', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主引兵五萬下公安，令關羽入益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-52', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-53', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '時關羽攻曹公將曹仁，禽于禁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-54', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '又前關羽圍樊、襄陽，襄陽男子張嘉、王休獻玉璽，璽潛漢水，伏於淵泉，暉景燭燿，靈光徹天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-55', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '初，先主忿孫權之襲關羽，將東征，秋七月，遂帥諸軍伐吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-033-56', 'p0131', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-57', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽、張飛等不恱，先主解之曰：「孤之有孔明，猶魚之有水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-58', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」亮曰：「豫州軍雖敗於長阪，今戰士還者及關羽水軍精甲萬人，劉琦合江夏戰士亦不下萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-59', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽為曹公所獲，遇之甚厚，可謂能盡其用矣，猶義不背本，曾謂孔明之不若雲長乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-60', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '然後吳更違盟，關羽毀敗，秭歸蹉跌，曹丕稱帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-61', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-62', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '關羽字雲長，本字長生，河東解人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-63', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-64', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-65', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '張飛字益德，涿郡人也，少與關羽俱事先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-66', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-67', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，飛雄壯威猛，亞於關羽，魏謀臣程昱等咸稱羽、飛萬人之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-68', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '山陽公載記曰：超因見備待之厚，與備言，常呼備字，關羽怒，請殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-69', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '為呼人主字，幾為關羽、張飛所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-70', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '且備之入蜀，留關羽鎮荊州，羽未甞在益土也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-71', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-72', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '評曰：關羽、張飛皆稱萬人之敵，為世虎臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-037-73', 'p0131', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '先主旣即尊號，將東征孫權以復關羽之耻，羣臣多諫，一不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-038-74', 'p0131', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '芳為南郡太守，與關羽共事，而私好攜貳，叛迎孫權，羽因覆敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-040-75', 'p0131', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '自關羽圍樊城、襄陽，連呼封、達，令發兵自助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-040-76', 'p0131', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '建安中，為荊州刺史傅羣主簿，背羣而詣襄陽太守關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-041-77', 'p0131', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主為漢中王，遣詩拜關羽為前將軍，羽聞黃忠為後將軍，羽怒曰：「大丈夫終不與老兵同列！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-78', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '為前將軍關羽主簿，羽敗，屬吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-79', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '士仁字君義，廣陽人也，為將軍，住公安，統屬關羽；與羽有隙，叛迎孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-80', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先主入蜀，以為荊州治中，典留州事，亦與關羽不穆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-81', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」遂置南三郡長吏，關羽盡逐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-82', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '會備到公安，使關羽將三萬兵至益陽，權乃召蒙等使還助肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-83', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二十四年，關羽圍曹仁於襄陽，曹公遣左將軍于禁救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-84', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '關羽還當陽，西保麥城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-85', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '復與關羽更相覘伺，逐利見便，挾為卑辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-86', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後領護于禁軍，軍沒，為關羽所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-87', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及文帝即王位，權乃遣周，為牋魏王曰：「昔討關羽，獲于將軍，即白先王，當發遣之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-88', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '雖致命虜庭，梟獲關羽，功效淺薄，未報萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-048-89', 'p0131', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '漢王亦馮帝王之號，率巴、漢之民，乘危騁變，結壘千里，志報關羽之敗，圖收湘西之地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-051-90', 'p0131', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」禽關羽，定荊州，皎有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-051-91', 'p0131', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '從討關羽於華容，誘羽餘黨，得五千人，牛馬器械甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-92', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後從討關羽，封宣城侯，以綏南將軍代呂蒙領南郡太守，住公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-93', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉備東伐吳，吳王求和，瑾與備牋曰：「奄聞旗鼓來至白帝，或恐議臣以吳王侵取此州，危害關羽，怨深禍大，不宜荅和，此用心於小，未留意於大者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-94', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '陛下以關羽之親何如先帝？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-95', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」臣松之云：以為劉后以庸蜀為關河，荊楚為維翰，關羽揚兵沔、漢，志陵上國，雖匡主定霸，功未可必，要為威聲遠震，有其經略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-96', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-97', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」後備西圖璋，留關羽守，權曰：「猾虜乃敢挾詐！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-98', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '酒酣，蒙問肅曰：「君受重任，與關羽為鄰，將何計略，以備不虞？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-99', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」蒙曰：「今東西雖為一家，而關羽實熊虎也，計安可不豫定？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-100', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '兄今代公瑾，旣難為繼，且與關羽為鄰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-101', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉備令關羽鎮守，專有荊土，權命蒙西取長沙、零、桂三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-102', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '關羽在南郡，今至尊身自臨之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-103', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '與關羽分土接境，知羽驍雄，有并兼心，且居國上流，其勢難乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-104', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙勇而有謀斷，識軍計，譎郝普，禽關羽，最其妙者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-105', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權討關羽，欽督水軍入沔，還，道病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-106', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後權破關羽，欲進圖蜀，拜泰漢中太守、奮威將軍，封陵陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-107', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨魯肅鎮益陽，拒關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-108', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '羽聞之，住不渡，而結柴營，今遂名此處為關羽瀨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-109', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權征關羽，璋與朱然斷羽走道，到臨沮，住夾石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-056-110', 'p0131', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '建安二十四年，從討關羽，別與潘璋到臨沮禽羽，遷昭武將軍，封西安鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-056-111', 'p0131', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '權討關羽，過範館，謂曰：「昔早從卿言，無此勞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-057-112', 'p0131', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '呂蒙圖取關羽，稱疾還建業，以翻兼知醫術，請以自隨，亦欲因此令翻得釋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-057-113', 'p0131', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '關羽旣敗，權使翻筮之，得兌下坎上，節，五爻變之臨，翻曰：「不出二日，必當斷頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-058-114', 'p0131', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '呂蒙稱疾詣建業，遜往見之，謂曰：「關羽接境，如何遠下，後不當可憂也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-058-115', 'p0131', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '永安二年，拜鎮軍將軍，都督西陵，自關羽至白帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-060-116', 'p0131', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-060-117', 'p0131', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '安成長吳碭及中郎將袁龍等首尾關羽，復為反亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-061-118', 'p0131', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫權殺關羽，并荊土，拜濬輔軍中郎將，授以兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-062-119', 'p0131', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '呂蒙圖襲關羽，權以問儀，儀善其計，勸權聽之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-063-120', 'p0131', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權與呂蒙謀襲關羽，議之近臣，多曰不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-121', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '及蜀將關羽圍曹仁於樊，于禁等七軍皆沒，脩、方果降羽，而仁圍甚急焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-122', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '關羽新破，諸為惡者藏竄觀望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-123', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '帝曰：「孫權新破關羽，此其欲自結之時也，必不敢為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a03-009-0', 'p0132', 'houhanshu', 'a03-009', '《後漢書·卷九》', '燕剽勇，軍中號曰張飛燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-001-1', 'p0132', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-001-2', 'p0132', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，張飛、馬超走漢中，陰平氐強端斬吳蘭，傳其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-003-3', 'p0132', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及劉備走小沛，張飛隨之，過謂宜祿曰：「人取汝妻，而為之長，何蚩蚩若是邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-008-4', 'p0132', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '典略曰：黑山、黃巾諸帥，本非冠蓋，自相號字，謂騎白馬者為張白騎，謂輕捷者為張飛燕，謂聲大者為張雷公，其饒鬚者則自稱于羝根，其眼大者自稱李大目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-009-5', 'p0132', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '初，建安五年，時霸從妹年十三四，在本郡，出行樵採，為張飛所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-009-6', 'p0132', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '備遣張飛屯固山，欲斷軍後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-7', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-8', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張飛、關羽者，皆萬人之敵也，為之死用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-9', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-014-10', 'p0132', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-017-11', 'p0132', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '進軍宕渠，為備將張飛所拒，引還南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-025-12', 'p0132', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-13', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '英雄記曰：備留張飛守下邳，引兵與袁術戰於淮陰石亭，更有勝負。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-14', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '陶謙故將曹豹在下邳，張飛欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-15', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '旣去，備謂張飛、關羽曰：「吾豈種菜者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-16', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-17', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備謂關羽、張飛曰：「彼欲致我，我今自結託於東而不往，非同盟之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-18', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-19', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-20', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-21', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-22', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主令張飛進兵宕渠，與郃等戰於瓦口，破郃等，郃收兵還南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-23', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-032-24', 'p0132', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '車騎將軍張飛為其左右所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-033-25', 'p0132', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-034-26', 'p0132', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '後主敬哀皇后，車騎將軍張飛長女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-27', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽、張飛等不恱，先主解之曰：「孤之有孔明，猶魚之有水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-28', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '先主自葭萌還攻璋，亮與張飛、趙雲等率衆泝江，分定郡縣，與先主共圍成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-29', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '張飛卒後，領司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-035-30', 'p0132', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-31', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主於鄉里合徒衆，而羽與張飛為之禦侮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-32', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '張飛字益德，涿郡人也，少與關羽俱事先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-33', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」張飛曰：「如是，當示之以禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-34', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '為呼人主字，幾為關羽、張飛所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-35', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '權聞備西征，大遣舟船迎妹，而夫人內欲將後主還吳，雲與張飛勒兵截江，乃得後主還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-36', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '亮率雲與張飛等俱泝江西上，平定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-37', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-036-38', 'p0132', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '評曰：關羽、張飛皆稱萬人之敵，為世虎臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-39', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：張飛甞就巴宿，巴不與語，飛遂忿恚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-40', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮謂巴曰：「張飛雖實武人，敬慕足下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-039-41', 'p0132', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-040-42', 'p0132', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-040-43', 'p0132', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主為漢中王，遷治成都，當得重將以鎮漢川，衆論以為必在張飛，飛亦以心自許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-041-44', 'p0132', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張飛自荊州由墊江入，璋授裔兵，拒張飛於德陽陌下，軍敗，還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-054-45', 'p0132', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-032-0', 'p0133', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-032-1', 'p0133', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-033-2', 'p0133', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年敗於長阪，備棄妻子走，趙雲傳曰「雲身抱弱子以免」，即後主也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-033-3', 'p0133', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年春三月，追謚故將軍趙雲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-034-4', 'p0133', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '值曹公軍至，追及先主於當陽長阪，于時困偪，棄后及後主，賴趙雲保護，得免於難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-034-5', 'p0133', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '夫人欲將太子歸吳，諸葛亮使趙雲勒兵斷江留太子，乃得止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-6', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '先主自葭萌還攻璋，亮與張飛、趙雲等率衆泝江，分定郡縣，與先主共圍成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-7', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年春，揚聲由斜谷道取郿，使趙雲、鄧芝為疑軍，據箕谷，魏大將軍曹真舉衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-035-8', 'p0133', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '自臣到漢中，中間朞年耳，然喪趙雲、陽羣、馬玉、閻芝、丁立、白壽、劉郃、鄧銅等及曲長屯將七十餘人，突將無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-036-9', 'p0133', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '趙雲字子龍，常山真定人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-036-10', 'p0133', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠、趙雲彊摯壯猛，並作爪牙，其灌、滕之徒歟？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a04-045-11', 'p0133', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '自豫州隨先主，名位常亞趙雲，俱以忠勇稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0133-a05-012-12', 'p0133', 'jinshu', 'a05-012', '《晉書·卷十二》', '韓雲如布，趙雲如牛，楚雲如日，宋雲如車，魯雲如馬，衞雲如犬，周雲如車輪，秦雲如行人，魏雲如鼠，鄭雲如絳衣，越雲如龍，蜀雲如囷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-009-0', 'p0134', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十六年秋九月庚戌，曹操與韓遂、馬超戰於渭南，遂等大敗，關西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-009-1', 'p0134', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馬超破涼州，殺刺史韋康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-069-2', 'p0134', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '從征馬超，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-070-3', 'p0134', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '後為馬超所圍，堅守歷時，救軍不至，遂為超所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-072-4', 'p0134', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '馬超率萬餘人攻兾城，阜率國士大夫及宗族子弟勝兵者千餘人，使弟岳於城上作偃月營，與超接戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a03-075-5', 'p0134', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '韓遂、馬超之亂，關西民奔魯者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-6', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時關中諸將疑繇欲自襲，馬超遂與韓遂、楊秋、李堪、成宜等叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-7', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超餘衆梁興等屯藍田，使夏侯淵擊平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-8', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超、成宜，同惡相濟，濵據河、潼，求逞所欲，殄之渭南，獻馘萬計，遂定邊境，撫和戎狄，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-9', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '馬超在漢陽，復因羌、胡為害，氐王千萬叛應超，屯興國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-10', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-001-11', 'p0134', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，張飛、馬超走漢中，陰平氐強端斬吳蘭，傳其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-12', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓遂、馬超之亂，關西民從子午谷奔之者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-13', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '馬超等反，不肯從，超破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-008-14', 'p0134', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安十六年，並與馬超合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-15', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '馬超圍涼州刺史韋康於兾，淵救康，未到，康敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-16', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '氐王千萬逃奔馬超，餘衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-009-17', 'p0134', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖討馬超，以仁行安西將軍，督諸將拒潼關，破超渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-18', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後為馬超所圍，堅守歷時，救軍不至，遂為超所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-19', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧曰：「關中將帥以十數，莫能相一，唯韓遂、馬超最彊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-010-20', 'p0134', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖後與韓遂、馬超戰於渭南，超等索割地以和，并求任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-011-21', 'p0134', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '建安十六年，百姓聞馬超叛，避兵入山者千餘家，飢乏，漸相劫略，昭常遜辭以解之，是以寇難消息，衆咸宗焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-012-22', 'p0134', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」從破馬超等，子伯功為多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-012-23', 'p0134', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖為司空，辟為掾屬，從西征馬超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-013-24', 'p0134', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '後馬超反，超劫洪，將詣華陰，使作露布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-014-25', 'p0134', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏書曰：太祖征馬超，文帝留守，使昱參軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-26', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會約西討張猛，留行守舊營，而馬超等結反謀，舉約為都督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-27', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖征馬超，至弘農，曰「此西道之要」，以逵領弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-015-28', 'p0134', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '十六年，馬超反，大軍西討，沛隨軍，都督孟津渡事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-016-29', 'p0134', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韓遂、馬超之叛也，弘農、馮翊多舉縣邑以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-016-30', 'p0134', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '始，京兆從馬超破後，民人多不專於農殖，又歷數四二千石，取解目前，亦不為民作乆遠計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-017-31', 'p0134', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破馬超、韓遂於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-017-32', 'p0134', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '韓遂、馬超等反關右，遣晃屯汾陰以撫河東，賜牛酒，令上先人墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-018-33', 'p0134', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討韓遂、馬超於潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-018-34', 'p0134', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '馬超走奔上邽，郡人任養等舉衆迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-021-35', 'p0134', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-022-36', 'p0134', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '會馬超作亂，大軍西征，太祖見官屬曰：「今當遠征，而此方未定，以為後憂，宜得清公大德以鎮統之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-023-37', 'p0134', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖徙出故韓遂、馬超等兵五千餘人，使平難將軍殷署等督領，以儼為關中護軍，盡統諸軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-023-38', 'p0134', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '及馬超反，幹郡近超，民人分散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-024-39', 'p0134', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-024-40', 'p0134', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '是以周、鄭交惡，漢高請羹，隗嚻捐子，馬超背父，其為酷忍如此之極也，安在其因質委誠，取任永固哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-41', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '馬超之戰敗渭南也，走保諸戎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-42', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '馬超背父叛君，虐殺州將，豈獨阜之憂責，一州士大夫皆蒙其恥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-43', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '建安中，馬超攻兾，害涼州刺史韋康，州人悽然，莫不感憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-44', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會馬超攻兾，異躬著布韝，佐昂守備，又悉脫所佩環、黼黻以賞戰士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-025-45', 'p0134', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-030-46', 'p0134', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '近去建安中，興國氐王阿貴、白項氐王千萬各有部落萬餘，至十六年，從馬超為亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-032-47', 'p0134', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-032-48', 'p0134', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-033-49', 'p0134', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-50', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽聞馬超來降，舊非故人，羽書與諸葛亮，問超人才可誰比類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-51', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '馬超字孟起，右扶風茂陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-52', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '故羽聞馬超歸降，以書問諸葛亮「超人才可誰比類」，不得如書所云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-53', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-036-54', 'p0134', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '馬超阻戎負勇，以覆其族，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-040-55', 'p0134', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕聞當遠出，私情不恱，往詣馬超。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-043-56', 'p0134', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主嘉之，從至雒城，遣恢至漢中交好馬超，超遂從命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-054-57', 'p0134', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今北土旣未平安，加馬超、韓遂尚在關西，為操後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0134-a04-054-58', 'p0134', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乞與奮威俱進取蜀，得蜀而并張魯，因留奮威固守其地，好與馬超結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a03-053-0', 'p0135', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '大將軍何進連徵不詣，進必欲致之，使蟠同郡黃忠書勸曰：「前莫府初開，至如先生，特加殊禮，優而不名，申以手筆，設几杖之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-1', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '乃使黃忠、卓膺勒兵向璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-2', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主命黃忠乘高鼓譟攻之，大破淵軍，斬淵及曹公所署益州刺史趙顒等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-032-3', 'p0135', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-033-4', 'p0135', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-5', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠字漢升，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-6', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠以為可取，雲兵隨忠取米。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-7', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-036-8', 'p0135', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '黃忠、趙雲彊摯壯猛，並作爪牙，其灌、滕之徒歟？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-037-9', 'p0135', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」先主命黃忠乘高鼓譟攻之，大破淵軍，淵等授首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0135-a04-041-10', 'p0135', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主為漢中王，遣詩拜關羽為前將軍，羽聞黃忠為後將軍，羽怒曰：「大丈夫終不與老兵同列！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-006-0', 'p0136', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-032-1', 'p0136', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張松令法正白先主，及謀臣龐統進說，便可於會所襲璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-033-2', 'p0136', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-036-3', 'p0136', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-4', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '龐統字士元，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-5', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '龐統懼斯言之泄宣，知其君之必悟，故衆中匡其失，而不脩常謙之道，矯然太當，盡其謇諤之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-037-6', 'p0136', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '評曰：龐統雅好人流，經學思謀，于時荊、楚謂之高俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-7', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕欲納說先主，乃往見龐統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-8', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '會公來西，僕因法孝直自衒鬻，龐統斟酌其間，遂得詣公於葭萌，指掌而譚，論治世之務，講霸王之業，建取益州之策，公亦宿慮明定，即相然贊，遂舉事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-9', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '昔每與龐統共相誓約，庶託足下末蹤，盡心於主公之業，追名古人，載勳竹帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-040-10', 'p0136', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-045-11', 'p0136', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '存素不服龐統，統中矢卒，先主發言嘉歎，存曰：「統雖盡忠可惜，然違大雅之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-045-12', 'p0136', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：習禎有風流，善談論，名亞龐統，而在馬良之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0136-a04-057-13', 'p0136', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻舊齒名盛，龐統荊州令士，年亦差長，皆與績友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a03-075-0', 'p0137', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '蜀志曰：「法正字孝直，扶風郿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-013-1', 'p0137', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '臣又疾病，前後歷年，氣力日微，尸素重祿，曠廢職任，罪明法正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-2', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '」璋皆然之，遣法正連好先主，尋又令正及孟達送兵數千助先主守禦，正遂還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-3', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '」璋又從之，遣法正請先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-031-4', 'p0137', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-5', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」璋然之，遣法正將四千人迎先主，前後賂遺以巨億計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-6', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '吳書曰：備前見張松，後得法正，皆厚以恩意接納，盡其殷勤之歡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-7', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張松令法正白先主，及謀臣龐統進說，便可於會所襲璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-8', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」張松書與先主及法正曰：「今大事垂可立，如何釋此去乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-9', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-032-10', 'p0137', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-034-11', 'p0137', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '羣下勸先主聘后，先主疑與瑁同族，法正進曰：「論其親踈，何與晉文之於子圉乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-12', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-13', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣松之以為亮之異美，誠所願聞，然冲之所說，實皆可疑，謹隨事難之如左：其一事曰：亮刑法峻急，刻剥百姓，自君子小人咸懷怨歎，法正諫曰：「昔高祖入關，約法三章，秦民知德，今君假借威力，跨據一州，初有其國，未垂惠撫；且客主之義，宜相降下，願緩刑弛禁，以慰其望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-035-14', 'p0137', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」難曰：案法正在劉主前死，今稱法正諫，則劉主在也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-036-15', 'p0137', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-036-16', 'p0137', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-17', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正字孝直，右扶風郿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-18', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正以靖方隗，未為不當，而盛以封墓式閭為難，何其迃哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-19', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '或謂諸葛亮曰：「法正於蜀郡太縱橫，將軍宜啟主公，抑其威福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-20', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-037-21', 'p0137', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '法正著見成敗，有奇畫策筭，然不以德素稱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-038-22', 'p0137', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-039-23', 'p0137', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：璋遣法正迎劉備，巴諫曰：「備，雄人也，入必為害，不可內也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-039-24', 'p0137', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建安二十四年，先主為漢中王，巴為尚書，後代法正為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-040-25', 'p0137', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，劉璋遣扶風孟達副法正，各將兵二千人，使迎先主，先主因令達并領其衆，留屯江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-040-26', 'p0137', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '統大善之，而法正宿自知羕，遂並致之先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0137-a04-041-27', 'p0137', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '」時蜀郡太守法正從先主北行，亮於是表洪領蜀郡太守，衆事皆辦，遂使即真。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a03-009-0', 'p0138', 'houhanshu', 'a03-009', '《後漢書·卷九》', '山陽公載記曰：「時許靖在巴郡，聞立諸王，曰：『將欲歙之，必姑張之；將欲奪之，必姑與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a03-068-1', 'p0138', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '劭邑人李逵，壯直有高氣，劭初善之，而後為隙，又與從兄靖不睦，蜀志曰：「許靖字文休，少與從弟劭俱知名，並有人倫臧否之稱，而私情不協。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-013-2', 'p0138', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '肅父朗與許靖書云：肅生於會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-3', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-4', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-5', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '太傅許靖、安漢將軍糜笁、軍師將軍諸葛亮、太常賴恭、光祿勳黃柱、少府王謀等上言：「曹丕篡弒，湮滅漢室，竊據神器，劫迫忠良，酷烈無道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-032-6', 'p0138', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '以諸葛亮為丞相，許靖為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-037-7', 'p0138', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '十九年，進圍成都，璋蜀郡太守許靖將踰城降，事覺，不果。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-037-8', 'p0138', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '正說曰：「天下有獲虛譽而無其實者，許靖是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-9', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖字文休，汝南平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-10', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖羇客會稽，閭閻之士，孫策之來，於靖何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-11', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖號為臧否，至蜀，見商而稱之曰：「設使商生於華夏，雖王景興無以加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-12', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '在郡十載，卒於官，許靖代之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-038-13', 'p0138', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '評曰：許靖夙有名譽，旣以篤厚為稱，又以人物為意，雖行事舉動，未悉允當，蔣濟以為「大較廊廟器」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-039-14', 'p0138', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '祗字奉宗，汝南人，許靖兄之外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-040-15', 'p0138', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '姿性驕傲，多所輕忽，惟敬同郡秦子勑，薦之於太守許靖曰：「昔高宗夢傅說，周文求呂尚，爰及漢祖，納食其於布衣，此乃帝王之所以倡業垂統，緝熈厥功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-042-16', 'p0138', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '建安中，與許靖等俱自交州入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0138-a04-044-17', 'p0138', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '時許靖喪子，允與禕欲共會其葬所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-032-0', 'p0140', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-032-1', 'p0140', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣麋笁、孫乾與劉表相聞，表自郊迎，以上賔禮待之，益其兵，使屯新野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-2', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孫乾字公祐，北海人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-3', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主至荊州，雍與麋笁、孫乾同為從事中郎，常為談客，往來使命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-4', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '益州旣定，以籍為左將軍從事中郎，見待亞於簡雍、孫乾等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0140-a04-038-5', 'p0140', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-032-0', 'p0141', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-1', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主定益州，乾自從事中郎為秉忠將軍，見禮次麋笁，與簡雍同等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-2', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '簡雍字憲和，涿郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-3', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '益州旣定，以籍為左將軍從事中郎，見待亞於簡雍、孫乾等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0141-a04-038-4', 'p0141', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0142-a04-038-0', 'p0142', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '麋笁、孫乾、簡雍、伊籍，皆雍容風議，見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-031-0', 'p0143', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後丞相諸葛亮問秦宓以扶所長，宓曰：「董扶襃秋毫之善，貶纖芥之惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-1', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '秦宓字子勑，廣漢緜竹人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-2', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後丞相亮問秦宓以安所長，宓曰：「記人之善，忘人之過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-038-3', 'p0143', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '秦宓始慕肥遯之高，而無若愚之實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-040-4', 'p0143', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '伏見處士緜竹秦宓，膺山甫之德，履雋生之直，枕石漱流，吟詠縕袍，偃息於仁義之途，恬惔於浩然之域，高概節行，守真不虧，雖古人潛遁，蔑以加旃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0143-a04-042-5', 'p0143', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '建興二年，丞相亮領益州牧，選迎皆妙簡舊德，以秦宓為別駕，五梁為功曹，微為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-020-0', 'p0144', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '魏書載璽書曰：「制詔彭城王：有司奏，王遣司馬董和，齎珠玉來到京師中尚方，多作禁物，交通工官，出入近署，踰侈非度，慢令違制，繩王以法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-032-1', 'p0144', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-039-2', 'p0144', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '董和字幼宰，南郡枝江人也，其先本巴郡江州人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-039-3', 'p0144', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-043-4', 'p0144', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '太守董和以習方土大姓，寢而不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0144-a04-047-5', 'p0144', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，克之，獲廬江太守朱光及參軍董和，男女數萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-032-0', 'p0145', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-038-1', 'p0145', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-039-2', 'p0145', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '劉巴字子初，零陵烝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-039-3', 'p0145', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-040-4', 'p0145', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-040-5', 'p0145', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主稱尊號，東征吳，儀與尚書令劉巴不睦，左遷遙署弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0145-a04-043-6', 'p0145', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主已還永安，見忠與語，謂尚書令劉巴曰：「雖亡黃權，復得狐篤，此為世不乏賢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-032-0', 'p0146', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '通武陵，遣侍中馬良安慰五谿蠻夷，咸相率響應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-1', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '馬良字季常，襄陽宜城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-2', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」良即為草曰：「寡君遣掾馬良通聘繼好，以紹昆吾、豕韋之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-039-3', 'p0146', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-040-4', 'p0146', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '恭作治中無綱紀；朗昔奉馬良兄弟，謂為聖人，今作長史，素能合道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0146-a04-045-5', 'p0146', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：習禎有風流，善談論，名亞龐統，而在馬良之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-003-0', 'p0147', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '王師方振，膽破氣奪，馬謖、高祥望旗奔敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-009-1', 'p0147', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝遣真督諸軍軍郿，遣張郃擊亮將馬謖，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-017-2', 'p0147', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '加郃位特進，遣督諸軍，拒亮將馬謖於街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-026-3', 'p0147', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，蜀相諸葛亮出祁山，遣將軍馬謖至街亭，高詳屯列柳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-035-4', 'p0147', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏明帝西鎮長安，命張郃拒亮，亮使馬謖督諸軍在前，與郃戰于街亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-035-5', 'p0147', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '詔策亮曰：「街亭之役，咎由馬謖，而君引愆，深自貶抑，重違君意，聽順所守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-039-6', 'p0147', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '先主臨薨謂亮曰：「馬謖言過其實，不可大用，君其察之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-041-7', 'p0147', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '朗素與馬謖善，謖逃亡，朗知情不舉，亮恨之，免官還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-041-8', 'p0147', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '自去長史，優游無事垂三十年，臣松之案：朗坐馬謖免長史，則建興六年中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-043-9', 'p0147', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '建興六年，屬參軍馬謖先鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-043-10', 'p0147', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '丞相亮旣誅馬謖及將軍張休、李盛，奪將軍黃襲等兵，平特見崇顯，加拜參軍，統五部兼當營事，進位討寇將軍，封亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-044-11', 'p0147', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會馬謖敗於街亭，亮拔將西縣千餘家及維等還，故維遂與母相失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0147-a04-045-12', 'p0147', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '馬謖在前敗績，亮將殺之，邈諫以「秦赦孟明，用霸西戎，楚誅子玉，二世不競」，失亮意，還蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-035-0', 'p0148', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」乃遣衞尉陳震慶權正號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-039-1', 'p0148', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳震字孝起，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-039-2', 'p0148', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0148-a04-047-3', 'p0148', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '六月，蜀遣衞尉陳震慶權踐位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-035-0', 'p0149', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-1', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-2', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '董允字休昭，掌軍中郎將和之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-3', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '上疏曰：「侍中郭攸之 ‧ 費禕、侍郎董允等，先帝簡拔以遺陛下，至於斟酌規益，進盡忠言，則其任也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-4', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之以為陳羣子泰，陸遜子抗，傳皆以子繫父，不別載姓，及王肅、杜恕、張承、顧劭之流，莫不皆然，惟董允獨否，未詳其意，當以允名位優重，事跡踰父故邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-5', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '後入為尚書，代董允為尚書令，衆事無留，門無停賔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-039-6', 'p0149', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '評曰：董和蹈羔羊之素，劉巴履清尚之節，馬良貞實，稱為令士，陳震忠恪，老而益篤，董允匡主，義形於色，皆蜀臣之良矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-040-7', 'p0149', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主以問侍中董允、留府長史蔣琬，琬、允咸保儀疑延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-8', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會先主定蜀，禕遂留益土，與汝南許叔龍、南郡董允齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-9', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '董允代禕為尚書令，欲斆禕之所行，旬日之中，事多愆滯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0149-a04-044-10', 'p0149', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '後主曰：「皓趨走小臣耳，往董允切齒，吾常恨之，君何足介意！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-0', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂卒，祗又以侍中守尚書令，加鎮軍將軍，大將軍姜維雖班在祗上，常率衆在外，希親朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-1', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂字季陽，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-039-2', 'p0150', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂臨郡則垂稱，處朝則被損，亦黃、薛之流亞矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0150-a04-041-3', 'p0150', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '遷司鹽校尉，較鹽鐵之利，利入甚多，有裨國用，於是簡取良才以為官屬，若呂乂、杜祺、劉幹等，終皆至大官，自連所拔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-003-0', 'p0151', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '干寶晉紀曰：達初入新城，登白馬塞，歎曰：「劉封、申耽，據金城千里而失之乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-019-1', 'p0151', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」魏略曰：太祖在漢中，而劉備栖於山頭，使劉封下挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-032-2', 'p0151', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣劉封、孟達、李平等攻申耽於上庸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-040-3', 'p0151', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '劉封者，本羅侯寇氏之子，長沙劉氏之甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-040-4', 'p0151', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '評曰：劉封處嫌疑之地，而思防不足以自衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0151-a04-041-5', 'p0151', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '嗚呼孟子，斯實劉封侵陵足下，以傷先主待士之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0152-a04-040-0', 'p0152', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-0', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-1', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮表立曰：「長水校尉廖立，坐自貴大，臧否羣士，公言國家不任賢達而任俗吏，又言萬人率者皆小子也；誹謗先帝，疵毀衆臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-2', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」詔曰：「三苗亂政，有虞流宥，廖立狂惑，朕不忍刑，亟徙不毛之地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-3', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮之使廖立垂泣，李平致死，豈徒無怨言而已哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0153-a04-040-4', 'p0153', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-0', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋復遣李嚴督緜竹諸軍，嚴率衆降先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-1', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-2', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-032-3', 'p0154', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主病篤，託孤於丞相亮，尚書令李嚴為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-033-4', 'p0154', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年春，都護李嚴自永安還住江州，築大城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-038-5', 'p0154', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-6', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立本意，自謂才名宜為諸葛亮之貳，而更游散在李嚴等下，常懷怏怏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-7', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '李嚴字正方，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-8', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主立，封都鄉侯，班位每亞李嚴，為衞尉中軍師後將軍，遷車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-040-9', 'p0154', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-10', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主定蜀，太守李嚴命為功曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-11', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '始洪為李嚴功曹，嚴未至犍為而洪已為蜀郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-041-12', 'p0154', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '為牙門將，統屬江州督李嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-043-13', 'p0154', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '都護李嚴與闓書六紙，解喻利害，闓但荅一紙曰：「蓋聞天無二日，土無二王，今天下鼎立，正朔有三，是以遠人惶惑，不知所歸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-045-14', 'p0154', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '觀建安十八年參李嚴軍，拒先主於緜竹，與嚴俱降，先主旣定益州，拜為裨將軍，後為巴郡太守、江州都督，建興元年封都亭侯，加振威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0154-a04-045-15', 'p0154', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '都護李嚴性自矜高，護軍輔匡等年位與嚴相次，而嚴不與親褻；觀年少嚴二十餘歲，而與嚴通狎如時輩云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-0', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-1', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '劉琰字威碩，魯國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0155-a04-040-2', 'p0155', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-032-0', 'p0156', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '拔魏延為都督，鎮漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-033-1', 'p0156', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，魏延破魏雍州刺史郭淮于陽谿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-033-2', 'p0156', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '征西大將軍魏延與丞相長史楊儀爭權不和，舉兵相攻，延敗走；斬延首，儀率諸軍還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-3', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '郭沖三事曰：亮屯于陽平，遣魏延諸軍并兵東下，亮惟留萬人守城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-4', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '案魏延傳云：「延每隨亮出，輒欲請精兵萬人，與亮異道會于潼關，亮制而不許；延常謂亮為怯，歎己才用之不盡也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-035-5', 'p0156', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮使魏延、高翔、吳班赴拒，大破之，獲甲首三千級、玄鎧五千領、角弩三千一百張，宣王還保營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-039-6', 'p0156', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '建興六年，亮出軍向祁山，時有宿將魏延、吳壹等，論者皆言以為宜令為先鋒，而亮違衆拔謖，統大衆在前，與魏將張郃戰于街亭，為郃所破，士卒離散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-039-7', 'p0156', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-8', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-9', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '建興十年，與前軍師魏延不和，言語虛誕，亮責讓之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-10', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '魏延字文長，義陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-11', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '且魏延何人，當為楊儀所部勒，作斷後將乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-12', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮深惜儀之才幹，憑魏延之驍勇，常恨二人之不平，不忍有所偏廢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-040-13', 'p0156', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-043-14', 'p0156', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '十二年，亮卒於武功，軍退還，魏延作亂，一戰而敗，平之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-044-15', 'p0156', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '值軍師魏延與長史楊儀相憎惡，每至並坐爭論，延或舉刃擬儀，儀泣涕橫集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-044-16', 'p0156', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '初，先主留魏延鎮漢中，皆實兵諸圍以禦外敵，敵若來攻，使不得入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a04-045-17', 'p0156', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '建興八年，與魏延入南安界，破魏將費瑤，徙亭侯，進封高陽鄉侯，遷左將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0156-a05-001-18', 'p0156', 'jinshu', 'a05-001', '《晉書·卷一》', '亮部將楊儀、魏延爭權，儀斬延，并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-033-0', 'p0157', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '征西大將軍魏延與丞相長史楊儀爭權不和，舉兵相攻，延敗走；斬延首，儀率諸軍還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-033-1', 'p0157', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年春正月，中軍師楊儀廢徙漢嘉郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-035-2', 'p0157', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」漢晉春秋曰：楊儀等整軍而出，百姓奔告宣王，宣王追焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-039-3', 'p0157', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-4', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-5', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '唯楊儀不假借延，延以為至忿，有如水火。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-6', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-7', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '且魏延何人，當為楊儀所部勒，作斷後將乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-8', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '亮長史楊儀宿與延不和，見延攝行軍事，懼為所害，乃張言延欲舉衆北附，遂率其衆攻延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-9', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '楊儀字威公，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-040-10', 'p0157', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '彭羕、廖立以才拔進，李嚴以幹局達，魏延以勇略任，楊儀以當官顯，劉琰舊仕，並咸貴重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-044-11', 'p0157', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '值軍師魏延與長史楊儀相憎惡，每至並坐爭論，延或舉刃擬儀，儀泣涕橫集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a04-045-12', 'p0157', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：楊顒字子昭，楊儀宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-13', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '亮長史楊儀反旗鳴皷，若將距帝者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-14', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '帝以窮寇不之逼，於是楊儀結陣而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0157-a05-001-15', 'p0157', 'jinshu', 'a05-001', '《晉書·卷一》', '亮部將楊儀、魏延爭權，儀斬延，并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0158-a04-041-0', 'p0158', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '霍峻字仲邈，南郡枝江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0158-a04-041-1', 'p0158', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a03-088-0', 'p0159', 'houhanshu', 'a03-088', '《後漢書·卷八十八》', '其後疏勒王連相殺害，朝廷亦不能禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-039-1', 'p0159', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '初，先主定益州，置鹽府校尉，較鹽鐵之利，後校尉王連請乂及南陽杜祺、南鄉劉幹等並為典曹都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-040-2', 'p0159', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '王連流俗，苟作掊克，使百姓疲弊，以致今日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-3', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '王連字文儀，南陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-4', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '後主踐阼，為步兵校尉，代王連領丞相長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0159-a04-041-5', 'p0159', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-034-0', 'p0160', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '今以貴人為皇后，使行丞相事左將軍向朗持節授璽綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-040-1', 'p0160', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '如向朗、文恭，凡俗之人耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-2', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '向朗字巨達，襄陽宜城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-3', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '洪對曰：「裔天姿明察，長於治劇，才誠堪之，然性不公平，恐不可專任，不如留向朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0160-a04-041-4', 'p0160', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-032-0', 'p0161', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-033-1', 'p0161', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '先是，益州郡有大姓雍闓反，流太守張裔於吳，據郡不賔，越嶲夷王高定亦背叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-2', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張裔字君嗣，蜀郡成都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-3', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '五年，丞相亮北住漢中，欲用張裔為留府長史，問洪何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-041-4', 'p0161', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-043-5', 'p0161', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '初，建寧郡殺太守正昂，縛太守張裔於吳，故都督常駐平夷縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-044-6', 'p0161', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '五年，亮住漢中，琬與長史張裔統留府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-044-7', 'p0161', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '亮與留府長史張裔、參軍蔣琬書曰：「姜伯約忠勤時事，思慮精密，考其所有，永南、季常諸人不如也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0161-a04-045-8', 'p0161', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-032-0', 'p0162', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-041-1', 'p0162', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '楊洪字季休，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0162-a04-041-2', 'p0162', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0163-a04-041-0', 'p0163', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '費詩字公舉，犍為南安人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0163-a04-041-1', 'p0163', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '評曰：霍峻孤城不傾，王連固節不移，向朗好學不倦，張裔膚敏應機，楊洪乃心忠公，費詩率意而言，皆有可紀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-033-0', 'p0164', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又諸葛亮以禪立之明年領益州牧，其年與主簿杜微書曰「朝廷今年十八」，與禪傳相應，理當非虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-042-1', 'p0164', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '杜微字國輔，梓潼涪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0164-a04-042-2', 'p0164', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '評曰：杜微脩身隱靜，不役當世，庶幾夷、皓之槩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-0', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝沈書曰：「太傅胡廣博綜舊儀，立漢制度，蔡邕依以為志，譙周後改定以為禮儀志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-1', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '譙周五經然否曰：「漢初或云三老荅天子拜，遭王莽之亂，法度殘缺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-094-2', 'p0166', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」譙周論之曰：「禮，尸服上服，猶以非親之故荅子拜，士見異國君亦荅拜，是皆不得視猶子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-095-3', 'p0166', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '先臘一日，大儺，譙周論語注曰：「儺，却之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-095-4', 'p0166', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」譙周論語注曰：「以葦矢射之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-100-5', 'p0166', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '謝沈書曰：「蔡邕撰建武已後，星驗著明，以續前志，譙周接繼其下者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-103-6', 'p0166', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '故泰山太守應劭、給事中董巴、散騎常侍譙周蜀志曰：「周字允南，巴西西充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a03-113-7', 'p0166', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '譙周巴記曰：「初平元年，趙穎分巴為二郡，欲得巴舊名，故郡以墊江為治，安漢以下為永寧郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-032-8', 'p0166', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-9', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '用光祿大夫譙周策，降於艾，奉書曰：「限分江、漢，遇值深遠，階緣蜀土，斗絕一隅，干運犯冒，漸苒歷載，遂與京畿攸隔萬里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-10', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '謹遣私署侍中張紹、光祿大夫譙周、駙馬都尉鄧良奉齎印緩，請命告誠，敬輸忠款，存亡勑賜，惟所裁之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-11', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '漢晉春秋曰：後主將從譙周之策，北地王諶怒曰：「若理窮力屈，禍敗必及，便當父子君臣背城一戰，同死社稷，以見先帝可也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-033-12', 'p0166', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-038-13', 'p0166', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '譙周蜀本紀曰：禹本汶山廣柔縣人也，生於石紐，其地名刳兒坪，見世帝紀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-041-14', 'p0166', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '充聞之曰：「吾聞譙周之言，先帝諱備，其訓具也，後主諱禪，其訓授也，如言劉已具矣，當授與人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-15', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '後進通儒譙周常問其意，瓊荅曰：「欲明此術甚難，須當身視，識其形色，不可信人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-16', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周字允南，巴西西充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-17', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '孫綽評曰：譙周說後主降魏，可乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-18', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '向使懷苟存之計，納譙周之言，何邦基之能構，令名之可獲哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-19', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年，後主從譙周之計，遣使請降於鄧艾，其書，正所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-20', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周詞理淵通，為世碩儒，有董、楊之規，郤正文辭燦爛，有張、蔡之風，加其行止，君子有取焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-042-21', 'p0166', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '張璠以為譙周所陳降魏之策，蓋素料劉禪懦弱，心無害戾，故得行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a04-045-22', 'p0166', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '又時人謂譙周無當世才，少歸敬者，唯戲重之，常稱曰：「吾等後世，終自不如此長兒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a05-011-23', 'p0166', 'jinshu', 'a05-011', '《晉書·卷十一》', '及班固敘漢史，馬遷續述天文，而蔡邕、譙周各有撰錄，司馬彪採之，以繼前志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0166-a05-011-24', 'p0166', 'jinshu', 'a05-011', '《晉書·卷十一》', '陳卓、范蠡、鬼谷先生、張良、諸葛亮、譙周、京房、張衡並云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-031-0', 'p0167', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '會益州刺史郤儉賦斂煩擾，儉，郤正祖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-1', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-2', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」郤正聞之，求見禪曰：「若王後問，宜泣而荅曰『先人墳墓遠在隴、蜀，乃心西悲，無日不思』，因閉其目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-033-3', 'p0167', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」會王復問，對如前，王曰：「何乃似郤正語邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-4', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '後進文士祕書郎郤正數從光諮訪，光問正太子所習讀并其情性好尚，正荅曰：「奉親虔恭，夙夜匪懈，有古世子之風；接待羣僚，舉動出於仁恕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-5', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '郤正字令先，河南偃師人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-042-6', 'p0167', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '譙周詞理淵通，為世碩儒，有董、楊之規，郤正文辭燦爛，有張、蔡之風，加其行止，君子有取焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-7', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '郤正著論論維曰：「姜伯約據上將之重，處羣臣之右，宅舍弊薄，資財無餘，側室無妾媵之褻，後庭無聲樂之娛，衣服取供，輿馬取備，飲食節制，不奢不約，官給費用，隨手消盡；察其所以然者，非以激貪厲濁，抑情自割也，直謂如是為足，不在多求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-8', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '臣松之以為郤正此論，取其可稱，不謂維始終行事皆可準則也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0167-a04-044-9', 'p0167', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '餘旣過苦，又非所以難郤正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a03-075-0', 'p0168', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」璋主簿巴西黃權諫曰：蜀志曰：「權字公衡，閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a03-075-1', 'p0168', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '先主曰：『孤負黃權，權不負孤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-002-2', 'p0168', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '八月，蜀大將黃權率衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-3', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，以鎮南將軍黃權為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-4', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏四月，車騎將軍黃權薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-004-5', 'p0168', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏初有孟達、黃權，在晉有孫秀、孫楷；達、權爵賞比壹為輕，秀、楷禮秩優異尤甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-031-6', 'p0168', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋主簿黃權陳其利害，從事廣漢王累自倒縣於州門以諫，璋一無所納，勑在所供奉先主，先主入境如歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-7', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及董和、黃權、李嚴等本璋之所授用也，吳壹、費觀等又璋之婚親也，彭羡又璋之所排擯也，劉巴者宿昔之所忌恨也，皆處之顯任，盡其器能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-8', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣黃權將兵迎張魯，張魯已降曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-9', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-032-10', 'p0168', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '鎮北將軍黃權督江北諸軍，與吳軍相拒於夷陵道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-037-11', 'p0168', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '統弟林，以荊州治中從事參鎮北將軍黃權征吳，值軍敗，隨權入魏，魏封列侯，至鉅鹿太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-037-12', 'p0168', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '曹公之破荊州，林婦與林分隔，守養弱女十有餘年，後林隨黃權降魏，始復集聚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-13', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '黃權字公衡，巴西閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-14', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主曰：「孤負黃權，權不負孤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-15', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '臣松之以為漢武用虛罔之言，滅李陵之家，劉主拒憲司所執，宥黃權之室，二主得失縣邈遠矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-16', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '先主已還永安，見忠與語，謂尚書令劉巴曰：「雖亡黃權，復得狐篤，此為世不乏賢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a04-043-17', 'p0168', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a05-013-18', 'p0168', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀記稱明帝問黃權曰：「天下鼎立，何地為正？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0168-a05-013-19', 'p0168', 'jinshu', 'a05-013', '《晉書·卷十三》', '正始元年四月，車騎將軍黃權薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-016-0', 'p0169', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '傅子曰：畿與太僕李恢、東安太守郭智有好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-043-1', 'p0169', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '李恢字德昂，建寧俞元人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a04-043-2', 'p0169', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0169-a05-015-3', 'p0169', 'jinshu', 'a05-015', '《晉書·卷十五》', '蜀以李恢為建寧太守，遙領交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-0', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '呂凱字季平、永昌不韋人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-1', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '亮至南，上表曰：「永昌郡吏呂凱、府丞王伉等，執忠絕域，十有餘年，雍闓、高定偪其東北，而凱等守義不與交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0170-a04-043-2', 'p0170', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-033-0', 'p0171', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，南夷劉胄反，將軍馬忠破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-1', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '馬忠字德信，巴西閬中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-2', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '是時，鄧芝在東，馬忠在南，平在北境，咸著名迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-3', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '拜為牙門將，屬馬忠，北討汶山叛羌，南平四郡蠻夷，輙有籌畫戰克之功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-4', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '益部耆舊傳曰：嶷受兵三百人，隨馬忠討叛羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-5', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '後南夷劉胄又反，以馬忠為督庲降討胄，嶷復屬焉，戰鬬常冠軍首，遂斬胄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-043-6', 'p0171', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '評曰：黃權弘雅思量，李恢公亮志業，呂凱守節不回，馬忠擾而能毅，尚書曰：擾而毅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-045-7', 'p0171', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '馬忠因其成基以破殄胄，丞相亮聞而善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-047-8', 'p0171', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，璋司馬馬忠獲羽及其子平、都督趙累等於章鄉，遂定荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a04-055-9', 'p0171', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '璋部下司馬馬忠禽羽，并羽子平、都督趙累等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0171-a05-006-10', 'p0171', 'jinshu', 'a05-006', '《晉書·卷六》', '十二月，劉聰故將王騰、馬忠等誅靳準，送傳國璽於劉曜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-017-0', 'p0172', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '竊聞大王平河北，開王業，此誠皇天祐漢，士人之福也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-018-1', 'p0172', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '永平十三年，坐與舅王平謀反，伏誅，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-027-2', 'p0172', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」武王平殷亂，而二人恥之，義不食周粟，餓死於首陽山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-041-3', 'p0172', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '與三府掾屬共考案楚獄顏忠、王平等，辭連及隧鄉侯耿建、朗陵侯臧信、護澤侯鄧鯉、曲成侯劉建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a03-042-4', 'p0172', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '十三年，男子燕廣告英與漁陽王平、顏忠等造作圖書，有逆謀，事下案驗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-030-5', 'p0172', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '王有五宮，一宮間相去十里，其王平旦之一宮聽事，至日暮一宿，明日復至一宮，五日一周。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-033-6', 'p0172', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-043-7', 'p0172', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平字子均，巴西宕渠人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-043-8', 'p0172', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平忠勇而嚴整，張嶷識斷明果，咸以所長，顯名發迹，遇其時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-044-9', 'p0172', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '劉敏，左護軍、揚威將軍，與鎮北大將軍王平俱鎮漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0172-a04-044-10', 'p0172', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及興勢之役，王平捍拒曹爽，皆承此制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-028-0', 'p0173', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '未到，聞其已破，退趣白水，與蜀將張翼、廖化等合守劒閣拒會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-028-1', 'p0173', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-033-2', 'p0173', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-036-3', 'p0173', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '公軍追至圍，此時沔陽長張翼在雲圍內，翼欲閉門拒守，而雲入營，更大開門，偃旗息鼓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-043-4', 'p0173', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '徵庲降都督張翼還，以忠代翼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-043-5', 'p0173', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '華陽國志曰：後張翼、廖化並為大將軍，時人語曰：「前有王、句，後有張、廖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-044-6', 'p0173', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-044-7', 'p0173', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-8', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '張翼字伯恭，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-9', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '官位與張翼齊，而在宗預之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a04-045-10', 'p0173', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0173-a05-002-11', 'p0173', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-0', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '以丞相留府長史蔣琬為尚書令，總統國事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-1', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '夏四月，進蔣琬位為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-2', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬十一月，大將軍蔣琬出屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-3', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二年春三月，進蔣琬位為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-4', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年冬十月，尚書令費禕至漢中，與蔣琬諮論事計，歲盡還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-5', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年冬十月，大司馬蔣琬自漢中還，住涪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-033-6', 'p0174', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬十一月，大司馬蔣琬卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-036-7', 'p0174', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-8', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '蔣琬後詣漢中，謂亮曰：「昔楚殺得臣，然後文公喜可知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-9', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-10', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '尚書令蔣琬領益州刺史，上疏以讓費禕及允，又表「允內侍歷年，翼贊王室，宜賜爵土以襃勳勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-039-11', 'p0174', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-12', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後丞相掾李邵、蔣琬至，立計曰：「軍當遠出，卿諸人好諦其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-13', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '後主以問侍中董允、留府長史蔣琬，琬、允咸保儀疑延。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-14', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，蔣琬率宿衞諸營赴難北行，行數十里，延死問至，乃旋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-040-15', 'p0174', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '而亮平生宓指，以儀性狷狹，意在蔣琬，琬遂為尚書令、益州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-041-16', 'p0174', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '建興三年，隨諸葛亮南行，歸至漢陽縣，降人李鴻來詣亮，亮見鴻，時蔣琬與詩在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-041-17', 'p0174', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '蔣琬秉政，以詩為諫議大夫，卒於家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-18', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '蔣琬、費禕等皆器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-19', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '大將軍蔣琬領刺史，徙為典學從事，緫州之學者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-042-20', 'p0174', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-21', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '八年，召為丞相參軍，副長史蔣琬署留府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-22', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '延熈五年還朝，因至漢中，見大司馬蔣琬，宣傳詔旨，加拜鎮南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-23', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '延熈元年，大將軍蔣琬住沔陽，平更為前護軍，署琬府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-043-24', 'p0174', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '十四年，武都氐王符健請降，遣將軍張尉往迎，過期不到，大將軍蔣琬深以為念。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-25', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '蔣琬字公琰、零陵湘鄉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-26', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '軍師將軍諸葛亮請曰：「蔣琬，社稷之器，非百里之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-27', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '頃之，代蔣琬為尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-28', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '亮與留府長史張裔、參軍蔣琬書曰：「姜伯約忠勤時事，思慮精密，考其所有，永南、季常諸人不如也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-29', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '延熈元年，隨大將軍蔣琬住漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-044-30', 'p0174', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '評曰：蔣琬方整有威重，費禕寬濟而博愛，咸承諸葛之成規，因循而不革，是以邊境無虞，邦家和一，然猶未盡治小之宜，居靜之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-31', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '亮卒，為尚書右選部郎，刺史蔣琬請為治中從事史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-32', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-33', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '後大將軍蔣琬問張休曰：「漢嘉前輩有王元泰，今誰繼者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-34', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '延熈初，大將軍蔣琬出征漢中，福以前監軍領司馬，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-045-35', 'p0174', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '乞復請，蔣琬之後，誰可任者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-047-36', 'p0174', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又蔣琬守漢中，聞司馬懿南向，不出兵乘虛以掎角之，反委漢中，還近成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0174-a04-061-37', 'p0174', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '江表傳曰：時濬姨兄零陵蔣琬為蜀大將軍，或有間濬於武陵太守衞旌者，云濬遣密使與琬相聞，欲有自託之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-004-0', 'p0175', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往歲偽大將軍費禕驅率羣衆，陰圖闚𨵦，道經漢壽，請會衆賔，脩於廣坐之中手刃擊禕，勇過聶政，功逾介子，可謂殺身成仁，釋生取義者矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-004-1', 'p0175', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏之與蜀，雖為敵國，非有趙襄滅智之仇，燕丹危亡之急；且劉禪凡下之主，費禕中才之相，二人存亡，固無關於興喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-009-2', 'p0175', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '費禕進兵據三嶺以截爽，爽爭嶮苦戰，僅乃得過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-3', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '四年冬十月，尚書令費禕至漢中，與蔣琬諮論事計，歲盡還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-4', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '以尚書令費禕為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-5', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年閏月，魏大將軍曹爽、夏侯玄等向漢中，鎮北大將軍王平拒興勢圍，大將軍費禕督諸軍往赴救，魏軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-6', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十二月，大將軍費禕至漢中，行圍守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-7', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '九年夏六月，費禕還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-8', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十一年夏五月，大將軍費禕出屯漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-9', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十四年夏，大將軍費禕還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-033-10', 'p0175', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十六年春正月，大將軍費禕為魏降人郭循所殺于漢壽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-035-11', 'p0175', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-036-12', 'p0175', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-13', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '上疏曰：「侍中郭攸之 ‧ 費禕、侍郎董允等，先帝簡拔以遺陛下，至於斟酌規益，進盡忠言，則其任也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-14', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '尚書令蔣琬領益州刺史，上疏以讓費禕及允，又表「允內侍歷年，翼贊王室，宜賜爵土以襃勳勞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-15', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '允甞與尚書令費禕、中典軍胡濟等共期游宴，嚴駕已辦，而郎中襄陽董恢詣允脩敬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-16', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '入蜀，以宣信中郎副費禕使吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-17', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，以侍中守尚書令，為大將軍費禕副貳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-18', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-039-19', 'p0175', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '多技藝，挾數術，費禕甚異之，故超繼允內侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-20', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-21', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-040-22', 'p0175', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '時人畏其言語不節，莫敢從也，惟後軍師費禕往慰省之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-23', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '蔣琬、費禕等皆器重之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-24', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '延熈九年秋，大赦，光於衆中責大將軍費禕曰：「夫赦者，偏枯之物，非明世所宜有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-25', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '刺史費禕命為從事，入為尚書郎，復辟禕大將軍東曹掾，稍遷尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-042-26', 'p0175', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-27', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '七年春，大將軍費禕北禦魏敵，留忠成都，平尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-28', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '涪諸軍及大將軍費禕自成都相繼而至，魏軍退還，如平本策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-043-29', 'p0175', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '嶷初見費禕為大將軍，恣性汎愛，待信新附太過，嶷書戒之曰：「昔岑彭率師，來歙杖節，咸見害於刺客，今明將軍位尊權重，宜鑒前事，少以為警。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-30', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是遣尚書令費禕、中監軍姜維等喻指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-31', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-32', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會大將軍費禕從成都至，魏軍即退，敏以功封雲亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-33', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '費禕字文偉，江夏鄳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-34', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '十年，遷衞將軍，與大將軍費禕共錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-35', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '每欲興軍大舉，費禕常裁制不從，與其兵不過萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-36', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：費禕謂維曰：「吾等不如丞相亦已遠矣；丞相猶不能定中夏，況吾等乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-044-37', 'p0175', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '評曰：蔣琬方整有威重，費禕寬濟而博愛，咸承諸葛之成規，因循而不革，是以邊境無虞，邦家和一，然猶未盡治小之宜，居靜之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-38', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先是，吳王孫權請和，先主累遣宋瑋、費禕等與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-39', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」權大笑，嘉其抗直，甚愛待之，見敬亞於鄧芝、費禕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-045-40', 'p0175', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '芝性驕慠，自大將軍費禕等皆避下之，而預獨不為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-053-41', 'p0175', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '江表傳曰：費禕聘于吳，陛見，公卿侍臣皆在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-064-42', 'p0175', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪別傳曰：權甞饗蜀使費禕，先逆勑羣臣：「使至，伏食勿起。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a04-064-43', 'p0175', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '昔魏人伐蜀，蜀人禦之，精嚴垂發，六軍雲擾，士馬擐甲，羽檄交馳，費禕時為元帥，荷國任重，而與來敏圍碁，意無厭倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0175-a05-002-44', 'p0175', 'jinshu', 'a05-002', '《晉書·卷二》', '林退，帝謂玄曰：「費禕以據險距守，進不獲戰，攻之不可，宜亟旋軍，以為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-0', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：是時姜維亦出圍狄道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-1', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '姜維有重兵而縣軍應恪，投食我麥，非深根之寇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-2', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '姜維聞淮進兵，軍食少，乃退屯隴西界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-3', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乃者蜀將姜維寇鈔脩郡，為所執略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-4', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '世語及魏氏春秋並云：此秋，姜維寇隴右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-5', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '八月辛亥，蜀大將軍姜維寇狄道，雍州刺史王經與戰洮西，經大敗，還保狄道城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-6', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，安西將軍鄧艾大破蜀大將姜維於上邽，詔曰：「兵未極武，醜虜摧破，斬首獲生，動以萬計，自頃戰克，無如此者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-7', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，蜀大將姜維寇洮陽，鎮西將軍鄧艾拒之，破維於侯和，維遁走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-004-8', 'p0176', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏五月，詔曰：「蜀，蕞爾小國，土狹民寡，而姜維虐用其衆，曾無廢志；往歲破敗之後，猶復耕種沓中，刻剥衆羌，勞役無已，民不堪命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-9', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '蜀大將軍姜維率衆依麴山築二城，使牙門將句安、李歆等守之，聚羌胡質任等寇偪諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-10', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '後年，雍州刺史王經白泰，云姜維、夏侯霸欲三道向祁山、石營、金城，求進兵為翅，使涼州軍至枹，討蜀護軍向祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-11', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '姜維之兵，是所辟之鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-022-12', 'p0176', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」泰曰：「姜維提輕兵深入，正欲與我爭鋒原野，求一戰之利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-026-13', 'p0176', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '姜維出石營，從彊川，乃西迎治無戴，留陰平太守廖化於成重山築城，斂破羌保質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-027-14', 'p0176', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '姜維因洮上之利，輕兵深入，糧餉不繼，軍覆上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-027-15', 'p0176', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '姜維深入，不待輜重，士衆飢餓，覆軍上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-16', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '嘉平元年，與征西將軍郭淮拒蜀偏將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-17', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '解雍州刺史王經圍於狄道，姜維退駐鍾提，乃以艾為安西將軍，假節、領護東羌校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-18', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '甘露元年詔曰：「逆賊姜維連年狡黠，民夷騷動，西土不寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-19', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」二年，拒姜維於長城，維退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-20', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」又曰：「姜維自一時雄兒也，與某相值，故窮耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-21', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '昔姜維有斷隴右之志，艾脩治備守，積糓彊兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-22', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文王以蜀大將姜維屢擾邊陲，料蜀國小民疲，資力單竭，欲大舉圖蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-23', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '姜維自沓中還，至陰平，合集士衆，欲赴關城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-24', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾追姜維到陰平，簡選精銳，欲從漢德陽入江由、左儋道詣緜竹，趣成都，與諸葛緒共行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-25', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '緒以本受節度邀姜維，西行非本詔，遂進軍前向白水，與會合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-26', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-27', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-28', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欲使姜維等皆將蜀兵出斜谷，會自將大衆隨其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-29', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '時方給與姜維鎧杖，白外有匈匈聲，似失火，有頃，白兵走向城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-028-30', 'p0176', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '姜維率會左右戰，手殺五六人，衆旣格斬維，爭赴殺會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-31', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '五年春正月，監軍姜維督偏軍，自漢中還屯涪縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-32', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十年，涼州胡王白虎文、治無戴等率衆降，衞將軍姜維迎逆安撫，居之于繁縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-33', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋，衞將軍姜維出攻雍州，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-34', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十三年，姜維復出西平，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-35', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '夏四月，衞將軍姜維復率衆圍南安，不克而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-36', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十七年春正月，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-37', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十八年春，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-38', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '十九年春，進姜維位為大將軍，督戎馬，與鎮西將軍胡濟期會上邽，濟失誓不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-39', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二十年，聞魏大將軍諸葛誕據壽春以叛，姜維復率衆出駱谷，至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-40', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '景耀元年，姜維還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-41', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，姜維復率衆出侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-42', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '」禪又遣太常張峻、益州別駕汝超受節度，遣太僕蔣顯有命勑姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-033-43', 'p0176', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '雖使諸葛亮在，不能輔之乆全，而況姜維邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-44', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮拔西縣千餘家，還于漢中，郭沖四事曰：亮出祁山，隴西、南安二郡應時降，圍天水，拔兾城，虜姜維，驅略士女數千人還蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-45', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維，天水之匹夫耳，獲之則於魏何損？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-46', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維謂亮曰：「辛佐治仗節而到，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-47', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '姜維令儀反旗鳴鼓，若將向宣王者，宣王乃退，不敢偪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-035-48', 'p0176', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '自瞻、厥、建統事，姜維常征伐在外，宦人黃皓竊弄機柄，咸共將護，無能匡矯，孫盛異同記曰：瞻、厥等以維好戰無功，國內疲弊，宜表後主，召還為益州刺史，奪其兵權；蜀長老猶有瞻表以閻宇代維故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-036-49', 'p0176', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」大將軍姜維等議，以為雲昔從先帝，勞績旣著，經營天下，遵奉法度，功效可書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-036-50', 'p0176', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '次子廣，牙門將，隨姜維沓中，臨陣戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-039-51', 'p0176', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '呂乂卒，祗又以侍中守尚書令，加鎮軍將軍，大將軍姜維雖班在祗上，常率衆在外，希親朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-52', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」後監軍姜維率偏軍經汶山，往詣立，稱立意氣不衰，言論自若。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-53', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-040-54', 'p0176', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '秋，亮病困，密與長史楊儀、司馬費禕、護軍姜維等作身歿之後退軍節度，令延斷後，姜維次之；若延或不從命，軍便自發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-042-55', 'p0176', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '子忠，亦博覽經學，有敏風，與尚書向充等並能協贊大將軍姜維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-043-56', 'p0176', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '魏狄道長李簡密書請降，衞將軍姜維率嶷等因簡之資以出隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-043-57', 'p0176', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '姜維之出，時論以嶷初還，股疾不能在行中，由是嶷自乞肆力中原，致身敵庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-58', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是遣尚書令費禕、中監軍姜維等喻指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-59', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '輙與費禕等議，以涼州胡塞之要，進退有資，賊之所惜；且羌、胡乃心思漢如渴，又昔偏軍入羌，郭淮破走，筭其長短，以為事首，宜以姜維為涼州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-60', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維字伯約，天水兾人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-61', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」孫盛雜記曰：初，姜維詣亮，與母相失，復得母書，令求當歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-62', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-63', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '盛以為古人云，非所困而困焉名必辱，非所據而據焉身必危，旣辱且危，死其將至，其姜維之謂乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-64', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '凡人之談，常譽成毀敗，扶高抑下，咸以姜維投厝無所，身死宗滅，以是貶削，不復料擿，異乎春秋襃貶之義矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-65', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '如姜維之樂學不倦，清素節約，自一時之儀表也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-66', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維策名魏室，而外奔蜀朝，違君徇利，不可謂忠；捐親苟免，不可謂孝；害加舊邦，不可謂義；敗不死難，不可謂節；且德政未敷而疲民以逞，居禦侮之任而致敵喪守，於夫智勇，莫可云也：凡斯六者，維無一焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-67', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '姜維粗有文武，志立功名，而翫衆黷旅，明斷不周，終致隕斃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-044-68', 'p0176', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '干寶曰：姜維為蜀相，國亡主辱弗之死，而死於鍾會之亂，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-69', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '於時人少所敬貴，唯器異姜維云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-70', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '十八年，與衞將軍姜維俱還成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-71', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '漢晉春秋曰：景耀五年，姜維率衆出狄道，廖化曰：「『兵不戢，必自焚』，伯約之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-72', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '延熈二十年，隨大將軍姜維出軍至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-73', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '大將軍姜維每出北征，羌、胡出馬牛羊氈毦及義穀裨軍糧，國賴其資。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-045-74', 'p0176', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a04-064-75', 'p0176', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '漢晉春秋曰：恪使司馬季無往蜀說姜維，令同舉，曰：「古人有言，聖人不能為時，時至亦不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-001-76', 'p0176', 'jinshu', 'a05-001', '《晉書·卷一》', '初，蜀將姜維聞毗來，謂亮曰：「辛毗杖節而至，賊不復出矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-77', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維之寇隴右也，征西將軍郭淮自長安距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-78', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '蜀將姜維又寇隴右，揚聲欲攻狄道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-79', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '雍州刺史陳泰欲先賊據狄道，帝曰：「姜維攻羌，收其質任，聚穀作邸閣訖，而復轉行至此，正欲了塞外諸羌，為後年之資耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-80', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '今絆姜維於沓中，使不得東顧，直指駱谷，出其空虛之地，以襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-81', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-002-82', 'p0176', 'jinshu', 'a05-002', '《晉書·卷二》', '姜維聞之，引還，王頎追敗維於強川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-013-83', 'p0176', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀將姜維攻隴西，車騎將軍郭淮討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-037-84', 'p0176', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '及蜀將姜維寇隴右，雍州刺史王經戰敗，遣孚西鎮關中，統諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0176-a05-037-85', 'p0176', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '先是蜀將姜維屢寇關中，及望至，廣設方略，維不得爲寇，關中賴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-033-0', 'p0177', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '遣尚書郎鄧芝固好於吳，吳王孫權與蜀和親使聘，是歲通好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-033-1', 'p0177', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋，涪陵屬國民夷反，車騎將軍鄧芝往討，皆破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-035-2', 'p0177', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年春，揚聲由斜谷道取郿，使趙雲、鄧芝為疑軍，據箕谷，魏大將軍曹真舉衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-036-3', 'p0177', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '亮令雲與鄧芝往拒，而身攻祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-040-4', 'p0177', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-041-5', 'p0177', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '會先主薨，諸葛亮遣鄧芝使吳，亮令芝言次可從權請裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-043-6', 'p0177', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '是時，鄧芝在東，馬忠在南，平在北境，咸著名迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-7', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '鄧芝字伯苗，義陽新野人，漢司徒禹之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-8', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '陰化不盡；和合二國，唯有鄧芝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-9', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」權大笑，嘉其抗直，甚愛待之，見敬亞於鄧芝、費禕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-10', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時車騎將軍鄧芝自江州還，來朝，謂預曰：「禮，六十不服戎，而卿甫受兵，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-045-11', 'p0177', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-047-12', 'p0177', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，蜀使中郎將鄧芝來聘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0177-a04-047-13', 'p0177', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」　吳錄曰：是歲蜀主又遣鄧芝來聘，重結盟好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-035-0', 'p0178', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-1', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '宗預字德豔，南陽安衆人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-2', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '官位與張翼齊，而在宗預之右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0178-a04-045-3', 'p0178', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-044-0', 'p0179', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '東曹掾楊戲素性簡略，琬與言論，時不應荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-045-1', 'p0179', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '楊戲字文然，犍為武陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0179-a04-045-2', 'p0179', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '楊戲商略，意在不羣，然智度有短，殆罹世難云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a03-083-0', 'p0180', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '」字之曰德曜，名孟光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a03-084-1', 'p0180', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '君若欲慕鮑宣、梁鴻之高者，妾亦請從少君、孟光之事矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-032-2', 'p0180', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣等謹與博士許慈、議郎孟光建立禮儀，擇令辰，上尊號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-3', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '先主定蜀，承喪亂歷紀，學業衰廢，乃鳩合典籍，沙汰衆學，慈、潛並為博士，與孟光、來敏等典掌舊文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-4', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '孟光字孝裕，河南洛陽人，漢太尉孟郁之族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0180-a04-042-5', 'p0180', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '時孟光亦以樞機不慎，議論干時，然猶愈於敏，俱以其耆宿學士見禮於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-0', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '先主定蜀，承喪亂歷紀，學業衰廢，乃鳩合典籍，沙汰衆學，慈、潛並為博士，與孟光、來敏等典掌舊文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-1', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '好公羊春秋而譏呵左氏，每與來敏爭此二義，光常譊譊讙咋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-2', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '來敏字敬達，義陽新野人，來歙之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-3', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '亮集有教曰：「將軍來敏對上官顯言『新人有何功德而奪我榮資與之邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-042-4', 'p0181', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '昔成都初定，議者以為來敏亂羣，先帝以新定之際，故遂含容，無所禮用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-044-5', 'p0181', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '光祿大夫來敏至禕許別，求共圍棊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0181-a04-064-6', 'p0181', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '昔魏人伐蜀，蜀人禦之，精嚴垂發，六軍雲擾，士馬擐甲，羽檄交馳，費禕時為元帥，荷國任重，而與來敏圍碁，意無厭倦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-032-0', 'p0182', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-1', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '尹默字思潛，梓潼涪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-2', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '父仁，字德賢，與同縣尹默俱游荊州，從司馬徽、宋忠等學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0182-a04-042-3', 'p0182', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '許、孟、來、李，愽涉多聞，尹默精於左氏，雖不以德業為稱，信皆一時之學士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0183-a04-050-0', 'p0183', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '奮弟祺，吳書曰：祺與張溫、顧譚友善，權令關平辭訟事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0185-a03-072-0', 'p0185', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遂引兵攻傕，矢及帝前，獻帝紀曰：「汜與傕將張苞、張龍謀誅傕，汜將兵夜攻傕門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0185-a04-026-1', 'p0185', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '縣人張苞為郡督郵，貪穢受取，干亂吏政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0187-a04-040-0', 'p0187', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '儀遣馬岱追斬之，致首於儀，儀起自踏之，曰：「庸奴！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0187-a05-001-1', 'p0187', 'jinshu', 'a05-001', '《晉書·卷一》', '蜀將馬岱入寇，帝遣將軍牛金擊走之，斬千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-004-0', 'p0188', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '興移書日南州郡，開示大計，兵臨合浦，告以禍福；遣都尉唐譜等詣進乘縣，因南中都督護軍霍弋上表自陳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-041-1', 'p0188', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '漢晉春秋曰：霍弋聞魏軍來，弋欲赴成都，後主以備敵旣定，不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-042-2', 'p0188', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時羅憲以重兵據白帝，霍弋以彊卒鎮夜郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-048-3', 'p0188', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '漢晉春秋曰：初霍弋遣楊稷、毛炅等戍，與之誓曰：「若賊圍城，未百日而降者，家屬誅；若過百日而城沒者，刺史受其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a04-048-4', 'p0188', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳人並諫，璜曰：「霍弋已死，無能來者，可須其糧盡，然後乃受，使彼來無罪，而我取有義，內訓吾民，外懷鄰國，不亦可乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0188-a05-015-5', 'p0188', 'jinshu', 'a05-015', '《晉書·卷十五》', '晉平蜀，以蜀建寧太守霍弋遙領交州，得以便宜選用長吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-041-0', 'p0189', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '弋與巴東領軍襄陽羅憲各保全一方，舉以內附，咸因仍前任，寵待有加。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-041-1', 'p0189', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '襄陽記曰：羅憲字令則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-042-2', 'p0189', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時羅憲以重兵據白帝，霍弋以彊卒鎮夜郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-048-3', 'p0189', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二月，鎮軍陸抗、撫軍步恊、征西將軍留平、建平太守盛曼，率衆圍蜀巴東守將羅憲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0189-a04-048-4', 'p0189', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏使將軍胡烈步騎二萬侵西陵，以救羅憲，陸抗等引軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-008-full-0', 'p0190', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '寇桂陽，長沙太守孫堅擊斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-008-1', 'p0190', 'houhanshu', 'a03-008', '《後漢書·卷八》', '寇桂陽，長沙太守孫堅擊斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-2', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '孫堅殺荊州刺史王叡，王氏譜曰：「叡字通曜，晉太保祥伯父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-3', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-4', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-009-5', 'p0190', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-048-6', 'p0190', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '孫堅從桂陽入雒討董卓，軍於城南，見井中有五色光，軍人莫敢汲，堅乃浚得璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-7', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '溫參軍事孫堅說慎曰：堅字文臺，吳郡富春人，即孫權之父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-8', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時長沙太守孫堅亦率豫州諸郡兵討卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-9', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年，孫堅收合散卒，進屯梁縣之陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-10', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '唯孫堅小戇，說文曰：「戇，愚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-072-11', 'p0190', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時孫堅為溫參軍，勸溫陳兵斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-073-12', 'p0190', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '術遣越隨其將孫堅，擊袁紹將周昕，越為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-073-13', 'p0190', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '又長沙太守孫堅，前領豫州刺史，遂能驅走董卓，埽除陵廟，忠勤王室，其功莫大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-14', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '會長沙太守孫堅殺南陽太守張咨，英雄記曰：「咨字子議，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-15', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」吳曆曰：「孫堅至南陽，咨不給軍糧，又不肯見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-16', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '初平三年，術遣孫堅擊劉表於襄陽，堅戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-17', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '又聞孫堅得傳國璽，韋昭吳書曰：「漢室大亂，天子北詣河上，六璽不自隨，掌璽者以投井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-18', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫堅北討董卓，頓軍城南，甄官署有井，每旦有五色氣從井中出，使人浚井，得漢傳國玉璽，其文曰『受命于天，旣壽永昌』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-075-19', 'p0190', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '自孫堅死，子策復領其部曲，術遣擊楊州刺史劉繇，破之，策因據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a03-120-20', 'p0190', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '孫堅北討董卓，頓軍城南，官署有井，每旦有五色氣從井出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-001-21', 'p0190', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-006-22', 'p0190', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會長沙太守孫堅殺南陽太守張咨，術得據其郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-006-23', 'p0190', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁術之在南陽也，與孫堅合從，欲襲奪表州，使堅攻表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-008-24', 'p0190', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '是時，術遣孫堅屯陽城拒卓，紹使周昂奪其處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-008-25', 'p0190', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '又長沙太守孫堅，前領豫州刺史，驅走董卓，掃除陵廟，其功莫大；紹令周昂盜居其位，斷絕堅糧，令不得入，使卓不被誅，紹罪十也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-022-26', 'p0190', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '太守孫堅舉階孝廉，除尚書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-028-27', 'p0190', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：黃初末，吳人發長沙王吳芮冢，以其塼於臨湘為孫堅立廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-031-28', 'p0190', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '臣松之案：靈帝崩後，義軍起，孫堅殺荊州刺史王叡，然後劉表為荊州，不與焉同時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-039-29', 'p0190', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時孫堅舉兵討董卓，以南陽太守張咨不給軍糧，殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-039-30', 'p0190', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之案：劉焉在漢靈帝時已經宗正太常，出為益州牧，祥始以孫堅作長沙時為江夏太守，不得舉焉為孝廉，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-31', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫堅字文臺，吳郡富春人，蓋孫武之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-32', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '惟孫堅小戇，頗能用人，當語諸將，使知忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-33', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時又上章言狀，而孫堅隨周慎行，謂慎求將萬兵造金城，使慎以二萬作後駐，邊、韓城中無宿穀，當於外運，畏慎大兵，不敢輕與堅戰，而堅兵足以斷其運道，兒曹用必還羌谷中，涼州或能定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-34', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」卓曰：「然，但殺二袁、劉表、孫堅，天下自服從孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-35', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣松之以為孫堅於興義之中最有忠烈之稱，若得漢神器而潛匿不言，此為陰懷異志，豈所謂忠臣者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-36', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　臣松之案：本傳云孫堅以初平三年卒，策以建安五年卒，策死時年二十六，計堅之亡，策應十八，而此表云十七，則為不符。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-046-37', 'p0190', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '評曰：孫堅勇摯剛毅，孤微發迹，導溫戮卓，山陵杜塞，有忠壯之烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-050-38', 'p0190', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫堅聞其才貌，欲娶之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-051-39', 'p0190', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '且孫堅以初平二年卒，洞口之役在黃初三年，堅卒至此合三十一年，匡時若尚在，本傳不得云卒時年二十餘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-054-40', 'p0190', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，孫堅興義兵討董卓，徙家於舒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-055-41', 'p0190', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從孫堅征伐，討黃巾於宛、鄧，破董卓於陽人，攻城野戰，身被創夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-055-42', 'p0190', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '以便弓馬，有膂力，幸於孫堅，從征伐周旋，數犯危難，陷敵擒虜，為別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-056-43', 'p0190', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '初為縣吏，後察孝廉，州辟從事，隨孫堅征伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-061-44', 'p0190', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '父祉，字宣嗣，從孫堅征伐有功，堅薦祉為九江太守，後轉吳郡，所在有聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0190-a04-064-45', 'p0190', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻字子遠，孫堅弟靜之曾孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-0', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-1', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '繇軍敗績，孫策遂據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-2', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '吳志曰：「孫策旣破繇，遂度兵據會稽，策自領會稽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-009-3', 'p0191', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，孫策死，為許貢客所射傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-031-4', 'p0191', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '術大怒，遣其將孫策攻康，圍城數重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-045-5', 'p0191', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '後孫策破會稽，忠等浮海南投交阯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-068-6', 'p0191', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '及孫策平吳，劭與繇南奔豫章而卒，時年四十六。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-070-7', 'p0191', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '後為孫策廬江太守李術所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-075-8', 'p0191', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魏志曰「勳字子臺，琅邪人，與太祖有舊，為孫策破後，自歸太祖，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-075-9', 'p0191', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫策破勳，復見收視，術女入孫權宮，子曜仕吳為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-076-10', 'p0191', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '袁術遣孫策攻破繇，因奔豫章，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a03-112-11', 'p0191', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '」　新淦　宜春　廬陵興平元年，孫策分立廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-001-12', 'p0191', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是歲，孫策受袁術使渡江，數年閒遂有江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-001-13', 'p0191', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫策聞公與紹相持，乃謀襲許，未發，為刺客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-006-14', 'p0191', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '妻子依術故吏廬江太守劉勳，孫策破勳，復見收視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-007-15', 'p0191', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '孫策遣軍攻登於匡琦城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-010-16', 'p0191', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '建安五年，為孫策廬江太守李術所殺，時年三十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-012-17', 'p0191', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '避難江東，孫策禮命之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-012-18', 'p0191', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '後為廬江太守，為孫策所破，自歸太祖，封列侯，遂從在散伍議中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-19', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫策略地江東，歆知策善用兵，乃幅巾奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-20', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '胡冲吳歷曰：孫策擊豫章，先遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-21', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '華嶠譜叙曰：孫策略有揚州，盛兵徇豫章，一郡大恐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-22', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '虞溥江表傳曰：孫策在椒丘，遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-23', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '獻帝春秋曰：孫策率軍如閩、越討朗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-24', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」　漢晉春秋曰：孫策之始得朗也，譴讓之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-013-25', 'p0191', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖問曰：「孫策何以得至此邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-26', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策轉鬬千里，盡有江東，聞太祖與袁紹相持於官渡，將渡江北襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-27', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '又本傳稱嘉料孫策輕佻，必死於匹夫之手，誠為明於見事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-014-28', 'p0191', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '孫策惡之，遣使卑辭厚幣，以書說勳曰：「上繚宗民，數欺下國，忿之有年矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-015-29', 'p0191', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後孫策所置廬江太守李述攻殺揚州刺史嚴象，廬江梅乾、雷緒、陳蘭等聚衆數萬在江、淮間，郡縣殘破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-022-30', 'p0191', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東及東城，辭孫策、袁術之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-022-31', 'p0191', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '避亂江東，又辭孫策之命，還本郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-035-32', 'p0191', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-038-33', 'p0191', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孫策東渡江，皆走交州以避其難，靖身坐岸邊，先載附從，踈親悉發，乃從後去，當時見者莫不歎息。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-038-34', 'p0191', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '許靖羇客會稽，閭閻之士，孫策之來，於靖何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-046-35', 'p0191', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初，吳郡太守許貢上表於漢帝曰：「孫策驍雄，與項籍相似，宜加貴寵，召還京邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-046-36', 'p0191', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫策雖威行江外，略有六郡，然黃祖乘其上流，陳登間其心腹，且深險彊宗未盡歸復，曹、袁虎爭，勢傾山海，策豈暇遠師汝、潁，而遷帝於吳、越哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-047-37', 'p0191', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '傅子曰：孫策為人明果獨斷，勇蓋天下，以父堅戰死，少而合其兵將以報讎，轉鬬千里，盡有江南之地，誅其名豪，威行鄰國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-049-38', 'p0191', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '漢命加繇為牧，振武將軍，衆數萬人，孫策東渡，破英、能等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-049-39', 'p0191', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '楊州刺史劉繇與慈同郡，慈自遼東還，未與相見，暫渡江到曲阿見繇，未去，會孫策至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-40', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-41', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '堅薨，隨孫策討樊能、于麋等於橫江，擊張英於當利口，而船少，欲駐軍更求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-050-42', 'p0191', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '漢末，其母攜將徙廬江，廬江為孫策所破，皆東渡江，以美麗得幸於權，寵冠後庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-43', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫輔字國儀，賁弟也，以揚武校尉佐孫策平三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-44', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫策愛之，賜姓為孫，列之屬籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-051-45', 'p0191', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫策平定吳、會，誅其英豪，憲素有高名，策深忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-46', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫策創業，命昭為長史、撫軍中郎將，升堂拜母，如比肩之舊，文武之事，一以委昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-47', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫策蒞事日淺，恩澤未洽，一旦傾隕，士民狼狽，頗有同異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-48', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '典略曰：余曩聞劉荊州甞自作書欲與孫伯符，以示禰正平，正平蚩之，言：「如是為欲使孫策帳下兒讀之邪，將使張子布見乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-052-49', 'p0191', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-053-50', 'p0191', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，紘同郡秦松字文表，陳端字子正，並與紘見待於孫策，參與謀謨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-053-51', 'p0191', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-52', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣松之案：孫策于時始得豫章、廬陵，尚未能得定江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-53', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時孫策已薨，權尚住吳，瑜謂肅曰：「昔馬援荅光武云『當今之世，非但君擇臣，臣亦擇君』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-054-54', 'p0191', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '當為孫策將，數討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-55', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '堅薨，復隨孫策在淮南，從攻廬江，拔之，還俱東渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-56', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '及孫策東渡，從討三郡，遷先登校尉，授兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-57', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策之襲袁術，欽隨從給事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-58', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與蔣欽隨孫策為左右，服事恭敬，數戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-59', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策在壽春，武往脩謁，時年十八，長七尺七寸，因從渡江，征討有功，拜別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-60', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫策入郡，襲迎於高遷亭，策見而偉之，到署門下賊曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-055-61', 'p0191', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '父操，輕俠有膽氣，孫策初興，每從征伐，常冠軍履鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-056-62', 'p0191', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後避亂壽春，孫策見而異之，範遂自委昵，將私客百人歸策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-63', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策征會稽，翻時遭父喪，衰絰詣府門，朗欲就之，翻乃脫衰入見，勸朗避策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-64', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '翻未至豫章，聞孫策向會稽，翻乃還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-65', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '而傳云孫策之來，翻衰絰詣府門，勸朗避策，則為大異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-66', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '江表傳曰：策書謂翻曰：「今日之事，當與卿共之，勿謂孫策作郡吏相待也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-67', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '然王公拒戰，華逆請服，實由孫策初起，名微衆寡，故王能舉兵，豈武勝哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-68', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」因述孫策才略殊異，用兵之奇，歆乃荅云當去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-057-69', 'p0191', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-058-70', 'p0191', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '當禦備時，諸將軍或是孫策時舊將，或公室貴戚，各自矜恃，不相聽從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-058-71', 'p0191', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '抗字幼節，孫策外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-060-72', 'p0191', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安元年，孫策臨郡，察齊孝廉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-060-73', 'p0191', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫策到吳，柔舉兵先附，策表柔為丹楊都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-061-74', 'p0191', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '玄兄良，字文鸞，隨孫策平定江東，策以為會稽東部都尉，卒，玄領良兵，拜奮武中郎將，以功封溧陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a04-062-75', 'p0191', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫策領會稽太守，綜年十四，為門下循行，留吳與孫權共讀書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a05-015-76', 'p0191', 'jinshu', 'a05-015', '《晉書·卷十五》', '獻帝興平中，孫策分豫章立廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0191-a05-037-77', 'p0191', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '自孫策至權，奕世相繼，惟強與弱，不在一禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-0', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操以舟師伐孫權，權將周瑜敗之於烏林、赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-1', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十一月，孫權取荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-009-2', 'p0192', 'houhanshu', 'a03-009', '《後漢書·卷九》', '明年，劉備稱帝于蜀，孫權亦自王於吳，於是天下遂三分矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-3', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及與孫權使語，謗訕朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-4', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會南征孫權，表請彧勞軍于譙，因表留彧曰：「臣聞古之遣將，上設監督之重，下建副二之任，史記，齊景公以田穰苴為將軍，扞燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-070-5', 'p0192', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '吳錄曰：「孫權聞操來，夾水立塢，狀如偃月，以相拒，月餘乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-072-6', 'p0192', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '溫參軍事孫堅說慎曰：堅字文臺，吳郡富春人，即孫權之父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-075-7', 'p0192', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫權破關羽，取荊州，以璋為益州牧，留住秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-075-8', 'p0192', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫策破勳，復見收視，術女入孫權宮，子曜仕吳為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-9', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十三年，孫權分新都郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-10', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十六年，孫權改曰建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-112-11', 'p0192', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '建安十五年，孫權分立鄱陽郡，治縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-113-12', 'p0192', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」　高涼建安二十五年，孫權立高梁郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a03-118-13', 'p0192', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '」獻帝春秋曰：「孫權以步隲行交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-14', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十二月，孫權為備攻合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-15', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，孫權圍合肥，張遼、李典擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-16', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遂征孫權，十一月至譙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-17', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫權遣使上書，以討關羽自效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-18', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏略曰：孫權上書稱臣，稱說天命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-001-19', 'p0192', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '殿下應期，十分天下而有其九，以服事漢，羣生注望，遐邇怨歎，是故孫權在遠稱臣，此天人之應，異氣齊聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-20', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋八月，孫權遣使奉章，并遣于禁等還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-21', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」魏書曰：癸亥，孫權上書，說：「劉備支黨四萬人，馬二三千匹，出秭歸，請往埽撲，以克捷為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-22', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '五月，以荊、揚、江表八郡為荊州，孫權領牧故也；荊州江北諸郡為郢州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-23', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '閏月，孫權破劉備於夷陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-24', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書載丙午詔曰：「孫權殘害民物，朕以寇不可長，故分命猛將三道並征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-25', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '論征孫權功，諸將已下進爵增戶各有差。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-26', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」三年之中，以孫權不服，復班太宗論於天下，明示不願征伐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-002-27', 'p0192', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '胡沖吳歷曰：帝以素書所著典論及詩賦餉孫權，又以紙寫一通與張昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-28', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '八月，孫權攻江夏郡，太守文聘堅守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-29', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，公孫淵斬送孫權所遣使張彌、許晏首，以淵為大司馬樂浪公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-30', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權入居巢湖口，向合肥新城，又遣將陸議、孫韶各將萬餘人入淮、沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-31', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '秋七月，高句驪王宮斬送孫權使胡衞等首，詣幽州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-003-32', 'p0192', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-33', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫權自十數年以來，大畋江北，繕治甲兵，精其守禦，數出盜竊，敢遠其水，陸次平土，此中國所願聞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-34', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：初，孫權築東興隄以遏巢湖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-35', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往者季漢分崩，九土顛覆，劉備、孫權乘間作禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-004-36', 'p0192', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '紹本偽南陵督，才質開壯；彧，孫權支屬，忠良見事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-006-37', 'p0192', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '術女入孫權宮，子燿拜郎中，燿女又配於權子奮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-38', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '淵遣使南通孫權，往來賂遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-39', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '故公文下遼東，因赦之曰：「告遼東、玄菟將校吏民：逆賊孫權遭遇亂階，因其先人劫略州郡，遂成羣凶，自擅江表，含垢藏疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-008-40', 'p0192', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '孫權慕義，不遠萬里，連年遣使，欲自結援，雖見絕殺，不念舊怨，纖纖往來，求成恩好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-41', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '二十一年，從征孫權還，使惇都督二十六軍，留居巢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-42', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征孫權還，使淵督諸將擊廬江叛者雷緒，緒破，又行征西護軍，督徐晃擊太原賊，攻下二十餘屯，斬賊帥商曜，屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-43', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權遣將陳邵據襄陽，詔仁討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-44', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權遣將屯歷陽，休到，擊破之，又別遣兵渡江，燒賊蕪湖營數千家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-45', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-46', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '與夏侯尚等征孫權，擊牛渚屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-009-47', 'p0192', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '孫權雖稱藩，尚益脩攻討之備，權後果有貳心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-48', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會征孫權，表請彧勞軍于譙，因輒留彧，以侍中光祿大夫持節，參丞相軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-49', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧卒於壽春，壽春亡者告孫權，言太祖使彧殺伏后，彧不從，故自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-50', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '荊人服劉主之雄姿，憚孫權之武略，為日旣乆，誠非曹氏諸將所能抗禦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-51', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '昔魏文帝用賈詡為三公，孫權笑之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-010-52', 'p0192', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-012-53', 'p0192', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」十三年，融對孫權使，有訕謗之言，坐棄市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-012-54', 'p0192', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖征孫權，徙為留府長史，謂奕曰：「君之忠亮，古人不過也，然微太嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-55', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：孫權稱臣，斬送關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-56', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '』顧念孫權，了更侮媚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-57', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '至於荀公之清談，孫權之侮媚，執書嗢噱，不能離手。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-58', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫權欲不遣，歆謂權曰：「將軍奉王命，始交好曹公，分義未固，使僕得為將軍效心，豈不有益乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-59', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太祖征孫權，表歆為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-60', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」太祖以孫權稱臣遣貢諮朗，朗荅曰：「孫權前牋，自詭躬討虜以補前愆，後疏稱臣，以明無二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-61', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '初，建安末，孫權始遣使稱藩，而與劉備交兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-62', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孫權欲遣子登入侍，不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-013-63', 'p0192', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '後孫權襲取其將士家屬，羽士衆一旦瓦解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-64', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '論者以為孫權必殺備，昱料之曰：「孫權新在位，未為海內所憚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-65', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及關羽圍曹仁於樊，孫權遣使辭以「遣兵西上，欲掩取羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-66', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：孫權遣使求降，帝以問曄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-67', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '建安十三年，孫權率衆圍合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-68', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-69', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」漢晉春秋曰：公孫淵聞魏將來討，復稱臣於孫權，乞兵自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-70', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '帝問濟：「孫權其救遼東乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-71', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '青龍初，孫權與諸葛亮連和，欲俱出為寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-014-72', 'p0192', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：是時，孫權、諸葛亮號稱劇賊，無歲不有軍征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-73', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '孫權率十萬衆攻圍合肥城百餘日，時天連雨，城欲崩，於是以苫蓑覆之，夜然脂照城外，視賊所作而為備，賊以破走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-74', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安二十四年，孫權攻合肥，是時諸州皆屯戍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-75', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '時孫權在東關，當豫州南，去江四百餘里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-015-76', 'p0192', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會病篤，謂左右曰：「受國厚恩，恨不斬孫權以下見先帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-77', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖旣征孫權還，使遼與樂進、李典等將七千餘人屯合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-78', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '俄而權率十萬衆圍合肥，乃共發教，教曰：「若孫權至者，張、李將軍出戰；樂將軍守，護軍勿得與戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-79', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安二十一年，太祖復征孫權，到合肥，循行遼戰處，歎息者良乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-80', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '孫權復叛，遣遼還屯合肥，進遼爵都鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-81', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '孫權復叛，帝遣遼乘舟，與曹休至海陵，臨江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-82', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」會孫權禽羽，獲其衆，禁復在吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-017-83', 'p0192', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '明帝即位，遣南屯荊州，與司馬宣王擊孫權別將劉阿等，追至祁口，交戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-84', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與張遼、樂進屯合肥，孫權率衆圍之，遼欲奉教出戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-85', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討孫權，先登，再入巢湖，攻居巢，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-86', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '霸從討孫權於濡須口，與張遼為前鋒，行遇霖雨，大軍先及，水遂長，賊舩稍進，將士皆不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-87', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '而孫觀亦至青州刺史，假節，從太祖討孫權，戰被創，薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-88', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從征孫權於濡須口，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-89', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '孫權以五萬衆自圍聘於石陽，甚急，聘堅守不動，權住二十餘日乃解去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-018-90', 'p0192', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '魏略曰：孫權嘗自將數萬衆卒至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-019-91', 'p0192', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '太祖征孫權，使植留守鄴，戒之曰：「吾昔為頓丘令，年二十三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-020-92', 'p0192', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '時孫權曾致巨象，太祖欲知其斤重，訪之羣下，咸莫能出其理。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-93', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '雄略冠時，智謀出世，摧袁氏於官渡，驅孫權於江外，逐劉備於隴右，破烏丸於白登，其餘梟夷蕩定者，往往如神，不可勝計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-94', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '臣松之案：孫權自此以前，尚與中國和同，未嘗交兵，何云「驅權於江外」乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-95', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今以海內之兵，百勝之威，而孫權負險於吳，劉備不賔於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-96', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-97', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破關羽并荊州之後，志盈欲滿，凶宄以極，是以宣文侯深建宏圖大舉之策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-98', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '彪曰：嘉平四年四月，孫權死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-99', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破蜀兼平荊州之後，志盈欲滿，罪戮忠良，殊及胤嗣，元凶已極。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-021-100', 'p0192', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏議以為「淮海非賊輕行之路，又昔孫權遣兵入海，漂浪沈溺，略無孑遺，恪豈敢傾根竭本，寄命洪流，以徼乾沒乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-101', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '帝征孫權，至廣陵，使羣領中領軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-102', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '郡為孫權所圍於匡奇，登令矯求救於太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-022-103', 'p0192', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '征軍大將軍曹休表得降賊辭，「孫權已在濡須口」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-023-104', 'p0192', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '羽軍旣退，舟船猶據沔水，襄陽隔絕不通，而孫權襲取羽輜重，羽聞之，即走南還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-023-105', 'p0192', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '孫權寇邊，征東大將軍曹休統五州軍禦之，徵儼為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-025-106', 'p0192', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝方脩殿舍，百姓勞役，毗上疏曰：「竊聞諸葛亮講武治兵，而孫權巿馬遼東，量其意指，似欲相左右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-107', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '孫權數擾東陲，復召寵還為汝南太守，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-108', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '三年春，降人稱吳大嚴，揚聲欲詣江北獵，孫權欲自出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-109', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '其冬，孫權揚聲欲至合肥，寵表召兖、豫諸軍，皆集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-026-110', 'p0192', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後孫權號十萬衆攻新城，征東將軍滿寵欲率諸軍救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-111', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '世語曰：黃初中，孫權通章表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-112', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '二年，昶奏：「孫權流放良臣，適庶分爭，可乘釁而制吳、蜀；白帝、夷陵之間，黔、巫、秭歸、房陵皆在江北，民夷與新城郡接，可襲取也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-027-113', 'p0192', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-114', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '文帝踐阼，拜散騎常侍，出為兖州刺史，與張遼等至廣陵討孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-115', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾言景王曰：「孫權已沒，大臣未附，吳名宗大族，皆有部曲，阻兵仗勢，足以建命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-028-116', 'p0192', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-031-117', 'p0192', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '孫權殺關羽，取荊州，以璋為益州牧，駐秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-118', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-119', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備大喜，進住鄂縣，即遣諸葛亮隨肅詣孫權，結同盟誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-120', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-121', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備未破魏軍之前，尚未與孫權相見，不得有此說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-122', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：孫權欲與備共取蜀，遣使報備曰：「米賊張魯居王巴、漢，為曹操耳目，規圖益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-123', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '明年，曹公征孫權，權呼先主自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-124', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二十年，孫權以先主已得益州，使使報欲得荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-125', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '俄而孫權襲殺羽，取荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-126', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '初，先主忿孫權之襲關羽，將東征，秋七月，遂帥諸軍伐吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-127', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-032-128', 'p0192', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權聞先主住白帝，甚懼，遣使請和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-129', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '遣尚書郎鄧芝固好於吳，吳王孫權與蜀和親使聘，是歲通好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-130', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '吳王孫權同恤灾患，潛軍合謀，掎角其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-033-131', 'p0192', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，孫權稱帝，與蜀約盟，共交分天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-132', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '孫權據有江東，已歷三世，國險而民附，賢能為之用，此可與為援而不可圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-133', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '將軍旣帝室之胄，信義著於四海，總攬英雄，思賢如渴，若跨有荊、益，保其巖阻，西和諸戎，南撫夷越，外結好孫權，內脩政理；天下有變，則命一上將將荊州之軍以向宛、洛，將軍身率益州之衆出於秦川，百姓孰敢不簞食壺漿以迎將軍者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-134', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：張子布薦亮於孫權，亮不肯留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-135', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮聞孫權破曹休，魏兵東下，關中虛弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-136', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」漢晉春秋曰：是歲，孫權稱尊號，其羣臣以並尊二帝來告。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-137', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛氏集目錄                     　　開府作牧第一　　　權制第二                     　　南征第三　　　　　北出第四                   　　計筭第五　　　　　訓厲第六                   　　綜覈上第七　　　　綜覈下第八                   　　雜言上第九　　　　雜言下第十                   　　貴和第十一　　　　兵要第十二                   　　傳運第十三　　　　與孫權書第十四                   　　與諸葛瑾書第十五　與孟達書第十六                   　　廢李平第十七　　　法檢上第十八                   　　法檢下第十九　　　科令上第二十                   　　科令下第二十一　　軍令上第二十二                   　　軍令中第二十三　　軍令下第二十四                   　右二十四篇，凡十萬四千一百一十二字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-138', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮時年二十七，乃建奇策，身使孫權，求援吳會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-139', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '初，亮未有子，求喬為嗣，瑾啟孫權遣喬來西，亮以喬為己適子，故易其字焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-035-140', 'p0192', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '延熈十四年，以校尉使吳，值孫權病篤，不自見建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-141', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '孫權遣兵佐先主拒曹公，曹公引軍退歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-142', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-143', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臣松之桉吳書：孫權遣將潘璋逆斷羽走路，羽至即斬，且臨沮去江陵二三百里，豈容不時殺羽，方議其生死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-144', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臨發，其帳下將張達、范彊殺飛，持其首，順流而奔孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-145', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '孫權襲荊州，先主大怒，欲討權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-036-146', 'p0192', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '雲諫曰：「國賊是曹操，非孫權也，且先滅魏，則吳自服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-147', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-148', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」初，孫權以妹妻先主，妹才捷剛猛，有諸兄之風，侍婢百餘人，皆親執刀侍立，先主每入，衷心常凜凜；亮又知先主雅愛信正，故言如此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-037-149', 'p0192', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '先主旣即尊號，將東征孫權以復關羽之耻，羣臣多諫，一不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-038-150', 'p0192', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '芳為南郡太守，與關羽共事，而私好攜貳，叛迎孫權，羽因覆敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-038-151', 'p0192', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '遣東使於吳，孫權聞其才辯，欲逆折以辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-152', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-153', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，孫權稱尊號，以震為衞尉，賀權踐阼，諸葛亮與兄瑾書曰：「孝起忠純之性，老而益篤，及其贊述東西，歡樂和合，有可貴者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-154', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」震到武昌，孫權與震升壇歃盟，交分天下：以徐、豫、幽、青屬吳，并、涼、兾、兖屬蜀，其司州之土，以函谷關為界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-039-155', 'p0192', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '孫權甞大醉問禕曰：「楊儀、魏延，牧豎小人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-040-156', 'p0192', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕於獄中與諸葛亮書曰：「僕昔有事於諸侯，以為曹操暴虐，孫權無道，振威闇弱，其惟主公有霸王之器，可與興業致治，故乃翻然有輕舉之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-040-157', 'p0192', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-041-158', 'p0192', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先是，益州郡殺太守正昂，耆率雍闓恩信著於南土，使命周旋，遠通孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-044-159', 'p0192', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '孫權性旣滑稽，嘲啁無方，諸葛恪、羊衜等才愽果辯，論難鋒至，禕辭順義篤，據理以荅，終不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-044-160', 'p0192', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '禕別傳曰：孫權每別酌好酒以飲禕，視其已醉，然後問以國事，并論當世之務，辭難累至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-161', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先是，吳王孫權請和，先主累遣宋瑋、費禕等與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-162', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '孫權蓋謂丁厷之言多浮豔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-163', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '預將命使吳，孫權問預曰：「東之與西，譬猶一家，而聞西更增白帝之守，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-164', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '預復東聘吳，孫權捉預手，涕泣而別曰：「君每銜命結二國之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-165', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」遺預大珠一斛，吳歷曰：預臨別，謂孫權曰：「蜀土僻小，雖云鄰國，東西相賴，吳不可無蜀，蜀不可無吳，君臣憑恃，唯陛下重垂神慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-166', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '士仁字君義，廣陽人也，為將軍，住公安，統屬關羽；與羽有隙，叛迎孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-045-167', 'p0192', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '評曰：鄧芝堅貞簡亮，臨官忘家，張翼亢姜維之銳，宗預禦孫權之嚴，咸有可稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-046-168', 'p0192', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-169', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '公曰：「此必孫權欲身見吾軍部伍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-170', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」曹公語諸將曰：「孫權不欺孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-171', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '吳王孫權，幼豎小子，無尺寸之功，遭遇兵亂，因父兄之緒，少蒙翼卵煦伏之恩，長含鴟梟反逆之性，背棄天施，罪惡積大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-172', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '孫權時合暮舉火於西陵，鼓三竟，達吳郡南沙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-173', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '評曰：孫權屈身忍辱，任才尚計，有句踐之奇英，人之傑矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-047-174', 'p0192', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '臣松之以為孫權橫廢無罪之子，雖為兆亂，然國之傾覆，自由暴皓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-175', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '臣松之案：孫權赤烏十年，詔徙武昌宮材瓦，以繕治建康宮，而此猶有端門內殿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-176', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳歷曰：亮數出中書視孫權舊事，問左右侍臣：「先帝數有特制，今大將軍問事，但令我書可邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-048-177', 'p0192', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '江表傳曰：定，汝南人，本孫權給使也，後出補吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-178', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '姿容美好，孫權愛敬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-179', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '孫權統事，以慈能制磐，遂委南方之事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-180', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '建安十五年，孫權遣步隲為交州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-049-181', 'p0192', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '呂岱師友士匡，使通信誓，徽兄弟肉袒，推心委命，岱因滅之，以要功利，君子是以知孫權之不能遠略，而呂氏之祚不延者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-050-182', 'p0192', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫權甞游幸諸營，而姬觀於道中，權望見異之，命宦者召入，以賜子和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-050-183', 'p0192', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '遠觀齊桓，近察孫權，皆有識士之明，傑人之志，而嫡庶不分，閨庭錯亂，遺笑古今，殃流後嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-051-184', 'p0192', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '初，孫權殺吳郡太守盛憲，會稽典錄曰：憲字孝章，器量雅偉，舉孝廉，補尚書郎，稍遷吳郡太守，以疾去官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-185', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權領會稽太守，不之郡，以雍為丞，行太守事，討除寇賊，郡界寧靜，吏民歸服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-186', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權統事，聞徽有才辯，召署主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-187', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為車騎將軍，辟西曹掾，轉主簿，出補海昏令，甚有惠化，年三十二卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-188', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-189', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權潛包禍心，助魏除害，是為翦宗子勤王之師，行曹公移都之計，拯漢之規，於茲而止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-190', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」臣松之以為魏明帝一時明主，政自己出，孫權此論，竟為無徵，而史載之者，將以主幼國疑，威柄不一，亂亡之形，有如權言，宜其存錄以為鑒戒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-052-191', 'p0192', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-192', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '獻帝春秋云：劉備至京，謂孫權曰：「吳去此數百里，即有驚急，赴救為難，將軍無意屯京乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-193', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '張昭進之於孫權，權以為騎都尉、從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-194', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫權為驃騎將軍，辟補西曹掾；及稱尊號，以澤為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-195', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '臣松之計孫權年大文帝五歲，其為長幼也微耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-053-196', 'p0192', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '士燮旣附孫權，召綜為五官中郎，除合浦、交阯太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-197', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-198', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-199', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-054-200', 'p0192', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權之論，優劣允當，故載錄焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-201', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，與張昭等共輔孫權，遂周旋三郡，平討不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-202', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-203', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-204', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權統事，以為別部司馬，授兵五百人，守柴桑長，拒黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-205', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '干寶晉紀所云疑城，已注孫權傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-055-206', 'p0192', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫權為陽羨長，始往隨權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-056-207', 'p0192', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '按魏少帝紀及孫權傳，是歲並無事，當是陳壽誤以吳嘉禾六年為赤烏五年耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-056-208', 'p0192', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫權為將軍，桓給事幕府，除餘姚長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-209', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權深貴待之，未及擢用，會病卒，甚見痛惜，殊其門戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-210', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權統事，辟為奏曹掾，以直道見憚，出為鬱林太守，加偏將軍，給兵二千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-211', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '父允，以輕財重士，名顯州郡，為孫權東曹掾，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-212', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權以將軍領會稽太守，統年二十，試為烏程相，民戶過萬，咸歎其惠理。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-213', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權忿公孫淵之巧詐反覆，欲親征之，瑁上疏諫曰：「臣聞聖王之御遠夷，羈縻而已，不常保有，故古者制地，謂之荒服，言慌惚無常，不可保也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-057-214', 'p0192', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權為車騎將軍，召為主簿，出為山陰令，還為參軍校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-215', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫權為將軍，遜年二十一，始仕幕府，歷東西曹令史，出為海昌屯田都尉，并領縣事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-216', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '臣松之以為遜慮孫權已退，魏得專力於己，旣能張拓形勢，使敵不敢犯，方舟順流，無復怵惕矣，何為復潛遣諸將，奄襲小縣，致令市人駭奔，自相傷害？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-058-217', 'p0192', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫權以楊笁所白遜二十事問抗，禁絕賔客，中使臨詰，抗無所顧問，事事條荅，權意漸解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-059-218', 'p0192', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-219', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫權為車騎將軍，以柔為長史，徙桂陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-220', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '小子吳，孫權外孫，封都鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-221', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫權統事，岱詣幕府，出守吳丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-060-222', 'p0192', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '評曰：山越好為叛亂，難安易動，是以孫權不遑外禦，卑詞魏氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-061-223', 'p0192', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫權殺關羽，并荊土，拜濬輔軍中郎將，授以兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-224', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫權承攝大業，優文徵儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-225', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '孫策領會稽太守，綜年十四，為門下循行，留吳與孫權共讀書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-062-226', 'p0192', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-227', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '會孫權起於東南，範委身服事，每有災祥，輒推數言狀，其術多效，遂以顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-228', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '建安中，孫權在豫章，時有星變，以問惇，惇曰：「災在丹楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-063-229', 'p0192', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '初孫權行師征伐，每令達有所推步，皆如其言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-230', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪父瑾靣長似驢，孫權大會羣臣，使人牽一驢入，長檢其靣，題曰諸葛子瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-231', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫權為車騎將軍，拜耽右司馬，以寬厚稱，早卒，無嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-232', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫權末，徙武衞都尉，為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a04-064-233', 'p0192', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '興少有士名，孫權時除上虞令，稍遷至尚書左曹，以五官中郎將使蜀，還為會稽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-234', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '孫權、劉備，外親內踈，羽之得意，權所不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-235', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '會孫權帥兵西過，朝議以樊、襄陽無穀，不可以禦寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-236', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '帝曰：「孫權新破關羽，此其欲自結之時也，必不敢為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-237', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '及孫權圍江夏，遣其將諸葛瑾、張霸并攻襄陽，帝督諸軍討權，走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-001-238', 'p0192', 'jinshu', 'a05-001', '《晉書·卷一》', '初，文懿聞魏師之出也，請救於孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-002-239', 'p0192', 'jinshu', 'a05-002', '《晉書·卷二》', '」全懌母，孫權女也，得罪於吳，全端兄子禕及儀奉其母來奔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-006-240', 'p0192', 'jinshu', 'a05-006', '《晉書·卷六》', '及孫權之稱號，自謂當之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-012-241', 'p0192', 'jinshu', 'a05-012', '《晉書·卷十二》', '吳孫權赤烏十一年二月，白虹貫日，權發詔戒懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-242', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是時孫權受魏爵號，而稱兵距守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-243', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，孫權遣張彌等將兵萬人，錫授公孫文懿為燕王，文懿斬彌等，虜其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-244', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '是時，諸葛亮據渭南，宣帝與相持；孫權寇合肥，又遣陸議、孫昭等入淮沔，天子親東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-245', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '吳孫權赤烏十三年夏五月，日北至，熒惑逆行，入南斗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-246', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '翼又楚分野，孫權封略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-013-247', 'p0192', 'jinshu', 'a05-013', '《晉書·卷十三》', '孫權發兵，緣江淮屯要衝，權自圍新城以應亮，天子東征權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-014-248', 'p0192', 'jinshu', 'a05-014', '《晉書·卷十四》', '孫權赤烏五年，亦取中州嘉號封建諸王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-015-249', 'p0192', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫權分江夏立武昌郡，又分蒼梧立臨賀郡，分長沙立衡陽、湘東二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-015-250', 'p0192', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫權又分豫章立鄱陽郡，分丹楊立新都郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0192-a05-037-251', 'p0192', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時孫權稱藩，請送任子，當遣前將軍于禁還，久而不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-0', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮字子明，權少子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-1', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮廢，己未，孫綝使宗正孫楷與中書郎董朝迎休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-048-2', 'p0193', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '評曰：孫亮童孺而無賢輔，其替位不終，必然之勢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-3', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '得幸有娠，夢有似龍頭授己者，己以蔽膝受之，遂生孫亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-4', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮即位，以夫人姊壻譚紹為騎都尉，授兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-5', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮全夫人，全尚女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-050-6', 'p0193', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '太平中，孫亮知朱主為全主所害，問朱主死意？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-055-7', 'p0193', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫亮即位，為冠軍將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-057-8', 'p0193', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '會稽典錄曰：孫亮時，有山陰朱育，少好奇字，凡所特達，依體象類，造作異字千名以上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-057-9', 'p0193', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫亮時，二子熊、損各復領兵，為全公主所譖，皆死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-059-10', 'p0193', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '基侍孫亮在內，太平二年，盜乘御馬，收付獄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-060-11', 'p0193', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '孫亮即位，遷鎮北將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-060-12', 'p0193', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '臣松之案：孫亮太平二年始立臨川郡，是時未有臨川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-064-13', 'p0193', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝以孫亮始親政事，多所難問，甚懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a04-065-14', 'p0193', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫亮即位，諸葛恪輔政，表曜為太史令，撰吳書，華覈、薛瑩等皆與參同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-013-15', 'p0193', 'jinshu', 'a05-013', '《晉書·卷十三》', '吳廢孫亮太平元年九月壬辰，太白犯南斗，吳志所書也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-013-16', 'p0193', 'jinshu', 'a05-013', '《晉書·卷十三》', '是歲，吳主孫亮五鳳元年也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-015-17', 'p0193', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫亮又分豫章立臨川郡，分會稽立臨海郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0193-a05-034-18', 'p0193', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祕孫亮，字長玄，有才能，多計數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-004-0', 'p0194', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫休遣使鄧句，勑交阯太守鎖送其民，發以為兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-004-1', 'p0194', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '又孫休病死，主帥改易，國內乖違，人各有心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-028-2', 'p0194', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '今宜厚劉禪以致孫休，安士民以來遠人，若便送禪於京都，吴以為流徙，則於向化之心不勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-041-3', 'p0194', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '孫休怒，復遣陸抗等帥衆三萬人增憲之圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-4', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休字子烈，權第六子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-5', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '時孫休在郡治，衡數以法繩之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-6', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休即位，特徵偉，累遷至光祿勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-7', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休立，封皓為烏程侯，遣就國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-8', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫休時，父亮為尚書令，而陟為中書令，每朝會，詔以屏風隔其座。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-048-9', 'p0194', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '襄陽記曰：悌字巨先，襄陽人，少有名理，孫休時為屯騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-10', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳主權王夫人，南陽人也，以選入宮，嘉禾中得幸，生孫休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-11', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休朱夫人，朱據女，休姊公主所生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-050-12', 'p0194', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休即位，大赦，得還，以牧為五官中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-052-13', 'p0194', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」周昭者字恭遠，與韋曜、薛瑩、華覈並述吳書，後為中書郎，坐事下獄，覈表救之，孫休不聽，遂伏法云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-053-14', 'p0194', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '漢晉春秋曰：孫休時，珝為五官中郎將，遣至蜀求馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-053-15', 'p0194', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」珝弟瑩，字道言，初為祕府中書郎，孫休即位，為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-055-16', 'p0194', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-057-17', 'p0194', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」歷顯位，孫休時固為左御史大夫，孫皓即位，遷司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-058-18', 'p0194', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫休時，追謚遜曰昭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-059-19', 'p0194', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫休立，封和子皓為烏程侯，自新都之本國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-059-20', 'p0194', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫休即位，封德錢唐侯，謙永安侯，俊拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-061-21', 'p0194', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫休即位，拜征北將軍，假節領豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-061-22', 'p0194', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '或曰寶鼎元年十二月，凱與大司馬丁奉、御史大夫丁固謀，因皓謁廟，欲廢皓立孫休子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-064-23', 'p0194', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫休曰：「盛夏出軍，士卒傷損，無尺寸之功，不可謂能；受託孤之任，死於豎子之手，不可謂智。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-24', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，與賀邵、薛瑩、虞汜俱為散騎中常侍，皆加駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-25', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，從中郎為散騎中常侍，出為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a04-065-26', 'p0194', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休踐阼，為中書郎、博士祭酒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a05-015-27', 'p0194', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫休分武陵立天門郡，分宜都立建平郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0194-a05-015-28', 'p0194', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫休又分會稽立建安郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a03-013-0', 'p0195', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '干寶晉記曰：「吳王孫皓將其子瑾等，泥首面縛降王濬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-004-1', 'p0195', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '孫皓諸所獻致，其皆還送，歸之于王，以恊古義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-2', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：案漢獻帝起居注云「天子從河上還，得六璽於閣上」，又太康之初孫皓送金璽六枚，無有玉，明其偽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-3', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '如其果然，以傳子孫，縱非六璽之數，要非常人所畜，孫皓之降，亦不得但送六璽，而寶藏傳國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-046-4', 'p0195', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫皓時，訛言謂奉當立，誅死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-5', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '己丑，封孫皓為烏程侯，皓弟德錢唐侯，謙永安侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-6', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫皓字元宗，權孫，和子也，一名彭祖，字皓宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-7', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫皓使送稷下都，稷至合浦，歐血死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-8', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」炅猶罵不止，曰：「尚欲斬汝孫皓，汝父何死狗也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-9', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '四月甲申，詔曰：「孫皓窮迫歸降，前詔待之以不死，今皓垂至，意猶愍之，其賜號為歸命侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-048-10', 'p0195', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：王濬治船於蜀，吳彥取其流柹以呈孫皓，曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-050-11', 'p0195', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫皓即位月餘，貶為景皇后，稱安定宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-050-12', 'p0195', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫皓滕夫人，故太常胤之族女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-052-13', 'p0195', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '條孫皓時位至尚書令、太子少傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-052-14', 'p0195', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫皓使陸抗西行，祜等遁退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-15', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫皓時為侍郎，以言語辯捷見知，擢為侍中、中書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-16', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孫皓初，為左執法，遷選曹尚書，及立太子，又領少傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-053-17', 'p0195', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '干寶晉紀曰：武帝從容問瑩曰：「孫皓之所以亡者何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-055-18', 'p0195', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '休薨，奉與丞相濮陽興等從萬彧之言，共迎立孫皓，遷右大司馬左軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-19', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」歷顯位，孫休時固為左御史大夫，孫皓即位，遷司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-20', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '子喜亦涉文籍，好人倫，孫皓時為選曹尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-057-21', 'p0195', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫皓時，宣至驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-22', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫皓即位，加鎮軍大將軍，領益州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-23', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '孫皓聞二境交和，以詰於抗，抗曰：「夫一邑一鄉，不可以無信義之人，而況大國乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-058-24', 'p0195', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '景妻，孫皓適妹，與景俱張承外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-25', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓移都，甚憚之，詔曰：「慎勳德俱茂，朕所敬憑，宜登上公，以副衆望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-26', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓即位，詔曰：「故僕射屈晃，志匡社稷，忠諫亡身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-27', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫皓即位，追和、霸舊隙，削基、壹爵土，與祖母謝姬俱徙會稽烏傷縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-28', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '建衡二年，孫皓左夫人王氏卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-059-29', 'p0195', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之案：建衡二年至奮之死，孫皓即位，尚猶未乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-061-30', 'p0195', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫皓立，遷鎮西大將軍，都督巴丘，領荊州牧，進封嘉興侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-061-31', 'p0195', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫皓與晉平，使者丁忠自北還，說皓弋陽可襲，凱諫止，語在皓傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-064-32', 'p0195', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '左典軍萬彧素與烏程侯孫皓善，乃勸興、布，於是興、布廢休適子而迎立皓，皓旣踐阼，加興侍中，領青州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-33', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓初，復入為常侍，與萬彧同官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-34', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，與王蕃、郭逴、萬彧俱為散騎中常侍，出為會稽太守，入為大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-35', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓時，入為左典軍，遷中書令，領太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-36', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，封高陵亭侯，遷中書僕射，職省，為侍中，常領左國史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a04-065-37', 'p0195', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，封徐陵亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-002-38', 'p0195', 'jinshu', 'a05-002', '《晉書·卷二》', '冬十月丁亥，奏遣吳人相國參軍徐劭、散騎常侍水曹屬孫彧使吳，喻孫皓以平蜀之事，致馬錦等物，以示威懷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-002-39', 'p0195', 'jinshu', 'a05-002', '《晉書·卷二》', '夏四月，孫皓使紀陟來聘，且獻方物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-40', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '三月，孫皓帥衆趨壽陽，遣大司馬望屯淮北以距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-41', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '孫皓窮蹙請降，送璽綬於琅邪王伷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-42', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '三月壬寅，王濬以舟師至于建鄴之石頭，孫皓大懼，面縳輿櫬，降于軍門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-43', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '五月辛亥，封孫皓為歸命侯，拜其太子為中郎，諸子為郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-003-44', 'p0195', 'jinshu', 'a05-003', '《晉書·卷三》', '詔選孫皓妓妾五千人入宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-006-45', 'p0195', 'jinshu', 'a05-006', '《晉書·卷六》', '故歸命侯孫皓子璠謀反，伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-012-46', 'p0195', 'jinshu', 'a05-012', '《晉書·卷十二》', '」是時孫皓淫暴，四月降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-013-47', 'p0195', 'jinshu', 'a05-013', '《晉書·卷十三》', '太康元年三月，大破吳軍，孫皓面縛請罪，吳國遂亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-48', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫皓分零陵立始安郡，分桂陽立始興郡，又分零陵立邵陵郡，分長沙立安成郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-49', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '孫皓分會稽立東陽郡，分吳立吳興郡，分豫章、廬陵、長沙立安成郡，分廬江立廬陵南部都尉，揚州統丹楊、吳、會稽、吳興、新都、東陽、臨海、建安、豫章、鄱陽、臨川、安成、廬陵南部十四郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-015-50', 'p0195', 'jinshu', 'a05-015', '《晉書·卷十五》', '及孫皓，又立新昌、武平、九德三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-51', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」孫皓聞二境交和，以詰抗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-52', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '今江淮之難，不過劍閣；山川之險，不過岷漢；孫皓之暴，侈於劉禪；吳人之困，甚於巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-53', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '孫皓恣情任意，與下多忌，名臣重將不復自信，是以孫秀之徒皆畏逼而至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-54', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '如舍之，若孫皓不幸而沒，吳人更立令主，雖百萬之眾，長江未可而越也，將爲後患乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-55', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '政，吳之名將也，據要害之地，恥以無備取敗，不以所喪之實告于孫皓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-56', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '若今中止，孫皓怖而生計，或徙都武昌，更完修江南諸城，遠其居人，城不可攻，野無所掠，積大船於夏口，則明年之計或無所及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-034-57', 'p0195', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '孫皓既平，振旅凱入，以功進爵當陽縣侯，增邑并前九千六百戶，封子耽爲亭侯，千戶，賜絹八千匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-037-58', 'p0195', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孫皓率眾向壽春，詔望統中軍二萬，騎三千，據淮北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-039-59', 'p0195', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時將發使聘吳，並遣當時文士作書與孫皓，帝用勖所作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-040-60', 'p0195', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '使及至轘轅，而孫皓已降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-61', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '孫皓司徒何植、建威將軍孫晏送印節詣渾降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-62', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '既而王濬破石頭，降孫皓，威名益振。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-63', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '帝下詔曰：「使持節、都督揚州諸軍事、安東將軍、京陵侯王渾，督率所統，遂逼秣陵，令賊孫皓救死自衛，不得分兵上赴，以成西軍之功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-64', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '帝嘗與濟奕棋，而孫皓在側，謂皓曰：「何以好剝人面皮？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-65', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '吳建平太守吾彥取流柿以呈孫皓曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-66', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '時朝議咸諫伐吳，濬乃上疏曰：「臣數參訪吳楚同異，孫皓荒淫凶逆，荊揚賢愚無不嗟怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-67', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '用光祿勳薛瑩、中書令胡沖計，送降文於濬曰：「吳郡孫皓叩頭死罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0195-a05-042-68', 'p0195', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '彬知賊寇已殄，孫皓將降，未至建鄴二百里，稱疾遲留，以示不競。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-001-0', 'p0196', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '銅馬、青犢、尤來餘賊共立孫登為天子於上郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-001-1', 'p0196', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '春秋保乾圖曰：「賊臣起，名孫登，巧用法，多技方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-048-2', 'p0196', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '懿怪而問之，酺曰：「圖書有漢賊孫登，將以才智為中官所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a03-048-3', 'p0196', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '春秋保乾圖曰「漢賊臣，名孫登，大形小口，長七尺九寸，巧用法，多技方，詩書不用，賢人杜口」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-008-4', 'p0196', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」魏書曰：度語毅、儀：「讖書云孫登當為天子，太守姓公孫，字升濟，升即登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-5', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '初，康採藥於汲郡共北山中，見隱者孫登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-6', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '康別傳云：孫登謂康曰：「君性烈而才儁，其能免乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-021-7', 'p0196', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又晉陽秋云：康見孫登，登對之長嘯，踰時不言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-059-8', 'p0196', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '孫登字子高，權長子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a04-059-9', 'p0196', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '評曰：孫登居心所存，足為茂美之德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0196-a05-040-10', 'p0196', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '初，駿徵高士孫登，遺以布被。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-048-0', 'p0197', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '劫皓庶弟永安侯謙出烏程，取孫和陵上鼓吹曲蓋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-1', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '夫人以選入宮，黃武中得幸，生孫和，寵次步氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-2', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及潘夫人母子有寵，全主自以與孫和母有隙，乃勸權為潘氏男亮納夫人，亮遂為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-3', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '初，孫和為太子時，全主譖害王夫人，欲廢太子，立魯王，朱主不聽，由是有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-050-4', 'p0197', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫和何姬，丹楊句容人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0197-a04-059-5', 'p0197', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '吳歷曰：孫和以無罪見殺，衆庶皆懷憤歎，前司馬桓慮因此招合將吏，欲共殺峻立英，事覺，皆見殺，英實不知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a03-070-0', 'p0198', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融逼急，乃遣東萊太史慈求救於平原相劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-011-1', 'p0198', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」原匿之月餘，時東萊太史慈當歸，原因以政付之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-047-2', 'p0198', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-049-3', 'p0198', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '太史慈字子義，東萊黃人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-049-4', 'p0198', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '太史慈信義篤烈，有古人之分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-051-5', 'p0198', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及軍還，郎與太史慈俱在前導軍，人以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-055-6', 'p0198', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '樂安平定，代太史慈備海昏，與周瑜為左右督，破曹公於烏林，又進攻南郡，走曹仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0198-a04-056-7', 'p0198', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又從攻祖郎於陵陽，太史慈於勇里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-009-0', 'p0199', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，楊州刺史劉繇與袁術將孫策戰于曲阿，策字伯符，孫堅子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-037-1', 'p0199', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '初平中，天下亂，避地會稽，遂浮海客交阯，東觀記曰「礹到吳郡，揚州刺史劉繇振給穀食衣服所乏者，悉不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-068-2', 'p0199', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」遂復投揚州刺史劉繇於曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-073-3', 'p0199', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '後為楊州刺史劉繇所破，走入山中，為人所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-075-4', 'p0199', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '自孫堅死，子策復領其部曲，術遣擊楊州刺史劉繇，破之，策因據江東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a03-075-5', 'p0199', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操毒被於東徐，劉表僭亂於南荊，公孫叛逆於朔北，正禮阻兵，劉繇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-001-6', 'p0199', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」兖州刺史劉岱、岱，劉繇之兄，事見吳志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-007-7', 'p0199', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-013-8', 'p0199', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：揚州刺史劉繇死，其衆願奉歆為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-035-9', 'p0199', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '皓從揚州刺史劉繇求兵擊玄，玄退屯西城，皓入南昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-035-10', 'p0199', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉繇、王朗各據州郡，論安言計，動引聖人，羣疑滿腹，衆難塞胷，今歲不戰，明年不征，使孫策坐大，遂并江東，此臣之未解二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-11', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先是，劉繇為揚州刺史，州舊治壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-12', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」術知其恨，而以劉繇據曲阿，王朗在會稽，謂策未必能定，故許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-13', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉繇棄軍遁逃，諸郡守皆捐城郭奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-14', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉繇旣走，策入曲阿勞賜將士，遣將陳寶詣阜陵迎母及弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-15', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '發恩布令，告諸縣：「其劉繇、笮融等故鄉部曲來降首者，一無所問；樂從軍者，一身行，復除門戶；不樂者，勿彊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-046-16', 'p0199', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-17', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '劉繇字正禮，東萊牟平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-18', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '繇奔丹徒，袁宏漢紀曰：劉繇將奔會稽，許子將曰：「會稽富實，策之所貪，且窮在海隅，不可往也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-19', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '楊州刺史劉繇與慈同郡，慈自遼東還，未與相見，暫渡江到曲阿見繇，未去，會孫策至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-20', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '後劉繇亡於豫章，士衆萬餘人未有所附，策命慈往撫安焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-21', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '今劉繇喪亡，恨不及其生時與共論辯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-049-22', 'p0199', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '評曰：劉繇藻厲名行，好尚臧否，至於擾攘之時，據萬里之土，非其長也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-23', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-24', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '從討劉繇，繇奔豫章，策遣景、賁到壽春報術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-050-25', 'p0199', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '」琨具啟策，策即行之，衆悉俱濟，遂破英，擊走笮融、劉繇，事業克定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-26', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策破劉繇，定諸縣，進攻會稽，遣人請靜，靜將家屬與策會于錢唐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-27', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '為揚州刺史劉繇所迫逐，因將士衆還住歷陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-051-28', 'p0199', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及策東渡，助賁、景破英、能等，遂進擊劉繇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-054-29', 'p0199', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乃渡擊秣陵，破笮融、薛禮，轉下湖孰、江乘，進入曲阿，劉繇奔走，而策之衆已數萬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-30', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時吳景已在丹楊，而策為術攻廬江，於是劉繇恐為袁、孫所并，遂搆嫌隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-31', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策旣走劉繇，東定會稽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-056-32', 'p0199', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策定秣陵、曲阿，收笮融、劉繇餘衆，增範兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a04-064-33', 'p0199', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '伯父耽，父胄，與劉繇州里通家，以世擾亂，渡江依繇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a05-036-full-34', 'p0199', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '太保主簿劉繇等冒難收瓘而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0199-a05-036-35', 'p0199', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '太保主簿劉繇等冒難收瓘而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-002-0', 'p0200', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '胡沖吳歷曰：帝以素書所著典論及詩賦餉孫權，又以紙寫一通與張昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-008-1', 'p0200', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：謙死時，年六十三，張昭等為之哀辭曰：「猗歟使君，君侯將軍，膺秉懿德，允武允文，體足剛直，守以溫仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-013-2', 'p0200', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '使張昭私問朗，朗誓不屈，策忿而不敢害也，留置曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-038-3', 'p0200', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孰若安時處順，端拱吳、越，與張昭、張紘之儔同保元吉者哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-039-4', 'p0200', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：輔吳將軍張昭甞對孫權論巴褊阨，不當拒張飛太甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-5', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '彭城張昭、廣陵張紘、秦松、陳端等為謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-6', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣松之以為張昭雖名重，然不如紘之文也，此書必紘所作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-046-7', 'p0200', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '創甚，請張昭等謂曰：「中國方亂，夫以吳、越之衆，三江之固，足以觀成敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-8', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '策長史張昭謂權曰：「孝廉，此寧哭時邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-9', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張昭、周瑜等謂權可與共成大業，故委心而服事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-10', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-11', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權自率衆圍合肥，使張昭攻九江之當塗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-047-12', 'p0200', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '父札，才學博達，權為驃騎將軍，以札為從事中郎，與張昭、孫邵共定朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-048-13', 'p0200', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '誅叛柔服而江外厎定，飭法脩師而威德翕赫，賔禮名賢而張昭為之雄，交御豪俊而周瑜為之傑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-048-14', 'p0200', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-050-15', 'p0200', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '建安七年，臨薨，引見張昭等，屬以後事，合葬高陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-051-16', 'p0200', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '行人以告，權乃還，偽若不知，與張昭共見輔，權謂輔曰：「兄厭樂邪，何為呼他人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-051-17', 'p0200', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策臨卒，張昭等謂策當以兵屬儼，而策呼權，佩以印綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-18', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '張昭字子布，彭城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-19', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '臣松之以為張昭勸迎曹公，所存豈不遠乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-20', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '習鑿齒曰：張昭於是乎不臣矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-21', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權嘗咨問得失，張昭因陳聽采聞，頗以法令太稠，刑罰微重，宜有所蠲損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-052-22', 'p0200', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '評曰：張昭受遺輔佐，功勳克舉，忠謇方直，動不為己；而以嚴見憚，以高見外，旣不處宰相，又不登師保，從容閭巷，養老而已，以此明權之不及策也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-23', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '表為正議校尉，吳書曰：紘與張昭並與參謀，常令一人居守，一人從征討，後呂布襲取徐州，因為之牧，不欲令紘與策從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-24', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '每有異事密計及章表書記，與四方交結，常令紘與張昭草創撰作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-25', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '江表傳曰：初，權於羣臣多呼其字，惟呼張昭曰張公，紘曰東部，所以重二人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-26', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '張昭進之於孫權，權以為騎都尉、從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-053-27', 'p0200', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-28', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜將兵赴喪，遂留吳，以中護軍與長史張昭共掌衆事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-29', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權召羣臣會議，張昭、秦松等猶豫不能決，權意不欲遣質，乃獨將瑜詣母前定議，瑜曰：「昔楚國初封於荊山之側，不滿百里之地，繼嗣賢能，廣土開境，立基於郢，遂據荊揚，至於南海，傳業延祚，九百餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-30', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-31', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」張昭非肅謙下不足，頗訾毀之，云肅年少麤踈，未可用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-054-32', 'p0200', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '數歲，鄧當死，張昭薦蒙代當，拜別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-33', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，與張昭等共輔孫權，遂周旋三郡，平討不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-34', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策薨，權年少，初統事，太妃憂之，引見張昭及襲等，問江東可保安不，襲對曰：「江東地勢有山川之固，而討逆明府恩德在民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-35', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '討虜承基，大小用命，張昭秉衆事，襲等為爪牙，此地利人和之時也，萬無所憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-36', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '張昭時在坐，難曰：「吳下業業，若軍果行，恐必致亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-055-37', 'p0200', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權出都亭候貞，貞有驕色，張昭旣怒，而盛忿憤，顧謂同列曰：「盛等不能奮身出命，為國家并許洛，吞巴蜀，而令吾君與貞盟，不亦辱乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-056-38', 'p0200', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後策薨，治與張昭等共尊奉權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-056-39', 'p0200', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '後權復征江夏，範與張昭留守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-40', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權與張昭論及神仙，翻指昭曰：「彼皆死人，而語神仙，世豈有仙人也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-41', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-057-42', 'p0200', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '罷出，張昭執其手曰：「老夫託意，君宜明之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-059-43', 'p0200', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權欲登讀漢書，習知近代之事，以張昭有師法，重煩勞之，乃令休從昭受讀，還以授登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-062-44', 'p0200', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '遼東之事，輔吳將軍張昭以諫權言辭切至，權亦大怒，其和協彼此，使之無隙，綜有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-064-45', 'p0200', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '命恪行酒，至張昭前，昭先有酒色，不肯飲，曰：「此非養老之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0200-a04-064-46', 'p0200', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」張昭自以坐中最老，疑恪以鳥戲之，因曰：「恪欺陛下，未甞聞鳥名白頭翁者，試使恪復求白頭母。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-038-0', 'p0201', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '孰若安時處順，端拱吳、越，與張昭、張紘之儔同保元吉者哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-1', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳歷曰：初策在江都時，張紘有母喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-2', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '彭城張昭、廣陵張紘、秦松、陳端等為謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-046-3', 'p0201', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳錄載策使張紘為書曰：「蓋上天垂司過之星，聖王建敢諫之鼓，設非謬之備，急箴闕之言，何哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-053-4', 'p0201', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '評曰：張紘文理意正，為世令器，孫策待之亞於張昭，誠有以也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-5', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」會稽東部都尉張紘又與融書曰：「虞仲翔前頗為論者所侵，美寶為質，彫摩益光，不足以損。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-6', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫策在吳，張昭、張紘、秦松為上賔，共論四海未泰，須當用武治而平之，績年少末坐，遙大聲言曰：「昔管夷吾相齊桓公，九合諸侯，一匡天下，不用兵車。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0201-a04-057-7', 'p0201', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陳國陳融、陳留濮陽逸、沛郡蔣纂、廣陵袁迪等，皆單貧有志，就瑁游處，迪孫曄，字思光，作獻帝春秋，云迪與張紘等俱過江，迪父綏為太傅掾，張超之討董卓，以綏領廣陵事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-047-0', 'p0202', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」六月，以太常顧雍為丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-047-1', 'p0202', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，丞相顧雍卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-048-2', 'p0202', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-3', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '顧雍字元歎，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-4', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-5', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-052-6', 'p0202', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '顧雍依杖素業，而將之智局，故能究極榮位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-057-7', 'p0202', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」太常顧雍曰：「基未詳其為人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-058-8', 'p0202', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '赤烏七年，代顧雍為丞相，詔曰：「朕以不德，應期踐運，王塗未一，姦宄充路，夙夜戰懼，不惶鑒寐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0202-a04-061-9', 'p0202', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '時校事呂壹操弄威柄，奏桉丞相顧雍、左將軍朱據等，皆見禁止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a03-023-0', 'p0203', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '乃庸力之不暇，思鳴之無晨，吳志諸葛瑾曰「失旦之雞，復思一鳴」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-003-1', 'p0203', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '吳將諸葛瑾、張霸等寇襄陽，撫軍大將軍司馬宣王討破之，斬霸，征東大將軍曹休又破其別將於尋陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-004-2', 'p0203', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-009-3', 'p0203', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '權將諸葛瑾與尚軍對江，瑾渡入江中渚，而分水軍於江中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-017-4', 'p0203', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '明帝即位，拒吳將諸葛瑾於襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-023-5', 'p0203', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時吳使朱然、諸葛瑾攻圍樊城，遣船兵於峴山東斫材，牂牁人兵作食，有先熟者呼後熟者，言：「共食來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-035-6', 'p0203', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛氏集目錄                     　　開府作牧第一　　　權制第二                     　　南征第三　　　　　北出第四                   　　計筭第五　　　　　訓厲第六                   　　綜覈上第七　　　　綜覈下第八                   　　雜言上第九　　　　雜言下第十                   　　貴和第十一　　　　兵要第十二                   　　傳運第十三　　　　與孫權書第十四                   　　與諸葛瑾書第十五　與孟達書第十六                   　　廢李平第十七　　　法檢上第十八                   　　法檢下第十九　　　科令上第二十                   　　科令下第二十一　　軍令上第二十二                   　　軍令中第二十三　　軍令下第二十四                   　右二十四篇，凡十萬四千一百一十二字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-7', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '招延俊秀，聘求名士，魯肅、諸葛瑾等始為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-8', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以備已得益州，令諸葛瑾從求荊州諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-9', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權令諸葛瑾報，更尋盟好，遂分荊州長沙、江夏、桂陽以東屬權，南郡、零陵、武陵以西屬備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-10', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-11', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」於是令有司盡寫科條，使郎中褚逢齎以就遜及諸葛瑾，意所不安，令損益之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-12', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-13', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-14', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '車騎將軍朱然圍樊，大將軍諸葛瑾取柤中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-15', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-047-16', 'p0203', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-048-17', 'p0203', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-051-18', 'p0203', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '輕財能施，善於交結，與諸葛瑾至厚，委廬江劉靖以得失，江夏李允以衆事，廣陵吳碩、河南張梁以軍旅，而傾心親待，莫不自盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-19', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字仲嗣，少以才學知名，與諸葛瑾、步隲、嚴畯相友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-20', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '初，承喪妻，昭欲為索諸葛瑾女，承以相與有好，難之，權聞而勸焉，遂為婚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-21', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '臣松之案：承與諸葛瑾同以赤烏中卒，計承年小瑾四歲耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-22', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '諸葛瑾字子瑜，琅邪陽都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-23', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-24', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-052-25', 'p0203', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '諸葛瑾、步隲並以德度規檢見器當世，張承、顧邵虛心長者，好尚人物，周昭之論，稱之甚美，故辭錄焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-053-26', 'p0203', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '避亂江東，與諸葛瑾、步隲齊名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-054-27', 'p0203', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '赤烏二年，諸葛瑾、步隲連名上疏曰：「故將軍周瑜子胤，昔蒙粉飾，受封為將，不能養之以福，思立功效，至縱情欲，招速罪辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-055-28', 'p0203', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將夏侯尚等圍南郡，分前部三萬人作浮橋，渡百里洲上，諸葛瑾、楊粲並會兵赴救，未知所出，而魏兵日渡不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-056-29', 'p0203', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '諸葛瑾子融、步隲子恊，雖各襲任，權特復使然總為大督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-058-30', 'p0203', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '嘉禾五年，權北征，使遜與諸葛瑾攻襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-059-31', 'p0203', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a04-060-32', 'p0203', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a05-001-33', 'p0203', 'jinshu', 'a05-001', '《晉書·卷一》', '及孫權圍江夏，遣其將諸葛瑾、張霸并攻襄陽，帝督諸軍討權，走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0203-a05-001-34', 'p0203', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0204-a05-001-0', 'p0204', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-0', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權嘗問衞尉嚴畯：「寧念小時所闇書不」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-1', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭曰：「嚴畯鄙生，臣請為陛下誦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-2', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字仲嗣，少以才學知名，與諸葛瑾、步隲、嚴畯相友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-3', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫權為討虜將軍，召隲為主記，吳書曰：歲餘，隲以疾免，與琅邪諸葛瑾、彭城嚴畯俱游吳中，並著聲名，為當時英俊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-052-4', 'p0205', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '潁川周昭著書稱步隲及嚴畯等曰：「古今賢士大夫所以失名喪身傾家害國者，其由非一也，然要其大歸，總其常患，四者而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-053-5', 'p0205', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '嚴畯字曼才，彭城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-053-6', 'p0205', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '嚴畯薦崇行足以厲俗，學足以為師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-056-7', 'p0205', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '江表傳曰：初，權移都建業，大會將相文武，時謂嚴畯曰：「孤昔歎魯子敬比鄧禹，呂子衡方吳漢，閒卿諸人未平此論，今定云何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0205-a04-059-8', 'p0205', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0206-a04-053-0', 'p0206', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '程秉字德樞，汝南南頓人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-053-0', 'p0207', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '闞澤字德潤，會稽山陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-053-1', 'p0207', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '西使張奉於權前列尚書闞澤姓名以嘲澤，澤不能荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-057-2', 'p0207', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '固在襁褓中，闞澤見而異之，曰：「此兒後必致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-057-3', 'p0207', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其淵懿純德，則太子少傅山陰闞澤，學通行茂，作帝師儒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-4', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-5', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '少以母王有寵見愛，年十四，為置宮衞，使中書令闞澤教以書藝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-059-6', 'p0207', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '闞澤為太傅，薛綜為少傅，而蔡穎、張純、封俌、嚴維等皆從容侍從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a04-063-7', 'p0207', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '達寶惜其術，自闞澤、殷禮皆名儒善士，親屈節就學，達祕而不告。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0207-a05-017-8', 'p0207', 'jinshu', 'a05-017', '《晉書·卷十七》', '吳中書令闞澤受劉洪乾象法於東萊徐岳，又加解注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-007-0', 'p0208', 'houhanshu', 'a03-007', '《後漢書·卷七》', '飾芳林而考濯龍之宮，薛綜注東京賦云：「濯龍，殿名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-040-1', 'p0208', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '薛綜注西京賦曰：「颯纚，長袖貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-094-2', 'p0208', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '薛綜曰：「九賔謂王、侯、公、卿、二千石、六百石下及郎、吏、匈奴侍子，凡九等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-094-3', 'p0208', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」薛綜注二京賦曰：「為天神借民力於此田，故名曰帝藉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-095-4', 'p0208', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」薛綜曰：「侲之言善，善童幼子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-098-5', 'p0208', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」薛綜注曰：「八達謂室有八䆫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-098-6', 'p0208', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」薛綜注曰：「於上班敎曰明堂，大合樂射饗者辟雍，司曆記候節氣者曰靈臺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-7', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「樹翠羽為蓋，如雲龍矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-8', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「釳中央低，兩頭高，如山形，而貫中翟尾結著之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-9', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「戈，句孑戟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-10', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」薛綜曰：「耜，耒金也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-11', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '屬車八十一乘，薛綜曰：「屬之言相連屬也，皆在後，為三行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-12', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鳳皇闟戟，薛綜曰：「闟之言函也，取四戟函車邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-13', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '薛綜曰：「侍御史載之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-119-14', 'p0208', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '薛綜曰：「飛軨，以緹油廣八寸，長注地，畫左蒼龍右白虎，繫軸頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-120-15', 'p0208', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」薛綜曰：「以珩玉為充耳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a03-120-16', 'p0208', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」薛綜曰：「下輪大，上輪小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-047-17', 'p0208', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」尚書僕射薛綜等切諫乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-052-18', 'p0208', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '薛綜為選曹尚書，固讓譚曰：「譚心精體密，貫道達微，才照人物，德允衆望，誠非愚臣所可越先。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-053-19', 'p0208', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '薛綜字敬文，沛郡竹邑人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-053-20', 'p0208', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '薛綜學識規納，為吳良臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-059-21', 'p0208', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '闞澤為太傅，薛綜為少傅，而蔡穎、張純、封俌、嚴維等皆從容侍從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-061-22', 'p0208', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先帝外仗顧、陸、朱、張，內近胡綜、薛綜，是以庶績雍熈，邦內清肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0208-a04-064-23', 'p0208', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權嘉其功，遣尚書僕射薛綜勞軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a03-009-0', 'p0209', 'houhanshu', 'a03-009', '《後漢書·卷九》', '曹操以舟師伐孫權，權將周瑜敗之於烏林、赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-009-1', 'p0209', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從平荊州，以仁行征南將軍，留屯江陵，拒吳將周瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-017-2', 'p0209', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-018-3', 'p0209', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-032-4', 'p0209', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-032-5', 'p0209', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '江表傳曰：周瑜為南郡太守，分南岸地以給備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-035-6', 'p0209', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-037-7', 'p0209', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '吳將周瑜助先主取荊州，因領南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-037-8', 'p0209', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」備歎息曰：「孤時危急，當有所求，故不得不往，殆不免周瑜之手！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-9', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '堅初興義兵，策將母徙居舒，與周瑜相友，收合士大夫，江、淮間人咸向之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-10', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '有周瑜者，與策同年，亦英達夙成，聞策聲聞，自舒來造焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-11', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時策西討黃祖，行及石城，聞勳輕身詣海昏，便分遣從兄賁、輔率八千人於彭澤待勳，自與周瑜率二萬人步襲皖城，即克之，得術百工及鼓吹部曲三萬餘人，并術、勳妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-046-12', 'p0209', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-13', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張昭、周瑜等謂權可與共成大業，故委心而服事焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-14', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-047-15', 'p0209', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-16', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '誅叛柔服而江外厎定，飭法脩師而威德翕赫，賔禮名賢而張昭為之雄，交御豪俊而周瑜為之傑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-17', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-18', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '而周瑜驅我偏師，黜之赤壁，喪旗亂轍，僅而獲免，收迹遠遁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-048-19', 'p0209', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '執鞭鞠躬，以重陸公之威；悉委武衞，以濟周瑜之師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-050-20', 'p0209', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-21', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '十一年，與周瑜共討麻、保二屯，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-22', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '昔周瑜、程普為左右部督，共攻江陵，雖事決於瑜，普自恃乆將，且俱是督，遂共不睦，幾敗國事，此目前之戒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-051-23', 'p0209', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '周瑜到巴丘，輔遂得進據廬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-052-24', 'p0209', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '江表傳曰：權旣即尊位，請會百官，歸功周瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-052-25', 'p0209', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭忠謇亮直，有大臣節，權敬重之，然所以不相昭者，蓋以昔駮周瑜、魯肅等議為非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-053-26', 'p0209', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '黃武四年，權為太子登娉周瑜女，秉守太常，迎妃於吳，權親幸秉船，深見優禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-27', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜字公瑾，廬江舒人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-28', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '于時周瑜使鄱陽，肅勸權呼瑜，瑜使鄱陽還，但與肅闇同，故能共成大勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-29', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '東方將吏，無有愚智，皆知其不可，惟周瑜、魯肅偏懷淺戇，意未解耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-30', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後著令曰：「故將軍周瑜、程普，其有人客，皆不得問。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-31', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」後書與權曰：「赤壁之役，值有疾病，孤燒船自退，橫使周瑜虛獲此名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-32', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '赤烏二年，諸葛瑾、步隲連名上疏曰：「故將軍周瑜子胤，昔蒙粉飾，受封為將，不能養之以福，思立功效，至縱情欲，招速罪辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-33', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜為居巢長，將數百人故過候肅，并求資糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-34', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '肅家有兩囷米，各三千斛，肅乃指一囷與周瑜，瑜益知其奇也，遂相親結，定僑、札之分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-35', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權然之，乃遣周瑜助備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-36', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時周瑜受使至鄱陽，肅勸追召瑜還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-37', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜病困，上疏曰：「當今天下，方有事役，是瑜乃心夙夜所憂，願至尊先慮未然，然後康樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-38', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-39', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是歲，又與周瑜、程普等西破曹公於烏林，圍曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-40', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅代周瑜，當之陸口，過蒙屯下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-41', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後魯肅上代周瑜，過蒙言議，常欲受屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-42', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-054-43', 'p0209', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜、魯肅建獨斷之明，出衆人之表，實奇才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-44', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '樂安平定，代太史慈備海昏，與周瑜為左右督，破曹公於烏林，又進攻南郡，走曹仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-45', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜卒，代領南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-46', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安中，隨周瑜拒曹公於赤壁，建策火攻，語在瑜傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-47', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後以中郎將與周瑜等拒破曹公，又與呂蒙襲取南郡，遷偏將軍，領永昌太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-48', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後與周瑜、程普拒曹公於赤壁，攻曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-49', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-50', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨周瑜拒破曹公於烏林。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-055-51', 'p0209', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權以統為承烈都尉，與周瑜等拒破曹公於烏林，遂攻曹仁，遷為校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0209-a04-056-52', 'p0209', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹公至赤壁，與周瑜等俱拒破之，拜裨將軍，領彭澤太守，以彭澤、柴桑、歷陽為奉邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-0', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-1', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-032-2', 'p0210', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備欲呼魯肅等共會語，瑜曰：「受命不得妄委署，若欲見子敬，可別過之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-035-3', 'p0210', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-037-4', 'p0210', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '吳將魯肅遺先主書曰：「龐士元非百里才也，使處治中、別駕之任，始當展其驥足耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-5', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '招延俊秀，聘求名士，魯肅、諸葛瑾等始為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-6', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '荊州牧劉表死，魯肅乞奉命弔表二子，且以觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-7', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十五年，分豫章為鄱陽郡；分長沙為漢昌郡，以魯肅為太守，屯陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-8', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，乃遣呂蒙督鮮于丹、徐忠、孫規等兵二萬取長沙、零陵、桂陽三郡，使魯肅以萬人屯巴丘巴丘今曰巴陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-9', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-047-10', 'p0210', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-11', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-12', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '故魯肅一面而自託，士燮蒙險而效命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-048-13', 'p0210', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '高張公之德而省游田之娛，賢諸葛之言而割情欲之歡，感陸公之規而除刑政之煩，奇劉基之議而作三爵之誓，屏氣跼蹐以伺子明之疾，分滋損甘以育淩統之孤，登壇慷慨歸魯肅之功，削投惡言信子瑜之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-052-14', 'p0210', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昭忠謇亮直，有大臣節，權敬重之，然所以不相昭者，蓋以昔駮周瑜、魯肅等議為非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-052-15', 'p0210', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '值孫策卒，孫權姊壻曲阿弘咨見而異之，薦之於權，與魯肅等並見賔待，後為權長史，轉中司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-053-16', 'p0210', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '及橫江將軍魯肅卒，權以畯代肅，督兵萬人，鎮據陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-17', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」　臣松之以為建計拒曹公，實始魯肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-18', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-19', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '東方將吏，無有愚智，皆知其不可，惟周瑜、魯肅偏懷淺戇，意未解耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-20', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-21', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅字子敬，臨淮東城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-22', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」魏書及九州春秋曰：曹公征荊州，孫權大懼，魯肅實欲勸權拒曹公，乃激說權曰：「彼曹公者，實嚴敵也，新并袁紹，兵馬甚精，乘戰勝之威，伐喪亂之國，克可必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-23', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-24', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅智略足任，乞以代瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-25', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅忠烈，臨事不苟，可以代瑜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-26', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅代周瑜，當之陸口，過蒙屯下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-27', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後魯肅上代周瑜，過蒙言議，常欲受屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-28', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權時住陸口，使魯肅將萬人屯益陽拒羽，而飛書召蒙，使捨零陵，急還助肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-29', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '魯肅卒，蒙西屯陸口，肅軍人馬萬餘盡以屬蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-30', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-31', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-054-32', 'p0210', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '周瑜、魯肅建獨斷之明，出衆人之表，實奇才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-055-33', 'p0210', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨魯肅鎮益陽，拒關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-060-34', 'p0210', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '權遣橫江將軍魯肅攻攸，碭得突走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0210-a04-061-35', 'p0210', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '右國史華覈表薦禕曰：「禕體質方剛，器幹彊固，董率之才，魯肅不過。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-032-0', 'p0211', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」權忿之，乃遣呂蒙襲奪長沙、零陵、桂陽三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-036-1', 'p0211', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '按呂蒙傳云：「伏精兵於𦩷𦪇之中，使白衣搖櫓，作商賈服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-040-2', 'p0211', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」建安二十年，權遣呂蒙奄襲南三郡，立脫身走，自歸先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-045-3', 'p0211', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '為吳將呂蒙所譎，開城詣蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-4', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-5', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-6', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '時甘寧在夷陵，為仁黨所圍，用呂蒙計，留凌統以拒仁，以其半救寧，軍以勝反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-7', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，乃遣呂蒙督鮮于丹、徐忠、孫規等兵二萬取長沙、零陵、桂陽三郡，使魯肅以萬人屯巴丘巴丘今曰巴陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-8', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，權征羽，先遣呂蒙襲公安，獲將軍士仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-047-9', 'p0211', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」帝問其狀，咨曰：「納魯肅於凡品，是其聦也；拔呂蒙於行陣，是其明也；獲于禁而不害，是其仁也；取荊州而兵不血刃，是其智也；據三州虎視於天下，是其雄也；屈身於陛下，是其略也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-048-10', 'p0211', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-048-11', 'p0211', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '拔呂蒙於戎行，識潘濬於係虜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-051-12', 'p0211', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '近聞卿與甘興霸飲，因酒發作，侵陵其人，其人求屬呂蒙督中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-051-13', 'p0211', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '後呂蒙當襲南郡，權欲令皎與蒙為左右部大督，蒙說權曰：「若至尊以征虜能，宜用之；以蒙能，宜用蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-052-14', 'p0211', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後從討關羽，封宣城侯，以綏南將軍代呂蒙領南郡太守，住公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-15', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜用呂蒙計，留凌統以守其後，身與蒙上救寧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-16', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備旣定益州，權求長沙、零、桂，備不承旨，權遣呂蒙率衆進取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-17', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙字子明，汝南富陂人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-18', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權常歎曰：「人長而進益，如呂蒙、蔣欽，蓋不可及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-19', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」呂蒙曰：「兵有利鈍，戰無百勝，如有邂逅，敵步騎蹙人，不暇及水，其得入船乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-20', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '以蒙為南郡太守，封孱陵侯，江表傳曰：權於公安大會，呂蒙以疾辭，權笑曰：「禽羽之功，子明謀也，今大功已捷，慶賞未行，豈邑邑邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-054-21', 'p0211', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙勇而有謀斷，識軍計，譎郝普，禽關羽，最其妙者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-22', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後以中郎將與周瑜等拒破曹公，又與呂蒙襲取南郡，遷偏將軍，領永昌太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-23', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹公出濡須，欽與呂蒙持諸軍節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-24', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周瑜、呂蒙皆共薦達，孫權加異，同於舊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-25', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '遣使報瑜，瑜用呂蒙計，帥諸將解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-26', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安二十年，從攻合肥，會疫疾，軍旅皆已引出，唯車下虎士千餘人，并呂蒙、蔣欽、凌統及寧，從權逍遙津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-27', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甞於呂蒙舍會，酒酣，統乃以刀舞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-28', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧厨下兒曾有過，走投呂蒙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-29', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時呂蒙敗其水軍，而統先搏其城，於是大獲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-30', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與呂蒙等西取三郡，反自益陽，從往合肥，為右部督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-055-31', 'p0211', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-056-32', 'p0211', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '虎威將軍呂蒙病篤，權問曰：「卿如不起，誰可代者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-056-33', 'p0211', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '自創業功臣疾病，權意之所鍾，呂蒙、凌統最重，然其次矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-057-34', 'p0211', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '呂蒙圖取關羽，稱疾還建業，以翻兼知醫術，請以自隨，亦欲因此令翻得釋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-057-35', 'p0211', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權咨嗟將率，發憤歎息，追思呂蒙、張溫，以為據才兼文武，可以繼之，自是拜建義校尉，領兵屯湖孰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-058-36', 'p0211', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '呂蒙稱疾詣建業，遜往見之，謂曰：「關羽接境，如何遠下，後不當可憂也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-058-37', 'p0211', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權乃潛軍而上，使遜與呂蒙為前部，至即克公安、南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-060-38', 'p0211', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-062-39', 'p0211', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '呂蒙圖襲關羽，權以問儀，儀善其計，勸權聽之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a04-063-40', 'p0211', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權與呂蒙謀襲關羽，議之近臣，多曰不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0211-a05-001-41', 'p0211', 'jinshu', 'a05-001', '《晉書·卷一》', '權果遣將呂蒙西襲公安，拔之，羽遂為蒙所獲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-032-0', 'p0212', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '權遣周瑜、程普等水軍數萬與先主并力，江表傳曰：備從魯肅計，進住鄂縣之樊口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-035-1', 'p0212', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」權大恱，即遣周瑜、程普、魯肅等水軍三萬，隨亮詣先主，并力拒曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-046-2', 'p0212', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '程普請擊昭，策曰：「許昭有義於舊君，有誠於故友，此丈夫之志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-046-3', 'p0212', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-4', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-5', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-047-6', 'p0212', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-048-7', 'p0212', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-051-8', 'p0212', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '遷都護征虜將軍，代程普督夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-051-9', 'p0212', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '昔周瑜、程普為左右部督，共攻江陵，雖事決於瑜，普自恃乆將，且俱是督，遂共不睦，幾敗國事，此目前之戒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-052-10', 'p0212', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-11', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-12', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜與程普又進南郡，與仁相對，各隔大江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-13', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後著令曰：「故將軍周瑜、程普，其有人客，皆不得問。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-14', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '性度恢廓，大率為得人，惟與程普不睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-054-15', 'p0212', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是歲，又與周瑜、程普等西破曹公於烏林，圍曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-055-16', 'p0212', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '程普字德謀，右北平土垠人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0212-a04-055-17', 'p0212', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後與周瑜、程普拒曹公於赤壁，攻曹仁於南郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-046-0', 'p0213', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-048-1', 'p0213', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-049-2', 'p0213', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '策從騎十三，皆韓當、宋謙、黃蓋輩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-051-3', 'p0213', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '黃蓋及兄瑜卒，又并其軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-053-4', 'p0213', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '及臣所見，南海黃蓋為日南太守，下車以供設不豐，檛殺主簿，仍見驅逐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-054-5', 'p0213', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜部將黃蓋曰：「今寇衆我寡，難與持乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0213-a04-055-6', 'p0213', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '黃蓋字公覆，零陵泉陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-018-0', 'p0214', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '張遼之討陳蘭，霸別遣至皖，討吳將韓當，使權不得救蘭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-1', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-2', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」荅云：「是韓當兵，在此射鹿耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-046-3', 'p0214', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又江表傳說策悉識韓當軍士，疑此為詐，便射殺一人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-047-4', 'p0214', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-047-5', 'p0214', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '閏月，韓當子綜以其衆降魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-048-6', 'p0214', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-049-7', 'p0214', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '策從騎十三，皆韓當、宋謙、黃蓋輩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-055-8', 'p0214', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蓋自彊以一聲呼韓當，當聞之，曰：「此公覆聲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-055-9', 'p0214', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '韓當字義公，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0214-a04-058-10', 'p0214', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-048-0', 'p0215', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-1', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '江表傳曰：初，權謂蒙及蔣欽曰：「卿今並當塗掌事，宜學問以自開益。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-2', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權常歎曰：「人長而進益，如呂蒙、蔣欽，蓋不可及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-054-3', 'p0215', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-4', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蔣欽字公弈，九江壽春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-5', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '與蔣欽隨孫策為左右，服事恭敬，數戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-6', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '鄱陽賊彭虎等衆數萬人，襲與凌統、步隲、蔣欽各別分討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-055-7', 'p0215', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '建安二十年，從攻合肥，會疫疾，軍旅皆已引出，唯車下虎士千餘人，并呂蒙、蔣欽、凌統及寧，從權逍遙津北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0215-a04-060-8', 'p0215', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '會稽東冶五縣賊呂合、秦狼等為亂，權以岱為督軍校尉，與將軍蔣欽等將兵討之，遂禽合、狼，五縣平定，拜昭信中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-047-0', 'p0216', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-047-1', 'p0216', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '近得守將周泰、全琮等白事，過月六日，有馬步七百，徑到橫江，又督將馬和復將四百人進到居巢，琮等聞有兵馬渡江，視之，為兵馬所擊，臨時交鋒，大相殺傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-048-2', 'p0216', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-055-3', 'p0216', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '周泰字幼平，九江下蔡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0216-a04-055-4', 'p0216', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-001-0', 'p0217', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖上書陳武等正直而見陷害，姦邪盈朝，善人壅塞，其言甚切；靈帝不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-039-1', 'p0217', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳武與表俱至偏將軍，以位不相過故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-048-2', 'p0217', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-3', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '陳武字子烈，廬江松滋人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-4', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫盛曰：觀孫權之養士也，傾心竭思，以求其死力，泣周泰之夷，殉陳武之妾，請呂蒙之命，育凌統之孤，卑曲苦志，如此之勤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0217-a04-055-5', 'p0217', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-047-0', 'p0218', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-048-1', 'p0218', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0218-a04-055-2', 'p0218', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '董襲字元代，會稽餘姚人，長八尺，武力過人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-031-0', 'p0219', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '荊州別駕劉闔，璋將沈彌、婁發、甘寧反，擊璋不勝，走入荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-037-1', 'p0219', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '今荊州道通，衆數十倍，加孫車騎遣弟及李異、甘寧等為其後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-047-2', 'p0219', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '時甘寧在夷陵，為仁黨所圍，用呂蒙計，留凌統以拒仁，以其半救寧，軍以勝反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-047-3', 'p0219', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '兵皆就路，權與凌統、甘寧等在津北為魏將張遼所襲，統等以死扞權，權乘駿馬越津橋得去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-048-4', 'p0219', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-051-5', 'p0219', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '嘗以小故與甘寧忿爭，或以諫寧，寧曰：「臣子一例，征虜雖公子，何可專行侮人邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-6', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-7', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '瑜使甘寧前據夷陵，曹仁分衆攻寧，寧困急，使使請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-8', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '蒙乃薦甘寧為升城督，督攻在前，蒙以精銳繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-054-9', 'p0219', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '甘寧麤暴好殺，旣常失蒙意，又時違權令，權怒之，蒙輒陳請：「天下未定，鬬將如寧難得，宜容忍之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-10', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甘寧字興霸，巴郡臨江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-11', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧引白削置膝上，呵謂之曰：「卿見知於至尊，孰與甘寧？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-12', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '甘寧尚不惜死，卿何以獨惜死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-13', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蒙母徒跣出諫蒙曰：「至尊待汝如骨肉，屬汝以大事，何有以私怒而欲攻殺甘寧？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0219-a04-055-14', 'p0219', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-047-0', 'p0220', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十三年春，權復征黃祖，祖先遣舟兵拒軍，都尉呂蒙破其前鋒，而淩統、董襲等盡銳攻之，遂屠其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-048-1', 'p0220', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-048-2', 'p0220', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '高張公之德而省游田之娛，賢諸葛之言而割情欲之歡，感陸公之規而除刑政之煩，奇劉基之議而作三爵之誓，屏氣跼蹐以伺子明之疾，分滋損甘以育淩統之孤，登壇慷慨歸魯肅之功，削投惡言信子瑜之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-054-3', 'p0220', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '師還，遂征合肥，旣徹兵，為張遼等所襲，蒙與淩統以死扞衞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0220-a04-064-4', 'p0220', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '淩統聞之，請與相見，甚奇之，乃表薦贊，遂被試用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-047-0', 'p0221', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '將軍全琮、徐盛追斬魏將尹盧，殺獲數百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-1', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '蕪湖令徐盛收欽屯吏，表斬之，權以欽在遠不許，盛由是自嫌於欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-2', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時朱然、徐盛等皆在所部，並不伏也，權特為案行至濡須鄔，因會諸將，大為酣樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-3', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '徐盛字文嚮，琅邪莒人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-055-4', 'p0221', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '合肥之役，張遼奄至，諸將不備，陳武鬬死，宋謙、徐盛皆披走，璋身次在後，便馳進，橫馬斬謙、盛兵走者二人，兵皆還戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-056-5', 'p0221', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-058-6', 'p0221', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-058-7', 'p0221', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又備旣住白帝，徐盛、潘璋、宋謙等各競表言備必可禽，乞復攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0221-a04-060-8', 'p0221', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '時城中出戰，徐盛被創失矛，齊引兵拒擊，得盛所失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-036-0', 'p0222', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '臣松之桉吳書：孫權遣將潘璋逆斷羽走路，羽至即斬，且臨沮去江陵二三百里，豈容不時殺羽，方議其生死乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-1', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-2', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權先使朱然、潘璋斷其徑路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-3', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-047-4', 'p0222', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-048-5', 'p0222', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-052-6', 'p0222', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '及春水生，潘璋等作水城於上流，瑾進攻浮橋，真等退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-054-7', 'p0222', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，魯肅等以為曹公尚存，禍難始搆，宜相輔協，與之同仇，不可失也，蒙乃密陳計策曰：「令征虜守南郡，潘璋住白帝，蔣欽將游兵萬人，循江上下，應敵所在，蒙為國家前據襄陽，如此，何憂於操，何賴於羽？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-054-8', 'p0222', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權使朱然、潘璋斷其徑路，即父子俱獲，荊州遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-9', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '潘璋字文珪，東郡發干人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-10', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-055-11', 'p0222', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '以潘璋之不脩，權能忘過記功，其保據東南，宜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-12', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '建安二十四年，從討關羽，別與潘璋到臨沮禽羽，遷昭武將軍，封西安鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-13', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '權遣潘璋、楊粲等解，而圍不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-056-14', 'p0222', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '六年，權自率衆攻石陽，及至旋師，潘璋斷後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-058-15', 'p0222', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-058-16', 'p0222', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又備旣住白帝，徐盛、潘璋、宋謙等各競表言備必可禽，乞復攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-060-17', 'p0222', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '嘉禾二年，權令岱領潘璋士衆，屯陸口，後徙蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-060-18', 'p0222', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0222-a04-063-19', 'p0222', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」權使潘璋邀其徑路，覘候者還，白羽已去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-0', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬十月丁未，遣孫憲及丁奉、施寬等以舟兵逆據於江都，遣將軍劉丞督步騎攻胤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-1', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，綝率衆救壽春，次于鑊里，朱異至自夏口，綝使異為前部督，與丁奉等將介士五萬解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-2', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '甲申，使大將軍丁奉督諸軍向魏壽春，將軍留平別詣施績於南郡，議兵所向，將軍丁封、孫異如沔中，皆救蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-3', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '元興元年八月，以上大將軍施績、大將軍丁奉為左右大司馬，張布為驃騎將軍，加侍中，諸增位班賞，一皆如舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-4', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋九月，皓出東關，丁奉至合肥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-5', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '右大司馬丁奉、司空孟仁卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-6', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '江表傳曰：初皓游華里，彧與丁奉、留平密謀曰：「此行不急，若至華里不歸，社稷事重，不得不自還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-048-7', 'p0223', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-055-8', 'p0223', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '丁奉字承淵，廬江安豐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-055-9', 'p0223', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-060-10', 'p0223', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東關之役，緒與丁奉建議引兵先出，以破魏軍，封一子亭侯，年四十四卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-11', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '或曰寶鼎元年十二月，凱與大司馬丁奉、御史大夫丁固謀，因皓謁廟，欲廢皓立孫休子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-12', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '吳錄曰：舊拜廟，選兼大將軍領三千兵為衞，凱欲因此兵圖之，令選曹白用丁奉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-061-13', 'p0223', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '平素與丁奉有隙，禕未及得宣凱旨，平語禕曰：「聞野豬入丁奉營，此凶徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-14', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪遣將軍留贊、呂據、唐咨、丁奉為前部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-15', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝於是大發卒出屯鑊里，復遣異率將軍丁奉、黎斐等五萬人攻魏，留輜重於都陸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-16', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '亮內嫌綝，乃推魯育見殺本末，責怒虎林督朱熊、熊弟外部督朱損不匡正孫峻，乃令丁奉殺熊於虎林，殺損於建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a04-064-17', 'p0223', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休密問張布，布與丁奉謀於會殺綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-003-18', 'p0223', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，吳將丁奉等出芍陂，安東將軍汝陰王駿與義陽王望擊走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-003-19', 'p0223', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將丁奉入渦口，揚州刺史牽弘擊走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0223-a05-037-20', 'p0223', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '俄而吳將丁奉寇芍陂，望又率諸軍以赴之，未至而奉退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-003-0', 'p0224', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-1', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '夏五月，吳將朱然等圍襄陽之樊城，太傅司馬宣王率衆拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-2', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-004-3', 'p0224', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '習鑿齒漢晉春秋曰：是年，吳將朱然入柤中，斬獲數千；柤中民吏萬餘家渡沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-014-4', 'p0224', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大司馬曹休帥軍向皖，濟表以為「深入虜地，與權精兵對，而朱然等在上流，乘休後，臣未見其利也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-015-5', 'p0224', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '正始二年，朱然圍樊城，城中守將乙脩等求救甚急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-022-6', 'p0224', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」亮又出斜谷；征南上：「朱然等軍已過荊城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-023-7', 'p0224', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時吳使朱然、諸葛瑾攻圍樊城，遣船兵於峴山東斫材，牂牁人兵作食，有先熟者呼後熟者，言：「共食來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-025-8', 'p0224', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '上軍大將軍曹真征朱然于江陵，毗行軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-027-9', 'p0224', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '吳大將朱然圍樊城，質輕軍赴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-027-10', 'p0224', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-11', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權先使朱然、潘璋斷其徑路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-12', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-13', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-14', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '車騎將軍朱然圍樊，大將軍諸葛瑾取柤中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-15', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-16', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，步隲、朱然等各上疏云：「自蜀還者，咸言背盟與魏交通，多作舟舩，繕治城郭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-17', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '九年春二月，車騎將軍朱然征魏柤中，斬獲千餘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-18', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-19', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十一年春正月，朱然城江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-20', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二年春三月，左大司馬朱然卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-047-21', 'p0224', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-048-22', 'p0224', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-052-23', 'p0224', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：曹真、夏侯尚等圍朱然於江陵，又分據中州，瑾以大兵為之救援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-052-24', 'p0224', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-054-25', 'p0224', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑾、隲表比上，朱然及全琮亦俱陳乞，權乃許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-054-26', 'p0224', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '權使朱然、潘璋斷其徑路，即父子俱獲，荊州遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-27', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '宜都之役，與陸遜、朱然等共攻蜀軍於涿鄉，大破之，徙威烈將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-28', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時朱然、徐盛等皆在所部，並不伏也，權特為案行至濡須鄔，因會諸將，大為酣樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-055-29', 'p0224', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權征關羽，璋與朱然斷羽走道，到臨沮，住夾石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-30', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然字義封，治姊子也，本姓施氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-31', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」蒙對曰：「朱然膽守有餘，愚以為可任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-32', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳志說赤烏五年，於魏為正始三年，魏將蒲忠與朱然戰，忠不利，質等皆退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-33', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然攻樊，據與朱異破城外圍，還拜偏將軍，入補馬閑右部督，遷越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-34', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '赤烏四年，隨朱然攻魏樊城，建計破其外圍，還拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-056-35', 'p0224', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-058-36', 'p0224', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-058-37', 'p0224', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權以問遜，遜與朱然、駱統以為曹丕大合士衆，外託助國討備，內實有姦心，謹決計輒還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-059-38', 'p0224', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a04-060-39', 'p0224', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a05-001-40', 'p0224', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0224-a05-013-41', 'p0224', 'jinshu', 'a05-013', '《晉書·卷十三》', '九月，吳將朱然圍江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-0', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-1', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '仁子泰因引軍急攻朱桓，桓兵拒之，遣將軍嚴圭等擊破彫等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-047-2', 'p0225', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-048-3', 'p0225', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-056-4', 'p0225', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱桓字休穆，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-056-5', 'p0225', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-058-6', 'p0225', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜自為中部，令朱桓、全琮為左右翼，三道俱進，果衝休伏兵，因驅走之，追亡逐北，徑至夾石，斬獲萬餘，牛馬騾驢車乘萬兩，軍資器械略盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0225-a04-060-7', 'p0225', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-002-0', 'p0226', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '今征東諸軍與權黨呂範等水戰，則斬首四萬，獲船萬艘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-009-1', 'p0226', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '帝征孫權，以休為征東大將軍，假黃鉞，督張遼等及諸州郡二十餘軍，擊權大將呂範等於洞浦，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-015-2', 'p0226', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '黃初中，與諸將並征吳，破呂範於洞浦，進封陽里亭侯，加建威將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-017-3', 'p0226', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」是歲，遼與諸將破權將呂範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-018-4', 'p0226', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與曹休討吳賊，破呂範於洞浦，徵為執金吾，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-028-5', 'p0226', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '臨江，夜大風，吳將呂範等船漂至北岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-6', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策舅吳景，時為丹楊太守，策乃載母徙曲阿，與呂範、孫河俱就景，因緣召募得數百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-7', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策覺之，遣呂範、徐逸攻瑀於海西，大破瑀，獲其吏士妻子四千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-046-8', 'p0226', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '臣以十一日平旦部所領江夏太守行建威中郎將周瑜、領桂陽太守行征虜中郎將呂範、領零陵太守行蕩寇中郎將程普、行奉業校尉孫權、行先登校尉韓當、行武鋒校尉黃蓋等同時俱進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-9', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '待張昭以師傅之禮，而周瑜、程普、呂範等為將率。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-10', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '還過豫章，使呂範平鄱陽、會稽，程普討樂安，太史慈領海昏，韓當、周泰、呂蒙等為劇縣令長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-11', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權遣呂範等督五軍，以舟軍拒休等，諸葛瑾、潘璋、楊粲救南郡，朱桓以濡須督拒仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-047-12', 'p0226', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及權繼其業，有張子布以為腹心，有陸議、諸葛瑾、步隲以為股肱，有呂範、朱然以為爪牙，分任受職，乘閒伺隙，兵不妄動，故戰少敗而江南安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-048-13', 'p0226', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-050-14', 'p0226', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-051-15', 'p0226', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '江表傳曰：曹休出洞口，呂範率軍禦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-051-16', 'p0226', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」而江表傳云呂範在洞口，匡為定武中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-052-17', 'p0226', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」後有呂範、諸葛恪為說隲所言，云：「每讀步隲表，輒失笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-054-18', 'p0226', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '漢晉春秋曰：呂範勸留備，肅曰：「不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-055-19', 'p0226', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹休出洞口，盛與呂範、全琮渡江拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-056-20', 'p0226', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '呂範字子衡，汝南細陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-056-21', 'p0226', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-057-22', 'p0226', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃武元年，與呂範、賀齊等俱以舟師拒魏將曹休於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-058-23', 'p0226', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '吳書曰：權嘉遜功德，欲殊顯之，雖為上將軍列侯，猶欲令歷本州舉命，乃使揚州牧呂範就辟別駕從事，舉茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-060-24', 'p0226', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃初元年，魏以舟軍大出洞口，權使呂範督諸將拒之，軍營相望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0226-a04-060-25', 'p0226', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-046-0', 'p0227', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '盡更置長吏，策自領會稽太守，復以吳景為丹楊太守，以孫賁為豫章太守；分豫章為廬陵郡，以賁弟輔為廬陵太守，丹楊朱治為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-051-1', 'p0227', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '太守朱治舉孝廉，司空辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-052-2', 'p0227', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳郡太守朱治，權舉將也，權曾有以望之，而素加敬，難自詰讓，忿忿不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-056-3', 'p0227', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱治字君理，丹楊故鄣人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-056-4', 'p0227', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0227-a04-057-5', 'p0227', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '國家之於曁豔，不內之忌族，猶等之平民，是故先見用於朱治，次見舉於衆人，中見任於明朝，亦見交於義也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-047-0', 'p0228', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '丙寅，驃騎將軍朱據領丞相，燎鵲以祭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-048-1', 'p0228', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」初為驃騎將軍朱據軍吏，將母在營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-050-2', 'p0228', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-050-3', 'p0228', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫休朱夫人，朱據女，休姊公主所生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-052-4', 'p0228', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權末年，嫡庶不分，悌數與驃騎將軍朱據共陳禍福，言辭切直，朝廷憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-056-5', 'p0228', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '異字季文，以父任除郎，文士傳曰：張惇子純與張儼及異俱童少，往見驃騎將軍朱據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-6', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '朱據字子範，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-7', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '數月，典軍吏劉助覺，言王遂所取，權大感寤，曰：「朱據見枉，況吏民乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-057-8', 'p0228', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲、朱據遭罹屯蹇，以正喪身，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-9', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-10', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-059-11', 'p0228', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '於是驃騎將軍朱據、尚書僕射屈晃率諸將吏泥頭自縛，連日詣闕請和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-061-12', 'p0228', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '時校事呂壹操弄威柄，奏桉丞相顧雍、左將軍朱據等，皆見禁止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-062-13', 'p0228', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '左將軍朱據、廷尉郝普稱蕃有王佐之才，普尤與之親善，常怨歎其屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0228-a04-064-14', 'p0228', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱據先帝舊臣，子男熊、損皆承父之基，以忠義自立，昔殺小主，自是大主所創，帝不復精其本末，便殺熊、損，諫不見用，諸下莫不側息。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-004-0', 'p0229', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '干寶晉紀曰：吳將全琮寇芍陂，朱然、孫倫五萬人圍樊城，諸葛瑾、步隲寇柤中；琮已破走而樊圍急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-024-1', 'p0229', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '吳大將全琮帥數萬衆來侵寇，時州兵休使，在者無幾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-027-2', 'p0229', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基曰：「昔孫權再至合肥，一至江夏，其後全琮出廬江，朱然寇襄陽，皆無功而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-028-3', 'p0229', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '二年，吳大將全琮數萬衆寇芍陂，淩率諸軍逆討，與賊爭塘，力戰連日，賊退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-028-4', 'p0229', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-037-5', 'p0229', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '及當西還，並會昌門，陸績、顧劭、全琮皆往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-037-6', 'p0229', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '謂全琮曰：「卿好施慕名，有似汝南樊子昭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-7', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '近得守將周泰、全琮等白事，過月六日，有馬步七百，徑到橫江，又督將馬和復將四百人進到居巢，琮等聞有兵馬渡江，視之，為兵馬所擊，臨時交鋒，大相殺傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-8', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '將軍全琮、徐盛追斬魏將尹盧，殺獲數百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-9', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '衞將軍全琮表稱熾任大將軍，赴召，道卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-10', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '以全琮為太守，平討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-11', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，權向合肥新城，遣將軍全琮征六安，皆不克還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-12', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，遣衞將軍全琮襲六安，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-13', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，遣衞將軍全琮略淮南，決芍陂，燒安城邸閣，收其人民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-14', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-047-15', 'p0229', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十年春正月，右大司馬全琮卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-050-16', 'p0229', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '生二女，長曰魯班，字大虎，前配周瑜子循，後配全琮；少曰魯育，字小虎，前配朱據，後配劉纂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-17', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '時長公主壻衞將軍全琮子寄為霸賔客，寄素傾邪，譚所不納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-18', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '先是，譚弟承與張休俱北征壽春，全琮時為大都督，與魏將王淩戰於芍陂，軍不利，魏兵乘勝陷沒五營將秦晃軍，休、承奮擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-052-19', 'p0229', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：全琮父子屢言芍陂之役為典軍陳恂詐增張休、顧承之功，而休、承與恂通情。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-054-20', 'p0229', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑾、隲表比上，朱然及全琮亦俱陳乞，權乃許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-054-21', 'p0229', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '峻卒，全琮表峻子護為將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-055-22', 'p0229', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹休出洞口，盛與呂範、全琮渡江拒守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-23', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '嘉禾三年，權與蜀克期大舉，權自向新城，然與全琮各受斧鉞，為左右督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-24', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-25', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '性好威儀，州民如陸遜、全琮及貴公子，皆脩敬虔肅，不敢輕脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-26', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時陸遜為元帥，全琮與桓為左右督，各督三萬人擊休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-27', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '桓與衞將軍全琮俱以師迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-056-28', 'p0229', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時全琮為督，權又令偏將軍胡綜宣傳詔命，參與軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-057-29', 'p0229', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」大司農劉基曰：「可與全琮為輩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-058-30', 'p0229', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜自為中部，令朱桓、全琮為左右翼，三道俱進，果衝休伏兵，因驅走之，追亡逐北，徑至夾石，斬獲萬餘，牛馬騾驢車乘萬兩，軍資器械略盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-058-31', 'p0229', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '全琮報遜，遜以為子弟苟有才，不憂不用，不宜私出以要榮利；若其不佳，終為取禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-32', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '時廷尉監隱蕃交結豪傑，自衞將軍全琮等皆傾心敬待，惟衜及宣詔郎豫章楊迪拒絕不與通，時人咸怪之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-33', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-34', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-059-35', 'p0229', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '呂岱、全琮之徒，蓋所不足論耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-36', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '全琮字子璜，吳郡錢唐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-37', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a04-060-38', 'p0229', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a05-001-39', 'p0229', 'jinshu', 'a05-001', '《晉書·卷一》', '二年夏五月，吳將全琮寇芍陂，朱然、孫倫圍樊城，諸葛瑾、步騭掠柤中，帝請自討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0229-a05-002-40', 'p0229', 'jinshu', 'a05-002', '《晉書·卷二》', '奇兵震擊，而朱異摧破；神變應機，而全琮稽服；取亂攻昧，而高墉不守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-0', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '四年夏，遣呂岱討桓等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-1', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏，呂岱討廬陵賊，畢，還陸口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-2', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '禮還，復有詔責數諸葛瑾、步隲、朱然、呂岱等曰：「袁禮還，云與子瑜、子山、義封、定公相見，並以時事當有所先後，各自以不掌民事，不肯便有所陳，悉推之伯言、承明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-3', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '遣將軍呂岱、唐咨討之，歲餘皆破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-047-4', 'p0230', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-5', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '閏月，以恪為帝太傅，胤為衞將軍領尚書事，上大將軍呂岱為大司馬，諸文武在位皆進爵班賞，宂官加等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-6', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '癸卯，更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-048-7', 'p0230', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-8', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '權以交阯縣遠，乃分合浦以北為廣州，呂岱為刺史；交阯以南為交州，戴良為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-9', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '而呂岱被詔誅徽，自廣州將兵晝夜馳入，過合浦，與良俱前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-049-10', 'p0230', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '呂岱師友士匡，使通信誓，徽兄弟肉袒，推心委命，岱因滅之，以要功利，君子是以知孫權之不能遠略，而呂氏之祚不延者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-052-11', 'p0230', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '延康元年，權遣呂岱代隲，隲將交州義士萬人出長沙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-12', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '時交土始開，刺吏呂岱率師討伐，綜與俱行，越海南征，及到九真。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-13', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '呂岱從交州召出，綜懼繼岱者非其人，上疏曰：「昔帝舜南巡，卒於蒼梧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-053-14', 'p0230', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '呂岱旣至，有士民之變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-057-15', 'p0230', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '欲諫不敢，作表以示呂岱，岱不報，為愛憎所白，復徙蒼梧猛陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-057-16', 'p0230', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」粲募合人衆，拜昭義中郎將，與呂岱討平山越，入為屯騎校尉、少府，遷太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-17', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-18', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-19', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '呂岱、全琮之徒，蓋所不足論耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-059-20', 'p0230', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '大司馬呂岱親受先帝詔勑，輔導大王，旣不承用其言，令懷憂怖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-21', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱字定公，廣陵海陵人也，為郡縣吏，避亂南渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-22', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '權聞之歎息，以讓羣臣曰：「呂岱出身萬里，為國勤事，家門內困，而孤不早知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-23', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及原死，岱哭之甚哀，曰：「德淵，呂岱之益友，今不幸，岱復於何聞過？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-060-24', 'p0230', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-063-25', 'p0230', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」後呂岱從蜀還，遇之白帝，說備部衆離落，死亡且半，事必不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-064-26', 'p0230', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臨去，大司馬呂岱戒之曰：「世方多難，子每事必十思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a04-064-27', 'p0230', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0230-a05-015-28', 'p0230', 'jinshu', 'a05-015', '《晉書·卷十五》', '戴良為刺史，值亂不得入，呂岱擊平之，復還并交部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-047-0', 'p0231', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏五月，鄱陽太守周魴偽叛，誘魏將曹休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-056-1', 'p0231', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武七年，鄱陽太守周魴譎誘魏大司馬曹休，休將步騎十萬至皖城以迎魴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-058-2', 'p0231', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '七年，權使鄱陽太守周魴譎魏大司馬曹休，休果舉衆入皖，乃召遜假黃鉞，為大都督，逆休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-060-3', 'p0231', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '周魴字子魚，吳郡陽羨人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0231-a04-060-4', 'p0231', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-048-0', 'p0232', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '鄱陽、新都民為亂，廷尉丁密、步兵校尉鄭胄、將軍鍾離牧率軍討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-060-1', 'p0232', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '鍾離牧字子幹，會稽山陰人，漢魯相意七世孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0232-a04-060-2', 'p0232', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂岱清恪在公；周魴譎略多奇；鍾離牧蹈長者之規；全琮有當世之才，貴重於時，然不檢姧子，獲譏毀名云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a03-112-0', 'p0233', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三國時陸遜攻襄陽，又值此穴中有數十匹馬出，遜載還建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-026-1', 'p0233', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '明年，吴將陸遜向廬江，論者以為宜速赴之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-027-2', 'p0233', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '今陸遜等已死，而權年老，內無賢嗣，中無謀主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-039-3', 'p0233', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之以為陳羣子泰，陸遜子抗，傳皆以子繫父，不別載姓，及王肅、杜恕、張承、顧劭之流，莫不皆然，惟董允獨否，未詳其意，當以允名位優重，事跡踰父故邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-4', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陸遜別取宜都，獲秭歸、枝江、夷道，還屯夷陵，守峽口以備蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-5', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權以陸遜為督，督朱然、潘璋等以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-6', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '黃武元年春正月，陸遜部將軍宋謙等攻蜀五屯，皆破之，斬其將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-7', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權未之許，而謂將相曰：「往年孤以玄德方向西鄙，故先命陸遜選衆以待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-8', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」是時陸遜以所在少穀，表令諸將增廣農畒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-9', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，陸遜陳便宜，勸以施德緩刑，寬賦息調。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-10', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋八月，權至皖口，使將軍陸遜督諸將大破休於石亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-11', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」秋九月，權遷都建業，因故府不改館，徵上大將軍陸遜輔太子登，掌武昌留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-12', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-13', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陸遜陳其素行，因為之請，權乃減宗一等，後不得以為比，因此遂絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-14', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二月，陸遜討彭旦等，其年，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-15', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '陛下身自御戎，取亂侮亡，宜滌荊、揚之地，舉彊羸之數，使彊者執戟，羸者轉運，西命益州軍于隴右，授諸葛瑾、朱然大衆指事襄陽，陸遜、朱桓別征壽春，大駕入淮陽，歷青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-16', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '七年春正月，以上大將軍陸遜為丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-047-17', 'p0233', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '八年春二月，丞相陸遜卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-051-18', 'p0233', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '鎮巴丘，數咨陸遜以得失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-051-19', 'p0233', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '年二十五，拜安東中郎將，與陸遜共拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-20', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '壹姦險亂法，毀傷忠賢，吳國寒心，自太子登、陸遜已下，切諫不能得，是以潘濬欲因會同手劒之，以除國患，疾惡忠主，義形於色，而今乃發起令言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-21', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少與舅陸績齊名，而陸遜、張敦、卜靜等皆亞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-22', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '此語頗流聞於外，陸遜表保明瑾無此，宜以散其意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-23', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '是歲，都督西陵，代陸遜撫二境，頃以兾州在蜀分，解牧職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-24', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-25', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-26', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-052-27', 'p0233', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '赤烏九年，代陸遜為丞相，猶誨育門生，手不釋書，被服居處有如儒生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-053-28', 'p0233', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-054-29', 'p0233', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫權與陸遜論周瑜、魯肅及蒙曰：「公瑾雄烈，膽略兼人，遂破孟德，開拓荊州，邈焉難繼，君今繼之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-30', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '宜都之役，與陸遜、朱然等共攻蜀軍於涿鄉，大破之，徙威烈將軍，封都亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-31', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '陸遜拜表偏將軍，進封都鄉侯，北屯章阬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-32', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-055-33', 'p0233', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '少以驍勇為小將，屬甘寧、陸遜、潘璋等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-34', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武元年，劉備舉兵攻宜都，然督五千人與陸遜并力拒備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-35', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又陸遜亦卒，功臣名將存者惟然，莫與比隆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-36', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '性好威儀，州民如陸遜、全琮及貴公子，皆脩敬虔肅，不敢輕脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-37', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時陸遜為元帥，全琮與桓為左右督，各督三萬人擊休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-056-38', 'p0233', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」權先與陸遜議，遜以為不可，故計不施行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-39', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '以隨陸遜破蜀軍於宜都，遷偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-40', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '雖起孤微，與同郡陸遜、卜靜等比肩齊聲矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-057-41', 'p0233', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '又數以消息語陸遜，遜時駐武昌，連表諫爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-42', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '陸遜字伯言，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-43', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '」蒙對曰：「陸遜意思深長，才堪負重，觀其規慮，終可大任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-058-44', 'p0233', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '評曰：劉備天下稱雄，一世所憚，陸遜春秋方壯，威名未著，摧而克之，罔不如志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-45', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權遷都建業，徵上大將軍陸遜輔登鎮武昌，領宮府留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-46', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '住十餘日，欲遣西還，深自陳乞，以乆離定省，子道有闕，又陳陸遜忠勤，無所顧憂，權遂留焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-47', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '陸遜忠勤於時，出身憂國，謇謇在公，有匪躬之節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-48', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '魯王霸覬覦滋甚，陸遜、吾粲、顧譚等數陳適庶之義，理不可奪，全寄、楊笁為魯王霸支黨，譖愬日興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-059-49', 'p0233', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-50', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '齊與陸遜討破突，斬首數千，餘黨震服，丹楊三縣皆降，料得精兵八千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-51', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '七年，權到皖，使琮與輔國將軍陸遜擊曹休，破之於石亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-52', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '潘濬卒，岱代濬領荊州文書，與陸遜並在武昌，故督蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-53', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及陸遜卒，諸葛恪代遜，權乃分武昌為兩部，岱督右部，自武昌上至蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-54', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '魴亦合衆，隨陸遜橫截休，休幅裂瓦解，斬獲萬計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-060-55', 'p0233', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '嗣弟怖懼，詣武昌降於陸遜，乞出平地，自改為善，由是數郡無復憂惕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-061-56', 'p0233', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先是，濬與陸遜俱駐武昌，共掌留事，還復故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-061-57', 'p0233', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '太子不見，而微服至其車上，與共密議，欲令陸遜表諫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-58', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛亮聞恪代詳，書與陸遜曰：「家兄年老，而恪性踈，今使典主糧穀，糧穀軍之要最，僕雖在遠，竊用不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-59', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '與丞相陸遜書曰：「楊敬叔傳述清論，以為方今人物彫盡，守德業者不能復幾，宜相左右，更為輔車，上熙國事，下相珍惜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0233-a04-064-60', 'p0233', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '若躬行所與陸遜及弟融之書，則悔吝不至，何尤禍之有哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-041-0', 'p0234', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '孫休怒，復遣陸抗等帥衆三萬人增憲之圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-1', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二月，鎮軍陸抗、撫軍步恊、征西將軍留平、建平太守盛曼，率衆圍蜀巴東守將羅憲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-2', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏使將軍胡烈步騎二萬侵西陵，以救羅憲，陸抗等引軍退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-3', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '遣樂鄉都督陸抗圍取闡，闡衆悉降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-4', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '二年春三月，以陸抗為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-048-5', 'p0234', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '陸抗之克步闡，皓意張大，乃使尚廣筮并天下，遇同人之頤，對曰：「吉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-052-6', 'p0234', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '孫皓使陸抗西行，祜等遁退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-056-7', 'p0234', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳書曰：綝要異相見，將往，恐陸抗止之，異曰：「子通，家人耳，當何所疑乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-058-8', 'p0234', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '陸抗每告其邊戍曰：「彼專為德，我專為暴，是不戰而自服也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-061-9', 'p0234', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '初，皓常銜凱數犯顏忤旨，加何定譖構非一，旣以重臣，難繩以法，又陸抗時為大將在疆埸，故以計容忍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a04-065-10', 'p0234', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '定聞陸抗表至，成都不守，臣主播越，社稷傾覆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-003-11', 'p0234', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將陸抗攻闡，遣車騎將軍羊祜帥衆出江陵，荊州刺史楊肇迎闡於西陵，巴東監軍徐胤擊建平以救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-034-12', 'p0234', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '吳將陸抗攻之甚急，詔祜迎闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0234-a05-034-13', 'p0234', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜與陸抗相對，使命交通，抗稱祜之德量，雖樂毅、諸葛孔明不能過也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-037-0', 'p0235', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '及當西還，並會昌門，陸績、顧劭、全琮皆往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-048-1', 'p0235', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-052-2', 'p0235', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少與舅陸績齊名，而陸遜、張敦、卜靜等皆亞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-3', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸績字公紀，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-4', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '豫自知亡日，乃為辭曰：「有漢志士吳郡陸績，幼敦詩、書，長玩禮、易，受命南征，遘疾遇厄，遭命不幸，嗚呼悲隔！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-5', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '臣切見故鬱林太守陸績女子鬱生，少履貞特之行，幼立匪石之節，年始十三，適同郡張白。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a04-057-6', 'p0235', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸績之於楊玄，是仲尼之左丘明，老聃之嚴周矣；以瑚璉之器，而作守南越，不亦賊夫人歟！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a05-011-7', 'p0235', 'jinshu', 'a05-011', '《晉書·卷十一》', '」陸績云：「天東西南北徑三十五萬七千里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0235-a05-011-8', 'p0235', 'jinshu', 'a05-011', '《晉書·卷十一》', '而陸績造渾象，其形如鳥卵，然則黃道應長於赤道矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-0', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '胡冲吳歷曰：孫策擊豫章，先遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-1', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '虞溥江表傳曰：孫策在椒丘，遣虞翻說歆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-013-2', 'p0236', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '朗功曹虞翻以為力不能拒，不如避之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-048-3', 'p0236', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-049-4', 'p0236', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '權嘗宴飲，騎都尉虞翻醉酒犯忤，權欲殺之，威怒甚盛，由基諫爭，翻以得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-052-5', 'p0236', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '虞翻以狂直流徙，惟瑾屢為之說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-054-6', 'p0236', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '吳書曰：將軍士仁在公安拒守，蒙令虞翻說之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-7', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻字仲翔，會稽餘姚人也，吳書曰：翻少好學，有高氣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-8', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」權曰：「曹孟德尚殺孔文舉，孤於虞翻何有哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-9', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻亮直，善於盡言，國之周舍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-10', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '昔初平末年，王府君以淵妙之才，超遷臨郡，思賢嘉善，樂采名俊，問功曹虞翻曰：『聞玉出崑山，珠生南海，遠方異域，各生珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-11', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其聦明大略，忠直謇諤，則侍御史餘姚虞翻、偏將軍烏傷駱統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-12', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '虞翻舊齒名盛，龐統荊州令士，年亦差長，皆與績友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-057-13', 'p0236', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '評曰：虞翻古之狂直，固難免乎末世，然權不能容，非曠宇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-059-14', 'p0236', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '蔣脩、虞翻，志節分明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0236-a04-064-15', 'p0236', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '虞翻徙交州，縣令使友送之，翻與語而奇焉，為書與豫章太守謝斐，令以為功曹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-0', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-1', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，以司空張溫為車騎將軍，討北宮伯玉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-2', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，張溫破北宮伯玉於美陽，因遣盪寇將軍周慎追擊之，圍榆中；縣名，故城在今蘭州金城縣東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-3', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '車騎將軍張溫為太尉，中常侍趙忠為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-full-4', 'p0237', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉張溫免，司徒崔烈為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-5', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-6', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，以司空張溫為車騎將軍，討北宮伯玉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-7', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，張溫破北宮伯玉於美陽，因遣盪寇將軍周慎追擊之，圍榆中；縣名，故城在今蘭州金城縣東也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-8', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '車騎將軍張溫為太尉，中常侍趙忠為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-008-9', 'p0237', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉張溫免，司徒崔烈為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-009-10', 'p0237', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月壬戌，董卓殺衞尉張溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-036-11', 'p0237', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '司空張溫數以禮辟，不能致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-038-12', 'p0237', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '後尚書令張溫特表薦之，徵拜尚書僕射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-052-13', 'p0237', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '是時段熲、樊陵、張溫等雖有功勤名譽，然皆先輸貨財而後登公位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-054-14', 'p0237', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '二年九月，復代張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-057-15', 'p0237', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '將軍張溫天性精勇，而主者旦夕迫促，軍無後殿，假令失利，其敗不救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-058-16', 'p0237', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」虞、紹亦素有謀，因相連結，未及發，而司隷校尉張溫舉勳為京兆尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-064-17', 'p0237', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '車騎將軍張溫西征關中，請補長史，別屯安定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-071-18', 'p0237', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '司空張溫上疏曰：「昔秦用白起，燕任樂毅，皆曠年歷載，乃能克敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-19', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '朝廷復以司空張溫為車騎將軍，假節，執金吾袁滂為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-20', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年春，遣使者持節就長安拜張溫為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-072-21', 'p0237', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃使人誣衞尉張溫與袁術交通，遂笞溫於市，殺之，以塞天變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-22', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '後車騎將軍張溫討賊邊章等，發幽州烏桓三千突騎，而牢稟逋懸，前書音義曰：「牢，賈直也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-23', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '中平中，以瓚督烏桓突騎，車騎將軍張溫討涼州賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-073-24', 'p0237', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '』」四遷為車騎將軍張溫司馬，西討邊章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-078-25', 'p0237', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '其所進達，皆海內名人，陳留虞放、邊韶、南陽延固、張溫、弘農張奐、潁川堂谿典等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a03-083-26', 'p0237', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '尚書郎南陽張溫異之，使問曰：「人皆來觀，老父獨不輟，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-001-27', 'p0237', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '其所稱薦，若陳留虞放、邊韶、南陽延固、張溫、弘農張奐、潁川堂谿典等，皆致位公卿，而不伐其善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-006-28', 'p0237', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉張溫時為衞尉，素不善卓，卓心怨之，因天有變，欲以塞咎，使人言溫與袁術交關，遂笞殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-006-29', 'p0237', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傅子曰：靈帝時牓門賣官，於是太尉段熲、司徒崔烈、太尉樊陵、司空張溫之徒，皆入錢上千萬下五百萬以買三公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-008-30', 'p0237', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '遷幽州刺史，徵拜議郎，參車騎將軍張溫軍事，西討韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-008-31', 'p0237', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '後邊章、韓遂為亂，司空張溫銜命征討；又請謙為參軍事，接遇甚厚，而謙輕其行事，心懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-038-32', 'p0237', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '吳遣使張溫來聘，百官皆往餞焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-045-33', 'p0237', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」遂自絕魏，與蜀連和，遣張溫報聘於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-046-34', 'p0237', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '中平三年，遣司空張溫行車騎將軍，西討章等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-046-35', 'p0237', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孤語張溫，求引所將兵為慎作後駐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-047-36', 'p0237', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '三年夏，遣輔義中郎將張溫聘于蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-047-37', 'p0237', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '張溫、曁豔奏其事，邵辭位請罪，權釋令復職，年六十三卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-048-38', 'p0237', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-050-39', 'p0237', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '奮弟祺，吳書曰：祺與張溫、顧譚友善，權令關平辭訟事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-052-40', 'p0237', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後與張溫俱使蜀，諸葛亮甚稱歎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-053-41', 'p0237', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-42', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '績於鬱林所生女，名曰鬱生，適張溫弟白。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-43', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '張溫字惠恕，吳郡吳人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-44', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權幽之有司，下令曰：「昔令召張溫，虛己待之，旣至顯授，有過舊臣，何圖凶醜，專挾異心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-45', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '多士旣受普篤之恩，張溫又蒙最隆之施。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-46', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」　臣松之以為莊周云「名者公器也，不可以多取」，張溫之廢，豈其取名之多乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-47', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權咨嗟將率，發憤歎息，追思呂蒙、張溫，以為據才兼文武，可以繼之，自是拜建義校尉，領兵屯湖孰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-057-48', 'p0237', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '張溫才藻俊茂，而智防未備，用致艱患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-059-49', 'p0237', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '太傅張溫言於權曰：「夫中庶子官最親密，切問近對，宜用儁德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-063-50', 'p0237', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '于時吳使張溫先在蜀，旣於市中相識，甚驚，便作書寄其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0237-a04-064-51', 'p0237', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時皇象亦寓居山陰，吳郡張溫來就象學，欲得所舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-048-0', 'p0238', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-053-1', 'p0238', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，拜固議郎，自陸遜、張溫、駱統等皆拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-2', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陵卒，僮客土田或見侵奪，駱統為陵家訟之，求與丁覽、卜清等為比，權許焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-3', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其聦明大略，忠直謇諤，則侍御史餘姚虞翻、偏將軍烏傷駱統。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-4', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '將軍駱統表理溫曰：「伏惟殿下，天生明德，神啟聖心，招髦秀於四方，置俊乂於宮朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-5', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '權旣疾溫名盛，而駱統方驟言其美，至云「卓躒冠羣，煒曄曜世，世人未有及之者也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-6', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '駱統字公緒，會稽烏傷人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-057-7', 'p0238', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '駱統抗明大義，辭切理至，值權方閉不開。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-058-8', 'p0238', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '權以問遜，遜與朱然、駱統以為曹丕大合士衆，外託助國討備，內實有姦心，謹決計輒還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0238-a04-058-9', 'p0238', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '駱統子名秀，被門庭之謗，衆論狐疑，莫能證明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-052-0', 'p0239', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '承字子直，嘉禾中與舅陸瑁俱以禮徵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-057-1', 'p0239', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸瑁字子璋，丞相遜弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0239-a04-057-2', 'p0239', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陸瑁篤義規諫，君子有稱焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-047-0', 'p0240', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '中郎將吾粲獲李桓，將軍唐咨獲羅厲等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-052-1', 'p0240', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昔丁諝出於孤家，吾粲由於牧豎，豫章揚其善，以並陸、全之列，是以人無幽滯而風俗厚焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-057-2', 'p0240', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲字孔休，吳郡烏程人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-057-3', 'p0240', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '吾粲、朱據遭罹屯蹇，以正喪身，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-058-4', 'p0240', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '太子太傅吾粲坐數與遜交書，下獄死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-059-5', 'p0240', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛瑾、步隲、朱然、全琮、朱據、呂岱、吾粲、闞澤、嚴畯、張承、孫怡忠於為國，通達治體。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-059-6', 'p0240', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '魯王霸覬覦滋甚，陸遜、吾粲、顧譚等數陳適庶之義，理不可奪，全寄、楊笁為魯王霸支黨，譖愬日興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0240-a04-060-7', 'p0240', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '吾粲、唐咨甞以三千兵攻守，連月不能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-045-0', 'p0241', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '－－贊糜芳、士仁、郝普、潘濬糜芳字子方，東海人也，為南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-045-1', 'p0241', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '潘濬字承明，武陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-2', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '三年春二月，遣太常潘濬率衆五萬討武陵蠻夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-3', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十一月，太常潘濬平武陵蠻夷，事畢，還武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-047-4', 'p0241', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '權大怒，召胄還，潘濬、陳表並為請，得釋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-048-5', 'p0241', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-048-6', 'p0241', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '拔呂蒙於戎行，識潘濬於係虜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-051-7', 'p0241', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時太常潘濬掌荊州事，重安長陳留舒燮有罪下獄，濬嘗失燮，欲致之於法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-8', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '壹姦險亂法，毀傷忠賢，吳國寒心，自太子登、陸遜已下，切諫不能得，是以潘濬欲因會同手劒之，以除國患，疾惡忠主，義形於色，而今乃發起令言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-9', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」隲於是條于時事業在荊州界者，諸葛瑾、陸遜、朱然、程普、潘濬、裴玄、夏侯承、衞旌、李肅、吳書曰：肅字偉恭，南陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-10', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '自今蔽獄，都下則宜諮顧雍，武昌則陸遜、潘濬，平心專意，務在得情，隲黨神明，受罪何恨？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-052-11', 'p0241', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」又曰：「丞相顧雍、上大將軍陸遜、太常潘濬，憂深責重，志在謁誠，夙夜兢兢，寢食不寧，念欲安國利民，建乆長之計，可謂心膂股肱，社稷之臣矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-056-12', 'p0241', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '叔父才卒，績領其兵，隨太常潘濬討五溪，以膽力稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-056-13', 'p0241', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '隨太常潘濬討五谿，復有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-058-14', 'p0241', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '時中書典校呂壹，竊弄權柄，擅作威福，遜與太常潘濬同心憂之，言至流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-15', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '會武陵蠻夷蠢動，岱與太常潘濬共討定之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-16', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '潘濬卒，岱代濬領荊州文書，與陸遜並在武昌，故督蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-060-17', 'p0241', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '其六曰：「東主致恨前者不拔石陽，今此後舉，大合新兵，并使潘濬發夷民，人數甚多，聞豫設科條，當以新羸兵置前，好兵在後，攻城之日，云欲以羸兵填壍，使即時破，雖未能然，是事大趣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-061-18', 'p0241', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '潘濬字承明，武陵漢壽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0241-a04-061-19', 'p0241', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '評曰：潘濬公清割斷，陸凱忠壯質直，皆節槩梗梗，有大丈夫格業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-047-0', 'p0242', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋七月，遣將軍聶友、校尉陸凱以兵三萬討珠崖、儋耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-047-1', 'p0242', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-2', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」皓訪羣臣，鎮西大將軍陸凱曰：「夫兵不得已而用之耳，且三國鼎立已來，更相侵伐，無歲寧居。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-3', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '以陸凱為左丞相，常侍萬彧為右丞相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-4', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十一月，左丞相陸凱卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-048-5', 'p0242', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-057-6', 'p0242', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '皓悖虐，固與陸凱、孟宗同心憂國，年七十六卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-059-7', 'p0242', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '靈輿當至，使丞相陸凱奉三牲祭於近郊，皓於金城外露宿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-061-8', 'p0242', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '陸凱字敬風，吳郡吳人，丞相遜族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-061-9', 'p0242', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '評曰：潘濬公清割斷，陸凱忠壯質直，皆節槩梗梗，有大丈夫格業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0242-a04-065-10', 'p0242', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '丞相陸凱上疏曰：「常侍王蕃黃中通理，知天知物，處朝忠蹇，斯社稷之重鎮，大吳之龍逢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-035-0', 'p0243', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '於是儀結陣而去，入谷然後發喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-1', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '是儀字子羽，北海營陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-2', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '徐衆評曰：是儀以羈旅異方，客仕吳朝，值讒邪殄行，當嚴毅之威，命縣漏刻，禍急危機，不雷同以害人，不苟免以傷義，可謂忠勇公正之士，雖祁奚之免叔向，慶忌之濟朱雲，何以尚之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-3', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '鄰家有起大宅者，權出望見，問起大室者誰，左右對曰：「似是儀家也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-4', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '權歎曰：「使人盡如是儀，當安用科法為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-5', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '權為車騎將軍，都京，召綜還，為書部，與是儀、徐詳俱典軍國密事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0243-a04-062-6', 'p0243', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-047-0', 'p0244', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」將軍胡綜議，以為「喪紀之禮，雖有典制，苟無其時，所不得行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-056-1', 'p0244', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時全琮為督，權又令偏將軍胡綜宣傳詔命，參與軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-056-2', 'p0244', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '琮欲自解，因曰：「上自令胡綜為督，綜意以為宜爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-059-3', 'p0244', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '江表傳曰：登使侍中胡綜作賔友目曰：「英才卓越，超踰倫匹，則諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-060-4', 'p0244', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃武中，鄱陽大帥彭綺作亂，攻沒屬城，乃以魴為鄱陽太守，與胡綜戮力攻討，遂生禽綺，送詣武昌，加昭義校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-061-5', 'p0244', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '先帝外仗顧、陸、朱、張，內近胡綜、薛綜，是以庶績雍熈，邦內清肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-062-6', 'p0244', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '胡綜字偉則，汝南固始人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0244-a04-062-7', 'p0244', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '評曰：是儀、徐詳、胡綜，皆孫權之時幹興事業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-008-0', 'p0245', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謙重令楊州從事會稽吳範宣旨，昱守意不移；欲威以刑罰，然後乃起。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-048-1', 'p0245', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '於是張昭為師傅，周瑜、陸公、魯肅、呂蒙之疇入為腹心，出作股肱；甘寧、淩統、程普、賀齊、朱桓、朱然之徒奮其威，韓當、潘璋、黃蓋、蔣欽、周泰之屬宣其力；風雅則諸葛瑾、張承、步隲以聲名光國，政事則顧雍、潘濬、呂範、呂岱以器任幹職，奇偉則虞翻、陸績、張溫、張惇以諷議舉正，奉使則趙咨、沈珩以敏達延譽，術數則吳範、趙達以禨祥協德，董襲、陳武殺身以衞主，駱統、劉基彊諫以補過，謀無遺筭，舉不失策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-057-2', 'p0245', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '其探極祕術，言合神明，則太史令上虞吳範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-3', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '吳範字文則，會稽上虞人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-4', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」曰：「使汝為吳範死，子以屬我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0245-a04-063-5', 'p0245', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權追思之，募三州有能舉知術數如吳範、趙達者，封千戶侯，卒無所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-0', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲諸葛恪帥軍更於隄左右結山，挾築兩城，使全端、留略守之，引軍而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-1', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月，吳大將軍諸葛恪拒戰，大破衆軍於東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-2', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五月，吳太傅諸葛恪圍合肥新城，詔太尉司馬孚拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-3', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '及諸葛恪圍城，特與將軍樂方等三軍衆合有三千人，吏兵疾病及戰死者過半，而恪起土山急攻，城將陷，不可護。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-004-4', 'p0246', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '六年春二月己丑，鎮東將軍毌丘儉上言：「昔諸葛恪圍合肥新城，城中遣士劉整出圍傳消息，為賊所得，考問所傳，語整曰：『諸葛公欲活汝，汝可具服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-015-5', 'p0246', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '數為國家陳擊吳、蜀形勢，又嘗對司馬大將軍料諸葛恪雖得勝於邊土，見誅不乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-015-6', 'p0246', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '大將軍聞恪死，謂衆人曰：「諸葛恪多輩耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-7', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今權以死，託孤於諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-8', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今權已死，託孤於諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-9', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '五年正月，諸葛恪拒戰，大破衆軍於東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-021-10', 'p0246', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '後吳大將諸葛恪新破東關，乘勝揚聲欲向青、徐，朝廷將為之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-027-11', 'p0246', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '基諫曰：「昔諸葛恪乘東關之勝，竭江表之兵，以圍新城，城旣不拔，而衆死者太半。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-12', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-13', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛恪興東關，遣誕督諸軍討之，與戰，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-14', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛恪圍合肥新城，不克，退歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-028-15', 'p0246', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾矯然彊壯，立功立事，然闇於防患，咎敗旋至，豈遠知乎諸葛恪而不能近自見，此蓋古人所謂目論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-035-16', 'p0246', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛恪見誅於吳，子孫皆盡，而亮自有胄裔，故攀還復為瑾後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-035-17', 'p0246', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-043-18', 'p0246', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '吳太傅諸葛恪以初破魏軍，大興兵衆以圖攻取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-044-19', 'p0246', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '孫權性旣滑稽，嘲啁無方，諸葛恪、羊衜等才愽果辯，論難鋒至，禕辭順義篤，據理以荅，終不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-20', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋八月，以諸葛恪為丹陽太守，討山越。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-21', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '諸葛恪平山越事畢，北屯廬江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-22', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '威北將軍諸葛恪攻六安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-23', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '諸葛恪征六安，破魏將謝順營，收其民人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-24', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是歲，司馬宣王率軍入舒，諸葛恪自皖遷于柴桑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-047-25', 'p0246', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '秋九月，以驃騎步隲為丞相，車騎朱然為左大司馬，衞將軍全琮為右大司馬，鎮南呂岱為上大將軍，威北將軍諸葛恪為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-26', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，權寢疾，徵大將軍諸葛恪為太子太傅，會稽太守滕胤為太常，並受詔輔太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-27', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳錄云：諸葛恪有遷都意，更起武昌宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-28', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '四月，權薨，休弟亮承統，諸葛恪秉政，不欲諸王在濵江兵馬之地，徙休於丹楊郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-048-29', 'p0246', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '後常為諸葛恪司馬，幹恪府事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-051-30', 'p0246', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-31', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '又諸葛恪年少時，衆人奇其英才，承言終敗諸葛氏者元遜也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-32', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '休字叔嗣，弱冠與諸葛恪、顧譚等俱為太子登僚友，以漢書授登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-33', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '譚字子默，弱冠與諸葛恪等為太子四友，從中庶子轉輔正都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-34', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '時四方之傑畢集，太傅諸葛恪以雄奇蓋衆，而譚以清識絕倫，獨見推重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-35', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後為吳郡西部都尉，與諸葛恪等共平山越，別得精兵八千人，還屯軍章阬，拜昭義中郎將，入為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-052-36', 'p0246', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」後有呂範、諸葛恪為說隲所言，云：「每讀步隲表，輒失笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-053-37', 'p0246', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '酒酣，禕與諸葛恪相對嘲難，言及吳、蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-38', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '東興之役，綜為前鋒，軍敗身死，諸葛恪斬送其首，以白權廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-39', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '弟表，字文奧，武庶子也，少知名，與諸葛恪、顧譚、張休等並侍東宮，皆共親友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-40', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '嘉禾三年，諸葛恪領丹楊太守，討平山越，以表領新安都尉，與恪參勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-055-41', 'p0246', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏遣諸葛誕、胡遵等攻東興，諸葛恪率軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-056-42', 'p0246', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，孫峻殺諸葛恪，遷據為驃騎將軍，平西宮事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-056-43', 'p0246', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '吳書曰：異又隨諸葛恪圍新城，城旣不拔，異等皆言宜速還豫章，襲石頭城，不過數日可拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-057-44', 'p0246', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '諸葛恪為丹楊太守，討山越，以平威重思慮，可與效力，請平為丞，稍遷武昌左部督，傾心接物，士卒皆為盡力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-45', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '又謂諸葛恪曰：「在我前者，吾必奉之同升；在我下者，則扶持之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-46', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '赤烏九年，遷立節中郎將，與諸葛恪換屯柴桑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-058-47', 'p0246', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '文士傳曰：陸景母張承女，諸葛恪外生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-48', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '是歲，立登為太子，選置師傅，銓簡秀士，以為賔友，於是諸葛恪、張休、顧譚、陳表等以選入，侍講詩書，出從騎射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-49', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '江表傳曰：登使侍中胡綜作賔友目曰：「英才卓越，超踰倫匹，則諸葛恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-50', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '諸葛恪才略博達，器任佐時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-51', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-52', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '四月，權薨，諸葛恪秉政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-059-53', 'p0246', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權薨，太傅諸葛恪不欲諸王處江濵兵馬之地，徙奮於豫章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-060-54', 'p0246', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '」及陸遜卒，諸葛恪代遜，權乃分武昌為兩部，岱督右部，自武昌上至蒲圻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-55', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛恪字元遜，瑾長子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-56', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '後蜀使至，群臣並會，權謂使曰：「此諸葛恪雅好騎乘，還告丞相，為致好馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-57', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '峻起如廁，解長衣，著短服，出曰：「有詔收諸葛恪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-58', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '先是，童謠曰：「諸葛恪，蘆葦單衣篾鉤落，於何相求成子閣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-59', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '伏念故太傅諸葛恪得承祖考風流之烈，伯叔諸父遭漢祚盡，九州鼎立，分託三方，並履忠勤，熈隆世業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-60', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '太元元年，權寢疾，詣都，留為太常，與諸葛恪等俱受遺詔輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-61', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '旣誅諸葛恪，遷丞相大將軍，督中外諸軍事，假節，進封富春侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-62', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛恪征東興，贊為前部，合戰先陷陣，大敗魏師，遷左將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-63', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '據御軍齊整，峻惡之，稱心痛去，遂夢為諸葛恪所擊，恐懼發病死，時年三十八，以後事付綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-64', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '初，峻從弟慮與誅諸葛恪之謀，峻厚之，至右將軍、無難督，授節蓋，平九官事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-65', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-064-66', 'p0246', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '評曰：諸葛恪才氣幹略，邦人所稱，然驕且吝，周公無觀，況在於恪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a04-065-67', 'p0246', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫亮即位，諸葛恪輔政，表曜為太史令，撰吳書，華覈、薛瑩等皆與參同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-001-68', 'p0246', 'jinshu', 'a05-001', '《晉書·卷一》', '先是，吳遣將諸葛恪屯皖，邊鄙苦之，帝欲自擊恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-001-69', 'p0246', 'jinshu', 'a05-001', '《晉書·卷一》', '四年秋九月，帝督諸軍擊諸葛恪，車駕送出津陽門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-002-70', 'p0246', 'jinshu', 'a05-002', '《晉書·卷二》', '五年夏五月，吳太傅諸葛恪圍新城，朝議慮其分兵以寇淮泗，欲戍諸水口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-002-71', 'p0246', 'jinshu', 'a05-002', '《晉書·卷二》', '帝曰：「諸葛恪新得政於吳，欲徼一時之利，并兵合肥，以冀萬一，不暇復為青徐患也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-013-72', 'p0246', 'jinshu', 'a05-013', '《晉書·卷十三》', '是月，宣帝討諸葛恪，恪棄城走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-013-73', 'p0246', 'jinshu', 'a05-013', '《晉書·卷十三》', '六月，宣帝討諸葛恪於皖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0246-a05-037-74', 'p0246', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時吳將諸葛恪圍新城，以孚進督諸軍二十萬防禦之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-048-0', 'p0247', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，權寢疾，徵大將軍諸葛恪為太子太傅，會稽太守滕胤為太常，並受詔輔太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-048-1', 'p0247', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '據、欽、咨等表薦衞將軍滕胤為丞相，綝不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-050-2', 'p0247', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '纂妻即滕胤女也，胤被誅，并遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-050-3', 'p0247', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '夫人立為皇后，以尚為城門校尉，封都亭侯，代滕胤為太常、衞將軍，進封永平侯，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-051-4', 'p0247', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '咨為滕胤所殺，儀為孫峻所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-051-5', 'p0247', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-052-6', 'p0247', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '吳錄曰：昭與孫紹、滕胤、鄭禮等，採周、漢，撰定朝儀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-059-7', 'p0247', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-060-8', 'p0247', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '始興太守羊衜與太常滕胤書曰：「鍾離子幹吾昔知之不熟，定見其在南海，威恩部伍，智勇分明，加操行清純，有古人之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-9', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」又問：「卿何如滕胤？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-10', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-11', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '未出路門，逢太常滕胤，恪曰：「卒腹痛，不任入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-12', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '吳歷曰：張約、朱恩密疏告恪，恪以示滕胤，胤勸恪還，恪曰：「峻小子何能為邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-13', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '始恪退軍還，聶友知其將敗，書與滕胤曰：「當人彊盛，河山可拔，一朝羸縮，人情萬端，言之悲歎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-14', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤字承嗣，北海劇人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-15', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤以恪子竦妻父辭位，峻曰：「鯀禹罪不相及，滕侯何為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-16', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時有媚峻者，以為大統宜在公族，若滕胤為亞公，聲名素重，衆心所附，不可貳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-17', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '唯滕胤諫止，不從，而功竟不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-18', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-19', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臣松之以為孫綝雖凶虐，與滕胤宿無嫌隙，胤若且順綝意，出鎮武昌，豈徒免當時之禍，仍將永保元吉，而犯機觸害，自取夷滅，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-20', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」休曰：「卿何以不徙滕胤、呂據？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-21', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0247-a04-064-22', 'p0247', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤厲脩士操，遵蹈規矩，而孫峻之時猶保其貴，必危之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-004-0', 'p0248', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，吳大將孫峻等衆號十萬至壽春，諸葛誕拒擊破之，斬吳左將軍留贊，獻捷于京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-1', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '戰敗走，晝夜間行，追者不及，遂得入吳，孫峻厚待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-2', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-028-3', 'p0248', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳大將軍孫峻等號十萬衆，將渡江，鎮東將軍諸葛誕遣艾據肥陽，艾以與賊勢相遠，非要害之地，輒移屯附亭，遣泰山太守諸葛緒等於黎漿拒戰，遂走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-048-4', 'p0248', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '武衞將軍孫峻伏兵殺恪於殿堂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-048-5', 'p0248', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '初為中書郎，孫峻使詰南陽王和，令其引分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-050-6', 'p0248', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '建興中，孫峻專政，公族皆患之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-050-7', 'p0248', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '搜神記曰：孫峻殺朱主，埋於石子岡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-051-8', 'p0248', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '咨為滕胤所殺，儀為孫峻所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-051-9', 'p0248', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-055-10', 'p0248', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏將文欽來降，以奉為虎威將軍，從孫峻至壽春迎之，與敵追軍戰於高亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-056-11', 'p0248', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，孫峻殺諸葛恪，遷據為驃騎將軍，平西宮事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-056-12', 'p0248', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '太平元年，帥師侵魏，未及淮，聞孫峻死，以從弟綝自代，據大怒，引軍還，欲廢綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-13', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '五鳳元年，英以大將軍孫峻擅權，謀誅峻，事覺自殺，國除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-14', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '權患之，謂侍中孫峻曰：「子弟不睦，臣下分部，將有袁氏之敗，為天下笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-15', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '吳書曰：權寢疾，意頗感寤，欲徵和還立之，全公主及孫峻、孫弘等固爭之，乃止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-059-16', 'p0248', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '及恪被誅，孫峻因此奪和璽綬，徙新都，又遣使者賜死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-17', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-18', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '時朝臣咸皆注意於恪，而孫峻表恪器任輔政，可付大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-19', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻因民之多怨，衆之所嫌，構恪欲為變，與亮謀，置酒請恪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-20', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」婢蹷然起躍，頭至于棟，攘臂切齒而言曰：「諸葛公乃為孫峻所殺！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-21', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」恪誅後，孫峻忌友，欲以為鬱林太守，友發病憂死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-22', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻字子遠，孫堅弟靜之曾孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-23', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫峻征淮南，授贊節，拜左護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-24', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '亮內嫌綝，乃推魯育見殺本末，責怒虎林督朱熊、熊弟外部督朱損不匡正孫峻，乃令丁奉殺熊於虎林，殺損於建業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-25', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '發孫峻棺，取其印綬，斲其木而埋之，以殺魯育等故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a04-064-26', 'p0248', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '滕胤厲脩士操，遵蹈規矩，而孫峻之時猶保其貴，必危之理也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0248-a05-002-27', 'p0248', 'jinshu', 'a05-002', '《晉書·卷二》', '孫峻猾夏，致寇徐方，戎車首路，威靈先邁，黃鉞未啟，鯨鯢竄迹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-0', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '孫綝以異戰不進，怒而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-1', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-028-2', 'p0249', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '況公今舉十餘萬之衆內附，而欽與全端等皆同居死地，父兄子弟盡在江表，就孫綝不欲，主上及其親戚豈肯聽乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-033-3', 'p0249', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '吳大將軍孫綝廢其主亮，立琅邪王休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-048-4', 'p0249', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '孫亮廢，己未，孫綝使宗正孫楷與中書郎董朝迎休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-050-5', 'p0249', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會孫綝廢亮為會稽王，後又黜為候官侯，夫人隨之國，居候官，尚將家屬徙零陵，追見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-050-6', 'p0249', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '損妻是峻妹也，孫綝益忌亮，遂廢亮，立休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-051-7', 'p0249', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-055-8', 'p0249', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '孫休即位，與張布謀，欲誅孫綝，布曰：「丁奉雖不能吏書，而計略過人，能斷大事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-056-9', 'p0249', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫綝秉政，大臣疑貳，績恐吳必擾亂，而中國乘釁，乃密書結蜀，使為并兼之慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-057-10', 'p0249', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫綝廢幼主，迎立琅邪王休。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-11', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '孫綝字子通，與峻同祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-12', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '臣松之以為孫綝雖凶虐，與滕胤宿無嫌隙，胤若且順綝意，出鎮武昌，豈徒免當時之禍，仍將永保元吉，而犯機觸害，自取夷滅，悲夫！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a04-064-13', 'p0249', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '江表傳曰：亮召全尚息黃門侍郎紀密謀，曰：「孫綝專勢，輕小於孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0249-a05-013-14', 'p0249', 'jinshu', 'a05-013', '《晉書·卷十三》', '」太平三年，孫綝盛兵圍宮，廢亮為會稽王，故國志又書於吳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-0', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬十月，以衞將軍濮陽興為丞相，廷尉丁密、光祿勳孟宗為左右御史大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-1', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '癸未，休薨，江表傳曰：休寢疾，口不能言，乃手書呼丞相濮陽興入，令子𩅦出拜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-048-2', 'p0250', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '左典軍萬彧昔為烏程令，與皓相善，稱皓才識明斷，是長沙桓王之疇也，又加之好學，奉遵法度，屢言之於丞相濮陽興、左將軍張布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-055-3', 'p0250', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '休薨，奉與丞相濮陽興等從萬彧之言，共迎立孫皓，遷右大司馬左軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-057-4', 'p0250', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '太守濮陽興正旦宴見掾吏，言次，問：「太守昔聞朱潁川問士於鄭召公，韓吳郡問士於劉聖博，王景興問士於虞仲翔，甞見鄭、劉二荅而未覩仲翔對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-064-5', 'p0250', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '濮陽興字子元，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0250-a04-064-6', 'p0250', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '濮陽興身居宰輔，慮不經國，協張布之邪，納萬彧之說，誅夷其宜矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0251-a04-051-0', 'p0251', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫翊字叔弼，權弟也，驍悍果烈，有兄策風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0251-a04-051-1', 'p0251', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '憲故孝廉媯覽、戴員亡匿山中，孫翊為丹楊，皆禮致之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-051-0', 'p0252', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫桓字叔武，河之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-058-1', 'p0252', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0252-a04-058-2', 'p0252', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '初，孫桓別討備前鋒於夷道，為備所圍，求救於遜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-003-0', 'p0253', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權入居巢湖口，向合肥新城，又遣將陸議、孫韶各將萬餘人入淮、沔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-1', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '孫韶又遣將高壽等率敢死之士五百人於徑路夜要之，帝大驚，壽等獲副車羽蓋以還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-2', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」夏五月，權遣陸遜、諸葛瑾等屯江夏、沔口，孫韶、張承等向廣陵、淮陽，權率大衆圍合肥新城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-047-3', 'p0253', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '未至壽春，權退還，孫韶亦罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-051-4', 'p0253', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '吳歷載翊妻徐節行，宜與媯覽等事相次，故列於後孫韶傳中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-056-5', 'p0253', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '曹休、張遼、臧霸等來伐，範督徐盛、全琮、孫韶等，以舟師拒休等於洞口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0253-a04-060-6', 'p0253', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '呂範、孫韶等入淮，全琮、朱桓趨合肥，諸葛瑾、步隲、朱然到襄陽，陸議、潘璋等討梅敷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0254-a04-047-0', 'p0254', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '蒙使人誘普，普降，盡得三郡將守，因引軍還，與孫皎、潘璋并魯肅兵並進，拒羽於益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0255-a04-060-0', 'p0255', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東主中營自掩石陽，別遣從弟孫奐治安陸城，脩立邸閣，輦貲運糧，以為軍儲，又命諸葛亮進指關西，江邊諸將無復在者，才留三千所兵守武昌耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-028-0', 'p0256', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽雖在他國，不能屈節下人，自呂據、朱異等諸大將皆憎疾之，惟峻常左右之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-028-1', 'p0256', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴大將孫峻、呂據、留贊等聞淮南亂，會文欽往，乃帥衆將欽徑至壽春；時誕諸軍已至，城不可攻，乃走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-047-2', 'p0256', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-048-3', 'p0256', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '閏月壬辰，峻及驃騎將軍呂據、左將軍留贊率兵襲壽春，軍及東興，聞欽等敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-048-4', 'p0256', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '八月，先遣欽及驃騎呂據、車騎劉纂、鎮南朱異、前將軍唐咨軍自江都入淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-051-5', 'p0256', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '及孫綝誅滕胤、呂據，據、胤皆壹之妹夫也，壹弟封又知胤、據謀，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-055-6', 'p0256', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '」及恪上岸，奉與將軍唐咨、呂據、留贊等，俱從山西上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-056-7', 'p0256', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '」乃遣呂據督二萬人，與異并力，至北界，欽果不降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-056-8', 'p0256', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-059-9', 'p0256', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-10', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '權疾困，召恪、弘及太常滕胤、將軍呂據、侍中孫峻，屬以後事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-11', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '恪遣將軍留贊、呂據、唐咨、丁奉為前部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-12', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '二年，魏將毌丘儉、文欽以衆叛，與魏人戰于樂嘉，峻帥驃騎將軍呂據、左將軍留贊襲壽春，會欽敗降，軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-13', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-14', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '呂據聞之大恐，與諸督將連名，共表薦滕胤為丞相，綝更以胤為大司馬，代呂岱駐武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-15', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '」休曰：「卿何以不徙滕胤、呂據？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0256-a04-064-16', 'p0256', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '休又下詔曰：「諸葛恪、滕胤、呂據蓋以無罪為峻、綝兄弟所見殘害，可為痛心，促皆改葬，各為祭奠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-057-0', 'p0257', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '休初即位，汜與賀邵、王蕃、薛瑩俱為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-058-1', 'p0257', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '故大司農樓玄、散騎中常侍王蕃、少府李勗，皆當世秀頴，一時顯器，旣蒙初寵，從容列位，而並旋受誅殛，或圮族替祀，或投棄荒裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-061-2', 'p0257', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '中常侍王蕃黃中通理，處朝忠謇，斯社稷之重鎮，大吳之龍逄也，而陛下忿其苦辭，惡其直對，梟之殿堂，尸骸暴棄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-3', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '王蕃字永元，廬江人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-4', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '丞相陸凱上疏曰：「常侍王蕃黃中通理，知天知物，處朝忠蹇，斯社稷之重鎮，大吳之龍逢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-5', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫皓即位，與王蕃、郭逴、萬彧俱為散騎中常侍，出為會稽太守，入為大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-6', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '故常侍王蕃忠恪在公，才任輔弼，以醉酒之間加之大戮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a04-065-7', 'p0257', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a05-011-8', 'p0257', 'jinshu', 'a05-011', '《晉書·卷十一》', '至吳時，中常侍廬江王蕃善數術，傳劉洪乾象歷，依其法而制渾儀，立論考度曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0257-a05-017-9', 'p0257', 'jinshu', 'a05-017', '《晉書·卷十七》', '中常侍王蕃以洪術精妙，用推渾天之理，以制儀象及論，故孫氏用乾象歷，至吳亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-048-0', 'p0258', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-058-1', 'p0258', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '故大司農樓玄、散騎中常侍王蕃、少府李勗，皆當世秀頴，一時顯器，旣蒙初寵，從容列位，而並旋受誅殛，或圮族替祀，或投棄荒裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-061-2', 'p0258', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '姚信、樓玄、賀卲、張悌、郭逴、薛瑩、滕脩及族弟喜、抗，或清白忠勤，或姿才卓茂，皆社稷之楨幹，國家之良輔，願陛下重留神思，訪以時務，各盡其忠，拾遺萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-3', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '樓玄字承先，沛郡蘄人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-4', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '臣夙夜思惟，諸吏之中，任幹之事，足委杖者，無勝於樓玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-5', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '乃共譖邵與樓玄謗毀國事，俱被詰責，玄見送南州，邵原復職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0258-a04-065-6', 'p0258', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-057-0', 'p0259', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '休初即位，汜與賀邵、王蕃、薛瑩俱為散騎中常侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-1', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '孫休即位，與賀邵、薛瑩、虞汜俱為散騎中常侍，皆加駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-2', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '後人誣白玄與賀邵相逢，駐共耳語大笑，謗訕政事，遂被詔詰責，送付廣州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-3', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '賀邵字興伯，會稽山陰人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0259-a04-065-4', 'p0259', 'sanguozhi', 'a04-065', '《三國志·吳書二十》', '評曰：薛瑩稱王蕃器量綽異，弘博多通；樓玄清白節操，才理條暢；賀邵厲志高潔，機理清要；韋曜篤學好古，博見羣籍，有記述之才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-005-0', 'p0260', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」韋昭云：「大行者，不反之辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-040-1', 'p0260', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」韋昭注曰：「璫，榱頭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-042-2', 'p0260', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '韋昭注國語曰：「有眸子而無見曰矇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-052-3', 'p0260', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」韋昭注云：「六柄，生、殺、貧、賤、富、貴也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-058-4', 'p0260', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '』」韋昭注曰：「燿，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-075-5', 'p0260', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '又聞孫堅得傳國璽，韋昭吳書曰：「漢室大亂，天子北詣河上，六璽不自隨，掌璽者以投井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-078-6', 'p0260', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」韋昭曰：「古者腐刑必熏合之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-078-7', 'p0260', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '節弟破石為越騎校尉，越騎營五百妻有美色，韋昭辯釋名曰：「五百字本為『伍』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-083-8', 'p0260', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '」韋昭注云：「側猶特也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-094-9', 'p0260', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」韋昭曰：「借民力以治之，以奉宗廟；且以勸率天下，使務農也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-099-10', 'p0260', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '韋昭曰：「古者穴居，故名室中為中霤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-100-11', 'p0260', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '」韋昭曰：「自下往觸之曰犯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-12', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」酈食其說曰「杜太行之道」，韋昭曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-13', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」韋昭曰：「戎來居此山，故號驪戎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-109-14', 'p0260', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '太史公曰「遷生龍門」，韋昭曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-112-15', 'p0260', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '」句踐欲遷吳王於甬東，韋昭曰縣東洲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-116-16', 'p0260', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '本注曰：成帝初置尚書四人，韋昭曰：「尚，奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a03-117-17', 'p0260', 'houhanshu', 'a03-117', '《二十四史-後漢書-志第二十七‧百官四》', '」韋昭曰：「長水校尉典胡騎，廄近長水，故以為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a04-001-18', 'p0260', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '君糾虔天刑，章厥有罪，「糾虔天刑」語出國語，韋昭注曰：「糾，察也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0260-a04-016-19', 'p0260', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韋昭國語註稱毛詩傳曰：「冥，契六世孫也，為夏水官，勤於其職而死於水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-025-0', 'p0262', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』逮鍾會為鎮西將軍，憲英謂從子羊祜曰：『鍾士季何故西出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-048-1', 'p0262', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '尚書僕射羊祜、尚書何楨並結縞帶之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-052-2', 'p0262', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '命車騎將軍羊祜、荊州刺史楊肇往赴救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-3', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '晉車騎將軍羊祜率師向江陵，諸將咸以抗不宜上，抗曰：「江陵城固兵足，無所憂患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-4', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '晉陽秋曰：抗與羊祜推僑、札之好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-5', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '漢晉春秋曰：羊祜旣歸，增脩德信，以懷吳人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a04-058-6', 'p0262', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '是以羊祜恢大同之略，思五兵之則，齊其民人，均其施澤，振義網以羅彊吳，明兼愛以革暴俗，易生民之視聽，馳不戰乎江表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-7', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '以中軍將軍羊祜為尚書左僕射，東莞王伷為尚書右僕射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-8', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '壬寅，以尚書左僕射羊祜都督荊州諸軍事，征東大將軍衞瓘都督青州諸軍事，東莞王伷鎮東大將軍、都督徐州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-9', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '吳將陸抗攻闡，遣車騎將軍羊祜帥衆出江陵，荊州刺史楊肇迎闡於西陵，巴東監軍徐胤擊建平以救闡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-10', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '以故太傅鄭沖、太尉荀顗、司徒石苞、司空裴秀、驃騎將軍王沈、安平獻王孚等及太保何曾、司空賈充、太尉陳騫、中書監荀勗、平南將軍羊祜、齊王攸等皆列於銘饗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-11', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '冬十月，以汝陰王駿為征西大將軍，平南將軍羊祜為征南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-003-12', 'p0262', 'jinshu', 'a05-003', '《晉書·卷三》', '立皇子瑋為始平王，允為濮陽王，該為新都王，遐為清河王，鉅平侯羊祜為南城侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-005-13', 'p0262', 'jinshu', 'a05-005', '《晉書·卷五》', '腹心不同，公卿異議，而獨納羊祜之策，杖王杜之決，役不二時，江湘來同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-013-14', 'p0262', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是時羊祜表求伐吳，上許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-019-15', 'p0262', 'jinshu', 'a05-019', '《晉書·卷十九》', '及晉國建，文帝又命荀顗因魏代前事，撰為新禮，參考今古，更其節文，羊祜、任愷、庾峻、應貞並共刊定，成百六十五篇，奏之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-16', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '羊祜字叔子，泰山南城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-17', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '人多諫抗，抗曰：「羊祜豈酖人者！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-18', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '故太傅、鉅平侯羊祜明德通賢，國之宗主，勳參佐命，功成平吳，而後嗣闕然，烝嘗莫寄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-19', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '時帝密有滅吳之計，而朝議多違，唯預、羊祜、張華與帝意合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-034-20', 'p0262', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」預旬月之中又上表曰：「羊祜與朝臣多不同，不先博畫而密與陛下共施此計，故益令多異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-full-21', 'p0262', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，帝潛與羊祜謀伐吳，而羣臣多以爲不可，唯華贊成其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-full-22', 'p0262', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-23', 'p0262', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，帝潛與羊祜謀伐吳，而羣臣多以爲不可，唯華贊成其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-036-24', 'p0262', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-25', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈以才望，顯名當世，是以創業之事，羊祜、荀勖、裴秀、賈充等，皆與沈諮謀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-26', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '顗上請羊祜、任愷、庾峻、應貞、孔顥共刪改舊文，撰定晉禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-27', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '會平，還洛，與裴秀、羊祜共管機密。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-039-28', 'p0262', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '勖以羊祜讓，乃固辭爲侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-29', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '帝甚信重充，與裴秀、王沈、羊祜、荀勖同受腹心之任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-30', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '太傅鄭沖，又與司空荀顗、中書監荀勖、中軍將軍羊祜、中護軍王業，及廷尉杜友、守河南尹杜預、散騎侍郎裴楷、潁川太守周雄、齊相郭頎、騎都尉成公綏荀煇、尚書郎柳軌等，典正其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-31', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '及羊祜等出鎮，充復上表欲立勳邊境，帝並不許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-040-32', 'p0262', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '先是羊祜密啟留充，及是，帝以語充。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-33', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '後參征南軍事，羊祜深知待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-34', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '車騎將軍羊祜雅知濬有奇略，乃密表留濬，於是重拜益州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0262-a05-042-35', 'p0262', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '先是，羊祜獲吳間諜，具知情狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-001-0', 'p0263', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」杜預注云：「內黃縣北有戲陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-002-1', 'p0263', 'houhanshu', 'a03-002', '《後漢書·卷二》', '帝生而豐下，杜預注左傳云：「豐下，蓋面方也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-002-2', 'p0263', 'houhanshu', 'a03-002', '《後漢書·卷二》', '」杜預注云：「物謂氣色災變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-003-3', 'p0263', 'houhanshu', 'a03-003', '《後漢書·卷三》', '」杜預注曰：「禁錮勿令仕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-005-4', 'p0263', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」杜預注云：「謂建巳之月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-009-5', 'p0263', 'houhanshu', 'a03-009', '《後漢書·卷九》', '杜預注左傳云「平旦，衆星皆沒，而孛星乃見」，故不言所在之次。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-010b-full-6', 'p0263', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '』」杜預注曰：「厲鬼，趙氏之先祖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-010b-full-7', 'p0263', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」杜預注曰：「懷胎為娠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-016-8', 'p0263', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '」杜預云：「河東大陽縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-017-9', 'p0263', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '杜預注春秋曰：「應國在襄城成父縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-023-10', 'p0263', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '臣融孤弱，介在其閒，杜預注左傳云「介猶閒也」。');
