INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-082-92', 'p0263', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '」杜預注云：「九州之伯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-083-93', 'p0263', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '杜預注左傳曰：「今河南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-94', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '渭南有驪戎，伊、洛閒有楊拒、泉皐之戎，杜預注左傳云：「楊拒，戎邑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-95', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '」杜預注云：「梁南有霍陽山，皆蠻子之邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-96', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '杜預注，戎侵魯，魯人不知，去乃追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-087-97', 'p0263', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '」杜預注曰：「陰地，河南山北，自上雒以東至陸渾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-089-98', 'p0263', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '杜預注左傳曰：「文馬，畫馬為文也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-090-99', 'p0263', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '其嫁娶則先略女通情，杜預注左傳曰：「不以道取為略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-090-100', 'p0263', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '」杜預注左傳曰：「疽，惡創也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-092-101', 'p0263', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '杜預長曆曰：「書稱『期三百六旬有六日，以閏月定四時成歲，允釐百工，庶績咸熙』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-094-102', 'p0263', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」杜預注曰：「藉稻，履行之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-094-103', 'p0263', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」杜預注曰：「鄅人藉稻，其君自出藉稻，蓋履行之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-098-104', 'p0263', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '杜預注傳曰：「雲物，氣色災變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-108-105', 'p0263', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '杜預曰：「曆家之說，謂日光以望時遙奪月光，故月蝕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-106', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二十九年「盟于狄泉」，杜預曰城內太倉西南池水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-107', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十六年「王宿褚氏」，杜預曰縣南有褚氏亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-108', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳周景王「崩于榮錡氏」，杜預曰鞏縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-109', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十二年單氏「伐東圉」，杜預曰縣東南有圉鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-110', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十三年晉師次于解，杜預曰縣西南有大解、小解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-111', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳定八年「單子伐穀城」，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-112', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」又有甘城，杜預曰縣西南有甘泉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-113', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳宣十二年楚潘黨逐魏錡及熒，杜預曰縣東熒澤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-114', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '卷左傳成十年晉鄭盟脩澤，杜預曰縣東有脩武亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-115', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳莊二十三年「盟于扈」，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-116', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '中牟左傳宣元年諸侯救鄭，遇于北林，杜預曰縣西南有林亭，在鄭北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-117', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳閔二年遇于清，杜預曰縣有清陽亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-118', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰管國也，在京縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-119', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '開封左傳哀十四年「逢澤有介麋」，杜預曰在縣東北，遠，疑 非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-120', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳宣元年諸侯會于棐林，杜預曰縣東南有林鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-121', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳成十六年諸侯遷於制田，杜預曰縣東有制澤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-122', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳襄十一年諸侯之師次于瑣，杜預曰縣東有瑣侯亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-123', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　緱氏左傳曰呂相絕秦伯，「殄滅我費、滑」，杜預曰滑國都於費，今緱氏縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-124', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳王取鄔、劉，杜預曰鄔在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-125', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「商湯有景亳之命」，杜預曰縣西南有湯亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-126', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十三年「單子取訾」，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-127', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左氏，周襄王出，國人納之坎埳，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-128', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭二十二年「王子猛居于皇」，杜預曰有黃亭，在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-129', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰「北制，一名虎牢」，亦即此縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-130', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰鄭子皮勞晉韓宣子于索氏，杜預曰縣東有大索城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-131', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '僖六年諸侯圍新城，杜預曰一名密縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-132', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預遺令曰：「山上有冢，或曰子產，邪東北向新鄭城，不忘本也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-133', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　新城左傳曰文十七年周敗戎于邥垂，杜預曰縣北有垂亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-134', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳昭十六年楚殺鄤子，杜預曰縣東南有蠻城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-135', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王取鄭隰城，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-136', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '傳又曰却至與周爭鄇田，杜預曰縣西南有鄇人亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-137', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '河陽左傳曰王與鄭盟，杜預曰縣南孟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-138', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '軹左傳曰王以蘇忿生田向與鄭，杜預曰縣西北地名向上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-139', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王與鄭原，杜預曰沁水西北有原城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-140', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰王與鄭絺，杜預曰在野王縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-141', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰古雍國，在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-142', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」杜預曰縣西北有攢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-143', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰定元年魏獻子田大陸，杜預曰西北吳澤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-144', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰襄二十三年「救晉，次雍榆」，杜預曰縣東有雍城是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-145', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰僖二十四年晉懷公死高梁，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-146', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰成七年諸侯盟馬陵，杜預曰衞地也，平陽東南地名馬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-147', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰晉改蒐于董，杜預曰縣有董亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-148', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰文十二年秦晉戰河曲，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-149', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '大陽，有吳山，上有虞城，杜預曰虞國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-150', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「秦伐晉，遂自茅津濟」，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-151', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '解左傳曰咎犯與秦晉大夫盟於郇，杜預曰縣西北有郇城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-152', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二十四年晉文公入桑泉，杜預曰在縣西二十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-153', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳文十二年秦侵晉及瑕，杜預曰猗氏縣東北有瑕城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-154', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳閔元年晉滅耿，杜預曰縣東南有耿鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-155', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖二年，晉荀息曰「兾為不道」，杜預曰國，在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-156', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰僖三十一年「晉蒐清原」，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-157', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '縣西有絳邑城，杜預曰故絳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-158', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳隱五年曲沃伐翼，杜預曰在縣東八十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-159', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳曰閔元年晉滅霍，杜預曰「縣東北有霍大山」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-160', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳襄元年晉討宋五大夫，寘諸瓠丘，杜預曰縣東南有壺丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-161', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '北屈左傳曰「二屈」，杜預曰「二」當為「北」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-162', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖八年晉敗狄于采桑，杜預曰縣西南有采桑津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-163', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '蒲子左傳曰晉文公居蒲城，杜預曰今蒲子縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-164', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '弘農故秦函谷關，左傳曰「虢公敗戎于桑田」，杜預曰在縣東北桑田亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-165', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜預曰虢都上陽，在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-166', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳僖十五年晉侯賂秦，東盡虢略，杜預曰從河曲南行，而東盡故虢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-167', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」杜預曰「畢國在西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-168', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '杜陵杜預曰古唐杜氏也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-169', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '〕杜預曰：「在鄠縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-170', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」　新豐，有驪山，杜預曰：「古驪戎國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-171', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '」左傳哀四年「將通於少習」，杜預曰少習，縣東之武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-172', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰哀四年楚右師軍蒼野，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-173', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳晉陰飴甥與秦伯盟王城，杜預曰後改為武鄉，在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-109-174', 'p0263', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '左傳曰「康有酆宮之朝」，杜預曰有靈臺，康王於是朝諸侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-175', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳曰「夏啟有鈞臺之享」，杜預曰有鈞臺陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-176', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成十七年衞侵鄭，至高氏，杜預曰縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-177', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十八年楚伐鄭，侵雍梁，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-178', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄城左傳定四年「盟皐鼬」，杜預曰縣東南有城皐亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-179', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十八年楚治兵於汾，杜預曰縣東北有汾丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-180', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳謂魚陵，杜預曰魚齒山也，在犨縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-181', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰縣西北有不羹亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-182', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　舞陽邑　郾　臨潁　潁陽　潁陰左傳文九年楚伐鄭，師於狼淵，杜預曰縣西有狼陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-183', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '許左傳莊二十八年楚伐鄭，鄭奔桐丘，杜預曰縣東北有桐丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-184', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '新汲左傳文元年衞孔達侵鄭，伐綿訾及匡，杜預曰縣東北有匡城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-185', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '成十七年伐鄭至曲洧，杜預曰縣治曲洧，城臨洧水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-186', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄十一年諸侯師于向，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-187', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳昭四年吳伐楚，入櫟，杜預曰縣東北有櫟亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-188', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成六年楚拒晉桑隧，杜預曰縣東有桑里亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-189', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '召陵左傳昭十三年楚蔡公與子干、子晳盟于鄧，杜預曰縣西南有鄧城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-190', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳僖四年齊伐楚，次陘，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-191', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄四年楚師繁陽，杜預曰鮦陽南有繁陽亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-192', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '春秋左氏傳僖二十一年宋盟鹿上，杜預曰原鹿縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-193', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰：「章華宮在華容縣城內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-194', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '下邑左傳哀七年築黍丘，杜預曰縣西南有黍丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-195', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '昭二十一年敗吳鴻口，杜預曰縣東南有鴻口亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-196', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳十二年楚伐宋，師楊梁，杜預曰有梁亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-197', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二十八年楚子玉夢河神謂己曰「吾賜汝孟諸之麋」，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-198', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二年齊侯盟貫，杜預曰縣西北有貰城，貰字與貫字相似。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-199', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳成十六年會沙隨，杜預曰縣北有沙隨亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-200', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰蒙縣西北有薄城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-201', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '相左傳桓十五年會於袲，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-202', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　酇左傳昭四年吳伐楚入棘，杜預曰縣東北有棘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-203', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄元年鄭侵宋，取犬丘，杜預曰縣東北有犬丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-204', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳曰「兾為不道，伐鄍三門」，服虔曰鄍，晉別都，杜預曰是虞邑，地處闕，則非此鄍矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-205', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」左傳僖元年會於檉，杜預曰縣西北有檉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-206', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '」　柘　新平　扶樂　武平左傳成十六年，諸侯侵陳鳴鹿，杜預曰縣西南有鹿邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-207', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳宋華氏戰于鬼閻，杜預曰縣西北有閻亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-208', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳宣十一年盟辰陵，杜預曰縣東南有辰亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-209', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '僖二十九年介葛盧舍于昌衍，杜預曰縣東南有昌平城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-210', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰：「大庭氏，古國名，在城內，魯於其處作庫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-211', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄四年戰狐台，杜預曰縣東南有目台亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-212', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳文公七年城郚，杜預曰縣南有郚鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-213', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '隱元年盟于蔑，杜預曰蔑，地名，縣南有姑城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-214', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '襄十七年齊圍桃，杜預曰縣東南有桃墟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-215', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '汶陽左傳桓十二年盟曲池，杜預曰縣北有曲水亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-216', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '繁陽　內黃左傳襄十九年會于柯，杜預曰縣東北有柯城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-217', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '昭九年荀盈卒于戲陽，杜預曰縣北有戲陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-218', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '魏　元城左傳成七年會馬陵，杜預曰縣東南有地名馬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-219', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳定七年盟于沙亭，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-220', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '黎陽左傳定十四年會于牽，杜預曰縣東北有牽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-221', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄三年諸侯會雞澤，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-222', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰縣西南有肥累城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-223', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳昭十二年晉荀吳入昔陽，杜預曰沾縣東有昔陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-224', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '望都左傳晉伐鮮虞及中人，杜預曰縣西北有中人城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-225', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成十六年衞伐鄭鳴鴈，杜預曰在雍丘縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-226', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三年次于滑，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-227', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄元年會鄫，杜預曰縣東南有鄫城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-228', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '外黃左傳「惠公季年，敗宋師于黃」，杜預曰宋邑，縣東有黃城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-229', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳桓十二年「盟于武父」，杜預曰縣東北有武父城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-230', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」左傳哀十三年盟黃池，杜預曰在封邱縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-231', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」　酸棗左傳鄭太叔至于廩延，杜預曰縣北有延津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-232', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄五年會城棣，杜預曰縣西南有棣城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-233', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖十五年會牡丘，次于匡，杜預曰匡在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-234', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '昭十三年會平丘，杜預曰縣西南有平丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-235', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成九年會于蒲，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-236', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖二十八年衞人盟宛濮，杜預曰近濮水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-237', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳宣二年鄭破宋師大棘，杜預曰在襄邑縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-238', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖五年齊侯會于首止，杜預曰在襄邑東南，有首鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-239', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」杜預曰：「戴在外黃東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-240', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '濮陽，古昆吾國，杜預曰古衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-241', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」左傳曰「衞，顓頊之墟」，杜預曰帝丘，昆吾氏因之，故曰昆吾之墟，縣城內有顓頊冢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-242', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳曰宣十二年盟清丘，杜預曰縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-243', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳曰定八年會于瓦，杜預曰縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-244', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「縣東南有韋城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-245', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '東阿左傳桓十年會于桃丘，杜預曰縣東南有桃城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-246', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄十四年孫林父敗衞侯于阿澤，杜預曰縣西南大澤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-247', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預注傳曰衞作新臺在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-248', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳文元年會于戚，鄭救晉中行氏，晉敗鄭鐵，杜預曰戚城南有鐵丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-249', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三十二年「城小穀」，杜預曰城中有管仲井。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-250', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又傳曰埋長狄榮如首於周首之北門，杜預曰縣東北有周首亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-251', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖二十六年追齊師至酅，杜預曰縣西有地名酅下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-252', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭二十五年臧會奔郈，杜預曰縣東南有郈鄉亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-253', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳桓十一年會于闞，杜預曰在須昌縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-254', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「須句，古國，在西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-255', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖三年會陽穀，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-256', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '亢父左傳襄十三年「取邿」，杜預曰縣有邿亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-257', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀六年「城邾瑕」，杜預曰縣北有邾瑕城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-258', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '紅亭在縣西北，杜預曰接宋、衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-259', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳定十年齊歸龜陰之田，杜預曰田在山北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-260', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成二年齊圍龍，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-261', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又楚有蜀之役，杜預曰縣西北有蜀亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-262', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱公「使營菟裘，吾將老焉」，杜預曰縣南有菟裘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-263', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '桓六年會于成，杜預曰縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-264', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳會于防，杜預曰在縣東南，有防城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-265', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄十九年城武城，杜預曰南城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-266', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀十四年司馬牛葬丘輿，杜預曰縣西北有輿城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-267', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱八年鄭歸祊，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-268', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '閔二年莒人歸共仲及密，杜預曰縣有密如亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-269', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十二年莒圍台，杜預曰縣南有台亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-270', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '盧左傳隱三年齊鄭尋盧之盟，杜預曰今縣故城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-271', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '成二年封銳司徒女石窌，杜預曰縣東有地名石窌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-272', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十八年齊禦晉平陰，塹防門，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-273', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又齊登巫山以望晉師，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-274', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰汶水北地有棘鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-275', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳「衞師入郕」，杜預曰東平剛父縣西南有郕鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-276', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳哀八年齊取闡，杜預曰在縣北，有闡鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-277', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三十二年遇于梁丘，杜預曰梁丘鄉在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-278', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰甲父，古國名，在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-279', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱十年「取防」，杜預曰縣西有防城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-280', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '鉅野左傳桓七年「焚咸丘」，杜預曰縣西有咸亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-281', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱元年費伯城郎，杜預曰縣東南有郁郎亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-282', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰茅鄉在昌邑西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-283', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄二十一年「邾庶其以漆、閭丘來奔」，杜預曰縣東北有漆鄉，西北有顯閭亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-284', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀七年囚邾子負瑕，杜預曰縣西北有瑕丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-285', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '方與，有武唐亭，左傳桓二年盟于唐，杜預曰在西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-286', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖七年盟甯母，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-287', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '三十一年臧文仲宿重館，杜預曰縣西北有重鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-288', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄二十六年「齊烏餘以廩丘奔晉」，杜預曰今縣故城是。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-289', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又「襲衞羊角取之」，杜預曰今縣所治城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-290', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又襲我高魚，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-291', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱七年「戎執凡伯於楚丘」，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-292', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱十年「取郜」，杜預曰縣東南有郜城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-293', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭三十一年邾黑肱以濫來奔，杜預曰縣所治，城東北有郳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-294', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '厚丘左傳成九年「城中城」，杜預曰在縣西南，有中鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-295', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳「齊伐莒，莒子奔紀鄣」，杜預曰縣東北有紀城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-296', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳哀三年城啟陽，杜預曰開陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-297', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱八年盟浮來，杜預曰邳來山之閒，號曰邳來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-298', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「東莞蒙陰縣西北有夷吾亭，或曰鮑叔解夷吾縛於此，因以為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-299', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」　諸左傳莊二十九年「城諸」，杜預曰諸縣在城陽郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-300', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又隱四年「莒人伐杞，取牟婁」，杜預曰縣東北有婁鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-301', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成八年申公巫臣會渠丘公，杜預曰縣有蘧丘里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-302', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳宣元年會于平州，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-303', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱六年盟于艾，杜預曰縣東南有艾山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-304', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '七年「城中丘」，杜預曰縣東北有中丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-305', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊九年盟于蔇，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-306', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '姑幕左傳昭五年「莒牟夷以牟婁及防茲來奔」，杜預曰縣東北有茲亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-307', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十年滅偪陽，杜預曰即此縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-308', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭十六年齊師至蒲隧，杜預曰縣東有蒲姑陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-309', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '著　於陵杜預曰縣西北有于亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-310', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '土鼓　梁鄒　鄒平　東朝陽杜預曰縣西有崔城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-311', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳哀十年「取犁及轅」，杜預曰縣西有轅城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-312', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭二十五年「齊侯唁公于野井」，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-313', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '古薄姑氏，杜預曰薄姑地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-314', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳齊侯田于貝丘，杜預曰縣南有地名貝丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-315', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊九年「戰于乾時」，杜預曰時水在縣界，岐流，旱則竭涸，故曰乾時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-316', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭五年「莒牟夷以牟婁及防、茲來奔」，杜預曰縣西南有防亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-317', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊元年齊遷紀郚，杜預曰朱虛縣東南有郚城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-318', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄六年圍棠，杜預曰棠國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-319', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄二十四年「伐莒，侵介根」，杜預曰縣東北計基城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-320', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳齊戍葵丘，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-321', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊元年齊所徙，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-322', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳鬬緡以權叛，楚遷於那處，杜預曰：縣東南有那口城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-323', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '當陽杜預曰縣東南有權城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-324', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '杜預曰縣西舊羅國，後徙枝江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-325', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳楚文王伐黃，還及湫，杜預曰縣東南有湫城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-326', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '杜預曰：「古䢵國，在東南，有䢵城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-327', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳楚公子比為王次魚陂，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-328', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '雲杜杜預曰縣東南有鄖城，故國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-329', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '浚遒左傳哀十二年會吳于橐皐，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-330', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳成七年吳入州來，杜預曰下蔡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-331', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄三年楚子伐吳，剋鳩茲，杜預曰在縣之東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-332', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭五年吳敗楚鵲岸，杜預曰縣有鵲尾渚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-333', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭二十三年吳敗諸侯之師于雞父，杜預曰縣南有雞備亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-334', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '又吳伐越，敗之夫椒，杜預曰太湖中椒山是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-335', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '烏程左傳襄三年楚伐吳至於衡山，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-336', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '曲阿　由拳左傳曰越敗吳於檇李，杜預曰縣南醉李城也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-337', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '杜預曰：「定安陰密縣，古密須國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-338', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '左傳哀四年齊伐晉壺口，杜預曰：「潞縣東有壺口關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-339', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '中都左傳昭二年執陳無宇於中都，杜預曰界休縣南中都城是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-119-340', 'p0263', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」杜預注左傳亦云「鸞在鑣，和在衡」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-119-341', 'p0263', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」杜預曰：「纓在馬膺前，如索帬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-120-342', 'p0263', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」杜預注左傳曰：「白與黑謂之黼，黑與青謂之黻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-120-343', 'p0263', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」杜預曰：「鞞，佩刀削上飾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-028-344', 'p0263', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」杜預言於衆曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-044-345', 'p0263', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會與維出則同轝，坐則同席，謂長史杜預曰：「以伯約比中土名士，公休、太初不能勝也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-048-346', 'p0263', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-347', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '辛卯，以尚書杜預都督荊州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-348', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，大舉伐吳，遣鎮軍將軍、琅邪王伷出涂中，安東將軍王渾出江西，建威將軍王戎出武昌，平西將軍胡奮出夏口，鎮南大將軍杜預出江陵，龍驤將軍王濬、廣武將軍唐彬率巴蜀之卒浮江而下，東西凡二十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-349', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '甲戌，杜預剋江陵，斬吳江陵督伍延；平南將軍胡奮剋江安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-350', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '杜預當鎮靜零、桂，懷輯衡陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-351', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-352', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '閏月，鎮南大將軍、當陽侯杜預卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-018-353', 'p0263', 'jinshu', 'a05-018', '《晉書·卷十八》', '當陽侯杜預著春秋長歷，說云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-018-354', 'p0263', 'jinshu', 'a05-018', '《晉書·卷十八》', '杜預又以為周衰世亂，學者莫得其真，今之所傳七歷，皆未必是時王之術也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-355', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '疾漸篤，乃舉杜預自代。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-356', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '望其碑者莫不流涕，杜預因名爲墮淚碑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-357', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '杜預字元凱，京兆杜陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-358', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '每大樹似癭，輒斫使白，題曰「杜預頸」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-359', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '杜預不有生知，用之則習，振長策而攻取，兼儒風而轉戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-360', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '徇以苟合，不求其正，以當代之元良，爲諸侯之庶子，檀弓習於變禮者也，杜預其有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-036-full-361', 'p0263', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-036-362', 'p0263', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-040-363', 'p0263', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '太傅鄭沖，又與司空荀顗、中書監荀勖、中軍將軍羊祜、中護軍王業，及廷尉杜友、守河南尹杜預、散騎侍郎裴楷、潁川太守周雄、齊相郭頎、騎都尉成公綏荀煇、尚書郎柳軌等，典正其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-040-364', 'p0263', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '杜預聞充有奏，馳表固爭，言平在旦夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-042-365', 'p0263', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '又杜預表請，帝乃發詔，分命諸方節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-042-366', 'p0263', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '初，詔書使濬下建平，受杜預節度，至秣陵，受王渾節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a03-013-0', 'p0264', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '干寶晉記曰：「吳王孫皓將其子瑾等，泥首面縛降王濬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-018-1', 'p0264', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '王濬在益州，受中制募兵討吳，無虎符，斆收濬從事列上，由此召斆還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-2', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-3', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '而王濬順流將至，司馬伷、王渾皆臨近境。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-4', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '壬申，王濬最先到，於是受皓之降，解縛焚櫬，延請相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-5', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：王濬治船於蜀，吳彥取其流柹以呈孫皓，曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-053-6', 'p0264', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '天紀四年，晉軍征皓，皓奉書於司馬伷、王渾、王濬請降，其文，瑩所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-058-7', 'p0264', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '天紀四年，晉軍伐吳，龍驤將軍王濬順流東下，所至輒克，終如抗慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-058-8', 'p0264', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '二月壬戌，晏為王濬別軍所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-9', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，大舉伐吳，遣鎮軍將軍、琅邪王伷出涂中，安東將軍王渾出江西，建威將軍王戎出武昌，平西將軍胡奮出夏口，鎮南大將軍杜預出江陵，龍驤將軍王濬、廣武將軍唐彬率巴蜀之卒浮江而下，東西凡二十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-10', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '二月戊午，王濬、唐彬等剋丹陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-11', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '三月壬寅，王濬以舟師至于建鄴之石頭，孫皓大懼，面縳輿櫬，降于軍門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-12', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-13', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '以鎮軍大將軍王濬為撫軍大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-14', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '庚子，撫軍大將軍、襄陽侯王濬卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-15', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '馬隆西伐，王濬南征，師不延時，獯虜削迹，兵無血刃，揚越為墟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-006-16', 'p0264', 'jinshu', 'a05-006', '《晉書·卷六》', '及吳之亡，王濬實先至建鄴，而皓之降款，遠歸璽於琅邪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-17', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」會益州刺史王濬徵爲大司農，祜知其可任，濬又小字阿童，因表留濬監益州諸軍事，加龍驤將軍，密令修舟楫，爲順流之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-18', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '歆遣軍出距王濬，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-19', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '王濬先列上得孫歆頭，預後生送歆，洛中以爲大笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-039-20', 'p0264', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及王濬表請伐吳，勖與賈充固諫不可，帝不從，而吳果滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-039-21', 'p0264', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '伐吳之役，紞領汝南太守，以郡兵隨王濬入秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-040-22', 'p0264', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '王濬之克武昌也，充遣使表曰：「吳未可悉定，方夏，江淮下溼，疾疫必起，宜召諸軍，以爲後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-23', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '既而王濬破石頭，降孫皓，威名益振。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-24', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '自以先據江上，破皓中軍，案甲不進，致在王濬之後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-25', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '以其父之故，每排王濬，時議譏焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-26', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '王濬字士治，弘農湖人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-27', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '案故撫軍王濬歷職內外，任兼文武，料敵制勝，明勇獨斷，義存社稷之利，不顧專輒之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-28', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '後與王濬共伐吳，彬屯據衝要，爲眾軍前驅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-0', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-1', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-2', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-3', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，皇甫嵩與黃巾戰於倉亭，獲其帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-4', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-5', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-6', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以皇甫嵩為左車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-7', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-8', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '北宮伯玉等寇三輔，遣左車騎將軍皇甫嵩討之，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-9', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，涼州賊王國圍陳倉，右將軍皇甫嵩救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-10', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '六年春二月，左將軍皇甫嵩大破王國於陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-11', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-12', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-13', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-14', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，皇甫嵩與黃巾戰於倉亭，獲其帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-15', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-16', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-17', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以皇甫嵩為左車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-18', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-19', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '北宮伯玉等寇三輔，遣左車騎將軍皇甫嵩討之，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-20', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，涼州賊王國圍陳倉，右將軍皇甫嵩救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-21', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '六年春二月，左將軍皇甫嵩大破王國於陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-22', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁未，征西將軍皇甫嵩為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-23', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '車騎將軍皇甫嵩為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-24', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十二月，太尉皇甫嵩免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-045-25', 'p0265', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '忠後代皇甫嵩為太尉，錄尚書事，以災異免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-048-26', 'p0265', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平二年，漢陽賊邊章、韓遂與羌胡為寇，東侵三輔，時遣車騎將軍皇甫嵩西討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-057-27', 'p0265', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '如是則南道斷絕，車騎之軍孤立，時湟中義從胡北宮伯玉等叛，遣左車騎將軍皇甫嵩討之不剋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-28', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後為護軍司馬，與左中郎將皇甫嵩俱討賊張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-29', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '皇甫嵩傳曰：「連結郡國，自青、徐、幽、兾、荊、楊、兖、豫八州之人，莫不畢應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-30', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時左將軍皇甫嵩精兵三萬屯扶風，勳密相要結，將以討卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-064-31', 'p0265', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及車騎將車皇甫嵩討平黃巾，盛稱植行師方略，嵩皆資用規謀，濟成其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-066-32', 'p0265', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '討擊黃巾別帥，大破之，與左中郎將皇甫嵩、右中郎將朱儁等受降數十萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-066-33', 'p0265', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '每三公缺，楊彪、皇甫嵩皆讓位於瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-34', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '皇甫嵩字義真，安定朝那人，度遼將軍規之兄子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-35', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '及黃巾起，公卿多薦儁有才略，拜為右中郎將，持節，與左中郎將皇甫嵩討潁川、汝南、陳國諸賊，悉破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-36', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '論曰：皇甫嵩、朱儁並以上將之略，受脤倉卒之時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-37', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-38', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '詔以卓為中郎將，副左車騎將軍皇甫嵩征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-39', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃拜卓前將軍，與左將軍皇甫嵩擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-40', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及靈帝寑疾，璽書拜卓為并州牧，令以兵屬皇甫嵩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-41', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '使皇甫嵩攻卓弟旻於郿塢，殺其母妻男女，盡滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-078-42', 'p0265', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '謂皇甫嵩、蔡雍等並被排也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-102-43', 'p0265', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '至中平元年，黃巾賊起，上遣中郎將皇甫嵩、朱儁等征之，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-44', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '靈帝紀曰：中平五年，徵卓為少府，勑以營吏士屬左將軍皇甫嵩，詣行在所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-45', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」六年，以卓為并州牧，又勑以吏兵屬皇甫嵩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-46', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '山陽公載記曰：初卓為前將軍，皇甫嵩為左將軍，俱征韓遂，各不相下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-47', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　張璠漢紀曰：卓抵其手謂皇甫嵩曰：「義真怖未乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-48', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉周忠、皇甫嵩，司徒淳于嘉、趙溫，司空楊彪、張喜等為公，皆辭拜讓瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-008-49', 'p0265', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：會西羌寇邊，皇甫嵩為征西將軍，表請武將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-010-50', 'p0265', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '九州春秋曰：中平元年，車騎將軍皇甫嵩旣破黃巾，威震天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-032-51', 'p0265', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '援亦少有名行，太尉皇甫嵩賢其才而以女妻之，丞相諸葛亮以援為祭酒，遷從事中郎，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-046-52', 'p0265', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '漢遣車騎將軍皇甫嵩、中郎將朱儁將兵討擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-0', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-1', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-2', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '」尚書盧植追讓、珪等，斬數人，其餘投河而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-3', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-4', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-5', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '」尚書盧植追讓、珪等，斬數人，其餘投河而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-035-6', 'p0266', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '以山東無足問者，乃西入關，因涿郡盧植，事扶風馬融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-039-7', 'p0266', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」盧植曰：「牆，載棺車箱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-054-8', 'p0266', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-060a-9', 'p0266', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '涿郡盧植，北海鄭玄，皆其徒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-10', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '吳祐　延篤　史弼　盧植　趙歧');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-11', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '盧植字子幹，涿郡涿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-12', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '告守令曰：「故北中郎將盧植，名著海內，學為儒宗，士之楷模，國之楨幹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-068-13', 'p0266', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」同志者乃共刻石立碑，蔡邕為其文，旣而謂涿郡盧植曰：「吾為碑銘多矣，皆有慙德，唯郭有道無愧色耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-069-14', 'p0266', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '尚書盧植執戈於閣道䆫下，仰數段珪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-069-15', 'p0266', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '公卿並出平樂觀，無得從者，唯尚書盧植夜馳河上，王允遣河南中部掾閔貢隨植後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-070-16', 'p0266', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-071-17', 'p0266', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-071-18', 'p0266', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-072-19', 'p0266', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中平元年，拜東中郎將，持節，代盧植擊張角於下曲陽，軍敗抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-072-20', 'p0266', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」尚書盧植獨曰：「昔太甲旣立不明，太甲，湯孫，太丁子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-073-21', 'p0266', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」後從涿郡盧植學於緱氏山中，略見書傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-080b-22', 'p0266', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '尚書盧植為之誄讚，以昭其懿德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-23', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注曰：「帝，天也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-24', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注禮記曰：「天子耕藉，一發九推耒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-25', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植曰：「藉，耕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-26', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注云：「玄鳥至時，陰陽中，萬物生，故於是以三牲請子於高禖之神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-27', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '盧植禮記注曰：「選三公老者為三老，卿大夫中之老者為五更，亦參五之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-095-28', 'p0266', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '盧植注曰：「角力，如漢家乘之，引關蹋踘之屬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-095-29', 'p0266', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」盧植禮記注云：「所以逐衰而迎新。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-097-30', 'p0266', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」盧植注曰：「封泰山，告太平，升中和之氣於天也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-097-31', 'p0266', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」盧植注曰：「配林，小山林麓配泰山者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-098-32', 'p0266', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」盧植注曰：「天宗，六宗之神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-099-33', 'p0266', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '」盧植曰：「諸主祭以土地為本也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-108-34', 'p0266', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '案：本傳盧植上書，丙子蝕自巳過午，旣蝕之後，雲霧晻曖，陳八事以諫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-114-35', 'p0266', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '盧植禮注曰：「如周小宰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-36', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「如大樂正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-37', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「如小樂正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-38', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '」盧植禮注曰：「大予令如古大胥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-39', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「大樂丞如古小胥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-40', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '董卓為東中郎將，盧植為北中郎將，獻帝以曹植為南中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-41', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '」案盧植禮注曰：「大行郎亦如謁者，兼舉形貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-118-42', 'p0266', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '盧植禮注曰：「計斷九月，因秦以十月為正故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-119-43', 'p0266', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」玄注禮含文嘉曰：「蓋旗有九名：日月為常，交龍為旂，通帛為旃，雜帛為物，熊虎為旗，鳥隼為旟，龜蛇為旐，全羽為旞，析羽為旌」盧植注禮記曰：「有鈴曰旂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-119-44', 'p0266', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」盧植禮記注曰：「軨，轄頭靼也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-006-45', 'p0266', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」尚書盧植曰：「案尚書太甲旣立不明，伊尹放之桐宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-006-46', 'p0266', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-022-47', 'p0266', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '太祖北征柳城，過涿郡，令告太守曰：「故北中郎將盧植，名著海內，學為儒宗，士之楷模，乃國之楨幹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-032-48', 'p0266', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」年十五，母使行學，與同宗劉德然、遼西公孫瓚俱事故九江太守同郡盧植。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-0', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '交阯刺史朱儁討交阯、合浦烏滸蠻，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-1', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-2', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-3', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-4', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '詔嵩討東郡，朱儁討南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-5', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '癸巳，朱儁拔宛城，斬黃巾別帥孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-6', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '交阯刺史朱儁討交阯、合浦烏滸蠻，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-7', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-8', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-9', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-10', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '詔嵩討東郡，朱儁討南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-11', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '癸巳，朱儁拔宛城，斬黃巾別帥孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-009-12', 'p0267', 'houhanshu', 'a03-009', '《後漢書·卷九》', '太尉周忠免，太僕朱儁為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-009-13', 'p0267', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月壬子，太尉朱儁免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-038-14', 'p0267', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '謝承書曰：「尚進善愛人，坐以待旦，擢門下書佐朱儁，恒嘆述之，以為有不凡之操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-045-15', 'p0267', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '吳書曰，忠字嘉謀，與朱儁共敗李傕於曹陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-048-16', 'p0267', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平元年，與中郎將朱儁擊黃巾賊於宛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-054-17', 'p0267', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '興平元年，代朱儁為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-058-18', 'p0267', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時河南尹朱儁為卓陳軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-066-19', 'p0267', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '討擊黃巾別帥，大破之，與左中郎將皇甫嵩、右中郎將朱儁等受降數十萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-20', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '於是發天下精兵，博選將帥，以嵩為左中郎將，持節，與右中郎將朱儁，共發五校、三河騎士及募精勇，合四萬餘人，嵩、儁各統一軍，共討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-21', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '會帝遣騎都尉曹操將兵適至，嵩、操與朱儁合兵更戰，大破之，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-22', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '朱儁字公偉，會稽上虞人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-23', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '論曰：皇甫嵩、朱儁並以上將之略，受脤倉卒之時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-24', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-072-25', 'p0267', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」擊破河南尹朱儁於中牟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-080b-26', 'p0267', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '靈帝時，從車騎將軍朱儁征黃巾，為別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-086-27', 'p0267', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '四年，刺史朱儁擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-102-28', 'p0267', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '至中平元年，黃巾賊起，上遣中郎將皇甫嵩、朱儁等征之，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-112-29', 'p0267', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '西鄂有精山，朱儁破孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-001-30', 'p0267', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '河間張超甞薦遺于太尉朱儁，稱遺「有冠世之懿，幹時之量。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-046-31', 'p0267', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '漢遣車騎將軍皇甫嵩、中郎將朱儁將兵討擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-046-32', 'p0267', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：堅為朱儁所表，為佐軍，留家著壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-053-33', 'p0267', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-009-0', 'p0268', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」壬子，曹操殺太中大夫孔融，夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-035-1', 'p0268', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '國相孔融深敬於玄，屣履造門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-035-2', 'p0268', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '玄唯有一子益恩，孔融在北海，舉為孝廉；及融為黃巾所圍，益恩赴難隕身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-054-3', 'p0268', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '將作大匠孔融聞之，不及朝服，往見操曰：獻帝春秋曰：「融見操曰：『刑之不濫，君之明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-054-4', 'p0268', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」孔融魯國男子，明日便當拂衣而去，不復朝矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-062-5', 'p0268', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '獻帝頗好文學，恱與彧及少府孔融侍講禁中，旦夕談論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-062-6', 'p0268', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '魏志曰「魯國孔融才高倨傲，年在羣、紀之閒，先與紀友，後與羣交，更為紀拜，由是顯名」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-064-7', 'p0268', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '光祿勳桓典、少府孔融上書薦之，於是就拜歧為太常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-066-8', 'p0268', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '辟荀爽、孔融等為從事，上除禁黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-9', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '孔融字文舉，魯國人，孔子二十世孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-10', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '避事之遼東，北海相孔融聞而竒之，數遣人訊問其母，并致餉遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-11', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」虞浦江表傳曰：「獻帝甞時見慮及少府孔融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-12', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」枉狀奏融曰：「少府孔融，昔在北海，見王室不靜，而招合徒衆，欲規不軌，云『我大聖之後，而見滅於宋，史記曰，魯大夫孟釐子曰：「孔丘，聖人之後，滅於宋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-13', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-071-14', 'p0268', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '彭城相汲廉、北海相孔融、沛相袁忠、太山太守應劭、汝南太守徐璆、前九江太守服虔、博士鄭玄等，敢言之行車騎將軍河南尹莫府：蔡質典職儀曰；「諸州刺史上郡并列卿府，言『敢言之』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-074-15', 'p0268', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '獻帝春秋曰：「使將作大匠孔融持節之鄴，拜太尉紹為大將軍，改封鄴侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-074-16', 'p0268', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '二年，使將作大匠孔融持節拜紹大將軍，錫弓矢節鉞，虎賁百人，禮含文嘉曰：「九錫一曰車馬，二曰衣服，三曰樂器，四曰朱戶，五曰納陛，六曰虎賁之士百人，七曰斧鉞，八曰弓矢，九曰秬鬯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-17', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '府掾孔融、王朗並修刺候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-18', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」唯善魯國孔融及弘農楊脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-19', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '孔融退而數之曰：「正平大雅，固當爾邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-20', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-21', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '臣松之以為楊彪亦曾為魏武所困，幾至於死，孔融竟不免於誅滅，豈所謂先行其言而後從之哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-22', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '虞溥江表傳曰：獻帝甞特見慮及少府孔融，問融曰：「鴻豫何所優長？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-004-23', 'p0268', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '玄別傳曰：「玄有子，為孔融吏，舉孝廉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-006-24', 'p0268', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三公並辟，歷豫州刺史，辟荀爽、孔融為從事，遷河南尹、尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-006-25', 'p0268', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遂北排田楷，東攻孔融，曜兵海隅，是時百姓無主，欣戴之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-26', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '唯少府孔融高貴其才，上書薦之曰：「淑質貞亮，英才卓犖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-27', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張衡文士傳曰：孔融數薦衡於太祖，欲與相見，而衡疾惡之，意常憤懣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-28', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融與康父端書曰：「前日元將來，淵才亮茂，雅度弘毅，偉世之器也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-29', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-30', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陳羣與孔融論汝、潁人物，羣曰：「荀文若、公達、休若、友若、仲豫，當今並無對。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-31', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '祈與孔融論肉刑，愔與孔融論聖人優劣，並在融集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-32', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初平中，北海孔融召以為主簿，守高密令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-33', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時孔融為北海相，舉原有道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-34', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時魯國孔融在郡，教選計當任公卿之才，乃以鄭玄為計掾，彭璆為計吏，原為計佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-35', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '孔融書曰：「隨會在秦，賈季在翟，諮仰靡所，歎息增懷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-36', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '初，太祖性忌，有所不堪者，魯國孔融、融字文舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-37', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '孔融魯國男子，明日便當褰衣而去，不復朝矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-38', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖懼遠近之議也，乃令曰：「太中大夫孔融旣伏其罪矣，然世人多採其虛名，少於核實，見融浮豔，好作變異，眩其誑詐，不復察其亂俗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-013-39', 'p0268', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孔融與朗書曰：「世路隔塞，情問斷絕，感懷增思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-40', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-41', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孔融體氣高妙，有過人者，然不能持論，理不勝辭，至于雜以嘲戲；及其所善，揚、班之儔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-42', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '及孔融有過，太祖使粹為奏，承指數致融罪，其大略言：「融昔在北海，見王室不寧，招合徒衆，欲圖不軌，言『我大聖之後也，而滅於宋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-022-43', 'p0268', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」魯國孔融高才倨傲，年在紀、羣之間，先與紀友，後與羣交，更為紀拜，由是顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-026-44', 'p0268', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-032-45', 'p0268', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」北海相孔融謂先主曰：「袁公路豈憂國忘家者邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-047-46', 'p0268', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '為孔融功曹，融稱曰「廊廟才也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-049-47', 'p0268', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '北海相孔融聞而奇之，數遣人訊問其母，并致餉遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-051-48', 'p0268', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '初，憲與少府孔融善，融憂其不免禍，乃與曹公書曰：「歲月不居，時節如流，五十之年，忽焉已至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-053-49', 'p0268', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孔融遺紘書曰：「聞大軍西征，足下留鎮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-053-50', 'p0268', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」紘旣好文學，又善楷篆，嘗與孔融書自耆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-057-51', 'p0268', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '翻與少府孔融書，并示以所著易注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-061-52', 'p0268', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '中郎將豫章徐宗，有名士也，甞到京師，與孔融交結，然儒生誕節，部曲寬縱，不奉節度，為衆作殿，濬遂斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-062-53', 'p0268', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '本姓氏，初為縣吏，後仕郡，郡相孔融嘲儀，言「氏」字「民」無上，可改為「是」，乃遂改焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a05-034-54', 'p0268', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜前母，孔融女，生兄發，官至都督淮北護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-0', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」鄭玄尚書中候注云：「日角謂庭中骨起，狀如日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-1', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '長一丈，大十圍，以為壘尉；鄭玄注周禮云：「軍壁曰壘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-2', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」鄭玄注云：「百辟，畿內諸侯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-3', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注云：「赤舄，為上冕服之舄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-4', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注論語云：「踧踖，敬恭貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-5', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注儀禮云：「酳，漱也，所以潔口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-6', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '夏四月戊子，詔曰：「昔歲五穀登衍，鄭玄注周禮云：「五穀，黍、稷、麥、麻、尗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-7', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '帝自御塤篪和之，鄭玄注周禮云：「塤，燒土為之，大如鴈子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-8', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「幽王在外，三公及諸侯隨而行者，皆無復君臣之禮，不肯晨夜省王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-9', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「福者，福賢者，謂爵祿之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-10', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「敦敦然道旁之葦，牧牛羊者無使踐履折傷之，況於人乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-11', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「太伯，周太王之長子，欲讓其弟季歷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-12', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「靡草，薺、亭歷之屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-13', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「大矣后稷之在其母懷也，終人道十月而生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-14', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」鄭玄云：「元，首也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-15', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」鄭玄注云：「雩，吁也，嗟而求雨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-16', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '鄭玄注云：「助老氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-17', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '鄭玄云：「婦使謂組紃之事」其賜人尤貧困、孤弱、單獨穀，人三斛；貞婦有節義十斛，甄表門閭，旌顯厥行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-006-18', 'p0269', 'houhanshu', 'a03-006', '《後漢書·卷六》', '」鄭玄注曰：「為死氣逆生氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-19', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「造，成也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-20', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「允，信也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-21', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「雲漢，天河也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-22', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注曰：「納其采擇之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-23', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注云：「士大夫已上，乃以玄纁束帛，天子加以穀圭，諸侯加以大璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-24', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注云：「左道，若巫蠱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-25', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注曰：「六宮之人，夫人以下，分居后之六宮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-26', 'p0269', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」鄭玄注曰：「六宮之人，夫人以下，分居后之六宮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-013-27', 'p0269', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '鄭玄注曰：「載，盟辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-015-28', 'p0269', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '」鄭玄注云：「痟，酸削也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-015-29', 'p0269', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '」鄭玄注云：「妄之言望，人所望宜正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-016-30', 'p0269', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '諸羌激忿，遂相與解仇結婚，交質盟詛，鄭玄注周禮云：「大事曰盟，小事曰詛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-021-31', 'p0269', 'houhanshu', 'a03-021', '《後漢書·卷二十一》', '」鄭玄注曰：「春秋以禮會民於州序也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-022-32', 'p0269', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '」鄭玄注云：「黃者，火之子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-023-33', 'p0269', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '」鄭玄注云：「光明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-34', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '」鄭玄云：「俑，偶人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-35', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '」鄭玄曰：「敬父同志如事父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-36', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '巽下震上，鄭玄注云：「巽為進退，不恒其德之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-025-37', 'p0269', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '」鄭玄注禮記云：「申之氣乘之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-38', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」鄭玄曰：「在旁曰帷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-39', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」鄭玄云：「所以廣敬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-40', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '鄭玄云「恂恂，恭順貌」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-41', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '故月令「仲秋之月養衰老，授几杖，行糜粥飲食」，鄭玄注云「助老氣也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-029-42', 'p0269', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '」鄭玄注云：「陳詩謂采其詩而示之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-029-43', 'p0269', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '誠不欲聖朝行誹謗之誅，以傷晏晏之化，鄭玄注尚書考靈耀云：「道德純備謂之塞，寬容覆載謂之晏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-031-44', 'p0269', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '」鄭玄注禮記曰：「瞀，目不明之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-033-45', 'p0269', 'houhanshu', 'a03-033', '《後漢書·卷三十三》', '張豐狂悖，姦黨日增，連年拒守，吏士疲勞，甲冑生蟣蝨，弓弩不得㢮，鄭玄注周禮曰：「㢮，釋下也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-034-46', 'p0269', 'houhanshu', 'a03-034', '《後漢書·卷三十四》', '」鄭玄注云：「畜，起也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-034-47', 'p0269', 'houhanshu', 'a03-034', '《後漢書·卷三十四》', '兾亦改易輿服之制，作平上軿車，鄭玄注周禮云：「軿猶屏也，所用自蔽隱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-48', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '」鄭玄注曰：「謂巡守至於方嶽，燔柴祭天，告以諸侯之成功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-49', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄注云：「言武王受此萬年之壽，輔佐之臣亦宜蒙餘福也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-50', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄字康成，北海高密人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-51', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄別傳曰「玄年十一二，隨母還家，正臘會同列十數人，皆美服盛飾，語言閑通，玄獨漠然如不及，母私督數之，乃曰『此非我志，不在所願』」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-52', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄括囊大典，網羅衆家，括，結也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-037-53', 'p0269', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '鄭玄注云：「太伯，周太王之長子，次子仲雍，次子季歷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-038-54', 'p0269', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '鄭玄注禮記云：「圓曰簞，方曰笥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-038-55', 'p0269', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '鄭玄注禮記云：「天子九門：路門也，應門也，雉門也，庫門也，皐門也，國門也，近郊門也，遠郊門也，關門也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-56', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「辯，別也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-57', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「詳，審察之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-58', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「諸公三重，諸侯再重，大夫一重，士不重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-59', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注云：「方猶道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-60', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注曰：「顯，光也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-61', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注周禮云「天子城十二門，通十二子」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-62', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注禮記曰：「廛，市物邸舍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-63', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「肆，市中陳物處也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-64', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「澤無水曰藪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-65', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」周禮夏后氏「世室九階」，鄭玄注云「南面三階，三面各二」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-66', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注云：「我敎告王，口語諄諄然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-67', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注禮記曰：「狡，疾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-68', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '罘罔連紘，籠山絡野，鄭玄注禮記曰：「獸罟曰罘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-69', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「結繳於矢謂之矰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-70', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注禮記曰：「土高曰臺，有木曰榭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-71', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注曰：「鑾在衡，和在軾，皆金鈴也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-72', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注詩云：「鷖，鳧屬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-041-73', 'p0269', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '」鄭玄云：「危猶高也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-74', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '鄭玄注周禮曰：「淺絳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-75', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄注云：「木性或曲或直，人所用為器者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-76', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄云：「副，婦人首服，三輔謂之假紒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-77', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄注云：「撙，趨也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-78', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」鄭玄注曰：「大道，謂三皇、五帝時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-79', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」當今中官近習，鄭玄注禮記云：「近習，天子所親幸者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-80', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '臣雖斗筲之人，鄭玄注論語：「筲，竹器，容斗二升。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-044-81', 'p0269', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '鄭玄注論語曰：「諒闇謂凶廬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-044-82', 'p0269', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '」鄭玄注云：「岐岐然意有所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-045-83', 'p0269', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '及竇氏敗，酺乃上疏曰：「臣實愚惷，鄭玄注周禮云：「惷愚，癡騃也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-046-84', 'p0269', 'houhanshu', 'a03-046', '《後漢書·卷四十六》', '」鄭玄注云：「禮篇多亡，本數未聞，其中事儀有三千也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-047-85', 'p0269', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '』」鄭玄注曰：「正丘首，正首丘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-048-86', 'p0269', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '鄭玄注云：「無所不至謂諂佞邪媚，無所不為也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-048-87', 'p0269', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '鄭玄注周禮曰：「水涯曰濆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-88', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '鄭玄注云：「極，中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-89', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '鄭玄注云：「空府臧則傷財，力役繁則害人，二者奢泰之所致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-90', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注云：「中饋，酒食也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-91', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注曰：「逢猶大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-92', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注禮記曰：「綸，今有秩、嗇夫所佩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-93', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注云：「葛屨賤，皮屨貴，魏俗至冬猶葛屨，可用履霜，利其賤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-94', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '鄭玄注云：「東方曰𩎟，南方曰任，西方曰朱離，北方曰禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-95', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」鄭玄注云：「鎬、方皆北方地名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-96', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」鄭玄注論語云：「匹夫之守志，重於三軍之死將者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-97', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」鄭玄云：「艮為手，手上肩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-98', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」鄭玄云：「謂飾其容而見於外曰冶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-99', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '鄭玄注易乾鑿度曰：「陽起於子，陰起於午，天數大分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-053-100', 'p0269', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '今潁川荀爽載病在道，北海鄭玄北面受署。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-101', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「二為陰爻，得正於內；五，陽爻也，得正於外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-102', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注云：「敎周宣王求賢人之未仕者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-103', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注云：「小亦於東，大亦於東，言賦斂多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-104', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「霓，邪氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-105', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「祥，吉也，言其漸即吉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-106', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注禮記曰：「緌，冠飾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-107', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注云：「壞滅之國，徵人起屋舍，築牆壁，百堵同時而起，言趨事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-108', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '鄭玄注云：「傷今不如古也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-109', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注云：「審諦於物也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-110', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注：「七人謂三公及前疑、後承、左輔、右弼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-111', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '鄭玄注云：「虺、蛇冗處，陰之祥也，故為生女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-112', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「兩書一札，同而別之，長曰質，短曰劑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-113', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '鄭玄注云：「人皆涉，我友未至，我獨待而不涉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-114', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「結繳於矢謂之矰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-115', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「太一者，北辰神名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-116', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「鞶，小囊，盛帨巾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-117', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '鄭玄注禮記云：「蹶，行處之貌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-118', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「舟，載度物者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-119', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '鄭玄注云：「澤無水曰藪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-120', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注曰：「燿，讀曰哨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-121', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '鄭玄注周禮曰「捎，除也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-122', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注云：「靈沼之水，魚盈滿其中也，皆以跳躍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-123', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注云：「房謂足下跗也，有似於堂房矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-124', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '涿郡盧植，北海鄭玄，皆其徒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-061-125', 'p0269', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '」鄭玄云：「如今三月上巳，水上之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-061-126', 'p0269', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '鄭玄注云：不為夷、齊之清，不為惠、連之屈，故曰異於是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-062-127', 'p0269', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '論曰：荀爽、鄭玄、申屠蟠俱以儒行為處士，累徵並謝病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-062-128', 'p0269', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '」鄭玄注曰：「懿，美也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-063-129', 'p0269', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '」鄭玄注曰：「稽，同也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-130', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '鄭玄注論語曰「謂年十五已上」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-131', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '少與鄭玄俱事馬融，能通古今學，好研精而不守章句。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-132', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」鄭玄注云：「骨曰切，象曰磋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-133', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '脩禮者，應徵有道之人，若鄭玄之徒，陳明洪範，攘服災咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-134', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」鄭玄注曰：「逢猶大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-135', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」鄭玄注云：「蕩蕩，法度廢壞之貌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-136', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」鄭玄注云：「方叔先與吉甫征伐玁狁，今特往伐蠻荊，皆使來服於宣王之威，美其功之多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-137', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '行春到高密縣，見鄭玄為鄉佐，知其異器，即召署郡職，遂遣就學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-138', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '鄭玄注周禮曰：「木在足曰桎，在手曰梏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-068-139', 'p0269', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」鄭玄注曰：「倫猶類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-068-140', 'p0269', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '鄭玄注云：「不仁之人，當以風化之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-141', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '東州鄭玄學該古今，玄，北海人，故云東州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-142', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '稍復鳩集吏民為黃巾所誤者男女四萬餘人，更置城邑，立學校，表顯儒術，薦舉賢良鄭玄、彭璆、邴原等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-143', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」案表跋扈，擅誅列侯，遏絕詔命，斷盜貢篚，鄭玄注儀禮曰：「篚，竹器如筐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-144', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」鄭玄注：「畿，限也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-145', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '山陽郗慮承望風旨，續漢書：「慮字鴻豫，山陽高平人，少受學於鄭玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-146', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '昔國家東遷，文舉盛歎鴻豫名實相副，綜達經學，出於鄭玄，又明司馬法，史記，齊威王使大夫追論古者司馬法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-147', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」鄭玄注曰：「懿伯，惠伯之叔父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-148', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '今鑾駕旋軫，鄭玄注周禮曰：「軫，輿後橫木也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-071-149', 'p0269', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '彭城相汲廉、北海相孔融、沛相袁忠、太山太守應劭、汝南太守徐璆、前九江太守服虔、博士鄭玄等，敢言之行車騎將軍河南尹莫府：蔡質典職儀曰；「諸州刺史上郡并列卿府，言『敢言之』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-071-150', 'p0269', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」鄭玄注云：「鞠，告也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-072-151', 'p0269', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」鄭玄注云：「蕩蕩，法度廢壞之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-074-152', 'p0269', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」鄭玄注周禮曰：「軿猶屏也，取其自蔽隱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-074-153', 'p0269', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」鄭玄注曰：「槐之言懷也，言懷來人於此欲與謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-076-154', 'p0269', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '」鄭玄注云：「愛蠶食也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-155', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注云：「中門，於外內為中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-156', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注月令云：「奄尹，主領奄豎之官者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-157', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注云：「荊、楊之州，貢金三品。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-158', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '鄭玄注云：「謂所殺者之左耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-159', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '陰陽乖剌，稼穡荒蔬，鄭玄注周禮云：「蔬，草有實者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-079-160', 'p0269', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '融授鄭玄，玄作易注，荀爽又作易傳，自是費氏興，而京氏遂衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-079-161', 'p0269', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '扶風杜林傳古文尚書，林同郡賈逵為之作訓，馬融作傳，鄭玄注解，由是古文尚書遂顯于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080-162', 'p0269', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '」鄭玄注曰：「謂刻其身以丹青涅之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080-163', 'p0269', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '」鄭玄注云：「燔魚以祭，變禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-164', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注云：「文昌中星。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-165', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注云：「小而柄長謂之罼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-166', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注禮記曰：「絞，蒼黃之色也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-081-167', 'p0269', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '鄭玄注云：「明者，神明之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-081-168', 'p0269', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '」鄭玄注儀禮云：「如今著幓頭，自項中而前，交額上，却繞髻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-169', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '』」鄭玄注云：「明素恭肅於鬼神，且順子路之言也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-170', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '鄭玄注云：「由，從也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-171', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '」鄭玄注「詩敦厚，近愚；書知遠，近誣」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-172', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '清白有節，博學善交，與鄭玄、陳紀等相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-083-173', 'p0269', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '鄭玄注禮記曰：「恇恇，恐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-084-174', 'p0269', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '霸子時方耕於野，聞賔至，投耒而歸，鄭玄注禮記云：「耒，耜之上曲者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-086-175', 'p0269', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '」鄭玄曰：「鍭猶候也，候物而射之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-087-176', 'p0269', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '鄭玄注云：「不仁之人，當以風化之，疾之已甚，是又使之為亂行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-090-177', 'p0269', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '鄭玄注周禮曰：「毛之縟細者為毳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-091-178', 'p0269', 'houhanshu', 'a03-091', '《二十四史-後漢書-志第一‧律曆上》', '鄭玄曰：「宮數八十一，黃鍾長九寸，九九八十一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-179', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '鄭玄注周禮曰：「天子三推，公五推，卿、諸侯九推，庶人終於千畝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-180', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄曰：「藉之言借也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-181', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注云：「弗之言祓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-182', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注禮記曰：「後王以為禖官嘉祥，而立其祠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-183', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注禮記曰：「皆年老更事致仕者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-184', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '鄭玄注儀禮曰「狗取擇人」，孟冬亦如之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-185', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '』」鄭玄注鄉飲酒禮曰：「今郡國十月行鄉飲酒禮，黨正每歲邦索鬼神而祭祀，則以禮屬民而飲酒于序，以正齒位之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-095-186', 'p0269', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」鄭玄曰：「䍿，赤皁染羽為之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-095-187', 'p0269', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '鄭玄注曰：「此謂民給傜役，若今衞士矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-188', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「夷之言尸也，實冰於槃中，置之尸床之下，所以寒尸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-189', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「以斂尸者，以大斂焉加之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-190', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄注曰：「袵，小腰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-191', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「方相，放想也，可畏怖之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-192', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄注旣夕曰：「陳明器，以西行南端為上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-193', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」筲八盛，容三升，鄭玄注旣夕曰：「筲，畚種類也，其容蓋與簋同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-194', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注旣夕曰：「屑，薑桂之屑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-195', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「翭猶候也，候物而射之矢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-196', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '巵八，牟八，鄭玄注旣夕曰：「牟，盛湯漿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-197', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注旣夕曰：「槃匜，盥器也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-198', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「不懸之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-199', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注禮記曰：「芻靈，東茅為人馬，謂之芻靈，神之類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-097-200', 'p0269', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」鄭玄曰：「猶，圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-201', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」鄭玄曰：「明堂者，明政敎之堂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-202', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '孝經云「宗祀文王於明堂以配上帝」，故鄭玄曰「上帝者，天之別名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-203', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」鄭玄曰：「六宗，星、辰、司中、司命、風伯、雨師也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-099-204', 'p0269', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '大司農鄭玄說古者官有大功，則配食其神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-205', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '五行傳曰：「田獵不宿，鄭玄注尚書大傳曰：「不宿，不宿禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-206', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」飲食不享，鄭玄曰：「享，獻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-207', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」注五行稱「鄭玄曰」，皆出注大傳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-208', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」出入不節，鄭玄曰：「角為天門，房有三道，出入之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-209', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」奪民農時，鄭玄曰：「房、心，農時之候也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-210', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」及有姦謀，鄭玄曰：「亢為朝廷，房、心為明堂，謀事出政之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-211', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「君行此五者，為逆天東宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-212', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥咎狂，鄭玄曰：「君臣不敬，則倨慢如狂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-213', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥罰恒雨，鄭玄曰：「貌曰木，木主春，春氣生；生氣失則踰其節，故常雨也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-214', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有服妖，鄭玄曰：「服，貌之飾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-215', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有龜孽，鄭玄曰：「龜蟲之生於水而游於春者，屬木。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-216', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有雞禍，鄭玄曰：「雞畜之有冠翼者也，屬貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-217', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有下體生上之痾，鄭玄曰：「痾，病也，貌氣失之病也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-218', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有青眚、青祥，鄭玄曰：「青，木色也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-219', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「沴，殄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-220', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「自正月盡四月為歲之朝，自五月盡八月為歲之中，自九月盡十二月為歲之夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-221', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「二辰謂曰、月也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-222', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '五行傳曰：「好攻戰，鄭玄注曰：「參、伐為武府，攻戰之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-223', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」輕百姓，鄭玄注曰：「輕之者，不重民命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-224', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」飾城郭，鄭玄注曰：「昴、畢閒為天街。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-225', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」侵邊境，鄭玄曰：「畢主邊兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-226', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄注曰：「君行此四者，為逆天西宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-227', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥咎僭，鄭玄曰：「君臣不治，則僭差矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-228', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥罰恒陽，鄭玄曰：「金主秋，秋氣殺，殺氣失，故常陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-229', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '鄭玄曰：「殺氣失，故於人為憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-230', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有詩妖，鄭玄曰：「詩之言志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-231', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有介蟲之孽，鄭玄曰：「蝝、螽、蜩、蟬之類，生於火而藏於秋者也，屬金。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-232', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有犬禍，鄭玄曰：「犬畜之以口吠守者，屬言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-233', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有口舌之痾，鄭玄曰：「言氣失之病。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-234', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '五行傳曰：「棄法律，鄭玄注尚書大傳曰：「東井主法令也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-235', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」逐功臣，鄭玄曰：「功臣制法律者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-236', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」殺太子，鄭玄曰：「五行火生土，天文以參繼東井，四時以秋代夏，殺太子之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-237', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '』」以妾為妻，鄭玄曰：「軒轅為后妃，屬南宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-238', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」鄭玄曰：「君行此四者，為逆天南宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-239', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」鄭玄曰：「君臣不瞭則舒緩矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-240', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」厥罰常燠，鄭玄曰：「視曰火，火主夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-241', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '鄭玄曰：「長氣失，故於人為疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-242', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有草妖，鄭玄曰：「草，視之物可見者，莫衆於草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-243', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有蠃蟲之孽，鄭玄曰：「蠶螟蟲之類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-244', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有羊禍，鄭玄曰：「羊畜之遠視者也，屬視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-245', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '五行傳曰：「簡宗廟，不禱祠，鄭玄注曰：「虛、危為宗廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-246', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」廢祭祀，鄭玄曰：「牽牛主祭祀之牲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-247', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」逆天時，鄭玄曰：「月在星紀，周以為正，月在玄枵，殷以為正，皆不得四時之正，逆天時之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-248', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」鄭玄曰：「君行此四者，為逆天北宮之政也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-249', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '鄭玄曰：「君聽不聦，則是不能謀其事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-250', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」厥咎急，鄭玄曰：「君臣不謀則急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-251', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」厥罰恒寒，鄭玄曰：「聽曰水，水主冬，冬氣藏，藏氣失，故常寒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-252', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '鄭玄曰：「藏氣失，故於人為貧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-253', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有鼓妖，鄭玄曰：「鼓聽之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-254', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有魚孽，鄭玄曰：「魚，蟲之生水而游於水者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-255', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有豕禍，鄭玄曰：「豕，畜之居閑衞而聽者也，屬聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-256', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有耳痾，鄭玄曰：「聽氣失之病。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-257', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '鄭玄曰：「瞀與思心之咎同耳，故傳曰眊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-258', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」厥罰恒陰，鄭玄曰：「王極象天，天陰養萬物，陰氣失，故常陰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-259', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '鄭玄曰：「天為剛德，剛氣失，故於人為弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-260', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有射妖，鄭玄曰：「射，王極之度也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-261', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有龍蛇之孽，鄭玄曰：「龍，蟲之生於淵，行於無形，遊於天者也，屬天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-262', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有馬禍，鄭玄曰：「天行健。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-263', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有下人伐上之痾，鄭玄曰：「夏侯勝說『伐』宜為『代』，書亦或作『代』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-264', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」鄭玄曰：「亂謂薄食鬬並見，逆謂贏縮反明，經天守舍之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-109-265', 'p0269', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '鄭玄詩譜曰：「周公攝政五年，成王宅雒邑，使邵公先相宅，旣成，謂之王城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-109-266', 'p0269', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '鄭玄詩譜曰：「豳者，公劉自邰而出，所徙戎狄之地名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-110-267', 'p0269', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '禹貢有外方山，鄭玄毛詩譜云外方之山即嵩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-112-268', 'p0269', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三齊記曰：「鄭玄敎授不其山，山下生草大如䪥，葉長一尺餘，堅刃異常，土人名曰康成書帶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-113-269', 'p0269', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」鄭玄曰：「西在隴西之西，今謂之八充山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-113-270', 'p0269', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '禮記曰趙武從先大夫於九京，鄭玄曰「晉卿大夫之墓地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-114-271', 'p0269', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」前書曰「秦官」，鄭玄注月令亦曰「秦官」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-116-272', 'p0269', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '周禮天官有司會，鄭玄曰「若今尚書」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-118-273', 'p0269', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '」鄭玄曰：「王者存二代而封及五，郊天用天子禮以祭其始祖，行其正朔，此謂通三統也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-274', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄注禮記曰：「此皆天子之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-275', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄曰：「此皆諸侯之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-276', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄曰：「取幹以冬，取角以秋，絲漆以夏，筋膠未聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-277', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」自此至弧旌枉矢，皆出周禮，「鄭玄曰」即是周禮注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-278', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '輿方法地，蓋圓象天；三十輻以象日月；鄭玄曰：「輪象日月者，以其運行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-279', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」蓋弓二十八以象列星；龍旂九斿，七仞齊軫，鄭玄曰：「軫謂車後橫木。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-280', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」以象大火；鄭玄曰：「交龍為旂，諸侯之所建也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-281', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鳥旟七斿，五仞齊較，鄭玄曰：「較者，車高檻木也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-282', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」以象鶉火；鄭玄曰：「鳥隼為旟，州里之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-283', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」熊旗六斿，五仞齊肩，以象參、伐；鄭玄曰：「熊虎為旗，師都之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-284', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」龜旐四斿，四仞齊首，以象營室；鄭玄曰：「龜蛇為旐，縣鄙之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-285', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」弧旌枉矢，以象弧也：鄭玄曰：「覲禮曰『侯氏載龍旂弧韣』，則旌旗之屬皆有弧也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-286', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「王在焉曰路，以玉飾諸末也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-287', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鍚樊纓十有再就，鄭玄曰：「鍚面當盧刻金為之，所謂鏤鍚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-288', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「纓，今馬鞅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-289', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「七尺為仞，天子之旗高六丈三尺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-290', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄以為天子四馬，周禮乘馬有四圉，各養一馬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-291', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄注旣夕曰：「服，車箱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-292', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」天子備章，鄭玄周禮注曰：「此古天子冕服十二章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-293', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '鄭玄曰：「華蟲，五色之蟲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-294', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄注曰：「繅，雜文之名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-295', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄曰：「謂之端，取其正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-296', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '禮曰：「朱干玉鏚，鄭玄曰：「朱干，赤大盾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-297', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '鄭玄箋曰：「佩璲者，以瑞玉為佩，佩之鞙鞙然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-298', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄詩箋曰：「旣爵命賞賜，而加賜容刀有飾，顯其能制斷也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-299', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄曰：「珈之言加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-300', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '少受業於鄭玄，建安初為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-301', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「先正，先臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-302', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「屆，極也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-303', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄曰：「爰，於也，安隱於其衆也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-304', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「昏，勉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-003-305', 'p0269', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」鄭玄云：「夏后氏以建寅為正，物生色黑；殷以建丑為正，物牙色白；周以建子為正，物萌色赤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-306', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝又問曰：「孔子作彖、象，鄭玄作注，雖聖賢不同，其所釋經義一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-307', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」俊對曰；「鄭玄合彖、象於經者，欲使學者尋省易了也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-308', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」帝曰：「若鄭玄合之，於學誠便，則孔子曷為不合以了學者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-309', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」帝曰：「若聖人以不合為謙，則鄭玄何獨不謙邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-310', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝問曰：「鄭玄云『稽古同天，言堯同於天也』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-311', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '伏見故漢大司農北海鄭玄，當時之學，名冠華夏，為世儒宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-312', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '鄭玄注文王世子曰「三老、五更各一人，皆年老更事致仕者也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-006-313', 'p0269', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：紹延徵北海鄭玄而不禮，趙融聞之曰：「賢人者，君子之望也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-314', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時魯國孔融在郡，教選計當任公卿之才，乃以鄭玄為計掾，彭璆為計吏，原為計佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-315', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時鄭玄博學洽聞，注解典籍，故儒雅之士集焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-316', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '昔司空荀爽，家拜光祿，先儒鄭玄，即授司農，若加備禮，庶必可致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-317', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」鄭玄曰：「耇，老也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-318', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '至年二十九，乃結公孫方等就鄭玄受學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-319', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '告高密縣為鄭玄特立一鄉，名為鄭公鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-320', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '高密鄭玄，稱之鄭公，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-013-321', 'p0269', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '授學鄭玄之門，人稱東州大儒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-014-322', 'p0269', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '濟又難：鄭玄注祭法云「有虞以上尚德，禘郊祖宗，配用有德，自夏已下，稍用其姓氏」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-014-323', 'p0269', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣以為祭法所云，見疑學者乆矣，鄭玄不考正其違而就通其義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-022-324', 'p0269', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '少事馬融，與鄭玄同門相友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-027-325', 'p0269', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '散騎常侍王肅著諸經傳解及論定朝儀，改易鄭玄舊說，而基據持玄義，常與抗衡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-032-326', 'p0269', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '今臣羣寮以為在昔虞書敦叙九族，庶明勵翼，鄭玄注曰：庶，衆也；勵，作也；叙，次序也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-038-327', 'p0269', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主領徐州，辟為從事，鄭玄傳云：玄薦乾於州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-042-328', 'p0269', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '著古文易、尚書、毛詩、三禮、左氏傳、太玄指歸，皆依準賈、馬，異於鄭玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-047-329', 'p0269', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」　鄭玄注曰：「周人卒哭而致事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-053-330', 'p0269', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '逮事鄭玄，後避亂交州，與劉熈考論大義，遂博通五經。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-331', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '若乃北海鄭玄，南陽宋忠，雖各立注，忠小差玄而皆未得其門，難以示世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-332', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」又奏鄭玄解尚書違失事目：「臣聞周公制禮以辨上下，孔子曰『有君臣然後有上下，有上下然後禮義有所錯』，是故尊君卑臣，禮之大司也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-333', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '伏見故徵士北海鄭玄所注尚書，以顧命康王執瑁，古『月』似『同』，從誤作『同』，旣不覺定，復訓為杯，謂之酒杯；成王疾困憑几，洮頮為濯，以為澣衣成事，『洮』字虛更作『濯』，以從其非；又古大篆『卯』字讀當為『柳』，古『柳』『卯』同字，而以為昧；『分北三苗』，『北』古『別』字，又訓北，言北猶別也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-011-334', 'p0269', 'jinshu', 'a05-011', '《晉書·卷十一》', '」鄭玄謂以玉為渾儀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-011-335', 'p0269', 'jinshu', 'a05-011', '《晉書·卷十一》', '」鄭玄云：「凡日景於地，千里而差一寸，景尺有五寸者，南戴日下萬五千里也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-016-336', 'p0269', 'jinshu', 'a05-016', '《晉書·卷十六》', '淮南、京房、鄭玄諸儒言律歷，皆上下相生，至蕤賔又重上生大呂，長八寸二百四十三分寸之百四；夷則上生夾鍾，長七寸千一百八十七分寸之千七十五；無射上生中呂，長六寸萬九千六百八十二分寸之萬二千九百七十四：此三呂於司馬遷、班固所生之寸數及分皆倍焉，餘則並同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-016-337', 'p0269', 'jinshu', 'a05-016', '《晉書·卷十六》', '鄭玄以為鬴方尺，積千寸，比九章粟米法少二升八十一分升之二十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-017-338', 'p0269', 'jinshu', 'a05-017', '《晉書·卷十七》', '獻帝建安元年，鄭玄受其法，以為窮幽極微，又加注釋焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-068-0', 'p0270', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '與陳留邊讓並善談論，俱有盛名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-070-1', 'p0270', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融由是顯名，與平原陶丘洪、陳留邊讓齊聲稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-074-2', 'p0270', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」故九江太守邊讓，英才儁逸，以直言正色，論不阿諂，身被梟懸之戮，妻孥受灰滅之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-3', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '張升　趙壹　劉梁　邊讓　酈炎　侯瑾　高彪　張超　禰衡');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-4', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '邊讓字文禮，陳留浚儀人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-5', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」竊見令史陳留邊讓，天授逸才，聦明賢智。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-001-6', 'p0270', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁忠為沛相，甞欲以法治太祖，沛國桓邵亦輕之，及在兖州，陳留邊讓言議頗侵太祖，太祖殺讓，族其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-006-7', 'p0270', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故九江太守邊讓，英才俊逸，天下知名，以直言正色，論不阿諂，身被梟縣之戮，妻孥受灰滅之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-012-8', 'p0270', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '融由是名震遠近，與平原陶丘洪、陳留邊讓，並以俊秀，為後進冠蓋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-023-9', 'p0270', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '受學陳留邊讓，讓器異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-028-10', 'p0270', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　松字叔茂，陳留人，九江太守邊讓外孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0271-a03-058-0', 'p0271', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '虞詡　傅爕　蓋勳　臧洪');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0271-a03-058-1', 'p0271', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '蓋勳字元固，敦煌廣至人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0272-a03-008-full-0', 'p0272', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0272-a03-008-1', 'p0272', 'houhanshu', 'a03-008', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-0', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，大鴻臚橋玄為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-1', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司徒許訓免，司空橋玄為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-2', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十二月丁巳，光祿大夫橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-3', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙丑，太尉橋玄罷，太中大夫段熲為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-4', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，大鴻臚橋玄為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-5', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司徒許訓免，司空橋玄為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-6', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十二月丁巳，光祿大夫橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-7', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙丑，太尉橋玄罷，太中大夫段熲為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-8', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '李恂　陳禪　龐參　陳龜　橋玄');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-9', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '橋玄字公祖，梁國睢陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-10', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」魏志曰「建安七年，曹公軍譙，遂至浚儀，遣使以太牢祀橋玄，進軍官度」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-11', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」龐參躬求賢之禮，故民恱其政；橋玄厲邦君之威，而衆失其情。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-12', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '橋玄之舍姜岐，以道不可違，故不得以威力逼也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-056-13', 'p0273', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '推達名臣橋玄、皇甫規等，為稱職相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-065-14', 'p0273', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '光和二年，復代橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-074-15', 'p0273', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁字元瑋，橋玄族子，先為兖州刺史，甚有威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-16', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '惟梁國橋玄、南陽何顒異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-17', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」魏書曰：太尉橋玄，世名知人，覩太祖而異之，曰：「吾見天下名士多矣，未有若君者也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-18', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」遂至浚儀，治睢陽渠，遣使以太牢祀橋玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-002-19', 'p0273', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '初，漢熹平五年，黃龍見譙，光祿大夫橋玄問太史令單颺：「此何祥也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-002-20', 'p0273', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '十二月，行自譙過梁，遣使以太牢祀故漢太尉橋玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-062-0', 'p0274', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-067-1', 'p0274', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '劉淑　李膺　杜密　劉祐　魏朗　夏馥　宗慈　巴肅　范滂　尹勳　蔡衍　羊陟　張儉　岑晊　陳翔　孔昱　苑康　檀𢿭　劉儒　賈彪　何顒');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-067-2', 'p0274', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '何顒字伯求，南陽襄鄉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-069-3', 'p0274', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '因復博徵智謀之士龐紀、何顒、荀攸等，與同腹心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-4', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業等與侍中伍瓊、卓長史何顒共說卓，以袁紹為勃海太守，以發山東之謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-5', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '乃與何顒、荀攸共謀殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-6', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '南陽何顒名知人，見彧而異之，曰：「王佐才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-072-7', 'p0274', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-001-8', 'p0274', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '惟梁國橋玄、南陽何顒異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-006-9', 'p0274', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '侍中周毖、城門校尉伍瓊、議郎何顒等，皆名士也，卓信之，而陰為紹，乃說卓曰：「夫廢立大事，非常人所及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-010-10', 'p0274', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧年少時，南陽何顒異之，曰：「王佐才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-010-11', 'p0274', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與議郎鄭泰、何顒、侍中种輯、越騎校尉伍瓊等謀曰：「董卓無道，甚於桀紂，天下皆怨之，雖資彊兵，實一匹夫耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-001-0', 'p0275', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '甲子，前將軍鄧禹擊更始定國公王匡於安邑，大破之，安邑，縣，屬河東郡，今蒲州縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-009-1', 'p0275', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」將作大匠吳脩、越騎校尉王瓌安集關東，後將軍袁術、河內太守王匡各執而殺之，英雄記曰：「匡字公節，太山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-2', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '新市人王匡、王鳳為平理諍訟，遂推為渠帥，衆數百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-3', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王常、成丹西入南郡，号下江兵；王匡、王鳳、馬武及其支黨朱鮪、張卬等續漢書「卬」作「印」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-4', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '悉拜置諸將，以族父良為國三老，王匡為定國上公，王鳳成國上公，朱鮪大司馬，伯升大司徒，陳牧大司空，餘皆九卿、將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-5', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王莽使太師王匡、國將哀章守洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-6', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '」更始遣定國上公王匡攻洛陽，西屏大將軍申屠建、丞相司直李松攻武關，三輔震動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-7', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '是月，拔洛陽，生縛王匡、哀章，至，皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-8', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始乃先封宗室太常將軍劉祉為定陶王，劉賜為宛王，劉慶為燕王，劉歙為元氏王，大將軍劉嘉為漢中王，劉信為汝陰王；後遂立王匡為比陽王，王鳳為宜城王，朱鮪為膠東王，衞尉大將軍張卬為淮陽王，廷尉大將軍王常為鄧王，執金吾大將軍廖湛為穰王，申屠建為平氏王，尚書胡殷為隨王，柱天大將軍李通為西平王，西平，縣，屬汝南郡，故城在今豫州郾城縣南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-9', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '時李軼、朱鮪擅命山東，王匡、張卬橫暴三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-10', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '時王匡、張卬守河東，為鄧禹所破，還奔長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-11', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '及赤眉立劉盆子，更始使王匡、陳牧、成丹、趙萌屯新豐，李松軍掫，掫音子侯反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-12', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始復疑王匡、陳牧、成丹與張卬等同謀，乃並召入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-13', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王匡懼，將兵入長安，與張卬等合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-14', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王莽遣平均公廉丹、太師王匡擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-014-15', 'p0275', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '使宗室劉嘉往誘新市、平林兵王匡、陳牧等，合軍而進，屠長聚及唐子鄉，殺湖陽尉，進拔棘陽，因欲攻宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-015-16', 'p0275', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '乆之，與王鳳、王匡等起兵雲杜綠林中，聚衆數萬人，以常為偏裨，攻傍縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-17', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '及赤眉西入關，更始使定國上公王匡、襄邑王成丹、抗威將軍劉均及諸將，分據河東、弘農以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-18', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '赤眉衆大集，王匡等莫能當。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-19', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '於是王匡、成丹、劉均等合軍十餘萬，復共擊禹，禹軍不利，樊崇戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-20', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '更始諸將王匡、胡殷、成丹等皆詣廣降，與共東歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-019-21', 'p0275', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '更始傳曰：「李軼、朱鮪擅命山東，王匡、張卬橫暴三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-023-22', 'p0275', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '王莽末，青、徐賊起，太師王匡匡，王舜之子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-050-full-23', 'p0275', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '堅立二十六年薨，子懷王匡嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-050-24', 'p0275', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '堅立二十六年薨，子懷王匡嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-069-25', 'p0275', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-072-26', 'p0275', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時河內太守王匡屯兵河陽津，英雄記曰：「匡字公節，泰山人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-27', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-28', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '王匡字公節，泰山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-29', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹與王匡屯河內，伷屯潁川，馥屯鄴，餘軍咸屯酸棗，約盟，遙推紹為盟主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-30', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹使王匡殺班、瓌、吳循等，海內先賢傳曰：「韓融字元長，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-31', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」謝承書曰：「班，王匡之妹夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-32', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時進旣被害，師徒喪沮，臣獨將家兵百餘人，抽戈承明，竦劔翼室，山陽公載記曰：「紹與王匡等并力入端門，於承明堂上格殺中常侍高望等二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-001-33', 'p0275', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '河內太守王匡、英雄記曰：匡字公節，泰山人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-34', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '河內太守王匡遣泰山兵屯河陽津，將以圖卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-35', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓遣執金吾胡母班、將作大匠吳脩齎詔書喻紹，紹使河內太守王匡殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-36', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：班，王匡之妹夫，董卓使班奉詔到河內，解釋義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-009-37', 'p0275', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太守王匡以為從事，將兵拒董卓於盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-023-38', 'p0275', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太守王匡起兵討董卓，遣諸生於屬縣微伺吏民罪負，便收之，考責錢穀贖罪，稽遲則夷滅宗族，以崇威嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-051-39', 'p0275', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '永興元年，乘輿幸鄴，司空東海王越治兵下邳，惠以書干越，詭其姓名，自稱南岳逸民秦祕之，勉以勤王匡世之略，辭義甚美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-058-0', 'p0276', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '兖州刺史岱、豫州刺史伷、陳留太守邈、東郡太守瑁、橋瑁也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-069-1', 'p0276', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-2', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-3', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁字元瑋，橋玄族子，先為兖州刺史，甚有威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-4', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁乃詐作三公移書，傳驛州郡，說董卓罪惡，天子危逼，企望義兵，以釋國難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-104-5', 'p0276', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '應劭曰：「關東義兵先起於宋、衞之郊，東郡太守橋瑁負衆怙亂，陵蔑同盟，忿嫉同類，以殞厥命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-6', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '東郡太守橋瑁詐作京師三公移書與州郡，陳卓罪惡，云「見逼迫，無以自救，企望義兵，解國患難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-7', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-8', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱與橋瑁相惡，岱殺瑁，以王肱領東郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a03-074-0', 'p0277', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a03-074-1', 'p0277', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁遺字伯業，紹從弟術字公路，汝南汝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a04-001-2', 'p0277', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '山陽太守袁遺、遺字伯業，紹從兄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a04-006-3', 'p0277', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹遣袁遺領州，敗散，奔沛國，為兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-058-0', 'p0278', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '豫州刺史孔伷，伷字公緒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-068-1', 'p0278', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '融一往，薦達郡士范冉、韓卓、孔伷等三人，伷音冑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-068-2', 'p0278', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '旣到官，融往相見，薦范冉為功曹，韓卓為主簿，孔伷為上計吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-072-3', 'p0278', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」陳留孔伷為豫州刺史，英雄記伷字公緒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-074-4', 'p0278', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-001-5', 'p0278', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '豫州刺史孔伷、英雄記曰：伷字公緒，陳留人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-006-6', 'p0278', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-038-7', 'p0278', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-009-0', 'p0279', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-1', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將胡軫、呂布攻之，布與軫不相能，軍中自驚恐，士卒散亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-2', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「卓以東郡太守胡軫為大督，呂布為騎督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-3', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a04-015-4', 'p0279', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '殷先與司隷校尉胡軫有隙，軫誣搆殺殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a04-046-5', 'p0279', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓亦遣兵步騎五千迎之，陳郡太守胡軫為大督護，呂布為騎督，其餘步騎將校都督者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0280-a03-010b-full-0', 'p0280', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '卓乃置弘農王於閣上，使郎中令李儒進酖，曰：「服此藥，可以辟惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-009-0', 'p0281', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」董卓遣其將牛輔擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-1', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣中郎將牛輔擊之，不能却。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-2', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中郎將牛輔屯安邑，其餘中郎將、校尉布在諸縣，以禦山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-3', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓以牛輔子壻，素所親信，使以兵屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-4', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '其後牛輔營中無故大驚，輔懼，乃齎金寶踰城走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-5', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '牛輔旣敗，衆無所依，欲各散去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-6', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」牛輔屯陝，詡在輔軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-7', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又以故牛輔部曲董承為安集將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a04-006-8', 'p0281', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a04-010-9', 'p0281', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓壻中郎將牛輔屯陝，詡在輔軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0282-a04-006-0', 'p0282', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '近董公之彊，明將軍目所見，內有王公以為內主，外有董旻、承、璜以為鯁毒，呂布受恩而反圖之，斯須之間，頭縣竿端，此有勇而無謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-009-0', 'p0283', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三年夏四月，遣謁者裴茂率中郎將段煨討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-1', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」乃使東中郎將董越屯黽池，中郎將段煨屯華陰，典略曰：「煨在華陰，特修農事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-2', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」寧輯將軍段煨乃具服御及公卿以下資儲，請帝幸其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-3', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '侍中种輯素與定親，乃言曰：『段煨欲反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-4', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-5', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年，使謁者僕射裴茂詔關中諸將段煨等討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-6', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」以段煨為安南將軍，封閺鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-7', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '後徵段煨為大鴻臚，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a04-010-8', 'p0283', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是時將軍段煨屯華陰，典略稱煨在華陰時，脩農事，不虜略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a04-013-9', 'p0283', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '興平中，關中擾亂，與兄季中依將軍段煨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0284-a04-007-0', 'p0284', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安元年六月夜半時，布將河內郝萌反，將兵入布所治下邳府，詣廳事閤外，同聲大呼攻閤，閤堅不得入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0284-a04-007-1', 'p0284', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布從郝萌反後，更疏順。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0285-a04-007-0', 'p0285', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '萌將曹性反萌，與對戰，萌刺傷性，性斫萌一臂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0286-a04-001-0', 'p0286', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0286-a04-007-1', 'p0286', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-001-0', 'p0287', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-007-1', 'p0287', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-007-2', 'p0287', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '以魏續有外內之親，悉奪順所將兵以與續。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-018-0', 'p0288', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '子哀侯成嗣，為奴所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-050-full-1', 'p0288', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '匡立十一年薨，無子，順帝封匡弟孝陽亭侯成為梁王，是為夷王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-050-2', 'p0288', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '匡立十一年薨，無子，順帝封匡弟孝陽亭侯成為梁王，是為夷王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-075-3', 'p0288', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '其將侯成使客牧其名馬，而客策之以叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a04-007-4', 'p0288', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a04-007-5', 'p0288', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '九州春秋曰：初，布騎將侯成遣客牧馬十五匹，客悉驅馬去，向沛城，欲歸劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-0', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '潁川郭圖、淳于瓊曰：九州春秋圖字公則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-1', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」郭圖、審配曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-2', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹乃分授所統為三都督，使授及郭圖、淳于瓊各典一軍，未及行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-3', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」遂以疾退，紹不許而意恨之，復省其所部，并屬郭圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-4', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '』郭圖曰：『郃計非也，不如攻其本營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-5', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-6', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-001-7', 'p0289', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-8', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，天子之立非紹意，及在河東，紹遣潁川郭圖使焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-9', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭圖、淳于瓊曰：「漢室陵遲，為日乆矣，今欲興之，不亦難乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-10', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '案此書稱郭圖之計，則與本傳違也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-11', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」審配、郭圖曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-12', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃分監軍為三都督，使授及郭圖、淳于瓊各典一軍，遂合而南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-13', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹恨之，乃省其所部兵屬郭圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-14', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-15', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣劫於郭圖，亦以兵鋒累交，遂戰不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-16', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-010-17', 'p0289', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧弟諶及同郡辛評、郭圖，皆為紹所任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-013-18', 'p0289', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-014-19', 'p0289', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-014-20', 'p0289', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '有郭圖、逢紀為之謀臣，必交鬬其閒，還相離也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-017-21', 'p0289', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」郭圖曰：「郃計非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-017-22', 'p0289', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至如此傳，為紹軍先潰，懼郭圖之譖，然後歸太祖，為參錯不同矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-025-23', 'p0289', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '郭圖說譚曰：「今將軍國小兵少，糧匱勢弱，顯甫之來，久則不敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-070-0', 'p0290', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '審配、逢紀盡忠之臣任其事，配字正南，魏郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-070-1', 'p0290', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-2', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹客逢紀謂紹曰：英雄記曰：「紀字元圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-3', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-4', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '先賢行狀曰：「紹謂逢紀曰：『兾州人聞吾軍敗，皆當念吾；唯田別駕前諫止吾，與衆不同，吾亦慙之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-5', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-6', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-7', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '英雄記曰：逢紀說紹曰：「將軍舉大事而仰人資給，不據一州，無以自全。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-8', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-9', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '逢紀憚豐亮直，數讒之於紹，紹遂忌豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-10', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹謂逢紀曰：「兾州人聞吾軍敗，皆當念吾，唯田別駕前諫止吾，與衆不同，吾亦慙見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-11', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-12', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '譚軍黎陽，尚少與譚兵，而使逢紀從譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-13', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是時凶臣逢紀，妄畫蛇足，曲辭諂媚，交亂懿親，將軍奮赫然之怒，誅不旋時，我將軍亦奉命承旨，加以淫刑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-010-14', 'p0290', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-010-15', 'p0290', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配專而無謀，逢紀果而自用，此二人留知後事，若攸家犯其法，必不能縱也，不縱，攸必為變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-014-16', 'p0290', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '有郭圖、逢紀為之謀臣，必交鬬其閒，還相離也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a03-074-0', 'p0291', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a03-074-1', 'p0291', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-006-2', 'p0291', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-006-3', 'p0291', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-010-4', 'p0291', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧弟諶及同郡辛評、郭圖，皆為紹所任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-014-5', 'p0291', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-009-0', 'p0292', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，曹操破高幹於并州，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-049-1', 'p0292', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '并州刺史高幹，袁紹甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-049-2', 'p0292', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '魏志曰：「高幹叛，欲南奔荊州，上洛都尉王琰捕斬之」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-3', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹乃使外甥陳留高幹及潁川荀諶等說馥曰：魏志云諶，荀彧之弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-4', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」於是以中子熙為幽州刺史，外甥高幹為并州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-5', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」并州越太行，紹甥高幹為并州刺史，故言越太行山而來助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-001-6', 'p0292', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁紹以甥高幹領并州牧，公之拔鄴，幹降，遂以為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-001-7', 'p0292', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟師洪河，拓定四州，袁譚、高幹，咸梟其首，海盜奔迸，黑山順軌，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-8', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會卓西入關，紹還軍延津，因馥惶遽，使陳留高幹、頴川荀諶等說馥曰：「公孫瓚乘勝來向南，而諸郡應之，袁車騎引軍東向，此其意不可知，竊為將軍危之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-9', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又以中子熈為幽州，甥高幹為并州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-10', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '高幹以并州降，復以幹為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-11', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」高幹叛，執上黨太守，舉兵守壺口關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-12', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '典略曰：上洛都尉王琰獲高幹，以功封侯；其妻哭於室，以為琰富貴將更娶妾媵而奪己愛故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-010-13', 'p0292', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-010-14', 'p0292', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖之征袁尚也，高幹密遣兵謀襲鄴，衍逆覺，盡誅之，以功封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-011-15', 'p0292', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '并州牧高幹表除樂平令，不就，徙遁常山，門徒且數百人，遷居任縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-16', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-17', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '今曹公與袁氏相持，而高幹、郭援獨制河東，曹公雖有萬全之計，不能禁河東之不危也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-18', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其後河東衞固作亂，與張晟、張琰及高幹等並為寇，繇又率諸將討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-19', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '時承高幹荒亂之餘，胡狄在界，張雄跋扈，吏民亡叛，入其部落；兵家擁衆，作為寇害，更相扇動，往往棊跱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-20', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '袁尚拒太祖於黎陽，遣所置河東太守郭援、并州刺史高幹及匈奴單于取平陽，發使西與關中諸將合從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-21', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '高幹之反，張琰將舉兵以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-016-22', 'p0292', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖旣定河北，而高幹舉并州反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-016-23', 'p0292', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '會白騎攻東垣，高幹入濩澤，上黨諸縣殺長吏，弘農執郡守，固等密調兵未至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-017-24', 'p0292', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '進別征高幹，從北道入上黨，回出其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-018-25', 'p0292', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從圍鄴，鄴定，與樂進圍高幹於壺關，擊管承於長廣，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-018-26', 'p0292', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-021-27', 'p0292', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '并州刺史高幹素貴有名，招致四方游士，多歸焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-023-28', 'p0292', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '并州刺史高幹表為騎都尉，林辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-023-29', 'p0292', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '會以建策捕高幹，又追錄前討郭援功，封武鄉侯，遷弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-024-30', 'p0292', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '高幹旣降，頃之以并州叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-026-31', 'p0292', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '時尚外兄高幹為并州刺史，招以并州左有恒山之險，右有大河之固，帶甲五萬，北阻彊胡，勸幹迎尚，并力觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-036-32', 'p0292', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '騰遣超隨繇討郭援、高幹於平陽，超將龐德親斬援首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-070-0', 'p0293', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」顏良、文醜勇冠三軍，統其兵，殆難克乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-070-1', 'p0293', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-2', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-3', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '乃先遣顏良攻曹操別將劉延於白馬，白馬，縣，屬東郡，今滑州縣也，故城在今縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-4', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹操遂救劉延，擊顏良斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-001-5', 'p0293', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-001-6', 'p0293', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公到延津，若將渡兵向其後者，紹必西應之，然後輕兵襲白馬，掩其不備，顏良可禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-006-7', 'p0293', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-006-8', 'p0293', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹進軍黎陽，遣顏良攻劉延於白馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-9', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-10', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顏良、文醜，一夫之勇耳，可一戰而禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-11', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-12', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後從救劉延於白馬，攸畫策斬顏良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-014-13', 'p0293', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹遣將顏良攻東郡，又徙昭為魏郡太守，從討良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-017-14', 'p0293', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破劉備，又從破顏良，拔白馬，進至延津，破文醜，拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-036-15', 'p0293', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '紹遣大將軍顏良攻東郡太守劉延於白馬，曹公使張遼及羽為先鋒擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-036-16', 'p0293', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」及羽殺顏良，曹公知其必去，重加賞賜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-008-full-0', 'p0295', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-008-1', 'p0295', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-069-2', 'p0295', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '是時置西園八校尉，以小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎都尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍校尉，淳于瓊為佐軍校尉，又有左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-3', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-4', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '潁川郭圖、淳于瓊曰：九州春秋圖字公則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-5', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹乃分授所統為三都督，使授及郭圖、淳于瓊各典一軍，未及行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-6', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遣淳于瓊等將兵萬餘人北迎粮運。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-7', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會攸家犯法，審配收繫之，攸不得志，遂奔曹操，而說使襲取淳于瓊等，瓊等時宿在烏巢，烏巢，地名，在滑州酸棗城東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-8', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-9', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹若有十倍之衆，理應當悉力圍守，使出入斷絕，而公使徐晃等擊其運車，公又自出擊淳于瓊等，揚旌往還，曾無抵閡，明紹力不能制，是不得甚少，二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-10', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」冬十月，紹遣車運穀，使淳于瓊等五人將兵萬餘人送之，宿紹營北四十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-11', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '輙勒兵馬，與戰官渡，乘聖朝之威，得斬紹大將淳于瓊等八人首，遂大破潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-12', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭圖、淳于瓊曰：「漢室陵遲，為日乆矣，今欲興之，不亦難乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-13', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃分監軍為三都督，使授及郭圖、淳于瓊各典一軍，遂合而南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-14', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會紹遣淳于瓊等將兵萬餘人北迎運車，沮授說紹：「可遣將蔣奇別為支軍於表，以斷曹公之鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-008-15', 'p0295', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝紀曰：以虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融、馮芳為助軍校尉，夏牟、淳于瓊為左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-010-16', 'p0295', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '遂以奇兵襲紹別屯，斬其將淳于瓊等，紹退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-010-17', 'p0295', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會許攸來降，言紹遣淳于瓊等將萬餘兵迎運糧，將驕卒惰，可要擊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-18', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '渡河攻獲嘉，還，從擊袁紹於官渡，力戰，斬紹將淳于瓊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-19', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '紹遣將淳于瓊等督運屯烏巢，太祖自將急擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-20', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-009-0', 'p0296', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，袁紹遣將麴義與公孫瓉戰於鮑丘，鮑丘，水名，出北塞中，南流經九莊嶺東，俗謂之大榆河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-073-1', 'p0296', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '烏桓峭王感虞恩德，率種人及鮮卑七千餘騎，共輔南迎虞子和，與袁紹將麴義合兵十萬，共攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-073-2', 'p0296', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '相持歲餘，麴義軍糧盡，士卒飢困，餘衆數千人退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-3', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '明年，馥將麴義反畔，馥與戰失利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-4', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹先令麴義領精兵八百，強弩千張，以為前登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-5', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '麴義追至界橋，九州春秋曰：「還屯廣宗界橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-6', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會麴義來迎，騎乃散退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-7', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '麴義自恃有功，驕縱不軌，紹召殺之，而并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-8', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹令麴義以八百兵為先登，彊弩千張夾承之，紹自以步兵數萬結陣於後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-9', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '瓚騎不知是紹，亦稍引郤；會麴義來迎，乃散去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-10', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」麴義後恃功而驕恣，紹乃殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-11', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹軍廣川，令將麴義先登與瓚戰，生禽綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-12', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹又遣麴義及虞子和，將兵與輔合擊瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-13', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '前以西山陸梁，出兵平討，會麴義餘殘，畏誅逃命，故遂住大軍，分兵撲蕩，此兵孤之前行，乃界橋搴旗拔壘，先登制敵者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-14', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '單于執楊與俱去，紹使將麴義追擊於鄴南，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0297-a03-075-0', 'p0297', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術遣將紀靈等步騎三萬以攻備，備求救於布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0297-a04-007-1', 'p0297', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術遣將紀靈等步騎三萬攻備，備求救於布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-0', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術大怒，遣其將張勳、橋蕤攻布，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-1', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術聞大駭，即走度淮，留張勳、橋蕤於蘄陽，水經曰：「蘄水出江夏蘄春縣北山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-2', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-006-3', 'p0298', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以張勳、橋蕤等為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-007-4', 'p0298', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-046-5', 'p0298', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '太傅馬日磾杖節安集關東，在壽春以禮辟策，表拜懷義校尉，術大將喬蕤、張勳皆傾心敬焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-046-6', 'p0298', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0299-a03-075-0', 'p0299', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '主簿閻象進曰：「昔周自后稷至于文王，積德累功，參分天下，猶服事殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0299-a04-006-1', 'p0299', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '主簿閻象進曰：「昔周自后稷至于文王，積德累功，參分天下有其二，猶服事殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0300-a04-028-0', 'p0300', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '淩陰謀滋甚，遣將軍楊弘以廢立事告兖州刺史黃華，華、弘連名以白太傅司馬宣王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0300-a04-046-1', 'p0300', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0301-a04-006-0', 'p0301', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-006-0', 'p0302', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-006-1', 'p0302', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」表大將蒯越亦勸表，表狐疑，乃遣嵩詣太祖以觀虛實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0302-a04-032-2', 'p0302', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曾請備宴會，蒯越、蔡瑁欲因會取備，備覺之，偽如厠，潛遁出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-006-0', 'p0303', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表初到，單馬入宜城，而延中廬人蒯良、蒯越、襄陽人蔡瑁與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-006-1', 'p0303', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，表及妻愛少子琮，欲以為後，而蔡瑁、張允為之支黨，乃出長子琦為江夏太守，衆遂奉琮為嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0303-a04-032-2', 'p0303', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曾請備宴會，蒯越、蔡瑁欲因會取備，備覺之，偽如厠，潛遁出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-001-0', 'p0304', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-1', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '從事中郎韓嵩、別駕劉先說表曰：「豪傑並爭，兩雄相持，天下之重在於將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-2', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表以為懷貳，大會寮屬數百人，陳兵見嵩，盛怒，持節將斬之，數曰：「韓嵩敢懷貳邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-006-3', 'p0304', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '表怒不已，其妻蔡氏諫之曰：「韓嵩，楚國之望也；且其言直，誅之無辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0304-a04-031-4', 'p0304', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a03-043-0', 'p0305', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '後拜為尚書，復上封事曰：「夫忠臣憂世，犯主嚴顏，譏刺貴臣，至以殺身滅家而猶為之者，何邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a03-078-1', 'p0305', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '倫有才學，盡心敦慎，數犯嚴顏，匡弼得失。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-019-2', 'p0305', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '及見之，帝猶嚴顏色，不與語，又不使冠履。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-036-3', 'p0305', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '至江州，破璋將巴郡太守嚴顏，生獲顏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0305-a04-036-4', 'p0305', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽報效曹公，飛義釋嚴顏，並有國士之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0306-a04-032-0', 'p0306', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋遣劉璝、冷苞、張任、鄧賢等拒先主於涪，益部耆舊雜記曰：張任，蜀郡人，家世寒門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0306-a04-032-1', 'p0306', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十九年夏，雒城破，益部耆舊雜記曰：劉璋遣張任與劉璝率精兵拒捍先主於涪，為先主所破，退與璋子循守雒城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0307-a04-037-0', 'p0307', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '鄭度說璋曰：華陽國志曰：度，廣漢人，為州從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-0', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '魯功曹閻圃諫曰：「漢川之民，戶出十萬，四面險固，財富土沃，上匡天子，則為桓文，次方竇融，不失富貴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-1', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '閻圃說曰：「今以急往，其功為輕，不如且依巴中，然後委質，功必多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a03-075-2', 'p0308', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '封魯五子及閻圃等皆為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-3', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魯功曹巴西閻圃諫魯曰：「漢川之民，戶出十萬，財富土沃，四面險固；上匡天子，則為桓、文，次及竇融，不失富貴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-4', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '封魯五子及閻圃等皆為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-5', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '習鑿齒曰：魯欲稱王，而閻圃諫止之，今封圃為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-008-6', 'p0308', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '今閻圃諫魯勿王，而太祖追封之，將來之人孰不思順！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0308-a04-036-7', 'p0308', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '魯敗，曹公得之，以董賜閻圃，以秋付魯，魯自手殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a03-073-0', 'p0309', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '長史關靖諫曰：「今將軍將士，莫不懷瓦解之心，所以猶能相守者，顧戀其老小，而恃將軍為主故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a03-073-1', 'p0309', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '關靖見瓚敗，歎恨曰：「前若不止將軍自行，未必不濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-2', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謂關靖曰：「當今四方虎爭，無有能坐吾城下相守經年者明矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-3', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '長史關靖說瓚曰：「今將軍將士皆已土崩瓦解，其所以能相守持者，顧戀其居處老小，以將軍為主耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-4', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：關靖字士起，太原人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0309-a04-008-5', 'p0309', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：關靖曰：「吾聞君子陷人於危，必同其難，豈可獨生乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-006-0', 'p0310', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遂北排田楷，東攻孔融，曜兵海隅，是時百姓無主，欣戴之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-008-1', 'p0310', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '以嚴綱為兾州，田楷為青州，單經為兖州，置諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-008-2', 'p0310', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '謙引兵擊之，青州刺史田楷亦以兵救謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-3', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-4', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-032-5', 'p0310', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公征徐州，徐州牧陶謙遣使告急於田楷，楷與先主俱救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0310-a04-036-6', 'p0310', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a03-073-0', 'p0311', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，同郡人笮融，笮音側格反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-008-1', 'p0311', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '賊笮融從臨淮見討，迸入郡界，昱將兵拒戰，敗績，見害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-046-2', 'p0311', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時彭城相薛禮、下邳相笮融依繇為盟主，禮據秣陵城，融屯縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-046-3', 'p0311', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '發恩布令，告諸縣：「其劉繇、笮融等故鄉部曲來降首者，一無所問；樂從軍者，一身行，復除門戶；不樂者，勿彊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-4', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融先至，笮音壯力反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-5', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '許子將謂繇曰：「笮融出軍，不顧命名義者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-049-6', 'p0311', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融者，丹楊人，初聚衆數百，往依徐州牧陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-050-7', 'p0311', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-050-8', 'p0311', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '」琨具啟策，策即行之，衆悉俱濟，遂破英，擊走笮融、劉繇，事業克定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-053-9', 'p0311', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，琅邪趙昱為廣陵太守，察紘孝廉，昱後為笮融所殺，紘甚傷憤，而力不能討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-054-10', 'p0311', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乃渡擊秣陵，破笮融、薛禮，轉下湖孰、江乘，進入曲阿，劉繇奔走，而策之衆已數萬矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0311-a04-056-11', 'p0311', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '策定秣陵、曲阿，收笮融、劉繇餘衆，增範兵二千，騎五十匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a03-073-0', 'p0312', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '別駕從事趙昱，知名士也，而以忠直見踈，出為廣陵太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a03-073-1', 'p0312', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-007-2', 'p0312', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '時選三署郎以補縣長；琅邪趙昱為莒長，東萊劉繇下邑長，東海王朗菑丘長，洪即丘長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-008-3', 'p0312', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '而謙背道任情：廣陵太守琅邪趙昱，徐方名士也，以忠直見疏；謝承漢書曰：昱年十三，母嘗病，經涉三月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-013-4', 'p0312', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時漢帝在長安，關東兵起，朗為謙治中，與別駕趙昱等說謙曰：「春秋之義，求諸侯莫如勤王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-049-5', 'p0312', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '曹公攻陶謙，徐土搔動，融將男女萬口，馬三千匹，走廣陵，廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-052-6', 'p0312', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '少好學，善隷書，從白侯子安受左氏春秋，博覽衆書，與琅邪趙昱、東海王朗俱發名友善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0312-a04-053-7', 'p0312', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '初，琅邪趙昱為廣陵太守，察紘孝廉，昱後為笮融所殺，紘甚傷憤，而力不能討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a03-009-0', 'p0313', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，孫策死，為許貢客所射傷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a03-112-1', 'p0313', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '興平二年，太守許貢奏分縣為永縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-014-2', 'p0313', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」策臨江未濟，果為許貢客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-038-3', 'p0313', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '禕死，吳郡都尉許貢、會稽太守王朗素與靖有舊，故往保焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-4', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '軍敗，還鄉里，為許貢所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-5', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢來領郡，岱將憲避難於許昭家，求救於陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-6', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '未發，會為故吳郡太守許貢客所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-7', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初，吳郡太守許貢上表於漢帝曰：「孫策驍雄，與項籍相似，宜加貴寵，召還京邑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-046-8', 'p0313', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢客，無聞之小人，而能感識恩遇，臨義忘生，卒然奮發，有侔古烈矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0313-a04-056-9', 'p0313', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '治從錢唐欲進到吳，吳郡太守許貢拒之於由拳，治與戰，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-0', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」策遂詣丹楊依舅，得數百人，而為涇縣大帥祖郎所襲，幾至危殆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-1', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '行到錢唐，瑀陰圖襲策，遣都尉萬演等密渡江，使持印傳三十餘紐與賊丹楊、宣城、涇、陵陽、始安、黟、歙諸險縣大帥祖郎、焦已及吳郡烏程嚴白虎等，使為內應，伺策軍發，欲攻取諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-046-2', 'p0314', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '于時彊宗驍帥，祖郎、嚴虎之徒，禽滅已盡，所餘山越，蓋何足慮？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-050-3', 'p0314', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫策與孫河、呂範依景，合衆共討涇縣山賊祖郎，郎敗走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-051-4', 'p0314', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '又從策討陵陽，生得祖郎等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-051-5', 'p0314', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '袁術深怨策，乃陰遣間使齎印綬與丹楊宗帥陵陽祖郎等，使激動山越，大合衆，圖共攻策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-055-6', 'p0314', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策甞攻祖郎，大為所圍，普與一騎共蔽扞策，驅馬疾呼，以矛突賊，賊披，策因隨出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0314-a04-056-7', 'p0314', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '又從攻祖郎於陵陽，太史慈於勇里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-0', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳人嚴白虎等衆各萬餘人，處處屯聚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-1', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '有誠於故友，則受嚴白虎也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-2', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '行到錢唐，瑀陰圖襲策，遣都尉萬演等密渡江，使持印傳三十餘紐與賊丹楊、宣城、涇、陵陽、始安、黟、歙諸險縣大帥祖郎、焦已及吳郡烏程嚴白虎等，使為內應，伺策軍發，欲攻取諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-046-3', 'p0315', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策前西征，登陰復遣間使，以印綬與嚴白虎餘黨，圖為後害，以報瑀見破之辱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-056-4', 'p0315', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '貢南就山賊嚴白虎，治遂入郡，領太守事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0315-a04-056-5', 'p0315', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是時下邳陳瑀自號吳郡太守，住海西，與彊族嚴白虎交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-009-0', 'p0316', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二年秋八月，曹操大破烏桓於柳城，斬其蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-1', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '獻帝初平中，丘力居死，子樓班年少，從子蹋頓有武略，蹋音大蠟反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-2', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-3', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '紹矯制賜蹋頓、難樓、蘇僕延、烏延等，皆以單于印綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-4', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '後難樓、蘇僕延率其部衆奉樓班為單于，蹋頓為王，然蹋頓猶秉計策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-5', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安十二年，曹操自征烏桓，大破蹋頓於柳城，斬之，首虜二十餘萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a03-090-6', 'p0316', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '而靈獻之閒，二虜迭盛，石槐驍猛，盡有單于之地，蹋頓凶桀，公據遼西之土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-7', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遼西單于蹋頓尤彊，為紹所厚，故尚兄弟歸之，數入塞為害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-8', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '尚、熙與蹋頓、遼西單于樓班、右北平單于能臣抵之等，將數萬騎逆軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-001-9', 'p0316', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公登高，望虜陳不整，乃縱兵擊之，使張遼為先鋒，虜衆大崩，斬蹋頓及名王已下，胡、漢降者二十餘萬口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-011-10', 'p0316', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '若嘿回軍，從盧龍口越白檀之險，出空虛之地，路近而便，掩其不備，蹋頓之首可不戰而禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-011-11', 'p0316', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '斬蹋頓於白狼，遂長驅於柳城，疇有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-12', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '今四州之民，徒以威附，德施未加，舍而南征，尚因烏丸之資，招其死主之臣，胡人一動，民夷俱應，以生蹋頓之心，成覬覦之計，恐青、兾非己之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-13', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '大破之，斬蹋頓及名王已下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-014-14', 'p0316', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '後袁尚依烏丸蹋頓，太祖將征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-017-15', 'p0316', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遂擊，大破之，斬單于蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-017-16', 'p0316', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征蹋頓，拜橫野將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-17', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其後尚、熈又逃于蹋頓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-18', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '蹋頓又驍武，邊長老皆比之冒頓，恃其阻遠，敢受亡命，以雄百蠻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-19', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後丘力居死，子樓班年小，從子蹋頓有武略，代立，總攝三王部，衆皆從其教令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-20', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-21', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '紹矯制賜蹋頓、峭王、汗魯王印綬，皆以為單于。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-22', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '版文曰：「使持節大將軍督幽、青、并領兾州牧阮鄉侯紹，承制詔遼東屬國率衆王頒下、烏丸遼西率衆王蹋頓、右北平率衆王汗盧維：乃祖慕義遷善，款塞內附，北捍玁狁，東拒濊貊，世守北陲，為百姓保鄣，雖時侵犯王畧，命將徂征厥罪，率不旋時，悔愆變改，方之外夷，最又聦慧者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-23', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後樓班大，峭王率其部衆奉樓班為單于，蹋頓為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-24', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後袁尚敗奔蹋頓，憑其勢，復圖兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-25', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安十一年，太祖自征蹋頓於柳城，潛軍詭道，未至百餘里，虜乃覺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-26', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '尚與蹋頓將衆逆戰於凡城，兵馬甚盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0316-a04-030-27', 'p0316', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '太祖登高望虜陣，柳軍未進，觀其小動，乃擊破其衆，臨陣斬蹋頓首，死者被野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-002-0', 'p0317', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '并州刺史梁習討鮮卑軻比能，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-003-1', 'p0317', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '夏四月，鮮卑附義王軻比能率其種人及丁零大人兒禪詣幽州貢名馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-003-2', 'p0317', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '保塞鮮卑大人步度根與叛鮮卑大人軻比能私通，并州刺史畢軌表，輒出軍以外威比能，內鎮步度根。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-009-3', 'p0317', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時雜虜數為暴，害吏民，軌輒出軍擊鮮卑軻比能，失利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-014-4', 'p0317', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏氏春秋曰：烏丸校尉田豫帥西部鮮卑泄歸尼等出塞，討軻比能、智鬱築鞬，破之，還至馬邑故城，比能帥三萬騎圍豫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-019-5', 'p0317', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '時鮮卑大人軻比能將數萬騎觀望彊弱，見彰力戰，所向皆破，乃請服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-026-6', 'p0317', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '鮮卑大人步度根、泄歸泥等與軻比能為隙，將部落三萬餘家詣郡附塞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-026-7', 'p0317', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，護烏丸校尉田豫出塞，為軻比能所圍於故馬邑城，移招求救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-8', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後鮮卑大人軻比能復制御群狄，盡收匈奴故地，自雲中、五原以東抵遼水，皆為鮮卑庭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-9', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，太祖定幽州，步度根與軻比能等因烏丸校尉閻柔上貢獻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-10', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '到桑乾，氏等議，以為扶羅韓部威禁寬緩，恐不見濟，更遣人呼軻比能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-11', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後數與軻比能更相攻擊，步度根部衆稍寡弱，將其衆萬餘落保太原、鴈門郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-12', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至黃初五年，步度根詣闕貢獻，厚加賞賜，是後一心守邊，不為寇害，而軻比能衆遂彊盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-030-13', 'p0317', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '軻比能本小種鮮卑，以勇健，斷法平端，不貪財物，衆推以為大人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0317-a04-035-14', 'p0317', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '九年，亮復出祁山，以木牛運，漢晉春秋曰：亮圍祁山，招鮮卑軻比能，比能等至故北地石城以應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-0', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '保塞鮮卑大人步度根與叛鮮卑大人軻比能私通，并州刺史畢軌表，輒出軍以外威比能，內鎮步度根。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-1', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '帝省表曰：「步度根以為比能所誘，有自疑心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-2', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '比能遣子將千餘騎迎步度根部落，與尚、弼相遇，戰於樓煩，二將敗沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-3', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '步度根部落皆叛出塞，與比能合寇邊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-003-4', 'p0318', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '冬十月，步度根部落大人戴胡阿狼泥等詣并州降，朗引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-026-5', 'p0318', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '鮮卑大人步度根、泄歸泥等與軻比能為隙，將部落三萬餘家詣郡附塞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-6', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '魁頭死，弟步度根代立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-7', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根旣立，衆稍衰弱，中兄扶羅韓亦別擁衆數萬為大人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-8', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，太祖定幽州，步度根與軻比能等因烏丸校尉閻柔上貢獻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-9', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根遣使獻馬，帝拜為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-10', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後數與軻比能更相攻擊，步度根部衆稍寡弱，將其衆萬餘落保太原、鴈門郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-11', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根乃使人招呼泄歸泥曰：「汝父為比能所殺，不念報仇，反屬怨家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-12', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '」由是歸泥將其部落逃歸步度根，比能追之弗及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-13', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至黃初五年，步度根詣闕貢獻，厚加賞賜，是後一心守邊，不為寇害，而軻比能衆遂彊盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-14', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至青龍元年，比能誘步度根深結和親，於是步度根將泄歸泥及部衆悉保比能，寇鈔并州，殺略吏民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-15', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '後與東部鮮卑大人素利及步度根三部爭鬪，更相攻擊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-16', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '步度根數數鈔盜，又殺我弟，而誣我以鈔盜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0318-a04-030-17', 'p0318', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '至青龍元年，比能誘納步度根，使叛并州，與結和親，自勒萬騎迎其累重於陘北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-0', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖要擊眭固，又擊匈奴於夫羅於內黃，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-1', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：於夫羅者，南單于子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-2', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '中平中，發匈奴兵，於夫羅率以助漢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-3', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會本國反，殺南單于，於夫羅遂將其衆留中國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-001-4', 'p0319', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荊州牧劉表斷術糧道，術引軍入陳留，屯封丘，黑山餘賊及於夫羅等佐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0319-a04-008-5', 'p0319', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹至河內，楊與紹合，復與匈奴單于於夫羅屯漳水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-011-0', 'p0322', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '魏略純固傳以脂習、王脩、龐淯、文聘、成公英、郭憲、單固七人為一傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-011-1', 'p0322', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '其脩、淯、聘三人自各有傳，成公英別見張旣傳，單固見王淩傳，餘習、憲二人列於脩傳後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-015-2', 'p0322', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '旣夜藏精卒三千人為伏，使參軍成公英督千餘騎挑戰，勑使陽退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0322-a04-015-3', 'p0322', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：成公英，金城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a03-009-0', 'p0323', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月，遼東太守公孫康殺袁尚、袁熙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a03-090-1', 'p0323', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '袁尚與樓班、烏延等皆走遼東，遼東太守公孫康並斬送之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-001-2', 'p0323', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，遼東太守公孫康恃遠不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-006-3', 'p0323', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚、熈與烏丸逆軍戰，敗走奔遼東，公孫康誘斬之，送其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-026-4', 'p0323', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '又遼東太守公孫康自稱平州牧，遣使韓忠齎單于印綬往假峭王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-030-5', 'p0323', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康出軍擊之，破其國，焚燒邑落。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0323-a04-030-6', 'p0323', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康分屯有縣以南荒地為帶方郡，遣公孫模、張敞等收集遺民，興兵伐韓濊，舊民稍出，是後倭韓遂屬帶方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-002-0', 'p0324', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '三月，加遼東太守公孫恭為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-003-1', 'p0324', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」遼東太守公孫恭兄子淵劫奪恭位，遂以淵領遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0324-a04-011-2', 'p0324', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '文帝即位，徵寧，遂將家屬浮海還郡，公孫恭送之南郊，加贈服物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a03-085-0', 'p0325', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '有一女子名曰卑彌呼，年長不嫁，事鬼神道，能以妖惑衆，於是共立為王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-1', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其國本亦以男子為王，住七八十年，倭國亂，相攻伐歷年，乃共立一女子為王，名曰卑彌呼，事鬼道，能惑衆，年已長大，無夫壻，有男弟佐治國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-2', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其年十二月，詔書報倭女王曰：「制詔親魏倭王卑彌呼：帶方太守劉夏遣使送汝大夫難升米、次使都巿牛利奉汝所獻男生口四人，女生口六人、班布二匹二丈，以到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-3', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '倭女王卑彌呼與狗奴國男王卑彌弓呼素不和，遣倭載斯、烏越等詣郡說相攻擊狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-4', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '卑彌呼以死，大作冢，徑百餘步，徇葬者奴婢百餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0325-a04-030-5', 'p0325', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '復立卑彌呼宗女壹與，年十三為王，國中遂定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-0', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '景初二年六月，倭女王遣大夫難升米等詣郡，求詣天子朝獻，太守劉夏遣吏將送詣京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-1', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其年十二月，詔書報倭女王曰：「制詔親魏倭王卑彌呼：帶方太守劉夏遣使送汝大夫難升米、次使都巿牛利奉汝所獻男生口四人，女生口六人、班布二匹二丈，以到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-2', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '汝來使難升米、牛利涉遠，道路勤勞，今以難升米為率善中郎將，牛利為率善校尉，假銀印青綬，引見勞賜遣還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-3', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '又特賜汝紺地句文錦三匹、細班華五張、白絹五十匹、金八兩、五尺刀二口、銅鏡百枚、真珠、鈆丹各五十斤，皆裝封付難升米、牛利還到錄受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-4', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '其六年，詔賜倭難升米黃幢，付郡假授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0326-a04-030-5', 'p0326', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '遣塞曹掾史張政等因齎詔書、黃幢，拜假難升米為檄告喻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-0', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '伊夷模無子，淫灌奴部，生子名位宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-1', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '句麗呼相似為位，似其祖，故名之為位宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0329-a04-030-2', 'p0329', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '位宮有力勇，便鞌馬，善獵射。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-033-0', 'p0330', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年春，使越嶲太守張嶷平定越嶲郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-1', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '軍還，督將軍張嶷等討汶山郡叛羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-2', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '又越嶲郡亦乆失土地，忠率將太守張嶷開復舊郡，由此就加安南將軍，進封彭鄉亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-3', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '張嶷字伯岐，巴郡南充國人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-4', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '益部耆舊傳曰：余觀張嶷儀貌辭令，不能駭人，而其策略足以入筭，果烈足以立威，為臣有忠誠之節，處類有亮直之風，而動必顧典，後主深崇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0330-a04-043-5', 'p0330', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '王平忠勇而嚴整，張嶷識斷明果，咸以所長，顯名發迹，遇其時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-0', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-1', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-2', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-3', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-4', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-5', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月丙寅，李傕脅帝幸其營，焚宮室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-6', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁酉，郭汜攻李傕，矢及御前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-7', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」是日，李傕移帝幸北塢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-8', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五月壬午，李傕自為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-9', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-10', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月庚午，李傕、郭汜等追乘輿，戰於東澗，王師敗績，殺光祿勳鄧泉、衞尉士孫瑞、廷尉宣播、大長秋苗祀、獻帝春秋「播」作「璠」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-11', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-12', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕等復來追戰，王師大敗，殺略宮人，少府田芬、大司農張義等皆戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-009-13', 'p0331', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三年夏四月，遣謁者裴茂率中郎將段煨討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-full-14', 'p0331', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '及李傕破長安，遣兵鈔關東，略得姬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-full-15', 'p0331', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-010b-16', 'p0331', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，〈度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-17', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕殺司徒王允，復代允為司徒，數月病免，拜尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-18', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '時李傕與郭汜相攻，傕遂虜掠禁省，劫帝幸北塢，外內隔絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-027-19', 'p0331', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕從弟應，溫故掾也，諫之數日，乃獲免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-045-20', 'p0331', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '吳書曰，忠字嘉謀，與朱儁共敗李傕於曹陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-052-21', 'p0331', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '及李傕入長安，為亂兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-054-22', 'p0331', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕脅帝歸其營，竒與黃門侍郎鍾繇誘傕部曲將宋曅、楊昂令反傕，傕由此孤弱，帝乃得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-054-23', 'p0331', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕、郭汜之亂，彪盡節衞主，崎嶇危難之間，幾不免於害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-056-24', 'p0331', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '李傕、郭汜之亂，長安城潰，百官多避兵衝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-056-25', 'p0331', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-061-26', 'p0331', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及卓將李傕、郭汜攻破長安，遂收琬下獄死，時年五十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-064-27', 'p0331', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及李傕專政，使太傅馬日磾撫慰天下，以歧為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-28', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」卓部曲將李傕、郭汜等先將兵在關東，因不自安，遂合謀為亂，攻圍長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-29', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '是時三輔民庶熾盛，兵穀富實，李傕等欲即殺允，懼二郡為患，乃先徵翼、宏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-066-30', 'p0331', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '宏遣使謂翼曰：「郭汜、李傕以我二人在外，故未危王公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-070-31', 'p0331', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-32', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '尋李傕作亂，嵩亦病卒，贈驃騎將軍印綬，拜家一人為郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-33', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-34', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '陶謙以儁名臣，數有戰功，可委以大事，乃與諸豪桀共推儁為太師，因移檄牧伯，同討李傕等，奉迎天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-35', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-36', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」會李傕用太尉周忠、尚書賈詡策，徵儁入朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-37', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-071-38', 'p0331', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-39', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將李傕詣堅求和，堅拒絕不受，進軍大谷，距洛九十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-40', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-41', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及李傕之叛，乃召文才、整脩，使東曉喻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-42', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-43', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '袁宏紀曰「李傕數設酒請汜，或留汜止宿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-44', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '汜恐變生，乃弃軍還就李傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-45', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-46', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕謂左右曰：「尚可活不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-072-47', 'p0331', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年，使謁者僕射裴茂詔關中諸將段煨等討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-073-48', 'p0331', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-073-49', 'p0331', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初三輔遭李傕亂，百姓流移依謙者皆殲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-074-50', 'p0331', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，車駕為李傕等所追於曹陽，沮授說紹曰：「將軍累葉台輔，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-51', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，征西將軍馬騰與範謀誅李傕，焉遣叟兵五千助之，漢世謂蜀為叟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-52', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '李傕入長安，欲結術為援，乃授以左將軍，假節，封陽翟侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-53', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '允旣不赦涼州人，由是卓將李傕等遂相結，還攻長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-075-54', 'p0331', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時李傕等購募求布急，楊下諸將皆欲圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-089-55', 'p0331', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-102-56', 'p0331', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-57', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '袁山松書曰：「李傕等攻破長安城，害允等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-58', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至二年春，李傕、郭汜鬬長安中，傕迫劫天子，移置傕塢，盡燒宮殿、城門、官府、民舍，放兵寇鈔公卿以下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-103-59', 'p0331', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時李傕、郭汜專權縱肆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-108-60', 'p0331', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」是時李傕、郭汜專政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a03-109-61', 'p0331', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-001-62', 'p0331', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '卓將李傕、郭汜等殺允攻布，布敗，東出武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-63', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-64', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '及李傕之叛，允乃呼文才、整脩使東解釋之，不假借以溫顏，謂曰：「關東鼠子欲何為邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-65', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：是時新遷都，宮人多亡衣服，帝欲發御府繒以與之，李傕弗欲，曰：「宮中有衣，胡為復作邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-66', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕曰「我邸閣儲偫少」，乃悉載置其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-67', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '多又劫質公卿，所為如是，而君苟欲利郭多，李傕有膽自知之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-68', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」酈言：「我累世受恩，身又常在幃幄，君辱臣死，當坐國家，為李傕所殺，則天命也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-69', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕入長安，欲結術為援，以術為左將軍，封陽翟侯，假節，遣太傅馬日磾因循行拜授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-006-70', 'p0331', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕、郭汜入長安，欲連表為援，乃以表為鎮南將軍、荊州牧，封成武侯，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-007-71', 'p0331', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '由是李傕等遂相結還攻長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-008-72', 'p0331', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-73', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」卓遣李傕等出關東，所過虜略，至潁川、陳留而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-74', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-010-75', 'p0331', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：天子旣東，而李傕來追，王師敗績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-013-76', 'p0331', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '是時，漢帝在西京，李傕、郭汜等亂長安中，與關東斷絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-014-77', 'p0331', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭為太祖作書與長安諸將李傕、郭汜等，各隨輕重致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-017-78', 'p0331', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '布為李傕所敗，從布東奔徐州，領魯相，時年二十八。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-017-79', 'p0331', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '李傕、郭汜之亂長安也，晃說奉，令與天子還洛陽，奉從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-023-80', 'p0331', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '建安初，以奉使率導關中諸將討李傕有功，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-028-81', 'p0331', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '卓將李傕、郭汜等為卓報仇，入長安，殺允，盡害其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-032-82', 'p0331', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '承謂服曰：「郭多有數百兵，壞李傕數萬人，但足下與吾同不耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-83', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '李傕、郭汜相攻，劫質天子公卿，儁性剛，即發病而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-84', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓憚堅猛壯，乃遣將軍李傕等來求和親，令堅列疏子弟任刺史、郡守者，許表用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0331-a04-046-85', 'p0331', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」艾曰：「堅雖時見計，故自不如李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-0', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-1', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-2', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-3', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馮翊羌叛，寇屬縣，郭汜、樊稠擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-4', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-5', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁酉，郭汜攻李傕，矢及御前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-6', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-7', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月戊戌，郭汜使其將伍習夜燒所幸學舍，逼脅乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-8', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-9', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-009-10', 'p0332', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月庚午，李傕、郭汜等追乘輿，戰於東澗，王師敗績，殺光祿勳鄧泉、衞尉士孫瑞、廷尉宣播、大長秋苗祀、獻帝春秋「播」作「璠」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-010b-full-11', 'p0332', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-010b-12', 'p0332', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '帝尋而東歸，李傕、郭汜等追敗乘輿於曹陽，帝乃潛夜度河走，〈度所在今陝州陝縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-027-13', 'p0332', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '時李傕與郭汜相攻，傕遂虜掠禁省，劫帝幸北塢，外內隔絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-027-14', 'p0332', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '今與郭汜爭睚眥之隙，以成千鈞之讎，睚眥，解見竇融傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-054-15', 'p0332', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及李傕、郭汜之亂，彪盡節衞主，崎嶇危難之間，幾不免於害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-056-16', 'p0332', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '李傕、郭汜之亂，長安城潰，百官多避兵衝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-056-17', 'p0332', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-061-18', 'p0332', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及卓將李傕、郭汜攻破長安，遂收琬下獄死，時年五十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-066-19', 'p0332', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」卓部曲將李傕、郭汜等先將兵在關東，因不自安，遂合謀為亂，攻圍長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-066-20', 'p0332', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '宏遣使謂翼曰：「郭汜、李傕以我二人在外，故未危王公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-21', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-22', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-23', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-071-24', 'p0332', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-25', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-26', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-27', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕使兄子利共郭汜、樊稠與騰等戰於長平觀下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-28', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '猶加稠及郭汜開府，與三公合為六府，皆參選舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-29', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」與郭汜相攻連月，死者以萬數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-30', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-31', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-072-32', 'p0332', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-073-33', 'p0332', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-087-34', 'p0332', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '興平元年，馮翊降羌反，寇諸縣，郭汜、樊稠擊破之，斬首數千級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-089-35', 'p0332', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-102-36', 'p0332', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-103-37', 'p0332', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至二年春，李傕、郭汜鬬長安中，傕迫劫天子，移置傕塢，盡燒宮殿、城門、官府、民舍，放兵寇鈔公卿以下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-103-38', 'p0332', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時李傕、郭汜專權縱肆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-108-39', 'p0332', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '」是時李傕、郭汜專政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a03-109-40', 'p0332', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-001-41', 'p0332', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '卓將李傕、郭汜等殺允攻布，布敗，東出武關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-42', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-43', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕對帝，或言「明陛下」，或言「明帝」，為帝說郭汜無狀，帝亦隨其意荅應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-44', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭汜復欲脅天子還都郿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-006-45', 'p0332', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕、郭汜入長安，欲連表為援，乃以表為鎮南將軍、荊州牧，封成武侯，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-007-46', 'p0332', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '英雄記曰：郭汜在城北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-47', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-48', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：郭汜、樊稠與傕互相違戾，欲鬬者數矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-010-49', 'p0332', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：傕時召羌、胡數千人，先以御物繒綵與之，又許以宮人婦女，欲令攻郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-013-50', 'p0332', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '是時，漢帝在西京，李傕、郭汜等亂長安中，與關東斷絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-014-51', 'p0332', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭為太祖作書與長安諸將李傕、郭汜等，各隨輕重致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-017-52', 'p0332', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '李傕、郭汜之亂長安也，晃說奉，令與天子還洛陽，奉從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-028-53', 'p0332', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '卓將李傕、郭汜等為卓報仇，入長安，殺允，盡害其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-046-54', 'p0332', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '李傕、郭汜相攻，劫質天子公卿，儁性剛，即發病而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0332-a04-046-55', 'p0332', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」艾曰：「堅雖時見計，故自不如李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-0', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-1', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-2', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-3', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '八月，馮翊羌叛，寇屬縣，郭汜、樊稠擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-009-4', 'p0333', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，李傕殺樊稠而與郭汜相攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-071-5', 'p0333', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '且傕、汜小豎，樊稠庸兒，無他遠略，又埶力相敵，變難必作。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-071-6', 'p0333', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未發，會李傕殺樊稠，而郭汜又自疑，與傕相攻，長安中亂，故儁止不出，留拜大司農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-7', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕隨道收兵，比至長安，已十餘萬，與卓故部曲樊稠、李蒙等合，袁宏紀曰：「蒙後為傕所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-8', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜、樊稠等皆為將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-9', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '自拜署傕為揚武將軍，汜為揚烈將軍，樊稠等皆為中郎將」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-10', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕令樊稠及兄子利數萬人攻圍槐里，夜梯城，城陷，斬稟梟首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-11', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕使兄子利共郭汜、樊稠與騰等戰於長平觀下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-072-12', 'p0333', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年春，傕因會刺殺樊稠於坐，獻帝紀曰：「傕見稠果勇而得衆心，疾害之，醉酒，潛使外生騎都尉胡封於坐中拉殺稠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a03-087-13', 'p0333', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '興平元年，馮翊降羌反，寇諸縣，郭汜、樊稠擊破之，斬首數千級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-006-14', 'p0333', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與卓故部曲樊稠、李蒙、王方等合圍長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-006-15', 'p0333', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0333-a04-010-16', 'p0333', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '獻帝紀曰：郭汜、樊稠與傕互相違戾，欲鬬者數矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-full-0', 'p0334', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空袁逢罷，太常張濟為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-full-1', 'p0334', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-2', 'p0334', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空袁逢罷，太常張濟為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-008-3', 'p0334', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空張濟罷，大司農張溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-4', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-5', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，李傕自為車騎將軍，郭汜後將軍，樊稠右將軍，張濟鎮東將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-6', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '六月庚午，張濟自陝來和傕、汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-7', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '張濟為票騎將軍，還屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-009-8', 'p0334', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」張濟復反，與李傕、郭汜合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-054-9', 'p0334', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '初，賜與太尉劉寬、司空張濟濟字元江，細陽人也，張酺曾孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-057-10', 'p0334', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '時太尉許戫、司空張濟承望內官，受取貨賂，其宦者子弟賔客雖貪汙穢濁，皆不敢問，而虛糺邊遠小郡清脩有惠化者二十六人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-11', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '輔分遣其校尉李傕、郭汜、張濟將步騎數萬，英雄記：「傕，北地人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-12', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '汜後將軍，稠右將軍，張濟為鎮東將軍，並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-13', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張濟自陝來和解二人，仍欲遷帝權幸弘農。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-14', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '以張濟為驃騎將軍，復還屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-15', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a03-072-16', 'p0334', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張濟飢餓，出至南陽，攻穰，戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-17', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-18', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟與郭多、楊定有謀，又為冠帶所附。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-19', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟自陝和解之，天子乃得出，至新豐、霸陵間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-006-20', 'p0334', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟引兵入荊州界，攻穰城，為流矢所中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0334-a04-010-21', 'p0334', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓敗，輔又死，衆恐懼，校尉李傕、郭汜、張濟等欲解散，間行歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a03-072-0', 'p0335', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓先遣將徐榮、李蒙四出虜掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a03-072-1', 'p0335', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕隨道收兵，比至長安，已十餘萬，與卓故部曲樊稠、李蒙等合，袁宏紀曰：「蒙後為傕所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0335-a04-006-2', 'p0335', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與卓故部曲樊稠、李蒙、王方等合圍長安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-006-0', 'p0336', 'houhanshu', 'a03-006', '《後漢書·卷六》', '四年春正月庚辰，中常侍張逵、蘧政、楊定等有罪誅，事見梁商傳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-009-1', 'p0336', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-009-2', 'p0336', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-3', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '安西將軍楊定者，故卓部曲將也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-4', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-5', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，楊定與煨有隙，遂誣煨欲反，乃攻其營，十餘日不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-6', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '袁宏紀曰：「煨與楊定有隙，煨迎乘輿，不敢下馬，揖馬上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-7', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-072-8', 'p0336', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a03-101-9', 'p0336', 'houhanshu', 'a03-101', '《二十四史-後漢書-志第十一‧天文中》', '其四年正月，祀南郊，夕牲，中常侍張逵、蘧政、楊定、內者令石光、尚方令傅福等與中常侍曹騰、孟賁爭權，白帝言騰、賁與商謀反，矯詔命收騰、賁，賁自解說，順帝寤，解騰、賁縛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0336-a04-006-10', 'p0336', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張濟與郭多、楊定有謀，又為冠帶所附。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-0', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-1', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '楊定、楊奉與郭汜戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-2', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-009-3', 'p0337', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-070-4', 'p0337', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '衆多以山東未定，韓暹、楊奉負功恣睢，恣睢，肆怒貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-070-5', 'p0337', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '韓暹、楊奉，安足恤哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-6', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕將楊奉本白波賊帥，乃將兵救傕，於是汜衆乃退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-7', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遷郭汜車騎將軍，楊定後將軍，楊奉興義將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-8', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-9', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-10', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-072-11', 'p0337', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊奉、韓暹欲要遮車駕，不及，曹操擊之，獻帝春秋曰：「車駕出洛陽，自轘轅而東，楊奉、韓暹引軍追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a03-075-12', 'p0337', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-001-13', 'p0337', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，楊奉、韓暹以天子還洛陽，獻帝春秋曰：天子初至洛陽，幸城西故中常侍趙忠宅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-001-14', 'p0337', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓暹、楊奉專用威命，君則致討，克黜其難，遂遷許都，造我京畿，設官兆祀，不失舊物，天地鬼神於是獲乂，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-006-15', 'p0337', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊奉，白波帥耳，猶知將軍所為非是，將軍雖拜寵之，猶不肯盡力也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-006-16', 'p0337', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕將楊奉與傕軍吏宋果等謀殺傕，事泄，遂將兵叛傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-007-17', 'p0337', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-007-18', 'p0337', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-008-19', 'p0337', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-010-20', 'p0337', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-014-21', 'p0337', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-014-22', 'p0337', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '楊奉近在梁耳，聞其兵精，得無為孤累乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-017-23', 'p0337', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '為郡吏，從車騎將軍楊奉討賊有功，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0337-a04-032-24', 'p0337', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '楊奉、韓暹寇徐、揚閒，先主邀擊，盡斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-0', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-1', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月，韓暹攻衞將軍董承。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-009-2', 'p0338', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-070-3', 'p0338', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '衆多以山東未定，韓暹、楊奉負功恣睢，恣睢，肆怒貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-070-4', 'p0338', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '韓暹、楊奉，安足恤哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-5', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-6', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-7', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-8', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-9', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '操乃詣闕貢獻，稟公卿以下，因奏韓暹、張楊之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-072-10', 'p0338', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊奉、韓暹欲要遮車駕，不及，曹操擊之，獻帝春秋曰：「車駕出洛陽，自轘轅而東，楊奉、韓暹引軍追之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-075-11', 'p0338', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a03-089-12', 'p0338', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '建安元年，獻帝自長安東歸，右賢王去卑與白波賊帥韓暹等侍衞天子，拒擊李傕、郭汜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-001-13', 'p0338', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋七月，楊奉、韓暹以天子還洛陽，獻帝春秋曰：天子初至洛陽，幸城西故中常侍趙忠宅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-001-14', 'p0338', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓暹、楊奉專用威命，君則致討，克黜其難，遂遷許都，造我京畿，設官兆祀，不失舊物，天地鬼神於是獲乂，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-006-15', 'p0338', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-007-16', 'p0338', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-007-17', 'p0338', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術怒，與韓暹、楊奉等連勢，遣大將張勳攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-008-18', 'p0338', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-010-19', 'p0338', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-014-20', 'p0338', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-014-21', 'p0338', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '奉由是失望，與韓暹等到定陵鈔暴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-017-22', 'p0338', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及到洛陽，韓暹、董承日爭鬬，晃說奉令歸太祖；奉欲從之，後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0338-a04-032-23', 'p0338', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '楊奉、韓暹寇徐、揚閒，先主邀擊，盡斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-009-0', 'p0339', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-1', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-2', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-3', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '拜胡才征東將軍，張楊為安國將軍，皆假節、開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a03-072-4', 'p0339', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」胡才、李樂留河東，才為怨家所害，樂自病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0339-a04-006-5', 'p0339', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-009-0', 'p0340', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-1', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承、奉乃譎傕等與連和，而密遣閒使至河東，招故白波帥李樂、韓暹、胡才及南匈奴右賢王去卑，並率其衆數千騎來，與承、奉共擊傕等，大破之，斬首數千級，乘輿乃得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-2', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-3', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李樂懼，欲令車駕御舡過砥柱，出盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-4', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』」使李樂先度具舟舡，舉火為應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-5', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」止於人家，然後幸李樂營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a03-072-6', 'p0340', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」胡才、李樂留河東，才為怨家所害，樂自病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a04-006-7', 'p0340', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '奉急招河東故白波帥韓暹、胡才、李樂等合，與傕、汜大戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0340-a04-006-8', 'p0340', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '及當北渡，使李樂具船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0341-a04-032-0', 'p0341', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0341-a04-036-1', 'p0341', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '及曹公克荊州，假行裨將軍，仍就故任，統屬長沙太守韓玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0342-a04-032-0', 'p0342', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0342-a04-032-1', 'p0342', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '三輔決錄注曰：金旋字元機，京兆人，歷位黃門郎、漢陽太守，徵拜議郎，遷中郎將，領武陵太守，為備所攻劫死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0343-a04-032-0', 'p0343', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0343-a04-036-1', 'p0343', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '從平江南，以為偏將軍，領桂陽太守，代趙範。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-001-0', 'p0344', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '太中大夫徐惲擅殺臨淮太守劉度，惲坐誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-1', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '又武陵蠻夷悉反，寇掠江陵閒，荊州刺史劉度、南郡太守李肅並奔走荊南，皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-2', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '又遣謁者馬睦，督荊州刺史劉度擊之，軍敗，睦、度奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-038-3', 'p0344', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '桓帝詔公卿舉任代劉度者，尚書朱穆舉尚，自右校令擢為荊州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a03-086-4', 'p0344', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '冬，武陵蠻六千餘人寇江陵，荊州刺史劉度、謁者馬睦、南郡太守李肅皆奔走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0344-a04-032-5', 'p0344', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '武陵太守金旋、長沙太守韓玄、桂陽太守趙範、零陵太守劉度皆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-073-0', 'p0345', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹與故虎牙都尉劉勳，首共造兵，勳降服張楊，累有功効，而以小忿枉加酷害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-075-1', 'p0345', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '妻子依故吏廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a03-112-2', 'p0345', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '尋陽有置馬亭，劉勳士衆散處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-001-3', 'p0345', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '廬江太守劉勳率衆降，封為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-001-4', 'p0345', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '於是中軍師王凌、謝亭侯荀攸、前軍師東武亭侯鍾繇、左軍師涼茂、右軍師毛玠、平虜將軍華鄉侯劉勳、建武將軍清苑亭侯劉若、伏波將軍高安侯夏侯惇、揚武將軍都亭侯王忠、奮威將軍樂鄉侯劉展、建忠將軍昌鄉亭侯鮮于輔、奮武將軍安國亭侯程昱、太中大夫都鄉侯賈詡、軍師祭酒千秋亭侯董昭、都亭侯薛洪、南鄉亭侯董蒙、關內侯王粲、傅巽、祭酒王選、袁奐、王朗、張承、任藩、杜襲、中護軍國明亭侯曹洪、中領軍萬歲亭侯韓浩、行驍騎將軍安平亭侯曹仁、領護軍將軍王圖、長史萬潛、謝奐、袁霸等勸進曰：「自古三代，胙臣以土，受命中興，封秩輔佐，皆所以襃功賞德，為國藩衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-002-5', 'p0345', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '甞與平虜將軍劉勳、奮威將軍鄧展等共飲，宿聞展善有手臂，曉五兵，又稱其能空手入白刃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-004-6', 'p0345', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '使保林李華、劉勳等與懷、信等戲，清商令令狐景呵華、勳曰：『諸女，上左右人，各有官職，何以得爾？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-006-7', 'p0345', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '妻子依術故吏廬江太守劉勳，孫策破勳，復見收視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-007-8', 'p0345', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：公孫瓚表列紹罪過云：「紹與故虎牙將軍劉勳首共造兵，勳仍有效，而以小忿枉害於勳，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-008-9', 'p0345', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹與故虎牙都尉劉勳首共造兵，勳仍有効，又降伏張楊，而以小忿枉害於勳，信用讒慝，殺害有功，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-012-10', 'p0345', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '征虜將軍劉勳，貴寵驕豪，又芝故郡將，賔客子弟在界數犯法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-014-11', 'p0345', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄覩漢室漸微，己為支屬，不欲擁兵，遂委其部曲與廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-015-12', 'p0345', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '沛辭去，未到鄴，而軍中豪右曹洪、劉勳等畏沛，各遣家馳騎告子弟，使各自檢勑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-016-13', 'p0345', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜氏新書曰：平虜將軍劉勳，為太祖所親，貴震朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-029-14', 'p0345', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」琅琊劉勳為河內太守，有女年幾二十，左脚膝裏上有瘡，癢而不痛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-15', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」策攻康，拔之，術復用其故吏劉勳為太守，策益失望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-16', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '後術死，長史楊弘、大將張勳等將其衆欲就策，廬江太守劉勳要擊，悉虜之，收其珍寶以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-046-17', 'p0345', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '軍嚴當進，會術死，術從弟胤、女壻黃猗等畏懼曹公，不敢守壽春，乃共舁術棺柩，扶其妻子及部曲男女，就劉勳於皖城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-047-18', 'p0345', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '建安四年，從策征廬江太守劉勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-051-19', 'p0345', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '時策已平吳、會二郡，賁與策征廬江太守劉勳、江夏太守黃祖，軍旋，聞繇病死，過定豫章，上賁領太守，江表傳曰：時丹楊僮芝自署廬陵太守，策留賁弟輔領兵住南昌，策謂賁曰：「兄今據豫章，是扼僮芝咽喉而守其門戶矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-051-20', 'p0345', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '策西襲廬江太守劉勳，輔隨從，身先士卒，有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-054-21', 'p0345', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」復進尋陽，破劉勳，討江夏，還定豫章、廬陵，留鎮巴丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-22', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後拜盪寇中郎將，領零陵太守，從討劉勳於尋陽，進攻黃祖於沙羨，還鎮石城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-23', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從征劉勳，破黃祖，還討鄱陽，領樂安長，山越畏服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-24', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '策破劉勳，多得廬江人，料其精銳，乃以武為督，所向無前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0345-a04-055-25', 'p0345', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從策攻皖，又討劉勳於尋陽，伐黃祖於江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-0', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術大怒，遣其將張勳、橋蕤攻布，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-1', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術聞大駭，即走度淮，留張勳、橋蕤於蘄陽，水經曰：「蘄水出江夏蘄春縣北山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-2', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a03-075-3', 'p0346', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '暹、奉大喜，遂共擊勳等於下邳，大破之，生禽橋蕤，餘衆潰走，其所殺傷、墯水死者殆盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-001-4', 'p0346', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '術聞公自來，棄軍走，留其將橋蕤、李豐、梁綱、樂就；公到，擊破蕤等，皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-001-5', 'p0346', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術僭逆，肆於淮南，懾憚君靈，用丕顯謀，蘄陽之役，橋蕤授首，稜威南邁，術以隕潰，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-006-6', 'p0346', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以張勳、橋蕤等為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-012-7', 'p0346', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '久之，術與橋蕤俱攻圍蘄陽，蘄陽為太祖固守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-017-8', 'p0346', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從擊呂布於濮陽，張超於雍丘，橋蕤於苦，皆先登有功，封廣昌亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-017-9', 'p0346', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從圍橋蕤於苦，斬蕤等四將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-046-0', 'p0347', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '繇遣樊能、于麋屯橫江津，張英屯當利口，以距術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-046-1', 'p0347', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '因渡江攻禮，禮突走，而樊能、于麋等復合衆襲奪牛渚屯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-049-2', 'p0347', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '繇遣樊能、張英屯江邊以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-050-3', 'p0347', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-050-4', 'p0347', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '堅薨，隨孫策討樊能、于麋等於橫江，擊張英於當利口，而船少，欲駐軍更求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-051-5', 'p0347', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '頃之，術復使賁與吳景共擊樊能、張英等，未能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a03-009-0', 'p0350', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五年春正月，車騎將軍董承、偏將軍王服、越騎校尉种輯受密詔誅曹操，事洩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a03-072-1', 'p0350', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承遂與劉備同謀，未發，會備出征，承更與偏將軍王服、長水校尉种輯、議郎吳碩結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-001-2', 'p0350', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '傅子曰：漢末王公，多委王服，以幅巾為雅，是以袁紹、崔豹之徒，雖為將帥，皆著縑巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-002-3', 'p0350', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '夫然，故在三之義惇，臣子之恩篤，雍熈之化隆，經國之道固，聖人之所以通天地，厚人倫，顯至教，敦風俗，斯萬世不易之典，百王服膺之制也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-057-4', 'p0350', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '若使易地而居，亦華戰王服耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-full-0', 'p0351', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '秋七月，射聲校尉馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-full-1', 'p0351', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-2', 'p0351', 'houhanshu', 'a03-008', '《後漢書·卷八》', '秋七月，射聲校尉馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-3', 'p0351', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-4', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '太尉趙謙罷，太常馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-5', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月庚子，太尉馬日磾為太傅，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-6', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」太傅馬日磾薨于壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-054-7', 'p0351', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-064-8', 'p0351', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-064-9', 'p0351', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及李傕專政，使太傅馬日磾撫慰天下，以歧為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-070-10', 'p0351', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，太傅馬日磾奉使山東，及至淮南，數有意於袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-074-11', 'p0351', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '太傅日磾位為師保，任配東征，而耗亂王命，三輔決錄注曰：「馬日磾字翁叔，馬融之族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-006-12', 'p0351', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初平四年，天子使太傅馬日磾、太僕趙岐和解關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-006-13', 'p0351', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕入長安，欲結術為援，以術為左將軍，封陽翟侯，假節，遣太傅馬日磾因循行拜授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-007-14', 'p0351', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '其後尚喪與太傅馬日磾喪俱至京師，天子嘉尚忠烈，為之咨嗟，詔百官弔祭，拜子瑋郎中，而日磾不與焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-013-15', 'p0351', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '歆欲棄去，會天子使太傅馬日磾安集關東，日磾辟歆為掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-046-16', 'p0351', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '太傅馬日磾杖節安集關東，在壽春以禮辟策，表拜懷義校尉，術大將喬蕤、張勳皆傾心敬焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-056-17', 'p0351', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時太傅馬日磾在壽春，辟治為掾，遷吳郡都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-057-18', 'p0351', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '策旣定豫章，引軍還吳，饗賜將士，計功行賞，謂翻曰：「孤昔再至壽春，見馬日磾，及與中州士大夫會，語我東方人多才耳，但恨學問不博，語議之間，有所不及耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-035-0', 'p0352', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '及黨事起，乃與同郡孫嵩等四十餘人俱被禁錮，嵩字賔石，見趙岐傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-049-1', 'p0352', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」趙岐注云：「餓死者曰莩」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-049-2', 'p0352', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」趙岐注云：「貊，夷貊之人在荒者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-052-3', 'p0352', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」趙岐注云：「摟，牽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-058-4', 'p0352', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」趙岐注曰：「浩然，天氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-059-5', 'p0352', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」趙岐注云：「志士，守義者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-059-6', 'p0352', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '』」趙岐注云：「兼金，好金也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-070-7', 'p0352', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '趙岐注孟子曰：「倒縣猶困苦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-074-8', 'p0352', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '四年初，天子遣太僕趙岐和解關東，使各罷兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-074-9', 'p0352', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '太僕趙岐銜命來征，宣明陛下含弘之施，蠲除細故，與下更新，奉詔之日，引師南轅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-006-10', 'p0352', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '僕與太傅馬公、太僕趙岐、少府陰脩俱受詔命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-006-11', 'p0352', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初平四年，天子使太傅馬日磾、太僕趙岐和解關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-010-12', 'p0352', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '象同郡趙岐作三輔決錄，恐時人不盡其意，故隱其書，唯以示象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-018-13', 'p0352', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '至興平中，趙岐以太僕持節使安慰天下，南詣荊州，乃復與賔碩相遇，相對流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-009-0', 'p0353', 'houhanshu', 'a03-009', '《後漢書·卷九》', '封衞將軍董承為輔國將軍伏完等十三人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-010b-full-1', 'p0353', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '皇女華，延熹元年封陽安長公主，適不其侯輔國將軍伏完。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-2', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-3', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '於是封衞將軍董承、輔國將軍伏完等十餘人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-4', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-072-0', 'p0354', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓先遣將徐榮、李蒙四出虜掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-072-1', 'p0354', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-074-2', 'p0354', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」魏志曰：「操引兵西，將據成臯，到滎陽汴水，遇卓將徐榮，戰不利，士卒死傷多，操為流矢所中，所乘馬被創。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-001-3', 'p0354', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '到熒陽汴水，遇卓將徐榮，與戰不利，士卒死傷甚多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-008-4', 'p0354', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '同郡徐榮為董卓中郎將，薦度為遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-009-5', 'p0354', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖起義兵討董卓，至熒陽，為卓將徐榮所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-032-0', 'p0355', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-032-1', 'p0355', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後十餘日，陸議大破先主軍於猇亭，將軍馮習、張南等皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-055-2', 'p0355', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-058-3', 'p0355', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-058-4', 'p0355', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '一爾勢成，通率諸軍同時俱攻，斬張南、馮習及胡王沙摩柯等首，破其四十餘營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a03-047-0', 'p0356', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '是時于窴王廣德新攻破莎車，遂雄張南道，于窴國去長安九千六百七十里，南與婼羌，西與姑墨接。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-001-1', 'p0356', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是月，袁熙大將焦觸、張南等叛攻熙、尚，熙、尚奔三郡烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-006-2', 'p0356', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '熈、尚為其將焦觸、張南所攻，奔遼西烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-032-3', 'p0356', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後十餘日，陸議大破先主軍於猇亭，將軍馮習、張南等皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-058-4', 'p0356', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-058-5', 'p0356', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '一爾勢成，通率諸軍同時俱攻，斬張南、馮習及胡王沙摩柯等首，破其四十餘營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a05-011-6', 'p0356', 'jinshu', 'a05-011', '《晉書·卷十一》', '張南十四星曰天廟，天子之祖廟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0357-a04-045-0', 'p0357', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時又有義陽傅肜，先主退軍，斷後拒戰，兵人死盡，吳將語肜令降，肜罵曰：「吳狗！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0357-a04-058-1', 'p0357', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0360-a04-029-0', 'p0360', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」謂曹彪曰：「君據藩國，至五十七當厄於兵，宜善防之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0360-a04-029-1', 'p0360', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '曹彪封楚王，年五十七，坐與王淩通謀，賜死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0362-a05-019-0', 'p0362', 'jinshu', 'a05-019', '《晉書·卷十九》', '兼侍中散騎常侍荀奕、兼黃門侍郎散騎侍郎曹宇駁曰：「尚書三公曹奏讀秋令，儀注舊典未備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-003-0', 'p0365', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '中書監劉放、令孫資久專權寵，為朗等素所不善，懼有後害，陰圖間之，而宇常在帝側，故未得有言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-003-1', 'p0365', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略曰：帝旣從劉放計，召司馬宣王，自力為詔，旣封，顧呼宮中常所給使者曰：「辟邪來！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-2', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '正始元年春二月乙丑，加侍中中書監劉放、侍中中書令孫資為左右光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-3', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，以左光祿大夫劉放為驃騎將軍，右光祿大夫孫資為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-4', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九年春二月，衞將軍中書令孫資，癸巳，驃騎將軍中書監劉放，三月甲午，司徒衞臻，各遜位，以侯就第，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-009-5', 'p0365', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」於是帝使中書監劉放令孫資為詔曰：「昔吳漢佐光武，有征定四方之功，為大司馬，名稱于今。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-014-6', 'p0365', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放字子棄，涿郡人，漢廣陽順王子西鄉侯宏後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-014-7', 'p0365', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放文翰，孫資勤慎，並管喉舌，權聞當時，雅亮非體，是故譏諛之聲，每過其實矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-025-8', 'p0365', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '時中書監劉放、令孫資見信於主，制斷時政，大臣莫不交好，而毗不與往來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-028-9', 'p0365', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-028-10', 'p0365', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '中書令劉放、侍郎衞瓘、夏侯和等家皆怪問：『夫人一子在危難之中，何能無憂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-036-full-11', 'p0365', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄉人劉放亦奇其才，以女妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-036-12', 'p0365', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄉人劉放亦奇其才，以女妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-039-13', 'p0365', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時議以勖傾國害時，孫資、劉放之匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-003-0', 'p0366', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及還，帝引見慰勞之，顧謂中書令孫資曰：「卿鄉里乃有爾曹快人，為將灼如此，朕復何憂乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-003-1', 'p0366', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '中書監劉放、令孫資久專權寵，為朗等素所不善，懼有後害，陰圖間之，而宇常在帝側，故未得有言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-2', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '正始元年春二月乙丑，加侍中中書監劉放、侍中中書令孫資為左右光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-3', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，以左光祿大夫劉放為驃騎將軍，右光祿大夫孫資為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-4', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九年春二月，衞將軍中書令孫資，癸巳，驃騎將軍中書監劉放，三月甲午，司徒衞臻，各遜位，以侯就第，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-5', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，以特進孫資為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-6', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚子，驃騎將軍孫資薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-009-7', 'p0366', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」於是帝使中書監劉放令孫資為詔曰：「昔吳漢佐光武，有征定四方之功，為大司馬，名稱于今。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-8', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏國旣建，與太原孫資俱為祕書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-9', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '令孫資對曰：「上谷太守閻志，柔弟也，為比能素所歸信。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-10', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放文翰，孫資勤慎，並管喉舌，權聞當時，雅亮非體，是故譏諛之聲，每過其實矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-015-11', 'p0366', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會諸葛亮出，緝上便宜，詔以問中書令孫資，資以為有籌略，遂召拜騎都尉，遣參征蜀軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-015-12', 'p0366', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '孫資別傳曰：資舉河東計吏，到許，薦於相府曰：「逵在絳邑，帥厲吏民，與賊郭援交戰，力盡而敗，為賊所俘，挺然直志，顏辭不屈；忠言聞於大衆，烈節顯于當時，雖古之直髮、據鼎，罔以加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-025-13', 'p0366', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '時中書監劉放、令孫資見信於主，制斷時政，大臣莫不交好，而毗不與往來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-028-14', 'p0366', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a05-039-15', 'p0366', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時議以勖傾國害時，孫資、劉放之匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a03-014-0', 'p0367', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '立十年薨，子哀王基嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a03-035-1', 'p0367', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '其門人山陽郗慮至御史大夫，東萊王基、清河崔琰著名於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-002-2', 'p0367', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '昔漢祖以秦中為國本，光武恃河內為王基，今朕復於此登壇受禪，天以此郡翼成大魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-004-3', 'p0367', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三年春正月，荊州刺史王基、新城太守州泰攻吳，破之，降者數千口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-011-4', 'p0367', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，脩識高柔於弱冠，異王基於幼童，終皆遠至，世稱其知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-011-5', 'p0367', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '正始二年，太僕陶丘一、永寧衞尉孟觀、侍中孫邕、中書侍郎王基薦寧曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-6', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '」乃遣新城太守州泰襲巫、秭歸、房陵，荊州刺史王基詣夷陵，昶詣江陵，兩岸引竹絙為橋，渡水擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-7', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '王基字伯輿，東萊曲城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-8', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '詔征南將軍王基部分諸軍，使烈督萬人徑造沮水，荊州、義陽南屯宜城，承書夙發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-9', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '晉室踐阼，下詔曰：「故司空王基旣著德立勳，又治身清素，不營產業，乆在重任，家無私積，可謂身沒行顯，足用勵俗者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-10', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-11', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍屯汝陽，使監軍王基督前鋒諸軍據南頓以待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-12', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '小人還項，復遇王基等十二軍，追尋毌丘，進兵討之，即時克破，所向全勝，要那後無繼何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-13', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '是時鎮南將軍王基始至，督諸軍圍壽春，未合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-14', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '而未及安坐，喪王基之功，種惠吳人，結異類之情，寵鴦葬欽，忘疇昔之隙，不咎誕衆，使揚士懷愧，功高而人樂其成，業廣而敵懷其德，武昭旣敷，文筭又洽，推此道也，天下其孰能當之哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-029-15', 'p0367', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅往見安平太守王基，基令作卦，輅曰：「當有賤婦人生一男兒，墯地便走入竈中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-029-16', 'p0367', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅別傳曰：王基即遣信都令遷掘其室中，入地八尺，果得二棺，一棺中有矛，一棺中有角弓及箭，箭乆遠，木皆消爛，但有鐵及角完耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-047-17', 'p0367', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-048-18', 'p0367', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳桓王基之以武，太祖成之以德，聦明睿達，懿度深遠矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-056-19', 'p0367', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '加討虜聦明神武，繼承洪業，攬結英雄，周濟世務，軍衆日盛，事業日隆，雖昔蕭王之在河北，無以加也，必克成王基，應運東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-064-20', 'p0367', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏鎮南將軍王基圍誕，欽等突圍入城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-21', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-22', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '儉、欽移入項城，帝遣荊州刺史王基進據南頓以逼儉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-23', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '石苞、王基並請攻之，帝曰：「誕之逆謀，非一朝一夕也，聚糧完守，外結吳人，自謂足據淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-24', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '四年夏六月，分荊州置二都督，王基鎮新野，州泰鎮襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-006-25', 'p0367', 'jinshu', 'a05-006', '《晉書·卷六》', '詔曰：「昔我高祖宣皇帝誕應期運，廓開王基。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-001-0', 'p0368', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '王昶家誡曰「濟陰魏諷」，而此云沛人，未詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-1', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙未，征南將軍王昶渡江，掩攻吳，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-2', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月甲申，以征南將軍王昶為征南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-3', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月，詔征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-4', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：毌丘儉、王昶聞東軍敗，各燒屯走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-5', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲戌，以征南大將軍王昶為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-6', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋八月甲戌，以驃騎將軍王昶為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-014-7', 'p0368', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '弈字伯益，見王昶家誡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-021-8', 'p0368', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '兖州刺史王昶請與相見，終日不得與言，昶歎賞之，自以不能測也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-021-9', 'p0368', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等表請征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-022-10', 'p0368', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '遷為司空，固推驃騎將軍王昶、光祿大夫王觀、司隷校尉王祥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-11', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '魏名臣奏載黃門侍郎杜恕表，稱：「韓觀、王昶，信有兼才，高官重任，不但三州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-12', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '王昶字文舒，太原晉陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-13', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '其年為尚書，出為荊州刺史，加揚烈將軍，隨征南王昶擊吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-14', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-029-15', 'p0368', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '惟相司空王昶、征北將軍程喜、中領軍王肅有蹉跌云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-047-16', 'p0368', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-048-17', 'p0368', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-056-18', 'p0368', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，魏征南將軍王昶率衆攻江陵城，不克而退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a05-002-19', 'p0368', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-004-0', 'p0369', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月，以司空高柔為司徒；光祿大夫徐邈為司空，固辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-008-1', 'p0369', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '州里徐邈責之曰：「不孝莫大於無後，何可終身不娶乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-014-2', 'p0369', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '如征東將軍滿寵、涼州刺史徐邈，並有譖毀之者，資皆盛陳其素行，使卒無纖介。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-024-3', 'p0369', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '及曁年過八十，起家就列；柔保官二十年，元老終位：比之徐邈、常林，於茲為疚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-4', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '徐邈字景山，燕國薊人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-5', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-6', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a05-019-7', 'p0369', 'jinshu', 'a05-019', '《晉書·卷十九》', '」祠部郎中徐邈議：「圓丘郊祀，繼典無二，宣皇帝嘗辯斯義，而檢以聖典。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a05-042-8', 'p0369', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '刺史燕國徐邈有女才淑，擇夫未嫁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-003-0', 'p0370', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-014-1', 'p0370', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖徵曄及蔣濟、胡質等五人，皆揚州名士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-015-2', 'p0370', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和二年，帝使逵督前將軍滿寵、東莞太守胡質等四軍，從西陽直向東關，曹休從皖，司馬宣王從江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-022-3', 'p0370', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '蜀大將軍姜維率衆依麴山築二城，使牙門將句安、李歆等守之，聚羌胡質任等寇偪諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-4', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-5', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '胡質字文德，楚國壽春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-6', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-056-7', 'p0370', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏將蒲忠、胡質各將數千人，忠要遮險隘，圖斷然後，質為忠繼援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-056-8', 'p0370', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫氏異同評曰：魏志及江表傳云然以景初元年、正始二年再出為寇，所破胡質、蒲忠在景初元年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-011-0', 'p0371', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '論曰：周武王觀兵孟津，退而還師，以為紂未可伐，斯時有未至者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-036-1', 'p0371', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '史記曰，武王觀兵孟津，諸侯不期而至者八百人，皆曰：「紂可伐矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-057-2', 'p0371', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '是以先王觀象育物，敬授民時，象，天象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-004-3', 'p0371', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸亥，以尚書右僕射王觀為司空，冬十月，觀薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-022-4', 'p0371', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '遷為司空，固推驃騎將軍王昶、光祿大夫王觀、司隷校尉王祥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-024-5', 'p0371', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '王觀字偉臺，東郡廩丘人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-024-6', 'p0371', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-063-7', 'p0371', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '昔聖王觀天地之文，以畫八卦之象，故亹亹成於蓍策，變化形乎六爻，是以三易雖殊，卦繇理一，安有迴轉一籌，可以鉤深測隱，意對逆占，而能遂知來物者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a05-001-8', 'p0371', 'jinshu', 'a05-001', '《晉書·卷一》', '」命太僕王觀行中領軍，攝羲營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-003-0', 'p0372', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '西平麴英反，殺臨羌令、西都長，遣將軍郝昭、鹿磐討斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-003-1', 'p0372', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略曰：先是使將軍郝昭築陳倉城；會亮至，圍昭，不能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-009-2', 'p0372', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '真以亮懲於祁山，後出必從陳倉，乃使將軍郝昭、王生守陳倉，治其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-016-3', 'p0372', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '又將軍郝昭、魏平先是各屯守金城，亦受詔不得西度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-033-0', 'p0373', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏將王雙率軍追亮，亮與戰，破之，斬雙，還漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-035-1', 'p0373', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏將王雙率騎追亮，亮與戰，破之，斬雙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-035-2', 'p0373', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '前年耀師，馘斬王雙；今歲爰征，郭淮遁走；降集氐、羌，興復二郡，威鎮凶暴，功勳顯然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-056-3', 'p0373', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '仁果遣其子泰攻濡須城，分遣將軍常雕督諸葛虔、王雙等，乘油船別襲中洲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-005-0', 'p0374', 'jinshu', 'a05-005', '《晉書·卷五》', '王浚遣鮮卑文鴦帥騎救之，勒退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-039-1', 'p0374', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '永嘉中，石勒寇冀州，浚遣鮮卑文鴦討勒，勒走南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-039-2', 'p0374', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '使者未及發，會洛京傾覆，浚大樹威令，專征伐，遣督護王昌、中山太守阮豹等，率諸軍及務勿塵世子疾陸眷、并弟文鴦、從弟末柸，攻石勒於襄國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0375-a03-085-0', 'p0375', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '山海經曰：「君子國衣冠帶劔，食獸，使二文虎在旁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0375-a03-119-1', 'p0375', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」文虎伏軾，魏都賦注曰：「軾，車橫覆膝，人所馮止者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-034-0', 'p0376', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '故太保衛瓘本爵菑陽縣公，既被橫害，乃進茅土，始贈蘭陵，又轉江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-039-1', 'p0376', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '先是，勖啟「伐蜀，宜以衛瓘爲監軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-039-2', 'p0376', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '尚書令衛瓘、吏部尚書山濤皆可爲司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-040-3', 'p0376', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '及楚王瑋矯詔害汝南王亮、太保衛瓘，詔使模將中騶二百人救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a03-096-0', 'p0377', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」晉起居注曰：「太尉賈充薨，皇太子妃之父，又太保也，有司奏依漢元明二帝親臨師保故事，皇太子素服為發哀，又臨其喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-1', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '中護軍賈充又逆帝戰於南闕下，帝自用劒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-2', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　干寶晉紀曰：成濟問賈充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-3', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '賈充自外而入，帝師潰散，猶稱天子，手劒奮擊，衆莫敢逼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-4', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏末傳曰：賈充呼帳下督成濟謂曰：「司馬家事若敗，汝等豈復有種乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-010-5', 'p0377', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '與賈充共定音律，又作易集解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-022-6', 'p0377', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」對曰：「誅賈充以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-022-7', 'p0377', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」泰曰：「獨有斬賈充，少可以謝天下耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-8', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：司馬文王旣秉朝政，長史賈充以為宜遣參佐慰勞四征，於是遣充至壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-9', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '魏末傳曰：賈充與誕相見，談說時事，因謂誕曰：「洛中諸賢，皆願禪代，君所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-10', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會得文王書云：「恐鄧艾或不就徵，今遣中護軍賈充將步騎萬人徑入斜谷，屯樂城，吾自將十萬屯長安，相見在近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-11', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '晏旣用賈充、裴秀、朱整，又議用弼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-033-12', 'p0377', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '王謂賈充曰：「人之無情，乃可至於是乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-048-13', 'p0377', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」旣至，車騎將軍賈充、尚書令裴秀、侍中荀勗等欲傲以所不知而不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-048-14', 'p0377', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-15', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '沈、業馳告于帝，帝召護軍賈充等為之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-16', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '相府兵將止不敢戰，賈充叱諸將曰：「公畜養汝輩，正為今日耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-17', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '」泰曰：「惟腰斬賈充，微以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-18', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '是時魏諸王侯悉在鄴城，命從事中郎山濤行軍司事，鎮於鄴，遣護軍賈充持節、督諸軍，據漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-19', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '秋七月，帝奏司空荀顗定禮儀，中護軍賈充正法律，尚書僕射裴秀議官制，太保鄭沖總而裁焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-20', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '」九月戊午，以魏司徒何曾為丞相，鎮南將軍王沈為御史大夫，中護軍賈充為衞將軍，議郎裴秀為尚書令、光祿大夫，皆開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-21', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以驃騎將軍石苞為大司馬，封樂陵公，車騎將軍陳騫為高平公，衞將軍賈充為車騎將軍、魯公，尚書令裴秀為鉅鹿公，侍中荀勗為濟北公，太保鄭冲為太傅、壽光公，太尉王祥為太保、睢陵公，丞相何曾為太尉、朗陵公，御史大夫王沈為驃騎將軍、愽陵公，司空荀顗為臨淮公，鎮北大將軍衞瓘為菑陽公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-22', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '秋七月癸酉，以車騎將軍賈充為都督秦、涼二州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-23', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '秋七月，以車騎將軍賈充為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-24', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以故太傅鄭沖、太尉荀顗、司徒石苞、司空裴秀、驃騎將軍王沈、安平獻王孚等及太保何曾、司空賈充、太尉陳騫、中書監荀勗、平南將軍羊祜、齊王攸等皆列於銘饗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-25', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '己亥，以太保何曾為太傅，太尉陳騫為大司馬，司空賈充為太尉，鎮軍大將軍齊王攸為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-26', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以太尉賈充為大都督，行冠軍將軍楊濟為副，總統衆軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-27', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-28', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '夏四月庚午，太尉、魯公賈充薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-29', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '況以新習易動之基，而無久安難拔之慮，故賈充凶豎，懷姦志以擁權；楊駿豺狼，苞禍心以專輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-005-30', 'p0377', 'jinshu', 'a05-005', '《晉書·卷五》', '察庾純、賈充之爭，而見師尹之多僻；考平吳之功，而知將帥之不讓；思郭欽之謀，而寤戎狄有釁；覽傅玄、劉毅之言，而得百官之邪；核傅咸之奏、錢神之論，而覩寵賂之彰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-31', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」時王佑、賈充、裴秀皆前朝名望，祜每讓，不處其右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-32', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '暨弟伊，初爲車騎賈充掾，後歷平南將軍、都督江北諸軍事，鎮宛，爲張昌所殺，追贈鎮南將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-33', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '與車騎將軍賈充等定律令，既成，預爲之注解，乃奏之曰：「法者，蓋繩墨之斷例，非窮理盡性之書也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-036-full-34', 'p0377', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '眾軍既進，而未有克獲，賈充等奏誅華以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-036-35', 'p0377', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '眾軍既進，而未有克獲，賈充等奏誅華以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-36', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈以才望，顯名當世，是以創業之事，羊祜、荀勖、裴秀、賈充等，皆與沈諮謀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-37', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '顗明三禮，知朝廷大儀，而無質直之操，唯阿意苟合於荀勖、賈充之間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-38', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '初，皇太子將納妃，顗上言賈充女姿德淑茂，可以參選，以此獲譏於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-39', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '拜中書監，加侍中，領著作，與賈充共定律令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-40', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及王濬表請伐吳，勖與賈充固諫不可，帝不從，而吳果滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-41', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」時太尉賈充、司徒李胤並薨，太子太傅又缺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-42', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '承顏悅色，寵愛日隆，賈充、荀勖並與之親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-43', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '初謀伐吳，紞與賈充、荀勖同共苦諫不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-44', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '賈充字公閭，平陽襄陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-45', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '車騎將軍賈充，獎明聖意，諮詢善道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-46', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '侍中、守尚書令、車騎將軍賈充，雅量弘高，達見明遠，武有折衝之威，文懷經國之慮，信結人心，名震域外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-47', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '美姿貌，善容止，賈充辟爲司空掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-48', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '與賈充素相親遇，充妻待彰若同生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-49', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '史臣曰：賈充以諂諛陋質，刀筆常材，幸屬昌辰，濫叨非據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-042-50', 'p0377', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '賈充、荀勖陳諫以爲不可，唯張華固勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-074-0', 'p0378', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '張華云：「望夷之宮在長陵西北長平觀，東臨涇水，作之以望北夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-080-1', 'p0378', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '張華博物志曰：「王子山與父叔師到泰山從鮑子真學筭，到魯賦靈光殿，歸度湘水溺死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-093-2', 'p0378', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '天誘其衷，得備著作郎，建言十志皆當撰錄，遂與議郎張華等分受之，其難者皆以付臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-096-3', 'p0378', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '司空張華以問博士束皙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-110-4', 'p0378', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '邯鄲張華曰：「趙奢冢在邯鄲西山上，謂之馬服山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-001-5', 'p0378', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張華博物志曰：漢世，安平崔瑗、瑗子寔、弘農張芝、芝弟昶並善草書，而太祖亞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-014-6', 'p0378', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '與張華六人，並稱文辭可觀，意思詳序。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-022-7', 'p0378', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '同郡張華，家單少孤，不為鄉邑所知，惟欽貴異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-022-8', 'p0378', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '晉諸公贊曰：張華博識多聞，無物不知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-026-9', 'p0378', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後張華請為長史，稍遷至尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-045-10', 'p0378', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '後失荀勗、張華指，左遷漢中太守，諸王多以為冤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-047-11', 'p0378', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '司空張華辟，未就，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-058-12', 'p0378', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '機雲別傳曰：晉太康末，俱入洛，造司空張華，華一見而奇之，曰：「伐吳之役，利在獲二儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-003-13', 'p0378', 'jinshu', 'a05-003', '《晉書·卷三》', '甲午，以尚書張華都督幽州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-004-14', 'p0378', 'jinshu', 'a05-004', '《晉書·卷四》', '以中書監張華為司空，太尉、隴西王泰為尚書令，衞將軍、梁王肜為太子太保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-004-15', 'p0378', 'jinshu', 'a05-004', '《晉書·卷四》', '癸巳，梁王肜、趙王倫矯詔廢賈后為庶人，司空張華、尚書僕射裴頠皆遇害，侍中賈謐及黨與數十人皆伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-012-16', 'p0378', 'jinshu', 'a05-012', '《晉書·卷十二》', '」後賈后陷殺太子，趙王廢后，又殺之，斬張華、裴頠，遂篡位，廢帝為太上皇，天下從此遘亂連禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-17', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是月，賈后殺太子，趙王倫尋廢殺后，斬司空張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-18', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '後五年，司空張華遇禍，賈后廢死，魯公賈謐誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-19', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是月賈后殺太子，趙王倫尋廢殺后，斬司空張華，又廢帝自立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-016-20', 'p0378', 'jinshu', 'a05-016', '《晉書·卷十六》', '泰始十年，中書監荀勗、中書令張華出御府銅竹律二十五具，部太樂郎劉秀等校試，其三具與杜夔及左延年律法同，其二十二具，視其銘題尺寸，是笛律也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-21', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '帝以其病，不宜常入，遣中書令張華問其籌策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-22', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '時帝密有滅吳之計，而朝議多違，唯預、羊祜、張華與帝意合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-23', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」時帝與中書令張華圍棋，而預表適至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-24', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '張華字茂先，范陽方城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-25', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-26', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '後倫、秀伏誅，齊王冏輔政，摯虞致箋於冏曰：「間於張華沒後入中書省，得華先帝時答詔本草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-27', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '張華、裴頠各以見憚取誅於時，解系、解結同以羔羊並被其害，歐陽建等無罪而死，百姓憐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-28', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '以計干張華而不見用，益以不平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-29', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '衞瓘撫武帝之牀，張華距趙倫之命，進諫則伯玉居多，臨危則茂先爲美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-30', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '張華字茂先，范陽方城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-31', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-32', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '後倫、秀伏誅，齊王冏輔政，摯虞致箋於冏曰：「間於張華沒後入中書省，得華先帝時答詔本草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-33', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '張華、裴頠各以見憚取誅於時，解系、解結同以羔羊並被其害，歐陽建等無罪而死，百姓憐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-34', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '以計干張華而不見用，益以不平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-35', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '衞瓘撫武帝之牀，張華距趙倫之命，進諫則伯玉居多，臨危則茂先爲美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-039-36', 'p0378', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '俄領祕書監，與中書令張華依劉向別錄，整理記籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-039-37', 'p0378', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '吳平，紞內懷慚懼，疾張華如讎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-38', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '雖腰斬張華，不足以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-39', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '於是事下三府，司徒王戎、司空張華、領軍將軍王衍、侍中樂廣、黃門侍郎嵇紹、國子博士謝衡皆從謐議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-40', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '今吳寇當平，汝方表斬張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-41', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '模乃盡心匡弼，推張華、裴頠同心輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-42', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '珧臨刑稱冤，云：「事在石函，可問張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-042-43', 'p0378', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '賈充、荀勖陳諫以爲不可，唯張華固勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a03-054-0', 'p0379', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '其夜有黃衣童子向寶再拜曰：『我西王母使者，君仁愛救拯，實感成濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-1', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '衆欲退，太子舍人成濟問充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-2', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　干寶晉紀曰：成濟問賈充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-3', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '充帥厲將士，騎督成倅弟成濟以矛進，帝崩于師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-4', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏末傳曰：賈充呼帳下督成濟謂曰：「司馬家事若敗，汝等豈復有種乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-5', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '皇太后令曰：「吾以不德，遭家不造，昔援立東海王子髦，以為明帝嗣，見其好書疏文章，兾可成濟，而情性暴戾，日月滋甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-6', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」魏氏春秋曰：成濟兄弟不即伏罪，袒而升屋，醜言悖慢；自下射之，乃殪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-021-7', 'p0379', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '山濤啟以為祕書郎，稱紹平簡溫敏，有文思，又曉音，當成濟者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-002-8', 'p0379', 'jinshu', 'a05-002', '《晉書·卷二》', '」太子舍人成濟抽戈犯蹕，刺之，刃出於背，天子崩于車中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-002-9', 'p0379', 'jinshu', 'a05-002', '《晉書·卷二》', '」於是歸罪成濟而斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-013-10', 'p0379', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年五月，有成濟之變及諸葛誕誅，皆其應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-013-11', 'p0379', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年，高貴鄉公為成濟所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-040-12', 'p0379', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '初，充母柳見古今重節義，竟不知充與成濟事，以濟不忠，數追罵之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0380-a04-005-0', 'p0380', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '文昭甄皇后，中山無極人，明帝母，漢太保甄邯後也，世吏二千石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-029-0', 'p0381', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '及郭皇后廢，建武十七年廢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-042-1', 'p0381', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '光武皇帝十一子：郭皇后生東海恭王彊、沛獻王輔、濟南安王康、阜陵質王延、中山簡王焉，許美人生楚王英，光烈皇后生顯宗、東平憲王蒼、廣陵思王荊、臨淮懷公衡、琅邪孝王京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-100-2', 'p0381', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '是時郭皇后已疏，至十七年十月，遂廢為中山太后，立陰貴人為皇后，除宮之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-108-3', 'p0381', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '其十月，廢郭皇后，詔曰「不可以奉供養」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a04-005-4', 'p0381', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '文德郭皇后，安平廣宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a04-005-5', 'p0381', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明元郭皇后，西平人也，世河右大族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0382-a04-005-0', 'p0382', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明悼毛皇后，河內人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0383-a04-028-0', 'p0383', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0383-a04-051-1', 'p0383', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫靜字幼臺，堅季弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0384-a04-032-0', 'p0384', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」權不聽，遣孫瑜率水軍住夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0384-a04-054-1', 'p0384', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '十一年，督孫瑜等討麻、保二屯，梟其渠帥，囚俘萬餘口，還備官亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-046-0', 'p0385', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '盡更置長吏，策自領會稽太守，復以吳景為丹楊太守，以孫賁為豫章太守；分豫章為廬陵郡，以賁弟輔為廬陵太守，丹楊朱治為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-046-1', 'p0385', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '書授孫賁以長沙，業張津以零、桂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-049-2', 'p0385', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '欲南渡江，吳景、孫賁迎置曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-050-3', 'p0385', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a03-069-0', 'p0386', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '武孫輔，時年二歲，逃竄得全。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a04-051-1', 'p0386', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫輔字國儀，賁弟也，以揚武校尉佐孫策平三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a04-063-2', 'p0386', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '遭亂避地，客遊廬陵，事孫輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a05-004-3', 'p0386', 'jinshu', 'a05-004', '《晉書·卷四》', '倫遣其將閭和出伊闕，張泓、孫輔出堮坂以距囧，孫會、士猗、許超出黃橋以距穎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a05-004-4', 'p0386', 'jinshu', 'a05-004', '《晉書·卷四》', '囧將何勗、盧播擊張泓於陽翟，大破之，斬孫輔等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-050-0', 'p0387', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳主權步夫人，臨淮淮陰人也，與丞相隲同族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-050-1', 'p0387', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及步夫人薨，權欲立之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-059-2', 'p0387', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '初，登所生庶賤，徐夫人少有母養之恩，後徐氏以妬廢處吳，而步夫人最寵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a03-047-0', 'p0391', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '前書曰，漢遣公主為烏孫夫人，結為昆弟，則是斷匈奴右臂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-034-1', 'p0391', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '先主旣定益州，而孫夫人還吳，漢晉春秋云：先主入益州，吳遣迎孫夫人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-036-2', 'p0391', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '此時先主孫夫人以權妹驕豪，多將吳吏兵，縱橫不法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-037-3', 'p0391', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0393-a04-045-0', 'p0393', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '－－贊糜芳、士仁、郝普、潘濬糜芳字子方，東海人也，為南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0393-a04-047-1', 'p0393', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '六月，權令將軍賀齊督糜芳、劉邵等襲蘄春，邵等生虜宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0394-a04-036-0', 'p0394', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '又南郡太守麋芳在江陵，將軍傅士仁屯公安，素皆嫌羽自輕己。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-026-0', 'p0395', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '姜維出石營，從彊川，乃西迎治無戴，留陰平太守廖化於成重山築城，斂破羌保質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-026-1', 'p0395', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '比歲以來，摧破廖化，禽虜句安，功績顯著，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-2', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '三日，維遣廖化自白水南向艾結營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-3', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '未到，聞其已破，退趣白水，與蜀將張翼、廖化等合守劒閣拒會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-4', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-033-5', 'p0395', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-043-6', 'p0395', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '華陽國志曰：後張翼、廖化並為大將軍，時人語曰：「前有王、句，後有張、廖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-044-7', 'p0395', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-044-8', 'p0395', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-9', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時都護諸葛瞻初統朝事，廖化過預，欲與預共詣瞻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-10', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '廖化字元儉，本名淳，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-11', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '漢晉春秋曰：景耀五年，姜維率衆出狄道，廖化曰：「『兵不戢，必自焚』，伯約之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a05-002-12', 'p0395', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-035-0', 'p0396', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮卒後，稍遷至尚書僕射，代陳祗為尚書令，遷大將軍，平臺事，而義陽樊建代焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-036-1', 'p0396', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-039-2', 'p0396', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳祗代允為侍中，與黃皓互相表裏，皓始預政事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-042-3', 'p0396', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '于時軍旅數出，百姓彫瘁，周與尚書令陳祗論其利害，退而書之，謂之仇國論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-028-0', 'p0397', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-033-1', 'p0397', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-2', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '景耀四年，為行都護衞將軍，與輔國大將軍南鄉侯董厥並平尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-3', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '董厥者，丞相亮時為府令史，亮稱之曰：「董令史，良士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-4', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '案晉百官表：董厥字龔襲，亦義陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-044-5', 'p0397', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-033-0', 'p0398', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-1', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮卒後，稍遷至尚書僕射，代陳祗為尚書令，遷大將軍，平臺事，而義陽樊建代焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-2', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-3', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '漢晉春秋曰：樊建為給事中，晉武帝問諸葛亮之治國，建對曰：「聞惡必改，而不矜過，賞罰之信，足感神明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-045-4', 'p0398', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '少子武，有文，與樊建齊名，官亦至尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-032-0', 'p0399', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-035-1', 'p0399', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '今使使持節左中郎將杜瓊，贈君丞相武鄉侯印綬，謚君為忠武侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-042-2', 'p0399', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '杜瓊字伯瑜，蜀郡成都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-042-3', 'p0399', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '周羣占天有徵，杜瓊沈默慎密，諸生之純也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-045-4', 'p0399', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '事廣漢任安學，精究安術，與杜瓊同師而名問過之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0400-a04-042-0', 'p0400', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '時又有魏郡胡潛，字公興，不知其所以在益土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0402-a04-045-0', 'p0402', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0402-a04-045-1', 'p0402', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：楊顒字子昭，楊儀宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-017-0', 'p0404', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '備遣陳式等十餘營絕馬鳴閣道，晃別征破之，賊自投山谷，多死者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-032-1', 'p0404', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二年春正月，先主軍還秭歸，將軍吳班、陳式水軍屯夷陵，夾江東西岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-033-2', 'p0404', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年春，亮遣陳式攻武都、陰平，遂克定二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-032-0', 'p0405', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-032-1', 'p0405', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二年春正月，先主軍還秭歸，將軍吳班、陳式水軍屯夷陵，夾江東西岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-035-2', 'p0405', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮使魏延、高翔、吳班赴拒，大破之，獲甲首三千級、玄鎧五千領、角弩三千一百張，宣王還保營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-040-3', 'p0405', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-058-4', 'p0405', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-064-0', 'p0406', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '先是陳留邊鳳為京兆尹，亦有能名，郡人為之語曰：「前有趙張三王，前書，趙廣漢、張敞、王遵、王章、王駿俱為京兆尹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-076-1', 'p0406', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '趙謂趙廣漢，張謂張敞者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-077-2', 'p0406', 'houhanshu', 'a03-077', '《後漢書·卷七十七》', '又趙廣漢為京兆尹，侵犯貴戚大臣，將吏卒入丞相魏相府，召其夫人跪庭下受辭，責以殺婢事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0407-a04-028-0', 'p0407', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '忠、纂馳還更戰，大破之，斬瞻及尚書張遵等首，進軍到雒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-0', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-1', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：蔣舒將出降，乃詭謂傅僉曰：「今賊至不擊而閉城自守，非良圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-2', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '蜀記曰：蔣舒為武興督，在事無稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-044-0', 'p0411', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-044-1', 'p0411', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：蔣舒將出降，乃詭謂傅僉曰：「今賊至不擊而閉城自守，非良圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-045-2', 'p0411', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '蜀記載晉武帝詔曰：「蜀將軍傅僉，前在關城，身拒官軍，致死不顧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a04-028-0', 'p0412', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蜀監軍王含守樂城，護軍蔣斌守漢城，兵各五千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a04-044-1', 'p0412', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是令督漢中胡濟却住漢壽，監軍王含守樂城，護軍蔣斌守漢城，又於西安、建威、武衞、石門、武城、建昌、臨遠皆立圍守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a05-002-2', 'p0412', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會分為二隊，入自斜谷，使李輔圍王含於樂城，又使部將易愷攻蔣斌於漢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0414-a04-056-0', 'p0414', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '績與奮威將軍諸葛融書曰：「昶遠來疲困，馬無所食，力屈而走，此天助也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-027-0', 'p0415', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '會吳遣朱異來救誕，軍於安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-1', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽雖在他國，不能屈節下人，自呂據、朱異等諸大將皆憎疾之，惟峻常左右之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-2', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴將朱異再以大衆來迎誕等，渡黎漿水，泰等逆與戰，每摧其鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-3', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-047-4', 'p0415', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-5', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三月，使鎮南將軍朱異襲安豐，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-6', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '八月，先遣欽及驃騎呂據、車騎劉纂、鎮南朱異、前將軍唐咨軍自江都入淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-7', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '朱異自虎林率衆襲夏口，夏口督孫壹奔魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-8', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，綝率衆救壽春，次于鑊里，朱異至自夏口，綝使異為前部督，與丁奉等將介士五萬解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-9', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '朱異以軍士乏食引還，綝大怒，九月朔己巳，殺異於鑊里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-055-10', 'p0415', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '遣朱異、唐咨等往救，復使奉與黎斐解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-056-11', 'p0415', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然攻樊，據與朱異破城外圍，還拜偏將軍，入補馬閑右部督，遷越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-056-12', 'p0415', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-13', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '將軍朱異有所是非，恪怒，立奪其兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-14', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-15', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱異帥三萬人屯安豐城，為文欽勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-16', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '又委罪朱異，擅殺功臣，不先表聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a05-002-17', 'p0415', 'jinshu', 'a05-002', '《晉書·卷二》', '八月，吳將朱異帥兵萬餘人，留輜重於都陸，輕兵至黎漿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a05-002-18', 'p0415', 'jinshu', 'a05-002', '《晉書·卷二》', '奇兵震擊，而朱異摧破；神變應機，而全琮稽服；取亂攻昧，而高墉不守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-004-0', 'p0416', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '偽將施績，賊之名臣，懷疑自猜，深見忌惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-027-1', 'p0416', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '於是昶使積弩同時俱發，賊大將施績夜遁入江陵城，追斬數百級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-027-2', 'p0416', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，昶據夾石以逼江陵，持施績、全熈使不得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-3', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '甲申，使大將軍丁奉督諸軍向魏壽春，將軍留平別詣施績於南郡，議兵所向，將軍丁封、孫異如沔中，皆救蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-4', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '元興元年八月，以上大將軍施績、大將軍丁奉為左右大司馬，張布為驃騎將軍，加侍中，諸增位班賞，一皆如舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-5', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '夏四月，左大司馬施績卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-6', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-051-7', 'p0416', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-052-8', 'p0416', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '恪旣誅，遣無難督施寬就將軍施績、孫壹、全熈等取融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-056-9', 'p0416', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-058-10', 'p0416', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '建衡二年，大司馬施績卒，拜抗都督信陵、西陵、夷道、樂鄉，公安諸軍事，治樂鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-059-11', 'p0416', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-060-12', 'p0416', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '盛以施績、留平，智略名將，屢經於彼，無云當城之者，不然徇計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a05-003-13', 'p0416', 'jinshu', 'a05-003', '《晉書·卷三》', '」冬十月，吳將施績入江夏，萬郁寇襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a05-037-14', 'p0416', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '吳將施績寇江夏，邊境騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-048-0', 'p0417', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '姊全公主嘗譖太子和子母，心不自安，因倚權意，欲豫自結，數稱述全尚女，勸為亮納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-048-1', 'p0417', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '亮以綝專恣，與太常全尚，將軍劉丞謀誅綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-050-2', 'p0417', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮全夫人，全尚女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-050-3', 'p0417', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '全尚妻即峻姊，故惟全主祐焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-4', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝入諫不從，亮遂與公主魯班、太常全尚、將軍劉承議誅綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-5', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝率衆夜襲全尚，遣弟恩殺劉承於蒼龍門外，遂圍宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-6', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '江表傳曰：亮召全尚息黃門侍郎紀密謀，曰：「孫綝專勢，輕小於孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-7', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '太常全尚，累世受恩，不能督諸宗親，而全端等委城就魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-0', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」八月，以軍師張悌為丞相，牛渚都督何植為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-1', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '預又斬江陵督伍延，渾復斬丞相張悌、丹楊太守沈瑩等，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-2', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：吳丞相軍師張悌、護軍孫震、丹楊太守沈瑩帥衆三萬濟江，圍成陽都尉張喬於楊荷橋，衆才七千，閉柵自守，舉白接告降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-3', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '人問之，榮曰：「上天北斗門下卒見人縛張悌，意中大愕，不覺大呼，言『何以縛張軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-4', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '聞晉大衆，遠來臨江，庶竭勞瘁，衆皆摧退，而張悌不反，喪軍過半。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-051-5', 'p0419', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '震後禦晉軍，與張悌俱死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-061-6', 'p0419', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '姚信、樓玄、賀卲、張悌、郭逴、薛瑩、滕脩及族弟喜、抗，或清白忠勤，或姿才卓茂，皆社稷之楨幹，國家之良輔，願陛下重留神思，訪以時務，各盡其忠，拾遺萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-003-7', 'p0419', 'jinshu', 'a05-003', '《晉書·卷三》', '王渾、周浚與吳丞相張悌戰于版橋，大破之，斬悌及其將孫震、沈瑩，傳首洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-8', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '吳丞相張悌、大將軍孫震等率眾數萬指城陽，渾遣司馬孫疇、揚州刺史周浚擊破之，臨陣斬二將，及首虜七千八百級，吳人大震。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-9', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '又摧大敵，獲張悌，使皓塗窮勢盡，面縛乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-10', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '」王渾久破皓中軍，斬張悌等，頓兵不敢進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0420-a04-048-0', 'p0420', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三月丙寅，殿中親近數百人叩頭請皓殺岑昏，皓惶憒從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0420-a04-053-1', 'p0420', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '尚書岑昏率公卿已下百餘人，詣宮叩頭請，尚罪得減死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-0', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '秋七月，太中大夫陳蕃為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-1', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '陳蕃等上疏諫曰『唯善政可以已之』，書奏不省。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-2', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '自非忠賢力爭，屢折姦鋒，忠賢謂李膺、陳蕃、竇武、黃瓊、朱穆、劉淑、劉陶等，各上書極諫，以折宦官等姦謀之鋒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-full-3', 'p0421', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-full-4', 'p0421', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-5', 'p0421', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-6', 'p0421', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-009-7', 'p0421', 'houhanshu', 'a03-009', '《後漢書·卷九》', '遣使弔祠故太傅陳蕃、大將軍竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-026-8', 'p0421', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '靈帝即位，中常侍曹節以陳蕃、竇氏旣誅，海內多怨，欲借寵時賢以為名，假借時賢寵榮以求美名，用解怨謗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-027-9', 'p0421', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '會病卒，謝承書曰：「靈帝即位，典與竇武、王暢、陳蕃等謀共誅中常侍曹節、侯覽、趙忠等，皆下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-10', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '其憲章朝右，簡覈才職，委功曹陳蕃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-11', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '後太傅陳蕃辟，不應，為郡五官掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-12', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '謂委任功曹陳蕃、主簿應嗣，郡中大化也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-037-13', 'p0421', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝即位，太傅陳蕃、大將軍竇武輔政，復徵用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-039-14', 'p0421', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '會司隷校尉李膺等抵罪，而南陽太守成瑨、太原太守劉瓆下獄當死，茂與太尉陳蕃、司徒劉矩共上書訟之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-039-15', 'p0421', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '靈帝初，太傅陳蕃、大將軍竇武為宦者所誅，咨乃謝病去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-044-16', 'p0421', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '靈帝立，與太傅陳蕃參錄尚書事，復封故國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-044-17', 'p0421', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '與故吏陳蕃、李咸並為三司。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-045-18', 'p0421', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '歲餘，復代陳蕃為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-048-19', 'p0421', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '」對曰：「尚書令陳蕃任事則化，中常侍黃門豫政則亂，是以知陛下可與為善，可與為非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-20', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '」同郡陳蕃、周舉常相謂曰：「時月之閒不見黃生，則鄙吝之萌復存乎心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-21', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '時陳蕃為太守，以禮請署功曹，稺不免之，旣謁而退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-22', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '延熹二年，尚書令陳蕃、僕射胡廣等上疏薦稺等曰：「臣聞善人天地之紀，政之所由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-23', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '中常侍曹節等專執朝事，新誅太傅陳蕃、大將軍竇武，欲借寵賢德，以釋衆望，乃白徵肱為太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-24', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '政崇溫和，好才愛士，引進郡人黃憲、陳蕃等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-25', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太尉陳蕃薦暢清方公正，有不可犯之色，禮記曰：「介冑之士，則有不可犯之色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-26', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太后本遷南宮雲臺，太后父竇武與陳蕃謀誅宦官，反為中常侍曹節矯詔殺武、蕃，遷太后焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-27', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '二十餘年，靈帝即位，大將軍竇武、太傅陳蕃輔政，徵拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-28', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '大鴻臚陳蕃上疏救雲曰：「李雲所言，雖不識禁忌，干上逆旨，其意歸於忠國而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-29', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '又故太傅陳蕃，輔相陛下，勤身王室，夙夜匪懈，而見陷羣邪，一旦誅滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-30', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '於是濟陰太守胡廣等十餘人皆坐謬舉免黜，唯汝南陳蕃、潁川李膺、下邳陳球等三十餘人得拜郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-31', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '時陳蕃為光祿勳，深相敬待，數與議事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-32', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後陳蕃被徵，而言事者多訟韙，復拜議郎，遷尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-33', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '陳蕃、楊秉處稱賢宰，皇甫、張、段出號名將，王暢、李膺彌縫衮闕，彌縫猶補合也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-34', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '前太尉陳蕃、劉矩，漢官儀曰：「矩字叔方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-35', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '時竇太后臨朝，大將軍竇武與太傅陳蕃謀誅宦官，事泄，中常侍曹節等於中作亂，以奐新徵，不知本謀，矯制使奐與少府周靖率五營士圍武。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-36', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '故大將軍竇武、太傅陳蕃，或志寧社稷，或方直不回，前以讒勝，並伏誅戮，海內默默，人懷震憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-37', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '陳蕃、竇武奮義草謀，徵會天下，名士有識所共聞也，而張奐見欺豎子，揚戈以斷忠烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-38', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐被曹節等矯制，使率五營士圍殺陳蕃、竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-39', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '陳蕃字仲舉，汝南平輿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-40', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '前太尉陳蕃，忠清直亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-41', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」太傅陳蕃，輔弼先帝，出內累年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-42', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '論曰：桓、靈之世，若陳蕃之徒，咸能樹立風聲，抗論惛俗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-43', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '贊曰：陳蕃蕪室，志清天綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-44', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '並與李膺、陳蕃、王暢更相襃重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-45', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竇武、劉淑、陳蕃為「三君」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-46', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-47', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '翟超，山陽太守，事見陳蕃傳，字及郡縣未詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-48', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '案經三府，太尉陳蕃卻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-49', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃免太尉，朝野屬意於膺，荀爽恐其名高致禍，欲令屈節以全亂世，為書貽曰：「乆廢過庭，不聞善誘，陟岵瞻望，惟日為歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-50', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '頃聞上帝震怒，貶黜鼎臣，上帝謂天子，鼎臣即陳蕃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-51', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃為太傅，與大將軍竇武共秉朝政，連謀誅諸宦官，故引用天下名士，乃以膺為長樂少府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-52', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '後太傅陳蕃輔政，復為太僕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-53', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '靈帝初，陳蕃輔政，以祐為河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-54', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '尚書令陳蕃薦朗公忠亮直，宜在機密，復徵為尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-55', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '與竇武、陳蕃等謀誅閹官，武等遇害，肅亦坐黨禁錮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-56', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '時陳蕃為光祿勳，滂執公儀詣蕃，蕃不止之，滂懷恨，投版弃官而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-57', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '延熹九年，黨事起，太尉陳蕃爭之不能得，朝廷寒心，莫敢復言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-58', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃、李膺之敗，顒以與蕃、膺善，遂為宦官所陷，乃變姓名，亡匿汝南閒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-068-59', 'p0421', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '建寧元年，太傅陳蕃、大將軍竇武為閹人所害，林宗哭之於野，慟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-068-60', 'p0421', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '又陳蕃喪妻還葬，鄉人畢至，而劭獨不往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-61', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '今臺閣近臣，尚書令陳蕃，僕射胡廣，尚書朱㝢、荀緄、音古本反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-62', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '武旣輔朝政，常有誅翦宦官之意，太傅陳蕃亦素有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-63', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '與陳蕃合策戮力，唯德是建，咸得其人，豪賢大姓皆絕望矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-64', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」因大呼曰：「陳蕃、竇武奏白太后廢帝，為大逆！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-069-65', 'p0421', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '『後年磽』者，陳蕃、竇武等誅，天下大壞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-071-66', 'p0421', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」太尉陳蕃、大將軍竇武連辟，並不到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-072-67', 'p0421', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-076-68', 'p0421', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '並以仁信篤誠，使人不欺；王堂、陳寵委任賢良，而職事自理：王堂任陳蕃、應嗣，陳寵任王渙、鐔顯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-078-69', 'p0421', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '時竇太后臨朝，后父大將軍武與太傅陳蕃謀誅中官，節與長樂五官史朱瑀、從官史共普、共音恭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-078-70', 'p0421', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '太傅陳蕃、大將軍竇武考其黨與，志清朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-102-71', 'p0421', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '永康元年十二月丁丑，桓帝崩，太傅陳蕃，大將軍竇武、尚書令尹勳、黃門令山冰等皆枉死，太白犯心，熒惑留守太微之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-102-72', 'p0421', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其八月，太傅陳蕃、大將軍竇武謀欲盡誅諸宦者；其九月辛亥，中常侍曹節、長樂五官史朱瑀覺之，矯制殺蕃、武等，家屬徙日南比景。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-103-73', 'p0421', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」案陳蕃上疏：「宮女多聚不御，憂悲之感，以致水旱之困也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-103-74', 'p0421', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '及太后攝政，為大將軍，與太傅陳蕃合心戮力，惟德是建，印綬所加，咸得其人，豪賢大姓皆絕望矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-75', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '陳蕃、劉矩、劉茂上疏諫曰：『古之火皆君弱臣強，極陰之變也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-76', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '袁山松書曰：「是時宦豎專朝，鉤黨事起，上尋無嗣，陳蕃、竇武為曹節等所害，天下無復紀綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-104-77', 'p0421', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '陳蕃諫云：「楚女悲而西宮災，不御宮女，怨之所致也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-107-78', 'p0421', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '奐上疏：「陳蕃、竇氏未被明宥，妖眚之來，皆為此也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-114-79', 'p0421', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」案：靈帝之初，以陳蕃為太傅，蕃誅，以胡廣代，始不止一人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-001-80', 'p0421', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '先是大將軍竇武、太傅陳蕃謀誅閹官，反為所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-001-81', 'p0421', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '司馬彪九州春秋曰：於是陳蕃子逸與術士平原襄楷會於芬坐，楷曰：「天文不利宦者，黃門、常侍貴族滅矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-010-82', 'p0421', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顒顯名太學，於是中朝名臣太傅陳蕃、司隷李膺等皆深接之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-051-83', 'p0421', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '少游京師，師事太傅陳蕃，博覽羣書，明於風角，善推災異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a04-054-84', 'p0421', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '後為豫州刺史，辟汝南陳蕃為別駕，潁川李膺、荀緄、杜密、沛國朱㝢為從事，皆天下英俊之士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-007-0', 'p0422', 'houhanshu', 'a03-007', '《後漢書·卷七》', '自非忠賢力爭，屢折姦鋒，忠賢謂李膺、陳蕃、竇武、黃瓊、朱穆、劉淑、劉陶等，各上書極諫，以折宦官等姦謀之鋒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-1', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '桓帝崩，無子，皇太后與父城門校尉竇武定策禁中，使守光祿大夫劉儵持節，將左右羽林至河閒奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-2', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '建寧元年春正月壬午，城門校尉竇武為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-3', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '」使竇武持節，以王青蓋車迎入殿中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-4', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-5', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-full-6', 'p0422', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太后與竇武密謀欲誅曹節，今武等旣誅，故太后被遷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-7', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '桓帝崩，無子，皇太后與父城門校尉竇武定策禁中，使守光祿大夫劉儵持節，將左右羽林至河閒奉迎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-8', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '建寧元年春正月壬午，城門校尉竇武為大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-9', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '」使竇武持節，以王青蓋車迎入殿中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-10', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-11', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-008-12', 'p0422', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太后與竇武密謀欲誅曹節，今武等旣誅，故太后被遷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-009-13', 'p0422', 'houhanshu', 'a03-009', '《後漢書·卷九》', '遣使弔祠故太傅陳蕃、大將軍竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-027-14', 'p0422', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '會病卒，謝承書曰：「靈帝即位，典與竇武、王暢、陳蕃等謀共誅中常侍曹節、侯覽、趙忠等，皆下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-031-15', 'p0422', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '續以忠臣子孫拜郎中，去官後，辟大將軍竇武府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-037-16', 'p0422', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝即位，太傅陳蕃、大將軍竇武輔政，復徵用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-039-17', 'p0422', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '靈帝初，太傅陳蕃、大將軍竇武為宦者所誅，咨乃謝病去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-053-18', 'p0422', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '中常侍曹節等專執朝事，新誅太傅陳蕃、大將軍竇武，欲借寵賢德，以釋衆望，乃白徵肱為太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-055-19', 'p0422', 'houhanshu', 'a03-055', '《後漢書·卷五十五》', '萇卒，子宏嗣，為大將軍竇武所立，是為靈帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-056-20', 'p0422', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太后本遷南宮雲臺，太后父竇武與陳蕃謀誅宦官，反為中常侍曹節矯詔殺武、蕃，遷太后焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-056-21', 'p0422', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '初，郃兄侍中儵，與大將軍竇武同謀俱死，故郃與球相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-057-22', 'p0422', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '二十餘年，靈帝即位，大將軍竇武、太傅陳蕃輔政，徵拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-057-23', 'p0422', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '及帝崩，大將軍竇武欲大誅宦官，乃引瑜為侍中，又以侍中尹勳為尚書令，共同謀畫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-062-24', 'p0422', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '昱後共大將軍竇武謀誅中官，與李膺俱死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-062-25', 'p0422', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '靈帝初，大將軍竇武辟以為掾屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-064-26', 'p0422', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '時皇后父大將軍竇武援立靈帝，初秉機政，朝議欲加封爵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-27', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '時竇太后臨朝，大將軍竇武與太傅陳蕃謀誅宦官，事泄，中常侍曹節等於中作亂，以奐新徵，不知本謀，矯制使奐與少府周靖率五營士圍武。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-28', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '故大將軍竇武、太傅陳蕃，或志寧社稷，或方直不回，前以讒勝，並伏誅戮，海內默默，人懷震憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-29', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '陳蕃、竇武奮義草謀，徵會天下，名士有識所共聞也，而張奐見欺豎子，揚戈以斷忠烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-065-30', 'p0422', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐被曹節等矯制，使率五營士圍殺陳蕃、竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-31', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃與后父大將軍竇武，同心盡力，徵用名賢，共參政事，天下之士，莫不延頸想望太平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-32', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃常疾之，志誅中官，會竇武亦有謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-33', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '蕃因與竇武謀之，語在武傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-34', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '適聞其言，而讓蕃曰：「先帝新弃天下，山陵未成，竇武何功，兄弟父子，一門三侯？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-066-35', 'p0422', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」及遭際會，協策竇武，自謂萬世一遇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-36', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '明年，尚書霍諝、城門校尉竇武並表為請，帝意稍解，乃皆赦歸田里，禁錮終身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-37', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竇武、劉淑、陳蕃為「三君」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-38', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-39', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '靈帝旣位，宦官譖淑與竇武等通謀，下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-40', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃為太傅，與大將軍竇武共秉朝政，連謀誅諸宦官，故引用天下名士，乃以膺為長樂少府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-41', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '後竇武等誅，朗以黨被急徵，行至牛渚，自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-42', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '與竇武、陳蕃等謀誅閹官，武等遇害，肅亦坐黨禁錮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-43', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '坐竇武等事，下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-067-44', 'p0422', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」乃入洛陽，說城門校尉竇武、尚書霍諝，武等訟之，桓帝以此大赦黨人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-068-45', 'p0422', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '建寧元年，太傅陳蕃、大將軍竇武為閹人所害，林宗哭之於野，慟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-46', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '竇武字游平，扶風平陵人，安豐戴侯融之玄孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-47', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」因大呼曰：「陳蕃、竇武奏白太后廢帝，為大逆！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-48', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '甫兵漸盛，使其士大呼武軍曰：「竇武反，汝皆禁兵，當宿衞宮省，何故隨反者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-49', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '『後年磽』者，陳蕃、竇武等誅，天下大壞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-50', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '袁紹復說進曰：「前竇武欲誅內寵而反為所害者，以其言語漏泄，而五營百官服畏中人故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-069-51', 'p0422', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '論曰：竇武、何進藉元舅之資，據輔政之權，內倚太后臨朝之威，外迎羣英乘風之埶，卒而事敗閹豎，身死功穨，為世所悲，豈智不足而權有餘乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-071-52', 'p0422', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」太尉陳蕃、大將軍竇武連辟，並不到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-072-53', 'p0422', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-54', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '竇武、何進，位崇戚近，乘九服之嚻怨，協羣英之埶力，九服已見上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-55', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '羣英謂劉猛、朱㝢之屬，見竇武傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-56', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '太傅陳蕃、大將軍竇武考其黨與，志清朝政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-078-57', 'p0422', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '至戚發憤，方啟專奪之隙，謂竇武謀誅宦者，反為宦者所殺也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-102-58', 'p0422', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '永康元年十二月丁丑，桓帝崩，太傅陳蕃，大將軍竇武、尚書令尹勳、黃門令山冰等皆枉死，太白犯心，熒惑留守太微之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-102-59', 'p0422', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其八月，太傅陳蕃、大將軍竇武謀欲盡誅諸宦者；其九月辛亥，中常侍曹節、長樂五官史朱瑀覺之，矯制殺蕃、武等，家屬徙日南比景。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-103-60', 'p0422', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時大將軍竇武謀變廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a03-104-61', 'p0422', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '袁山松書曰：「是時宦豎專朝，鉤黨事起，上尋無嗣，陳蕃、竇武為曹節等所害，天下無復紀綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a04-001-62', 'p0422', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '先是大將軍竇武、太傅陳蕃謀誅閹官，反為所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0422-a04-006-63', 'p0422', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：初紹說進曰：「黃門、常侍累世太盛，威服海內，前竇武欲誅之而反為所害，但坐言語漏泄，以五營士為兵故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a03-009-0', 'p0423', 'houhanshu', 'a03-009', '《後漢書·卷九》', '白波賊寇河東，薛瑩書曰：「黃巾郭泰等起於西河白波谷，時謂之白波賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a03-053-1', 'p0423', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '郭泰別傳曰：「時林宗過薛恭祖，恭祖問曰：『聞足不見袁奉高，車不停軌，鑾不輟軶，從叔度乃彌信宿也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-006-2', 'p0423', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '少有大節，郭泰見而奇之，曰：「王生一日千里，王佐之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-010-3', 'p0423', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」事垂就而覺，收顒、攸繫獄，顒憂懼自殺，張璠漢紀曰：顒字伯求，少與郭泰、賈彪等遊學洛陽，泰等與同風好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-022-4', 'p0423', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '四方至者車數千乘，自太原郭泰等無不造門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0423-a04-057-5', 'p0423', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '宜遠模仲尼之汎愛，中則郭泰之弘濟，近有益於大道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-009-0', 'p0424', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-009-1', 'p0424', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」夏五月，司空荀爽薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-026-2', 'p0424', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '潁川荀爽深以為美，時人亦服焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-043-3', 'p0424', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '野字子遼，見荀爽薦文。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-053-4', 'p0424', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '今潁川荀爽載病在道，北海鄭玄北面受署。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-054-5', 'p0424', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '司空荀爽見卓意壯，恐害彪等，因從容言曰：「相國豈樂此邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-056-6', 'p0424', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '初平元年，代荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-062-7', 'p0424', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '論曰：荀爽、鄭玄、申屠蟠俱以儒行為處士，累徵並謝病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-063-8', 'p0424', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '時潁川荀爽、賈彪，雖俱知名而不相能，爕並交二子，情無適莫，世稱其平正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-066-9', 'p0424', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '辟荀爽、孔融等為從事，上除禁黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-10', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」荀爽甞就謁膺，因為其御，旣還，喜曰：「今日乃得御李君矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-11', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃免太尉，朝野屬意於膺，荀爽恐其名高致禍，欲令屈節以全亂世，為書貽曰：「乆廢過庭，不聞善誘，陟岵瞻望，惟日為歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-12', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '少遊京師，志節慷慨，與同郡荀爽齊名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-067-13', 'p0424', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-072-14', 'p0424', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-079-15', 'p0424', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '融授鄭玄，玄作易注，荀爽又作易傳，自是費氏興，而京氏遂衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a03-084-16', 'p0424', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '南陽陰瑜妻者，潁川荀爽之女也，名采，字女荀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-006-17', 'p0424', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-006-18', 'p0424', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三公並辟，歷豫州刺史，辟荀爽、孔融為從事，遷河南尹、尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-011-19', 'p0424', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '昔司空荀爽，家拜光祿，先儒鄭玄，即授司農，若加備禮，庶必可致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-013-20', 'p0424', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太子書報繇，繇荅書曰：「臣同郡故司空荀爽言：『人當道情，愛我者一何可愛！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-022-21', 'p0424', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '寔之亡也，司空荀爽、太僕令韓融並制緦麻，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-037-22', 'p0424', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '以此為貶，則荀爽、陳紀之儔皆應擯棄於世矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-038-23', 'p0424', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0424-a04-053-24', 'p0424', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-0', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '甲午，豫州牧黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-1', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-2', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，太尉黃琬、司徒楊彪免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-009-3', 'p0425', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-027-4', 'p0425', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '謙字彥信，初平元年，代黃琬為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-053-5', 'p0425', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '後蟠友人陳郡馮雍坐事繫獄，豫州牧黃琬欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-054-6', 'p0425', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '中平六年，代董卓為司空，其冬，代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-054-7', 'p0425', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '太尉黃琬曰：「此國之大事，楊公之言得無可思？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-066-8', 'p0425', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '自蕃為光祿勳，與五官中郎將黃琬共典選舉，不偏權富，而為埶家郎所譖訴，坐免歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-066-9', 'p0425', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '允見卓禍毒方深，篡逆已兆，密與司隷校尉黃琬、尚書鄭公業等謀共誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-072-10', 'p0425', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-072-11', 'p0425', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '會公卿議，太尉黃琬、司徒楊彪廷爭不能得，而伍瓊、周珌又固諫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-074-12', 'p0425', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續漢書曰：「彪代董卓為司空，又代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-075-13', 'p0425', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '太僕黃琬為豫州牧，宗正劉虞為幽州牧，皆以本秩居職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a03-079-14', 'p0425', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '司徒黃琬特辟，不行，終於家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-006-15', 'p0425', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-008-16', 'p0425', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：虞讓太尉，因薦衞尉趙謨、益州牧劉焉、豫州牧黃琬、南陽太守羊續，並任為公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-009-17', 'p0425', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時豫州刺史黃琬欲害太祖，太祖避之而邵獨遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-029-18', 'p0425', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '沛相陳珪舉孝廉，太尉黃琬辟，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-042-19', 'p0425', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '漢末大亂，敏隨姊奔荊州，姊夫黃琬是劉璋祖母之姪，故璋遣迎琬妻，敏遂俱與姊入蜀，常為璋賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0425-a04-049-20', 'p0425', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '比至，宮已免，黃琬代為司徒，甚禮遇壹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-007-0', 'p0426', 'houhanshu', 'a03-007', '《後漢書·卷七》', '九月，司空黃瓊免，大鴻臚劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-1', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，司空王暢免，宗正劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-2', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空劉寵為司徒，大鴻臚許栩為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-3', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '六月，司徒劉寵為太尉，太常許訓為司徒，訓字季師，平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-full-4', 'p0426', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，太尉劉寵免，太僕郭禧為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-5', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，司空王暢免，宗正劉寵為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-6', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空劉寵為司徒，大鴻臚許栩為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-7', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '六月，司徒劉寵為太尉，太常許訓為司徒，訓字季師，平輿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-008-8', 'p0426', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，太尉劉寵免，太僕郭禧為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-015-9', 'p0426', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '謝承書曰：「安衆侯劉寵，長沙定王五代孫，南陽宗室也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-046-10', 'p0426', 'houhanshu', 'a03-046', '《後漢書·卷四十六》', '建寧二年，代劉寵為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-057-11', 'p0426', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '今之四公，唯司空劉寵斷斷守善，餘皆素餐致寇之人，四公謂劉矩為太尉，許訓為司徒，胡廣為太傅及寵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-067-12', 'p0426', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以前太尉劉寵、司隷校尉許冰、幽州刺史楊熙、涼州刺史劉恭、益州刺史龐艾清亮在公，薦舉升進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-076-13', 'p0426', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '衞颯　任延　王景　秦彭　王渙　許荊　孟甞　弟五訪　劉矩　劉寵　仇香　童恢');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-076-14', 'p0426', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '劉寵字祖榮，東萊牟平人，齊悼惠王之後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-077-15', 'p0426', 'houhanshu', 'a03-077', '《後漢書·卷七十七》', '辟司徒劉寵府，舉高第。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-081-16', 'p0426', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '太守劉寵舉就孝廉，光祿主事，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0426-a03-112-17', 'p0426', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三齊記曰：「南有蹲犬山，山似犬蹲，有神，劉寵出西都，經此山，山犬吠之，寵曰『山神謂我人也』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-0', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '己未，以平東將軍、琅邪王睿為安東將軍、都督揚州江南諸軍事、假節，鎮建鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-1', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '鎮東將軍周馥表迎大駕遷都壽陽，越使裴頠討馥，為馥所敗，走保東城，請救於琅邪王睿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-2', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '戊寅，安東將軍、琅邪王睿使將軍甘卓攻鎮東將軍周馥於壽春，馥衆潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-3', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '進司空王浚為大司馬，征西大將軍、南陽王模為太尉，太子太傅傅祗為司徒，尚書令荀藩為司空，安東將軍、琅邪王睿為鎮東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-4', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '癸丑，鎮東大將軍、琅邪王睿上尚書，檄四方以討石勒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-5', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '五月壬辰，以鎮東大將軍、琅邪王睿為侍中、左丞相、大都督陝東諸軍事，大司馬、南陽王保為右丞相、大都督陝西諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-6', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '二月丙子，進左丞相、琅邪王睿為大都督、督中外諸軍事，右丞相、南陽王保為相國，司空荀組為太尉，大將軍劉琨為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0428-a05-005-7', 'p0428', 'jinshu', 'a05-005', '《晉書·卷五》', '三月，琅邪王睿承制改元，稱晉王于建康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a03-075-0', 'p0429', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '州大吏趙韙等貪璋溫仁，立為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a03-075-1', 'p0429', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '趙韙之在巴中，甚得衆心，璋委之以權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-2', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '扶亦求為蜀郡西部屬國都尉，及太倉令會巴西趙韙去官，俱隨焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-3', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '州大吏趙韙等貪璋溫仁，共上璋為益州刺史，詔書因以為監軍使者，領益州牧，以韙為征東中郎將，率衆擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-4', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋使趙韙進攻荊州，屯朐䏰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-5', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後羲與璋情好攜隙，趙韙稱兵內向，衆散見殺，皆由璋明斷少而外言入故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0429-a04-031-6', 'p0429', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '趙韙素得人心，璋委任之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a03-075-0', 'p0430', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '璋怒，殺魯母及弟，而遣其將龐羲等攻魯，數為所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-1', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '議郎河南龐羲與焉通家，乃募將焉諸孫入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-2', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋累遣龐羲等攻魯，數為所破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-3', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：龐羲與璋有舊，又免璋諸子於難，故璋厚德羲，以羲為巴西太守，遂專權勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-4', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後松復說璋曰：「今州中諸將龐羲、李異等皆恃功驕豪，欲有外意，不得豫州，則敵攻其外，民攻其內，必敗之道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-031-5', 'p0430', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '初，璋長子循妻，龐羲女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-032-6', 'p0430', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '秋，羣下上先主為漢中王，表於漢帝曰：「平西將軍都亭侯臣馬超、左將軍長史領鎮軍將軍臣許靖、營司馬臣龐羲、議曹從事中郎軍議中郎將臣射援、三輔決錄注曰：援字文雄，扶風人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-045-7', 'p0430', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」芝聞巴西太守龐羲好士，往依焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0430-a04-045-8', 'p0430', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '巴西太守龐羲以天下擾亂，郡宜有武衞，頗招合部曲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a03-074-0', 'p0431', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '瓚輕其兵少，縱騎騰之，義兵伏楯下，一時同發，瓚軍大敗，斬其所置兾州刺史嚴綱，獲甲首千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a03-082-1', 'p0431', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '昔為陪隷，與臣從事，奮忠毅之操，躬史魚之節，董臣嚴綱，勗臣懦弱，董，督也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-006-2', 'p0431', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '義兵皆伏楯下不動，未至數十步，乃同時俱起，揚塵大叫，直前衝突，彊弩雷發，所中必倒，臨陣斬瓚所署兾州刺史嚴綱甲首千餘級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-008-3', 'p0431', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '以嚴綱為兾州，田楷為青州，單經為兖州，置諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0431-a04-047-4', 'p0431', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '祕所領都督廖式殺臨賀太守嚴綱等，自稱平南將軍，與弟潛共攻零陵、桂陽，及搖動交州、蒼梧、鬱林諸郡，衆數萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a03-067-0', 'p0433', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以儉及檀彬、褚鳳、張肅、薛蘭、馮禧、魏玄、徐乾為「八俊」，田林、張隱、劉表、薛郁、王訪、劉祇、宣靖、公緒恭為「八顧」，公緒，姓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a03-074-1', 'p0433', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布將薛蘭、李封屯鉅野，操攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-001-2', 'p0433', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，布將薛蘭、李封屯鉅野，太祖攻之，布救蘭，蘭敗，布走，遂斬蘭等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-010-3', 'p0433', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0433-a04-018-4', 'p0433', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '布別駕薛蘭、治中李封招乾，欲俱叛，乾不聽，遂殺乾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a03-036-0', 'p0434', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '帝以元新忿爭，乃用其次司隷從事李封，於是諸儒以左氏之立，論議讙譁，自公卿以下數廷爭之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a03-074-1', 'p0434', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布將薛蘭、李封屯鉅野，操攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-001-2', 'p0434', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，布將薛蘭、李封屯鉅野，太祖攻之，布救蘭，蘭敗，布走，遂斬蘭等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-010-3', 'p0434', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0434-a04-018-4', 'p0434', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '布別駕薛蘭、治中李封招乾，欲俱叛，乾不聽，遂殺乾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-008-full-0', 'p0437', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '黑山賊張牛角等十餘輩並起，所在寇鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-008-1', 'p0437', 'houhanshu', 'a03-008', '《後漢書·卷八》', '黑山賊張牛角等十餘輩並起，所在寇鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-009-2', 'p0437', 'houhanshu', 'a03-009', '《後漢書·卷九》', '黃巾起，燕合聚少年為羣盜，萬餘人，博陵人張牛角為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-058-3', 'p0437', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '博陵張牛角之起，衆次癭陶，牛角為飛矢所中，且死，告其衆曰：「必以燕為帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a03-074-4', 'p0437', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '黃巾賊起，燕聚少年為羣盜，博陵張牛角亦起與燕合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0437-a04-008-5', 'p0437', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '博陵張牛角亦起衆，自號將兵從事，與燕合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a03-071-0', 'p0439', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a04-001-1', 'p0439', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '黑山賊于毒、白繞、眭固等眭，申隨反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0439-a04-001-2', 'p0439', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十餘萬衆略魏郡、東郡，王肱不能禦，太祖引兵入東郡，擊白繞於濮陽，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a03-070-0', 'p0440', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '時融為管亥所圍，慈從遼東還，母謂之曰：「汝與孔北海未甞相見，至汝行後，贍恤殷勤，過於故舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a04-049-1', 'p0440', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '時融以黃巾寇暴，出屯都昌，為賊管亥所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0440-a04-049-2', 'p0440', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '今管亥暴亂，北海被圍，孤窮無援，危在旦夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0442-a04-032-0', 'p0442', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '紹遣先主將本兵復至汝南，與賊龔都等合，衆數千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0443-a04-001-0', 'p0443', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0444-a04-001-0', 'p0444', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0445-a04-001-0', 'p0445', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '汝南、潁川黃巾何儀、劉辟、黃邵、何曼等，衆各數萬，初應袁術，又附孫堅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0445-a04-017-1', 'p0445', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征黃巾劉辟、黃邵等，屯版梁，邵等夜襲太祖營，禁帥麾下擊破之，斬辟、邵等，盡降其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-024-0', 'p0446', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '明年，防復以病乞骸骨，詔賜故中山王田廬，中山王焉以郭太后少子故，獨留京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-042-1', 'p0446', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '焉以郭太后少子故，獨留京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-042-2', 'p0446', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」帝以焉郭太后偏愛，特加恩寵，獨得往來京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-068-3', 'p0446', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '郭太字林宗，范曄父名泰，故改為此「太」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a03-072-4', 'p0446', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，靈帝末，黃巾餘黨郭太等復起西河白波谷，轉寇太原，遂破河東，百姓流轉三輔，號為「白波賊」，衆十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a04-003-5', 'p0446', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '送詣京師，郭太后愛養之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0446-a04-009-6', 'p0446', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '奏使郭太后出居別宮，及遣樂安王使北詣鄴，又遣文欽令還淮南，皆謐之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-0', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '黑山賊于毒、白繞、眭固等眭，申隨反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-1', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖要擊眭固，又擊匈奴於夫羅於內黃，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-2', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-001-3', 'p0447', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-008-4', 'p0447', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '其將楊醜殺楊以應太祖，楊將眭固殺醜，將其衆，欲北合袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-014-5', 'p0447', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-017-6', 'p0447', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0447-a04-017-7', 'p0447', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a03-071-0', 'p0448', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '雷公、浮雲、飛燕、白雀、楊鳳、于毒、五鹿、李大目、白繞、畦固、苦唒之徒，九州春秋「唒」作「蝤」，音才由反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a03-101-1', 'p0448', 'houhanshu', 'a03-101', '《二十四史-後漢書-志第十一‧天文中》', '是時中常侍高梵、張防、將作大匠翟酺、尚書令高堂芝、僕射張敦、尚書尹就、郎姜述、楊鳳等，及兖州刺史鮑就、使匈奴中郎將張國、金城太守張篤、敦煌太守張朗，相與交通，漏泄，就、述棄巿，梵、防、酺、芝、敦、鳳、就、國皆抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a04-008-2', 'p0448', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0448-a04-008-3', 'p0448', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝不能討，乃遣使拜楊鳳為黑山校尉，領諸山賊，得舉孝廉計吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-0', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '五月戊申，詔曰：「乃者鳳皇、黃龍、鸞鳥比集七郡，孫柔之瑞應圖曰：「鸞鳥者，赤神之精，鳳皇之佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-1', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '九月壬辰，詔：「鳳皇、黃龍所見亭部無出二年租賦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-003-2', 'p0449', 'houhanshu', 'a03-003', '《後漢書·卷三》', '」古今注云：「黃龍見洛陽元延亭部。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-3', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '舍利之獸從西方來，戲于庭，入前殿，激水化成比目魚，嗽水作霧，化成黃龍，長八丈，出水遨戲於庭，炫燿日光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-4', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '辛卯，九真言黃龍見無功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-5', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '辛亥，濟南上言黃龍見歷城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-6', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '十二月乙未，琅邪言黃龍見諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-005-7', 'p0449', 'houhanshu', 'a03-005', '《後漢書·卷五》', '四年春正月壬午，東郡言黃龍二、麒麟一見濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-8', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '八月，濟陰言黃龍見句陽，縣名，屬濟陰郡，左傳曰「盟于句瀆之丘」是也，故城在今曹州乘氏縣北，一名穀丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-9', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '己酉，南宮嘉德署黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-007-10', 'p0449', 'houhanshu', 'a03-007', '《後漢書·卷七》', '續漢志曰：「時人欲就沲浴，見沲水濁，因戲相恐：『此中有黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-036-11', 'p0449', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '章帝時，鳳皇見百三十九，騏麟五十二，白虎二十九，黃龍三十四，神雀、白燕等史官不可勝紀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-043-12', 'p0449', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '而明年嚴鮪謀立清河王蒜，又黃龍二見沛國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-048-13', 'p0449', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '帝東巡狩，鳳皇黃龍並集，終贊頌嘉瑞，上述祖宗鴻業，凡十五章，奏上，詔貰還故郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-069-14', 'p0449', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '閒者有嘉禾、芝草、黃龍之見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-071-15', 'p0449', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-074-16', 'p0449', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-17', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中黃門孫程、王康、長樂太官丞王國、中黃門黃龍、彭愷、孟叔、李建、王成、張賢、史汎、馬國、王道、李元、楊佗、佗音駝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-18', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '其封程為浮陽侯，食邑萬戶；康為華容侯，國為酈侯，各九千戶；黃龍為湘南侯，五千戶；彭愷為西平昌侯，西平昌，諸縣，屬平原郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-078-19', 'p0449', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '黃龍、楊佗、孟叔、李建、張賢、史汎、王道、李元、李剛九人與阿母山陽君宋娥更相貨賂，求高官增邑，又誣罔中常侍曹騰、孟賁等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-082-20', 'p0449', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '舜禮壇于河畔，沈璧，禮畢，至于下昃，黃龍負卷舒圖，出水壇畔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-086-21', 'p0449', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '盟曰：「秦犯夷，輸黃龍一雙；夷犯秦，輸清酒一鍾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-092-22', 'p0449', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '太宗遵修，三階以平，黃龍以至，刑犴以錯，五是以備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-095-23', 'p0449', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '以戊、己日為大黃龍一，長五丈，居中央；又為小龍四，各長二丈五尺，於中央，皆南鄉，其閒相去五尺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-095-24', 'p0449', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '畢，化成黃龍，長八丈，出水遨戲於庭，炫燿日光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-103-25', 'p0449', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '宣帝黃龍元年，未央宮雌雞化為雄，不鳴無距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-104-26', 'p0449', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '八年二月己酉，南宮嘉德署、黃龍、千秋萬歲殿皆火。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-27', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '安帝延光三年，濟南言黃龍見歷城，琅邪言黃龍見諸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-28', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '明年正月，東郡又言黃龍二見濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-29', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '永康元年八月，巴郡言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a03-107-30', 'p0449', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '甞見堅語云：「時民以天熱，欲就池浴，見池水濁，因戲相恐『此中有黃龍』，語遂行人間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-31', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '初，漢熹平五年，黃龍見譙，光祿大夫橋玄問太史令單颺：「此何祥也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-32', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '三月，黃龍見譙，登聞之曰：「單颺之言，其驗茲乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-33', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '辛亥，太史丞許芝條魏代漢見讖緯於魏王曰：「易傳曰：『聖人受命而王，黃龍以戊己日見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-34', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '』七月四日戊寅，黃龍見，此帝王受命之符瑞最著明者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-002-35', 'p0449', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '是以黃龍數見，鳳皇仍翔，麒麟皆臻，白虎效仁，前後獻見於郊甸；甘露醴泉，奇獸神物，衆瑞並出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-36', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '景初元年春正月壬辰，山茌縣言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-37', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '又鑄黃龍、鳳皇各一，龍高四丈，鳳高三丈餘，置內殿前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-003-38', 'p0449', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '若今宮室狹小，當廣大之，猶宜隨時，不妨農務，況乃作無益之物，黃龍、鳳皇，九龍、承露盤，土山、淵池，此皆聖明之所不興也，其功參倍於殿舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-39', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '戊戌，黃龍見于鄴井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-40', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是歲，青龍、黃龍仍見頓丘、冠軍、陽夏縣界井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-41', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四年春正月，黃龍二，見寧陵縣界井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-004-42', 'p0449', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '十二月甲申，黃龍見華陰縣井中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-006-43', 'p0449', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-008-44', 'p0449', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-020-45', 'p0449', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '其年，黃龍見鄴西漳水，衮上書贊頌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-021-46', 'p0449', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '黃龍不反于涸澤，鳳皇不離其罻羅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-025-47', 'p0449', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝愈增崇宮殿，彫飾觀閣，鑿太行之石英，采穀城之文石，起景陽山於芳林之園，建昭陽殿於太極之北，鑄作黃龍鳳皇奇偉之獸，飾金墉、陵雲臺、陵霄闕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-029-48', 'p0449', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '昔夏禹文明，不怪於黃龍，周武信時，不惑於暴風，今明府道德高妙，神不懼妖，自天祐之，吉無不利，願安百祿以光休寵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-032-49', 'p0449', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '間黃龍見武陽赤水，九日乃去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-032-50', 'p0449', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孝經援神契曰『德至淵泉則黃龍見』，龍者，君之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-51', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '黃龍元年春，公卿百司皆勸權正尊號。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-52', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，夏口、武昌並言黃龍、鳳凰見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-53', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」三月，海鹽縣言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-047-54', 'p0449', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '夏四月，雨雹，雲陽言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-048-55', 'p0449', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，始新言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-048-56', 'p0449', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '六年夏四月，泉陵言黃龍見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-053-57', 'p0449', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '黃龍三年，建昌侯慮為鎮軍大將軍，屯半州，以綜為長史，外掌衆事，內授書籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-054-58', 'p0449', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '黃龍元年，封都鄉侯，後以罪徙廬陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-055-59', 'p0449', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '曹仁出濡須，戰有功，又從攻破曹休，進位裨將軍，黃龍二年卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-055-60', 'p0449', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '時山陰宿賊黃龍羅、周勃聚黨數千人，策自出討，襲身斬羅、勃首，還拜別部司馬，授兵數千，遷揚武都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-056-61', 'p0449', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃龍元年，拜車騎將軍、右護軍，領兖州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-056-62', 'p0449', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃龍元年，拜桓前將軍，領青州牧，假節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-057-63', 'p0449', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '黃龍元年，權遷都建業，徵據尚公主，拜左將軍，封雲陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-058-64', 'p0449', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃龍元年，拜上大將軍、右都護。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-059-65', 'p0449', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '黃龍元年，權稱尊號，登為皇太子，以恪為左輔，休右弼，譚為輔正，表為翼正都尉，是為四友，而謝景、范慎、刁玄、羊衜等皆為賔客，衜音道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-060-66', 'p0449', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃龍元年，遷衞將軍、左護軍、徐州牧，吳書曰：初，琮為將甚勇決，當敵臨難，奮不顧身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-060-67', 'p0449', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '黃龍三年，以南土清定，召岱還屯長沙漚口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-68', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '黃武八年夏，黃龍見夏口，於是權稱尊號，因瑞改元。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-69', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '又作黃龍大牙，常在中軍，諸軍進退，視其所向，命綜作賦曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-70', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '四靈旣布，黃龍處中，周制日月，實曰太常，桀然特立，六軍所望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-71', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '軍欲轉向，黃龍先移，金鼓不鳴，寂然變施，闇謨若神，可謂祕奇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-062-72', 'p0449', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '在昔周室，赤烏銜書，今也大吳，黃龍吐符。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a04-064-73', 'p0449', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '初，權黃龍元年遷都建業，二年築東興隄遏湖水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-003-74', 'p0449', 'jinshu', 'a05-003', '《晉書·卷三》', '是歲，鳳皇六、青龍十、黃龍九、麒麟各一見于郡國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-003-75', 'p0449', 'jinshu', 'a05-003', '《晉書·卷三》', '戊申，青龍、黃龍各一見于魯國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-010-76', 'p0449', 'jinshu', 'a05-010', '《晉書·卷十》', '慕容寶將慕容詳僭即皇帝位于中山，寶奔黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-010-77', 'p0449', 'jinshu', 'a05-010', '《晉書·卷十》', '丙戌，慕容盛僭即皇帝位於黃龍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0449-a05-011-78', 'p0449', 'jinshu', 'a05-011', '《晉書·卷十一》', '軒轅，黃帝之神，黃龍之體也；后妃之主，士職也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-004-0', 'p0450', 'houhanshu', 'a03-004', '《後漢書·卷四》', '二月，大將軍竇憲遣左校尉耿夔出居延塞，居延，縣，屬張掖郡，居延澤在東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-004-1', 'p0450', 'houhanshu', 'a03-004', '《後漢書·卷四》', '遣大將軍左校尉耿夔授璽綬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-005-2', 'p0450', 'houhanshu', 'a03-005', '《後漢書·卷五》', '秋七月丁酉，初復右校令、左校丞官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-008-full-3', 'p0450', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-008-4', 'p0450', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-019-5', 'p0450', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '三年，憲復出河西，以夔為大將軍左校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-026-6', 'p0450', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '政任威刑，為受罰者所奏，坐論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-026-7', 'p0450', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '左校，署名，屬將作也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-031-8', 'p0450', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '及謙至，部案得其臧，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-038-9', 'p0450', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '遷，故車騎將軍單超之弟，中官相黨，遂共誹章誣緄，坐與司隷校尉李膺、大司農劉祐俱輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-043-10', 'p0450', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '左校，署名，屬將作，掌左工徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-043-11', 'p0450', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '由是內官咸共恚疾，謗讟煩興，讒隙仍作，極其刑讁，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-051-12', 'p0450', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '初仕郡，未知名，河南尹龐奮見而竒之，舉為孝廉，拜左校令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-051-13', 'p0450', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '臣伏見故左校令河南龐參，勇謀不測，卓爾竒偉，高才武略，有魏尚之風。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-054-14', 'p0450', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '今盛夏土王，而攻山採石，其大匠左校別部將作合數十處，續漢志將作大匠，秩二千石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-054-15', 'p0450', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」而秉竟坐輸作左校，以乆旱赦出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-058-16', 'p0450', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '書奏，防流涕訴帝，詡坐論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-063-17', 'p0450', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '爕以謗毀宗室，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-064-18', 'p0450', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '行賂於侯覽，得減死罪一等，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-19', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '官屬欲賦斂請謝，規誓而不聽，遂以餘寇不絕，坐繫廷尉，論輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-20', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '漢官儀曰，左校署屬將作大匠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-21', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '又臣昔論輸左校時，太學生張鳳等上書訟臣，是為黨人所附也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-065-22', 'p0450', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '郭閎歸罪於熲，熲坐徵下獄，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-066-23', 'p0450', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '又山陽太守翟超，沒入中常侍侯覽財產，東海相黃浮，誅殺下邳令徐宣，超、浮並坐髡鉗，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-24', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '膺表欲桉其罪，元羣行賂宦豎，膺反坐輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-25', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竊見左校弛刑徒前廷尉馮緄、大司農劉祐、河南尹李膺等，執法不撓，誅舉邪臣，肆之以法，肆，陳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-26', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '桓帝大怒，論祐輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-067-27', 'p0450', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '騰使大將軍梁兾為書請之，衍不荅，鼎竟坐輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-071-28', 'p0450', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '儁乃羸服閒行，輕齎數百金到京師，賂主章吏，遂得刊定州奏，故端得輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-071-29', 'p0450', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-074-30', 'p0450', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-074-31', 'p0450', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-078-32', 'p0450', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '節等怨猛不已，使熲以它事奏猛，抵罪輸左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-089-33', 'p0450', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '由是始置度遼營，以中郎將吳棠行度遼將軍事，副校尉來苗、左校尉閻章、右校尉張國將黎陽虎牙營士屯五原曼柏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-092-34', 'p0450', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '詔書報，恂、誠各以二月奉贖罪，整適作左校二月。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-093-35', 'p0450', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '臣初決罪雒陽詔獄，生出牢戶，顧念元初中故尚書郎張俊，坐漏泄事，當伏重刑，已出穀門，復聽讀鞠，詔書馳救，減罪一等，輸作左校。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a03-117-36', 'p0450', 'houhanshu', 'a03-117', '《二十四史-後漢書-志第二十七‧百官四》', '」案紀，光武改青巾左校尉為越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-006-37', 'p0450', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，皆屠其屯壁，奔走得脫，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-008-38', 'p0450', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0450-a04-008-39', 'p0450', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張璠漢紀云：又有左校、郭大賢、左髭丈八三部也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a03-071-0', 'p0451', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '自黃巾賊後，復有黑山、黃龍、白波、左校、郭大賢、于氐根、青牛角、張白騎、劉石、左髭丈八、平漢、大計、司隷、掾哉、九州春秋「大計」作「大洪」，「掾哉」作「緣城」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0451-a03-074-1', 'p0451', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遂尋山北行，進擊諸賊左髭丈八等，皆斬之，又擊劉石、青牛角、黃龍、左校、郭大賢、李大目、于氐根等，復斬數萬級，皆屠其屯壁。');
